import { AccessError, isAccessError } from "thesidedoor-core/access";
import {
  requestIdentity,
  sharedAccess,
  accessFailure,
} from "@/lib/auth/access";
import {
  withProfileFiles,
  withProfileActivity,
} from "@/lib/auth/profile-capability";
import { getPaper } from "@/lib/library/papers";
import {
  readChat,
  appendMessage,
  appendUserMessage,
