  if (!getPaper(topic, slug)) {
    return NextResponse.json({ error: "Unknown paper." }, { status: 404 });
  }
  const body = createSchema.safeParse(await readBoundedJsonOrNull(request));
  if (!body.success) {
    return NextResponse.json(
      { error: "Invalid conversations." },
      { status: 400 },
    );
  }
  try {
    if (readConnection(topic, slug))
      return NextResponse.json(
        {
          error:
            "Create sharing links on the original owner's instance. Use an independent fork to share your own copy.",
        },
        { status: 403 },
      );
    if (
      body.data.mode === "collaborate" &&
      !body.data.acknowledgePublicAnnotations
    )
      return NextResponse.json(
        {
          error:
            "Confirm that collaborative annotations will also appear through existing reading links.",
        },
        { status: 400 },
      );
    const snapshot =
      body.data.includeArtifacts || body.data.mode === "collaborate"
        ? await snapshotArtifacts(topic, slug)
        : undefined;
    const artifacts = body.data.includeArtifacts ? snapshot : undefined;
    const share = withProfileFiles(sharedAccess().identity, capability, () =>
      createShare(
        topic,
        slug,
        capability,
        body.data.chatIds,
        body.data.mode,
        artifacts,
      ),
    );
    return NextResponse.json(
      { share: toPublicSummary(share) },
      { status: 201 },
    );
  } catch (error) {
    if (error instanceof ShareError) {
      return NextResponse.json({ error: error.message }, { status: 400 });
    }
    return sharingFailure(error);
  }
}

import { z } from "zod";
import { ANIMAL_AVATARS } from "@/lib/auth/avatars";
import { createProfile, toPublicProfile } from "@/lib/auth/users";
import {
  ACCESS_COOKIE,
  accessFailure,
  accessHandler,
  requestIdentity,
  sharedAccess,
} from "@/lib/auth/access";
import { readBoundedJsonOrNull } from "@/lib/bounded-request";
import { erasureWorkerStatus } from "@/lib/auth/platform/erasure-worker";

export async function GET(): Promise<Response> {
  try {
    const identity = await requestIdentity();
    if (!identity)
      return Response.json(
        {
          owner: false,
          profiles: [],
          instancePassword: true,
          gated: true,
        },
        { headers: { "Cache-Control": "private, no-store" } },
      );
    const state = await sharedAccess().identity.read();
    sharedAccess().access.sessionFromState(state.access, identity.token);
    const owner = sharedAccess().access.householdOwnerFromState(
      state.access,
      identity.token,
    );
    const worker = owner ? erasureWorkerStatus() : undefined;
    const visible =
      owner || state.access.mode === "household"
        ? state.profiles
        : state.profiles.filter(
            (profile) => profile.username === identity.profile?.username,
          );
    return Response.json(
      {
        owner,
        ...(worker
          ? {
              erasures: {
                workerRunning: worker.running,
                profiles: state.erasures.map((marker) => ({
                  ...marker,
                  status:
                    worker.diagnostics.find(
                      (entry) =>
                        entry.username === marker.username &&
                        entry.generation === marker.generation,
                    )?.status ?? "pending",
                })),
              },
            }
          : {}),
        profiles: visible.map((profile) =>
          toPublicProfile(
            profile,
            owner &&
              state.access.principals.some(
                (principal) =>
                  principal.role === "owner" &&
                  state.bindings[principal.id] === profile.username,
              ),
          ),
        ),
        instancePassword: true,
      },
      { headers: { "Cache-Control": "private, no-store" } },
    );
  } catch (error) {
    return accessFailure(error);
  }
}

const createSchema = z.object({
  displayName: z.string().min(2).max(40),
  avatarSlug: z
    .enum(ANIMAL_AVATARS.map((a) => a.slug) as [string, ...string[]])
    .optional(),
  password: z.string().max(200).optional(),
});

export async function POST(request: Request): Promise<Response> {
  const handler = accessHandler();
  const headers = new Headers(request.headers);
  const check = await handler(
    new Request(request.url, { method: "POST", headers, body: "{}" }),
    "check-origin",
  );
  if (!check.ok) return check;
  const input = createSchema.safeParse(await readBoundedJsonOrNull(request));
  if (!input.success)
    return Response.json({ error: "Invalid profile." }, { status: 400 });
  let admission: Response | undefined;
  let token: string | undefined;
  try {
    let identity = await requestIdentity();
    if (!identity) {
      admission = await handler(
        new Request(request.url, {
          method: "POST",
          headers,
          body: JSON.stringify({ password: input.data.password ?? "" }),
        }),
        "household",
      );
      if (!admission.ok) return admission;
      const cookie = admission.headers.get("set-cookie")?.split(";")[0];
      if (!cookie?.startsWith(ACCESS_COOKIE + "="))
        throw new Error("Access handler did not issue a session cookie");
      token = decodeURIComponent(cookie.slice(ACCESS_COOKIE.length + 1));
      identity = await requestIdentity(token);
    }
    if (!identity)
      return Response.json({ error: "Not signed in." }, { status: 401 });
    const profile = await createProfile(
      input.data.displayName,
      input.data.avatarSlug,
      identity.token,
    );
    const response = Response.json(
      { profile: toPublicProfile(profile) },
      { status: 201 },
    );
    const cookie = admission?.headers.get("set-cookie");
    if (cookie) response.headers.set("set-cookie", cookie);
    return response;
  } catch (error) {
    if (token) await sharedAccess().access.logout(token);
    return accessFailure(error);
  }
}

import { z } from "zod";
import { accessHandler, requestIdentity } from "@/lib/auth/access";
import { toPublicProfile } from "@/lib/auth/users";
import { readBoundedJsonOrNull } from "@/lib/bounded-request";

function actionRequest(
  request: Request,
  body: unknown,
  cookie?: string,
): Request {
  const headers = new Headers(request.headers);
  if (request.method !== "POST")
    headers.set("content-type", "application/json");
  if (cookie) headers.set("cookie", cookie);
  return new Request(request.url, {
    method: "POST",
    headers,
    body: JSON.stringify(body),
    signal: request.signal,
  });
}

export async function GET(): Promise<Response> {
  const identity = await requestIdentity();
  return Response.json(
    {
      profile: identity?.profile
        ? toPublicProfile(identity.profile, identity.isAdmin)
        : null,
    },
    { headers: { "Cache-Control": "no-store" } },
  );
}

export async function POST(request: Request): Promise<Response> {
  const input = z
    .object({ username: z.string().min(2).max(31) })
    .strict()
    .safeParse(await readBoundedJsonOrNull(request));
  if (!input.success)
    return Response.json({ error: "Invalid login." }, { status: 400 });
  const handler = accessHandler();
  const currentIdentity = await requestIdentity();
  if (!currentIdentity)
    return Response.json({ error: "Unauthorized." }, { status: 401 });
  if (currentIdentity?.principal) {
    const authorized = await handler(
      actionRequest(request, {}),
      "authorize-session",
    );
    if (!authorized.ok) return authorized;
    if (currentIdentity.profile?.username !== input.data.username)
      return Response.json({ error: "Forbidden." }, { status: 403 });
    return Response.json(
      {
        profile: toPublicProfile(
          currentIdentity.profile,
          currentIdentity.isAdmin,
        ),
      },
      { headers: { "Cache-Control": "no-store" } },
    );
  }
  const selected = await handler(
    actionRequest(request, { id: input.data.username }),
    "select-profile",
  );
  if (!selected.ok) return selected;
  const identity = await requestIdentity();
  return Response.json(
    {
      profile: identity?.profile
        ? toPublicProfile(identity.profile, identity.isAdmin)
        : null,
    },
    { headers: selected.headers },
  );
}

export async function DELETE(request: Request): Promise<Response> {
  return accessHandler()(actionRequest(request, {}), "logout");
}

import { NextResponse, type NextRequest } from "next/server";
import { z } from "zod";
import { readBoundedJsonOrNull } from "@/lib/bounded-request";
import { requestIdentity, accessFailure } from "@/lib/auth/access";
import { isAccessError } from "thesidedoor-core/access";
import {
  importCatalogItem,
  listCatalogItems,
  ZoteroCatalogItemNotFoundError,
  ZoteroImportUnavailableError,
} from "@/lib/capture/zotero-service";
import { ZoteroError, ZoteroPdfTooLargeError } from "@/lib/capture/zotero";
import { ZoteroBusyError } from "@/lib/capture/zotero-lock";

export const dynamic = "force-dynamic";

const querySchema = z.object({
  q: z.string().max(200).default(""),
  page: z.coerce.number().int().min(1).max(10_000).default(1),
  limit: z.coerce.number().int().min(1).max(50).default(20),
});

export async function GET(request: NextRequest): Promise<Response> {
  const admission = await requestIdentity();
  const profile = admission?.profile;
  if (!profile || !admission.capability) {
    return NextResponse.json({ error: "Not signed in." }, { status: 401 });
  }
  if (!profile.zotero) {
    return NextResponse.json(
      { error: "Zotero not connected." },
      { status: 400 },
    );
  }
  const query = querySchema.safeParse({
    q: request.nextUrl.searchParams.get("q") ?? undefined,
    page: request.nextUrl.searchParams.get("page") ?? undefined,
    limit: request.nextUrl.searchParams.get("limit") ?? undefined,
  });
  if (!query.success) {
    return NextResponse.json(
      { error: "Invalid Zotero catalog query." },
      { status: 400 },
    );
  }
  try {
    return NextResponse.json(
      await listCatalogItems(
        admission.capability,
        query.data.q,
        query.data.page,
        query.data.limit,
      ),
      { headers: { "Cache-Control": "no-store" } },
    );
  } catch (error) {
    return accessFailure(error);
  }
}

const importSchema = z.object({
  itemKey: z.string().regex(/^[A-Za-z0-9]{1,64}$/),
});

export async function POST(request: NextRequest): Promise<Response> {
  const admission = await requestIdentity();
  if (!admission?.capability) {
    return NextResponse.json({ error: "Not signed in." }, { status: 401 });
  }
  const body = importSchema.safeParse(await readBoundedJsonOrNull(request));
  if (!body.success) {
    return NextResponse.json(
      { error: "Invalid Zotero item." },
      { status: 400 },
    );
  }
  try {
    const result = await importCatalogItem(
      admission.capability,
      body.data.itemKey,
    );
    return NextResponse.json(result, { status: result.created ? 201 : 200 });
  } catch (error) {
    if (isAccessError(error)) return accessFailure(error);
    if (error instanceof ZoteroCatalogItemNotFoundError) {
      return NextResponse.json({ error: error.message }, { status: 404 });
    }
    if (error instanceof ZoteroBusyError) {
      return NextResponse.json({ error: error.message }, { status: 409 });
    }
    if (error instanceof ZoteroPdfTooLargeError) {
      return NextResponse.json({ error: error.message }, { status: 413 });
    }
    if (error instanceof ZoteroImportUnavailableError) {
      return NextResponse.json({ error: error.message }, { status: 422 });
    }
    if (error instanceof ZoteroError) {
      return NextResponse.json({ error: error.message }, { status: 502 });
    }
    throw error;
  }
}

import { NextResponse, type NextRequest } from "next/server";
import { z } from "zod";
import { readBoundedJsonOrNull } from "@/lib/bounded-request";
import { requestIdentity } from "@/lib/auth/access";
import {
  recordFailure,
  recordSuccess,
  retryAfterMs,
} from "@/lib/auth/rate-limit";
import {
  verifyKey,
  syncProfile,
  isSyncing,
  lastSyncResult,
  listLibraryTargets,
  listCollections,
} from "@/lib/capture/zotero";
import {
  disconnectZotero,
  saveZoteroConfig,
  ZoteroConfigConflictError,
} from "@/lib/capture/zotero-service";
import { ZoteroBusyError } from "@/lib/capture/zotero-lock";
import type {
  Profile,
  ZoteroLibraryTarget,
  ZoteroProfileConfig,
} from "@/lib/auth/users";

/**
 * Per-profile Zotero connection: connect with an API key (verified against
 * the Zotero API, which also discovers the user ID), disconnect, and trigger
 * a sync. The key itself is never returned to the browser.
 */

export const dynamic = "force-dynamic";

function configuredTarget(config: ZoteroProfileConfig): ZoteroLibraryTarget {
  return (
    config.target ?? {
      type: "user",
      id: config.userId,
      name: "My Library",
    }
  );
}

function snapshot(profile: Profile) {
  return {
    connected: Boolean(profile.zotero),
    userId: profile.zotero?.userId ?? null,
    target: profile.zotero ? configuredTarget(profile.zotero) : null,
    collectionKeys: profile.zotero?.collectionKeys ?? [],
    syncing: isSyncing(profile.username),
    lastResult: lastSyncResult(profile.username),
  };
}

const optionsQuerySchema = z.object({
  options: z.literal("1").optional(),
  libraryType: z.enum(["user", "group"]).optional(),
  libraryId: z.string().regex(/^\d+$/).optional(),
});

export async function GET(request?: NextRequest): Promise<NextResponse> {
  const identity = await requestIdentity();
  const me = identity?.profile;
  if (!identity?.capability || !me)
    return NextResponse.json({ error: "Not signed in." }, { status: 401 });
  const query = optionsQuerySchema.safeParse({
    options: request?.nextUrl.searchParams.get("options") ?? undefined,
    libraryType: request?.nextUrl.searchParams.get("libraryType") ?? undefined,
    libraryId: request?.nextUrl.searchParams.get("libraryId") ?? undefined,
  });
  if (!query.success) {
    return NextResponse.json(
      { error: "Invalid Zotero options request." },
      { status: 400 },
    );
  }
  if (query.data.options === "1") {
    if (!me.zotero) {
      return NextResponse.json(
        { error: "Zotero not connected." },
        { status: 400 },
      );
    }
    const verified = await verifyKey(me.zotero.apiKey);
    if (!verified) {
      return NextResponse.json(
        { error: "Zotero rejected this key. Reconnect it to continue." },
        { status: 422 },
      );
    }
    const personalReadable = verified.personalLibrary;
    const libraries = await listLibraryTargets(me.zotero, personalReadable);
    if (libraries.length === 0) {
      return NextResponse.json(
        { error: "This key cannot read any Zotero library metadata." },
        { status: 422 },
      );
    }
    let target = configuredTarget(me.zotero);
    let warning: string | null = null;
    if (query.data.libraryType || query.data.libraryId) {
      if (!query.data.libraryType || !query.data.libraryId) {
        return NextResponse.json(
          { error: "Choose a complete Zotero library target." },
          { status: 400 },
        );
      }
      const requested = libraries.find(
        (library) =>
          library.type === query.data.libraryType &&
          library.id === query.data.libraryId,
      );
      if (!requested) {
        return NextResponse.json(
          { error: "That Zotero library is not accessible with this key." },
          { status: 422 },
        );
      }
      target = requested;
    } else if (
      !libraries.some(
        (library) => library.type === target.type && library.id === target.id,
      )
    ) {
      target = libraries[0];
      warning =
        "The configured Zotero group is no longer accessible. Choose another library.";
    }
    const collections = await listCollections({
      ...me.zotero,
      target,
    });
    return NextResponse.json({
      ...snapshot(me),
      libraries: libraries.map((library) => ({
        ...library,
        canImportFiles:
          library.type === "group" ? null : verified.personalFiles,
      })),
      collections,
      previewTarget: target,
      warning,
    });
  }
  return NextResponse.json(snapshot(me));
}

const schema = z.object({ apiKey: z.string().min(8).max(128) });

export async function PUT(request: NextRequest): Promise<NextResponse> {
  const identity = await requestIdentity();
  const me = identity?.profile;
  if (!identity?.capability || !me)
    return NextResponse.json({ error: "Not signed in." }, { status: 401 });
  if (isSyncing(me.username)) {
    return NextResponse.json(
      { error: "Wait for the current Zotero sync to finish." },
      { status: 409 },
    );
  }
  const limitKey = `zotero-key:${me.username}`;
  if (retryAfterMs(limitKey) > 0) {
    return NextResponse.json(
      { error: "Too many attempts. Try again shortly." },
      { status: 429 },
    );
  }
  const body = schema.safeParse(await readBoundedJsonOrNull(request));
  if (!body.success) {
    return NextResponse.json({ error: "Invalid API key." }, { status: 400 });
  }
  const verified = await verifyKey(body.data.apiKey.trim());
  if (!verified) {
    recordFailure(limitKey);
    return NextResponse.json(
      { error: "Zotero rejected this key." },
      { status: 422 },
    );
  }
  const personalReadable = verified.personalLibrary;
  const config = {
    apiKey: body.data.apiKey.trim(),
    userId: verified.userId,
  };
  const libraries = await listLibraryTargets(config, personalReadable);
  if (libraries.length === 0) {
    recordFailure(limitKey);
    return NextResponse.json(
      {
        error: "This key cannot read a personal or group Zotero library.",
      },
      { status: 422 },
    );
  }
  recordSuccess(limitKey);
  const target = personalReadable
    ? libraries.find((library) => library.type === "user")!
    : libraries[0];
  try {
    const profile = await saveZoteroConfig(
      identity.token,
      identity.capability,
      {
        ...config,
        target,
        collectionKeys: [],
      },
      me.zotero,
    );
    return NextResponse.json(snapshot(profile));
  } catch (error) {
    if (
      error instanceof ZoteroBusyError ||
      error instanceof ZoteroConfigConflictError
    ) {
      return NextResponse.json({ error: error.message }, { status: 409 });
    }
    throw error;
  }
}

export async function DELETE(): Promise<NextResponse> {
  const identity = await requestIdentity();
  const me = identity?.profile;
  if (!identity?.capability || !me)
    return NextResponse.json({ error: "Not signed in." }, { status: 401 });
  if (isSyncing(me.username)) {
    return NextResponse.json(
      { error: "Wait for the current Zotero sync to finish." },
      { status: 409 },
    );
  }
  try {
    await disconnectZotero(identity.token, identity.capability);
    const disconnected = { ...me };
    delete disconnected.zotero;
    return NextResponse.json(snapshot(disconnected));
  } catch (error) {
    if (
      error instanceof ZoteroBusyError ||
      error instanceof ZoteroConfigConflictError
    ) {
      return NextResponse.json({ error: error.message }, { status: 409 });
    }
    throw error;
  }
}

const targetSchema = z.object({
  type: z.enum(["user", "group"]),
  id: z.string().regex(/^\d+$/),
});
const updateSchema = z.object({
  target: targetSchema,
  collectionKeys: z.array(z.string().min(1).max(64)).max(1_000).default([]),
});

export async function PATCH(request: NextRequest): Promise<NextResponse> {
  const identity = await requestIdentity();
  const me = identity?.profile;
  if (!identity?.capability || !me)
    return NextResponse.json({ error: "Not signed in." }, { status: 401 });
  if (!me.zotero) {
    return NextResponse.json(
      { error: "Zotero not connected." },
      { status: 400 },
    );
  }
  if (isSyncing(me.username)) {
    return NextResponse.json(
      { error: "Wait for the current Zotero sync to finish." },
      { status: 409 },
    );
  }
  const body = updateSchema.safeParse(await readBoundedJsonOrNull(request));
  if (!body.success) {
    return NextResponse.json(
      { error: "Invalid Zotero sync source." },
      { status: 400 },
    );
  }
  const verified = await verifyKey(me.zotero.apiKey);
  if (!verified) {
    return NextResponse.json(
      { error: "Zotero rejected this key. Reconnect it to continue." },
      { status: 422 },
    );
  }
  const libraries = await listLibraryTargets(
    me.zotero,
    verified.personalLibrary,
  );
  const target = libraries.find(
    (library) =>
      library.type === body.data.target.type &&
      library.id === body.data.target.id,
  );
  if (!target) {
    return NextResponse.json(
      { error: "That Zotero library is not accessible with this key." },
      { status: 422 },
    );
  }
  const proposed = { ...me.zotero, target };
  const collections = await listCollections(proposed);
  const available = new Set(collections.map((collection) => collection.key));
  const collectionKeys = [...new Set(body.data.collectionKeys)].sort();
  if (collectionKeys.some((key) => !available.has(key))) {
    return NextResponse.json(
      { error: "One or more Zotero collections are not accessible." },
      { status: 422 },
    );
  }
  try {
    const profile = await saveZoteroConfig(
      identity.token,
      identity.capability,
      {
        ...proposed,
        collectionKeys,
      },
      me.zotero,
    );
    return NextResponse.json(snapshot(profile));
  } catch (error) {
    if (
      error instanceof ZoteroBusyError ||
      error instanceof ZoteroConfigConflictError
    ) {
      return NextResponse.json({ error: error.message }, { status: 409 });
    }
    throw error;
  }
}

/** Kick off a sync in the background; poll GET for completion. */
const lastManualSync = new Map<string, number>();
const MANUAL_SYNC_COOLDOWN_MS = 60_000;

export async function POST(): Promise<NextResponse> {
  const identity = await requestIdentity();
  const me = identity?.profile;
  if (!identity?.capability || !me)
    return NextResponse.json({ error: "Not signed in." }, { status: 401 });
  if (!me.zotero) {
    return NextResponse.json(
      { error: "Zotero not connected." },
      { status: 400 },
    );
  }
  const last = lastManualSync.get(me.username) ?? 0;
  if (!isSyncing(me.username) && Date.now() - last < MANUAL_SYNC_COOLDOWN_MS) {
    return NextResponse.json(
      { error: "Synced moments ago. Try again in a minute." },
      { status: 429 },
    );
  }
  lastManualSync.set(me.username, Date.now());
  void syncProfile(me.username, identity.capability).catch((error) =>
    console.error(`zotero sync now failed for ${me.username}:`, error),
  );
  return NextResponse.json({ ...snapshot(me), syncing: true });
}

import { z } from "zod";
import { getShare, withShareFiles } from "@/lib/library/shares";
import { readPublishedArtifacts } from "@/lib/sharing/artifacts/publication";
import { validatePortableCanvas } from "@/lib/sharing/artifacts/canvas";
import { canvasMediaType, portableAssetNameSchema } from "@/lib/canvas/media";
import { withSharingResponse } from "@/lib/sharing/storage";
import { sharingFailure, SharingError } from "@/lib/sharing/schema";

export const dynamic = "force-dynamic";
interface Params {
  params: Promise<{ topic: string; slug: string; shareId: string }>;
}
const querySchema = z.union([
  z.object({}).strict(),
  z.object({ asset: portableAssetNameSchema }).strict(),
  z.object({ pdf: z.literal("1") }).strict(),
]);
const headers = {
  "cache-control": "private, no-store",
  "referrer-policy": "no-referrer",
  "x-robots-tag": "noindex, nofollow",
  "x-content-type-options": "nosniff",
  "content-security-policy":
    "default-src 'none'; sandbox; frame-ancestors 'none'",
};

export async function GET(request: Request, { params }: Params) {
  try {
    const { topic, slug, shareId } = await params;
    const share = getShare(topic, slug, shareId);
    if (!share?.includeArtifacts)
      throw new SharingError("Unknown shared snapshot.", 404);
    const query = querySchema.parse(
      Object.fromEntries(new URL(request.url).searchParams),
    );
    return await withSharingResponse(async () => {
      const snapshot = readPublishedArtifacts(share);
      return withShareFiles(share, () => {
        if ("pdf" in query) {
          if (!snapshot.exercisePdf)
            throw new SharingError("No exercise PDF was shared.", 404);
          return new Response(Buffer.from(snapshot.exercisePdf.pdf, "base64"), {
            headers: {
              ...headers,
              "content-type": "application/pdf",
              etag: snapshot.exercisePdf.etag,
            },
          });
        }
        if ("asset" in query) {
          const asset = snapshot.assets[query.asset];
          if (!asset) throw new SharingError("Unknown shared media.", 404);
          return new Response(Buffer.from(asset, "base64"), {
            headers: {
              ...headers,
              "content-type": canvasMediaType(query.asset),
            },
          });
        }
        const canvas = validatePortableCanvas(snapshot.canvas, snapshot.assets);
        if (canvas)
          for (const record of Object.values(canvas.store)) {
            if (
              record.typeName === "asset" &&
              record.type !== "bookmark" &&
              record.props.src
            )
              record.props.src = `/api/v1/shares/${topic}/${slug}/${shareId}/artifacts?asset=${encodeURIComponent(record.props.src.slice(15))}`;
          }
        return Response.json(
          {
            document: canvas,
            exercises: snapshot.exercises,
            hasPdf: snapshot.exercisePdf !== null,
          },
          { headers },
        );
      });
    });
  } catch (error) {
    return sharingFailure(error);
  }
}

import { z } from "zod";
import { consumeRequestLimit, publicRequestLimit } from "@/lib/auth/rate-limit";
import { clientIp, crossSiteMutation } from "@/lib/auth/request-security";
import { readBoundedJson, RequestBodyError } from "@/lib/bounded-request";
import { exportBundle } from "@/lib/sharing/bundle";
import {
  reconstructAnnotations,
  reconstructComment,
  MAX_COLLABORATIVE_PDF_BYTES,
} from "@/lib/sharing/sandbox";
import {
  authenticateParticipant,
  requestParticipant,
  publicParticipant,
  requireCollaboration,
  withCollaboration,
  withSharingResponse,
  leaveCollaboration,
} from "@/lib/sharing/storage";
import {
  collaborationThreads,
  publishThread,
  unpublishThread,
} from "@/lib/sharing/threads";
import {
  assetsSchema,
  base64Schema,
  conversationSchema,
  labelSchema,
  MAX_CHAT_BYTES,
  revisionSchema,
  idSchema,
  secretSchema,
  SharingError,
  sharingFailure,
} from "@/lib/sharing/schema";
import {
  getShare,
  withShareFiles,
  type PaperShare,
} from "@/lib/library/shares";
import {
  PdfBusyError,
  PdfConflictError,
  readVersionedPdf,
  readVersionedPdfFile,
  rewritePdf,
} from "@/lib/library/pdf/file";
import { pdfCommentActionSchema } from "@/lib/library/pdf/comments";
import {
  artifactOperations,
  exchangeArtifact,
} from "@/lib/sharing/artifacts/exchange";
import { artifactVersions } from "@/lib/sharing/artifacts/snapshot";
import { CanvasError } from "@/lib/canvas/errors";
import { ExerciseError } from "@/lib/library/exercises/schema";
import { recoverSourceExercises } from "@/lib/sharing/artifacts/source";
import { FilesystemBusyError } from "@/lib/filesystem-lock";

const operationSchema = z.discriminatedUnion("action", [
  ...artifactOperations,
  z.object({ action: z.literal("bundle") }).strict(),
  z.object({ action: z.literal("request"), name: labelSchema }).strict(),
  z.object({ action: z.literal("status") }).strict(),
  z.object({ action: z.literal("threads") }).strict(),
  z
    .object({
      action: z.literal("version"),
      kind: z.enum(["paper", "exercises"]).default("paper"),
    })
    .strict(),
  z.object({ action: z.literal("changes") }).strict(),
  z
    .object({
      action: z.literal("pdf"),
      kind: z.enum(["paper", "exercises"]).default("paper"),
    })
    .strict(),
  z.object({ action: z.literal("leave") }).strict(),
  z.object({ action: z.literal("unpublish"), id: idSchema }).strict(),
  z.object({ action: z.literal("read") }).strict(),
  z
    .object({
      action: z.literal("save-pdf"),
      etag: revisionSchema,
      pdf: base64Schema,
      kind: z.enum(["paper", "exercises"]).default("paper"),
    })
    .strict(),
  z
    .object({
      action: z.literal("comment"),
      etag: revisionSchema,
      comment: pdfCommentActionSchema,
    })
    .strict(),
  z
    .object({
      action: z.literal("publish"),
      chat: conversationSchema,
      assets: assetsSchema,
      expected: revisionSchema.nullable(),
    })
    .strict(),
]);
const headers = {
  "cache-control": "private, no-store",
  "referrer-policy": "no-referrer",
  "x-robots-tag": "noindex, nofollow",
  "x-content-type-options": "nosniff",
  "content-security-policy":
    "default-src 'none'; frame-ancestors 'none'; base-uri 'none'",
};
type Params = {
  params: Promise<{ topic: string; slug: string; shareId: string }>;
};

function sharedResponse(
  share: PaperShare,
  token: string,
  value: unknown,
  approved = true,
): Response {
  return withShareFiles(share, () => {
    if (token) authenticateParticipant(share, token, approved);
    return Response.json(value, { headers });
  });
}

async function handleExchange(request: Request, { params }: Params) {
  try {
    const { topic, slug, shareId } = await params;
    const share = getShare(topic, slug, shareId);
    if (!share || share.mode === "view")
      throw new SharingError("Unknown transferable share.", 404);
    const token =
      request.headers.get("authorization")?.replace(/^Bearer /, "") ?? "";
    // Authenticate before reading large bodies. The sole unauthenticated operation
    // is a bounded fork snapshot request, never an editing operation.
    if (!token) {
      if (request.headers.get("x-sharing-operation") !== "bundle")
        throw new SharingError("A collaboration credential is required.", 401);
      const body = z
        .object({ action: z.literal("bundle") })
        .strict()
        .safeParse(
          await readBoundedJson(request, 1024, AbortSignal.timeout(2000)),
        );
      if (!body.success)
        throw new SharingError("A collaboration credential is required.", 401);
      return withSharingResponse(async () =>
        sharedResponse(share, "", await exportBundle(share)),
      );
    }
    if (!secretSchema.safeParse(token).success)
      throw new SharingError("Invalid collaboration credential.", 401);
    requireCollaboration(topic, slug, shareId);
    const action = request.headers.get("x-sharing-operation");
    if (action !== "request") {
      authenticateParticipant(
        share,
        token,
        action !== "status" && action !== "leave" && action !== "threads",
      );
    }
    const limit =
      action === "save-pdf"
        ? Math.ceil((MAX_COLLABORATIVE_PDF_BYTES * 4) / 3) + 64 * 1024
        : action === "publish"
          ? MAX_CHAT_BYTES
          : action === "save-canvas"
            ? 4 * 1024 * 1024 + 2048
            : action === "upload-canvas-asset"
              ? 12 * 1024 * 1024
              : action === "create-exercise"
                ? 600 * 1024
                : 2048;
    const parsed = operationSchema.safeParse(
      await readBoundedJson(
        request,
        limit,
        AbortSignal.timeout(
          [
            "save-pdf",
            "publish",
            "save-canvas",
            "upload-canvas-asset",
            "create-exercise",
          ].includes(action ?? "")
            ? 30_000
            : 2000,
        ),
      ),
    );
    if (!parsed.success || parsed.data.action !== action || action === "bundle")
      throw new SharingError("Invalid sharing operation.");
    const body = parsed.data;
    return await withCollaboration(share, async () => {
      if (body.action === "request") {
        const participant = requestParticipant(share, token, body.name);
        return sharedResponse(
          share,
          token,
          publicParticipant(participant),
          false,
        );
      }
      const participant = authenticateParticipant(
        share,
        token,
        body.action !== "status" &&
          body.action !== "leave" &&
          body.action !== "threads",
      );
      if (
        artifactOperations.some(
          (operation) => operation.shape.action.value === body.action,
        )
      )
        return sharedResponse(
          share,
          token,
          await exchangeArtifact(share, token, participant, body),
        );
      if (body.action === "status")
        return sharedResponse(
          share,
          token,
          publicParticipant(participant),
          false,
        );
      if (body.action === "threads")
        return withSharingResponse(async () =>
          sharedResponse(
            share,
            token,
            {
              participant: publicParticipant(participant),
              threads:
                participant.status === "approved"
                  ? collaborationThreads(share)
                  : [],
            },
            false,
          ),
        );
      if (body.action === "version" || body.action === "changes")
        return withSharingResponse(async () => {
          if (body.action === "changes")
            await recoverSourceExercises(topic, slug, (operation) =>
              withShareFiles(share, () => {
                authenticateParticipant(share, token);
                operation();
              }),
            );
          const pdf = await readVersionedPdfFile(
            topic,
            slug,
            body.action === "version" ? body.kind : "paper",
          );
          if (!pdf) throw new SharingError("Unknown paper.", 404);
          return sharedResponse(share, token, {
            etag: pdf.etag,
            ...(body.action === "changes"
              ? {
                  threads: collaborationThreads(share).map(
                    ({ id, actorId, revision }) => ({ id, actorId, revision }),
                  ),
                  artifacts: await artifactVersions(topic, slug),
                }
              : {}),
          });
        });
      if (body.action === "pdf")
        return withSharingResponse(async () => {
          const pdf = await readVersionedPdf(topic, slug, body.kind);
          if (!pdf) throw new SharingError("Unknown paper.", 404);
          return withShareFiles(share, () => {
            authenticateParticipant(share, token);
            return Response.json(
              {
                etag: pdf.etag,
                pdf: Buffer.from(pdf.bytes).toString("base64"),
              },
              { headers },
            );
          });
        });
      if (body.action === "leave") {
        leaveCollaboration(share, participant);
        return Response.json({ left: true }, { headers });
      }
      if (body.action === "unpublish") {
        unpublishThread(share, participant, body.id);
        return Response.json({ unpublished: true }, { headers });
      }
      if (body.action === "read")
        return withSharingResponse(async () =>
          sharedResponse(
            share,
            token,
            await exportBundle(share, collaborationThreads(share)),
          ),
        );
      if (body.action === "save-pdf" || body.action === "comment") {
        const bytes =
          body.action === "save-pdf"
            ? Buffer.from(body.pdf, "base64")
            : Buffer.alloc(0);
        if (bytes.byteLength > MAX_COLLABORATIVE_PDF_BYTES)
          throw new SharingError(
            "The PDF exceeds the 32 MB collaboration limit.",
            413,
          );
        await rewritePdf(
          topic,
          slug,
          async (trusted) => {
            const actorId = `participant:${participant.id}`;
            const next =
              body.action === "comment"
                ? await reconstructComment(trusted, body.comment, {
                    name: participant.name,
                    id: actorId,
                  })
                : await reconstructAnnotations(trusted, bytes, {
                    id: actorId,
                    name: participant.name,
                  });
            withShareFiles(share, () => authenticateParticipant(share, token));
            return next;
          },
          body.etag,
          (commit) =>
            withShareFiles(share, () => {
              authenticateParticipant(share, token);
              commit();
            }),
          body.action === "save-pdf" ? body.kind : "paper",
        );
        withShareFiles(share, () => authenticateParticipant(share, token));
        const pdf = await readVersionedPdf(
          topic,
          slug,
          body.action === "save-pdf" ? body.kind : "paper",
        );
        if (!pdf) throw new SharingError("Unknown paper.", 404);
        return withShareFiles(share, () => {
          authenticateParticipant(share, token);
          return Response.json(
            {
              etag: pdf.etag,
              pdf: Buffer.from(pdf.bytes).toString("base64"),
              canonicalized: true,
            },
            { headers },
          );
        });
      }
      if (body.action === "publish")
        return sharedResponse(
          share,
          token,
          publishThread(
            share,
            authenticateParticipant(share, token),
            body,
            body.expected,
          ),
        );
      throw new SharingError("Invalid sharing operation.");
    });
  } catch (error) {
    if (error instanceof CanvasError || error instanceof ExerciseError)
      return Response.json(
        { error: error.message },
        { status: error.status, headers },
      );
    if (error instanceof RequestBodyError)
      return Response.json(
        { error: error.message },
        { status: error.status, headers },
      );
    if (error instanceof PdfConflictError)
      return Response.json({ error: error.message }, { status: 412, headers });
    if (error instanceof PdfBusyError || error instanceof FilesystemBusyError)
      return Response.json({ error: error.message }, { status: 409, headers });
    return sharingFailure(error);
  }
}

// This bearer-only endpoint bypasses proxy body cloning so admission can reject
// unfinished uploads. Keep its request policy here, before reading any bytes.
export async function POST(request: Request, context: Params) {
  const denied = requestPolicy(request);
  if (denied) return denied;
  try {
    return secure(
      [
        "save-pdf",
        "publish",
        "comment",
        ...artifactOperations.map((operation) => operation.shape.action.value),
      ].includes(request.headers.get("x-sharing-operation") ?? "")
        ? await withSharingResponse(() => handleExchange(request, context))
        : await handleExchange(request, context),
    );
  } catch (error) {
    return secure(sharingFailure(error));
  }
}

function secure(response: Response): Response {
  for (const [name, value] of Object.entries(headers))
    response.headers.set(name, value);
  return response;
}

function requestPolicy(request: Request): Response | null {
  const wait = consumeRequestLimit(
    `request:${clientIp(request)}`,
    publicRequestLimit(),
    60_000,
  );
  if (wait > 0)
    return secure(
      Response.json(
        { error: "Too many requests." },
        {
          status: 429,
          headers: { "Retry-After": String(Math.ceil(wait / 1000)) },
        },
      ),
    );
  if (crossSiteMutation(request))
    return secure(
      Response.json({ error: "Cross-site request rejected." }, { status: 403 }),
    );
  return null;
}

function unsupported(request: Request): Response {
  return (
    requestPolicy(request) ??
    secure(
      Response.json(
        { error: "Use POST for sharing exchanges." },
        { status: 405, headers: { Allow: "POST" } },
      ),
    )
  );
}

export const GET = unsupported;
export const HEAD = unsupported;
export const OPTIONS = unsupported;
export const PUT = unsupported;
export const PATCH = unsupported;
export const DELETE = unsupported;

import { NextResponse, type NextRequest } from "next/server";
import { fileResponse } from "@/lib/http/file-range";
import { getPaper } from "@/lib/library/papers";
import { readVersionedPdfFile } from "@/lib/library/pdf/file";
import { getShare, withShareFiles } from "@/lib/library/shares";
import { acquireProfileActivity } from "@/lib/auth/profile-capability";
import { PapernookIdentityStore } from "@/lib/auth/identity-store";
import { dataRoot } from "@/lib/data-dir";
import { guardStream } from "thesidedoor-core/runtime/stream";
import { isAccessError } from "thesidedoor-core/access";

export const dynamic = "force-dynamic";

interface Params {
  params: Promise<{ topic: string; slug: string; shareId: string }>;
}

const PRIVATE_CACHE_CONTROL = "private, no-cache";

const PRIVATE_HEADERS = {
  "cache-control": "private, no-store",
  "referrer-policy": "no-referrer",
  "x-robots-tag": "noindex, nofollow",
};

export async function GET(request: NextRequest, { params }: Params) {
  const { topic, slug, shareId } = await params;
  const share = getShare(topic, slug, shareId);
  const paper = share ? getPaper(topic, slug) : null;
  if (!share || !paper || share.ownerGeneration === undefined) {
    return NextResponse.json(
      { error: "Unknown share." },
      { status: 404, headers: PRIVATE_HEADERS },
    );
  }
  let release: (() => Promise<void>) | undefined;
  let streamOwnsLease = false;
  async function releaseOnce() {
    const cleanup = release;
    release = undefined;
    await cleanup?.();
  }
  try {
    release = await acquireProfileActivity(
      new PapernookIdentityStore(dataRoot()),
      {
        username: share.ownerUsername,
        generation: share.ownerGeneration,
      },
      request.signal,
    );
    withShareFiles(share, () => undefined);
    const pdf = await readVersionedPdfFile(topic, slug);
    if (!pdf) throw new Error("The shared PDF is missing.");
    const response = withShareFiles(share, () =>
      fileResponse({
        path: pdf.path,
        size: pdf.size,
        etag: pdf.etag,
        headers: request.headers,
        contentType: "application/pdf",
        filename: `${slug}.pdf`,
        cacheControl: PRIVATE_CACHE_CONTROL,
        extraHeaders: PRIVATE_HEADERS,
      }),
    );
    if (!response.body) return response;
    const stream = guardStream(response.body, {
      validate() {
        request.signal.throwIfAborted();
        withShareFiles(share, () => undefined);
      },
      release: releaseOnce,
    });
    try {
      const result = new NextResponse(stream, {
        status: response.status,
        headers: response.headers,
      });
      streamOwnsLease = true;
      return result;
    } catch (error) {
      await stream.cancel(error);
      throw error;
    }
  } catch (error) {
    if (isAccessError(error) && error.code === "unauthorized")
      return NextResponse.json(
        { error: "Unknown share." },
        { status: 404, headers: PRIVATE_HEADERS },
      );
    return NextResponse.json(
      { error: "Paper is temporarily unavailable." },
      { status: 503, headers: PRIVATE_HEADERS },
    );
  } finally {
    if (!streamOwnsLease) await releaseOnce();
  }
}

import { z } from "zod";
import { requestIdentity, sharedAccess } from "@/lib/auth/access";
import { withProfileFiles } from "@/lib/auth/profile-capability";
import { readBoundedJsonOrNull } from "@/lib/bounded-request";
import {
  bundleSchema,
  SharingError,
  sharingFailure,
  slugSchema,
} from "@/lib/sharing/schema";
import { exchange, parseShareUrl } from "@/lib/sharing/transport";
import { importBundle } from "@/lib/sharing/bundle";
import { artifactVersions } from "@/lib/sharing/artifacts/snapshot";
import {
  newSecret,
  participantId,
  saveConnection,
} from "@/lib/sharing/storage";

const bodySchema = z
  .object({
    url: z.string().max(4500),
    topic: slugSchema,
    mode: z.enum(["fork", "collaborate"]),
    acknowledgePublicAnnotations: z.boolean().default(false),
  })
  .strict();

export async function POST(request: Request) {
  try {
    const admission = await requestIdentity();
    if (!admission?.profile || !admission.capability)
      throw new SharingError("Not signed in.", 401);
    const parsed = bodySchema.safeParse(await readBoundedJsonOrNull(request));
    if (!parsed.success) throw new SharingError("Invalid import request.");
    const body = parsed.data;
    if (body.mode === "collaborate" && !body.acknowledgePublicAnnotations)
      throw new SharingError(
        "Confirm the visibility of collaborative annotations before requesting access.",
      );
    parseShareUrl(body.url);
    const bundle = bundleSchema.parse(
      await exchange(body.url, { action: "bundle" }),
    );
    if (body.mode === "collaborate" && bundle.mode !== "collaborate")
      throw new SharingError("This link permits independent copies only.", 403);
    const token = newSecret();
    if (body.mode === "collaborate")
      await exchange(
        body.url,
        { action: "request", name: admission.profile.displayName },
        token,
        () =>
          withProfileFiles(
            sharedAccess().identity,
            admission.capability!,
            () => undefined,
          ),
      );
    const paper = await importBundle(
      bundle,
      body.topic,
      admission.capability,
      body.mode === "collaborate",
    );
    if (body.mode === "collaborate") {
      const mirror = await artifactVersions(body.topic, paper.slug);
      saveConnection(
        body.topic,
        paper.slug,
        admission.capability,
        {
          version: 1,
          url: body.url,
          token,
          participantId: participantId(token),
          username: admission.capability.username,
          generation: admission.capability.generation,
          mirrorEtag: bundle.etag,
          artifacts: { source: null, mirror },
        },
        true,
      );
    }
    return Response.json(
      {
        href: `/paper/${body.topic}/${paper.slug}`,
        participantId:
          body.mode === "collaborate" ? participantId(token) : null,
      },
      { status: 201, headers: { "cache-control": "private, no-store" } },
    );
  } catch (error) {
    return sharingFailure(error);
  }
}

import Link from "next/link";
import { redirect } from "next/navigation";
import { requestIdentity } from "@/lib/auth/access";
import { profilePageFiles } from "@/lib/auth/platform/page-access";
import { listConversations } from "@/lib/conversations/store";
import { AccountBar } from "@/components/profiles/AccountBar";
import { LibraryNavigation } from "@/components/conversations/LibraryNavigation";
import { ImportConversation } from "@/components/conversations/ImportConversation";
import styles from "@/components/conversations/ConversationView.module.css";
export const dynamic = "force-dynamic";
export default async function Conversations({
  searchParams,
}: {
  searchParams: Promise<{
    q?: string;
    topic?: string;
    tag?: string;
    import?: string;
  }>;
}) {
  const admission = await requestIdentity();
  const profile = admission?.profile;
  if (!profile || !admission.capability) redirect("/login");
  const params = await searchParams;
  const all = profilePageFiles(admission.capability, () =>
    listConversations(profile.username),
  );
  const query = (params.q ?? "").toLowerCase();
  const records = all.filter(
    (record) =>
      (!params.topic || record.topic === params.topic) &&
      (!params.tag || record.tags.includes(params.tag)) &&
      (!query ||
        [
          record.title,
          record.topic,
          ...record.tags,
          ...record.messages.map((message) => message.content),
        ]
          .join(" ")
          .toLowerCase()
          .includes(query)),
  );
  return (
    <main>
      <AccountBar
        displayName={profile.displayName}
        avatarSlug={profile.avatarSlug}
      />
      <div className={styles.root}>
        <LibraryNavigation />
        <h1>
          Conversations <small>({all.length})</small>
        </h1>
        <p>
          Your imported source snapshots and follow-up chats are private to this
          profile.
        </p>
        <ImportConversation initialUrl={params.import} />
        <form className={`${styles.form} ${styles.filters}`}>
          <label>
            Search conversations
            <input name="q" defaultValue={params.q} />
          </label>
          <label>
            Topic
            <select name="topic" defaultValue={params.topic ?? ""}>
              <option value="">All topics</option>
              {[...new Set(all.map((record) => record.topic))]
                .sort()
                .map((topic) => (
                  <option key={topic}>{topic}</option>
                ))}
            </select>
          </label>
          <label>
            Tag
            <select name="tag" defaultValue={params.tag ?? ""}>
              <option value="">All tags</option>
              {[...new Set(all.flatMap((record) => record.tags))]
                .sort()
                .map((tag) => (
                  <option key={tag}>{tag}</option>
                ))}
            </select>
          </label>
          <button>Search</button>
        </form>
        {records.map((record) => (
          <article className={styles.card} key={record.id}>
            <h2>
              <Link href={`/conversations/${record.id}`}>{record.title}</Link>
            </h2>
            <p>
              {record.topic} · {record.provider} · {record.messages.length}{" "}
              messages
            </p>
            <p>{record.tags.join(", ")}</p>
          </article>
        ))}
        {records.length === 0 && <p>No conversations found.</p>}
      </div>
    </main>
  );
}

"use client";

import { useEffect, useState } from "react";
import styles from "./discover.module.css";
import { submitCapture } from "@/lib/capture/browser/submit";
import { AddToLibraryButton } from "@/components/library/AddToLibraryButton";

/**
 * Two independent sources of what to read next:
 *  - "Cited in your library": deterministic, server-derived from the papers'
 *    bibliographies. Fetched on mount and rendered even when no AI agent is
 *    configured (the /api/v1/discover route may 409; this section must not
 *    care).
 *  - AI suggestions: ask the agent for papers worth adding, grounded in the
 *    current library. "Add to papernook" hands the suggested URL to the
 *    normal /add capture pipeline (same as AddPaperBox), which downloads,
 *    analyzes, and files it — and surfaces the error if the agent suggested
 *    a dead link.
 */

interface Suggestion {
  title: string;
  authors: string[];
  year: number | null;
  url: string;
  why: string;
}

interface ReadingListCiter {
  topic: string;
  slug: string;
  title: string;
}

interface ReadingListItem {
  key: string;
  title: string;
  entryText: string;
  citedBy: ReadingListCiter[];
  count: number;
}

type ReadingListState =
  | { status: "loading" }
  | { status: "failed" }
  | { status: "ready"; items: ReadingListItem[] };

interface DiscoverClientProps {
  captureToken: string;
  topics: string[];
}

function CitedWorks() {
  const [state, setState] = useState<ReadingListState>({ status: "loading" });

  useEffect(() => {
    let cancelled = false;
    void (async () => {
      try {
        const res = await fetch("/api/v1/reading-list", {
          credentials: "include",
        });
        if (!res.ok) throw new Error(`reading list failed (${res.status})`);
        const data = (await res.json()) as { items: ReadingListItem[] };
        if (!cancelled) setState({ status: "ready", items: data.items });
      } catch {
        if (!cancelled) setState({ status: "failed" });
      }
    })();
    return () => {
      cancelled = true;
    };
  }, []);

  return (
    <section aria-label="Cited in your library">
      <h2 className={styles.sectionTitle}>Cited in your library</h2>
      {state.status === "loading" && (
        <p className={styles.empty}>Looking through your papers’ references…</p>
      )}
      {state.status === "failed" && (
        <p className={styles.empty}>Couldn’t load cited works right now.</p>
      )}
      {state.status === "ready" && state.items.length === 0 && (
        <p className={styles.empty}>
          No cited works yet — works your papers cite but your library lacks
          will appear here.
        </p>
      )}
      {state.status === "ready" && state.items.length > 0 && (
        <ul className={styles.cards}>
          {state.items.map((item) => (
            <li key={item.key} className={styles.card}>
              <h3 className={styles.cardTitle}>{item.title}</h3>
              <p className={styles.entryText}>{item.entryText}</p>
              <p className={styles.cardMeta}>
                Cited by {item.count === 1 ? "1 paper" : `${item.count} papers`}
                {": "}
                {item.citedBy.map((citer, index) => (
                  <span key={`${citer.topic}/${citer.slug}`}>
                    {index > 0 && ", "}
                    <a
                      className={styles.citedByLink}
                      href={`/paper/${citer.topic}/${citer.slug}`}
                    >
                      {citer.title}
                    </a>
                  </span>
                ))}
              </p>
              <div className={styles.cardActions}>
                <AddToLibraryButton resolveQuery={item.entryText} />
              </div>
            </li>
          ))}
        </ul>
      )}
    </section>
  );
}

export function DiscoverClient({ captureToken, topics }: DiscoverClientProps) {
  const [topic, setTopic] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [suggestions, setSuggestions] = useState<Suggestion[] | null>(null);

  async function discover(): Promise<void> {
    setBusy(true);
    setError(null);
    try {
      const res = await fetch("/api/v1/discover", {
        method: "POST",
        credentials: "include",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(topic ? { topic } : {}),
      });
      const data = (await res.json()) as {
        suggestions?: Suggestion[];
        error?: string;
      };
      if (!res.ok || !data.suggestions) {
        throw new Error(data.error ?? `Discovery failed (${res.status}).`);
      }
      setSuggestions(data.suggestions);
    } catch (err) {
      setError(err instanceof Error ? err.message : String(err));
    } finally {
      setBusy(false);
    }
  }

  function addToLibrary(url: string): void {
    submitCapture("/add", captureToken, url);
  }

  return (
    <section className={styles.body}>
      <CitedWorks />

      <h2 className={styles.sectionTitle}>Ask your agent</h2>
      <div className={styles.controls}>
        <select
          className={styles.topicSelect}
          value={topic}
          onChange={(e) => setTopic(e.target.value)}
          aria-label="Focus discovery on a topic"
          disabled={busy}
        >
          <option value="">Whole library</option>
          {topics.map((t) => (
            <option key={t} value={t}>
              {t}
            </option>
          ))}
        </select>
        <button
          type="button"
          className={styles.goButton}
          onClick={() => void discover()}
          disabled={busy}
        >
          {busy ? "Asking your agent…" : "Find related work"}
        </button>
      </div>

      {error && <p className={styles.error}>{error}</p>}

      {suggestions?.length === 0 && (
        <p className={styles.empty}>The agent had nothing new to suggest.</p>
      )}

      {suggestions && suggestions.length > 0 && (
        <ul className={styles.cards}>
          {suggestions.map((s) => (
            <li key={s.url} className={styles.card}>
              <h3 className={styles.cardTitle}>{s.title}</h3>
              <p className={styles.cardMeta}>
                {s.authors.join(", ")}
                {s.year ? ` · ${s.year}` : ""}
              </p>
              <p className={styles.cardWhy}>{s.why}</p>
              <div className={styles.cardActions}>
                <a
                  className={styles.sourceLink}
                  href={s.url}
                  target="_blank"
                  rel="noopener noreferrer"
                >
                  Source ↗
                </a>
                <button
                  type="button"
                  className={styles.addButton}
                  onClick={() => addToLibrary(s.url)}
                >
                  Add to papernook
                </button>
              </div>
            </li>
          ))}
        </ul>
      )}
    </section>
  );
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import styles from "./inbox.module.css";

interface InboxReviewProps {
  slug: string;
  topics: string[];
  /** Capture analysis' filing proposal; preselected when present. */
  proposedTopic: string | null;
}

function errorMessage(payload: unknown, fallback: string): string {
  return payload &&
    typeof payload === "object" &&
    "error" in payload &&
    typeof payload.error === "string"
    ? payload.error
    : fallback;
}

export function InboxReview({ slug, topics, proposedTopic }: InboxReviewProps) {
  const router = useRouter();
  const [topic, setTopic] = useState(proposedTopic ?? topics[0] ?? "unsorted");
  const [busy, setBusy] = useState<"accept" | "discard" | null>(null);
  const [error, setError] = useState<string | null>(null);

  async function accept(): Promise<void> {
    setBusy("accept");
    setError(null);
    const response = await fetch(`/api/v1/inbox/${slug}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      credentials: "include",
      body: JSON.stringify({ topic: topic.trim() }),
    });
    const payload: unknown = await response.json().catch(() => null);
    if (
      response.ok &&
      payload &&
      typeof payload === "object" &&
      "href" in payload &&
      typeof payload.href === "string"
    ) {
      router.push(payload.href);
      router.refresh();
      return;
    }
    setError(errorMessage(payload, "The paper could not be filed."));
    setBusy(null);
  }

  async function discard(): Promise<void> {
    if (!window.confirm("Discard this pending capture?")) return;
    setBusy("discard");
    setError(null);
    const response = await fetch(`/api/v1/inbox/${slug}`, {
      method: "DELETE",
      credentials: "include",
    });
    const payload: unknown = await response.json().catch(() => null);
    if (response.ok) {
      router.push("/");
      router.refresh();
      return;
    }
    setError(errorMessage(payload, "The paper could not be discarded."));
    setBusy(null);
  }

  return (
    <div className={styles.review}>
      <label htmlFor="inbox-topic">Library topic</label>
      <input
        id="inbox-topic"
        list="library-topics"
        value={topic}
        disabled={busy !== null}
        onChange={(event) => setTopic(event.target.value)}
      />
      <datalist id="library-topics">
        {topics.map((item) => (
          <option key={item} value={item} />
        ))}
      </datalist>
      {topics.length > 0 && (
        <div className={styles.topics}>
          {topics.map((item) => (
            <button
              key={item}
              type="button"
              className={
                item === topic.trim() ? styles.topicActive : styles.topic
              }
              disabled={busy !== null}
              onClick={() => setTopic(item)}
            >
              {item}
            </button>
          ))}
        </div>
      )}
      <div className={styles.actions}>
        <button
          type="button"
          className={styles.accept}
          disabled={busy !== null || topic.trim().length === 0}
          onClick={() => void accept()}
        >
          {busy === "accept" ? "Filing…" : "Add to papernook"}
        </button>
        <button
          type="button"
          className={styles.discard}
          disabled={busy !== null}
          onClick={() => void discard()}
        >
          {busy === "discard" ? "Discarding…" : "Discard"}
        </button>
      </div>
      {error && (
        <p className={styles.error} role="alert">
          {error}
        </p>
      )}
    </div>
  );
}

import { notFound, redirect } from "next/navigation";
import { headers } from "next/headers";
import { activeProfile } from "@/lib/auth/session";
import { getPaper } from "@/lib/library/papers";
import { getProvider, hasConfiguredProvider } from "@/lib/agent/registry";
import { ChatPanel } from "@/components/chat/ChatPanel";
import { ReadingWorkspace } from "@/components/chat/ReadingWorkspace";
import { CopySourceLinkButton } from "@/components/paper/CopySourceLinkButton";
import { PaperHeader } from "@/components/paper/PaperHeader";
import { CanvasClient } from "./CanvasClient";
import {
  CanvasConfigError,
  configuredCanvasLicense,
  tldrawLicenseRequired,
} from "@/lib/canvas/config";
import styles from "../paper.module.css";
import { readConnection } from "@/lib/sharing/storage";

export const dynamic = "force-dynamic";

interface CanvasPageProps {
  params: Promise<{ topic: string; slug: string }>;
}

export default async function CanvasPage({ params }: CanvasPageProps) {
  const profile = await activeProfile();
  if (!profile) redirect("/login");
  const { topic, slug } = await params;
  const paper = getPaper(topic, slug);
  if (!paper) notFound();
  const connection = readConnection(topic, slug);
  const headerStore = await headers();
  const protocol = headerStore.get("x-forwarded-proto") ?? "http";
  const hostname = headerStore.get("host") ?? "localhost";
  const currentOrigin = `${protocol}://${hostname}`;
  const aiAvailable = hasConfiguredProvider();
  const visionAvailable = aiAvailable && getProvider().capabilities.vision;
  let licenseKey: string | null = null;
  let licenseError: string | null = null;
  try {
    licenseKey = configuredCanvasLicense().licenseKey;
  } catch (error) {
    licenseError =
      error instanceof CanvasConfigError
        ? error.message
        : "The canvas configuration could not be loaded.";
  }

  return (
    <main className={styles.root}>
      <ReadingWorkspace
        mainLabel="Canvas"
        header={
          <PaperHeader
            topic={topic}
            slug={slug}
            meta={paper.meta}
            view="canvas"
          />
        }
        collapsedHeaderActions={
          <CopySourceLinkButton sourceUrl={paper.meta.sourceUrl} />
        }
        main={
          connection && connection.username !== profile.username ? (
            <p>
              This collaboration belongs to another profile. Switch profiles to
              open its canvas.
            </p>
          ) : (
            <CanvasClient
              topic={topic}
              slug={slug}
              title={paper.meta.title}
              username={profile.username}
              licenseKey={licenseKey}
              licenseRequired={tldrawLicenseRequired(protocol, hostname)}
              licenseError={licenseError}
              visionAvailable={visionAvailable}
            />
          )
        }
        chat={
          <div className={styles.chat}>
            {paper.summary && <p className={styles.summary}>{paper.summary}</p>}
            <ChatPanel
              topic={topic}
              slug={slug}
              currentOrigin={currentOrigin}
              paperSourceUrl={paper.meta.sourceUrl ?? undefined}
              aiAvailable={aiAvailable}
              visionAvailable={visionAvailable}
              bibliographyEndpoint={`/api/v1/papers/${topic}/${slug}/bibliography`}
            />
          </div>
        }
      />
    </main>
  );
}

