import {
  getShare,
  withShareFiles,
  type PaperShare,
} from "@/lib/library/shares";
import { isAccessError } from "thesidedoor-core/access";
import styles from "./share.module.css";
import { ImportOnInstance } from "@/components/share/ImportReading";
import { PublicStudyArtifacts } from "@/components/share/StudyArtifacts";
import { configuredCanvasLicense } from "@/lib/canvas/config";

export const dynamic = "force-dynamic";

interface SharePageProps {
  params: Promise<{ topic: string; slug: string; shareId: string }>;
}

export const metadata: Metadata = {
  robots: { index: false, follow: false },
  referrer: "no-referrer",
};

function cropUrl(share: PaperShare, imagePath: string): string | null {
  const match = imagePath.match(/^crops\/([^/]+)$/);
  if (!match) return null;
  return `/api/v1/shares/${share.topic}/${share.slug}/${share.id}/images/${encodeURIComponent(match[1])}`;
}

export default async function SharePage({ params }: SharePageProps) {
  const { topic, slug, shareId } = await params;
  const share = getShare(topic, slug, shareId);
  const paper = share ? getPaper(topic, slug) : null;
  if (!share || !paper) notFound();

  const meta = paper.meta;
  const licenseKey = share.includeArtifacts
    ? configuredCanvasLicense().licenseKey
    : null;
  let currentOrigin: string | undefined;
  try {
    const headerStore = await headers();
    const protocol = headerStore.get("x-forwarded-proto") ?? "http";
    const hostname = headerStore.get("host") ?? "localhost";
    currentOrigin = `${protocol}://${hostname}`;
  } catch {
    // Direct server-component tests have no request store. Relative links
    // still classify as internal; absolute web links safely open separately.
  }
  try {
    return withShareFiles(share, () => (
      <main className={styles.root}>
        <header className={styles.masthead}>
          <div className={styles.brand}>papernook</div>
          <div className={styles.permission}>
            <span className={styles.lock} aria-hidden="true">
              ◇
            </span>
            View only
          </div>
        </header>

        <section className={styles.intro}>
          <p className={styles.eyebrow}>A shared reading</p>
          <h1 className={styles.title}>{meta.title}</h1>
          <p className={styles.meta}>
            {meta.authors.join(", ")}
            {meta.year ? ` · ${meta.year}` : ""}
            {meta.venue ? ` · ${meta.venue}` : ""}
          </p>
          <p className={styles.note}>
            You can read the current annotated paper and the conversation
            snapshots selected by its owner. This page cannot change the paper
            or continue the chats.
          </p>
        </section>

        <div className={styles.columns}>
          <section className={styles.paperColumn} aria-label="Annotated paper">
            <div className={styles.sectionLabel}>
              <span>Annotated paper</span>
              <span>Live copy</span>
            </div>
            <div className={styles.pdfFrame}>
              <PdfReader
                src={`/api/v1/shares/${topic}/${slug}/${shareId}/pdf`}
                title={meta.title}
              />
            </div>
          </section>

          <aside className={styles.studyColumn}>
            {share.includeArtifacts && (
              <PublicStudyArtifacts
                endpoint={`/api/v1/shares/${topic}/${slug}/${shareId}/artifacts`}
                licenseKey={licenseKey}
              />
            )}
            {paper.summary && (
              <section className={styles.summary}>
                <h2>Reading note</h2>
                <p>{paper.summary}</p>
              </section>
            )}

            <section className={styles.conversations}>
              <div className={styles.sectionLabel}>
                <span>Conversations</span>
                <span>
                  {share.conversations.length} snapshot
                  {share.conversations.length === 1 ? "" : "s"}
                </span>
              </div>
              {share.conversations.length === 0 ? (
                <p className={styles.empty}>
                  The owner shared the annotated paper without conversations.
                </p>
              ) : (
                share.conversations.map((conversation, conversationIndex) => (
                  <article
                    className={styles.conversation}
                    key={conversation.header.id}
                  >
                    <h2>
                      <span>
                        {String(conversationIndex + 1).padStart(2, "0")}
                      </span>
                      {conversation.header.title}
                    </h2>
                    <div className={styles.messages}>
                      {conversation.messages.map((message, messageIndex) => (
                        <div
                          className={
                            message.role === "user"
                              ? styles.readerMessage
                              : styles.agentMessage
                          }
                          key={`${conversation.header.id}-${messageIndex}`}
                        >
                          <p className={styles.role}>
                            {message.role === "user" ? "Reader" : "Papernook"}
                          </p>
                          {message.images?.map((imagePath) => {
                            const src = cropUrl(share, imagePath);
                            return src ? (
                              // eslint-disable-next-line @next/next/no-img-element
                              <img
                                className={styles.crop}
                                src={src}
                                alt="Conversation attachment"
                                key={imagePath}
                              />
                            ) : null;
                          })}
                          {message.role === "assistant" ? (
                            <Markdown
                              content={message.content}
                              currentOrigin={currentOrigin}
                              paperSourceUrl={meta.sourceUrl ?? undefined}
                            />
                          ) : (
                            <p className={styles.messageText}>
                              {message.content}
                            </p>
                          )}
                        </div>
                      ))}
                    </div>
                  </article>
                ))
              )}
            </section>
          </aside>
        </div>

        <footer className={styles.footer}>
          {share.mode !== "view" && <ImportOnInstance mode={share.mode} />}
          Shared {new Date(share.createdAt).toLocaleDateString()} · The owner
          can revoke this link at any time.
        </footer>
      </main>
    ));
  } catch (error) {
    if (isAccessError(error) && error.code === "unauthorized") notFound();
    throw error;
  }
}

"use client";

import { useEffect, useRef, useState } from "react";
import { PdfReader } from "@/components/pdf/PdfReader";
import { CopySourceLinkButton } from "@/components/paper/CopySourceLinkButton";
import { originalWebUrl } from "@/lib/pdf/reader/source-link";
import styles from "./viewer.module.css";

interface ViewerShellProps {
  /** Original external PDF URL (already validated http/https server-side). */
  src: string;
  title: string;
}

type CaptureState =
  | { phase: "idle" }
  | { phase: "capturing"; slug: string }
  | { phase: "added"; finalSlug: string | null }
  | { phase: "failed"; error: string };

const POLL_MS = 2000;

export function ViewerShell({ src, title }: ViewerShellProps) {
  const [capture, setCapture] = useState<CaptureState>({ phase: "idle" });
  // Prefer the PDF's embedded Title over the URL-derived filename — tabs and
  // the header then read as the actual paper name.
  const [displayTitle, setDisplayTitle] = useState(title);
  const unmounted = useRef(false);

  useEffect(() => {
    document.title = displayTitle;
  }, [displayTitle]);

  useEffect(() => {
    unmounted.current = false;
    return () => {
      unmounted.current = true;
    };
  }, []);

  async function addToLibrary(): Promise<void> {
    setCapture({ phase: "capturing", slug: "" });
    try {
      const response = await fetch("/api/v1/capture", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({ url: src }),
      });
      const payload: unknown = await response.json().catch(() => null);
      const slug = stringField(payload, "slug");
      if (!response.ok || !slug) {
        setCapture({
          phase: "failed",
          error:
            stringField(payload, "error") ??
            "Capture failed: no response from the server. A slow capture may still finish — check the Inbox before retrying.",
        });
        return;
      }
      setCapture({ phase: "capturing", slug });
      await pollUntilSettled(slug);
    } catch {
      setCapture({ phase: "failed", error: "Capture failed." });
    }
  }

  /** Poll the job marker until done/failed; the viewer never navigates away. */
  async function pollUntilSettled(slug: string): Promise<void> {
    for (;;) {
      await sleep(POLL_MS);
      if (unmounted.current) return;
      let response: Response;
      try {
        response = await fetch(
          `/api/v1/capture?slug=${encodeURIComponent(slug)}`,
          { credentials: "include" },
        );
      } catch {
        // Transient network blip: the capture is still running server-side.
        continue;
      }
      const payload: unknown = await response.json().catch(() => null);
      if (!response.ok) {
        setCapture({
          phase: "failed",
          error: stringField(payload, "error") ?? "Capture failed.",
        });
        return;
      }
      const state = stringField(payload, "state");
      if (state === "done") {
        setCapture({
          phase: "added",
          finalSlug: stringField(payload, "finalSlug"),
        });
        return;
      }
      if (state === "failed") {
        setCapture({
          phase: "failed",
          error: stringField(payload, "error") ?? "Capture failed.",
        });
        return;
      }
    }
  }

  const busy = capture.phase === "capturing";
  return (
    <>
      <header className={styles.bar}>
        <span className={styles.barTitle} title={displayTitle}>
          {displayTitle}
        </span>
        <div className={styles.sourceAction}>
          <CopySourceLinkButton sourceUrl={src} />
        </div>
        <a className={styles.original} href={originalWebUrl(src) ?? src}>
          Original
        </a>
        {capture.phase === "added" ? (
          <a
            className={styles.added}
            href={
              capture.finalSlug
                ? `/inbox/${encodeURIComponent(capture.finalSlug)}`
                : "/?topic=_inbox"
            }
          >
            Added ✓ — review in Inbox
          </a>
        ) : (
          <button
            type="button"
            className={styles.addBtn}
            disabled={busy}
            onClick={() => void addToLibrary()}
          >
            {busy && <span className={styles.spinner} aria-hidden="true" />}
            {busy ? "Capturing…" : "+ Add to papernook"}
          </button>
        )}
      </header>
      {capture.phase === "failed" && (
        <p className={styles.error} role="alert">
          {capture.error}
        </p>
      )}
      <PdfReader
        src={`/api/v1/viewer/pdf?src=${encodeURIComponent(src)}`}
        title={displayTitle}
        originalHref={src}
        onDocumentTitle={setDisplayTitle}
        libraryLookup
      />
    </>
  );
}

function stringField(payload: unknown, key: string): string | null {
  if (payload && typeof payload === "object" && key in payload) {
    const value = (payload as Record<string, unknown>)[key];
    if (typeof value === "string") return value;
  }
  return null;
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

