import {
  useEffect,
  useRef,
  useState,
  type FormEvent,
  type ReactNode,
} from "react";
import { useRouter } from "next/navigation";
import { Markdown } from "@/components/chat/Markdown";
import { ReadingWorkspace } from "@/components/chat/ReadingWorkspace";
import { LibraryNavigation } from "./LibraryNavigation";
import {
