} from "@/components/chat/DocumentAppearance";

type TurnMessage = {
  role: "user" | "assistant";
  content: string;
  images?: string[];
};

function ConversationInput({
  busy,
  connected,
  onSend,
}: {
  busy: boolean;
  connected: boolean;
  onSend: (query: string, images: string[]) => Promise<void>;
}) {
  const [query, setQuery] = useState("");
  const [images, setImages] = useState<string[]>([]);

  async function submit(event: FormEvent<HTMLFormElement>): Promise<void> {
    event.preventDefault();
    if (busy || !connected || !query.trim()) return;
    const value = query;
    setQuery("");
    const attached = images;
    setImages([]);
    await onSend(value, attached);
  }

  function onKeyDown(event: React.KeyboardEvent<HTMLTextAreaElement>): void {
    if (
      event.nativeEvent.isComposing ||
      event.key !== "Enter" ||
      event.shiftKey
    )
      return;
    event.preventDefault();
    event.currentTarget.form?.requestSubmit();
  }

  function onPaste(event: React.ClipboardEvent<HTMLTextAreaElement>): void {
    for (const item of event.clipboardData.items) {
      if (!item.type.startsWith("image/")) continue;
      const file = item.getAsFile();
      if (!file) continue;
      const reader = new FileReader();
      reader.onload = () => {
        if (typeof reader.result === "string") {
          setImages((current) =>
            [...current, reader.result as string].slice(0, 4),
          );
        }
      };
      reader.readAsDataURL(file);
    }
  }

  return (
    <>
      {images.length > 0 && (
        <div className={chatStyles.pastedRow} aria-label="Attached images">
          {images.map((src, index) => (
            // eslint-disable-next-line @next/next/no-img-element
            <img
              key={`${src.slice(0, 30)}-${index}`}
              className={chatStyles.pastedThumb}
              src={src}
              alt={`Attachment ${index + 1}`}
            />
          ))}
          <button type="button" onClick={() => setImages([])}>
            Clear
          </button>
        </div>
      )}
      <form
        className={chatStyles.inputRow}
        onSubmit={(event) => void submit(event)}
      >
        <textarea
          className={chatStyles.input}
          aria-label="Question"
          rows={2}
          required
          maxLength={40_000}
          value={query}
          placeholder="Ask about this conversation… (paste screenshots here)"
          onChange={(event) => setQuery(event.target.value)}
          onPaste={onPaste}
          onKeyDown={onKeyDown}
          disabled={busy}
        />
        <button
          className={chatStyles.sendBtn}
          disabled={busy || !connected || !query.trim()}
        >
          {busy ? "Thinking…" : "Send"}
        </button>
      </form>
    </>
  );
}

function ConversationTurns({
  messages,
  followUp = false,
  conversationId,
}: {
  messages: TurnMessage[];
  followUp?: boolean;
  conversationId?: string;
}) {
  const groups: { start: number; messages: TurnMessage[] }[] = [];
  messages.forEach((message, index) => {
    const previous = groups.at(-1);
    if (previous?.messages[0].role === message.role) {
      previous.messages.push(message);
    } else {
      groups.push({ start: index, messages: [message] });
    }
  });
  return groups.map((group) =>
    group.messages.length === 1 ? (
      <ConversationTurn
        key={group.start}
        message={group.messages[0]}
        index={group.start}
        followUp={followUp}
        conversationId={conversationId}
      />
    ) : (
      <ConversationTurnGroup
        key={group.start}
        {...group}
        followUp={followUp}
        conversationId={conversationId}
      />
    ),
  );
}

function ConversationTurnGroup({
  messages,
  start,
  followUp,
  conversationId,
}: {
  messages: TurnMessage[];
  start: number;
  followUp: boolean;
  conversationId?: string;
}) {
  const [expanded, setExpanded] = useState(true);
  const label =
    messages[0].role === "user" ? (followUp ? "You" : "User") : "Assistant";
  return (
    <details
      className={`${readerStyles.turnGroup} ${followUp ? readerStyles.chatGroup : ""}`}
      open={expanded}
      onToggle={(event) => setExpanded(event.currentTarget.open)}
    >
      <summary
        className={readerStyles.messageHeading}
        aria-label={`${label} turns ${start + 1} to ${start + messages.length}`}
      >
        <strong>
          {label} · {messages.length} messages
        </strong>
        <span>
          {start + 1}–{start + messages.length}
          <ChevronDown
            className={readerStyles.turnChevron}
            size={16}
            aria-hidden="true"
          />
        </span>
      </summary>
      <div className={readerStyles.groupMessages}>
        {messages.map((message, index) => (
          <ConversationTurn
            key={start + index}
            message={message}
            index={start + index}
            followUp={followUp}
            conversationId={conversationId}
          />
        ))}
      </div>
    </details>
  );
}

function ConversationTurn({
  message,
  index,
  followUp = false,
  conversationId,
}: {
  message: TurnMessage;
  index: number;
  followUp?: boolean;
  conversationId?: string;
}) {
  const [expanded, setExpanded] = useState(true);
  const label =
    message.role === "user" ? (followUp ? "You" : "User") : "Assistant";
  return (
    <details
      className={
        followUp
          ? `${readerStyles.chatMessage} ${message.role === "user" ? chatStyles.userMsg : chatStyles.assistantMsg}`
          : readerStyles.sourceMessage
      }
      data-message-role={message.role}
      open={expanded}
      onToggle={(event) => setExpanded(event.currentTarget.open)}
    >
      <summary
        className={readerStyles.messageHeading}
        aria-label={`${label} turn ${index + 1}`}
      >
        <h3
          className={`${readerStyles.role} ${message.role === "user" ? readerStyles.userRole : readerStyles.assistantRole}`}
        >
          {message.role === "user" ? (
            <User size={13} aria-hidden="true" />
          ) : (
            <Bot size={13} aria-hidden="true" />
          )}
          {label}
        </h3>
        <span>
          {String(index + 1).padStart(2, "0")}{" "}
          <ChevronDown
            className={readerStyles.turnChevron}
            size={16}
            aria-hidden="true"
          />
        </span>
      </summary>
      {message.images?.map((image) => {
        const name = image.split("/").at(-1);
        return conversationId && name ? (
          // eslint-disable-next-line @next/next/no-img-element
          <img
            key={image}
            className={chatStyles.msgImage}
            src={`/api/v1/conversations/${conversationId}/images/${encodeURIComponent(name)}`}
            alt="Conversation attachment"
          />
        ) : null;
      })}
      <Markdown content={message.content} renderThree currentOrigin="" />
    </details>
  );
}
export function ConversationReader({
  conversation,
  initialChats,
  accountBar,
}: {
  conversation: Conversation;
  initialChats: Chat[];
  accountBar: ReactNode;
}) {
  const router = useRouter();
  const appearance = useDocumentAppearance();
  const connected = useConnection();
  const [chats, setChats] = useState(initialChats);
  const [chatId, setChatId] = useState(initialChats[0]?.header.id ?? "");
  const [pendingQuery, setPendingQuery] = useState("");
  const [pendingImages, setPendingImages] = useState<string[]>([]);
  const [draft, setDraft] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [readingProgress, setReadingProgress] = useState(0);
  const sourceRef = useRef<HTMLDivElement>(null);
  const chatScrollRef = useRef<HTMLDivElement>(null);
  const base = `/api/v1/conversations/${conversation.id}`;
  useEffect(() => {
    const key = `papernook:offline-position:conversation:${conversation.id}:source`;
    const scrollElement = sourceRef.current;
    if (!scrollElement) return;
    const updateProgress = () => {
      const maximum = scrollElement.scrollHeight - scrollElement.clientHeight;
      setReadingProgress(
        maximum > 0 ? Math.round((scrollElement.scrollTop / maximum) * 100) : 0,
      );
    };
    try {
      const value = Number(localStorage.getItem(key));
      if (value > 0) scrollElement.scrollTop = value;
    } catch {}
    const save = () => {
      try {
        localStorage.setItem(key, String(scrollElement.scrollTop));
      } catch {}
    };
    scrollElement.addEventListener("scroll", save, { passive: true });
    scrollElement.addEventListener("scroll", updateProgress, { passive: true });
    updateProgress();
    return () => {
      scrollElement.removeEventListener("scroll", save);
      scrollElement.removeEventListener("scroll", updateProgress);
    };
  }, [conversation.id]);
  useEffect(() => {
    const element = chatScrollRef.current;
    if (element)
      element.scrollTop =
        draft ||
        chats.find((chat) => chat.header.id === chatId)?.messages.length
          ? element.scrollHeight
          : 0;
  }, [draft, chatId, chats]);
  async function send(query: string, images: string[] = []): Promise<void> {
    if (busy || !query.trim()) return;
    if (!connected) {
      setError("Connect to continue this conversation.");
      return;
    }
    setBusy(true);
    setError("");
    setPendingQuery(query);
    setPendingImages(images);
    setDraft("");
    try {
      const response = await fetch(`${base}/chats`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          query,
          chatId: chatId || undefined,
          images: images.length ? images : undefined,
        }),
      });
      if (!response.ok) {
        const data = await response.json();
        throw new Error(data.error || "Chat failed.");
      }
      if (!response.body)
        throw new Error("The server returned no reply stream.");
      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let pending = "";
      let done = false;
      try {
        while (true) {
          const next = await reader.read();
          pending += decoder.decode(next.value, { stream: !next.done });
          const lines = pending.split("\n");
          pending = lines.pop() ?? "";
          for (const line of lines) {
            if (!line) continue;
            const data = JSON.parse(line);
            if (data.type === "error") throw new Error(data.error);
            if (data.type === "delta") setDraft((value) => value + data.text);
            if (data.type === "done") {
              const chat = data.chat as Chat;
              setChats((current) => [
                ...current.filter(
                  (value) => value.header.id !== chat.header.id,
                ),
                chat,
              ]);
              setChatId(chat.header.id);
              setPendingQuery("");
              setPendingImages([]);
              setDraft("");
              done = true;
            }
          }
          if (next.done) break;
        }
        if (!done)
          throw new Error(
            "The reply stream ended before saving. Retry your question.",
          );
      } finally {
        reader.releaseLock();
      }
    } catch (error) {
      setPendingQuery("");
      setPendingImages([]);
      setDraft("");
      setError(error instanceof Error ? error.message : "Chat failed.");
    } finally {
      setBusy(false);
    }
  }
  async function metadata(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const data = new FormData(event.currentTarget);
    setError("");
    try {
      const response = await fetch(base, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          title: data.get("title"),
          topic: data.get("topic"),
          tags: String(data.get("tags") || "")
            .split(",")
            .map((tag) => tag.trim())
            .filter(Boolean),
        }),
      });
      if (!response.ok) throw new Error((await response.json()).error);
      router.refresh();
    } catch (error) {
      setError(error instanceof Error ? error.message : "Update failed.");
    }
  }
  async function remove() {
    if (
      !window.confirm(
        "Delete this imported conversation and its follow-up chats?",
      )
    )
      return;
    try {
      const response = await fetch(base, { method: "DELETE" });
      if (!response.ok) throw new Error((await response.json()).error);
      router.push("/conversations");
      router.refresh();
    } catch (error) {
      setError(error instanceof Error ? error.message : "Delete failed.");
    }
  }
  const active = chats.find((chat) => chat.header.id === chatId);
  return (
    <>
      <div className={readerStyles.mobileAccount}>{accountBar}</div>
      {error && (
        <p role="alert" className={styles.error}>
          {error}
        </p>
      )}
      <ReadingWorkspace
        mainLabel="Source transcript"
        workspaceLabel="Conversation workspace"
        actions={
          <DownloadButton
            snapshotUrl={`/api/v1/offline/conversations/${conversation.id}`}
          />
        }
        header={
          <header className={readerStyles.header}>
            <div className={readerStyles.desktopAccount}>{accountBar}</div>
            <LibraryNavigation />
            <div className={readerStyles.headingRow}>
              <div>
                <h1>{conversation.title}</h1>
                <p className={readerStyles.caption}>
                  Saved {new Date(conversation.importedAt).toLocaleDateString()}{" "}
                  · {conversation.provider} · {conversation.messages.length}{" "}
                  messages · Private
                </p>
              </div>
              <div className={readerStyles.actions}>
                <details className={readerStyles.exportMenu}>
                  <summary>
                    <Download size={16} aria-hidden="true" /> Export
                  </summary>
                  <div>
                    <a
                      href={`${base}/export?format=html`}
                      target="_blank"
                      rel="noopener noreferrer"
                    >
                      HTML / Save as PDF
                    </a>
                    <a href={`${base}/export?format=markdown`}>Markdown</a>
                    <a href={`${base}/export?format=json`}>JSON</a>
                  </div>
                </details>
                {conversation.sourceUrl && (
                  <a
                    href={conversation.sourceUrl}
                    target="_blank"
                    rel="noreferrer noopener"
                  >
                    <ExternalLink size={16} aria-hidden="true" /> Original share
                  </a>
                )}
              </div>
            </div>
            <details className={readerStyles.metadata}>
              <summary>Edit title, topic and tags</summary>
              <form
                className={styles.form}
                onSubmit={(event) => void metadata(event)}
              >
                <label>
                  Title
                  <input
                    name="title"
                    defaultValue={conversation.title}
                    required
                    maxLength={200}
                  />
                </label>
                <label>
                  Topic
                  <input
                    name="topic"
                    defaultValue={conversation.topic}
                    required
                    maxLength={80}
                  />
                </label>
                <label>
                  Tags
                  <input
                    name="tags"
                    defaultValue={conversation.tags.join(", ")}
                  />
                </label>
                <button>Save details</button>
                <button
                  type="button"
                  className={readerStyles.deleteButton}
                  disabled={busy}
                  onClick={() => void remove()}
                >
                  Delete conversation
                </button>
              </form>
            </details>
          </header>
        }
        main={
          <div className={pdfStyles.root} data-document-appearance={appearance}>
            <div
              className={`${pdfStyles.toolbar} ${readerStyles.documentToolbar}`}
            >
              <span>
                <BookOpen size={16} aria-hidden="true" /> Source transcript
              </span>
              <span>{conversation.messages.length} messages</span>
              <DocumentAppearanceSelect value={appearance} />
            </div>
            <progress
              className={readerStyles.readingProgress}
              max={100}
              value={readingProgress}
              aria-label={`Reading progress: ${readingProgress}%`}
            />
            <div
              ref={sourceRef}
              className={readerStyles.documentScroll}
              tabIndex={0}
              aria-label="Scroll transcript"
            >
              <div className={readerStyles.paper}>
                <div className={readerStyles.documentTitle}>
                  <p className={readerStyles.eyebrow}>
                    Conversation · {conversation.provider}
                  </p>
                  <p className={readerStyles.paperTitle}>
                    {conversation.title}
                  </p>
                  <div className={readerStyles.tags}>
                    <span>{conversation.topic}</span>
                    {conversation.tags.map((tag) => (
                      <span key={tag}>{tag}</span>
                    ))}
                  </div>
                </div>
                <ConversationTurns
                  messages={conversation.messages}
                  conversationId={conversation.id}
                />
                <footer className={readerStyles.documentFooter}>
                  End of saved conversation · {conversation.messages.length}{" "}
                  messages
                </footer>
              </div>
            </div>
          </div>
        }
        chat={
          <section
            className={`${chatStyles.root} ${readerStyles.chatPanel}`}
            aria-label="Follow-up chats"
          >
            <div className={chatStyles.header}>
              <select
                className={chatStyles.chatSelect}
                aria-label="Follow-up chat"
                disabled={busy}
                value={chatId}
                onChange={(event) => setChatId(event.target.value)}
              >
                <option value="">New chat</option>
                {chats.map((chat) => (
                  <option key={chat.header.id} value={chat.header.id}>
                    {chat.header.title}
                  </option>
                ))}
              </select>
              <button
                type="button"
                className={chatStyles.newBtn}
                disabled={busy}
                onClick={() => setChatId("")}
              >
                + New
              </button>
            </div>
            <div ref={chatScrollRef} className={chatStyles.messages}>
              {!active?.messages.length && !busy && (
                <p className={chatStyles.empty}>
                  Ask a question to explore the saved conversation.
                </p>
              )}
              <ConversationTurns
                key={chatId}
                messages={active?.messages ?? []}
                followUp
                conversationId={conversation.id}
              />
              {pendingQuery && (
                <article className={chatStyles.userMsg}>
                  <h3 className={readerStyles.role}>You</h3>
                  {pendingImages.map((src, index) => (
                    // eslint-disable-next-line @next/next/no-img-element
                    <img
                      key={`${src.slice(0, 30)}-${index}`}
                      className={chatStyles.msgImage}
                      src={src}
                      alt={`Attachment ${index + 1}`}
                    />
                  ))}
                  <p>{pendingQuery}</p>
                </article>
              )}
              {busy && (
                <article className={chatStyles.assistantMsg}>
                  <h3 className={readerStyles.role}>Assistant</h3>
                  {draft ? (
                    <Markdown
                      content={draft}
                      highlightCode={false}
                      copyCode={false}
                      currentOrigin=""
                    />
                  ) : (
                    <span
                      className={chatStyles.typingIndicator}
                      role="status"
                      aria-label="Assistant is typing"
                    >
                      <span />
                      <span />
                      <span />
                    </span>
                  )}
                </article>
              )}
            </div>
            {!connected && (
              <p role="status" className={readerStyles.caption}>
                Connect to continue this conversation. Your draft is preserved.
              </p>
            )}
            <ConversationInput
              busy={busy}
              connected={connected}
              onSend={send}
            />
          </section>
        }
      />
    </>
  );
}

"use client";
import { useState, type ChangeEvent, type FormEvent } from "react";
import { useRouter } from "next/navigation";
import styles from "./ConversationView.module.css";
export function ImportConversation({
  initialUrl = "",
}: {
  initialUrl?: string;
}) {
  const router = useRouter();
  const [url, setUrl] = useState(initialUrl);
  const [content, setContent] = useState("");
  const [format, setFormat] = useState("markdown");
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);
  const [source, setSource] = useState<"link" | "transcript">("link");
  const [reading, setReading] = useState(false);
  const ready = Boolean(source === "link" ? url.trim() : content.trim());

  async function readFile(event: ChangeEvent<HTMLInputElement>) {
    const file = event.currentTarget.files?.[0];
    if (!file) return;
    setError("");
    if (file.size > 4 * 1024 * 1024) {
      setError("Transcript exceeds the 4 MB limit.");
      event.currentTarget.value = "";
      return;
    }
    setReading(true);
    try {
      setContent(await file.text());
      setFormat(/\.jsonl?$/i.test(file.name) ? "json" : "markdown");
    } catch {
      setError("Could not read the selected file.");
    } finally {
      setReading(false);
    }
  }

  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!ready || busy || reading) return;
    setBusy(true);
    setError("");
    const fields = new FormData(event.currentTarget);
    try {
      const response = await fetch("/api/v1/conversations", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          url: source === "link" ? url.trim() : undefined,
          content: source === "transcript" ? content : undefined,
          format,
          title: String(fields.get("title") || "").trim() || undefined,
          topic: String(fields.get("topic") || "").trim() || "Uncategorized",
          tags: String(fields.get("tags") || "")
            .split(",")
            .map((value) => value.trim())
            .filter(Boolean),
        }),
      });
      const result = await response.json();
      if (!response.ok) throw new Error(result.error || "Import failed.");
      router.push(`/conversations/${result.conversation.id}`);
      router.refresh();
    } catch (error) {
      setError(error instanceof Error ? error.message : "Import failed.");
    } finally {
      setBusy(false);
    }
  }
  return (
    <form className={styles.form} onSubmit={(event) => void submit(event)}>
      <h2>Import a conversation</h2>
      <fieldset className={styles.importFields} disabled={busy || reading}>
        <div
          className={styles.sourceSwitch}
          role="group"
          aria-label="Import source"
        >
          <button
            type="button"
            aria-pressed={source === "link"}
            onClick={() => {
              setSource("link");
              setError("");
            }}
          >
            Share link
          </button>
          <button
            type="button"
            aria-pressed={source === "transcript"}
            onClick={() => {
              setSource("transcript");
              setError("");
            }}
          >
            Paste or upload
          </button>
        </div>
        {source === "link" ? (
          <>
            <label>
              Public ChatGPT or Claude share link
              <input
                type="url"
                required
                maxLength={2000}
                value={url}
                onChange={(event) => setUrl(event.target.value)}
                placeholder="https://chatgpt.com/share/..."
              />
            </label>
            <p className={styles.hint}>
              Paste a public ChatGPT or Claude conversation link.
            </p>
          </>
        ) : (
          <>
            <label>
              Transcript format
              <select
                value={format}
                onChange={(event) => setFormat(event.target.value)}
              >
                <option value="markdown">Markdown or text</option>
                <option value="json">JSON messages</option>
              </select>
            </label>
            <label>
              Transcript file
              <input
                type="file"
                accept=".json,.jsonl,.md,.txt,.markdown"
                onChange={(event) => void readFile(event)}
              />
            </label>
            <label>
              Transcript
              <textarea
                value={content}
                required
                placeholder={"# User\nYour question\n\n# Assistant\nThe reply"}
                onChange={(event) => setContent(event.target.value)}
              />
            </label>
            <p className={styles.hint}>
              Upload a text, Markdown, or JSON file up to 4 MB, or paste the
              conversation above.
            </p>
          </>
        )}
        <details className={styles.metadata}>
          <summary>
            Title, topic, and tags <span>(optional)</span>
          </summary>
          <div className={styles.importFields}>
            <label>
              Title (optional)
              <input name="title" maxLength={200} />
            </label>
            <label>
              Topic
              <input name="topic" defaultValue="Uncategorized" maxLength={80} />
            </label>
            <label>
              Tags, separated by commas
              <input name="tags" />
            </label>
          </div>
        </details>
      </fieldset>
      <p className={styles.hint}>
        Only this profile can see imported conversations. Missing attachments
        are not imported.
      </p>
      {error && (
        <p className={styles.error} role="alert">
          {error}
        </p>
      )}
      <button
        type="submit"
        className={styles.primaryButton}
        disabled={!ready || busy || reading}
      >
        {busy
          ? "Importing…"
          : reading
            ? "Reading file…"
            : "Import conversation"}
      </button>
      <p className={styles.hint} role="status">
        {busy
          ? "Importing your conversation. This may take a moment."
          : reading
            ? "Reading your transcript."
            : !ready
              ? source === "link"
                ? "Add a share link to enable import."
                : "Paste a transcript or choose a file to enable import."
              : "Ready to import."}
      </p>
    </form>
  );
}

"use client";

import { useEffect, useRef, useState, type CSSProperties } from "react";
import { useRouter } from "next/navigation";
import cytoscape from "cytoscape";
import fcose from "cytoscape-fcose";
import styles from "./LibraryGraph.module.css";

/**
 * The library as a force-directed graph (Cytoscape + fcose). Papers, authors, topics, and tags are nodes;
 * clicking a paper opens it. Cytoscape renders to canvas and is styled via
 * its JS stylesheet API (accepted CSS-Modules deviation).
 */

cytoscape.use(fcose);

interface GraphNode {
  id: string;
  label: string;
  kind: "paper" | "author" | "topic" | "tag";
  href?: string;
}

interface GraphEdge {
  source: string;
  target: string;
  kind: string;
}

const KIND_COLORS: Record<GraphNode["kind"], string> = {
  paper: "#3f4fb0",
  author: "#1f8a5b",
  topic: "#c2730a",
  tag: "#b83280",
};

const EDGE_COLORS = {
  related: "#3f4fb0",
  cites: "#d0342c",
} as const;

const HIDDEN_CLASS = "hidden";

function swatch(color: string): CSSProperties {
  return { "--swatch": color } as CSSProperties;
}

/** Keep only paper nodes and directed citation edges while the filter is on. */
function applyCitationsOnly(cy: cytoscape.Core, on: boolean): void {
  cy.batch(() => {
    cy.elements().removeClass(HIDDEN_CLASS);
    if (!on) return;
    cy.nodes('[kind != "paper"]').addClass(HIDDEN_CLASS);
    cy.edges('[kind != "cites"]').addClass(HIDDEN_CLASS);
  });
}

export function LibraryGraph() {
  const router = useRouter();
  const containerRef = useRef<HTMLDivElement>(null);
  const cyRef = useRef<cytoscape.Core | null>(null);
  const [empty, setEmpty] = useState(false);
  const [citationsOnly, setCitationsOnly] = useState(false);
  // Mirrors state so the async load can apply a toggle made before data arrived.
  const citationsOnlyRef = useRef(false);

  useEffect(() => {
    let cy: cytoscape.Core | null = null;
    let cancelled = false;
    void (async () => {
      const res = await fetch("/api/v1/graph", { credentials: "include" });
      const data = (await res.json()) as {
        nodes?: GraphNode[];
        edges?: GraphEdge[];
      };
      if (cancelled || !containerRef.current) return;
      const nodes = data.nodes ?? [];
      if (nodes.length === 0) {
        setEmpty(true);
        return;
      }
      cy = cytoscape({
        container: containerRef.current,
        elements: [
          ...nodes.map((n, index) => {
            const angle = (index / Math.max(nodes.length, 1)) * Math.PI * 2;
            return {
              data: { id: n.id, label: n.label, kind: n.kind, href: n.href },
              position: {
                x: 400 + Math.cos(angle) * 220,
                y: 300 + Math.sin(angle) * 220,
              },
            };
          }),
          ...(data.edges ?? []).map((e, i) => ({
            data: {
              id: `e${i}`,
              source: e.source,
              target: e.target,
              kind: e.kind,
            },
          })),
        ],
        style: [
          {
            selector: "node",
            style: {
              label: "data(label)",
              "font-size": 9,
              color: "#565b68",
              "text-wrap": "ellipsis",
              "text-max-width": "120",
              "text-valign": "bottom",
              "text-margin-y": 4,
              width: 14,
              height: 14,
              "background-color": "#999",
            },
          },
          ...(Object.keys(KIND_COLORS) as GraphNode["kind"][]).map((kind) => ({
            selector: `node[kind = "${kind}"]`,
            style: { "background-color": KIND_COLORS[kind] },
          })),
          {
            selector: 'node[kind = "paper"]',
            style: { width: 26, height: 26, "font-size": 10 },
          },
          {
            selector: "edge",
            style: {
              width: 1,
              "line-color": "#c8c8c8",
              "curve-style": "haystack",
            },
          },
          {
            selector: 'edge[kind = "related"]',
            style: { "line-color": EDGE_COLORS.related, width: 2 },
          },
          {
            // Haystack edges cannot carry arrowheads; citations are directed.
            selector: 'edge[kind = "cites"]',
            style: {
              "line-color": EDGE_COLORS.cites,
              width: 2,
              "curve-style": "bezier",
              "target-arrow-shape": "triangle",
              "target-arrow-color": EDGE_COLORS.cites,
              "arrow-scale": 0.9,
            },
          },
          {
            selector: `.${HIDDEN_CLASS}`,
            style: { display: "none" },
          },
        ],
        layout: {
          name: "fcose",
          animate: false,
          randomize: false,
          nodeRepulsion: 6000,
          idealEdgeLength: 60,
        } as cytoscape.LayoutOptions,
      });
      cy.on("tap", "node", (event) => {
        const href = event.target.data("href") as string | undefined;
        if (href) router.push(href);
      });
      cyRef.current = cy;
      applyCitationsOnly(cy, citationsOnlyRef.current);
    })();
    return () => {
      cancelled = true;
      cyRef.current = null;
      cy?.destroy();
    };
  }, [router]);

  if (empty) {
    return (
      <p className={styles.empty}>
        The graph appears once the library has papers. Add one and come back.
      </p>
    );
  }
  return (
    <div className={styles.wrap}>
      <div ref={containerRef} className={styles.canvas} />
      <div className={styles.legend}>
        {(Object.keys(KIND_COLORS) as GraphNode["kind"][]).map((kind) => (
          <span key={kind} className={styles.legendItem}>
            <span className={styles.dot} style={swatch(KIND_COLORS[kind])} />
            {kind}
          </span>
        ))}
        <span className={styles.legendItem}>
          <span className={styles.line} style={swatch(EDGE_COLORS.related)} />
          related
        </span>
        <span className={styles.legendItem}>
          <span className={styles.arrow} style={swatch(EDGE_COLORS.cites)} />
          cites
        </span>
      </div>
      <label className={styles.filter}>
        <input
          type="checkbox"
          checked={citationsOnly}
          onChange={(event) => {
            const on = event.target.checked;
            citationsOnlyRef.current = on;
            setCitationsOnly(on);
            const cy = cyRef.current;
            if (cy) applyCitationsOnly(cy, on);
          }}
        />
        Citations only
      </label>
    </div>
  );
}

"use client";

import { useState } from "react";
import { captureInboxHref, startCapture, useCapture } from "./useCapture";
import styles from "./AddToLibraryButton.module.css";

/**
 * Shared "Add to library" affordance. Two entry points:
 *  - `url`: the work's link is already known (a chat sources card row) —
 *    hand it straight to the shared capture registry.
 *  - `resolveQuery`: only the bibliography entry text is known (a citation
 *    popover) — resolve it to a capturable URL server-side via
 *    /api/v1/citations/resolve first, then capture.
 * Capture progress lives in the module-level registry (`useCapture`), so
 * the outcome stays visible across remounts of whichever surface hosts it.
 */

type AddToLibraryButtonProps =
  | { url: string; resolveQuery?: undefined }
  | { url?: undefined; resolveQuery: string };

type ResolveState =
  | { status: "idle" }
  | { status: "resolving" }
  | { status: "notFound" }
  | { status: "failed"; error: string }
  | { status: "resolved"; url: string };

function CaptureAction({ url }: { url: string }) {
  const { state, start } = useCapture(url);
  if (state.status === "added") {
    return (
      <a className={styles.added} href={captureInboxHref(state.finalSlug)}>
        Added ✓ · review in Inbox
      </a>
    );
  }
  if (state.status === "adding") {
    return (
      <span className={styles.adding} role="status">
        <span className={styles.spinner} aria-hidden="true" />
        Adding…
      </span>
    );
  }
  return (
    <span className={styles.actionGroup}>
      <button type="button" className={styles.addBtn} onClick={start}>
        {state.status === "failed" ? "Retry" : "+ Add to library"}
      </button>
      {state.status === "failed" && (
        <span className={styles.failed} role="alert" title={state.error}>
          Failed · {state.error}
        </span>
      )}
    </span>
  );
}

function ResolveAndCapture({ query }: { query: string }) {
  const [state, setState] = useState<ResolveState>({ status: "idle" });

  async function resolveAndCapture(): Promise<void> {
    // The resolve API requires 12-400 chars.
    if (query.length < 12) {
      setState({ status: "notFound" });
      return;
    }
    setState({ status: "resolving" });
    try {
      const response = await fetch(
        `/api/v1/citations/resolve?q=${encodeURIComponent(query.slice(0, 400))}`,
        { credentials: "same-origin" },
      );
      if (!response.ok) {
        setState({
          status: "failed",
          error:
            response.status === 429
              ? "too many lookups, try again later"
              : `lookup failed (${response.status})`,
        });
        return;
      }
      const data = (await response.json()) as { url: string | null };
      if (!data.url) {
        setState({ status: "notFound" });
        return;
      }
      await startCapture(data.url);
      setState({ status: "resolved", url: data.url });
    } catch {
      setState({ status: "failed", error: "lookup failed" });
    }
  }

  if (state.status === "resolved") return <CaptureAction url={state.url} />;
  if (state.status === "resolving") {
    return (
      <span className={styles.stateText} role="status">
        Resolving…
      </span>
    );
  }
  if (state.status === "notFound") {
    return (
      <span className={styles.stateText} role="status">
        Not found online
      </span>
    );
  }
  return (
    <span className={styles.actionGroup}>
      <button
        type="button"
        className={styles.addBtn}
        onClick={() => void resolveAndCapture()}
      >
        {state.status === "failed" ? "Retry" : "+ Add to library"}
      </button>
      {state.status === "failed" && (
        <span className={styles.failed} role="alert" title={state.error}>
          Failed · {state.error}
        </span>
      )}
    </span>
  );
}

export function AddToLibraryButton(props: AddToLibraryButtonProps) {
  if (props.url !== undefined) return <CaptureAction url={props.url} />;
  return <ResolveAndCapture query={props.resolveQuery} />;
}

import Link from "next/link";
import { profilePageFiles } from "@/lib/auth/platform/page-access";
import type { ProfileCapability } from "@/lib/auth/profile-capability";
import { LibraryNavigation } from "@/components/conversations/LibraryNavigation";
import { AddPaperBox } from "./AddPaperBox";
import { ReviewStrip } from "./ReviewStrip";
import { ViewToggle } from "./ViewToggle";
import {
  allIndexed,
  searchIndex,
  allTags,
  type IndexedPaper,
} from "@/lib/library/index-db";
import {
  isPaperVisibleToProfile,
  matchesLibraryFilters,
} from "@/lib/library/citations/filters";
import { listTopics, listInbox } from "@/lib/library/papers";
import { listCaptureJobs } from "@/lib/capture/jobs";
import { CaptureJobs, type CaptureJobView } from "./CaptureJobs";
import { InboxCardDelete } from "./InboxCardDelete";
import { LibraryCitationExport } from "./LibraryCitationExport";
import styles from "./LibraryView.module.css";

interface LibraryViewProps {
  query: string;
  activeTag: string | null;
  activeTopic: string | null;
  captureToken: string;
  capability: ProfileCapability;
}

function paperHref(paper: IndexedPaper): string {
  return paper.topic
    ? `/paper/${paper.topic}/${paper.slug}`
    : `/inbox/${paper.slug}`;
}

export function LibraryView({
  query,
  activeTag,
  activeTopic,
  captureToken,
  capability,
}: LibraryViewProps) {
  return profilePageFiles(capability, () => {
    const username = capability.username;
    const papers = searchIndex(query)
      .filter((paper) => isPaperVisibleToProfile(paper, username))
      .filter((paper) =>
        matchesLibraryFilters(paper, {
          tag: activeTag,
          topic: activeTopic,
        }),
      );
    const topics = listTopics();
    const tags = allTags(username);
    // "done" markers are handles for the /add status page, not jobs to show;
    // the finished paper appears as a normal inbox card.
    const captureJobs: CaptureJobView[] = listCaptureJobs(username).flatMap(
      (job) =>
        job.state === "done" || job.generation !== capability.generation
          ? []
          : [
              {
                slug: job.slug,
                state: job.state,
                sourceUrl: job.sourceUrl,
                startedAt: job.startedAt,
                error: job.error,
              },
            ],
    );
    const inboxCount =
      listInbox().filter((paper) => paper.meta.addedBy === username).length +
      captureJobs.length;
    const flagged = allIndexed()
      .filter((p) => p.needsReview && p.topic !== null)
      .map((p) => ({ slug: p.slug, topic: p.topic as string, title: p.title }));

    return (
      <div className={styles.root}>
        <aside className={styles.sidebar}>
          <LibraryNavigation sidebar />
          <nav aria-label="Topics">
            <h2 className={styles.sideTitle}>Topics</h2>
            <ul className={styles.sideList}>
              <li>
                <Link
                  className={
                    activeTopic === null ? styles.sideActive : styles.sideLink
                  }
                  href="/"
                  aria-current={activeTopic === null ? "page" : undefined}
                >
                  All papers
                </Link>
              </li>
              {topics.map((topic) => (
                <li key={topic}>
                  <Link
                    className={
                      activeTopic === topic
                        ? styles.sideActive
                        : styles.sideLink
                    }
                    href={`/?topic=${encodeURIComponent(topic)}`}
                    aria-current={activeTopic === topic ? "page" : undefined}
                  >
                    {topic}
                  </Link>
                </li>
              ))}
            </ul>
          </nav>
          {inboxCount > 0 && (
            <Link className={styles.inboxBadge} href="/?topic=_inbox">
              Inbox · {inboxCount} awaiting
            </Link>
          )}
          {tags.length > 0 && (
            <nav aria-label="Tags">
              <h2 className={styles.sideTitle}>Tags</h2>
              <div className={styles.tagCloud}>
                {tags.map((tag) => (
                  <Link
                    key={tag}
                    className={
                      activeTag === tag ? styles.tagActive : styles.tag
                    }
                    href={`/?tag=${encodeURIComponent(tag)}`}
                  >
                    {tag}
                  </Link>
                ))}
              </div>
            </nav>
          )}
        </aside>

        <section className={styles.main}>
          <ViewToggle active="library" />
          <ReviewStrip flagged={flagged} topics={topics} />
          <AddPaperBox captureToken={captureToken} />
          <LibraryCitationExport
            query={query}
            tag={activeTag}
            topic={activeTopic}
          />
          <form className={styles.searchRow} action="/" method="get">
            <input
              className={styles.search}
              type="search"
              name="q"
              defaultValue={query}
              placeholder="Search titles, authors, tags, full text…"
              aria-label="Search the library"
            />
          </form>

          {activeTopic === "_inbox" && <CaptureJobs jobs={captureJobs} />}
          {papers.length === 0 ? (
            activeTopic === "_inbox" && captureJobs.length > 0 ? null : (
              <p className={styles.empty}>
                {query
                  ? "Nothing matches that search."
                  : "No papers yet. Paste a link above to add your first."}
              </p>
            )
          ) : (
            <ul className={styles.grid}>
              {papers.map((paper) => (
                <li key={paper.slug} className={styles.card}>
                  <Link className={styles.cardLink} href={paperHref(paper)}>
                    <h3 className={styles.cardTitle}>{paper.title}</h3>
                    <p className={styles.cardMeta}>
                      {paper.authors}
                      {paper.year ? ` · ${paper.year}` : ""}
                    </p>
                    {paper.summarySnippet && (
                      <p className={styles.cardSnippet}>
                        {paper.summarySnippet}
                      </p>
                    )}
                    <p className={styles.cardTags}>
                      {paper.topic === null && (
                        <span className={styles.cardInbox}>inbox</span>
                      )}
                      {paper.tags.map((tag) => (
                        <span key={tag} className={styles.cardTag}>
                          {tag}
                        </span>
                      ))}
                    </p>
                  </Link>
                  {paper.topic === null && (
                    <InboxCardDelete slug={paper.slug} title={paper.title} />
                  )}
                </li>
              ))}
            </ul>
          )}
        </section>
      </div>
    );
  });
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import styles from "./ReviewStrip.module.css";

/**
 * Papers a sync auto-filed that await a human glance: keep the AI's topic or
 * re-file into another one. Disappears once nothing is flagged.
 */

interface FlaggedPaper {
  slug: string;
  topic: string;
  title: string;
}

interface ReviewStripProps {
  flagged: FlaggedPaper[];
  topics: string[];
}

export function ReviewStrip({ flagged, topics }: ReviewStripProps) {
  const router = useRouter();
  const [busySlug, setBusySlug] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  if (flagged.length === 0) return null;

  async function review(paper: FlaggedPaper, moveTo?: string): Promise<void> {
    setBusySlug(paper.slug);
    setError(null);
    const res = await fetch("/api/v1/papers/review", {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      credentials: "include",
      body: JSON.stringify({ topic: paper.topic, slug: paper.slug, moveTo }),
    });
    setBusySlug(null);
    if (!res.ok) {
      const data = (await res.json().catch(() => null)) as {
        error?: string;
      } | null;
      setError(data?.error ?? "Could not update the paper.");
      return;
    }
    router.refresh();
  }

  return (
    <section className={styles.root} aria-label="Synced papers to review">
      <h2 className={styles.title}>
        Synced from Zotero · {flagged.length} to review
      </h2>
      <ul className={styles.list}>
        {flagged.map((paper) => (
          <li key={paper.slug} className={styles.row}>
            <span className={styles.name}>
              {paper.title}
              <span className={styles.topic}> → {paper.topic}</span>
            </span>
            <span className={styles.actions}>
              <button
                type="button"
                className={styles.keep}
                onClick={() => void review(paper)}
                disabled={busySlug === paper.slug}
              >
                Keep
              </button>
              <select
                className={styles.select}
                aria-label={`Re-file ${paper.title}`}
                value=""
                onChange={(e) => {
                  if (e.target.value) void review(paper, e.target.value);
                }}
                disabled={busySlug === paper.slug}
              >
                <option value="">Re-file to…</option>
                {topics
                  .filter((t) => t !== paper.topic)
                  .map((t) => (
                    <option key={t} value={t}>
                      {t}
                    </option>
                  ))}
              </select>
            </span>
          </li>
        ))}
      </ul>
      {error && <p className={styles.error}>{error}</p>}
    </section>
  );
}

"use client";

import { useEffect, useId, useState } from "react";
import { CircleCheck, Download, RefreshCw } from "lucide-react";
import { downloadOffline } from "@/lib/offline/download";
import {
  listOffline,
  offlineError,
  subscribeOffline,
} from "@/lib/offline/storage";
import styles from "./Offline.module.css";

async function ensureOfflineReader(): Promise<void> {
  if (!("serviceWorker" in navigator) || !window.isSecureContext)
    throw new Error(
      "Offline reading requires HTTPS or localhost and a browser with service worker support.",
    );
  await navigator.serviceWorker.register("/sw.js", { updateViaCache: "none" });
  const registration = await new Promise<ServiceWorkerRegistration>(
    (resolve, reject) => {
      const timer = setTimeout(
        () =>
          reject(
            new Error(
              "Offline reader installation timed out. Check your connection and try again.",
            ),
          ),
        90_000,
      );
      navigator.serviceWorker.ready.then(
        (ready) => {
          clearTimeout(timer);
          resolve(ready);
        },
        (error) => {
          clearTimeout(timer);
          reject(error);
        },
      );
    },
  );
  await new Promise<void>((resolve, reject) => {
    const channel = new MessageChannel();
    const timer = setTimeout(() => {
      channel.port1.close();
      reject(
        new Error("The offline reader is not ready. Reload and try again."),
      );
    }, 10_000);
    channel.port1.onmessage = (event) => {
      clearTimeout(timer);
      channel.port1.close();
      if (event.data?.ready) resolve();
      else reject(new Error("The offline reader is not completely installed."));
    };
    registration.active?.postMessage({ type: "OFFLINE_READY" }, [
      channel.port2,
    ]);
  });
}

export function DownloadButton({ snapshotUrl }: { snapshotUrl: string }) {
  const descriptionId = useId();
  const [saved, setSaved] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  useEffect(() => {
    let active = true;
    const refresh = () => {
      void listOffline()
        .then((items) => {
          if (active)
            setSaved(
              items.some((item) => item.manifest.snapshotUrl === snapshotUrl),
            );
        })
        .catch(() => {});
    };
    refresh();
    const unsubscribe = subscribeOffline(refresh);
    return () => {
      active = false;
      unsubscribe();
    };
  }, [snapshotUrl]);
  async function download() {
    setBusy(true);
    setError(null);
    try {
      await ensureOfflineReader();
      await navigator.storage?.persist?.();
      await downloadOffline(snapshotUrl);
      setSaved(true);
    } catch (cause) {
      setError(offlineError(cause));
    } finally {
      setBusy(false);
    }
  }
  return (
    <div className={styles.download} data-saved={saved}>
      <div className={styles.downloadDescription} hidden={!saved}>
        <p id={descriptionId} role="status">
          {saved && (
            <>
              <CircleCheck aria-hidden="true" />
              Saved on this device
            </>
          )}
        </p>
      </div>
      <button
        type="button"
        disabled={busy}
        aria-describedby={saved ? descriptionId : undefined}
        onClick={() => void download()}
      >
        {saved ? (
          <RefreshCw aria-hidden="true" />
        ) : (
          <Download aria-hidden="true" />
        )}
        {busy
          ? saved
            ? "Updating…"
            : "Saving…"
          : saved
            ? "Update copy"
            : "Save for offline"}
      </button>
      {saved && <a href="/offline/index.html">Open downloads</a>}
      {error && <p role="alert">{error}</p>}
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { downloadOffline, formatBytes } from "@/lib/offline/download";
import {
  listOffline,
  offlineError,
  removeOffline,
  subscribeOffline,
} from "@/lib/offline/storage";
import type { OfflineRecord } from "@/lib/offline/types";
import styles from "./Offline.module.css";

export function OfflineStorage() {
  const [items, setItems] = useState<OfflineRecord[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  useEffect(() => {
    let active = true;
    const refresh = () => {
      void listOffline()
        .then((value) => {
          if (active) setItems(value);
        })
        .catch((cause) => {
          if (active) setError(offlineError(cause));
        });
    };
    refresh();
    const unsubscribe = subscribeOffline(refresh);
    return () => {
      active = false;
      unsubscribe();
    };
  }, []);
  async function act(action: () => Promise<unknown>) {
    setBusy(true);
    setError(null);
    try {
      await action();
      setItems(await listOffline());
    } catch (cause) {
      setError(offlineError(cause));
    } finally {
      setBusy(false);
    }
  }
  return (
    <section className={styles.storage} id="offline-storage">
      <h2>Offline storage</h2>
      <p>
        {items.length} downloads ·{" "}
        {formatBytes(items.reduce((sum, item) => sum + item.bytes, 0))}
      </p>
      <p>
        Saved in this browser on this device. Removing downloads leaves your
        server library intact. Switching profiles or logging out clears private
        downloads. Your browser may reclaim storage; export PDF or HTML to keep
        independent files.
      </p>
      <a href="/offline/index.html">Open downloaded library</a>
      {error && <p role="alert">{error}</p>}
      <ul>
        {items.map((item) => (
          <li key={item.manifest.key}>
            <div>
              <a
                href={`/offline/index.html?key=${encodeURIComponent(item.manifest.key)}`}
              >
                {item.manifest.title}
              </a>
              <p>
                {item.manifest.kind === "paper" ? "Paper" : "Conversation"} ·{" "}
                {item.manifest.topic} · {formatBytes(item.bytes)}
              </p>
              <p>Saved {new Date(item.downloadedAt).toLocaleString()}</p>
            </div>
            <div className={styles.actions}>
              <button
                type="button"
                disabled={busy}
                onClick={() =>
                  void act(() => downloadOffline(item.manifest.snapshotUrl))
                }
              >
                Update
              </button>
              <button
                type="button"
                disabled={busy}
                onClick={() => void act(() => removeOffline(item.manifest.key))}
              >
                Remove
              </button>
            </div>
          </li>
        ))}
      </ul>
      <button
        type="button"
        disabled={busy || !items.length}
        onClick={() => {
          if (
            window.confirm(
              "Remove all downloads from this device? Server documents will remain.",
            )
          )
            void act(() => removeOffline());
        }}
      >
        Clear all downloads
      </button>
    </section>
  );
}

