"use client";

import {
  useCallback,
  useEffect,
  useRef,
  useState,
  type RefObject,
} from "react";
import { MessageSquare } from "lucide-react";
import type { PDFDocumentProxy } from "pdfjs-dist";
import type { PDFViewer } from "pdfjs-dist/web/pdf_viewer.mjs";
import type { PdfAutosaveCoordinator } from "@/lib/pdf/autosave";
import type { PdfEditGate } from "@/lib/pdf/reader/edit-gate";
import styles from "./PdfReader.module.css";
import {
  projectedComment,
  type PdfCommentProjection,
} from "@/lib/pdf/reader/comment-card";
import { PdfCommentCard, type CommentDraft } from "./comments/PdfCommentCard";
import { useCommentPosition } from "./comments/useCommentPosition";

interface ViewerComment {
  id: string;
  subtype?: string;
  contentsObj?: { str?: string };
  titleObj?: { str?: string };
  richText?: { str?: string };
}

function isCommentBlocked(editGate: RefObject<PdfEditGate>): boolean {
  return Boolean(
    editGate.current.notesInFlight || editGate.current.reloadingDocument,
  );
}

export function PdfComments({
  src,
  pdfDocument,
  viewer,
  stage,
  etag,
  autosave,
  refresh,
  onEnable,
  onDraftChange,
  editGate,
  commentDirtyRef,
  onBlocked,
  enabled,
  setEnabled,
  disabled,
  appearance,
  hideTrigger = false,
  controlled = false,
  onAskSelection,
}: {
  src: string;
  pdfDocument: PDFDocumentProxy | null;
  viewer: RefObject<PDFViewer | null>;
  stage: RefObject<HTMLDivElement | null>;
  etag: RefObject<string | null>;
  autosave: RefObject<PdfAutosaveCoordinator | null>;
  refresh(): void;
  onEnable(): void;
  onDraftChange(active: boolean): void;
  editGate: RefObject<PdfEditGate>;
  commentDirtyRef: RefObject<boolean>;
  onBlocked(): void;
  enabled: boolean;
  setEnabled(enabled: boolean): void;
  disabled: boolean;
  appearance: "theme" | "light" | "dark";
  hideTrigger?: boolean;
  controlled?: boolean;
  onAskSelection?(selection: { page: number; quote: string }): void;
}) {
  const [draft, setDraft] = useState<CommentDraft | null>(null);
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);
  const [discardPrompt, setDiscardPrompt] = useState(false);
  const [placementError, setPlacementError] = useState("");
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const dialogRef = useRef<HTMLDivElement>(null);
  const commentButtonRef = useRef<HTMLButtonElement>(null);
  const restoreFocusRef = useRef(false);
  const opening = useRef(0);
  const projection = useRef<{
    document: PDFDocumentProxy;
    etag: string | null;
    comments: PdfCommentProjection[];
  } | null>(null);
  const dialogOpen = draft !== null;
  const callbacks = useRef({ onEnable, onBlocked, onDraftChange });
  useEffect(() => {
    callbacks.current = { onEnable, onBlocked, onDraftChange };
  }, [onEnable, onBlocked, onDraftChange]);
  const position = useCommentPosition(draft, stage, viewer);
  const positioned = position !== null;

  function rememberFocus() {
    restoreFocusRef.current =
      document.activeElement === document.body ||
      Boolean(dialogRef.current?.contains(document.activeElement));
  }

  useEffect(() => {
    if (dialogOpen || disabled || !restoreFocusRef.current) return;
    restoreFocusRef.current = false;
    if (hideTrigger) stage.current?.focus();
    else commentButtonRef.current?.focus();
  }, [dialogOpen, disabled, hideTrigger, stage]);

  const openDraft = useCallback(
    (next: CommentDraft) => {
      if (isCommentBlocked(editGate)) {
        callbacks.current.onBlocked();
        return;
      }
      commentDirtyRef.current = false;
      setError("");
      setPlacementError("");
      setDiscardPrompt(false);
      callbacks.current.onDraftChange(next.mode !== "view");
      setDraft(next);
    },
    [commentDirtyRef, editGate],
  );

  function placeOnVisiblePage() {
    const currentViewer = viewer.current;
    const stageElement = stage.current;
    if (!currentViewer || !stageElement) return;
    const page = currentViewer.currentPageNumber;
    const pageElement = stageElement.querySelector<HTMLElement>(
      `.page[data-page-number="${page}"]`,
    );
    const pageView = currentViewer.getPageView(page - 1);
    if (!pageElement || !pageView) {
      setPlacementError("请先滚动到要添加评论的页面。");
      return;
    }
    const pageRect = pageElement.getBoundingClientRect();
    const stageRect = stageElement.getBoundingClientRect();
    const visual = window.visualViewport;
    const left = Math.max(
      pageRect.left,
      stageRect.left,
      visual?.offsetLeft ?? 0,
    );
    const top = Math.max(pageRect.top, stageRect.top, visual?.offsetTop ?? 0);
    const right = Math.min(
      pageRect.right,
      stageRect.right,
      (visual?.offsetLeft ?? 0) + (visual?.width ?? window.innerWidth),
    );
    const bottom = Math.min(
      pageRect.bottom,
      stageRect.bottom,
      (visual?.offsetTop ?? 0) + (visual?.height ?? window.innerHeight),
    );
    if (left >= right || top >= bottom) {
      setPlacementError("请先滚动到要添加评论的页面。");
      return;
    }
    const [x, y] = pageView.viewport.convertToPdfPoint(
      (left + right) / 2 - pageRect.left,
      (top + bottom) / 2 - pageRect.top,
    );
    openDraft({ page, x, y, text: "", initialText: "" });
  }

  useEffect(() => {
    if (!dialogOpen) return;
    if (draft?.mode === "view") dialogRef.current?.focus();
    else textareaRef.current?.focus();
    function onKeyDown(event: KeyboardEvent) {
      if (event.key !== "Escape") return;
      event.preventDefault();
      event.stopImmediatePropagation();
      if (busy) return;
      if (discardPrompt) {
        setDiscardPrompt(false);
        return;
      }
      if (commentDirtyRef.current) {
        setDiscardPrompt(true);
        return;
      }
      rememberFocus();
      commentDirtyRef.current = false;
      onDraftChange(false);
      setDraft(null);
    }
    window.addEventListener("keydown", onKeyDown, true);
    return () => window.removeEventListener("keydown", onKeyDown, true);
  }, [
    dialogOpen,
    positioned,
    busy,
    commentDirtyRef,
    onDraftChange,
    draft?.mode,
    discardPrompt,
  ]);

  useEffect(() => {
    if (draft?.mode !== "view") return;
    const outside = (event: PointerEvent) => {
      if (
        event.target instanceof Node &&
        !dialogRef.current?.contains(event.target)
      ) {
        opening.current++;
        setDraft(null);
      }
    };
    document.addEventListener("pointerdown", outside, true);
    return () => document.removeEventListener("pointerdown", outside, true);
  }, [draft?.mode]);

  useEffect(() => {
    let disposed = false;
    const selector = controlled
      ? '.annotationLayer section[data-annotation-id]:is([aria-haspopup="dialog"],.textAnnotation,.highlightAnnotation):not(.popupAnnotation):not(.linkAnnotation):not(.widgetAnnotation)'
      : ".textAnnotation[data-annotation-id]";
    async function commentsForDocument(): Promise<PdfCommentProjection[]> {
      if (!controlled || !pdfDocument) return [];
      const baseline = etag.current;
      const cached = projection.current;
      if (cached?.document === pdfDocument && cached.etag === baseline)
        return cached.comments;
      try {
        const response = await fetch(src.replace(/\/pdf$/, "/comments"), {
          cache: "no-store",
        });
        if (!response.ok) return [];
        const result: { etag?: string; comments?: PdfCommentProjection[] } =
          await response.json();
        if (
          result.etag !== baseline ||
          etag.current !== baseline ||
          !Array.isArray(result.comments)
        )
          return [];
        projection.current = {
          document: pdfDocument,
          etag: baseline,
          comments: result.comments,
        };
        return result.comments;
      } catch {
        return [];
      }
    }
    async function place(event: MouseEvent) {
      if (disabled || !pdfDocument || (draft && draft.mode !== "view")) return;
      const target = event.target;
      if (!(target instanceof Element)) return;
      const marker = target.closest<HTMLElement>(selector);
      // Existing comments remain editable in normal selection mode.
      if (!enabled && !marker) return;
      const pageElement = target.closest<HTMLElement>(
        ".page[data-page-number]",
      );
      const page = Number(pageElement?.dataset.pageNumber);
      if (!pageElement || !page || !viewer.current) return;
      event.preventDefault();
      event.stopImmediatePropagation();
      const rect = pageElement.getBoundingClientRect();
      const viewport = viewer.current.getPageView(page - 1).viewport;
      const [x, y] = viewport.convertToPdfPoint(
        (event.detail === 0 && marker
          ? marker.getBoundingClientRect().left +
            marker.getBoundingClientRect().width / 2
          : event.clientX) - rect.left,
        (event.detail === 0 && marker
          ? marker.getBoundingClientRect().top +
            marker.getBoundingClientRect().height / 2
          : event.clientY) - rect.top,
      );
      if (marker?.dataset.annotationId) {
        const token = ++opening.current;
        const [annotations, comments]: [
          ViewerComment[],
          PdfCommentProjection[],
        ] = await Promise.all([
          pdfDocument.getPage(page).then((entry) => entry.getAnnotations()),
          commentsForDocument(),
        ]);
        const existing = annotations.find(
          (item: { id: string }) => item.id === marker.dataset.annotationId,
        );
        if (!existing || disposed || token !== opening.current) return;
        const group = projectedComment(comments, marker.dataset.annotationId);
        callbacks.current.onEnable();
        const text = group
          ? group.text
          : existing.contentsObj?.str || existing.richText?.str || "";
        openDraft({
          page,
          x,
          y,
          id: marker.dataset.annotationId,
          text,
          initialText: text,
          ...(controlled
            ? {
                mode: "view" as const,
                editable: group?.editable ?? false,
                author: group?.author ?? existing.titleObj?.str,
                quote: group?.quote,
                kind: group?.kind,
              }
            : {}),
        });
        return;
      }
      openDraft({ page, x, y, text: "", initialText: "" });
    }
    const element = stage.current;
    const click = (event: MouseEvent) => {
      void place(event).catch(() =>
        setPlacementError("暂时无法读取这条批注，请重试。"),
      );
    };
    const key = (event: KeyboardEvent) => {
      if (
        !controlled ||
        !["Enter", " "].includes(event.key) ||
        !(event.target instanceof HTMLElement)
      )
        return;
      const marker = event.target.closest<HTMLElement>(selector);
      if (!marker) return;
      event.preventDefault();
      event.stopImmediatePropagation();
      marker.click();
    };
    element?.addEventListener("click", click, true);
    element?.addEventListener("keydown", key, true);
    return () => {
      disposed = true;
      element?.removeEventListener("click", click, true);
      element?.removeEventListener("keydown", key, true);
    };
  }, [
    enabled,
    disabled,
    pdfDocument,
    draft,
    stage,
    viewer,
    openDraft,
    controlled,
    src,
    etag,
  ]);

  async function save(remove = false) {
    if (!draft || busy || draft.mode === "view" || draft.editable === false)
      return;
    setError("");
    setBusy(true);
    try {
      await autosave.current?.flush();
      const state = autosave.current?.state();
      if (state?.dirty || state?.saving || state?.error)
        throw new Error("请先保存已有批注，再编辑评论。");
      if (!etag.current)
        throw new Error("无法获取 PDF 版本，请重新打开论文后重试。");
      const body = draft.id
        ? remove
          ? { action: "delete", id: draft.id }
          : { action: "edit", id: draft.id, text: draft.text }
        : {
            action: "create",
            page: draft.page,
            x: draft.x,
            y: draft.y,
            text: draft.text,
          };
      const response = await fetch(src.replace(/\/pdf$/, "/comments"), {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "If-Match": etag.current,
        },
        body: JSON.stringify(body),
      });
      const result: { error?: string } = await response.json();
      if (!response.ok)
        throw new Error(result.error ?? "评论未保存，请稍后重试。");
      rememberFocus();
      commentDirtyRef.current = false;
      setDraft(null);
      setEnabled(false);
      refresh();
    } catch (cause) {
      setError(
        cause instanceof Error ? cause.message : "评论未保存，请稍后重试。",
      );
    } finally {
      setBusy(false);
    }
  }

  return (
    <>
      {!hideTrigger && (
        <button
          ref={commentButtonRef}
          className={`${styles.editorButton} ${enabled ? styles.activeTool : ""}`}
          type="button"
          disabled={busy || dialogOpen || disabled}
          aria-label="评论"
          title="评论"
          aria-pressed={enabled}
          onClick={() => {
            setPlacementError("");
            if (!enabled) onEnable();
            setEnabled(!enabled);
          }}
        >
          <MessageSquare aria-hidden="true" />
          <span>评论</span>
        </button>
      )}
      {enabled && !draft && (
        <button
          className={styles.keyboardPlace}
          type="button"
          disabled={disabled}
          onClick={placeOnVisiblePage}
        >
          在当前页添加评论
        </button>
      )}
      {placementError && <span role="status">{placementError}</span>}
      {draft && position && (
        <PdfCommentCard
          key={draft.id ?? "new-comment"}
          draft={draft}
          position={position}
          appearance={appearance}
          busy={busy}
          editDisabled={disabled}
          discardPrompt={discardPrompt}
          error={error}
          dialogRef={dialogRef}
          textareaRef={textareaRef}
          onText={(text) => {
            commentDirtyRef.current = text !== draft.initialText;
            setDraft({ ...draft, text });
          }}
          onEdit={() => {
            if (disabled || !draft.editable) return;
            openDraft({ ...draft, mode: "edit" });
          }}
          onSave={(remove) => void save(remove)}
          onAsk={
            onAskSelection && draft.quote?.trim()
              ? () => {
                  if (busy || draft.mode !== "view" || !draft.quote?.trim())
                    return;
                  restoreFocusRef.current = false;
                  commentDirtyRef.current = false;
                  setDraft(null);
                  setEnabled(false);
                  onDraftChange(false);
                  onAskSelection({ page: draft.page, quote: draft.quote });
                }
              : undefined
          }
          onContinueEditing={() => setDiscardPrompt(false)}
          onDiscard={() => {
            if (busy) return;
            rememberFocus();
            opening.current++;
            commentDirtyRef.current = false;
            setDiscardPrompt(false);
            onDraftChange(false);
            setDraft(null);
          }}
          onClose={() => {
            if (busy) return;
            if (commentDirtyRef.current) {
              setDiscardPrompt(true);
              return;
            }
            rememberFocus();
            opening.current++;
            commentDirtyRef.current = false;
            onDraftChange(false);
            setDraft(null);
          }}
        />
      )}
    </>
  );
}

"use client";

import {
  Check,
  LoaderCircle,
  Maximize2,
  MessageSquare,
  Minimize2,
  MousePointer2,
  Save,
  X,
} from "lucide-react";
import {
  useEffect,
  useCallback,
  useRef,
  useState,
  type CSSProperties,
  type PointerEvent,
} from "react";
import type { PDFDocumentProxy } from "pdfjs-dist";
import type { ResolvedPdfDestination } from "@/lib/pdf/destinations";
import { resolvePdfDocumentTitle } from "@/lib/pdf/title";
import { originalPdfUrl } from "@/lib/pdf/reader/source-link";
import type { PdfEditGate } from "@/lib/pdf/reader/edit-gate";
import { usePdfVersionPoll } from "./usePdfVersionPoll";
import "pdfjs-dist/web/pdf_viewer.css";
import styles from "./PdfReader.module.css";
import { ReferencePreview, type Preview } from "./ReferencePreview";
import { PREVIEW_GAP, placePreview } from "./placePreview";
import {
  BIBLIOGRAPHY_EVENT,
  requestChatPrompt,
} from "@/lib/chat/paper-ref-events";
import { selectionPrompt } from "./selection/selectionAsk";
import { useTextSelectionAsk } from "./selection/useTextSelectionAsk";
import { useCitationHotspots } from "./useCitationHotspots";
import { usePaperRefBridge } from "./usePaperRefBridge";
import {
  usePdfDocument,
  type EditMode,
  type PdfReaderEditState,
} from "./usePdfDocument";
import { useMarginNotes } from "./notes/useMarginNotes";
import { PdfComments } from "./PdfComments";
import { usePinchZoom } from "./usePinchZoom";
import { useSaveOnLeave } from "./useSaveOnLeave";
import { PdfMoreTools } from "./controls/PdfMoreTools";
import { EditorButton, NativeEditorTools } from "./controls/PdfEditorTools";
import {
  DocumentAppearanceSelect,
  useDocumentAppearance,
} from "@/components/chat/DocumentAppearance";

export type { PdfReaderEditState } from "./usePdfDocument";

/**
 * The bibliography route reads at most 1MB of body; keep the cache PUT
 * under that with headroom so it is never silently rejected.
 */
const BIBLIOGRAPHY_PUT_MAX_BYTES = 900 * 1024;

interface PdfReaderProps {
  src: string;
  title: string;
  /** Where "open original" points when src is a proxy URL (viewer mode). */
  originalHref?: string;
  /** Keep the study workspace controls in one compact, scrollable row. */
  compactToolbar?: boolean;
  editable?: boolean;
  onClose?(): void;
  onEditStateChange?(state: PdfReaderEditState): void;
  /** Notify the host after comment or PDF annotation bytes have been saved. */
  onDocumentSaved?(): void;
  /** Use the workspace's source-linked comment flow for the visible page. */
  onQuickComment?(page: number): void;
  onPageChange?(page: number): void;
  onAskSelection?(selection: { page: number; quote: string }): void;
  /** Fired with the PDF's embedded Title metadata when it has one. */
  onDocumentTitle?(title: string): void;
  /** Let reference previews query the library (signed-in surfaces only). */
  libraryLookup?: boolean;
  /** Let reference previews hand prompts to a mounted chat composer. */
  chatPrompts?: boolean;
  /**
   * localStorage key that remembers the last page and zoom for this paper
   * (see `readingPositionKey`); omit to always open at the top.
   */
  positionKey?: string;
  /**
   * Session-authed per-profile position route
   * (`/api/v1/papers/<topic>/<slug>/position`); with it the last page and
   * zoom follow the reader across devices, newest copy winning. Only
   * signed-in surfaces (paper page, canvas annotator) pass this.
   */
  positionEndpoint?: string;
  /**
   * PUT the scanned bibliography here once per document open
   * (`/api/v1/papers/<topic>/<slug>/bibliography`), so readerless surfaces
   * (the canvas chat) and the library graph can use it. Only the paper page
   * passes this; viewer/share/canvas readers stay silent.
   */
  bibliographyEndpoint?: string;
}

export function PdfReader({
  src,
  title,
  originalHref,
  compactToolbar = false,
  editable = false,
  onClose,
  onEditStateChange,
  onDocumentSaved,
  onQuickComment,
  onPageChange,
  onAskSelection,
  onDocumentTitle,
  libraryLookup = false,
  chatPrompts = false,
  positionKey,
  positionEndpoint,
  bibliographyEndpoint,
}: PdfReaderProps) {
  const appearance = useDocumentAppearance();
  const readerRoot = useRef<HTMLDivElement>(null);
  const stageRef = useRef<HTMLDivElement>(null);
  const referenceAnchorRef = useRef<Pick<Preview, "horizontal" | "top"> | null>(
    null,
  );
  const onDocumentTitleRef = useRef(onDocumentTitle);
  const previewRef = useRef<Preview | null>(null);
  const hoverTimerRef = useRef<number | null>(null);
  const hoverLinkRef = useRef<HTMLAnchorElement | null>(null);
  // One PUT per loaded document: a reload (documentGeneration bump, new
  // src) yields a new proxy and re-publishes; re-renders never re-PUT.
  const bibliographyPutRef = useRef<PDFDocumentProxy | null>(null);
  const [preview, setPreview] = useState<Preview | null>(null);
  const [fullscreen, setFullscreen] = useState(false);
  const [commentDraftActive, setCommentDraftActive] = useState(false);
  const [commentEnabled, setCommentEnabled] = useState(false);
  const editGate = useRef<PdfEditGate>({
    commentActive: false,
    notesInFlight: 0,
    reloadingDocument: null,
  });
  const commentDirtyRef = useRef(false);
  const commentDraftRef = useRef(false);
  const nativeStateRef = useRef<PdfReaderEditState>({
    dirty: false,
    saving: false,
  });
  const hostEditRef = useRef(onEditStateChange);
  useEffect(() => {
    hostEditRef.current = onEditStateChange;
  }, [onEditStateChange]);
  const publishEditState = useCallback((state: PdfReaderEditState) => {
    nativeStateRef.current = state;
    hostEditRef.current?.({
      ...state,
      dirty: state.dirty || commentDraftRef.current,
    });
  }, []);
  const updateCommentDraft = useCallback(
    (active: boolean) => {
      editGate.current.commentActive = active;
      commentDraftRef.current = active;
      setCommentDraftActive(active);
      publishEditState(nativeStateRef.current);
    },
    [publishEditState],
  );
  const {
    containerRef,
    viewerRef,
    pdfViewerRef,
    etagRef,
    editorTypesRef,
    autosaveRef,
    commitAnnotations,
    uiManagerRef,
    pendingPenRef,
    dirtyRef,
    savingRef,
    restoreViewRef,
    noteUserMove,
    hoverPreviewRequestedRef,
    bibliographyRef,
    pdfDocument,
    viewerBus,
    pageNumber,
    pageCount,
    status,
    zoom,
    editMode,
    setEditMode,
    editorReady,
    dirty,
    saving,
    saveStatus,
    setSaveStatus,
    remoteUpdate,
    pencilMode,
    setPencilMode,
    setDocumentGeneration,
  } = usePdfDocument({
    src,
    editable,
    appearance,
    positionKey,
    positionEndpoint,
    onEditStateChange: publishEditState,
    onDocumentSaved,
    onHoverPreview: (target) => showReferencePreview(target, null, null),
  });

  useEffect(() => {
    if (pageCount > 0 && !status) onPageChange?.(pageNumber);
  }, [pageNumber, pageCount, status, onPageChange]);

  useEffect(() => {
    onDocumentTitleRef.current = onDocumentTitle;
  }, [onDocumentTitle]);

  // Separate from the load effect so any resolution failure is isolated and
  // loud instead of vanishing inside the loader's error handling.
  useEffect(() => {
    if (!pdfDocument || !onDocumentTitleRef.current) return;
    let cancelled = false;
    resolvePdfDocumentTitle(pdfDocument)
      .then((resolved) => {
        if (!cancelled && resolved) onDocumentTitleRef.current?.(resolved);
      })
      .catch((error: unknown) => {
        console.error("papernook: document title resolution failed", error);
      });
    return () => {
      cancelled = true;
    };
  }, [pdfDocument]);

  useSaveOnLeave(
    editable,
    dirtyRef,
    autosaveRef,
    commentDirtyRef,
    commitAnnotations,
  );

  useEffect(() => {
    const gate = editGate.current;
    if (
      !gate.reloadingDocument ||
      !pdfDocument ||
      gate.reloadingDocument === pdfDocument
    )
      return;
    gate.reloadingDocument = null;
    updateCommentDraft(false);
  }, [pdfDocument, updateCommentDraft]);

  useMarginNotes({
    pdfDocument,
    editable,
    pdfViewerRef,
    uiManagerRef,
    autosaveRef,
    restoreViewRef,
    remoteUpdate,
    editGate,
    setEditMode,
    setSaveStatus,
    setDocumentGeneration,
  });

  usePinchZoom(stageRef, pdfViewerRef, pencilMode, commentEnabled);

  // Read-only readers have no edit mode, yet their text layer is just as
  // selectable; only the ink/highlight tools of an editable reader hide it.
  const { selection, clear: clearSelectionAsk } = useTextSelectionAsk(
    stageRef,
    chatPrompts && (!editable || editMode === "select"),
  );

  function askAboutSelection(): void {
    if (!selection) return;
    requestChatPrompt(selectionPrompt(selection.text, selection.page));
    window.getSelection()?.removeAllRanges();
    clearSelectionAsk();
  }

  usePdfVersionPoll({
    enabled: editable && !!pdfDocument && !remoteUpdate && !commentDraftActive,
    src,
    etagRef,
    savingRef,
    dirtyRef,
    onRemoteUpdate: () => {
      // Nothing unsaved here, so another session's annotations can be
      // picked up silently: remount the document at the same page and
      // zoom instead of interrupting with a reload banner.
      const viewer = pdfViewerRef.current;
      if (viewer) {
        restoreViewRef.current = {
          page: viewer.currentPageNumber,
          scale: viewer.currentScale,
        };
      }
      setEditMode("select");
      setSaveStatus("已载入其他会话保存的批注。");
      setDocumentGeneration((generation) => generation + 1);
    },
  });

  function chooseEditMode(nextMode: EditMode): void {
    setCommentEnabled(false);
    const viewer = pdfViewerRef.current;
    const editorTypes = editorTypesRef.current;
    if (!viewer || !editorTypes) return;
    cancelHoverPreview();
    const modes: Record<EditMode, number> = {
      select: editorTypes.NONE,
      highlight: editorTypes.HIGHLIGHT,
      text: editorTypes.FREETEXT,
      draw: editorTypes.INK,
    };
    viewer.annotationEditorMode = { mode: modes[nextMode] };
    setEditMode(nextMode);
    const saveError = autosaveRef.current?.state().error;
    if (!remoteUpdate)
      setSaveStatus(
        saveError
          ? "保存失败：" + saveError.message
          : dirtyRef.current
            ? "有未保存的修改"
            : nextMode === "select"
              ? ""
              : `${{ highlight: "高亮", text: "文本框", draw: "手写", select: "选择" }[nextMode]}工具已启用`,
      );
  }

  async function saveAnnotations(): Promise<void> {
    commitAnnotations();
    await autosaveRef.current?.flush();
  }

  const simpleTools = compactToolbar && !!onQuickComment;
  const saveFailed = saveStatus.startsWith("保存失败：");
  const saveLabel = remoteUpdate
    ? "版本冲突"
    : saving
      ? "正在保存"
      : commentDraftActive
        ? "评论待保存"
        : dirty
          ? saveFailed
            ? "重试"
            : "待保存"
          : editorReady
            ? "已保存"
            : "载入中";

  async function closeReader(): Promise<void> {
    commitAnnotations();
    if (dirtyRef.current) {
      await autosaveRef.current?.flush();
    }
    if (!dirtyRef.current && !savingRef.current) onClose?.();
  }

  function captureReferenceAnchor(event: PointerEvent<HTMLDivElement>): void {
    const target = event.target;
    if (!(target instanceof Element) || !target.closest("a")) return;
    referenceAnchorRef.current = placePreview(
      event,
      event.currentTarget.getBoundingClientRect(),
    );
  }

  function scheduleHoverPreview(event: PointerEvent<HTMLDivElement>): void {
    if (editable && editMode !== "select") return;
    if (event.pointerType !== "mouse") return;
    const target = event.target;
    const link = target instanceof Element ? target.closest("a") : null;
    // pdf.js marks GoTo annotations with data-internal-link on the section
    // wrapping the anchor; external links never carry it.
    if (!link || !link.closest("[data-internal-link]")) return;
    if (link === hoverLinkRef.current) return;
    cancelHoverPreview();
    hoverLinkRef.current = link as HTMLAnchorElement;
    const anchor = placePreview(
      event,
      event.currentTarget.getBoundingClientRect(),
    );
    hoverTimerRef.current = window.setTimeout(() => {
      referenceAnchorRef.current = anchor;
      const link = hoverLinkRef.current;
      if (!link) return;
      hoverPreviewRequestedRef.current = true;
      try {
        link.click();
      } finally {
        hoverPreviewRequestedRef.current = false;
      }
    }, 180);
  }

  function cancelHoverPreview(event?: PointerEvent<HTMLDivElement>): void {
    if (event) {
      const next = event.relatedTarget;
      if (
        next instanceof Element &&
        hoverLinkRef.current &&
        hoverLinkRef.current.contains(next)
      ) {
        return;
      }
    }
    if (hoverTimerRef.current !== null) {
      window.clearTimeout(hoverTimerRef.current);
      hoverTimerRef.current = null;
    }
    hoverLinkRef.current = null;
  }

  function enablePencilDrawing(event: PointerEvent<HTMLDivElement>): void {
    captureReferenceAnchor(event);
    if (commentEnabled) return;
    if (pencilMode && event.pointerType === "touch") {
      event.preventDefault();
      event.stopPropagation();
      return;
    }
    if (!editable || event.pointerType !== "pen") return;
    setPencilMode(true);
    if (editMode === "draw") {
      setSaveStatus("Pencil detected; touch reserved for pinch zoom");
      return;
    }
    const viewer = pdfViewerRef.current;
    const editorTypes = editorTypesRef.current;
    if (!viewer || !editorTypes || !editorReady) {
      pendingPenRef.current = true;
      return;
    }
    setCommentEnabled(false);
    viewer.annotationEditorMode = { mode: editorTypes.INK };
    setEditMode("draw");
    setSaveStatus(
      "Pencil detected; Draw enabled, touch reserved for pinch zoom",
    );
  }

  function reloadLatest(): void {
    if (
      dirtyRef.current &&
      !window.confirm(
        "Reloading will discard your unsaved browser annotations. Continue?",
      )
    ) {
      return;
    }
    window.location.reload();
  }

  function closePreview(): void {
    previewRef.current = null;
    setPreview(null);
  }

  function showReferencePreview(
    target: ResolvedPdfDestination,
    entryText: string | null,
    at: { clientX: number; clientY: number } | null,
    ref?: Preview["ref"],
  ): void {
    const container = containerRef.current;
    if (!container) return;
    const rect = container.getBoundingClientRect();
    // Prefer the trigger, then the captured pointer, then keyboard focus.
    let point = at;
    if (!point && !referenceAnchorRef.current) {
      const link =
        window.document.activeElement instanceof HTMLElement
          ? window.document.activeElement.closest("a")
          : null;
      const linkRect = link?.getBoundingClientRect();
      if (linkRect) {
        point = {
          clientX: linkRect.left + linkRect.width / 2,
          clientY: linkRect.top + linkRect.height / 2,
        };
      }
    }
    const anchor: Pick<Preview, "horizontal" | "top"> = point
      ? placePreview(point, rect)
      : (referenceAnchorRef.current ?? {
          horizontal: "right",
          top: PREVIEW_GAP,
        });
    const nextPreview = {
      destination: target,
      ...(entryText === null ? {} : { entryText }),
      ...(ref ? { ref } : {}),
      ...anchor,
    };
    previewRef.current = nextPreview;
    setPreview(nextPreview);
  }

  useCitationHotspots({
    pdfDocument,
    eventBus: viewerBus,
    enabled: !editable || editMode === "select",
    onCitation: (target) =>
      showReferencePreview(target.destination, target.entryText, target),
    onBibliography: (bibliography) => {
      bibliographyRef.current = bibliography;
      window.dispatchEvent(
        new CustomEvent(BIBLIOGRAPHY_EVENT, { detail: bibliography }),
      );
      if (
        !bibliographyEndpoint ||
        !pdfDocument ||
        bibliographyPutRef.current === pdfDocument
      ) {
        return;
      }
      bibliographyPutRef.current = pdfDocument;
      // Fire-and-forget cache write; the store schema bounds entry text
      // and entry count tighter than the in-memory scan. The serialized
      // body must also fit the route's bounded JSON reader (1MB) or the
      // PUT 400s silently, so trim trailing entries until it fits.
      let entries = bibliography.entries.slice(0, 2000).map((entry) => ({
        ...entry,
        text: entry.text.slice(0, 1000),
        surname: entry.surname?.slice(0, 200) ?? null,
      }));
      let body = JSON.stringify({ style: bibliography.style, entries });
      while (
        entries.length > 0 &&
        new TextEncoder().encode(body).length > BIBLIOGRAPHY_PUT_MAX_BYTES
      ) {
        entries = entries.slice(0, Math.floor(entries.length * 0.9));
        body = JSON.stringify({ style: bibliography.style, entries });
      }
      if (entries.length === 0) return;
      void fetch(bibliographyEndpoint, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body,
      }).catch(() => undefined);
    },
  });

  usePaperRefBridge({
    pdfDocument,
    enabled: !editable || editMode === "select",
    bibliography: () => bibliographyRef.current,
    onNavigate: (target) => {
      closePreview();
      pdfViewerRef.current?.scrollPageIntoView({
        pageNumber: target.pageNumber,
        ...(target.kind === "XYZ"
          ? {
              // Keep the reader's scale, matching ignoreDestinationZoom.
              destArray: [null, { name: "XYZ" }, target.left, target.top, null],
            }
          : {}),
      });
    },
    onPreview: (target, entryText, ref) => {
      // Chat events have no pointer position; use the chat-adjacent corner.
      const stage = stageRef.current?.getBoundingClientRect();
      showReferencePreview(
        target,
        entryText,
        stage ? { clientX: stage.right, clientY: stage.bottom } : null,
        ref ?? undefined,
      );
    },
  });

  useEffect(() => {
    if (!preview) return;
    const closeOnEscape = (event: KeyboardEvent) => {
      if (event.key === "Escape") closePreview();
    };
    // Outside clicks dismiss; another citation then opens its own preview.
    const closeOnOutsidePointer = (event: globalThis.PointerEvent) => {
      const target = event.target;
      if (
        target instanceof Element &&
        target.closest("[data-reference-preview]")
      )
        return;
      closePreview();
    };
    window.addEventListener("keydown", closeOnEscape);
    window.addEventListener("pointerdown", closeOnOutsidePointer);
    return () => {
      window.removeEventListener("keydown", closeOnEscape);
      window.removeEventListener("pointerdown", closeOnOutsidePointer);
    };
  }, [preview]);

  useEffect(() => {
    if (!fullscreen) return;
    const exitOnEscape = (event: KeyboardEvent) => {
      if (event.key === "Escape") setFullscreen(false);
    };
    window.addEventListener("keydown", exitOnEscape);
    return () => window.removeEventListener("keydown", exitOnEscape);
  }, [fullscreen]);

  return (
    <div
      ref={readerRoot}
      className={`${styles.root} ${saving ? styles.saving : ""} ${
        fullscreen ? styles.fullscreen : ""
      }`}
      aria-label={title}
      data-document-appearance={appearance}
      data-compact={compactToolbar ? "true" : undefined}
      data-simple-tools={simpleTools ? "true" : undefined}
      data-pdf-page={pageNumber}
      data-pdf-ready={pageCount > 0 && !status}
      data-controlled-comments={
        src.startsWith("/api/research/papers/") ? "true" : undefined
      }
      data-pdf-edit-mode={
        commentEnabled || commentDraftActive ? "comment" : editMode
      }
    >
      <div className={styles.toolbar}>
        <div className={styles.toolbarGroup}>
          <button
            type="button"
            onClick={() => {
              noteUserMove();
              pdfViewerRef.current?.previousPage();
            }}
            disabled={pageNumber <= 1}
            aria-label="上一页"
            title="上一页"
          >
            ←
          </button>
          <span
            className={styles.pageStatus}
            aria-label={`第 ${pageNumber} 页${pageCount > 0 ? `，共 ${pageCount} 页` : ""}`}
          >
            {compactToolbar
              ? `${pageNumber} / ${pageCount || "…"}`
              : `第 ${pageNumber} 页${pageCount > 0 ? ` / 共 ${pageCount} 页` : ""}`}
          </span>
          <button
            type="button"
            onClick={() => {
              noteUserMove();
              pdfViewerRef.current?.nextPage();
            }}
            disabled={pageCount === 0 || pageNumber >= pageCount}
            aria-label="下一页"
            title="下一页"
          >
            →
          </button>
        </div>
        {editable ? (
          <div className={styles.editorTools} aria-label="批注工具">
            <EditorButton
              label="选择"
              active={editMode === "select" && !commentEnabled}
              onClick={() => chooseEditMode("select")}
              disabled={!editorReady || commentDraftActive}
            >
              <MousePointer2 aria-hidden="true" />
            </EditorButton>
            {simpleTools ? (
              <>
                <EditorButton
                  label="写评论"
                  active={false}
                  disabled={
                    !editorReady ||
                    dirty ||
                    saving ||
                    remoteUpdate ||
                    commentDraftActive
                  }
                  onClick={() => {
                    chooseEditMode("select");
                    onQuickComment?.(
                      pdfViewerRef.current?.currentPageNumber ?? pageNumber,
                    );
                  }}
                >
                  <MessageSquare aria-hidden="true" />
                </EditorButton>
                <PdfMoreTools
                  container={readerRoot}
                  className={styles.moreToolsButton}
                  mode={editMode}
                  commentEnabled={commentEnabled}
                  disabled={
                    !editorReady || saving || remoteUpdate || commentDraftActive
                  }
                  commentDisabled={
                    !editorReady ||
                    dirty ||
                    saving ||
                    remoteUpdate ||
                    commentDraftActive
                  }
                  onMode={chooseEditMode}
                  onComment={() => {
                    chooseEditMode("select");
                    setCommentEnabled(true);
                  }}
                />
              </>
            ) : (
              <NativeEditorTools
                mode={editMode}
                disabled={!editorReady || commentDraftActive}
                onMode={chooseEditMode}
              />
            )}
            <PdfComments
              onAskSelection={onAskSelection}
              controlled={src.startsWith("/api/research/papers/")}
              hideTrigger={simpleTools}
              src={src}
              appearance={appearance}
              pdfDocument={pdfDocument}
              viewer={pdfViewerRef}
              stage={stageRef}
              etag={etagRef}
              autosave={autosaveRef}
              enabled={commentEnabled}
              setEnabled={setCommentEnabled}
              disabled={
                !editorReady || saving || remoteUpdate || commentDraftActive
              }
              onEnable={() => chooseEditMode("select")}
              editGate={editGate}
              commentDirtyRef={commentDirtyRef}
              onBlocked={() => setSaveStatus("请等待批注保存完成。")}
              onDraftChange={updateCommentDraft}
              refresh={() => {
                onDocumentSaved?.();
                editGate.current.reloadingDocument = pdfDocument;
                const viewer = pdfViewerRef.current;
                if (viewer)
                  restoreViewRef.current = {
                    page: viewer.currentPageNumber,
                    scale: viewer.currentScale,
                  };
                setDocumentGeneration((generation) => generation + 1);
              }}
            />
            <button
              className={styles.saveIndicator}
              type="button"
              onClick={() => void saveAnnotations()}
              disabled={
                !editorReady ||
                !dirty ||
                saving ||
                remoteUpdate ||
                commentDraftActive
              }
              aria-label={
                !saving && dirty
                  ? saveFailed
                    ? "重试保存 PDF 批注"
                    : "立即保存 PDF 批注"
                  : saveLabel
              }
              title={dirty ? "批注会自动保存，点击可立即保存" : saveLabel}
            >
              {saving || !editorReady ? (
                <LoaderCircle
                  aria-hidden="true"
                  className={styles.saveSpinner}
                />
              ) : dirty || commentDraftActive ? (
                <Save aria-hidden="true" />
              ) : (
                <Check aria-hidden="true" />
              )}
              <span aria-live="polite">{saveLabel}</span>
            </button>
          </div>
        ) : (
          <span className={styles.hint}>Paper view</span>
        )}
        <div className={styles.toolbarGroup}>
          <button
            type="button"
            onClick={() => {
              noteUserMove();
              pdfViewerRef.current?.decreaseScale();
            }}
            aria-label="缩小"
            title="缩小"
          >
            −
          </button>
          {compactToolbar ? (
            <button
              type="button"
              className={styles.zoom}
              title="适合当前宽度"
              aria-label="适合当前宽度"
              disabled={!pageCount}
              onClick={() => {
                noteUserMove();
                const viewer = pdfViewerRef.current;
                if (viewer) viewer.currentScaleValue = "page-width";
              }}
            >
              {zoom}%
            </button>
          ) : (
            <span className={styles.zoom}>{zoom}%</span>
          )}
          <button
            type="button"
            onClick={() => {
              noteUserMove();
              pdfViewerRef.current?.increaseScale();
            }}
            aria-label="放大"
            title="放大"
          >
            +
          </button>
          <button
            className={compactToolbar ? styles.secondaryAction : undefined}
            type="button"
            onClick={() => setFullscreen((current) => !current)}
            aria-label={fullscreen ? "退出全屏" : "全屏阅读"}
            aria-pressed={fullscreen}
            title={fullscreen ? "退出全屏" : "全屏阅读"}
          >
            {fullscreen ? (
              <Minimize2 aria-hidden="true" />
            ) : (
              <Maximize2 aria-hidden="true" />
            )}
            {compactToolbar && (
              <span className={styles.actionLabel}>
                {fullscreen ? "退出全屏" : "全屏"}
              </span>
            )}
          </button>
          <a
            className={styles.originalLink}
            href={originalPdfUrl(originalHref ?? src)}
            target="_blank"
            rel="noopener noreferrer"
            aria-label="在新标签页打开原 PDF"
            title="在新标签页打开原 PDF"
          >
            ↗
            {compactToolbar && (
              <span className={styles.actionLabel}>原 PDF</span>
            )}
          </a>
          <DocumentAppearanceSelect
            value={appearance}
            compact={compactToolbar}
          />
          {onClose && (
            <button
              type="button"
              onClick={() => void closeReader()}
              disabled={saving || remoteUpdate || commentDraftActive}
              aria-label={dirty ? "保存批注并关闭" : "关闭阅读器"}
              title={dirty ? "保存批注并关闭" : "关闭阅读器"}
            >
              <X aria-hidden="true" />
            </button>
          )}
        </div>
      </div>
      {editable &&
        saveStatus &&
        !remoteUpdate &&
        (!simpleTools || saveFailed) && (
          <div
            className={`${styles.saveStatus} ${dirty ? styles.unsaved : ""}`}
            role="status"
          >
            {saveStatus}
          </div>
        )}
      {editable && remoteUpdate && (
        <div className={styles.remoteUpdate} role="alert">
          <span>{saveStatus}</span>
          <button type="button" onClick={reloadLatest}>
            重新载入
          </button>
        </div>
      )}
      <div
        ref={stageRef}
        tabIndex={-1}
        inert={commentDraftActive}
        data-comment-placement={
          commentEnabled && !commentDraftActive ? "true" : undefined
        }
        className={`${styles.stage} ${pencilMode && !commentEnabled ? styles.pencilMode : ""}`}
        onPointerDownCapture={enablePencilDrawing}
        onPointerOver={scheduleHoverPreview}
        onPointerOut={cancelHoverPreview}
      >
        <div className={styles.container} ref={containerRef}>
          <div className="pdfViewer" ref={viewerRef} />
          {status && (
            <p className={styles.status} role="status">
              {status}
            </p>
          )}
        </div>
        {selection && (
          <button
            data-selection-ask
            className={styles.selectionAsk}
            style={
              {
                "--ask-top": `${selection.top}px`,
                "--ask-left": `${selection.left}px`,
              } as CSSProperties
            }
            type="button"
            // Cancelling pointerdown keeps the text selection alive until
            // click fires; a plain press would collapse it and unmount us.
            onPointerDown={(event) => event.preventDefault()}
            onClick={askAboutSelection}
          >
            询问选文
          </button>
        )}
        {preview && pdfDocument && (
          <ReferencePreview
            document={pdfDocument}
            preview={preview}
            libraryLookup={libraryLookup}
            chatPrompts={chatPrompts}
            onClose={closePreview}
          />
        )}
      </div>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState, type MouseEvent } from "react";
import type { PDFDocumentProxy, PageViewport, RenderTask } from "pdfjs-dist";
import type { ResolvedPdfDestination } from "@/lib/pdf/destinations";
import type { PdfTextChunk } from "@/lib/pdf/bibliography";
import type { PaperRefKind } from "@/lib/pdf/paper-refs";
import {
  locatorLinesAtPoint,
  referenceEntryAtPoint,
  referenceTextAtPoint,
  type ReferenceEntry,
} from "@/lib/pdf/reference-text";
import { pdfTextChunks, pdfTextItems } from "@/lib/pdf/text-items";
import { requestChatPrompt } from "@/lib/chat/paper-ref-events";
import {
  captureInboxHref,
  startCapture,
  useCapture,
} from "@/components/library/useCapture";
import styles from "./PdfReader.module.css";

export interface Preview {
  destination: ResolvedPdfDestination;
  /** Known entry text (text-recognized citations); link-annotation
   * citations derive it from the destination point instead. */
  entryText?: string;
  /** Set for in-paper locators ("Section 2", "Figure 3"): the preview frames
   * the heading or caption instead of a bibliography entry, and the
   * library/web-search affordances (bibliography-only) stay hidden. */
  ref?: { kind: PaperRefKind; label: string };
  horizontal: "left" | "right";
  /** Offset from the viewer's top edge, in px. */
  top: number;
}

interface ReferencePreviewProps {
  document: PDFDocumentProxy;
  preview: Preview;
  /**
   * Look the cited entry up in the library (session-authed API) — only
   * passed by signed-in surfaces, never the public share page.
   */
  libraryLookup?: boolean;
  /**
   * Offer "Ask": only where a ChatPanel with a live composer is mounted
   * (the paper page with an AI provider), so the prompt never goes nowhere.
   */
  chatPrompts?: boolean;
  onClose(): void;
}

interface LibraryMatch {
  topic: string;
  slug: string;
  title: string;
}

/** Preview canvas CSS box; the crop is rendered to exactly this aspect. */
const PREVIEW_WIDTH = 760;
const PREVIEW_HEIGHT = 285;
/** Fraction of the page width trimmed per side (past the text margins). */
const PREVIEW_MARGIN_TRIM = 0.055;
/** Locator kinds whose target is a wrapped caption rather than a heading. */
const MULTILINE_KINDS = new Set<PaperRefKind>(["figure", "table", "algorithm"]);

/** The chat prompt quotes at most this much of the cited entry. */
const ASK_ENTRY_CHARS = 160;

function locatorTitle(ref: NonNullable<Preview["ref"]>): string {
  return `${ref.kind.charAt(0).toUpperCase()}${ref.kind.slice(1)} ${ref.label}`;
}

/** The text under the destination point: the locator's heading/caption
 * lines for in-paper refs, the bibliography entry for citations. */
function targetAtDestination(
  chunks: PdfTextChunk[],
  destination: ResolvedPdfDestination,
  pageWidth: number,
  ref: Preview["ref"],
): ReferenceEntry | null {
  if (destination.left === null || destination.top === null) return null;
  const point = { x: destination.left + 15, y: destination.top - 6 };
  return ref
    ? locatorLinesAtPoint(chunks, point, pageWidth, {
        multiline: MULTILINE_KINDS.has(ref.kind),
      })
    : referenceEntryAtPoint(chunks, point, pageWidth);
}

/**
 * Rendered-page cache: references cluster on the same bibliography pages, so
 * re-hovering must not re-render the whole page (the slow step). Keyed by
 * document identity (WeakMap, so closing a PDF frees its pages) and
 * page@pixelRatio.
 */
const pageCanvasCache = new WeakMap<
  PDFDocumentProxy,
  Map<string, HTMLCanvasElement>
>();
const pageTextCache = new WeakMap<
  PDFDocumentProxy,
  Map<number, PdfTextChunk[]>
>();
/**
 * Resolved library matches per reference text: hotspot papers surface many
 * previews per session and the match API is rate-limited (120 per 10 min),
 * so never ask twice for the same entry.
 */
const libraryMatchCache = new WeakMap<
  PDFDocumentProxy,
  Map<string, LibraryMatch | null>
>();

interface CropMapping {
  viewport: PageViewport;
  sourceX: number;
  sourceY: number;
  pageWidth: number;
}

type ResolveState =
  | { status: "idle" }
  | { status: "resolving" }
  | { status: "notFound" }
  | { status: "failed"; error: string }
  | { status: "resolved"; url: string };

function hostOf(url: string): string {
  try {
    return new URL(url).host;
  } catch {
    return url;
  }
}

/** Capture progress for a resolved URL; the registry keeps it across
 * remounts. The host is shown throughout: the URL came from the PDF's own
 * bibliography text, so the reader should see where the capture goes. */
function CaptureProgress({ url }: { url: string }) {
  const { state, start } = useCapture(url);
  const host = hostOf(url);
  if (state.status === "added") {
    return (
      <a
        className={styles.previewLibrary}
        href={captureInboxHref(state.finalSlug)}
        title={url}
      >
        Added from {host} ✓ · review in Inbox
      </a>
    );
  }
  if (state.status === "failed") {
    return (
      <span className={styles.previewActionState} role="alert" title={url}>
        <span
          className={`${styles.previewActionText} ${styles.previewActionFailed}`}
          title={state.error}
        >
          Failed · {state.error}
        </span>
        <button type="button" className={styles.previewAction} onClick={start}>
          Retry
        </button>
      </span>
    );
  }
  return (
    <span className={styles.previewActionState} role="status" title={url}>
      Adding from {host}…
    </span>
  );
}

/**
 * "Add to library" for a cited work: resolve the entry to a URL server-side
 * (arXiv id, DOI, printed link, or an arXiv title search), then hand it to
 * the shared capture registry. Mounted with the destination as its key so
 * a new target starts over.
 */
function AddToLibrary({
  resolveEntry,
}: {
  resolveEntry: () => Promise<string | null>;
}) {
  const [state, setState] = useState<ResolveState>({ status: "idle" });

  async function resolveAndCapture(): Promise<void> {
    setState({ status: "resolving" });
    try {
      // Reading the entry can fail too (the PDF proxy is torn down when
      // the document reloads), so it belongs inside the same try.
      const entry = await resolveEntry();
      // The resolve API requires 12-400 chars.
      if (!entry || entry.length < 12) {
        setState({ status: "notFound" });
        return;
      }
      const response = await fetch(
        `/api/v1/citations/resolve?q=${encodeURIComponent(entry.slice(0, 400))}`,
        { credentials: "same-origin" },
      );
      if (!response.ok) {
        setState({
          status: "failed",
          error:
            response.status === 429
              ? "too many lookups, try again later"
              : `lookup failed (${response.status})`,
        });
        return;
      }
      const data = (await response.json()) as { url: string | null };
      if (!data.url) {
        setState({ status: "notFound" });
        return;
      }
      await startCapture(data.url);
      setState({ status: "resolved", url: data.url });
    } catch {
      setState({ status: "failed", error: "lookup failed" });
    }
  }

  if (state.status === "resolved") return <CaptureProgress url={state.url} />;
  if (state.status === "resolving") {
    return (
      <span className={styles.previewActionState} role="status">
        Resolving…
      </span>
    );
  }
  if (state.status === "notFound") {
    return (
      <span className={styles.previewActionState} role="status">
        Not found online
      </span>
    );
  }
  return (
    <span className={styles.previewActionState}>
      {state.status === "failed" && (
        <span
          className={`${styles.previewActionText} ${styles.previewActionFailed}`}
          role="alert"
          title={state.error}
        >
          Failed · {state.error}
        </span>
      )}
      <button
        type="button"
        className={styles.previewAction}
        onClick={() => void resolveAndCapture()}
      >
        {state.status === "failed" ? "Retry" : "+ Add to library"}
      </button>
    </span>
  );
}

async function pageTextChunks(
  document: PDFDocumentProxy,
  pageNumber: number,
): Promise<PdfTextChunk[]> {
  let cache = pageTextCache.get(document);
  if (!cache) {
    cache = new Map();
    pageTextCache.set(document, cache);
  }
  const cached = cache.get(pageNumber);
  if (cached) return cached;
  const page = await document.getPage(pageNumber);
  const chunks = pdfTextChunks(await pdfTextItems(page));
  cache.set(pageNumber, chunks);
  return chunks;
}

export function ReferencePreview({
  document,
  preview,
  libraryLookup = false,
  chatPrompts = false,
  onClose,
}: ReferencePreviewProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const mappingRef = useRef<CropMapping | null>(null);
  const [status, setStatus] = useState("Loading reference…");
  // Keyed by destination so a stale lookup never renders for a new target —
  // no reset-in-effect needed. Unset for the current key = lookup pending:
  // the header shows "Checking library…" instead of flashing AddToLibrary.
  const [libraryMatch, setLibraryMatch] = useState<{
    key: string;
    match: LibraryMatch | null;
  } | null>(null);
  const { destination, ref } = preview;
  const destinationKey = `${destination.pageNumber}:${destination.left}:${destination.top}`;
  const settledLookup =
    libraryMatch?.key === destinationKey ? libraryMatch : null;
  const currentMatch = settledLookup?.match ?? null;

  // Safari kills window.open issued after an await (outside the click's
  // gesture), so open the tab synchronously and point it at the search once
  // the reference text resolves.
  function searchViaPopup(resolve: () => Promise<string | null>): void {
    const popup = window.open("about:blank", "_blank");
    void resolve()
      .then((reference) => {
        if (!reference) {
          popup?.close();
          return;
        }
        const url = `https://www.google.com/search?q=${encodeURIComponent(reference)}`;
        if (popup) popup.location.href = url;
        else window.open(url, "_blank", "noopener,noreferrer");
      })
      .catch((error: unknown) => {
        popup?.close();
        console.error("papernook: reference search failed", error);
      });
  }

  // The cited entry's full text: known up front for text-recognized
  // citations; for link annotations, the entry under the GoTo destination
  // (which points at the entry's marker).
  async function resolveEntry(): Promise<string | null> {
    if (preview.entryText) return preview.entryText;
    const mapping = mappingRef.current;
    const { left, top } = destination;
    if (!mapping || left === null || top === null) return null;
    const chunks = await pageTextChunks(document, destination.pageNumber);
    return referenceTextAtPoint(
      chunks,
      { x: left + 15, y: top - 6 },
      mapping.pageWidth,
    );
  }

  function searchTargetReference(): void {
    searchViaPopup(async () => (await resolveEntry())?.slice(0, 300) ?? null);
  }

  // Hand the chat a prompt about the cited work and get out of its way.
  function askAboutReference(): void {
    void resolveEntry()
      .then((entry) => {
        const work = entry
          ? `“${entry.length > ASK_ENTRY_CHARS ? `${entry.slice(0, ASK_ENTRY_CHARS).trimEnd()}…` : entry}”`
          : `cited on page ${destination.pageNumber}`;
        requestChatPrompt(
          `About the cited work ${work}: what does this paper take from it and how does it differ?`,
        );
      })
      .catch(() => undefined)
      .finally(onClose);
  }

  // Map the click back through the crop into PDF coordinates, find the
  // bibliography entry under it, and web-search that citation.
  function searchClickedReference(event: MouseEvent<HTMLCanvasElement>): void {
    const canvas = canvasRef.current;
    const mapping = mappingRef.current;
    if (!canvas || !mapping) return;
    const rect = canvas.getBoundingClientRect();
    const cropX =
      ((event.clientX - rect.left) / rect.width) * canvas.width +
      mapping.sourceX;
    const cropY =
      ((event.clientY - rect.top) / rect.height) * canvas.height +
      mapping.sourceY;
    const [pdfX, pdfY] = mapping.viewport.convertToPdfPoint(cropX, cropY);
    searchViaPopup(async () => {
      const chunks = await pageTextChunks(document, destination.pageNumber);
      return referenceTextAtPoint(
        chunks,
        { x: pdfX, y: pdfY },
        mapping.pageWidth,
      );
    });
  }

  useEffect(() => {
    let disposed = false;
    let renderTask: RenderTask | null = null;
    // Every terminal path must settle the lookup for this key (match or
    // null): an unsettled key keeps "Checking library…" up forever.
    const settle = (match: LibraryMatch | null) => {
      if (!disposed) setLibraryMatch({ key: destinationKey, match });
    };
    const settleWithoutLookup = () => {
      if (libraryLookup && !ref) settle(null);
    };

    void (async () => {
      try {
        const page = await document.getPage(destination.pageNumber);
        if (disposed) return;
        const canvas = canvasRef.current;
        const context = canvas?.getContext("2d");
        if (!canvas || !context) {
          settleWithoutLookup();
          return;
        }

        const pixelRatio = Math.min(window.devicePixelRatio || 1, 2);
        // Fit the full text column into the preview width so bibliography
        // lines are never cut horizontally: scale the page such that the
        // margin-trimmed width maps exactly onto the canvas box.
        const base = page.getViewport({ scale: 1 });
        const scale =
          PREVIEW_WIDTH / (base.width * (1 - 2 * PREVIEW_MARGIN_TRIM));
        const cacheKey = `${destination.pageNumber}@${pixelRatio}`;
        let cache = pageCanvasCache.get(document);
        if (!cache) {
          cache = new Map();
          pageCanvasCache.set(document, cache);
        }
        const viewport = page.getViewport({ scale: scale * pixelRatio });
        let source = cache.get(cacheKey);
        if (!source) {
          source = window.document.createElement("canvas");
          source.width = Math.ceil(viewport.width);
          source.height = Math.ceil(viewport.height);
          const sourceContext = source.getContext("2d");
          if (!sourceContext) {
            settleWithoutLookup();
            return;
          }
          renderTask = page.render({
            canvas: source,
            canvasContext: sourceContext,
            viewport,
          });
          await renderTask.promise;
          if (disposed) return;
          cache.set(cacheKey, source);
        }

        const cropWidth = Math.min(
          source.width,
          Math.round(PREVIEW_WIDTH * pixelRatio),
        );
        const cropHeight = Math.min(
          source.height,
          Math.round(PREVIEW_HEIGHT * pixelRatio),
        );
        // Resolve the cited entry first: it drives both the highlight and
        // where the crop sits, so a long entry is framed whole instead of
        // hanging off the bottom.
        const entry = targetAtDestination(
          await pageTextChunks(document, destination.pageNumber),
          destination,
          base.width,
          ref,
        );
        if (disposed) return;
        const point =
          destination.left !== null && destination.top !== null
            ? viewport.convertToViewportPoint(destination.left, destination.top)
            : [source.width / 2, Math.min(source.height / 2, cropHeight / 2)];
        const entryHeight = entry
          ? entry.boxes.reduce(
              (total, box) => total + box.height * scale * pixelRatio,
              0,
            )
          : 0;
        const sourceX = Math.max(
          0,
          Math.min(
            source.width - cropWidth,
            Math.round(base.width * PREVIEW_MARGIN_TRIM * scale * pixelRatio),
          ),
        );
        const sourceY = Math.max(
          0,
          Math.min(
            source.height - cropHeight,
            // Center the entry when it fits; otherwise start at its top.
            entryHeight > 0 && entryHeight < cropHeight
              ? point[1] - (cropHeight - entryHeight) / 2
              : point[1] - cropHeight / 3,
          ),
        );
        canvas.width = cropWidth;
        canvas.height = cropHeight;
        context.drawImage(
          source,
          sourceX,
          sourceY,
          cropWidth,
          cropHeight,
          0,
          0,
          cropWidth,
          cropHeight,
        );
        mappingRef.current = {
          viewport,
          sourceX,
          sourceY,
          pageWidth: base.width,
        };
        setStatus("");

        // Mark the cited entry inside the crop — a page of bibliography all
        // looks alike, so without it the reader cannot tell which line the
        // hovered citation points at.
        if (entry) {
          context.save();
          context.globalCompositeOperation = "multiply";
          context.fillStyle = "rgba(255, 226, 92, 0.55)";
          for (const box of entry.boxes) {
            const [x, y] = viewport.convertToViewportPoint(
              box.x,
              box.y + box.height,
            );
            context.fillRect(
              x - sourceX,
              y - sourceY,
              box.width * scale * pixelRatio,
              box.height * scale * pixelRatio,
            );
          }
          context.restore();
        }

        // Eagerly resolve the cited entry against the library so the header
        // can offer "In your library" (signed-in surfaces only; a heading or
        // caption is not a citation, so in-paper locators skip this).
        const { left, top } = destination;
        const entryText = preview.entryText;
        if (libraryLookup && !ref) {
          if (entryText || (left !== null && top !== null)) {
            void (async () => {
              const reference =
                entryText ??
                referenceTextAtPoint(
                  await pageTextChunks(document, destination.pageNumber),
                  { x: (left ?? 0) + 15, y: (top ?? 0) - 6 },
                  base.width,
                );
              // The match API requires 12-400 chars.
              if (!reference || reference.length < 12) {
                settle(null);
                return;
              }
              if (disposed) return;
              const query = reference.slice(0, 400);
              let cache = libraryMatchCache.get(document);
              if (!cache) {
                cache = new Map();
                libraryMatchCache.set(document, cache);
              }
              let match = cache.get(query);
              if (match === undefined) {
                const response = await fetch(
                  `/api/v1/citations/match?q=${encodeURIComponent(query)}`,
                  { credentials: "same-origin" },
                );
                if (disposed) return;
                if (!response.ok) {
                  settle(null);
                  return;
                }
                const data = (await response.json()) as {
                  match: LibraryMatch | null;
                };
                match = data.match;
                cache.set(query, match);
              }
              settle(match);
            })().catch(() => settle(null));
          } else {
            settle(null);
          }
        }
      } catch (error) {
        if (
          !disposed &&
          (!(error instanceof Error) ||
            error.name !== "RenderingCancelledException")
        ) {
          setStatus("This reference preview could not be rendered.");
          // The lookup never ran (or died with the render); settle it so
          // the header falls back to AddToLibrary instead of "Checking…".
          settleWithoutLookup();
        }
      }
    })();

    return () => {
      disposed = true;
      renderTask?.cancel();
    };
  }, [
    destination,
    destinationKey,
    document,
    libraryLookup,
    preview.entryText,
    ref,
  ]);

  return (
    <aside
      className={`${styles.preview} ${
        preview.horizontal === "left" ? styles.previewLeft : styles.previewRight
      }`}
      style={{ top: preview.top }}
      data-reference-preview=""
      aria-label={`Reference preview, page ${destination.pageNumber}`}
    >
      <div className={styles.previewHeader}>
        <span className={styles.previewEyebrow}>
          {ref ? locatorTitle(ref) : "Reference"} · page{" "}
          {destination.pageNumber}
        </span>
        {chatPrompts && !ref && (
          <button
            className={styles.previewAction}
            type="button"
            onClick={askAboutReference}
            title="Ask the chat about this cited work"
          >
            Ask
          </button>
        )}
        {currentMatch && (
          <a
            className={styles.previewLibrary}
            href={`/paper/${currentMatch.topic}/${currentMatch.slug}`}
            title={currentMatch.title}
          >
            In your library
          </a>
        )}
        {libraryLookup && !ref && !settledLookup && (
          <span className={styles.previewChecking} role="status">
            Checking library…
          </span>
        )}
        {libraryLookup && !ref && settledLookup && !currentMatch && (
          <AddToLibrary key={destinationKey} resolveEntry={resolveEntry} />
        )}
        {!ref && (
          <button
            className={styles.previewOpen}
            type="button"
            onClick={searchTargetReference}
            aria-label="Search this reference on the web"
            title="Search this reference on the web"
          >
            🔍
          </button>
        )}
        <button
          className={styles.close}
          type="button"
          onClick={onClose}
          aria-label="Close reference preview"
        >
          ×
        </button>
      </div>
      <div
        className={
          ref
            ? `${styles.previewPage} ${styles.previewPageStatic}`
            : styles.previewPage
        }
      >
        <canvas
          ref={canvasRef}
          {...(ref
            ? {}
            : {
                onClick: searchClickedReference,
                title: "Click a reference to search it on the web",
              })}
        />
        {status && <p className={styles.previewStatus}>{status}</p>}
      </div>
    </aside>
  );
}

import { createPortal } from "react-dom";
import { useState, type RefObject } from "react";
import type { CommentCardBox } from "@/lib/pdf/reader/comment-card";
import base from "../PdfReader.module.css";
import styles from "./PdfCommentCard.module.css";

export interface CommentDraft {
  page: number;
  x: number;
  y: number;
  id?: string;
  text: string;
  initialText: string;
  mode?: "view" | "edit";
  editable?: boolean;
  author?: string;
  quote?: string;
  kind?: "comment" | "highlight" | "other";
}

export function PdfCommentCard({
  draft,
  position,
  appearance,
  busy,
  editDisabled,
  discardPrompt,
  error,
  dialogRef,
  textareaRef,
  onText,
  onEdit,
  onSave,
  onClose,
  onContinueEditing,
  onDiscard,
  onAsk,
}: {
  draft: CommentDraft;
  position: CommentCardBox;
  appearance: "theme" | "light" | "dark";
  busy: boolean;
  editDisabled: boolean;
  discardPrompt: boolean;
  error: string;
  dialogRef: RefObject<HTMLDivElement | null>;
  textareaRef: RefObject<HTMLTextAreaElement | null>;
  onText(text: string): void;
  onEdit(): void;
  onSave(remove?: boolean): void;
  onClose(): void;
  onContinueEditing(): void;
  onDiscard(): void;
  onAsk?(): void;
}) {
  const viewing = draft.mode === "view";
  const [confirmDelete, setConfirmDelete] = useState(false);
  return createPortal(
    <svg className={base.commentOverlay}>
      <foreignObject
        x={position.x}
        y={position.y}
        width={position.width}
        height={position.height}
      >
        <div
          ref={dialogRef}
          className={`${base.commentDialog} ${styles.card}`}
          data-document-appearance={appearance}
          role="dialog"
          tabIndex={-1}
          aria-label={viewing ? "查看批注" : draft.id ? "编辑评论" : "添加评论"}
        >
          <div className={styles.heading}>
            <strong>
              {viewing ? "批注" : draft.id ? "编辑评论" : "添加评论"}
            </strong>
            <span>第 {draft.page} 页</span>
            <button
              type="button"
              className={styles.close}
              aria-label="关闭批注卡片"
              disabled={busy}
              onClick={onClose}
            >
              ×
            </button>
          </div>
          {discardPrompt ? (
            <div
              className={styles.discardPrompt}
              role="alertdialog"
              aria-label="放弃未保存的评论"
            >
              <p>评论尚未保存，要放弃修改吗？</p>
              <div className={styles.actions}>
                <button
                  type="button"
                  disabled={busy}
                  autoFocus
                  onClick={onContinueEditing}
                >
                  继续编辑
                </button>
                <button type="button" disabled={busy} onClick={onDiscard}>
                  放弃修改
                </button>
              </div>
            </div>
          ) : confirmDelete ? (
            <div
              className={styles.discardPrompt}
              role="alertdialog"
              aria-label="删除这条批注"
            >
              <p>
                {draft.kind === "highlight"
                  ? "删除这条高亮及其想法？"
                  : "删除这条想法？"}
              </p>
              {error && <p role="alert">{error}</p>}
              <div className={styles.actions}>
                <button
                  type="button"
                  disabled={busy}
                  onClick={() => setConfirmDelete(false)}
                >
                  保留批注
                </button>
                <button
                  type="button"
                  disabled={busy}
                  onClick={() => onSave(true)}
                >
                  {busy ? "删除中…" : "删除批注"}
                </button>
              </div>
            </div>
          ) : viewing ? (
            <>
              {draft.author && <p className={styles.author}>{draft.author}</p>}
              {draft.quote && (
                <blockquote className={styles.quote}>{draft.quote}</blockquote>
              )}
              {draft.text && <p className={styles.text}>{draft.text}</p>}
              {!draft.text && !draft.quote && (
                <p className={styles.author}>这条批注没有附加评论。</p>
              )}
              <div className={styles.actions}>
                {onAsk && draft.quote && (
                  <button type="button" disabled={editDisabled} onClick={onAsk}>
                    提问
                  </button>
                )}
                {draft.editable ? (
                  <button
                    type="button"
                    disabled={editDisabled}
                    onClick={onEdit}
                  >
                    {draft.text ? "编辑想法" : "添加想法"}
                  </button>
                ) : (
                  <span className={styles.author}>只读批注</span>
                )}
                <button type="button" onClick={onClose}>
                  关闭
                </button>
              </div>
            </>
          ) : (
            <>
              <label>
                我的想法
                <textarea
                  ref={textareaRef}
                  value={draft.text}
                  disabled={busy}
                  onChange={(event) => onText(event.target.value)}
                  maxLength={10000}
                />
              </label>
              {error && <p role="alert">{error}</p>}
              <div className={styles.actions}>
                <button
                  type="button"
                  disabled={
                    busy ||
                    (!draft.text.trim() && draft.kind !== "highlight") ||
                    draft.text === draft.initialText
                  }
                  onClick={() => onSave()}
                >
                  {busy ? "保存中…" : "保存想法"}
                </button>
                {draft.id && (
                  <button
                    type="button"
                    disabled={busy}
                    onClick={() => setConfirmDelete(true)}
                  >
                    {draft.kind === "highlight" ? "删除批注" : "删除评论"}
                  </button>
                )}
                <button type="button" disabled={busy} onClick={onClose}>
                  取消
                </button>
              </div>
            </>
          )}
        </div>
      </foreignObject>
    </svg>,
    document.body,
  );
}

"use client";

import { useLayoutEffect, useState, type RefObject } from "react";
import type { PDFViewer } from "pdfjs-dist/web/pdf_viewer.mjs";
import {
  placeCommentCard,
  type CommentCardBox,
} from "@/lib/pdf/reader/comment-card";

export function useCommentPosition(
  anchor: { page: number; x: number; y: number } | null,
  stage: RefObject<HTMLDivElement | null>,
  viewer: RefObject<PDFViewer | null>,
): CommentCardBox | null {
  const [position, setPosition] = useState<CommentCardBox | null>(null);
  const page = anchor?.page;
  const x = anchor?.x;
  const y = anchor?.y;
  useLayoutEffect(() => {
    if (page === undefined || x === undefined || y === undefined) return;
    const stageElement = stage.current;
    const visual = window.visualViewport;
    const pageElement = stageElement?.querySelector<HTMLElement>(
      `.page[data-page-number="${page}"]`,
    );
    if (!stageElement || !pageElement) return;
    const place = () => {
      const pageView = viewer.current?.getPageView(page - 1);
      if (!pageView) return;
      const [pageX, pageY] = pageView.viewport.convertToViewportPoint(x, y);
      const rect = pageElement.getBoundingClientRect();
      const bounds = stageElement.getBoundingClientRect();
      setPosition(
        placeCommentCard(
          { x: rect.left + pageX, y: rect.top + pageY },
          {
            x: bounds.left,
            y: bounds.top,
            width: bounds.width,
            height: bounds.height,
          },
          {
            x: visual?.offsetLeft ?? 0,
            y: visual?.offsetTop ?? 0,
            width: visual?.width ?? window.innerWidth,
            height: visual?.height ?? window.innerHeight,
          },
        ),
      );
    };
    place();
    const observer = new ResizeObserver(place);
    observer.observe(pageElement);
    observer.observe(stageElement);
    window.addEventListener("resize", place);
    window.addEventListener("scroll", place, true);
    visual?.addEventListener("resize", place);
    visual?.addEventListener("scroll", place);
    return () => {
      observer.disconnect();
      window.removeEventListener("resize", place);
      window.removeEventListener("scroll", place, true);
      visual?.removeEventListener("resize", place);
      visual?.removeEventListener("scroll", place);
    };
  }, [page, x, y, stage, viewer]);
  return position;
}

"use client";

import { useEffect, useId, useRef, useState, type RefObject } from "react";
import { createPortal } from "react-dom";
import {
  Highlighter,
  MessageSquare,
  MoreHorizontal,
  PenLine,
  Type,
} from "lucide-react";
import type { EditMode } from "../usePdfDocument";
import styles from "./PdfMoreTools.module.css";

export function PdfMoreTools({
  container,
  className,
  mode,
  commentEnabled,
  disabled,
  commentDisabled,
  onMode,
  onComment,
}: {
  container: RefObject<HTMLDivElement | null>;
  className?: string;
  mode: EditMode;
  commentEnabled: boolean;
  disabled: boolean;
  commentDisabled: boolean;
  onMode(mode: EditMode): void;
  onComment(): void;
}) {
  const [open, setOpen] = useState(false);
  const trigger = useRef<HTMLButtonElement>(null);
  const panel = useRef<HTMLDivElement>(null);
  const id = useId();
  useEffect(() => {
    if (!open) return;
    panel.current
      ?.querySelector<HTMLButtonElement>("button:not(:disabled)")
      ?.focus();
    const outside = (event: PointerEvent) => {
      if (!(event.target instanceof Node)) return;
      if (
        !panel.current?.contains(event.target) &&
        !trigger.current?.contains(event.target)
      )
        setOpen(false);
    };
    const escape = (event: KeyboardEvent) => {
      if (event.key !== "Escape") return;
      event.preventDefault();
      event.stopImmediatePropagation();
      setOpen(false);
      trigger.current?.focus();
    };
    document.addEventListener("pointerdown", outside, true);
    document.addEventListener("keydown", escape, true);
    return () => {
      document.removeEventListener("pointerdown", outside, true);
      document.removeEventListener("keydown", escape, true);
    };
  }, [open]);

  function choose(action: () => void) {
    action();
    setOpen(false);
    trigger.current?.focus();
  }
  const tools = [
    { mode: "highlight" as const, label: "高亮工具", icon: Highlighter },
    { mode: "text" as const, label: "文本框", icon: Type },
    { mode: "draw" as const, label: "手写", icon: PenLine },
  ];
  return (
    <>
      <button
        ref={trigger}
        type="button"
        className={`${styles.trigger} ${className ?? ""}`}
        aria-label="更多批注工具"
        aria-haspopup="menu"
        aria-expanded={open}
        aria-controls={open ? id : undefined}
        title="更多工具"
        disabled={disabled}
        onClick={() => setOpen((value) => !value)}
        onKeyDown={(event) => {
          if (event.key === "ArrowDown") {
            event.preventDefault();
            setOpen(true);
          }
        }}
      >
        <MoreHorizontal size={16} />
        <span>更多</span>
      </button>
      {open &&
        container.current &&
        createPortal(
          <div
            id={id}
            ref={panel}
            className={styles.menu}
            role="menu"
            aria-label="更多批注工具"
            onBlur={(event) => {
              if (
                event.relatedTarget instanceof Node &&
                !event.currentTarget.contains(event.relatedTarget) &&
                !trigger.current?.contains(event.relatedTarget)
              )
                setOpen(false);
            }}
            onKeyDown={(event) => {
              const buttons = Array.from(
                event.currentTarget.querySelectorAll<HTMLButtonElement>(
                  "button:not(:disabled)",
                ),
              );
              const index = buttons.indexOf(
                document.activeElement as HTMLButtonElement,
              );
              let next = index;
              if (event.key === "ArrowDown")
                next = (index + 1) % buttons.length;
              else if (event.key === "ArrowUp")
                next = (index - 1 + buttons.length) % buttons.length;
              else if (event.key === "Home") next = 0;
              else if (event.key === "End") next = buttons.length - 1;
              else return;
              event.preventDefault();
              buttons[next]?.focus();
            }}
          >
            {tools.map((tool) => (
              <button
                key={tool.mode}
                type="button"
                role="menuitemradio"
                aria-checked={mode === tool.mode && !commentEnabled}
                disabled={disabled}
                onClick={() => choose(() => onMode(tool.mode))}
              >
                <tool.icon size={16} />
                <span>{tool.label}</span>
                {mode === tool.mode && !commentEnabled && (
                  <span className={styles.active}>已启用</span>
                )}
              </button>
            ))}
            <button
              type="button"
              role="menuitemradio"
              aria-checked={commentEnabled}
              disabled={commentDisabled}
              onClick={() => choose(onComment)}
            >
              <MessageSquare size={16} />
              <span>页面便签</span>
              {commentEnabled && <span className={styles.active}>已启用</span>}
            </button>
          </div>,
          container.current,
        )}
    </>
  );
}

"use client";

/**
 * Saves chat answers into the paper as FreeText margin notes. A note is
 * written straight into pdf.js's annotationStorage in the shape
 * FreeTextEditor.serialize() produces, which dirties the autosave and gets
 * the worker to append a real FreeText annotation on the next PUT. Once
 * that save lands the document remounts at the same page and zoom so the
 * note renders (and stays editable) as an annotation loaded from the file,
 * never as a second copy re-serialized from storage.
 */

import {
  useEffect,
  type Dispatch,
  type RefObject,
  type SetStateAction,
} from "react";
import type { AnnotationEditorUIManager, PDFDocumentProxy } from "pdfjs-dist";
import type { PDFViewer } from "pdfjs-dist/web/pdf_viewer.mjs";
import {
  MARGIN_NOTE_EVENT,
  parseMarginNoteEvent,
  type MarginNoteDetail,
} from "@/lib/chat/paper-ref-events";
import { NOTE_FONT_SIZE, noteRect } from "@/lib/chat/margin-note";
import type { PdfAutosaveCoordinator } from "@/lib/pdf/autosave";
import type { PdfEditGate } from "@/lib/pdf/reader/edit-gate";
import { locateRef, type LineCache } from "../usePaperRefBridge";
import type { EditMode } from "../usePdfDocument";

/** pdf.js AnnotationEditorType.FREETEXT; the worker switches on it. */
const FREETEXT_ANNOTATION_TYPE = 3;
/** Far above anything the editor's own id counter reaches in a session. */
const FALLBACK_ID_BASE = 9000;
const SAVE_POLL_MS = 250;
const SAVE_POLL_LIMIT = 40;

interface UseMarginNotesOptions {
  pdfDocument: PDFDocumentProxy | null;
  editable: boolean;
  pdfViewerRef: RefObject<PDFViewer | null>;
  uiManagerRef: RefObject<AnnotationEditorUIManager | null>;
  autosaveRef: RefObject<PdfAutosaveCoordinator | null>;
  restoreViewRef: RefObject<{ page: number; scale: number } | null>;
  /** Another session saved first; the coordinator is paused until the
   * reader reloads, so a note written now could never reach the file. */
  remoteUpdate: boolean;
  editGate: RefObject<PdfEditGate>;
  setEditMode: Dispatch<SetStateAction<EditMode>>;
  setSaveStatus: Dispatch<SetStateAction<string>>;
  setDocumentGeneration: Dispatch<SetStateAction<number>>;
}

const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

/**
 * Wait until the coordinator has nothing left to write. `flush()` is a
 * no-op while another save is in flight; the note's own `markDirty()`
 * bumped the revision past the in-flight one, so the next poll's flush
 * writes it.
 */
async function settleSave(
  autosave: PdfAutosaveCoordinator,
  cancelled: () => boolean,
): Promise<boolean> {
  for (let attempt = 0; attempt < SAVE_POLL_LIMIT; attempt++) {
    await autosave.flush();
    if (cancelled()) return false;
    const state = autosave.state();
    if (state.error) return false;
    if (!state.dirty && !state.saving) return true;
    await sleep(SAVE_POLL_MS);
  }
  return false;
}

export function useMarginNotes({
  pdfDocument,
  editable,
  pdfViewerRef,
  uiManagerRef,
  autosaveRef,
  restoreViewRef,
  remoteUpdate,
  editGate,
  setEditMode,
  setSaveStatus,
  setDocumentGeneration,
}: UseMarginNotesOptions): void {
  useEffect(() => {
    // Listen whenever the reader is editable, even before the document is
    // ready or after a remote update paused saving: the chat's "Save as
    // note" button is live the whole time, so a click must always get an
    // answer rather than dispatch into the void.
    if (!editable) return;
    let disposed = false;
    let fallbackIds = 0;
    const lineCache: LineCache = new Map();

    const saveNote = async (detail: MarginNoteDetail) => {
      if (remoteUpdate) {
        setSaveStatus("Reload the latest version before saving a note.");
        return;
      }
      const viewer = pdfViewerRef.current;
      const autosave = autosaveRef.current;
      if (!pdfDocument || !viewer || !autosave) {
        setSaveStatus(
          "The paper is still loading; save the note again in a moment.",
        );
        return;
      }
      let pageNumber = viewer.currentPageNumber;
      let anchorTop: number | null = null;
      if (detail.ref) {
        const target = await locateRef(
          pdfDocument,
          detail.ref,
          lineCache,
          () => disposed,
        );
        if (disposed) return;
        if (target) {
          pageNumber = target.pageNumber;
          anchorTop = target.top;
        }
      }
      const page = await pdfDocument.getPage(pageNumber);
      if (disposed) return;
      const [x0, y0, x1, y1] = page.view;
      const lineCount = detail.text.split("\n").length;
      const id =
        uiManagerRef.current?.getId() ??
        `pdfjs_internal_editor_${FALLBACK_ID_BASE + fallbackIds++}`;
      pdfDocument.annotationStorage.setValue(id, {
        annotationType: FREETEXT_ANNOTATION_TYPE,
        color: [0, 0, 0],
        fontSize: NOTE_FONT_SIZE,
        value: detail.text,
        pageIndex: pageNumber - 1,
        rect: noteRect([x0, y0, x1, y1], lineCount, anchorTop),
        rotation: 0,
        structTreeParentId: null,
        popupRef: null,
      });
      // pdf.js only reports the first edit of a modified cycle through
      // onSetModified; while a save is in flight that latch is already set,
      // so the coordinator has to hear about the note directly or the save
      // would complete without it and the remount below would drop it.
      autosave.markDirty();
      setSaveStatus(`Saving note to page ${pageNumber}…`);
      const saved = await settleSave(autosave, () => disposed);
      if (disposed) return;
      if (!saved) {
        // A failed save already shows the coordinator's own error and keeps
        // the note queued for its retry; only a stalled one needs a word.
        if (!autosave.state().error) {
          setSaveStatus(
            `Still saving the note for page ${pageNumber}; it appears after the next reload.`,
          );
        }
        return;
      }
      restoreViewRef.current = {
        page: pageNumber,
        scale: viewer.currentScale,
      };
      // The rebuilt viewer starts in select mode; keep the toolbar honest.
      setEditMode("select");
      setSaveStatus(`Note saved on page ${pageNumber}`);
      editGate.current.reloadingDocument = pdfDocument;
      setDocumentGeneration((generation) => generation + 1);
    };

    const onMarginNote = (event: Event) => {
      const detail = parseMarginNoteEvent(
        (event as CustomEvent<unknown>).detail,
      );
      if (!detail) return;
      const gate = editGate.current;
      if (gate.commentActive) {
        setSaveStatus("Finish the comment before saving a note.");
        return;
      }
      if (gate.notesInFlight || gate.reloadingDocument) {
        setSaveStatus("Wait for the note to finish saving.");
        return;
      }
      gate.notesInFlight += 1;
      void saveNote(detail)
        .catch((error: unknown) => {
          console.error("papernook: margin note failed", error);
          if (!disposed) setSaveStatus("The note could not be saved.");
        })
        .finally(() => {
          gate.notesInFlight -= 1;
        });
    };

    window.addEventListener(MARGIN_NOTE_EVENT, onMarginNote);
    return () => {
      disposed = true;
      window.removeEventListener(MARGIN_NOTE_EVENT, onMarginNote);
    };
  }, [
    pdfDocument,
    editable,
    pdfViewerRef,
    uiManagerRef,
    autosaveRef,
    restoreViewRef,
    remoteUpdate,
    editGate,
    setEditMode,
    setSaveStatus,
    setDocumentGeneration,
  ]);
}

"use client";

import { useCallback, useEffect, useState, type RefObject } from "react";
import styles from "../PdfReader.module.css";
import { placeSelectionAsk } from "./selectionAsk";

export interface SelectionAsk {
  text: string;
  page: number;
  top: number;
  left: number;
}

/** Quiet period after the last selection change before measuring it. */
const SELECTION_SETTLE_MS = 160;

/**
 * Track a text-layer selection inside the reader stage and where to float
 * an "Ask about selection" button for it. Measured when a pointer drag
 * that started in the stage ends (wherever it ends) and, for selections
 * made without a pointer drag (shift+arrow keys, touch handles), once the
 * selection has stopped changing. Cleared when the selection collapses,
 * the stage scrolls, Escape is pressed, or the hook goes inactive.
 * Citation hotspots win over selection: a pointerup on one leaves
 * whatever was showing untouched.
 */
export function useTextSelectionAsk(
  stageRef: RefObject<HTMLDivElement | null>,
  active: boolean,
): { selection: SelectionAsk | null; clear(): void } {
  const [selection, setSelection] = useState<SelectionAsk | null>(null);
  const clear = useCallback(() => setSelection(null), []);

  useEffect(() => {
    const stage = stageRef.current;
    if (!stage || !active) {
      setSelection(null);
      return;
    }
    let dragging = false;
    let settle: ReturnType<typeof setTimeout> | null = null;
    const cancelSettle = () => {
      if (settle !== null) clearTimeout(settle);
      settle = null;
    };
    const measure = () => setSelection(readSelection(stage));
    const onPointerDown = (event: PointerEvent) => {
      dragging = event.target instanceof Node && stage.contains(event.target);
    };
    const onPointerUp = (event: PointerEvent) => {
      dragging = false;
      const target = event.target;
      if (target instanceof Element) {
        // The floating button itself (PdfReader marks it) never re-measures.
        if (target.closest("[data-selection-ask]")) return;
        if (target.closest(`.${styles.citationHotspot}`)) return;
      }
      cancelSettle();
      measure();
    };
    const onPointerCancel = () => {
      dragging = false;
    };
    const onSelectionChange = () => {
      const live = window.getSelection();
      if (!live || live.isCollapsed) {
        cancelSettle();
        setSelection(null);
        return;
      }
      // Mid-drag the selection grows on every move; wait for the pointer
      // to lift instead of flashing the button under the cursor.
      if (dragging) return;
      cancelSettle();
      settle = setTimeout(() => {
        settle = null;
        measure();
      }, SELECTION_SETTLE_MS);
    };
    const onEscape = (event: KeyboardEvent) => {
      if (event.key !== "Escape") return;
      // Escape alone leaves the DOM selection live; drop it so nothing
      // measures it again.
      window.getSelection()?.removeAllRanges();
      cancelSettle();
      setSelection(null);
    };
    window.addEventListener("pointerdown", onPointerDown);
    window.addEventListener("pointerup", onPointerUp);
    window.addEventListener("pointercancel", onPointerCancel);
    stage.addEventListener("scroll", clear, true);
    window.document.addEventListener("selectionchange", onSelectionChange);
    window.addEventListener("keydown", onEscape);
    return () => {
      cancelSettle();
      window.removeEventListener("pointerdown", onPointerDown);
      window.removeEventListener("pointerup", onPointerUp);
      window.removeEventListener("pointercancel", onPointerCancel);
      stage.removeEventListener("scroll", clear, true);
      window.document.removeEventListener("selectionchange", onSelectionChange);
      window.removeEventListener("keydown", onEscape);
      setSelection(null);
    };
  }, [active, clear, stageRef]);

  return { selection, clear };
}

function readSelection(stage: HTMLDivElement): SelectionAsk | null {
  const live = window.getSelection();
  if (!live || live.isCollapsed || live.rangeCount === 0) return null;
  const anchor = live.anchorNode;
  const anchorElement =
    anchor instanceof Element ? anchor : (anchor?.parentElement ?? null);
  if (!anchorElement || !stage.contains(anchorElement)) return null;
  // pdf.js renders selectable text only inside .textLayer; anything else
  // (toolbar labels, preview copy) is not a passage of the paper.
  if (!anchorElement.closest(".textLayer")) return null;
  const pageElement = anchorElement.closest<HTMLElement>(".page");
  const page = Number(pageElement?.dataset.pageNumber);
  if (!Number.isInteger(page) || page < 1) return null;
  const text = live.toString().trim();
  if (!text) return null;
  const rect = live.getRangeAt(0).getBoundingClientRect();
  if (rect.width === 0 && rect.height === 0) return null;
  return {
    text,
    page,
    ...placeSelectionAsk(rect, stage.getBoundingClientRect()),
  };
}

"use client";

/**
 * Text-based citation recognition for papers WITHOUT embedded cite links:
 * builds the bibliography index once per document, then decorates every
 * rendered text layer with invisible hotspots over recognized citations.
 * Papers whose citations already carry link annotations are untouched — a
 * hotspot overlapping a link annotation is dropped, and fully-linked papers
 * keep the existing goToDestination interception as their only path.
 */

import { useEffect, useRef } from "react";
import type { PDFDocumentProxy } from "pdfjs-dist";
import {
  buildBibliography,
  matchCitation,
  type BibEntry,
  type Bibliography,
  type BibliographyPage,
} from "@/lib/pdf/bibliography";
import { findCitations } from "@/lib/pdf/citations";
import type { ResolvedPdfDestination } from "@/lib/pdf/destinations";
import { pdfTextChunks, pdfTextItems } from "@/lib/pdf/text-items";
import {
  assembleSegments,
  boxesIntersect,
  mergeRectsIntoLines,
  positionAt,
  type Box,
  type TextLayerSegment,
} from "@/lib/pdf/text-layer-map";
import styles from "./PdfReader.module.css";

interface CitationTarget {
  destination: ResolvedPdfDestination;
  entryText: string;
  clientX: number;
  clientY: number;
}

export interface ViewerEventBus {
  on(name: string, listener: (event: unknown) => void): void;
  off(name: string, listener: (event: unknown) => void): void;
}

interface UseCitationHotspotsOptions {
  pdfDocument: PDFDocumentProxy | null;
  eventBus: ViewerEventBus | null;
  /** False while an annotation tool is active — hotspots must never steal
   * highlight/ink strokes. */
  enabled: boolean;
  onCitation(target: CitationTarget): void;
  /** Fired once per document when the bibliography scan lands, so the
   * owner can resolve chat-originated citations against it. */
  onBibliography?(bibliography: Bibliography): void;
}

/** Only the trailing pages can hold a bibliography worth scanning. */
const MAX_SCANNED_PAGES = 100;
const HOVER_DELAY_MS = 180;

/** EventBus payloads are untyped; narrow by hand (no `any`). */
function renderedTextLayer(
  event: unknown,
): { pageNumber: number; layer: HTMLElement } | null {
  if (!event || typeof event !== "object") return null;
  const { pageNumber, source } = event as {
    pageNumber?: unknown;
    source?: unknown;
  };
  if (typeof pageNumber !== "number" || !source || typeof source !== "object") {
    return null;
  }
  const textLayer = (source as { textLayer?: unknown }).textLayer;
  if (!textLayer || typeof textLayer !== "object") return null;
  const layer = (textLayer as { div?: unknown }).div;
  return layer instanceof HTMLElement ? { pageNumber, layer } : null;
}

async function scanBibliography(
  pdfDocument: PDFDocumentProxy,
  cancelled: () => boolean,
): Promise<Bibliography | null> {
  const firstPage = Math.max(1, pdfDocument.numPages - MAX_SCANNED_PAGES + 1);
  const pages: BibliographyPage[] = [];
  for (let pageNumber = firstPage; pageNumber <= pdfDocument.numPages;) {
    const page = await pdfDocument.getPage(pageNumber);
    if (cancelled()) return null;
    const items = await pdfTextItems(page);
    if (cancelled()) return null;
    const viewport = page.getViewport({ scale: 1 });
    pages.push({
      pageNumber,
      pageWidth: viewport.width,
      chunks: pdfTextChunks(items),
    });
    pageNumber += 1;
  }
  return buildBibliography(pages);
}

function relativeBox(rect: DOMRect, origin: DOMRect): Box {
  return {
    left: rect.left - origin.left,
    top: rect.top - origin.top,
    width: rect.width,
    height: rect.height,
  };
}

export function useCitationHotspots({
  pdfDocument,
  eventBus,
  enabled,
  onCitation,
  onBibliography,
}: UseCitationHotspotsOptions): void {
  const onCitationRef = useRef(onCitation);
  const onBibliographyRef = useRef(onBibliography);
  const enabledRef = useRef(enabled);
  const overlaysRef = useRef(new Set<HTMLElement>());

  useEffect(() => {
    onCitationRef.current = onCitation;
    onBibliographyRef.current = onBibliography;
  }, [onCitation, onBibliography]);

  useEffect(() => {
    enabledRef.current = enabled;
    for (const overlay of overlaysRef.current) {
      overlay.classList.toggle(styles.citationOverlayDisabled ?? "", !enabled);
    }
  }, [enabled]);

  useEffect(() => {
    if (!pdfDocument || !eventBus) return;

    let disposed = false;
    let bibliography: Bibliography | null = null;
    let hoverTimer: number | null = null;
    const overlays = overlaysRef.current;
    // Text layers rendered before the bibliography scan finishes get
    // decorated as soon as it lands.
    const pendingLayers = new Map<number, HTMLElement>();

    const clearHoverTimer = () => {
      if (hoverTimer !== null) {
        window.clearTimeout(hoverTimer);
        hoverTimer = null;
      }
    };

    const removeOverlays = () => {
      clearHoverTimer();
      for (const overlay of overlays) overlay.remove();
      overlays.clear();
    };

    const openCitation = (entry: BibEntry, at: MouseEvent) => {
      onCitationRef.current({
        destination: {
          pageNumber: entry.pageNumber,
          kind: "XYZ",
          left: entry.x,
          // Slightly above the entry's first baseline so the crop starts on
          // the entry, matching where hyperref destinations point.
          top: entry.y + 8,
          zoom: null,
        },
        entryText: entry.text,
        clientX: at.clientX,
        clientY: at.clientY,
      });
    };

    const decorate = (pageNumber: number, layer: HTMLElement) => {
      if (!bibliography) {
        pendingLayers.set(pageNumber, layer);
        return;
      }
      const pageContainer = layer.parentElement;
      if (!pageContainer) return;
      const stale = pageContainer.querySelector("[data-citation-overlay]");
      if (stale instanceof HTMLElement) {
        overlays.delete(stale);
        stale.remove();
      }

      const segments: TextLayerSegment[] = [];
      const nodes: (Text | null)[] = [];
      const walker = window.document.createTreeWalker(
        layer,
        NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT,
      );
      for (let node = walker.nextNode(); node; node = walker.nextNode()) {
        if (node instanceof Text) {
          segments.push({ text: node.data, isBreak: false });
          nodes.push(node);
        } else if (node instanceof HTMLBRElement) {
          segments.push({ text: "", isBreak: true });
          nodes.push(null);
        }
      }
      const assembled = assembleSegments(segments);
      if (!assembled.text) return;

      const resolved = findCitations(assembled.text).flatMap((citation) => {
        const entry = matchCitation(bibliography!, citation.key);
        return entry ? [{ citation, entry }] : [];
      });
      if (resolved.length === 0) return;

      const pageRect = pageContainer.getBoundingClientRect();
      const linkBoxes = [
        ...pageContainer.querySelectorAll(".annotationLayer a"),
      ].map((link) => relativeBox(link.getBoundingClientRect(), pageRect));

      const overlay = window.document.createElement("div");
      overlay.dataset.citationOverlay = "";
      overlay.className = `${styles.citationOverlay ?? ""} ${
        enabledRef.current ? "" : (styles.citationOverlayDisabled ?? "")
      }`.trim();

      for (const { citation, entry } of resolved) {
        const start = positionAt(assembled, citation.start, "start");
        const end = positionAt(assembled, citation.end, "end");
        const startNode = start ? nodes[start.segment] : null;
        const endNode = end ? nodes[end.segment] : null;
        if (!start || !end || !startNode || !endNode) continue;
        const range = window.document.createRange();
        range.setStart(startNode, start.offset);
        range.setEnd(endNode, end.offset);
        const boxes = mergeRectsIntoLines(
          [...range.getClientRects()].map((rect) =>
            relativeBox(rect, pageRect),
          ),
        );
        if (boxes.length === 0) continue;
        // An overlapping link annotation means the PDF already handles this
        // citation — never double-trigger.
        if (
          boxes.some((box) =>
            linkBoxes.some((link) => boxesIntersect(box, link)),
          )
        ) {
          continue;
        }
        for (const box of boxes) {
          const hotspot = window.document.createElement("button");
          hotspot.type = "button";
          hotspot.tabIndex = -1;
          hotspot.dataset.citation = "";
          hotspot.className = styles.citationHotspot ?? "";
          hotspot.style.left = `${box.left - 1}px`;
          hotspot.style.top = `${box.top - 1}px`;
          hotspot.style.width = `${box.width + 2}px`;
          hotspot.style.height = `${box.height + 2}px`;
          hotspot.setAttribute(
            "aria-label",
            `Show reference: ${entry.text.slice(0, 80)}`,
          );
          hotspot.addEventListener("click", (event) => {
            openCitation(entry, event);
          });
          hotspot.addEventListener("pointerenter", (event) => {
            if (event.pointerType !== "mouse") return;
            clearHoverTimer();
            hoverTimer = window.setTimeout(() => {
              openCitation(entry, event);
            }, HOVER_DELAY_MS);
          });
          hotspot.addEventListener("pointerleave", clearHoverTimer);
          overlay.append(hotspot);
        }
      }
      if (overlay.childElementCount === 0) return;
      pageContainer.append(overlay);
      overlays.add(overlay);
    };

    const onLayerRendered = (event: unknown) => {
      const rendered = renderedTextLayer(event);
      if (rendered) decorate(rendered.pageNumber, rendered.layer);
    };
    // Pinch zoom takes pdf.js's CSS-transform fast path, which resizes
    // pages WITHOUT re-firing textlayerrendered — overlays would sit over
    // the wrong glyphs, so drop them until the real re-render arrives.
    const onScaleChanging = () => {
      removeOverlays();
    };
    eventBus.on("textlayerrendered", onLayerRendered);
    // The annotation layer renders after the text layer; re-decorating then
    // lets the link-overlap filter see the links it must defer to.
    eventBus.on("annotationlayerrendered", onLayerRendered);
    eventBus.on("scalechanging", onScaleChanging);

    // Deferred to idle: the scan pulls text off up to 100 pages, which with
    // a streaming document means competing with page 1 for both the worker
    // and the bytes still in flight. Text layers rendered before it lands
    // already queue in pendingLayers, so only the timing moves.
    const startScan = () => {
      void scanBibliography(pdfDocument, () => disposed)
        .then((scanned) => {
          if (disposed || !scanned) return;
          bibliography = scanned;
          onBibliographyRef.current?.(scanned);
          const layers = [...pendingLayers];
          pendingLayers.clear();
          for (const [pageNumber, layer] of layers) {
            if (layer.isConnected) decorate(pageNumber, layer);
          }
        })
        .catch((error: unknown) => {
          console.error("papernook: bibliography scan failed", error);
        });
    };
    // A plain timeout, not requestIdleCallback: WebKit still does not
    // implement it (TypeScript's DOM lib types it as always present, which
    // is how it shipped and broke every Safari load), and the only thing
    // this needs is to be off the first-render path.
    const scanHandle = window.setTimeout(startScan, 500);

    return () => {
      disposed = true;
      window.clearTimeout(scanHandle);
      eventBus.off("textlayerrendered", onLayerRendered);
      eventBus.off("annotationlayerrendered", onLayerRendered);
      eventBus.off("scalechanging", onScaleChanging);
      removeOverlays();
    };
  }, [eventBus, pdfDocument]);
}

"use client";

/**
 * PDF side of the chat → PDF reference bridge: listens for the
 * `papernook:paper-ref` window events ChatPanel dispatches, resolves them
 * against the open document, and hands the result back to PdfReader —
 * preview (hover/citations) or navigation (ref clicks).
 *
 * In-paper refs resolve by trying hyperref destination-name candidates in
 * order via resolvePdfDestination (getDestination per name; pdf.js's own
 * docs warn against eagerly fetching the whole destination tree).
 * Citations resolve against the bibliography the hotspot scan published.
 * Event payloads originate from AI-authored chat content and are
 * validated before use.
 */

import { useEffect, useRef } from "react";
import type { PDFDocumentProxy } from "pdfjs-dist";
import {
  PAPER_REF_EVENT,
  parsePaperRefEvent,
} from "@/lib/chat/paper-ref-events";
import {
  matchCitation,
  pageLines,
  type Bibliography,
  type TextLine,
} from "@/lib/pdf/bibliography";
import {
  resolvePdfDestination,
  type ResolvedPdfDestination,
} from "@/lib/pdf/destinations";
import {
  captionPattern,
  destinationCandidates,
  type PaperRef,
} from "@/lib/pdf/paper-refs";
import { pdfTextChunks, pdfTextItems } from "@/lib/pdf/text-items";

interface UsePaperRefBridgeOptions {
  pdfDocument: PDFDocumentProxy | null;
  /** False while an annotation tool is active — a chat click must never
   * scroll the page under an in-progress stroke. */
  enabled: boolean;
  bibliography(): Bibliography | null;
  onNavigate(target: ResolvedPdfDestination): void;
  /** Citations carry the bibliography entry's text; in-paper refs carry the
   * locator itself so the preview can frame its heading or caption. */
  onPreview(
    target: ResolvedPdfDestination,
    entryText: string | null,
    ref: PaperRefLocator | null,
  ): void;
}

type PaperRefLocator = Pick<PaperRef, "kind" | "label">;

async function resolveRef(
  pdfDocument: PDFDocumentProxy,
  ref: Pick<PaperRef, "kind" | "label">,
): Promise<ResolvedPdfDestination | null> {
  for (const candidate of destinationCandidates(ref)) {
    const target = await resolvePdfDestination(pdfDocument, candidate);
    if (target) return target;
  }
  return null;
}

/** Promise-per-page so concurrent lookups never extract a page twice. */
export type LineCache = Map<number, Promise<TextLine[]>>;

function pageTextLines(
  pdfDocument: PDFDocumentProxy,
  pageNumber: number,
  cache: LineCache,
): Promise<TextLine[]> {
  let lines = cache.get(pageNumber);
  if (!lines) {
    lines = (async () => {
      const page = await pdfDocument.getPage(pageNumber);
      const items = await pdfTextItems(page);
      const viewport = page.getViewport({ scale: 1 });
      return pageLines({
        pageNumber,
        pageWidth: viewport.width,
        chunks: pdfTextChunks(items),
      });
    })();
    cache.set(pageNumber, lines);
  }
  return lines;
}

/**
 * Fallback for PDFs without named destinations: find the ref's caption
 * (or heading) line in page text. First line-start match wins — captions
 * are the only place "Figure 3:" starts a line.
 */
async function findCaption(
  pdfDocument: PDFDocumentProxy,
  ref: Pick<PaperRef, "kind" | "label">,
  cache: LineCache,
  cancelled: () => boolean,
): Promise<ResolvedPdfDestination | null> {
  const pattern = captionPattern(ref);
  if (!pattern) return null;
  for (let pageNumber = 1; pageNumber <= pdfDocument.numPages; pageNumber++) {
    if (cancelled()) return null;
    const lines = await pageTextLines(pdfDocument, pageNumber, cache);
    const hit = lines.find((line) => pattern.test(line.text));
    if (hit) {
      return {
        pageNumber,
        kind: "XYZ",
        left: hit.x,
        // Slightly above the line's baseline, like hyperref destinations.
        top: hit.y + 8,
        zoom: null,
      };
    }
  }
  return null;
}

/**
 * Full resolution: destination names first, then the caption text search.
 * `cache` should live as long as the document (a fresh Map per effect).
 */
export async function locateRef(
  pdfDocument: PDFDocumentProxy,
  ref: Pick<PaperRef, "kind" | "label">,
  cache: LineCache,
  cancelled: () => boolean,
): Promise<ResolvedPdfDestination | null> {
  return (
    (await resolveRef(pdfDocument, ref)) ??
    findCaption(pdfDocument, ref, cache, cancelled)
  );
}

export function usePaperRefBridge({
  pdfDocument,
  enabled,
  bibliography,
  onNavigate,
  onPreview,
}: UsePaperRefBridgeOptions): void {
  const optionsRef = useRef({ enabled, bibliography, onNavigate, onPreview });
  useEffect(() => {
    optionsRef.current = { enabled, bibliography, onNavigate, onPreview };
  });

  useEffect(() => {
    if (!pdfDocument) return;
    let disposed = false;
    // Effect-scoped: a document change re-runs the effect, dropping the
    // stale cache with it.
    const lineCache: LineCache = new Map();

    const onPaperRef = (event: Event) => {
      if (!optionsRef.current.enabled) return;
      const detail = parsePaperRefEvent((event as CustomEvent<unknown>).detail);
      if (!detail) return;

      if ("citation" in detail) {
        const scanned = optionsRef.current.bibliography();
        const entry = scanned && matchCitation(scanned, detail.citation);
        if (!entry) return;
        optionsRef.current.onPreview(
          {
            pageNumber: entry.pageNumber,
            kind: "XYZ",
            left: entry.x,
            // Slightly above the entry's first baseline, matching where
            // hyperref destinations point (see useCitationHotspots).
            top: entry.y + 8,
            zoom: null,
          },
          entry.text,
          null,
        );
        return;
      }

      void locateRef(pdfDocument, detail.ref, lineCache, () => disposed)
        .then((target) => {
          if (disposed || !target) return;
          if (detail.action === "goto") {
            optionsRef.current.onNavigate(target);
          } else {
            optionsRef.current.onPreview(target, null, detail.ref);
          }
        })
        .catch((error: unknown) => {
          console.error("papernook: paper-ref resolution failed", error);
        });
    };

    window.addEventListener(PAPER_REF_EVENT, onPaperRef);
    return () => {
      disposed = true;
      window.removeEventListener(PAPER_REF_EVENT, onPaperRef);
    };
  }, [pdfDocument]);
}

"use client";

import {
  useCallback,
  useEffect,
  useRef,
  useState,
  type Dispatch,
  type RefObject,
  type SetStateAction,
} from "react";
import type {
  AnnotationEditorUIManager,
  PDFDocumentLoadingTask,
  PDFDocumentProxy,
} from "pdfjs-dist";
import type { PDFViewer } from "pdfjs-dist/web/pdf_viewer.mjs";
import {
  resolvePdfDestination,
  type ResolvedPdfDestination,
} from "@/lib/pdf/destinations";
import { normalizeEtag } from "@/lib/pdf/etag";
import {
  createPdfAutosave,
  type PdfAutosaveCoordinator,
} from "@/lib/pdf/autosave";
import type { Bibliography } from "@/lib/pdf/bibliography";
import {
  newerReadingPosition,
  scaleTransfers,
  parseReadingPosition,
  readingPositionFromUnknown,
  serializeReadingPosition,
  type ReadingPosition,
} from "@/lib/pdf/view/reading-position";
import type { ViewerEventBus } from "./useCitationHotspots";
import { installDarkPdfRendering } from "./rendering/darkPdfRendering";

const READING_POSITION_WRITE_DELAY_MS = 500;

export interface PdfReaderEditState {
  dirty: boolean;
  saving: boolean;
}

export type EditMode = "select" | "highlight" | "text" | "draw";

interface EditorTypes {
  NONE: number;
  HIGHLIGHT: number;
  FREETEXT: number;
  INK: number;
}

interface MutableAnnotationStorage {
  onSetModified: (() => void) | null;
  onResetModified: (() => void) | null;
  resetModified(): void;
  /** Content hash over real annotation edits; "" when nothing would save. */
  readonly serializable: { hash: string };
}

class PdfSaveConflictError extends Error {}

function errorMessage(payload: unknown, fallback: string): string {
  if (
    payload &&
    typeof payload === "object" &&
    "error" in payload &&
    typeof payload.error === "string"
  ) {
    return payload.error;
  }
  return fallback;
}

// localStorage throws in private browsing on some engines and when site
// data is blocked; a remembered position is a convenience, never worth a
// broken reader, so both directions swallow storage failures.
function readStoredReadingPosition(key: string): ReadingPosition | null {
  try {
    return parseReadingPosition(window.localStorage.getItem(key));
  } catch {
    return null;
  }
}

function writeStoredReadingPosition(key: string, position: ReadingPosition) {
  try {
    window.localStorage.setItem(key, serializeReadingPosition(position));
  } catch {
    // Nothing to recover: the next visit simply starts at page 1.
  }
}

function uiManagerFromEvent(event: unknown): AnnotationEditorUIManager | null {
  if (
    event &&
    typeof event === "object" &&
    "uiManager" in event &&
    event.uiManager &&
    typeof event.uiManager === "object"
  ) {
    return event.uiManager as AnnotationEditorUIManager;
  }
  return null;
}

interface UsePdfDocumentOptions {
  src: string;
  editable: boolean;
  appearance: "theme" | "light" | "dark";
  /**
   * localStorage key under which the last page and zoom are remembered and
   * restored on the next open. Omitted on surfaces (share links, the
   * viewer) that should always start from the top.
   */
  positionKey?: string;
  /**
   * Session-authed route (`/api/v1/papers/<topic>/<slug>/position`) that
   * mirrors the reading position per profile, so a paper resumes where the
   * same reader left it on another device. Omitted on logged-out surfaces
   * (share links, the viewer).
   */
  positionEndpoint?: string;
  onEditStateChange?(state: PdfReaderEditState): void;
  onDocumentSaved?(): void;
  /**
   * Receives the destination of an internal link clicked while
   * `hoverPreviewRequestedRef` is set, instead of the viewer scrolling to it.
   */
  onHoverPreview(target: ResolvedPdfDestination): void;
}

export interface PdfDocumentHandle {
  containerRef: RefObject<HTMLDivElement | null>;
  viewerRef: RefObject<HTMLDivElement | null>;
  pdfViewerRef: RefObject<PDFViewer | null>;
  etagRef: RefObject<string | null>;
  editorTypesRef: RefObject<EditorTypes | null>;
  autosaveRef: RefObject<PdfAutosaveCoordinator | null>;
  commitAnnotations(): void;
  /** pdf.js editor manager, published once the annotation layer is ready. */
  uiManagerRef: RefObject<AnnotationEditorUIManager | null>;
  pendingPenRef: RefObject<boolean>;
  dirtyRef: RefObject<boolean>;
  savingRef: RefObject<boolean>;
  /** Page and scale to re-apply on the next `pagesinit` (document remount). */
  restoreViewRef: RefObject<{ page: number; scale: number } | null>;
  /**
   * Marks the current view as chosen by the reader. The toolbar's page and
   * zoom buttons live outside the scroll container whose input listeners
   * feed `userMovedRef`, so the reader calls this from those handlers;
   * without it, toolbar-only navigation would never persist a position and
   * a late-arriving server position could yank the view away.
   */
  noteUserMove(): void;
  /**
   * Set by the reader while it synthesises a link click for a hover
   * preview; the link service then routes the destination to
   * `onHoverPreview`.
   */
  hoverPreviewRequestedRef: RefObject<boolean>;
  /** Latest bibliography scan; reset whenever the document remounts. */
  bibliographyRef: RefObject<Bibliography | null>;
  pdfDocument: PDFDocumentProxy | null;
  viewerBus: ViewerEventBus | null;
  pageNumber: number;
  pageCount: number;
  status: string;
  zoom: number;
  editMode: EditMode;
  setEditMode: Dispatch<SetStateAction<EditMode>>;
  editorReady: boolean;
  dirty: boolean;
  saving: boolean;
  saveStatus: string;
  setSaveStatus: Dispatch<SetStateAction<string>>;
  remoteUpdate: boolean;
  pencilMode: boolean;
  setPencilMode: Dispatch<SetStateAction<boolean>>;
  /** Bumping this remounts the document (after `restoreViewRef` is set). */
  setDocumentGeneration: Dispatch<SetStateAction<number>>;
}

/**
 * Owns the pdf.js viewer lifecycle for one `src`: dynamic import, viewer and
 * link-service construction, event-bus subscriptions, the streaming
 * document load, and (when editable) annotation dirty tracking plus the
 * autosave coordinator that PUTs the saved PDF back with if-match.
 */
export function usePdfDocument({
  src,
  editable,
  appearance,
  positionKey,
  positionEndpoint,
  onEditStateChange,
  onDocumentSaved,
  onHoverPreview,
}: UsePdfDocumentOptions): PdfDocumentHandle {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const viewerRef = useRef<HTMLDivElement | null>(null);
  const pdfViewerRef = useRef<PDFViewer | null>(null);
  const documentRef = useRef<PDFDocumentProxy | null>(null);
  const darkRef = useRef(false);
  const etagRef = useRef<string | null>(null);
  const editorTypesRef = useRef<EditorTypes | null>(null);
  const autosaveRef = useRef<PdfAutosaveCoordinator | null>(null);
  const uiManagerRef = useRef<AnnotationEditorUIManager | null>(null);
  const annotationRefreshRef = useRef<(() => void) | null>(null);
  const commitAnnotations = useCallback(() => {
    uiManagerRef.current?.commitOrRemove();
    annotationRefreshRef.current?.();
  }, []);
  const pendingPenRef = useRef(false);
  const dirtyRef = useRef(false);
  const savingRef = useRef(false);
  const restoreViewRef = useRef<{ page: number; scale: number } | null>(null);
  // True once the reader wheels, taps, or keys inside the current document,
  // or presses a toolbar page/zoom button (via `noteUserMove`); a server
  // position that arrives after that must not yank the view away. Only real
  // input sets it — programmatic restores fire the same
  // pagechanging/scalechanging events a person does.
  const userMovedRef = useRef(false);
  const hoverPreviewRequestedRef = useRef(false);
  const bibliographyRef = useRef<Bibliography | null>(null);
  const onEditStateChangeRef = useRef(onEditStateChange);
  const onDocumentSavedRef = useRef(onDocumentSaved);
  const onHoverPreviewRef = useRef(onHoverPreview);
  const [pdfDocument, setPdfDocument] = useState<PDFDocumentProxy | null>(null);
  const [viewerBus, setViewerBus] = useState<ViewerEventBus | null>(null);
  const [pageNumber, setPageNumber] = useState(1);
  const [pageCount, setPageCount] = useState(0);
  const [status, setStatus] = useState("Loading paper…");
  const [zoom, setZoom] = useState(100);
  const [editMode, setEditMode] = useState<EditMode>("select");
  const [editorReady, setEditorReady] = useState(false);
  const [dirty, setDirty] = useState(false);
  const [saving, setSaving] = useState(false);
  const [saveStatus, setSaveStatus] = useState("");
  const [remoteUpdate, setRemoteUpdate] = useState(false);
  const [documentGeneration, setDocumentGeneration] = useState(0);
  const [pencilMode, setPencilMode] = useState(false);

  useEffect(() => {
    onEditStateChangeRef.current = onEditStateChange;
  }, [onEditStateChange]);

  useEffect(() => {
    onDocumentSavedRef.current = onDocumentSaved;
  }, [onDocumentSaved]);

  useEffect(() => {
    onHoverPreviewRef.current = onHoverPreview;
  }, [onHoverPreview]);

  const noteUserMove = () => {
    userMovedRef.current = true;
  };

  useEffect(() => {
    const updateAppearance = () => {
      const dark =
        appearance === "dark" ||
        (appearance === "theme" &&
          document.documentElement.dataset.theme === "dark");
      if (darkRef.current === dark) return;
      darkRef.current = dark;
      const viewer = pdfViewerRef.current;
      if (!viewer) return;
      // refresh() skips re-rendering pages with restricted canvas scaling.
      // Keep the editor and annotation layers alive while replacing the paint.
      for (let index = 0; index < viewer.pagesCount; index++) {
        viewer.getPageView(index)?.reset({
          keepAnnotationLayer: true,
          keepAnnotationEditorLayer: true,
          keepXfaLayer: true,
          keepTextLayer: true,
          keepCanvasWrapper: true,
        });
      }
      viewer.update();
    };
    updateAppearance();
    const observer = new MutationObserver(updateAppearance);
    observer.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["data-theme"],
    });
    return () => observer.disconnect();
  }, [appearance]);

  useEffect(() => {
    const container = containerRef.current;
    const viewerElement = viewerRef.current;
    if (!container || !viewerElement) return;

    let disposed = false;
    let loadingTask: PDFDocumentLoadingTask | null = null;
    let viewerCleanup: (() => void) | null = null;
    let positionWriteTimer: ReturnType<typeof setTimeout> | null = null;
    let remotePosition: ReadingPosition | null = null;
    const abortController = new AbortController();

    userMovedRef.current = false;
    const markUserMoved = () => {
      userMovedRef.current = true;
    };
    container.addEventListener("wheel", markUserMoved, {
      signal: abortController.signal,
      passive: true,
    });
    container.addEventListener("pointerdown", markUserMoved, {
      signal: abortController.signal,
    });
    container.addEventListener("keydown", markUserMoved, {
      signal: abortController.signal,
    });

    void (async () => {
      try {
        const pdfjs = await import("pdfjs-dist");
        const { EventBus, LinkTarget, PDFLinkService, PDFViewer } =
          await import("pdfjs-dist/web/pdf_viewer.mjs");

        pdfjs.GlobalWorkerOptions.workerSrc = new URL(
          "pdfjs-dist/build/pdf.worker.min.mjs",
          import.meta.url,
        ).toString();

        const eventBus = new EventBus();
        const linkService = new PDFLinkService({
          eventBus,
          externalLinkTarget: LinkTarget.BLANK,
          externalLinkRel: "noopener noreferrer nofollow",
          ignoreDestinationZoom: true,
        });
        const pdfViewer = new PDFViewer({
          container,
          viewer: viewerElement,
          eventBus,
          linkService,
          removePageBorders: true,
          imageResourcesPath: "/offline/pdf/images/",
          annotationEditorMode: editable
            ? pdfjs.AnnotationEditorType.NONE
            : pdfjs.AnnotationEditorType.DISABLE,
          annotationEditorHighlightColors:
            "Yellow=#fff066,Green=#8ee3a1,Blue=#8dc8ff,Pink=#ff9cce",
          enableSelectionRendering: true,
        });
        pdfViewerRef.current = pdfViewer;
        editorTypesRef.current = pdfjs.AnnotationEditorType;
        linkService.setViewer(pdfViewer);

        const originalGoToDestination =
          linkService.goToDestination.bind(linkService);
        linkService.goToDestination = async (destination) => {
          if (!hoverPreviewRequestedRef.current)
            return originalGoToDestination(destination);
          const document = documentRef.current;
          if (!document) return;
          const target = await resolvePdfDestination(document, destination);
          if (!target) {
            await originalGoToDestination(destination);
            return;
          }
          onHoverPreviewRef.current(target);
        };
        setViewerBus(eventBus);

        // Page and zoom are written together, so a stored position is
        // always a pair the viewer actually showed. Debounced: the wheel and
        // pinch fire scalechanging dozens of times a second.
        const flushReadingPosition = () => {
          positionWriteTimer = null;
          // Only a position the reader chose by hand may be stamped and
          // persisted. pagesinit restores and applyRemotePosition fire the
          // same pagechanging/scalechanging events real moves do; stamping
          // those with a fresh Date.now() would clobber the server copy on
          // every open and let a restamped local copy beat a genuinely
