      document.removeEventListener("click", saveBeforeClientNavigation, true);
  }, [editable, dirtyRef, autosaveRef, commentDirtyRef, commitAnnotations]);
}

"use client";

import { useEffect, useId, useRef, useState } from "react";
import Image from "next/image";
import Link from "next/link";
import { ThemeToggle } from "./ThemeToggle";
import { clearOfflineForAuthentication } from "@/lib/offline/storage";
import styles from "./AccountBar.module.css";

/**
 * Netflix-style account control: the round avatar sits top-right; clicking
 * it opens the menu (Settings, Switch profile, Log out). Switching is free,
 * the session already proves the access password; logging out closes the
 * gate so the next visitor needs the password again.
 */

interface AccountBarProps {
  displayName: string;
  avatarSlug: string;
}

export function AccountBar({ displayName, avatarSlug }: AccountBarProps) {
  const menuId = useId();
  const [open, setOpen] = useState(false);
  const [loggingOut, setLoggingOut] = useState(false);
  const [logoutError, setLogoutError] = useState<string | null>(null);
  const rootRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!open) return;
    const close = (e: MouseEvent) => {
      if (!rootRef.current?.contains(e.target as Node)) setOpen(false);
    };
    window.addEventListener("mousedown", close);
    return () => window.removeEventListener("mousedown", close);
  }, [open]);

  async function logout(): Promise<void> {
    if (loggingOut) return;
    setLoggingOut(true);
    setLogoutError(null);
    try {
      const response = await fetch("/api/v1/session", {
        method: "DELETE",
        credentials: "include",
      });
      if (!response.ok) throw new Error("Could not log out. Try again.");
      await clearOfflineForAuthentication();
      window.location.replace("/login");
    } catch {
      setLogoutError("Could not log out. Try again.");
      setLoggingOut(false);
    }
  }

  return (
    <div className={styles.root} ref={rootRef}>
      <Link className={styles.brand} href="/" aria-label="papernook home">
        <Image
          src="/logo.svg"
          width={32}
          height={30}
          alt=""
          className={styles.logo}
        />
        <span>papernook</span>
      </Link>
      <div className={styles.controls}>
        <ThemeToggle />
        <button
          type="button"
          className={styles.avatarBtn}
          onClick={() => setOpen((o) => !o)}
          aria-expanded={open}
          aria-controls={menuId}
          aria-label={`Account menu for ${displayName}`}
        >
          <Image
            src={`/avatars/${avatarSlug}.png`}
            alt=""
            width={40}
            height={40}
            className={styles.avatar}
          />
        </button>
      </div>
      {open && (
        <div className={styles.menu} id={menuId} aria-label="Account options">
          <p className={styles.menuWho}>
            <Image
              src={`/avatars/${avatarSlug}.png`}
              alt=""
              width={28}
              height={28}
              className={styles.avatar}
            />
            {displayName}
          </p>
          <Link href="/graph" onClick={() => setOpen(false)}>
            Graph
          </Link>
          <Link href="/settings" onClick={() => setOpen(false)}>
            Settings
          </Link>
          <a href="/offline/index.html">Downloads</a>
          <Link href="/login" onClick={() => setOpen(false)}>
            Switch profile
          </Link>
          <button
            type="button"
            disabled={loggingOut}
            onClick={() => void logout()}
          >
            Log out
          </button>
          {logoutError && <p role="alert">{logoutError}</p>}
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import styles from "./AdminMembers.module.css";

/** Admin-only member list with complete profile erasure. */

interface Member {
  username: string;
  displayName: string;
  isAdmin: boolean;
}

interface PendingErasure {
  username: string;
  status: "pending" | "waiting" | "failed";
}

export function AdminMembers({ members }: { members: Member[] }) {
  const [visible, setVisible] = useState(members);
  const [removing, setRemoving] = useState(false);
  const mutation = useRef<AbortController | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [statusError, setStatusError] = useState<string | null>(null);
  const [pending, setPending] = useState<PendingErasure[]>([]);
  const [workerRunning, setWorkerRunning] = useState(true);
  const [authorized, setAuthorized] = useState(true);
  const [refresh, setRefresh] = useState(0);
  const epoch = useRef(0);
  useEffect(
    () => () => {
      epoch.current += 1;
      mutation.current?.abort();
    },
    [],
  );

  useEffect(() => {
    const controller = new AbortController();
    const admittedEpoch = epoch.current;
    let timer: ReturnType<typeof setTimeout> | undefined;
    async function poll(): Promise<void> {
      if (controller.signal.aborted || admittedEpoch !== epoch.current) return;
      try {
        const response = await fetch("/api/v1/profiles", {
          credentials: "include",
          cache: "no-store",
          signal: controller.signal,
        });
        if (controller.signal.aborted || admittedEpoch !== epoch.current)
          return;
        if (response.status === 401 || response.status === 403) {
          setAuthorized(false);
          setPending([]);
          setVisible([]);
          return;
        }
        if (!response.ok)
          throw new Error(
            "Cleanup status could not be refreshed. The displayed status may be out of date.",
          );
        const body = (await response.json()) as {
          owner?: boolean;
          profiles: Member[];
          erasures?: { workerRunning: boolean; profiles: PendingErasure[] };
        };
        if (controller.signal.aborted || admittedEpoch !== epoch.current)
          return;
        if (!body.owner || !body.erasures) {
          setAuthorized(false);
          setPending([]);
          setVisible([]);
          return;
        }
        setAuthorized(true);
        setVisible(body.profiles);
        setPending(body.erasures.profiles);
        setWorkerRunning(body.erasures.workerRunning);
        setStatusError(null);
      } catch {
        if (controller.signal.aborted || admittedEpoch !== epoch.current)
          return;
        setStatusError(
          "Cleanup status could not be refreshed. The displayed status may be out of date.",
        );
      }
      if (!controller.signal.aborted && admittedEpoch === epoch.current)
        timer = setTimeout(() => void poll(), 5000);
    }
    void poll();
    return () => {
      controller.abort();
      if (timer) clearTimeout(timer);
    };
  }, [refresh]);

  async function remove(username: string): Promise<void> {
    if (!authorized || mutation.current) return;
    if (
      !window.confirm(
        `Completely remove ${username}? Their profile, chats, captures, and owned share links will be erased. Shared confirmed papers remain.`,
      )
    ) {
      return;
    }
    setError(null);
    const admittedEpoch = ++epoch.current;
    const controller = new AbortController();
    mutation.current = controller;
    setRemoving(true);
    try {
      const res = await fetch(`/api/v1/profiles/${username}`, {
        method: "DELETE",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        signal: controller.signal,
        body: JSON.stringify({ confirmation: username }),
      });
      if (controller.signal.aborted || admittedEpoch !== epoch.current) return;
      if (res.status === 401 || res.status === 403) {
        setError(
          "The server did not authorize removal. Verify your account before trying again.",
        );
        setAuthorized(false);
        setPending([]);
        setVisible([]);
        return;
      }
      if (res.ok) {
        setVisible((entries) =>
          entries.filter((entry) => entry.username !== username),
        );
        setPending((entries) => [
          ...entries.filter((entry) => entry.username !== username),
          { username, status: "pending" },
        ]);
      } else {
        const body = (await res.json().catch(() => ({}))) as { error?: string };
        if (controller.signal.aborted || admittedEpoch !== epoch.current)
          return;
        setError(body.error ?? "Could not remove the profile.");
      }
    } catch {
      if (controller.signal.aborted || admittedEpoch !== epoch.current) return;
      setError(
        "Could not confirm profile removal. Refresh the page before trying again.",
      );
    } finally {
      mutation.current = null;
      if (!controller.signal.aborted && admittedEpoch === epoch.current) {
        epoch.current += 1;
        setRemoving(false);
        setRefresh((value) => value + 1);
      }
    }
  }

  if (!authorized) return <p>Owner access is required to manage members.</p>;
  return (
    <div>
      <ul className={styles.list}>
        {visible.map((m) => (
          <li key={m.username} className={styles.row}>
            <span>
              {m.displayName}{" "}
              {m.displayName.trim().toLocaleLowerCase() !==
                m.username.toLocaleLowerCase() && (
                <code>{m.username}</code>
              )}{" "}
              {m.isAdmin && <strong>(admin)</strong>}
            </span>
            {!m.isAdmin && (
              <button
                type="button"
                className={styles.remove}
                disabled={removing}
                onClick={() => void remove(m.username)}
              >
                Remove completely
              </button>
            )}
          </li>
        ))}
      </ul>
      {pending.length > 0 && (
        <div aria-live="polite">
          <h4>Pending erasure</h4>
          <p>
            Access is revoked. Private file cleanup continues in the background.
          </p>
          <ul className={styles.list}>
            {pending.map((entry) => (
              <li key={entry.username} className={styles.row}>
                <span>{entry.username}</span>
                <span>
                  {entry.status === "failed"
                    ? "Cleanup needs attention. Automatic retries continue."
                    : entry.status === "waiting"
                      ? "Waiting for active work to finish."
                      : "Cleanup queued."}
                </span>
              </li>
            ))}
          </ul>
          {!workerRunning && (
            <p className={styles.error}>
              The cleanup worker is not running in this server process. Check
              the local access migration and server logs.
            </p>
          )}
        </div>
      )}
      {statusError && (
        <p className={styles.error} role="alert">
          {statusError}
        </p>
      )}
      {error && (
        <p className={styles.error} role="alert">
          {error}
        </p>
      )}
    </div>
  );
}

"use client";

import Image from "next/image";
import { useRouter } from "next/navigation";
import { useState } from "react";
import { ANIMAL_AVATARS } from "@/lib/auth/avatars";
import styles from "./AvatarPicker.module.css";

interface AvatarPickerProps {
  username: string;
  avatarSlug: string;
}

export function AvatarPicker({ username, avatarSlug }: AvatarPickerProps) {
  const router = useRouter();
  const [savedSlug, setSavedSlug] = useState(avatarSlug);
  const [selectedSlug, setSelectedSlug] = useState(avatarSlug);
  const [busy, setBusy] = useState(false);
  const [feedback, setFeedback] = useState<{
    tone: "success" | "error";
    message: string;
  } | null>(null);

  async function save(): Promise<void> {
    setBusy(true);
    setFeedback(null);
    try {
      const response = await fetch(`/api/v1/profiles/${username}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({ avatarSlug: selectedSlug }),
      });
      const data = (await response.json().catch(() => ({}))) as {
        error?: string;
      };
      if (!response.ok) {
        setFeedback({
          tone: "error",
          message: data.error ?? "Could not save the avatar.",
        });
        return;
      }
      setSavedSlug(selectedSlug);
      setFeedback({ tone: "success", message: "Avatar saved." });
      router.refresh();
    } catch {
      setFeedback({
        tone: "error",
        message: "Could not save the avatar. Check the server connection.",
      });
    } finally {
      setBusy(false);
    }
  }

  return (
    <div className={styles.root}>
      <div
        className={styles.options}
        role="radiogroup"
        aria-label="Choose your avatar"
      >
        {ANIMAL_AVATARS.map((avatar) => {
          const selected = avatar.slug === selectedSlug;
          return (
            <button
              key={avatar.slug}
              type="button"
              role="radio"
              aria-checked={selected}
              aria-label={avatar.name}
              className={`${styles.option} ${selected ? styles.optionSelected : ""}`}
              onClick={() => {
                setSelectedSlug(avatar.slug);
                setFeedback(null);
              }}
              disabled={busy}
            >
              <Image
                src={`/avatars/${avatar.slug}.png`}
                alt=""
                width={64}
                height={64}
              />
              <span>{avatar.name}</span>
            </button>
          );
        })}
      </div>
      <div className={styles.actions}>
        <button
          type="button"
          className={styles.save}
          onClick={() => void save()}
          disabled={busy || selectedSlug === savedSlug}
        >
          {busy ? "Saving…" : "Save avatar"}
        </button>
        {feedback && (
          <p
            className={
              feedback.tone === "error" ? styles.error : styles.success
            }
            role={feedback.tone === "error" ? "alert" : "status"}
          >
            {feedback.message}
          </p>
        )}
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import styles from "./DeleteProfile.module.css";

export function DeleteProfile({ username }: { username: string }) {
  const router = useRouter();
  const [open, setOpen] = useState(false);
  const [confirmation, setConfirmation] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  async function erase(): Promise<void> {
    if (confirmation !== username || busy) return;
    setBusy(true);
    setError(null);
    const response = await fetch(`/api/v1/profiles/${username}`, {
      method: "DELETE",
      headers: { "Content-Type": "application/json" },
      credentials: "include",
      body: JSON.stringify({ confirmation }),
    });
    if (!response.ok) {
      const body = (await response.json().catch(() => ({}))) as {
        error?: string;
      };
      setError(body.error ?? "Could not delete the profile.");
      setBusy(false);
      return;
    }
    router.replace("/login");
    router.refresh();
  }

  if (!open) {
    return (
      <button
        type="button"
        className={styles.open}
        onClick={() => setOpen(true)}
      >
        Delete my profile and data
      </button>
    );
  }

  return (
    <div className={styles.confirm} role="group" aria-label="Delete profile">
      <p>
        This permanently removes your profile, capture token, Zotero connection,
        chats, pasted chat images, pending captures, and owned share links.
        Confirmed papers and shared annotations remain, without your profile
        attribution.
      </p>
      <label htmlFor="delete-profile-confirmation">
        Type <code>{username}</code> to confirm
      </label>
      <input
        id="delete-profile-confirmation"
        value={confirmation}
        onChange={(event) => setConfirmation(event.target.value)}
        autoComplete="off"
      />
      {error && (
        <p className={styles.error} role="alert">
          {error}
        </p>
      )}
      <div className={styles.actions}>
        <button
          type="button"
          className={styles.cancel}
          onClick={() => {
            setOpen(false);
            setConfirmation("");
            setError(null);
          }}
          disabled={busy}
        >
          Cancel
        </button>
        <button
          type="button"
          className={styles.erase}
          onClick={() => void erase()}
          disabled={busy || confirmation !== username}
        >
          {busy ? "Deleting…" : "Delete permanently"}
        </button>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import {
  ProviderFields,
  AccessVerification,
  type ProviderFieldsPatch,
  type ProviderFieldStatus,
} from "thesidedoor/react";
import type { ProviderDescriptor } from "thesidedoor-core/ai/browser";
import styles from "./ModelPicker.module.css";

/**
 * Admin control: which provider answers (claude-code, codex, or an API key)
 * and with which of its currently offered models. The model list is live
 * from the provider's API when reachable, curated otherwise.
 */

type Readiness =
  | "ready"
  | "no_key"
  | "no_model"
  | "not_installed"
  | "not_authenticated"
  | "unreachable"
  | "checking";

const READINESS_LABEL: Record<Readiness, string> = {
  ready: "ready",
  no_key: "needs API key",
  no_model: "select a model",
  not_installed: "CLI not installed",
  not_authenticated: "CLI needs login",
  unreachable: "endpoint or SSH host not answering",
  checking: "checking availability",
};

interface AgentState {
  revision: number;
  descriptor?: ProviderDescriptor;
  credentialFields?: ProviderFieldStatus[];
  credentialError?: boolean;
  provider: string | null;
  statuses: Record<string, Readiness>;
  model: string | null;
  effort: string | null;
  effortOptions: string[];
  defaultEffort: string | null;
  baseUrl: string | null;
  baseUrlPlaceholder: string | null;
  endpointConfigurable: boolean;
  suggestions: string[];
  liveList: boolean;
  discoveryError?: string | null;
  admin: boolean;
  available?: boolean;
  webAccess: boolean;
  webCapable: boolean;
  credentialReloadAvailable: boolean;
}

interface Feedback {
  tone: "info" | "success" | "error";
  label: string;
  message: string;
}

export function ModelPicker() {
  const [state, setState] = useState<AgentState | null>(null);
  const [value, setValue] = useState("");
  const [baseUrl, setBaseUrl] = useState("");
  const [feedback, setFeedback] = useState<Feedback | null>(null);
  const [busy, setBusy] = useState(false);
  const [credentialPatch, setCredentialPatch] = useState<ProviderFieldsPatch>(
    {},
  );
  const [resetCredentials, setResetCredentials] = useState(false);
  const requestVersion = useRef(0);
  const draftRevision = useRef<number | null>(null);
  const [settingsChanged, setSettingsChanged] = useState(false);
  const [verificationRequired, setVerificationRequired] = useState(false);

  async function refreshDetails(
    version: number,
    announce: boolean,
  ): Promise<void> {
    try {
      const response = await fetch("/api/v1/agent/model?probe=1", {
        credentials: "include",
      });
      if (version !== requestVersion.current) return;
      if (response.status === 401 || response.status === 403) {
        setCredentialPatch({});
        setResetCredentials(false);
        setState(null);
        return;
      }
      if (!response.ok) throw new Error("Availability request failed");
      const data = (await response.json()) as AgentState;
      if (version !== requestVersion.current) return;
      if (data.revision !== draftRevision.current) {
        setSettingsChanged(true);
        return;
      }
      setState(data);
      if (announce) {
        setFeedback(
          data.available
            ? {
                tone: "success",
                label: "Provider ready",
                message: `${data.provider} answers with ${data.model ?? "its default model"} at ${data.effort ?? data.defaultEffort ?? "default"} effort.`,
              }
            : {
                tone: "error",
                label: "Provider unavailable",
                message: `Saved, but ${data.provider} is not answering. It may need its CLI, key, or SSH host on the server.`,
              },
        );
      }
    } catch {
      if (announce && version === requestVersion.current) {
        setFeedback({
          tone: "error",
          label: "Availability check failed",
          message: "Saved. Could not refresh provider availability.",
        });
      }
    }
  }

  useEffect(() => {
    const version = requestVersion.current;
    void fetch("/api/v1/agent/model", { credentials: "include" })
      .then((r) => r.json())
      .then((d: AgentState) => {
        if (version !== requestVersion.current) return;
        setState(d);
        draftRevision.current = d.revision;
        setValue(d.model ?? "");
        setBaseUrl(d.baseUrl ?? "");
        void refreshDetails(version, false);
      });
  }, []);

  if (!state?.admin) return null;
  const draftModel = value.trim() || null;
  const modelChanged = draftModel !== state.model;
  const draftBaseUrl = baseUrl.trim() || null;
  const endpointChanged = draftBaseUrl !== state.baseUrl;

  async function save(body: {
    provider?: string;
    model?: string | null;
    effort?: string | null;
    baseUrl?: string | null;
    webAccess?: boolean;
    credentials?: ProviderFieldsPatch;
    resetCredentials?: boolean;
  }): Promise<void> {
    const version = requestVersion.current + 1;
    requestVersion.current = version;
    setBusy(true);
    setFeedback(null);
    try {
      const res = await fetch("/api/v1/agent/model", {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({ ...body, revision: draftRevision.current }),
      });
      const data = (await res.json()) as AgentState & { error?: string };
      if (!res.ok) {
        if (res.status === 409) setSettingsChanged(true);
        if (res.status === 401) setVerificationRequired(true);
        setFeedback({
          tone: "error",
          label: "Settings not saved",
          message: data.error ?? "Could not save.",
        });
        return;
      }
      setState(data);
      draftRevision.current = data.revision;
      setSettingsChanged(false);
      setValue(data.model ?? "");
      setBaseUrl(data.baseUrl ?? "");
      setCredentialPatch({});
      setResetCredentials(false);
      setFeedback({
        tone: "info",
        label: "Settings saved",
        message: "Checking provider availability…",
      });
      void refreshDetails(version, true);
    } catch {
      setFeedback({
        tone: "error",
        label: "Settings not saved",
        message: "Could not save. Check the server connection and try again.",
      });
    } finally {
      setBusy(false);
    }
  }

  async function reloadCredentials(): Promise<void> {
    if (
      !window.confirm(
        "Reload the latest CLI login from this server? Active chats are not interrupted.",
      )
    ) {
      return;
    }
    setBusy(true);
    setFeedback({
      tone: "info",
      label: "Reloading CLI login",
      message: "Reading the latest credentials from this server…",
    });
    try {
      const response = await fetch("/api/v1/settings/credentials", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
      });
      const data = (await response.json()) as {
        error?: string;
        outcome?: "installed" | "skipped" | "removed";
        readiness?: Readiness;
      };
      if (!response.ok) {
        setFeedback({
          tone: "error",
          label: "CLI login not reloaded",
          message: data.error ?? "Could not reload CLI login.",
        });
        return;
      }
      const version = requestVersion.current + 1;
      requestVersion.current = version;
      // Say what actually happened. A refused older snapshot leaves the newer
      // token in place, which is the right outcome but reads as a no-op, and
      // "reloaded" would be a lie.
      const outcomeMessage =
        data.outcome === "skipped"
          ? "This server already had a newer login than the host copy, so it was kept."
          : data.outcome === "removed"
            ? "The host is signed out, so the login here was removed too."
            : "The provider is ready.";
      setFeedback(
        data.readiness === "ready"
          ? {
              tone: "success",
              label:
                data.outcome === "skipped"
                  ? "Kept the newer login"
                  : "CLI login reloaded",
              message: outcomeMessage,
            }
          : {
              tone: "error",
              label: "Provider still unavailable",
              message:
                data.outcome === "removed"
                  ? "The host is signed out, so this server has no login."
                  : "CLI login reloaded, but the provider still needs login.",
            },
      );
      await refreshDetails(version, false);
    } catch {
      setFeedback({
        tone: "error",
        label: "CLI login not reloaded",
        message: "Could not reload CLI login. Check the server connection.",
      });
    } finally {
      setBusy(false);
    }
  }

  async function testModel(): Promise<void> {
    setBusy(true);
    setFeedback({
      tone: "info",
      label: "Testing selected model",
      message: "Waiting for one short response…",
    });
    try {
      const response = await fetch("/api/v1/agent/test", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({}),
      });
      const data = (await response.json()) as {
        error?: string;
        provider?: string;
        reply?: string;
        elapsedMs?: number;
      };
      if (!response.ok) {
        setFeedback({
          tone: "error",
          label: "Model test failed",
          message: data.error ?? "The selected model did not answer.",
        });
        return;
      }
      const seconds = ((data.elapsedMs ?? 0) / 1000).toFixed(1);
      setFeedback({
        tone: "success",
        label: "Model test passed",
        message: `${data.provider} answered in ${seconds}s: ${data.reply ?? "(empty response)"}`,
      });
    } catch {
      setFeedback({
        tone: "error",
        label: "Model test failed",
        message: "Could not test the model. Check the server connection.",
      });
    } finally {
      setBusy(false);
    }
  }

  return (
    <div className={styles.root}>
      {verificationRequired && (
        <>
          <AccessVerification
            endpoint="/api/v1/access"
            disabled={busy}
            classes={{
              form: styles.root,
              label: styles.line,
              input: styles.input,
              button: styles.save,
              secondary: styles.secondaryAction,
              hint: styles.hint,
              error: styles.hint,
            }}
            onVerified={() => {
              setVerificationRequired(false);
              setFeedback({
                tone: "info",
                label: "Identity verified",
                message: "Your edits are still here. Save them when ready.",
              });
            }}
          />
          <p className={styles.hint}>
            If your session has ended, <a href="/login">sign in again</a>.
          </p>
        </>
      )}
      {settingsChanged && (
        <p role="alert" className={styles.hint}>
          Settings changed in another session. Your edits have not been saved.{" "}
          <button
            type="button"
            className={styles.secondaryAction}
            onClick={() => window.location.reload()}
          >
            Discard edits and reload settings
          </button>
        </p>
      )}
      <div className={styles.current} aria-live="polite">
        <span className={styles.currentLabel}>Current</span>
        <span className={styles.currentValue}>
          <strong>{state.provider ?? "Not configured"}</strong>
          {state.provider && <span aria-hidden="true">/</span>}
          {state.provider && <code>{state.model ?? "provider default"}</code>}
          {state.provider && state.effort && <code>{state.effort} effort</code>}
        </span>
      </div>
      {state.provider && (
        <div className={styles.reloadRow}>
          <button
            type="button"
            className={styles.secondaryAction}
            disabled={busy}
            onClick={() => void testModel()}
          >
            Test selected model
          </button>
          <span className={styles.hint}>
            Sends one short prompt without web access or chat history.
          </span>
        </div>
      )}
      {feedback && (
        <div
          className={styles.status}
          data-tone={feedback.tone}
          role={feedback.tone === "error" ? "alert" : "status"}
          aria-atomic="true"
        >
          <span className={styles.statusMark} aria-hidden="true">
            {feedback.tone === "error"
              ? "!"
              : feedback.tone === "success"
                ? "✓"
                : "…"}
          </span>
          <span className={styles.statusCopy}>
            <strong>{feedback.label}</strong>
            <span>{feedback.message}</span>
          </span>
        </div>
      )}
      <p className={styles.line}>Provider</p>
      <div className={styles.controls}>
        {Object.entries(state.statuses).map(([p, readiness]) => (
          <button
            key={p}
            type="button"
            className={state.provider === p ? styles.chipActive : styles.chip}
            onClick={() => void save({ provider: p })}
            disabled={busy || state.provider === p}
            aria-pressed={state.provider === p}
            aria-label={`${p}: ${READINESS_LABEL[readiness]}`}
            title={
              readiness === "ready" ? undefined : READINESS_LABEL[readiness]
            }
          >
            <span
              className={
                readiness === "ready"
                  ? styles.readyDot
                  : readiness === "checking"
                    ? styles.checkingDot
                    : styles.notReadyDot
              }
              aria-hidden="true"
            />
            {p}
            {readiness !== "ready" && readiness !== "checking" && (
              <span className={styles.readinessNote}>
                {READINESS_LABEL[readiness]}
              </span>
            )}
          </button>
        ))}
      </div>
      {state.credentialReloadAvailable && (
        <div className={styles.reloadRow}>
          <button
            type="button"
            className={styles.secondaryAction}
            disabled={busy}
            onClick={() => void reloadCredentials()}
          >
            Reload CLI login
          </button>
          <span className={styles.hint}>
            Use after signing in or out with the CLI on this server.
          </span>
        </div>
      )}
      {state.provider === "codex" && (
        <p className={styles.hint} role="note">
          Heads up: codex runs with a read-only sandbox that can still read
          library data if a malicious paper prompt-injects a turn. On a public
          instance with several profiles, only keep it selected if you trust
          every account holder.
        </p>
      )}
      {state.webCapable && (
        <>
          <p className={styles.line}>Web access</p>
          <div className={styles.switchRow}>
            <button
              type="button"
              className={styles.switch}
              role="switch"
              aria-checked={state.webAccess}
              aria-label="Allow chats to search the web"
              disabled={busy}
              onClick={() => void save({ webAccess: !state.webAccess })}
            >
              <span className={styles.switchTrack} aria-hidden="true">
                <span className={styles.switchThumb} />
              </span>
              <span className={styles.switchText}>
                <strong>{state.webAccess ? "On" : "Off"}</strong>
                <span>Chats may search the web</span>
              </span>
            </button>
          </div>
          <p className={styles.hint}>
            On by default. A malicious paper could steer a web request. Answers
            gain live lookups; nothing on this server becomes readable.
          </p>
        </>
      )}
      {state.endpointConfigurable && (
        <>
          <p className={styles.line}>
            Endpoint{" "}
            <span className={styles.hint}>
              (HTTP(S), reachable from the papernook server)
            </span>
          </p>
          <div className={styles.controls}>
            <input
              className={styles.input}
              value={baseUrl}
              onChange={(e) => setBaseUrl(e.target.value)}
              placeholder={
                state.baseUrlPlaceholder ??
                (state.provider === "openai"
                  ? "https://api.openai.com/v1"
                  : "http://localhost:8000")
              }
              onKeyDown={(e) => {
                if (e.key === "Enter") {
                  void save({ baseUrl: baseUrl.trim() || null });
                }
              }}
              disabled={busy}
              inputMode="url"
            />
            <button
              type="button"
              className={styles.save}
              onClick={() => void save({ baseUrl: draftBaseUrl })}
              disabled={busy || !endpointChanged}
            >
              Save endpoint
            </button>
          </div>
        </>
      )}
      {state.descriptor &&
        state.descriptor.fields.some((field) => field.id !== "baseUrl") && (
          <>
            <p className={styles.line}>Provider credentials</p>
            <ProviderFields
              descriptor={{
                ...state.descriptor,
                fields: state.descriptor.fields.filter(
                  (field) => field.id !== "baseUrl",
                ),
              }}
              fields={state.credentialFields}
              patch={credentialPatch}
              onChange={setCredentialPatch}
              disabled={busy}
              error={state.credentialError}
              reset={resetCredentials}
              onResetChange={setResetCredentials}
              classes={{
                root: styles.root,
                field: styles.reloadRow,
                label: styles.line,
                input: styles.input,
                button: styles.secondaryAction,
                hint: styles.hint,
                error: styles.hint,
              }}
            />
            <button
              type="button"
              className={styles.save}
              disabled={
                busy ||
                (!resetCredentials && Object.keys(credentialPatch).length === 0)
              }
              onClick={() =>
                void save({ credentials: credentialPatch, resetCredentials })
              }
            >
              Save credentials
            </button>
          </>
        )}
      <p className={styles.line}>
        Model{" "}
        <span className={styles.hint}>
          {state.liveList
            ? "(live list from the provider)"
            : state.provider === "claude-code"
              ? "(aliases track the latest release; exact ids also work)"
              : "(common choices; any id the provider accepts works)"}
        </span>
      </p>
      {state.discoveryError && (
        <p role="status" className={styles.hint}>
          {state.discoveryError}
        </p>
      )}
      <div className={styles.controls}>
        {state.suggestions.slice(0, 8).map((s) => (
          <button
            key={s}
            type="button"
            className={state.model === s ? styles.chipActive : styles.chip}
            onClick={() => void save({ model: s })}
            disabled={busy || state.model === s}
            aria-pressed={state.model === s}
          >
            {s}
          </button>
        ))}
      </div>
      <div className={styles.controls}>
        <input
          className={styles.input}
          value={value}
          onChange={(e) => setValue(e.target.value)}
          placeholder="custom model id (empty = provider default)"
          onKeyDown={(e) => {
            if (e.key === "Enter") void save({ model: value.trim() || null });
          }}
          disabled={busy}
        />
        <button
          type="button"
          className={styles.save}
          onClick={() => void save({ model: draftModel })}
          disabled={busy || !modelChanged}
        >
          Save
        </button>
      </div>
      {modelChanged && <p className={styles.draftNote}>Unsaved model change</p>}
      {state.effortOptions.length > 0 && (
        <>
          <p className={styles.line}>
            Thinking effort{" "}
            <span className={styles.hint}>
              {state.defaultEffort
                ? `(model default: ${state.defaultEffort})`
                : "(default follows the selected model)"}
            </span>
          </p>
          <div className={styles.controls}>
            <button
              type="button"
              className={
                state.effort === null ? styles.chipActive : styles.chip
              }
              onClick={() => void save({ effort: null })}
              disabled={busy || state.effort === null}
              aria-pressed={state.effort === null}
            >
              Default
            </button>
            {state.effortOptions.map((effort) => (
              <button
                key={effort}
                type="button"
                className={
                  state.effort === effort ? styles.chipActive : styles.chip
                }
                onClick={() => void save({ effort })}
                disabled={busy || state.effort === effort}
                aria-pressed={state.effort === effort}
              >
                {effort}
              </button>
            ))}
          </div>
        </>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import Image from "next/image";
import { useRouter } from "next/navigation";
import { Plus, Check, X } from "lucide-react";
import { ANIMAL_AVATARS } from "@/lib/auth/avatars";
import {
  clearOfflineForAuthentication,
  setOfflineIdentity,
} from "@/lib/offline/storage";
import styles from "./ProfilePicker.module.css";

export interface PickerProfile {
  username: string;
  displayName: string;
  avatarSlug: string;
  isAdmin: boolean;
}

interface ProfilePickerProps {
  profiles: PickerProfile[];
}

type Editor = { mode: "create" } | null;

export function ProfilePicker({ profiles }: ProfilePickerProps) {
  const router = useRouter();
  const [editor, setEditor] = useState<Editor>(null);
  const [name, setName] = useState("");
  const [avatarSlug, setAvatarSlug] = useState(ANIMAL_AVATARS[0].slug);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  async function login(username: string): Promise<void> {
    setBusy(true);
    setError(null);
    try {
      await clearOfflineForAuthentication();
      const res = await fetch("/api/v1/session", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({ username }),
      });
      const body = (await res.json().catch(() => ({}))) as { error?: string };
      if (!res.ok) {
        throw new Error(body.error ?? "Could not sign in.");
      }
      try {
        await setOfflineIdentity(username);
      } catch {
        /* Online sign-in succeeds; denied offline storage stays revoked. */
      }
      router.push("/");
      router.refresh();
    } catch (e) {
      setError(e instanceof Error ? e.message : "Could not sign in.");
      setBusy(false);
    }
  }

  function pick(profile: PickerProfile): void {
    if (busy) return;
    // Past the access gate everyone is a trusted member of the household, so
    // picking a profile signs straight in — no second credential.
    void login(profile.username);
  }

  async function saveCreate(): Promise<void> {
    setBusy(true);
    setError(null);
    try {
      const res = await fetch("/api/v1/profiles", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({
          displayName: name.trim(),
          avatarSlug,
        }),
      });
      const body = (await res.json().catch(() => ({}))) as {
        error?: string;
        profile?: { username: string };
      };
      if (!res.ok || !body.profile)
        throw new Error(body.error ?? "Could not create the profile.");
      setBusy(false);
      await login(body.profile.username);
    } catch (e) {
      setError(
        e instanceof Error ? e.message : "Could not create the profile.",
      );
      setBusy(false);
    }
  }

  function closeEditor(): void {
    setEditor(null);
    setError(null);
  }

  if (editor?.mode === "create") {
    return (
      <div className={styles.root}>
        <div className={styles.brand}>papernook</div>
        <div
          className={styles.panel}
          role="dialog"
          aria-modal="true"
          aria-label="Add a profile"
        >
          <h1 className={styles.panelTitle}>Add a profile</h1>
          <label className={styles.fieldLabel} htmlFor="profile-name">
            Name
          </label>
          <input
            id="profile-name"
            className={styles.nameInput}
            value={name}
            onChange={(e) => setName(e.target.value)}
            maxLength={40}
            placeholder="e.g. Andres"
            autoFocus
          />
          <span className={styles.fieldLabel}>Avatar</span>
          <div
            className={styles.animalGrid}
            role="radiogroup"
            aria-label="Choose an avatar"
          >
            {ANIMAL_AVATARS.map((a) => {
              const selected = a.slug === avatarSlug;
              return (
                <button
                  key={a.slug}
                  type="button"
                  role="radio"
                  aria-checked={selected}
                  aria-label={a.name}
                  className={`${styles.animalTile} ${selected ? styles.animalTileSelected : ""}`}
                  onClick={() => setAvatarSlug(a.slug)}
                >
                  <Image
                    src={`/avatars/${a.slug}.png`}
                    alt=""
                    width={64}
                    height={64}
                  />
                </button>
              );
            })}
          </div>
          {error && (
            <p className={styles.error} role="alert">
              {error}
            </p>
          )}
          <div className={styles.panelActions}>
            <button
              type="button"
              className={styles.ghostBtn}
              onClick={closeEditor}
              disabled={busy}
            >
              <X size={16} aria-hidden="true" /> Cancel
            </button>
            <button
              type="button"
              className={styles.primaryBtn}
              onClick={() => void saveCreate()}
              disabled={busy || name.trim().length < 2}
            >
              <Check size={16} aria-hidden="true" /> Create
            </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className={styles.root}>
      <div className={styles.brand}>papernook</div>
      <h1 className={styles.heading}>Who&rsquo;s reading?</h1>
      <p className={styles.sub}>
        self hosted · {profiles.length}{" "}
        {profiles.length === 1 ? "profile" : "profiles"} on this server
      </p>
      <div className={styles.row}>
        {profiles.map((p) => (
          <button
            key={p.username}
            type="button"
            className={styles.profile}
            onClick={() => pick(p)}
            disabled={busy}
            aria-label={`Switch to ${p.displayName}${p.isAdmin ? " (Admin)" : ""}`}
          >
            <span className={styles.avatar}>
              <Image
                src={`/avatars/${p.avatarSlug}.png`}
                alt=""
                fill
                sizes="140px"
              />
            </span>
            <span className={styles.name}>{p.displayName}</span>
            {p.isAdmin && <span className={styles.meta}>Admin</span>}
          </button>
        ))}
        <button
          type="button"
          className={`${styles.profile} ${styles.add}`}
          onClick={() => {
            setName("");
            setAvatarSlug(ANIMAL_AVATARS[0].slug);
            setError(null);
            setEditor({ mode: "create" });
          }}
          disabled={busy}
        >
          <span className={`${styles.avatar} ${styles.addAvatar}`}>
            <Plus size={40} aria-hidden="true" />
          </span>
          <span className={styles.name}>Add profile</span>
        </button>
      </div>
      {error && (
        <p className={styles.error} role="alert">
          {error}
        </p>
      )}
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import styles from "./ZoteroCard.module.css";

interface ZoteroTarget {
  type: "user" | "group";
  id: string;
  name: string;
}

interface ZoteroCollection {
  key: string;
  name: string;
  parentCollection: string | null;
}

interface ZoteroState {
  connected: boolean;
  userId: string | null;
  target: ZoteroTarget | null;
  collectionKeys: string[];
  syncing: boolean;
  lastResult: {
    discovered: number;
    updated: number;
    removed: number;
    available: number;
    failed: number;
  } | null;
}

interface ZoteroOptions extends ZoteroState {
  libraries: (ZoteroTarget & { canImportFiles: boolean | null })[];
  collections: ZoteroCollection[];
  previewTarget: ZoteroTarget;
  warning: string | null;
}

interface ZoteroCatalogItem {
  key: string;
  title: string;
  authors: string[];
  year: number | null;
  annotationCount: number;
  hasStoredPdf: boolean;
  imported: { topic: string; slug: string } | null;
}

interface ZoteroCatalogPage {
  items: ZoteroCatalogItem[];
  total: number;
  importable: number;
  imported: number;
  page: number;
  limit: number;
  refreshedAt: string | null;
}

function targetValue(target: ZoteroTarget): string {
  return `${target.type}:${target.id}`;
}

async function fetchCatalog(
  query: string,
  page = 1,
): Promise<ZoteroCatalogPage | null> {
  const params = new URLSearchParams({
    q: query.trim(),
    page: String(page),
    limit: "20",
  });
  const response = await fetch(
    `/api/v1/settings/zotero/items?${params.toString()}`,
    { credentials: "include" },
  );
  return response.ok ? ((await response.json()) as ZoteroCatalogPage) : null;
}

export function ZoteroCard() {
  const [state, setState] = useState<ZoteroState | null>(null);
  const [apiKey, setApiKey] = useState("");
  const [status, setStatus] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [options, setOptions] = useState<ZoteroOptions | null>(null);
  const [selectedTarget, setSelectedTarget] = useState("");
  const [selectedCollections, setSelectedCollections] = useState<string[]>([]);
  const [catalog, setCatalog] = useState<ZoteroCatalogPage | null>(null);
  const [catalogQuery, setCatalogQuery] = useState("");
  const [importingKey, setImportingKey] = useState<string | null>(null);
  const pollRef = useRef<ReturnType<typeof setInterval> | null>(null);

  async function refresh(): Promise<ZoteroState | null> {
    const response = await fetch("/api/v1/settings/zotero", {
      credentials: "include",
    });
    if (!response.ok) return null;
    const data = (await response.json()) as ZoteroState;
    setState(data);
    return data;
  }

  useEffect(() => {
    void fetch("/api/v1/settings/zotero", { credentials: "include" })
      .then((response) =>
        response.ok ? (response.json() as Promise<ZoteroState>) : null,
      )
      .then((data) => {
        if (!data) return;
        setState(data);
        if (data.connected) {
          void fetchCatalog("").then((catalogData) => {
            if (catalogData) setCatalog(catalogData);
          });
        }
      });
    return () => {
      if (pollRef.current) clearInterval(pollRef.current);
    };
  }, []);

  function watchSync(): void {
    if (pollRef.current) clearInterval(pollRef.current);
    pollRef.current = setInterval(() => {
      void refresh().then((data) => {
        if (data && !data.syncing && pollRef.current) {
          clearInterval(pollRef.current);
          pollRef.current = null;
          setStatus(
            data.lastResult?.failed
              ? "Zotero catalog refresh failed. It will retry automatically."
              : `Catalog refreshed: ${data.lastResult?.available ?? 0} papers with stored PDFs; no PDFs downloaded and no AI calls made.`,
          );
          void loadCatalog();
        }
      });
    }, 3000);
  }

  async function call(method: "PUT" | "POST" | "DELETE"): Promise<void> {
    setBusy(true);
    setStatus(null);
    try {
      const response = await fetch("/api/v1/settings/zotero", {
        method,
        credentials: "include",
        ...(method === "PUT"
          ? {
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({ apiKey: apiKey.trim() }),
            }
          : {}),
      });
      const data = (await response.json()) as ZoteroState & { error?: string };
      if (!response.ok) {
        setStatus(data.error ?? "Something went wrong.");
        return;
      }
      setState(data);
      setOptions(null);
      if (method === "PUT") {
        setApiKey("");
        setCatalog(null);
        setStatus(
          "Connected. Refresh the metadata catalog to browse papers; nothing is downloaded automatically.",
        );
      }
      if (method === "DELETE") {
        setCatalog(null);
        setStatus("Disconnected.");
      }
      if (method === "POST") {
        setStatus("Refreshing metadata and annotations…");
        watchSync();
      }
    } catch {
      setStatus("Could not reach the Zotero settings service.");
    } finally {
      setBusy(false);
    }
  }

  async function loadCatalog(query = catalogQuery, page = 1): Promise<void> {
    try {
      const data = await fetchCatalog(query, page);
      if (data) setCatalog(data);
    } catch {
      setStatus("Could not load the Zotero catalog.");
    }
  }

  async function importItem(item: ZoteroCatalogItem): Promise<void> {
    setImportingKey(item.key);
    setStatus(
      `Importing “${item.title}”… This downloads one PDF and runs the configured AI analysis.`,
    );
    try {
      const response = await fetch("/api/v1/settings/zotero/items", {
        method: "POST",
        credentials: "include",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ itemKey: item.key }),
      });
      const data = (await response.json()) as {
        error?: string;
        topic?: string;
        slug?: string;
        created?: boolean;
      };
      if (!response.ok) {
        setStatus(data.error ?? "Could not import this Zotero paper.");
        return;
      }
      setStatus(
        data.created
          ? `Imported “${item.title}” into Papernook.`
          : `“${item.title}” was already in Papernook.`,
      );
      await loadCatalog(catalogQuery, catalog?.page ?? 1);
    } catch {
      setStatus("Could not import this Zotero paper.");
    } finally {
      setImportingKey(null);
    }
  }

  async function loadOptions(target?: ZoteroTarget): Promise<void> {
    setBusy(true);
    setStatus(null);
    try {
      const params = new URLSearchParams({ options: "1" });
      if (target) {
        params.set("libraryType", target.type);
        params.set("libraryId", target.id);
      }
      const response = await fetch(
        `/api/v1/settings/zotero?${params.toString()}`,
        { credentials: "include" },
      );
      const data = (await response.json()) as ZoteroOptions & {
        error?: string;
      };
      if (!response.ok) {
        setStatus(data.error ?? "Could not load Zotero libraries.");
        return;
      }
      setOptions(data);
      setSelectedTarget(targetValue(data.previewTarget));
      const available = new Set(
        data.collections.map((collection) => collection.key),
      );
      const isConfiguredTarget =
        state?.target?.type === data.previewTarget.type &&
        state?.target?.id === data.previewTarget.id;
      setSelectedCollections(
        isConfiguredTarget
          ? data.collectionKeys.filter((key) => available.has(key))
          : [],
      );
      if (data.warning) setStatus(data.warning);
    } catch {
      setStatus("Could not load Zotero libraries.");
    } finally {
      setBusy(false);
    }
  }

  async function changeTarget(value: string): Promise<void> {
    const target = options?.libraries.find(
      (library) => targetValue(library) === value,
    );
    if (!target) return;
    setSelectedTarget(value);
    await loadOptions(target);
  }

  async function saveScope(): Promise<void> {
    const target = options?.libraries.find(
      (library) => targetValue(library) === selectedTarget,
    );
    if (!target) return;
    setBusy(true);
    setStatus(null);
    try {
      const response = await fetch("/api/v1/settings/zotero", {
        method: "PATCH",
        credentials: "include",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          target: { type: target.type, id: target.id },
          collectionKeys: selectedCollections,
        }),
      });
      const data = (await response.json()) as ZoteroState & { error?: string };
      if (!response.ok) {
        setStatus(data.error ?? "Could not save the Zotero sync source.");
        return;
      }
      setState(data);
      setOptions(null);
      await loadCatalog();
      setStatus(
        selectedCollections.length === 0
          ? `Cataloging all of ${target.name}.`
          : `Cataloging ${selectedCollections.length} selected collection${selectedCollections.length === 1 ? "" : "s"} in ${target.name}.`,
      );
    } catch {
      setStatus("Could not save the Zotero sync source.");
    } finally {
      setBusy(false);
    }
  }

  if (!state) return null;

  if (!state.connected) {
    return (
      <div className={styles.root}>
        <p className={styles.line}>
          Create a dedicated key at{" "}
          <a
            href="https://www.zotero.org/settings/keys/new"
            target="_blank"
            rel="noopener noreferrer"
          >
            zotero.org/settings/keys
          </a>
          . Enable library read access. File access is needed only when you
          explicitly import a PDF; write access is never needed.
        </p>
        <div className={styles.controls}>
          <input
            className={styles.input}
            type="password"
            value={apiKey}
            onChange={(event) => setApiKey(event.target.value)}
            placeholder="Zotero API key"
            onKeyDown={(event) => {
              if (event.key === "Enter" && apiKey.trim()) void call("PUT");
            }}
            disabled={busy}
          />
          <button
            type="button"
            className={styles.save}
            onClick={() => void call("PUT")}
            disabled={busy || !apiKey.trim()}
          >
            Connect
          </button>
        </div>
        {status && (
          <p className={styles.status} role="status">
            {status}
          </p>
        )}
      </div>
    );
  }

  return (
    <div className={styles.root}>
      <p className={styles.line}>
        Connected to <strong>{state.target?.name ?? "My Library"}</strong>.
        {state.collectionKeys.length === 0
          ? " All collections are included."
          : ` ${state.collectionKeys.length} collection filter${state.collectionKeys.length === 1 ? " is" : "s are"} active.`}{" "}
        Metadata and annotations refresh every 30 minutes. PDFs are downloaded
        only when you explicitly import one, and catalog refreshes never call an
        AI provider.
      </p>

      {options && (
        <div className={styles.scope}>
          <label>
            Zotero library
            <select
              className={styles.select}
              value={selectedTarget}
              onChange={(event) => void changeTarget(event.target.value)}
              disabled={busy}
            >
              {options.libraries.map((library) => (
                <option key={targetValue(library)} value={targetValue(library)}>
                  {library.name}
                  {library.type === "group" ? " (group)" : ""}
                </option>
              ))}
            </select>
            {options.libraries.find(
              (library) => targetValue(library) === selectedTarget,
            )?.canImportFiles === false && (
              <span className={styles.hint}>
                This key can catalog metadata but cannot download PDFs from this
                personal library. Enable file read access to import.
              </span>
            )}
          </label>
          <fieldset className={styles.collections}>
            <legend>Collections</legend>
            <p className={styles.hint}>
              Select none to sync the entire library. Subcollections are
              included automatically.
            </p>
            <div className={styles.collectionList}>
              {options.collections.map((collection) => (
                <label key={collection.key} className={styles.collection}>
                  <input
                    type="checkbox"
                    checked={selectedCollections.includes(collection.key)}
                    onChange={(event) =>
                      setSelectedCollections((current) =>
                        event.target.checked
                          ? [...current, collection.key]
                          : current.filter((key) => key !== collection.key),
                      )
                    }
                  />
                  {collection.name}
                </label>
              ))}
              {options.collections.length === 0 && (
                <span className={styles.hint}>
                  No collections in this library.
                </span>
              )}
            </div>
          </fieldset>
          <div className={styles.controls}>
            <button
              type="button"
              className={styles.save}
              onClick={() => void saveScope()}
              disabled={busy}
            >
              Save sync source
            </button>
            <button
              type="button"
              className={styles.secondary}
              onClick={() => setOptions(null)}
              disabled={busy}
            >
              Cancel
            </button>
          </div>
        </div>
      )}

      {!options && (
        <div className={styles.controls}>
          <button
            type="button"
            className={styles.save}
            onClick={() => void call("POST")}
            disabled={busy || state.syncing}
          >
            {state.syncing ? "Refreshing…" : "Refresh catalog"}
          </button>
          <button
            type="button"
            className={styles.secondary}
            onClick={() => void loadOptions()}
            disabled={busy || state.syncing}
          >
            Library & collections
          </button>
          <button
            type="button"
            className={styles.secondary}
            onClick={() => void call("DELETE")}
            disabled={busy || state.syncing}
          >
            Disconnect
          </button>
        </div>
      )}
      {!options && catalog && (
        <div className={styles.catalog}>
          <div className={styles.catalogHeader}>
            <div>
              <strong>Zotero catalog</strong>
              <p className={styles.hint}>
                {catalog.total} papers in scope · {catalog.importable} with a
                stored PDF · {catalog.imported} imported
              </p>
            </div>
            <div className={styles.catalogSearch}>
              <input
                className={styles.input}
                type="search"
                value={catalogQuery}
                onChange={(event) => setCatalogQuery(event.target.value)}
                placeholder="Search Zotero metadata"
                onKeyDown={(event) => {
                  if (event.key === "Enter") void loadCatalog(catalogQuery, 1);
                }}
              />
              <button
                type="button"
                className={styles.secondary}
                onClick={() => void loadCatalog(catalogQuery, 1)}
              >
                Search
              </button>
            </div>
          </div>
          <div className={styles.catalogList}>
            {catalog.items.map((item) => (
              <div key={item.key} className={styles.catalogItem}>
                <div>
                  <strong>{item.title}</strong>
                  <p className={styles.hint}>
                    {[item.authors.join(", "), item.year]
                      .filter(Boolean)
                      .join(" · ") || "Metadata only"}
                    {item.annotationCount > 0
                      ? ` · ${item.annotationCount} annotation${item.annotationCount === 1 ? "" : "s"}`
                      : ""}
                  </p>
                </div>
                {item.imported ? (
                  <a
                    className={styles.secondary}
                    href={`/paper/${item.imported.topic}/${item.imported.slug}`}
                  >
                    Open
                  </a>
                ) : (
                  <button
                    type="button"
                    className={styles.save}
                    disabled={!item.hasStoredPdf || importingKey !== null}
                    onClick={() => void importItem(item)}
                    title={
                      item.hasStoredPdf
                        ? "Download this PDF and run AI analysis"
                        : "No stored Zotero PDF is available"
                    }
                  >
                    {importingKey === item.key ? "Importing…" : "Import"}
                  </button>
                )}
              </div>
            ))}
            {catalog.items.length === 0 && (
              <p className={styles.hint}>
                Refresh the catalog, or adjust the current search and collection
                filters.
              </p>
            )}
          </div>
          {catalog.total > catalog.limit && (
            <div className={styles.catalogPagination}>
              <button
                type="button"
                className={styles.secondary}
                disabled={catalog.page <= 1}
                onClick={() => void loadCatalog(catalogQuery, catalog.page - 1)}
              >
                Previous
              </button>
              <span className={styles.hint}>
                Page {catalog.page} of{" "}
                {Math.max(1, Math.ceil(catalog.total / catalog.limit))}
              </span>
              <button
                type="button"
                className={styles.secondary}
                disabled={catalog.page * catalog.limit >= catalog.total}
                onClick={() => void loadCatalog(catalogQuery, catalog.page + 1)}
              >
                Next
              </button>
            </div>
          )}
        </div>
      )}
      {status && (
        <p className={styles.status} role="status">
          {status}
        </p>
      )}
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { usePathname } from "next/navigation";
import { probeConnection, refreshOffline } from "@/lib/offline/download";
import {
  clearOfflineForAuthentication,
  OfflineIdentityChangedError,
  getOfflineIdentity,
  offlineError,
  setOfflineIdentity,
  subscribeOffline,
} from "@/lib/offline/storage";
import styles from "@/components/offline/Offline.module.css";
import { reportServerConnection } from "@/components/offline/useConnection";

/** Reconcile device identity and use the saved reader when the server is down. */
export function PwaSetup() {
  const pathname = usePathname();
  const [notice, setNotice] = useState<string | null>(null);
  useEffect(() => {
    if ("serviceWorker" in navigator && window.isSecureContext) {
      void navigator.serviceWorker
        .register("/sw.js", { updateViaCache: "none" })
        .catch((error) =>
          setNotice(
            `Offline reader could not be installed: ${offlineError(error)}`,
          ),
        );
    }
  }, []);
  useEffect(() => {
    let active = true;
    let checking = false;
    let refreshing = false;
    let owner: string | null = null;
    const publicPage =
      pathname === "/login" ||
      pathname.startsWith("/share/") ||
      pathname.startsWith("/add") ||
      pathname === "/invite";
    if (pathname === "/login") void clearOfflineForAuthentication();
    async function check() {
      if (checking || publicPage || !active) return;
      checking = true;
      try {
        const initialIdentity = await getOfflineIdentity().catch(() => null);
        const connection = await probeConnection();
        if (!active) return;
        reportServerConnection(
          connection.state === "online" || connection.state === "busy",
        );
        if (connection.state === "signed-out") {
          if (initialIdentity) {
            try {
              await setOfflineIdentity(null, initialIdentity);
            } catch (error) {
              if (error instanceof OfflineIdentityChangedError) return;
            }
          }
          await clearOfflineForAuthentication();
          location.replace("/login");
          return;
        }
        if (connection.state === "online") {
          if (!initialIdentity) {
            setNotice(
              "Offline storage is unavailable in this browser. Your online library is available.",
            );
            return;
          }
          const previous = initialIdentity;
          await setOfflineIdentity(connection.owner, initialIdentity);
          if (owner && owner !== connection.owner) {
            location.reload();
            return;
          }
          owner = connection.owner;
          if (previous.owner && previous.owner !== owner) {
            location.reload();
            return;
          }
          setNotice(null);
          if (!refreshing) {
            refreshing = true;
            void refreshOffline()
              .catch((error) => {
                if (active)
                  setNotice(
                    `Offline download update failed: ${offlineError(error)}`,
                  );
              })
              .finally(() => {
                refreshing = false;
              });
          }
          return;
        }
        if (connection.state === "busy") return;
        const draft = [...document.querySelectorAll("textarea")].some(
          (textarea) => textarea.value.trim(),
        );
        if (draft) {
          setNotice(
            "Server unavailable. Your draft is still here. Open your downloaded library to read offline.",
          );
          return;
        }
        if (navigator.serviceWorker?.controller)
          location.replace(
            `/offline/index.html?return=${encodeURIComponent(location.pathname + location.search)}`,
          );
        else
          setNotice(
            "Server unavailable. Connect once to install the offline reader.",
          );
      } catch (error) {
        if (active)
          setNotice(`Offline storage unavailable: ${offlineError(error)}`);
      } finally {
        checking = false;
      }
    }
    const unsubscribe = subscribeOffline(() => {
      void getOfflineIdentity()
        .then((identity) => {
          if (active && owner && identity.owner !== owner && !publicPage)
            location.replace("/login");
        })
        .catch(() => {});
    });
    void check();
    const timer = window.setInterval(() => {
      void check();
    }, 15_000);
    const onConnection = () => {
      void check();
    };
    window.addEventListener("online", onConnection);
    window.addEventListener("offline", onConnection);
    return () => {
      active = false;
      unsubscribe();
      clearInterval(timer);
      window.removeEventListener("online", onConnection);
      window.removeEventListener("offline", onConnection);
    };
  }, [pathname]);
  return notice ? (
    <div className={styles.banner} role="status">
      {notice} <a href="/offline/index.html">Downloads</a>
    </div>
  ) : null;
}

"use client";

import type {
  ResearchGraph as GraphData,
  GraphEdge,
  GraphNode,
  SourceRef,
} from "@/lib/research/types";
import {
  ArrowLeft,
  ArrowRight,
  ArrowUpRight,
  BookOpen,
  Check,
  ChevronDown,
  Download,
  Focus,
  GitBranch,
  Maximize2,
  Minus,
  Network,
  Plus,
  RotateCcw,
  Search,
  Sparkles,
  X,
} from "lucide-react";
import { useCallback, useMemo, useRef, useState } from "react";
import { errorText, postJson } from "./api";
import { SourceChips } from "./ResearchUi";
import { filterGraph, nodeKindLabel } from "./graph/graph-data";
import { useGraphCanvas } from "./graph/use-graph-canvas";
import styles from "./graph/graph.module.css";

type Selection = { kind: "node" | "edge"; id: string } | null;

export function ResearchGraph({
  graph,
  onRefresh,
  onOpenSource,
  notify,
}: {
  graph: GraphData;
  onRefresh(): Promise<void>;
  onOpenSource(source: SourceRef): void;
  notify(message: string, error?: boolean): void;
}) {
  const container = useRef<HTMLDivElement>(null);
  const exportMenu = useRef<HTMLDetailsElement>(null);
  const [view, setView] = useState<"all" | "papers">("all");
  const [paperId, setPaperId] = useState("");
  const [query, setQuery] = useState("");
  const [showCandidates, setShowCandidates] = useState(true);
  const [selection, setSelection] = useState<Selection>(null);
  const [focusNodeId, setFocusNodeId] = useState<string | null>(null);
  const [list, setList] = useState<"nodes" | "candidates">("nodes");
  const [generating, setGenerating] = useState(false);
  const [saving, setSaving] = useState(false);

  const visible = useMemo(
    () =>
      filterGraph(graph, { view, paperId, query, showCandidates, focusNodeId }),
    [graph, view, paperId, query, showCandidates, focusNodeId],
  );
  const nodesById = useMemo(
    () => new Map(graph.nodes.map((node) => [node.id, node])),
    [graph.nodes],
  );
  const paperOptions = useMemo(
    () =>
      graph.nodes
        .filter((node) => node.kind === "paper" && node.paperId)
        .sort((a, b) => a.label.localeCompare(b.label, "zh-CN")),
    [graph.nodes],
  );
  const degrees = useMemo(() => {
    const values = new Map<string, number>();
    visible.edges.forEach((edge) => {
      values.set(edge.source, (values.get(edge.source) ?? 0) + 1);
      values.set(edge.target, (values.get(edge.target) ?? 0) + 1);
    });
    return values;
  }, [visible.edges]);
  const listedNodes = useMemo(() => {
    const matches = new Set(visible.matchedIds);
    const order = { paper: 0, concept: 1, note: 2 };
    return visible.nodes
      .filter((node) => !query.trim() || matches.has(node.id))
      .sort(
        (a, b) =>
          order[a.kind] - order[b.kind] ||
          (degrees.get(b.id) ?? 0) - (degrees.get(a.id) ?? 0) ||
          a.label.localeCompare(b.label, "zh-CN"),
      );
  }, [visible, query, degrees]);
  const candidates = useMemo(
    () => visible.edges.filter((edge) => edge.status === "candidate"),
    [visible.edges],
  );
  const selectedNode =
    selection?.kind === "node"
      ? visible.nodes.find((node) => node.id === selection.id)
      : undefined;
  const selectedEdge =
    selection?.kind === "edge"
      ? visible.edges.find((edge) => edge.id === selection.id)
      : undefined;
  const select = useCallback(
    (kind: "node" | "edge" | null, id: string | null) => {
      setSelection(kind && id ? { kind, id } : null);
    },
    [],
  );
  const canvas = useGraphCanvas({
    container,
    graph,
    visible,
    selectedId: selectedNode?.id ?? selectedEdge?.id ?? null,
    onSelect: select,
  });

  function resetScope() {
    setSelection(null);
    setFocusNodeId(null);
  }

  async function updateEdge(edge: GraphEdge, action: "confirm" | "reject") {
    setSaving(true);
    try {
      await postJson("/graph", {
        action,
        edgeId: edge.id,
        version: edge.version,
      });
      await onRefresh();
      if (action === "reject") setSelection(null);
      notify(
        action === "confirm" ? "这条关系已确认。" : "已拒绝这条候选关系。",
      );
    } catch (error) {
      notify(errorText(error), true);
    } finally {
      setSaving(false);
    }
  }

  async function suggest() {
    setGenerating(true);
    try {
      await postJson("/graph", { action: "suggest" });
      await onRefresh();
      notify("关系候选已更新。");
    } catch (error) {
      notify(errorText(error), true);
    } finally {
      setGenerating(false);
    }
  }

  function exportGraph(image = false) {
    if (exportMenu.current) exportMenu.current.open = false;
    const anchor = document.createElement("a");
    if (image && canvas.cyRef.current) {
      anchor.href = canvas.cyRef.current.png({
        full: true,
        bg: "#fafbfc",
        scale: 2,
      });
      anchor.download = "教研阅记-知识图谱.png";
    } else {
      anchor.href = URL.createObjectURL(
        new Blob([JSON.stringify(graph, null, 2)], {
          type: "application/json",
        }),
      );
      anchor.download = "教研阅记-知识图谱.json";
    }
    anchor.click();
    if (!image) setTimeout(() => URL.revokeObjectURL(anchor.href), 0);
  }

  function nodeMark(node: GraphNode) {
    return <i aria-hidden="true" className={styles[node.kind]} />;
  }

  function relationshipRow(edge: GraphEdge, fromNode?: string) {
    const otherId = edge.source === fromNode ? edge.target : edge.source;
    return (
      <button
        key={edge.id}
        className={styles.relationRow}
        onClick={() => select("edge", edge.id)}
      >
        <span className={styles.relationLabel}>
          {edge.status === "candidate" && <i className={styles.candidateDot} />}
          {edge.label}
          <ArrowUpRight size={13} />
        </span>
        <span className={styles.relationNames}>
          {fromNode ? (
            nodesById.get(otherId)?.label
          ) : (
            <>
              {nodesById.get(edge.source)?.label}
              <ArrowRight size={12} />
              {nodesById.get(edge.target)?.label}
            </>
          )}
        </span>
      </button>
    );
  }

  return (
    <section className={styles.page} aria-label="知识图谱工作区">
      <header className={styles.heading}>
        <h1>知识图谱</h1>
        <div className={styles.actions}>
          <select
            className={styles.paperFilter}
            aria-label="筛选图谱论文"
            value={paperId}
            title={
              paperOptions.find((paper) => paper.paperId === paperId)?.label ??
              "全部论文"
            }
            onChange={(event) => {
              setPaperId(event.target.value);
              resetScope();
            }}
          >
            <option value="">全部论文</option>
            {paperOptions.map((paper) => (
              <option key={paper.id} value={paper.paperId}>
                {paper.label}
              </option>
            ))}
          </select>
          <details ref={exportMenu} className={styles.exportMenu}>
            <summary>
              <Download size={15} />
              导出
              <ChevronDown size={12} />
            </summary>
            <div>
              <button
                onClick={() => exportGraph(true)}
                disabled={!canvas.ready || !visible.nodes.length}
              >
                当前图谱 PNG
              </button>
              <button onClick={() => exportGraph()}>完整数据 JSON</button>
            </div>
          </details>
          <button
            className={styles.primary}
            disabled={generating}
            onClick={() => void suggest()}
          >
            <Sparkles size={15} />
            {generating ? "整理中…" : "整理关系"}
          </button>
        </div>
      </header>

      <div className={styles.workspace}>
        <div className={styles.toolbar}>
          <div className={styles.tabs} role="group" aria-label="图谱视图">
            <button
              aria-pressed={view === "all"}
              onClick={() => {
                setView("all");
                resetScope();
              }}
            >
              研究网络
            </button>
            <button
              aria-pressed={view === "papers"}
              onClick={() => {
                setView("papers");
                resetScope();
              }}
            >
              论文关系
            </button>
          </div>
          <div className={styles.search}>
            <Search size={15} />
            <input
              aria-label="搜索图谱节点"
              placeholder="查找论文、概念、笔记"
              value={query}
              onChange={(event) => {
                setQuery(event.target.value);
                resetScope();
              }}
            />
            {query && (
              <button
                aria-label="清空图谱搜索"
                onClick={() => {
                  setQuery("");
                  resetScope();
                }}
              >
                <X size={14} />
              </button>
            )}
          </div>
          <label className={styles.candidateToggle}>
            <input
              type="checkbox"
              checked={showCandidates}
              onChange={(event) => {
                setShowCandidates(event.target.checked);
                resetScope();
              }}
            />
            候选关系
          </label>
        </div>

        <div className={styles.body}>
          <div className={styles.canvas}>
            {focusNodeId && (
              <div className={styles.focusBar}>
                <button
                  onClick={() => {
                    setFocusNodeId(null);
                    setSelection(null);
                  }}
                >
                  <ArrowLeft size={14} />
                  返回全图
                </button>
                <span>{nodesById.get(focusNodeId)?.label}</span>
              </div>
            )}
            <div
              ref={container}
              className={styles.surface}
              tabIndex={0}
              role="region"
              aria-label="可交互知识图谱"
              aria-describedby="graph-keyboard-help"
              aria-busy={!canvas.ready}
            />
            <span id="graph-keyboard-help" className={styles.srOnly}>
              拖动节点调整位置，滚轮缩放。加减键缩放，0
              适应画布。也可在节点列表中选择。
            </span>
            {(!canvas.ready || canvas.error || !visible.nodes.length) && (
              <div className={styles.empty} role="status">
                <Network size={28} />
                <strong>
                  {canvas.error
                    ? "图谱暂时无法显示"
                    : !canvas.ready
                      ? "正在排列研究网络…"
                      : "没有匹配的节点"}
                </strong>
                <p>
                  {canvas.error ||
                    (canvas.ready ? "试试其他关键词或筛选条件。" : "")}
                </p>
                {canvas.ready && !canvas.error && (
                  <button
                    onClick={() => {
                      setQuery("");
                      setPaperId("");
                      setView("all");
                      setShowCandidates(true);
                      resetScope();
                    }}
                  >
                    重置筛选
                  </button>
                )}
              </div>
            )}
            <div className={styles.canvasControls} aria-label="图谱画布操作">
              <button
                title="缩小图谱"
                aria-label="缩小图谱"
                onClick={() => canvas.zoomBy(1 / 1.2)}
                disabled={!canvas.ready}
              >
                <Minus size={16} />
              </button>
              <span aria-label="图谱缩放比例">{canvas.zoom}%</span>
              <button
                title="放大图谱"
                aria-label="放大图谱"
                onClick={() => canvas.zoomBy(1.2)}
                disabled={!canvas.ready}
              >
                <Plus size={16} />
              </button>
              <span className={styles.divider} />
              <button
                title="适应画布 (0)"
                aria-label="适应画布"
                onClick={canvas.fit}
                disabled={!canvas.ready}
              >
                <Maximize2 size={16} />
              </button>
              <button
                title="重新布局"
                aria-label="重新布局"
                onClick={canvas.relayout}
                disabled={!canvas.ready}
              >
                <RotateCcw size={16} />
              </button>
            </div>
          </div>

          <aside className={styles.inspector} aria-label="图谱详情">
            <header className={styles.inspectorHeader}>
              {selectedNode || selectedEdge ? (
                <button
                  className={styles.back}
                  onClick={() => select(null, null)}
                >
                  <ArrowLeft size={14} />
                  {selectedEdge ? "关系与证据" : "节点详情"}
                </button>
              ) : (
                <div
                  className={styles.inspectorTabs}
                  role="group"
                  aria-label="图谱浏览列表"
                >
                  <button
                    aria-pressed={list === "nodes"}
                    onClick={() => setList("nodes")}
                  >
                    {query.trim() ? "搜索结果" : "节点"}
                    <span>{listedNodes.length}</span>
                  </button>
                  <button
                    aria-pressed={list === "candidates"}
                    onClick={() => setList("candidates")}
                  >
                    待核对<span>{candidates.length}</span>
                  </button>
                </div>
              )}
              {(selectedNode || selectedEdge) && (
                <button
                  className={styles.close}
                  aria-label="关闭图谱详情"
                  onClick={() => select(null, null)}
                >
                  <X size={15} />
                </button>
              )}
            </header>

            <div className={styles.inspectorBody}>
              {selectedEdge ? (
                <div className={styles.detail}>
                  <div className={styles.detailMeta}>
                    <GitBranch size={14} />
                    <span>
                      {selectedEdge.status === "candidate"
                        ? "候选关系"
                        : "已确认"}
                    </span>
                    <span>
                      {selectedEdge.origin === "ai"
                        ? "AI 整理"
                        : selectedEdge.origin === "user"
                          ? "人工建立"
                          : "资料关联"}
                    </span>
                  </div>
                  <div className={styles.relationFlow}>
                    {[selectedEdge.source, selectedEdge.target].map(
                      (id, index) => (
                        <div key={id}>
                          {index === 1 && (
                            <span className={styles.flowLabel}>
                              ↓ {selectedEdge.label}
                            </span>
                          )}
                          <button onClick={() => select("node", id)}>
                            {nodesById.get(id) && nodeMark(nodesById.get(id)!)}
                            <span>{nodesById.get(id)?.label ?? id}</span>
                            <ArrowUpRight size={14} />
                          </button>
                        </div>
                      ),
                    )}
                  </div>
                  {selectedEdge.rationale && <p>{selectedEdge.rationale}</p>}
                  {selectedEdge.stale && (
                    <p className={styles.notice}>原文已更新，请重新核对。</p>
                  )}
                  <h3>
                    原文证据 <span>{selectedEdge.evidence.length}</span>
                  </h3>
                  {selectedEdge.evidence.map((source, index) => (
                    <div className={styles.evidence} key={index}>
                      {source.quote && <blockquote>{source.quote}</blockquote>}
                      <SourceChips sources={[source]} onOpen={onOpenSource} />
                    </div>
                  ))}
                  {!selectedEdge.evidence.length && (
                    <p className={styles.muted}>暂无原文摘录。</p>
                  )}
                  {selectedEdge.status === "candidate" && (
                    <div className={styles.detailActions}>
                      <button
                        className={styles.primary}
                        disabled={saving}
                        onClick={() => void updateEdge(selectedEdge, "confirm")}
                      >
                        <Check size={14} />
                        确认关系
                      </button>
                      <button
                        className={styles.secondary}
                        disabled={saving}
                        onClick={() => void updateEdge(selectedEdge, "reject")}
                      >
                        <X size={14} />
                        拒绝
                      </button>
                    </div>
                  )}
                </div>
              ) : selectedNode ? (
                <div className={styles.detail}>
                  <div className={styles.detailMeta}>
                    {nodeMark(selectedNode)}
                    {nodeKindLabel(selectedNode.kind)}
                    <span>{degrees.get(selectedNode.id) ?? 0} 条关系</span>
                  </div>
                  <h2>{selectedNode.label}</h2>
                  {selectedNode.definition && <p>{selectedNode.definition}</p>}
                  <div className={styles.detailActions}>
                    {(selectedNode.paperId || selectedNode.noteId) && (
                      <button
                        className={styles.secondary}
                        onClick={() =>
                          onOpenSource({
                            paperId: selectedNode.paperId,
                            noteId: selectedNode.noteId,
                          })
                        }
                      >
                        <BookOpen size={14} />
                        {selectedNode.kind === "note" ? "打开笔记" : "打开论文"}
                      </button>
                    )}
                    <button
                      className={styles.secondary}
                      aria-pressed={focusNodeId === selectedNode.id}
                      onClick={() =>
                        setFocusNodeId(
                          focusNodeId === selectedNode.id
                            ? null
                            : selectedNode.id,
                        )
                      }
                    >
                      <Focus size={14} />
                      {focusNodeId === selectedNode.id
                        ? "显示全图"
                        : "只看相邻"}
                    </button>
                  </div>
                  <h3>相连的关系</h3>
                  {visible.edges
                    .filter(
                      (edge) =>
                        edge.source === selectedNode.id ||
                        edge.target === selectedNode.id,
                    )
                    .map((edge) => relationshipRow(edge, selectedNode.id))}
                  {!degrees.get(selectedNode.id) && (
                    <p className={styles.muted}>暂无相连关系。</p>
                  )}
                </div>
              ) : list === "nodes" ? (
                <div className={styles.nodeList}>
                  {listedNodes.map((node) => (
                    <button
                      className={styles.nodeRow}
                      key={node.id}
                      onClick={() => select("node", node.id)}
                    >
                      {nodeMark(node)}
                      <span>
                        <strong>{node.label}</strong>
                        <small>{nodeKindLabel(node.kind)}</small>
                      </span>
                      <span className={styles.degree} title="相连关系数">
                        {degrees.get(node.id) ?? 0}
                      </span>
                    </button>
                  ))}
                  {!listedNodes.length && (
                    <p className={styles.listEmpty}>没有匹配的节点。</p>
                  )}
                </div>
              ) : (
                <div className={styles.candidateList}>
                  {candidates.map((edge) => relationshipRow(edge))}
                  {!candidates.length && (
                    <p className={styles.listEmpty}>
                      {showCandidates
                        ? "当前范围没有待核对关系。"
                        : "开启“候选关系”后查看。"}
                    </p>
                  )}
                </div>
              )}
            </div>
          </aside>
        </div>

        <footer className={styles.footer}>
          <div className={styles.legend} aria-label="图谱图例">
            <span>
              <i className={styles.paper} />
              论文
            </span>
            <span>
              <i className={styles.concept} />
              概念
            </span>
            <span>
              <i className={styles.note} />
              笔记
            </span>
            <span className={styles.candidateKey}>
              <i />
              候选
            </span>
          </div>
          <span role="status">
            {visible.nodes.length} 个节点 · {visible.edges.length} 条关系
          </span>
        </footer>
      </div>
    </section>
  );
}

"use client";

import { Markdown } from "@/components/chat/Markdown";
import type { KnowledgeEntry, SourceRef } from "@/lib/research/types";
import {
  ArrowUpRight,
  BookMarked,
  Check,
  GraduationCap,
  Plus,
  Search,
} from "lucide-react";
import { useMemo, useState } from "react";
import { errorText, postJson } from "./api";
import { EmptyState, Modal, SourceChips } from "./ResearchUi";
import styles from "./styles";

export function ResearchKnowledge({
  entries,
  onRefresh,
  onOpenSource,
  notify,
}: {
  entries: KnowledgeEntry[];
  onRefresh(): Promise<void>;
  onOpenSource(source: SourceRef): void;
  notify(message: string, error?: boolean): void;
}) {
  const [query, setQuery] = useState("");
  const [category, setCategory] = useState("全部概念");
  const [selected, setSelected] = useState<KnowledgeEntry | null>(null);
  const [creating, setCreating] = useState(false);
  const [title, setTitle] = useState("");
  const [definition, setDefinition] = useState("");
  const [source, setSource] = useState("");
  const [saving, setSaving] = useState(false);
  const categories = [
    "全部概念",
    ...new Set(entries.map((entry) => entry.category)),
  ];
  const filtered = useMemo(
    () =>
      entries.filter(
        (entry) =>
          (category === "全部概念" || category === entry.category) &&
          [entry.title, ...entry.aliases, entry.definition]
            .join(" ")
            .toLowerCase()
            .includes(query.toLowerCase()),
      ),
    [entries, category, query],
  );
  async function create() {
    if (!title.trim() || !definition.trim() || !source.trim()) {
      notify("请填写概念名称、解释及资料出处。", true);
      return;
    }
    setSaving(true);
    try {
      await postJson("/knowledge", {
        title,
        definition,
        body: definition,
        source,
        category: "自建概念",
        aliases: [],
        sources: [{ title: source }],
      });
      await onRefresh();
      setCreating(false);
      setTitle("");
      setDefinition("");
      setSource("");
      notify("概念已保存，阅读分析可以检索这份资料。");
    } catch (error) {
      notify(errorText(error), true);
    } finally {
      setSaving(false);
    }
  }
  return (
    <div className={styles.standardPage}>
      <div className={styles.pageHeading}>
        <div>
          <h1>
            教育概念库 <span>{entries.length}</span>
          </h1>
        </div>
        <button
          className={styles.primaryButton}
          onClick={() => setCreating(true)}
        >
          <Plus size={17} />
          添加概念
        </button>
      </div>

      <div className={styles.filterToolbar}>
        <div className={styles.filterTabs}>
          {categories.map((label) => (
            <button
              key={label}
              className={category === label ? styles.filterActive : ""}
              onClick={() => setCategory(label)}
            >
              {label}
            </button>
          ))}
        </div>
        <div className={styles.fieldWithIcon}>
          <Search size={16} />
          <input
            value={query}
            onChange={(event) => setQuery(event.target.value)}
            placeholder="搜索概念或别名…"
            aria-label="搜索教育概念"
          />
        </div>
      </div>
      <div className={styles.conceptGrid}>
        {filtered.map((entry) => (
          <button
            key={entry.id}
            className={styles.conceptCard}
            onClick={() => setSelected(entry)}
          >
            <div className={styles.conceptCardTop}>
              <span className={styles.conceptCategory}>{entry.category}</span>
              <ArrowUpRight size={17} />
            </div>
            <h2>{entry.title}</h2>
            <div className={styles.conceptAliases}>
              {entry.aliases.join(" · ") || "教育研究参考"}
            </div>
            <p>{entry.definition.replace(/[#*_>]/g, "").slice(0, 180)}</p>
            <footer>
              <BookMarked size={13} />
              <span>
                {entry.source || entry.sources[0]?.title || "已整理参考资料"}
              </span>
            </footer>
          </button>
        ))}
      </div>
      {!filtered.length && (
        <EmptyState
          icon={<GraduationCap size={25} />}
          title="还没有找到这个概念"
          description="试试别名，或把你的可靠参考资料加入概念库。"
        />
      )}
      {selected && (
        <Modal
          title={selected.title}
          subtitle={selected.aliases.join(" · ") || selected.category}
          onClose={() => setSelected(null)}
          wide
        >
          <div className={styles.modalBody}>
            <div className={styles.provenanceLabel}>
              <Check size={13} />
              {selected.origin === "seed"
                ? "预先整理的参考资料"
                : "用户补充资料"}
            </div>
            <div className={styles.articleBody}>
              <Markdown content={selected.body || selected.definition} />
            </div>
            <div className={styles.referenceBox}>
              <strong>
                <BookMarked size={15} />
                资料出处
              </strong>
              <p>{selected.source}</p>
              <SourceChips sources={selected.sources} onOpen={onOpenSource} />
            </div>
          </div>
        </Modal>
      )}
      {creating && (
        <Modal title="添加教育概念" onClose={() => setCreating(false)}>
          <div className={styles.modalBody}>
            <label className={styles.formLabel}>
              概念名称
              <input
                value={title}
                onChange={(event) => setTitle(event.target.value)}
                placeholder="例如：形成性评价"
              />
            </label>
            <label className={styles.formLabel}>
              概念解释
              <textarea
                rows={7}
                value={definition}
                onChange={(event) => setDefinition(event.target.value)}
                placeholder="定义、理论背景、适用情境，以及容易混淆的概念…"
              />
            </label>
            <label className={styles.formLabel}>
              资料出处
              <textarea
                rows={2}
                value={source}
                onChange={(event) => setSource(event.target.value)}
                placeholder="作者、书名或论文名、年份、页码或可靠链接"
              />
            </label>
          </div>
          <div className={styles.modalFooter}>
            <button
              className={styles.secondaryButton}
              onClick={() => setCreating(false)}
            >
              取消
            </button>
            <button
              className={styles.primaryButton}
              disabled={saving}
              onClick={() => void create()}
            >
              {saving ? "正在保存…" : "保存概念"}
            </button>
          </div>
        </Modal>
      )}
    </div>
  );
}

"use client";

import type { ResearchPaper } from "@/lib/research/types";
import {
  Check,
  ChevronDown,
  FileText,
  Grid2X2,
  Layers3,
  LayoutList,
  LoaderCircle,
  NotebookPen,
  Plus,
  Search,
  ShieldCheck,
  Tag,
  Trash2,
  Upload,
  X,
} from "lucide-react";
import { useRef, useState, type FormEvent } from "react";
import {
  displayDate,
  errorText,
  patchJson,
  postJson,
  researchApi,
  type WorkspaceSnapshot,
} from "./api";
import { EmptyState, Modal } from "./ResearchUi";
import styles from "./styles";
import {
  filterAndSortPapers,
  libraryTagOptions,
  type LibraryReadFilter,
  type LibrarySort,
} from "./library/filters";
import filterStyles from "./library/filters.module.css";
import coverStyles from "./library/cover.module.css";
import { PaperCover } from "./library/PaperCover";
import { PaperTrashModal, RemovePaperModal } from "./library/PaperTrash";
import trashStyles from "./library/trash.module.css";
import { uploadPendingPdfs } from "./library/upload-queue";

export function LibraryView({
  data,
  topic,
  setTopic,
  onUpload,
  onOpen,
  onRefresh,
  notify,
}: {
  data: WorkspaceSnapshot;
  topic: string;
  setTopic(value: string): void;
  onUpload(): void;
  onOpen(paper: ResearchPaper): void;
  onRefresh(): Promise<void>;
  onNotes(): void;
  onGraph(): void;
  notify(message: string, error?: boolean): void;
}) {
  const [filter, setFilter] = useState<LibraryReadFilter>("all");
  const [query, setQuery] = useState("");
  const [layout, setLayout] = useState("grid");
  const [selectedTags, setSelectedTags] = useState<string[]>([]);
  const [sort, setSort] = useState<LibrarySort>("added");
  const [importing, setImporting] = useState(false);
  const [edit, setEdit] = useState<ResearchPaper | null>(null);
  const [saving, setSaving] = useState(false);
  const [removeId, setRemoveId] = useState("");
  const [trashOpen, setTrashOpen] = useState(false);
  const topics = [
    "全部文献",
    ...new Set(data.papers.map((paper) => paper.topic)),
  ];
  const tagOptions = libraryTagOptions(data.papers);
  const currentTopic = topics.includes(topic) ? topic : "全部文献";
  const removingPaper = data.papers.find((paper) => paper.id === removeId);
  const noteCounts = new Map<string, number>();
  for (const note of data.notes)
    noteCounts.set(note.paperId, (noteCounts.get(note.paperId) ?? 0) + 1);
  const filtered = filterAndSortPapers(data.papers, {
    topic: currentTopic,
    readStatus: filter,
    query,
    tags: selectedTags,
    sort,
  });
  const hasFilters =
    filter !== "all" ||
    currentTopic !== "全部文献" ||
    !!query.trim() ||
    selectedTags.length > 0;
  function clearFilters() {
    setFilter("all");
    setTopic("全部文献");
    setQuery("");
    setSelectedTags([]);
  }
  async function examples() {
    setImporting(true);
    try {
      await postJson("/examples/import", {});
      await onRefresh();
      notify("示例论文已导入，可以开始阅读。");
    } catch (error) {
      notify(errorText(error), true);
    } finally {
      setImporting(false);
    }
  }
  async function updatePaper(event: FormEvent) {
    event.preventDefault();
    if (!edit) return;
    setSaving(true);
    try {
      await patchJson("/papers/" + edit.id, {
        title: edit.title,
        authors: edit.authors,
        year: edit.year,
        topic: edit.topic,
        tags: edit.tags,
        readStatus: edit.readStatus,
        version: edit.version,
      });
      await onRefresh();
      setEdit(null);
      notify("论文信息已更新。");
    } catch (error) {
      notify(errorText(error), true);
    } finally {
      setSaving(false);
    }
  }
  return (
    <div className={styles.libraryPage}>
      <div className={styles.welcomeHeading}>
        <h1>
          文献库 <span>{data.papers.length}</span>
        </h1>
        <div className={styles.actionRow}>
          <button
            className={styles.textButton}
            onClick={() => setTrashOpen(true)}
          >
            <Trash2 size={15} aria-hidden="true" />
            回收站
          </button>
          <button
            className={styles.textButton}
            disabled={importing}
            onClick={() => void examples()}
          >
            <Layers3 size={15} />
            {importing ? "正在导入…" : "导入示例"}
          </button>
          <div className={styles.layoutSwitch}>
            <button
              className={layout === "grid" ? styles.layoutActive : ""}
              onClick={() => setLayout("grid")}
              aria-label="网格视图"
              aria-pressed={layout === "grid"}
            >
              <Grid2X2 size={16} />
            </button>
            <button
              className={layout === "list" ? styles.layoutActive : ""}
              onClick={() => setLayout("list")}
              aria-label="列表视图"
              aria-pressed={layout === "list"}
            >
              <LayoutList size={17} />
            </button>
          </div>
          <button className={styles.primaryButton} onClick={onUpload}>
            <Plus size={17} />
            导入论文
          </button>
        </div>
      </div>
      <div className={styles.filterToolbar}>
        <div className={styles.filterTabs}>
          {[
            ["all", "全部文献"],
            ["unread", "未阅读"],
            ["reading", "阅读中"],
            ["finished", "已读完"],
          ].map(([value, label]) => (
            <button
              key={value}
              className={filter === value ? styles.filterActive : ""}
              onClick={() => setFilter(value as LibraryReadFilter)}
            >
              {label}
              {value === "all" && <span>{data.papers.length}</span>}
            </button>
          ))}
        </div>
        <div className={styles.libraryFilters}>
          <select
            value={currentTopic}
            onChange={(event) => setTopic(event.target.value)}
            aria-label="筛选研究主题"
          >
            {topics.map((label) => (
              <option key={label}>{label}</option>
            ))}
          </select>
          <div className={styles.fieldWithIcon}>
            <Search size={15} />
            <input
              value={query}
              onChange={(event) => setQuery(event.target.value)}
              placeholder="搜索当前文献…"
              aria-label="搜索文献库"
            />
          </div>
        </div>
      </div>
      <div className={filterStyles.utilityRow}>
        <div className={filterStyles.filterGroup}>
          {tagOptions.length > 0 && (
            <details className={filterStyles.tagMenu}>
              <summary>
                <Tag size={13} aria-hidden="true" />
                筛选标签
                {selectedTags.length > 0 && <span>{selectedTags.length}</span>}
                <ChevronDown size={13} aria-hidden="true" />
              </summary>
              <div className={filterStyles.tagPopover}>
                <p>多选时，论文需同时具备全部所选标签。</p>
                <div className={filterStyles.tagOptions}>
                  {tagOptions.map((tag) => (
                    <label key={tag.label}>
                      <input
                        type="checkbox"
                        aria-label={"筛选标签：" + tag.label}
                        checked={selectedTags.includes(tag.label)}
                        onChange={(event) =>
                          setSelectedTags((current) =>
                            event.target.checked
                              ? [...current, tag.label]
                              : current.filter((value) => value !== tag.label),
                          )
                        }
                      />
                      <span>{tag.label}</span>
                      <small>{tag.count}</small>
                    </label>
                  ))}
                </div>
              </div>
            </details>
          )}
          <span className={filterStyles.resultCount} aria-live="polite">
            显示 {filtered.length} / {data.papers.length} 篇
          </span>
          {hasFilters && (
            <button className={filterStyles.clear} onClick={clearFilters}>
              清除筛选
            </button>
          )}
        </div>
        <label className={filterStyles.sort}>
          <span>排序</span>
          <select
            aria-label="文献排序"
            value={sort}
            onChange={(event) => setSort(event.target.value as LibrarySort)}
          >
            <option value="added">最近导入</option>
            <option value="updated">最近更新</option>
            <option value="title">标题 A–Z</option>
          </select>
        </label>
      </div>
      {selectedTags.length > 0 && (
        <div className={filterStyles.selectedTags}>
          <span>同时包含</span>
          {selectedTags.map((tag) => (
            <button
              key={tag}
              onClick={() =>
                setSelectedTags((current) =>
                  current.filter((value) => value !== tag),
                )
              }
              aria-label={"移除标签筛选：" + tag}
            >
              {tag}
              <X size={12} aria-hidden="true" />
            </button>
          ))}
        </div>
      )}
      <div className={layout === "grid" ? styles.paperGrid : styles.paperList}>
        {filtered.map((paper) => (
          <article key={paper.id} className={styles.paperCard}>
            <button
              className={`${styles.paperMain} ${layout === "grid" ? coverStyles.gridMain : coverStyles.listMain}`}
              onClick={() => onOpen(paper)}
            >
              <PaperCover paper={paper} compact={layout === "list"} />
              <div className={styles.paperContent}>
                <div className={styles.paperCardMeta}>
                  <span className={styles.paperTopic}>{paper.topic}</span>
                  <span
                    className={
                      paper.readStatus === "reading"
                        ? styles.readingTag
                        : paper.readStatus === "finished"
                          ? styles.confirmedTag
                          : styles.unreadTag
                    }
                  >
                    {paper.readStatus === "reading"
                      ? "阅读中"
                      : paper.readStatus === "finished"
                        ? "已读完"
                        : "未阅读"}
                  </span>
                </div>
                <h3>{paper.title}</h3>
                <p className={styles.paperAuthors} title={paper.authors}>
                  {paper.authors || "作者信息待补充"}
                  {paper.year ? " · " + paper.year : ""}
                </p>
                <div className={styles.paperTags}>
                  {paper.tags
                    .filter((tag) => tag !== paper.topic)
                    .slice(0, 3)
                    .map((tag) => (
                      <span key={tag}>{tag}</span>
                    ))}
                </div>
              </div>
            </button>
            <footer>
              <span>
                <NotebookPen size={12} />
                {noteCounts.get(paper.id) ?? 0} 条笔记<span>·</span>
                {displayDate(paper.updatedAt)}
              </span>
              <div className={trashStyles.cardActions}>
                <button
                  onClick={() => setEdit({ ...paper })}
                  aria-label={"编辑论文信息：" + paper.title}
                >
                  编辑信息
                </button>
                <button
                  className={trashStyles.removeButton}
                  onClick={() => setRemoveId(paper.id)}
                  aria-label={"删除论文：" + paper.title}
                >
                  <Trash2 size={12} aria-hidden="true" />
                  删除
                </button>
              </div>
            </footer>
          </article>
        ))}
      </div>
      {!filtered.length && data.papers.length > 0 && (
        <EmptyState
          title="这个范围里还没有论文"
          description="换一个标签、阅读状态、主题或关键词，或点击“清除筛选”。"
        />
      )}
      {data.papers.length === 0 && (
        <EmptyState
          title="文献库为空"
          description="导入 PDF 开始阅读，或从回收站恢复论文。"
        />
      )}

      {removingPaper && (
        <RemovePaperModal
          paper={removingPaper}
          onClose={() => setRemoveId("")}
          onRefresh={onRefresh}
          notify={notify}
          onRemoved={() => {
            setEdit(null);
            const remaining = data.papers.filter(
              (paper) => paper.id !== removeId,
            );
            if (!remaining.some((paper) => paper.topic === topic))
              setTopic("全部文献");
            const remainingTags = new Set(
              libraryTagOptions(remaining).map((tag) => tag.label),
            );
            setSelectedTags((current) =>
              current.filter((tag) => remainingTags.has(tag)),
            );
          }}
        />
      )}
      {trashOpen && (
        <PaperTrashModal
          onClose={() => setTrashOpen(false)}
          onRefresh={onRefresh}
          notify={notify}
        />
      )}

      {edit && (
        <Modal title="整理论文信息" onClose={() => setEdit(null)}>
          <form onSubmit={(event) => void updatePaper(event)}>
            <div className={styles.modalBody}>
              <label className={styles.formLabel}>
                论文标题
                <input
                  required
                  value={edit.title}
                  onChange={(event) =>
                    setEdit({ ...edit, title: event.target.value })
                  }
                />
              </label>
              <div className={styles.formColumns}>
                <label className={styles.formLabel}>
                  作者
                  <input
                    value={edit.authors}
                    onChange={(event) =>
                      setEdit({ ...edit, authors: event.target.value })
                    }
                  />
                </label>
                <label className={styles.formLabel}>
                  年份
                  <input
                    value={edit.year}
                    onChange={(event) =>
                      setEdit({ ...edit, year: event.target.value })
                    }
                  />
                </label>
              </div>
              <label className={styles.formLabel}>
                研究主题
                <input
                  value={edit.topic}
                  onChange={(event) =>
                    setEdit({ ...edit, topic: event.target.value })
                  }
                />
              </label>
              <label className={styles.formLabel}>
                标签 · 用逗号分隔
                <input
                  value={edit.tags.join("，")}
                  onChange={(event) =>
                    setEdit({
                      ...edit,
                      tags: event.target.value
                        .split(/[,，]/)
                        .map((tag) => tag.trim())
                        .filter(Boolean),
                    })
                  }
                />
              </label>
              <label className={styles.formLabel}>
                阅读状态
                <select
                  value={edit.readStatus}
                  onChange={(event) =>
                    setEdit({
                      ...edit,
                      readStatus: event.target
                        .value as ResearchPaper["readStatus"],
                    })
                  }
                >
                  <option value="unread">未阅读</option>
                  <option value="reading">阅读中</option>
                  <option value="finished">已读完</option>
                </select>
              </label>
            </div>
            <div className={styles.modalFooter}>
              <button
                type="button"
                className={styles.secondaryButton}
                onClick={() => setEdit(null)}
              >
                取消
              </button>
              <button
                type="submit"
                className={styles.primaryButton}
                disabled={saving}
              >
                {saving ? "保存中…" : "保存信息"}
              </button>
            </div>
          </form>
        </Modal>
      )}
    </div>
  );
}

export function UploadModal({
  onClose,
  onRefresh,
  notify,
}: {
  onClose(): void;
  onRefresh(): Promise<void>;
  notify(message: string, error?: boolean): void;
}) {
  const [files, setFiles] = useState<File[]>([]);
  const [topic, setTopic] = useState("");
  const [uploading, setUploading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [failure, setFailure] = useState("");
  const [dragging, setDragging] = useState(false);
  const input = useRef<HTMLInputElement>(null);
  const uploadLock = useRef(false);
  const uploaded = useRef(new Set<File>());
  const [completedFiles, setCompletedFiles] = useState(() => new Set<File>());
  const pendingCount = files.filter((file) => !completedFiles.has(file)).length;
  function addFiles(list: FileList | File[]) {
    if (uploadLock.current) return;
    const selected = Array.from(list).filter((file) =>
      file.name.toLowerCase().endsWith(".pdf"),
    );
    if (selected.length !== list.length)
      notify("目前支持 PDF 文件，请选择 .pdf 文档。", true);
    if (selected.some((file) => file.size > 100 * 1024 * 1024)) {
      notify("单篇 PDF 请控制在 100 MB 内。", true);
      return;
    }
    setFiles((current) => [
      ...current,
      ...selected.filter(
        (file) =>
          !current.some(
            (old) => old.name === file.name && old.size === file.size,
          ),
      ),
    ]);
  }
  async function upload() {
    const pending = files.filter((file) => !uploaded.current.has(file));
    if (!pending.length || uploadLock.current) return;
    uploadLock.current = true;
    setUploading(true);
    setFailure("");
    let count = 0;
    let currentFile = "";
    try {
      await uploadPendingPdfs(
        pending,
        uploaded.current,
        async (file) => {
          currentFile = file.name;
          const form = new FormData();
          form.set("file", file);
          if (topic.trim()) form.set("topic", topic.trim());
          await researchApi("/papers", { method: "POST", body: form });
        },
        () => {
          count++;
          setCompletedFiles(new Set(uploaded.current));
          setProgress(uploaded.current.size);
        },
      );
      try {
        await onRefresh();
        notify("已导入 " + uploaded.current.size + " 篇论文。");
      } catch {
        notify("论文已导入，请刷新页面更新文献库。", true);
      }
      onClose();
    } catch (error) {
      setFailure(currentFile + "：" + errorText(error));
      await onRefresh().catch(() => undefined);
      notify(
        (count ? "已导入 " + count + " 篇。" : "") + errorText(error),
        true,
      );
    } finally {
      uploadLock.current = false;
      setUploading(false);
    }
  }
  return (
    <Modal
      title="导入研究论文"
      onClose={() => {
        if (!uploading) onClose();
      }}
    >
      <div className={styles.modalBody}>
        <input
          ref={input}
          type="file"
          accept=".pdf,application/pdf"
          multiple
          className={styles.hiddenInput}
          onChange={(event) => {
            if (event.target.files) addFiles(event.target.files);
            event.target.value = "";
          }}
        />
        <button
          className={dragging ? styles.dropzoneActive : styles.dropzone}
          disabled={uploading}
          onClick={() => input.current?.click()}
          onDragOver={(event) => {
            event.preventDefault();
            setDragging(true);
          }}
          onDragLeave={() => setDragging(false)}
          onDrop={(event) => {
            event.preventDefault();
            setDragging(false);
            addFiles(event.dataTransfer.files);
          }}
        >
          <span>
            <Upload size={27} />
          </span>
          <strong>将 PDF 拖到这里，或点击选择</strong>
          <p>支持多篇导入 · 单篇不超过 100 MB</p>
        </button>
        {files.length > 0 && (
          <div className={styles.uploadFiles}>
            {files.map((file, index) => (
              <div key={file.name + ":" + file.size}>
                <FileText size={17} />
                <span>
                  {file.name}
                  <small>{(file.size / 1024 / 1024).toFixed(1)} MB</small>
                </span>
                {completedFiles.has(file) ? (
                  <Check size={16} aria-label="已导入" />
                ) : (
                  <button
                    disabled={uploading}
                    onClick={() =>
                      setFiles(files.filter((_, at) => at !== index))
                    }
                    aria-label={"移除 " + file.name}
                  >
                    <X size={15} />
                  </button>
                )}
              </div>
            ))}
          </div>
        )}
        {failure && (
          <p className={trashStyles.error} role="alert">
            {failure}
          </p>
        )}
        <label className={styles.formLabel}>
          研究主题 <span>选填</span>
          <input
            value={topic}
            onChange={(event) => setTopic(event.target.value)}
            placeholder="例如：课堂评价与教学改进"
            disabled={uploading}
          />
        </label>
        <div className={styles.softInfo}>
          <ShieldCheck size={15} />
          文件保存在本机，仅分析时发送相关片段至模型服务。
        </div>
      </div>
      <div className={styles.modalFooter}>
        <button
          className={styles.secondaryButton}
          disabled={uploading}
          onClick={onClose}
        >
          {progress > 0 ? "关闭" : "取消"}
        </button>
        <button
          className={styles.primaryButton}
          disabled={!pendingCount || uploading}
          onClick={() => void upload()}
        >
          {uploading ? (
            <LoaderCircle size={15} className={styles.spin} />
          ) : (
            <Upload size={15} />
          )}
          {uploading
            ? "正在导入 " +
              Math.min(progress + 1, files.length) +
              " / " +
              files.length
            : failure && pendingCount
              ? "重试剩余 " + pendingCount + " 篇"
              : pendingCount
                ? "导入 " + pendingCount + " 篇论文"
                : "导入论文"}
        </button>
      </div>
    </Modal>
  );
}

"use client";

import { StudyMarkdown } from "./study/StudyMarkdown";
import type {
  ResearchNote,
  ResearchPaper,
  SourceRef,
} from "@/lib/research/types";
import {
  BookOpen,
  Check,
  Download,
  Eye,
  FilePenLine,
  ListChecks,
  NotebookPen,
  Plus,
  Save,
  Search,
} from "lucide-react";
import { useEffect, useMemo, useRef, useState } from "react";
import { displayDate, errorText, noteLabels } from "./api";
import { EmptyState, SourceChips } from "./ResearchUi";
import { PaperTrashModal } from "./library/PaperTrash";
import styles from "./styles";
import {
  editableNote,
  type EditableNote,
  type LocalNoteDraft,
} from "./learning/note-drafts";
import {
  NoteDraftFeedback,
  NoteDraftShelf,
  NoteDraftStatus,
  NoteLeaveConfirm,
} from "./learning/NoteDraftFeedback";
import { useNoteEditor } from "./learning/use-note-editor";

export function ResearchNotes({
  notes,
  papers,
  initialNoteId,
  onRefresh,
  onOpenSource,
  onReview,
  notify,
}: {
  notes: ResearchNote[];
  papers: ResearchPaper[];
  initialNoteId?: string;
  onRefresh(): Promise<void>;
  onOpenSource(source: SourceRef): void;
  onReview(note: ResearchNote): void | Promise<void>;
  notify(message: string, error?: boolean): void;
}) {
  // The parent remounts only for explicit note navigation; snapshot refreshes
  // must never replace the user's in-progress editor contents.
  const initialNote = initialNoteId
    ? notes.find((note) => note.id === initialNoteId)
    : notes[0];
  const empty = (origin: string): EditableNote => ({
    paperId: papers[0]?.id ?? "",
    title: "",
    body: "",
    kind: "reading",
    sources: [],
    confirmed: false,
    origin,
  });
  const editor = useNoteEditor(
    initialNote ? editableNote(initialNote) : empty("manual"),
    notes,
  );
  const { id: activeId, title, body, paperId, kind, sources } = editor.model;
  const [preview, setPreview] = useState(false);
  const saving = editor.busy;
  const [reviewing, setReviewing] = useState(false);
  const reviewLock = useRef(false);
  const [query, setQuery] = useState("");
  const [trashOpen, setTrashOpen] = useState(false);
  const [pendingLeave, setPendingLeave] = useState<(() => void) | null>(null);
  const active = notes.find((note) => note.id === activeId);
  const filtered = useMemo(
    () =>
      [...notes]
        .filter((note) =>
          (note.title + note.body).toLowerCase().includes(query.toLowerCase()),
        )
        .sort((a, b) => b.updatedAt.localeCompare(a.updatedAt)),
    [notes, query],
  );
  const dirty = editor.unsaved;
  const disabled = saving || reviewing || !editor.ready || editor.blocked;

  function select(note?: ResearchNote) {
    if (disabled) return;
    requestLeave(() => {
      void editor.open(
        note ? editableNote(note) : empty("manual-" + crypto.randomUUID()),
      );
      setPreview(false);
    });
  }
  function recover(entry: LocalNoteDraft) {
    if (disabled) return;
    requestLeave(() => {
      const note = notes.find((item) => item.id === entry.model.id);
      void editor.open(note ? editableNote(note) : entry.model, entry);
      setPreview(false);
    });
  }
  function requestLeave(action: () => void) {
    if (disabled) return;
    if (editor.protectLeave) {
      setPendingLeave(() => action);
      return;
    }
    setPendingLeave(null);
    action();
  }
  async function save(confirmed = false, asNew = false) {
    if (reviewing) return;
    if (paperId && !papers.some((paper) => paper.id === paperId)) {
      notify(
        "关联文献已移出文献库，请恢复文献后保存。当前编辑内容已保留。",
        true,
      );
      return;
    }
    await editor.save({
      confirmed,
      asNew,
      onSaved: async () => {
        await onRefresh();
      },
      notify,
    });
  }
  useEffect(() => {
    const keydown = (event: KeyboardEvent) => {
      if (
        (event.ctrlKey || event.metaKey) &&
        event.key.toLowerCase() === "s" &&
        !event.altKey
      ) {
        event.preventDefault();
        if (
          !reviewing &&
          papers.some((paper) => paper.id === editor.model.paperId)
        )
          void editor.save({
            onSaved: async () => {
              await onRefresh();
            },
            notify,
          });
      }
    };
    window.addEventListener("keydown", keydown);
    return () => window.removeEventListener("keydown", keydown);
  }, [editor, reviewing, papers, onRefresh, notify]);
  const paper = papers.find((entry) => entry.id === paperId);
  const paperUnavailable = !!paperId && !paper;
  async function review() {
    if (
      !active ||
      dirty ||
      disabled ||
      !!editor.server ||
      reviewLock.current ||
      paperUnavailable
    )
      return;
    reviewLock.current = true;
    setReviewing(true);
    try {
      await onReview(active);
    } catch (error) {
      notify(errorText(error), true);
    } finally {
      reviewLock.current = false;
      setReviewing(false);
    }
  }
  return (
    <div className={styles.notesPage}>
      <div className={styles.pageHeading}>
        <div>
          <h1>研究笔记</h1>
        </div>
        <div className={styles.actionRow}>
          <a
            className={styles.secondaryButton}
            href="/api/research/export?format=markdown"
            download
          >
            <Download size={16} />
            导出笔记
          </a>
          <button
            className={styles.primaryButton}
            onClick={() => select()}
            disabled={disabled}
          >
            <Plus size={17} />
            新建笔记
          </button>
        </div>
      </div>
      <NoteDraftShelf
        editor={editor}
        papers={papers}
        notes={notes}
        onRecover={recover}
      />
      <div className={styles.notesLayout}>
        <aside className={styles.notesList}>
          <div className={styles.notesListHeader}>
            <strong>
              全部笔记 <span>{notes.length}</span>
            </strong>
            <div className={styles.fieldWithIcon}>
              <Search size={15} />
              <input
                value={query}
                onChange={(event) => setQuery(event.target.value)}
                placeholder="查找标题或内容…"
                aria-label="搜索笔记"
              />
            </div>
          </div>
          <div className={styles.notesItems}>
            {filtered.map((note) => (
              <button
                key={note.id}
                className={
                  activeId === note.id ? styles.noteItemActive : styles.noteItem
                }
                onClick={() => select(note)}
                disabled={disabled}
              >
                <div className={styles.smallMeta}>
                  <span>{noteLabels[note.kind]}</span>
                  <span>{displayDate(note.updatedAt)}</span>
                </div>
                <h3>{note.title}</h3>
                <p>{note.body.replace(/[#*_>]/g, "").slice(0, 90)}</p>
                <span
                  className={
                    note.confirmed ? styles.confirmedTag : styles.draftTag
                  }
                >
                  {note.confirmed ? (
                    <Check size={11} />
                  ) : (
                    <FilePenLine size={11} />
                  )}
                  {note.confirmed ? "已确认" : "草稿"}
                </span>
              </button>
            ))}
            {!filtered.length && (
              <EmptyState
                icon={<NotebookPen size={22} />}
                title="暂无笔记"
                description=""
              />
            )}
          </div>
        </aside>
        <section className={styles.noteEditor}>
          <div className={styles.editorToolbar}>
            <div className={styles.segmented}>
              <button
                className={!preview ? styles.segmentActive : ""}
                onClick={() => setPreview(false)}
              >
                <FilePenLine size={14} />
                编辑
              </button>
              <button
                className={preview ? styles.segmentActive : ""}
                onClick={() => setPreview(true)}
              >
                <Eye size={14} />
                预览
              </button>
            </div>
            <div className={styles.actionRow}>
              <span className={styles.mutedSmall}>
                <NoteDraftStatus editor={editor} />
              </span>
              <button
                className={styles.secondaryButton}
                onClick={() => void review()}
                disabled={
                  !active ||
                  dirty ||
                  disabled ||
                  !!editor.server ||
                  paperUnavailable
                }
                title={
                  dirty ? "请先保存修改，再开始复习" : "从这份笔记开始复习"
                }
              >
                <ListChecks size={15} />
                {reviewing ? "正在准备…" : "复习这份笔记"}
              </button>
              <button
                className={styles.secondaryButton}
                onClick={() => void save()}
                disabled={
                  disabled || !!editor.server || paperUnavailable || !dirty
                }
              >
                <Save size={14} />
                保存
              </button>
              <button
                className={styles.primaryButton}
                onClick={() => void save(true)}
                disabled={
                  disabled ||
                  !!editor.server ||
                  paperUnavailable ||
                  !body.trim() ||
                  (!!active?.confirmed && !dirty)
                }
              >
                <Check size={15} />
                确认入库
              </button>
            </div>
          </div>
          <div className={styles.editorInner}>
            <NoteDraftFeedback
              editor={editor}
              onSaveCopy={() => void save(false, true)}
            />
            {pendingLeave && editor.protectLeave && (
              <NoteLeaveConfirm
                disabled={saving}
                onCancel={() => setPendingLeave(null)}
                onContinue={() => {
                  if (disabled) return;
                  setPendingLeave(null);
                  pendingLeave();
                }}
              />
            )}
            {paperUnavailable && (
              <div className={styles.softInfo} role="status">
                <span>
                  关联文献已移出文献库。恢复文献后可保存当前编辑内容。
                </span>
                <button
                  className={styles.textButton}
                  onClick={() => setTrashOpen(true)}
                >
                  打开回收站
                </button>
              </div>
            )}
            <div className={styles.editorMeta}>
              <select
                value={kind}
                onChange={(event) =>
                  editor.change({
                    kind: event.target.value as ResearchNote["kind"],
                  })
                }
                aria-label="笔记类型"
                disabled={disabled}
              >
                {Object.entries(noteLabels).map(([value, label]) => (
                  <option key={value} value={value}>
                    {label}
                  </option>
                ))}
              </select>
              <span>·</span>
              <select
                value={paperId}
                onChange={(event) =>
                  editor.change({ paperId: event.target.value })
                }
                aria-label="关联论文"
                disabled={disabled || !!activeId}
                title={activeId ? "已保存笔记的关联论文固定" : undefined}
              >
                <option value="">关联一篇论文</option>
                {papers.map((entry) => (
                  <option key={entry.id} value={entry.id}>
                    {entry.title}
                  </option>
                ))}
              </select>
            </div>
            <input
              className={styles.noteTitleInput}
              placeholder="给这份思考一个标题…"
              value={title}
              onChange={(event) => editor.change({ title: event.target.value })}
              aria-label="笔记标题"
              maxLength={500}
              readOnly={disabled}
            />
            {sources.length > 0 && (
              <div className={styles.editorSources}>
                <span>
                  <BookOpen size={13} />
                  原文依据
                </span>
                <SourceChips
                  sources={sources}
                  onOpen={(source) => {
                    requestLeave(() => onOpenSource(source));
                  }}
                />
              </div>
            )}
            {preview ? (
              <div className={styles.notePreview}>
                <StudyMarkdown content={body || "还没有正文。"} />
              </div>
            ) : (
              <textarea
                className={styles.noteBodyInput}
                value={body}
                onChange={(event) =>
                  editor.change({ body: event.target.value })
                }
                aria-label="Markdown 笔记正文"
                maxLength={200000}
                readOnly={disabled}
                placeholder={"## 重要发现\n\n## 原文依据\n\n## 我的思考"}
              />
            )}
          </div>
          <footer className={styles.editorFooter}>
            <span>{body.length} 字符 · Markdown · Ctrl / ⌘ + S</span>
            <span>
              {paper ? "关联：" + paper.title.slice(0, 34) : "尚未关联论文"}
            </span>
          </footer>
        </section>
      </div>
      {trashOpen && (
        <PaperTrashModal
          onClose={() => setTrashOpen(false)}
          onRefresh={onRefresh}
          notify={notify}
        />
      )}
    </div>
  );
}

"use client";

import { PdfReader, type PdfReaderEditState } from "@/components/pdf/PdfReader";
import type {
  ResearchAnnotation,
  KnowledgeEntry,
  ResearchMode,
  ResearchNote,
  ResearchPaper,
  ResearchRun,
  ResearchSelection,
  SourceRef,
} from "@/lib/research/types";
import { BookOpen, Highlighter, NotebookPen, Sparkles } from "lucide-react";
import { useCallback, useEffect, useRef, useState } from "react";
import {
  errorText,
  isRunActive,
  postJson,
  researchApi,
  type PaperDetail,
} from "./api";
import { responseSources, type ResearchProposal } from "./reader-context";
import { ReaderAnnotations } from "./study/ReaderAnnotations";
import { ReadingControls } from "./study/ReadingControls";
import { ResizableReader } from "./reader-layout/ResizableReader";
import { ReaderTextSize, useReaderTextSize } from "./study/ReaderTextSize";
import type { LearningRequest } from "@/lib/research/learning-types";
import { learningTitle } from "@/lib/research/learning-types";
import { NoteEditor, type NoteDraft } from "./learning/NoteEditor";
import { ReaderNotes } from "./learning/ReaderNotes";
import { LearningComposer } from "./learning/LearningComposer";
import {
  parseReviewMarkdown,
  reviewFromRun,
  reviewFromNote,
} from "./learning/review-actions";
import { ReaderCommentDialog } from "./reader-layout/ReaderCommentDialog";
import { ReaderSelectionBar } from "./annotations/ReaderSelectionBar";
import { useQuickHighlight } from "./annotations/useQuickHighlight";
import { ReaderAnswer } from "./qa/ReaderAnswer";
import { ReaderQuestionComposer } from "./qa/ReaderQuestionComposer";
import { useQuestionDraft } from "./qa/useQuestionDraft";
import { DiscussionControls } from "./qa/discussion/DiscussionControls";
import {
  ReaderConversation,
  RecentDiscussions,
} from "./qa/discussion/ReaderConversation";
import { questionSignature } from "./qa/question-draft";
import { useHighlightColor } from "./annotations/useHighlightColor";
import { HighlightUndoNotice } from "./annotations/HighlightUndoNotice";
import { captureReaderSelection } from "./reader-layout/capture-selection";
import { findPassageDiscussion } from "./qa/discussion/passage-thread";
import styles from "./styles";
export interface ReaderJump {
  page?: number;
  quote?: string;
  nonce: number;
  learning?: LearningRequest;
}
export function ResearchReader({
  paper,
  papers,
  knowledge,
  history,
  jump,
  onRefresh,
  onOpenSource,
  notify,
  onOpenReview,
}: {
  paper: ResearchPaper;
  papers: ResearchPaper[];
  knowledge: KnowledgeEntry[];
  history: ResearchRun[];
  jump: ReaderJump | null;
  onRefresh(): Promise<void>;
  onOpenSource(source: SourceRef): void;
  notify(message: string, error?: boolean): void;
  onOpenReview(deckId: string, paperId: string): void;
}) {
  const [detail, setDetail] = useState<PaperDetail | null>(null);
  const [tab, setTab] = useState<"ai" | "notes" | "annotations">("ai");
  const textSize = useReaderTextSize();
  const highlightColor = useHighlightColor();
  const [currentPage, setCurrentPage] = useState(
    jump?.page ?? paper.lastReadPage ?? 1,
  );
  const [selectionToolsVisible, setSelectionToolsVisible] = useState(true);
  const questionDraft = useQuestionDraft(paper, papers);
  const {
    selection,
    setSelection,
    question,
    setQuestion,
    sourcePaperIds,
    setSourcePaperIds,
    answerStyle = "discussion",
    setAnswerStyle,
    referenceConceptIds,
    setReferenceConceptIds,
  } = questionDraft;
  const activeSourceIds = sourcePaperIds.filter((id) =>
    papers.some((entry) => entry.id === id),
  );
  const [run, setRun] = useState<ResearchRun | null>(
    () =>
      history
        .filter((entry) => entry.paperId === paper.id && entry.mode !== "graph")
        .sort((a, b) => b.createdAt.localeCompare(a.createdAt))[0] ?? null,
  );
  const [starting, setStarting] = useState(false);
  const [connectionWarning, setConnectionWarning] = useState("");
  const [commentText, setCommentText] = useState("");
  const [commentPage, setCommentPage] = useState(1);
  const [commentSelection, setCommentSelection] =
    useState<ResearchSelection | null>(null);
  const [commentOpen, setCommentOpen] = useState(false);
  const [commentSaving, setCommentSaving] = useState(false);
  const [noteDraft, setNoteDraft] = useState<NoteDraft | null>(null);
  const [learningComposer, setLearningComposer] =
    useState<LearningRequest | null>(jump?.learning ?? null);
  const [pendingLearning, setPendingLearning] = useState<{
    runId: string;
    task: LearningRequest["task"];
  } | null>(null);
  const [reviewSaving, setReviewSaving] = useState(false);
  const [draftProposal, setDraftProposal] = useState<ResearchProposal | null>(
    null,
  );
  const [permissionPending, setPermissionPending] = useState("");
  const readerRoot = useRef<HTMLDivElement>(null);
  const questionInput = useRef<HTMLTextAreaElement>(null);
  const assistantScroll = useRef<HTMLDivElement>(null);
  const startLocked = useRef(false);
  const reviewLocked = useRef(false);
  const handledLearning = useRef(new Set<string>());
  const commentActionId = useRef("");
  const commentLocked = useRef(false);
  const nativeEdit = useRef<PdfReaderEditState>({
    dirty: false,
    saving: false,
  });
  const [readerGeneration, setReaderGeneration] = useState(0);
  const active = starting || isRunActive(run);
  const src = "/api/research/papers/" + paper.id + "/pdf";
  useEffect(() => {
    assistantScroll.current?.scrollTo({ top: 0 });
  }, [run?.id]);

  const loadDetail = useCallback(async () => {
    const result = await researchApi<PaperDetail>("/papers/" + paper.id);
    setDetail(result);
  }, [paper.id]);
  function canWriteAnnotation() {
    if (nativeEdit.current.dirty || nativeEdit.current.saving) {
      notify("请等待当前批注保存完成。", true);
      return false;
    }
    return true;
  }
  const quickHighlight = useQuickHighlight({
    paper,
    detail,
    color: highlightColor.color,
    beforeWrite: canWriteAnnotation,
    onSaved: async () => {
      setReaderGeneration((generation) => generation + 1);
      setSelectionToolsVisible(false);
      await loadDetail();
      await onRefresh();
    },
    notify,
  });
  useEffect(() => {
    void researchApi<PaperDetail>("/papers/" + paper.id)
      .then(setDetail)
      .catch((error: unknown) => notify(errorText(error), true));
  }, [paper.id, notify]);

  const onPdfEdit = useCallback(
    (state: PdfReaderEditState) => {
      const hadEdits = nativeEdit.current.dirty || nativeEdit.current.saving;
      nativeEdit.current = state;
      if (state.dirty || state.saving) setSelection(null);
      if (hadEdits && !state.dirty && !state.saving) {
        void loadDetail().catch((error: unknown) =>
          notify(errorText(error), true),
        );
      }
    },
    [loadDetail, notify, setSelection],
  );
  const activeRunId = run && isRunActive(run) ? run.id : null;
  useEffect(() => {
    if (!activeRunId) return;
    let disposed = false;
    let timer: ReturnType<typeof setTimeout>;
    const id = activeRunId;
    async function poll() {
      try {
        const result = await researchApi<{ run: ResearchRun }>("/runs/" + id);
        if (disposed) return;
        setRun(result.run);
        setConnectionWarning("");
        if (!isRunActive(result.run)) {
          await onRefresh();
          return;
        }
      } catch {
        if (!disposed)
          setConnectionWarning("连接暂时中断，正在重新获取分析进度…");
      }
      if (!disposed) timer = setTimeout(() => void poll(), 650);
    }
    timer = setTimeout(() => void poll(), 350);
    return () => {
      disposed = true;
      clearTimeout(timer);
    };
  }, [activeRunId, onRefresh]);

  useEffect(() => {
    if (!jump?.page || !readerRoot.current) return;
    const pageNumber = jump.page;
    let tries = 0;
    const timer = setInterval(() => {
      const readyReader = readerRoot.current?.querySelector<HTMLElement>(
        '[data-pdf-ready="true"]',
      );
      const target = readyReader?.querySelector<HTMLElement>(
        '.page[data-page-number="' + pageNumber + '"]',
      );
      if (target) {
        target.scrollIntoView({ block: "start", behavior: "smooth" });
        target.classList.add(...styles.citationTarget.split(/\s+/));
        setTimeout(
          () => target.classList.remove(...styles.citationTarget.split(/\s+/)),
          2400,
        );
        clearInterval(timer);
      } else if (++tries > 35) clearInterval(timer);
    }, 200);
    return () => clearInterval(timer);
  }, [jump]);
  function captureSelection() {
    if (!readerRoot.current) return;
    captureReaderSelection(
      readerRoot.current,
      detail,
      paper,
      (next) => {
        setSelection(next);
        setSelectionToolsVisible(!!next);
      },
      (message) => notify(message, true),
    );
  }
  async function start(
    mode: ResearchMode,
    prompt?: string,
    learning?: LearningRequest,
    explicitSelection?: ResearchSelection,
  ): Promise<boolean> {
    const fromInput = mode === "ask" && prompt === undefined && !learning;
    const submitted = fromInput ? questionDraft.capture() : undefined;
    const submittedSettings = questionDraft.capture();
    const value = learning
      ? learningTitle(learning)
      : (prompt ?? submitted?.question ?? question).trim();
    if (!value && mode === "ask") return false;
    if (active || startLocked.current) return false;
    startLocked.current = true;
    setStarting(true);
    setTab("ai");
    try {
      const result = await postJson<{ run: ResearchRun }>("/runs", {
        paperId: paper.id,
        question:
          value ||
          (mode === "card"
            ? "请生成一份有原文依据的结构化论文卡。"
            : "请分析这篇论文的研究问题、方法、结果与局限。"),
        mode,
        learning,
        answerStyle: submittedSettings.answerStyle ?? answerStyle,
        referenceConceptIds:
          (submittedSettings.answerStyle ?? answerStyle) === "grounded"
            ? []
            : submittedSettings.referenceConceptIds,
        selection:
          explicitSelection ??
          (submitted ? submitted.selection : selection) ??
          undefined,
        sourcePaperIds:
          mode === "ask" && !learning && !value.startsWith("[学习笔记:")
            ? (submitted?.sourcePaperIds ?? activeSourceIds).filter((id) =>
                papers.some((entry) => entry.id === id),
              )
            : undefined,
      });
      setRun(result.run);
      if (learning)
        setPendingLearning({ runId: result.run.id, task: learning.task });
      if (submitted) questionDraft.clearAccepted(submitted);
      if (
        result.run.answerStyle === "discussion" &&
        questionSignature({ ...questionDraft.capture(), question: "" }) ===
          questionSignature({ ...submittedSettings, question: "" }) &&
        submittedSettings.referenceConceptIds === undefined
      )
        setReferenceConceptIds(result.run.referenceConceptIds ?? []);
      setConnectionWarning("");
      return true;
    } catch (error) {
      notify(errorText(error), true);
      return false;
    } finally {
      startLocked.current = false;
      setStarting(false);
    }
  }
  async function cancel() {
    if (!run) return;
    try {
      const result = await postJson<{ run: ResearchRun }>("/runs/" + run.id, {
        action: "cancel",
      });
      setRun(result.run);
      await onRefresh();
    } catch (error) {
      notify(errorText(error), true);
    }
  }
  async function permission(
    toolUseId: string,
    decision: "allow_once" | "deny_once",
  ) {
    if (!run) return;
    setPermissionPending(toolUseId);
    try {
      await postJson("/runs/" + run.id + "/permission", {
        toolUseId,
        decision,
      });
    } catch (error) {
      notify(errorText(error), true);
    } finally {
      setPermissionPending("");
    }
  }
  function prepareNote(
    body: string,
    title: string,
    suppliedSources?: SourceRef[],
    originatingRun: ResearchRun | null = run,
    origin?: string,
  ) {
    setDraftProposal(null);
    setNoteDraft({
      title,
      body,
      origin,
      runId: originatingRun?.id,
      kind: originatingRun?.mode === "card" ? "card" : "reading",
      sources:
        suppliedSources ??
        (selection && body.startsWith("> ")
          ? [
              {
                paperId: paper.id,
                page: selection.page,
                quote: selection.quote,
                contentRevision: selection.contentRevision,
                title: paper.title,
              },
            ]
          : responseSources(body, {
              ...paper,
              contentRevision: run?.contentRevision ?? paper.contentRevision,
            })),
    });
  }
  function prepareComment(
    text: string,
    page?: number,
    source?: ResearchSelection | null,
  ) {
    if (!canWriteAnnotation()) return;
    setDraftProposal(null);
    const anchor = source === undefined ? (page ? null : selection) : source;
    setCommentSelection(anchor);
    commentActionId.current = crypto.randomUUID();
    setCommentText(text);
    const visiblePage = Number(
      readerRoot.current
        ?.querySelector("[data-pdf-page]")
        ?.getAttribute("data-pdf-page"),
    );
    setCommentPage(
      page ??
        anchor?.page ??
        (visiblePage > 0 ? visiblePage : (jump?.page ?? 1)),
    );
    setCommentOpen(true);
  }
  function prepareProposal(proposal: ResearchProposal) {
    if (
      !run?.contentRevision ||
      run.contentRevision !==
        (detail?.paper.contentRevision ?? paper.contentRevision)
    ) {
      notify("论文正文已变化或来源版本缺失，请重新分析后保存。", true);
      return;
    }
    if (proposal.kind === "note") {
      prepareNote(proposal.body, proposal.title);
      setNoteDraft({
        title: proposal.title,
        body: proposal.body,
        runId: run.id,
        sources: [
          {
            paperId: paper.id,
            page: proposal.page,
            quote: proposal.quote,
            contentRevision: run.contentRevision,
            title: paper.title,
          },
        ],
      });
    } else {
      prepareComment(proposal.body);
      setCommentPage(proposal.page ?? 1);
      commentActionId.current = proposal.id;
    }
    setDraftProposal(proposal);
  }
  async function verifyProposalVersion() {
    if (!draftProposal) return true;
    const latest = await researchApi<PaperDetail>("/papers/" + paper.id);
    setDetail(latest);
    if (
      !run?.contentRevision ||
      draftProposal.run_id !== run.id ||
      run.contentRevision !== latest.paper.contentRevision
    ) {
      notify("论文正文已变化或来源版本缺失，请重新分析后保存。", true);
      return false;
    }
    return true;
  }
  async function saveComment() {
    if (!commentText.trim() || commentLocked.current) return;
    if (nativeEdit.current.dirty || nativeEdit.current.saving) {
      notify("请先等待 PDF 阅读器中的批注保存完成，再写入这条评论。", true);
      return;
    }
    commentLocked.current = true;
    setCommentSaving(true);
    try {
      if (!(await verifyProposalVersion())) return;
      if (commentText.length > 10000) {
        notify("PDF 评论最多 10000 字，请精简后保存。", true);
        return;
      }
      const result = await postJson<{ annotation: ResearchAnnotation }>(
        "/annotations",
        {
          paperId: paper.id,
          page: commentPage,
          text: draftProposal
            ? draftProposal.quote
            : (commentSelection?.text ?? ""),
          quote: draftProposal
            ? draftProposal.quote
            : (commentSelection?.quote ?? ""),
          comment: commentText.trim(),
          kind: "comment",
          color: highlightColor.color,
          rects:
            !draftProposal && commentSelection?.page === commentPage
              ? commentSelection.rects
              : undefined,
          contentRevision: draftProposal
            ? run?.contentRevision
            : commentSelection?.contentRevision,
          pdfEtag: detail?.paper.pdfEtag ?? paper.pdfEtag,
          actionId: commentActionId.current,
        },
      );
      setCommentOpen(false);
      setReaderGeneration((generation) => generation + 1);
      setSelectionToolsVisible(false);
      await loadDetail();
      await onRefresh();
      notify(
        result.annotation.pdfSaved
          ? "评论已保存。"
          : "评论已记录，请检查 PDF 保存状态。",
        !result.annotation.pdfSaved,
      );
    } catch (error) {
      notify(errorText(error), true);
    } finally {
      commentLocked.current = false;
      setCommentSaving(false);
    }
  }
  const openRunReview = useCallback(
    async (entry: ResearchRun) => {
      if (reviewLocked.current) return;
      if (nativeEdit.current.dirty || nativeEdit.current.saving) {
        notify("请先保存 PDF 中的批注，再开始复习。", true);
        return;
      }
      reviewLocked.current = true;
      setReviewSaving(true);
      try {
        const deck = await reviewFromRun(entry, paper);
        onOpenReview(deck.id, paper.id);
      } catch (error) {
        notify(errorText(error), true);
      } finally {
        reviewLocked.current = false;
        setReviewSaving(false);
      }
    },
    [paper, onOpenReview, notify],
  );

  useEffect(() => {
    if (!jump?.learning) return;
    const request = jump.learning;
    queueMicrotask(() => setLearningComposer(request));
  }, [jump?.nonce, jump?.learning]);

  useEffect(() => {
    if (
      !pendingLearning ||
      !run ||
      run.id !== pendingLearning.runId ||
      isRunActive(run) ||
      handledLearning.current.has(run.id)
    )
      return;
    if (run.status !== "completed" || !run.answer) return;
    const entry = run;
    let disposed = false;
    queueMicrotask(() => {
      if (disposed) return;
      if (handledLearning.current.has(entry.id)) return;
      handledLearning.current.add(entry.id);
      if (pendingLearning.task === "notes")
        notify("笔记已生成，点击“编辑为笔记”核对并保存。");
      else if (pendingLearning.task === "quiz")
        notify("题目已就绪，点击“开始逐题复习”。");
    });
    return () => {
      disposed = true;
    };
  }, [pendingLearning, run, notify]);

  async function openNoteReview(note: ResearchNote) {
    if (nativeEdit.current.dirty || nativeEdit.current.saving) {
      notify("请先保存 PDF 中的批注，再开始复习。", true);
      return;
    }
    if (!parseReviewMarkdown(note.body).length) {
      setLearningComposer({
        task: "quiz",
        source: { kind: "note", noteId: note.id, version: note.version },
        count: 5,
      });
      return;
    }
    if (reviewLocked.current) return;
    reviewLocked.current = true;
    setReviewSaving(true);
    try {
      const deck = await reviewFromNote(note);
      onOpenReview(deck.id, paper.id);
    } catch (error) {
      notify(errorText(error), true);
    } finally {
      reviewLocked.current = false;
      setReviewSaving(false);
    }
  }

  function reuseSources(entry: ResearchRun) {
    const currentRevision =
      detail?.paper.contentRevision ?? paper.contentRevision;
    if (
      !entry.contentRevision ||
      entry.contentRevision !== currentRevision ||
      (entry.selection?.contentRevision &&
        entry.selection.contentRevision !== currentRevision)
    ) {
      notify("原文版本已变化，请重新选择提问范围。", true);
      return;
    }
    const ids = entry.sourcePaperIds ?? [paper.id];
    if (ids.some((id) => !papers.some((item) => item.id === id))) {
      notify("部分资料已不在文献库，请先恢复。", true);
      return;
    }
    setSourcePaperIds(ids);
    setSelection(entry.selection ?? null);
    setAnswerStyle(entry.answerStyle ?? "grounded");
    const conceptsCurrent = (entry.referenceConcepts ?? []).every((ref) =>
      knowledge.some(
        (item) => item.id === ref.id && item.version === ref.version,
      ),
    );
    setReferenceConceptIds(
      conceptsCurrent ? entry.referenceConceptIds : undefined,
    );
    if (!conceptsCurrent) notify("参考概念已更新，将重新匹配当前条目。");
    questionInput.current?.focus();
  }
  function focusQuestion() {
    setTab("ai");
    if (!active) {
      const draft = questionDraft.capture();
      const previous = findPassageDiscussion(
        history,
        detail?.paper ?? paper,
        draft.selection,
        draft.answerStyle ?? "discussion",
        draft.referenceConceptIds,
      );
      if (draft.selection) setRun(previous);
      if (previous && draft.referenceConceptIds === undefined)
        setReferenceConceptIds(previous.referenceConceptIds ?? []);
    }
    setTimeout(() => questionInput.current?.focus(), 0);
  }
  function askAnnotation(annotation: ResearchAnnotation) {
    const quote =
      annotation.quote.trim() ||
      (annotation.kind === "highlight" ? annotation.text.trim() : "");
    setSelection(
      quote
        ? {
            page: annotation.page,
            text: quote,
            quote,
            rects: annotation.rects,
            contentRevision:
              annotation.contentRevision ??
              detail?.paper.contentRevision ??
              paper.contentRevision,
            pdfEtag: detail?.paper.pdfEtag ?? paper.pdfEtag,
          }
        : null,
    );
    setSelectionToolsVisible(false);
    if (!quote && !question.trim())
      setQuestion(
        `请结合第 ${annotation.page} 页，讨论我的批注：${annotation.comment || annotation.text}`,
      );
    focusQuestion();
  }
  return (
    <div className={styles.readerPage}>
      <ResizableReader className={styles.readingWorkspace}>
        <section className={styles.pdfPane}>
          <div
            ref={readerRoot}
            className={styles.pdfMount}
            onPointerUpCapture={(event) => {
              if (
                event.target instanceof Element &&
                event.currentTarget.contains(event.target) &&
                event.target.closest(".page")
              )
                captureSelection();
            }}
            onKeyUpCapture={(event) => {
              if (
                !(event.target instanceof Node) ||
                !event.currentTarget.contains(event.target)
              )
                return;
              if (
                (event.shiftKey &&
                  /^(Arrow|Home$|End$|Page)/.test(event.key)) ||
                ((event.ctrlKey || event.metaKey) &&
                  event.key.toLowerCase() === "a")
              )
                captureSelection();
            }}
          >
            <PdfReader
              compactToolbar
              onQuickComment={(page) => prepareComment("", page)}
              key={readerGeneration}
              onEditStateChange={onPdfEdit}
              onDocumentSaved={() => {
                void loadDetail()
                  .then(onRefresh)
                  .catch((error: unknown) => notify(errorText(error), true));
              }}
              src={src}
              title={paper.title}
              editable
              chatPrompts={false}
              positionKey={"research:" + paper.id}
              onPageChange={setCurrentPage}
              onAskSelection={({ page, quote }) => {
                setSelection({
                  page,
                  text: quote,
                  quote,
                  contentRevision:
                    detail?.paper.contentRevision ?? paper.contentRevision,
                  pdfEtag: detail?.paper.pdfEtag ?? paper.pdfEtag,
                });
                setSelectionToolsVisible(false);
                focusQuestion();
              }}
            />
          </div>
          {selection && selectionToolsVisible && (
            <ReaderSelectionBar
              selection={selection}
              saving={quickHighlight.saving || commentSaving}
              aiBusy={active}
              color={highlightColor.color}
              onColor={highlightColor.setColor}
              onAsk={focusQuestion}
              onHighlight={() => void quickHighlight.save(selection)}
              onComment={() => prepareComment("")}
              onExplain={() =>
                void start("ask", undefined, {
                  task: "explain",
                  source: { kind: "selection" },
                  detail: "brief",
                })
              }
              onExcerpt={() =>
                prepareNote(
                  "> " + selection.text + "\n\n## 我的思考\n\n",
                  paper.title.slice(0, 20) + " · 阅读摘录",
                  undefined,
                  null,
                )
              }
              onClear={() => setSelection(null)}
            />
          )}
          <HighlightUndoNotice
            notice={quickHighlight.notice}
            busy={quickHighlight.undoing || quickHighlight.saving}
            onUndo={() => void quickHighlight.undo()}
            onDismiss={quickHighlight.dismiss}
          />
          {jump?.quote && (
            <div className={styles.jumpQuote}>
              <BookOpen size={13} />
              <span>来源摘录：{jump.quote}</span>
            </div>
          )}
        </section>
        <aside
          className={styles.readerSidebar}
          data-ai-text-size={textSize.size}
        >
          <div className={styles.readerTabs}>
            <button
              className={tab === "ai" ? styles.readerTabActive : ""}
              onClick={() => setTab("ai")}
            >
              <Sparkles size={15} />
              阅读助手
            </button>
            <button
              className={tab === "notes" ? styles.readerTabActive : ""}
              onClick={() => setTab("notes")}
            >
              <NotebookPen size={15} />
              笔记<span>{detail?.notes.length ?? 0}</span>
            </button>
            <button
              className={tab === "annotations" ? styles.readerTabActive : ""}
              onClick={() => setTab("annotations")}
            >
              <Highlighter size={15} />
              批注
            </button>
            <ReaderTextSize size={textSize.size} onChange={textSize.change} />
          </div>
          {tab === "ai" && (
            <>
              <div className={styles.aiScroll} ref={assistantScroll}>
                <ReadingControls
                  paper={paper}
                  papers={papers}
                  selectedIds={activeSourceIds}
                  onSelection={setSourcePaperIds}
                  active={active}
                  empty={!run}
                  textLength={
                    detail?.pages.reduce(
                      (sum, page) => sum + page.text.length,
                      0,
                    ) ?? 0
                  }
                  answerStyle={answerStyle}
                  selection={selection}
                  onRun={(mode, prompt) => void start(mode, prompt)}
                />
                {run && (
                  <>
                    <ReaderConversation
                      run={run}
                      history={history}
                      active={active}
                      onOpen={setRun}
                    />
                    <ReaderAnswer
                      run={run}
                      paper={detail?.paper ?? paper}
                      papers={papers}
                      currentRevision={
                        detail?.paper.contentRevision ?? paper.contentRevision
                      }
                      active={active}
                      permissionPending={permissionPending}
                      connectionWarning={connectionWarning}
                      reviewSaving={reviewSaving}
                      onPrepare={prepareProposal}
                      onPermission={permission}
                      onReview={openRunReview}
                      onNote={prepareNote}
                      onComment={(text) =>
                        prepareComment(
                          text,
                          run.selection?.page,
                          run.selection ?? null,
                        )
                      }
                      onExplain={(request, source) =>
                        start("ask", undefined, request, source)
                      }
                      onOpenSource={onOpenSource}
                      onUseSources={() => reuseSources(run)}
                    />
                  </>
                )}
                <RecentDiscussions
                  runs={history}
                  paperId={paper.id}
                  currentRunId={run?.id}
                  active={active}
                  onOpen={(entry) => {
                    if (!active) setRun(entry);
                  }}
                />
              </div>
              <ReaderQuestionComposer
                selection={selection}
                question={question}
                inputRef={questionInput}
                active={active}
                sources={activeSourceIds.length}
                status={questionDraft.status}
                available={questionDraft.available}
                controls={
                  <DiscussionControls
                    answerStyle={answerStyle}
                    knowledge={knowledge}
                    query={[
                      selection?.text ?? selection?.quote ?? "",
                      question,
                    ].join("\n")}
                    referenceConceptIds={referenceConceptIds}
                    onStyle={setAnswerStyle}
                    onConcepts={setReferenceConceptIds}
                  />
                }
                onQuestion={setQuestion}
                onFocus={() => {
                  const live = window.getSelection();
                  if (
                    !questionDraft.capture().selection &&
                    live?.anchorNode &&
                    readerRoot.current?.contains(live.anchorNode)
                  )
                    captureSelection();
                }}
                onClearSelection={() => setSelection(null)}
                onSend={() => void start("ask")}
                onStop={() => void cancel()}
              />
            </>
          )}
          {tab === "notes" && (
            <ReaderNotes
              notes={detail?.notes ?? []}
              active={active || reviewSaving}
              onCreate={() =>
                prepareNote(
                  "",
                  paper.title.slice(0, 20) + " · 我的思考",
                  undefined,
                  null,
                )
              }
              onEdit={(note) => {
                setDraftProposal(null);
                setNoteDraft(note);
              }}
              onOrganize={() =>
                setLearningComposer({
                  task: "notes",
                  source: selection ? { kind: "selection" } : { kind: "paper" },
                })
              }
              onQuiz={() =>
                setLearningComposer({
                  task: "quiz",
                  source: selection ? { kind: "selection" } : { kind: "paper" },
                  count: 5,
                })
              }
              onReview={(note) => void openNoteReview(note)}
              onOpenSource={onOpenSource}
            />
          )}
          {tab === "annotations" && (
            <ReaderAnnotations
              detail={detail}
              paper={paper}
              onAdd={() => prepareComment("")}
              currentPage={currentPage}
              onAsk={askAnnotation}
              onOpenSource={onOpenSource}
              notify={notify}
              beforeWrite={() => {
                if (nativeEdit.current.dirty || nativeEdit.current.saving) {
                  notify("请先保存阅读器中尚未提交的批注。", true);
                  return false;
                }
                return true;
              }}
              onSaved={async () => {
                setReaderGeneration((generation) => generation + 1);
                setSelection(null);
                await loadDetail();
                await onRefresh();
              }}
            />
          )}
        </aside>
      </ResizableReader>
      {noteDraft && (
        <NoteEditor
          paper={paper}
          draft={noteDraft}
          onClose={() => setNoteDraft(null)}
          beforeSave={verifyProposalVersion}
          onSaved={async () => {
            await loadDetail();
            await onRefresh();
          }}
          onOpenSource={onOpenSource}
          notify={notify}
        />
      )}
      {learningComposer && (
        <LearningComposer
          paper={paper}
          detail={detail}
          selection={selection}
          initial={learningComposer}
          onClose={() => setLearningComposer(null)}
          onGenerate={(request) => start("ask", undefined, request)}
        />
      )}
      {commentOpen && (
        <ReaderCommentDialog
          pageCount={paper.pageCount}
          page={commentPage}
          text={commentText}
          quote={draftProposal ? draftProposal.quote : commentSelection?.quote}
          proposal={!!draftProposal}
          saving={commentSaving}
          onPage={setCommentPage}
          onText={setCommentText}
          onClose={() => setCommentOpen(false)}
          onSave={() => void saveComment()}
        />
      )}
    </div>
  );
}

"use client";

import { StudyMarkdown } from "./study/StudyMarkdown";
import { studyLabel } from "./study/frameworks";
import type {
  ResearchPaper,
  ResearchRun,
  ResearchSettings,
  SearchResult,
  SourceRef,
} from "@/lib/research/types";
import {
  Activity,
  ArrowUpRight,
  BookMarked,
  BookOpen,
  Check,
  ChevronRight,
  Clock3,
  Download,
  FolderOpen,
  GraduationCap,
  LoaderCircle,
  RefreshCw,
  Search,
  Settings,
  ShieldCheck,
  Sparkles,
} from "lucide-react";
import { useEffect, useState } from "react";
import {
  displayDate,
  errorText,
  isRunActive,
  patchJson,
  researchApi,
  runLabels,
} from "./api";
import { EmptyState, Loading, Modal } from "./ResearchUi";
import styles from "./styles";
import { ResearchPlanner } from "./planner/ResearchPlanner";

interface Health {
  ok?: boolean;
  available?: boolean;
  configured?: boolean;
  model?: string;
  provider?: string;
  active_runs?: number;
}
export function SearchView({
  query,
  onQuery,
  onOpenSource,
}: {
  query: string;
  onQuery(value: string): void;
  onOpenSource(source: SourceRef): void;
}) {
  const [scope, setScope] = useState("personal");
  const [results, setResults] = useState<SearchResult[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  useEffect(() => {
    if (!query.trim()) {
      return;
    }
    const controller = new AbortController();
    const timer = setTimeout(() => {
      setLoading(true);
      setError("");
      void researchApi<{ results: SearchResult[] }>(
        "/search?q=" + encodeURIComponent(query) + "&scope=" + scope,
        { signal: controller.signal },
      )
        .then((result) => setResults(result.results))
        .catch((failure: unknown) => {
          if (!controller.signal.aborted) setError(errorText(failure));
        })
        .finally(() => {
          if (!controller.signal.aborted) setLoading(false);
        });
    }, 250);
    return () => {
      clearTimeout(timer);
      controller.abort();
    };
  }, [query, scope]);
  const labels: Record<SearchResult["type"], string> = {
    paper: "论文",
    page: "原文片段",
    note: "研究笔记",
    annotation: "阅读批注",
    knowledge: "教育概念",
  };
  return (
    <div className={styles.searchPage}>
      <div className={styles.pageHeading}>
        <div>
          <h1>个人研究检索</h1>
        </div>
      </div>
      <div className={styles.searchHero}>
        <Search size={23} />
        <input
          autoFocus
          value={query}
          onChange={(event) => onQuery(event.target.value)}
          placeholder="例如：形成性评价、混合研究、教师反馈…"
          aria-label="输入检索关键词"
        />
        <kbd>本机资料</kbd>
      </div>
      <div className={styles.scopeTabs}>
        {[
          ["personal", "个人研究知识库"],
          ["education", "教育概念库"],
          ["all", "所有资料"],
        ].map(([value, label]) => (
          <button
            key={value}
            className={scope === value ? styles.scopeActive : ""}
            onClick={() => setScope(value)}
          >
            {value === "education" ? (
              <GraduationCap size={15} />
            ) : (
              <BookMarked size={15} />
            )}
            {label}
          </button>
        ))}
      </div>
      {loading && <Loading label="正在检索资料…" />}
      {error && <div className={styles.inlineError}>{error}</div>}
      {!loading && query && (
        <div className={styles.resultCount}>
          找到 {results.length} 条相关资料 <span>所有结果保留原始来源</span>
        </div>
      )}
      <div className={styles.searchResults}>
        {(query.trim() ? results : []).map((result) => (
          <article key={result.id + "-" + (result.page ?? 0)}>
            <div className={styles.smallMeta}>
              <span
                className={
                  result.type === "knowledge"
                    ? styles.conceptCategory
                    : styles.paperTopic
                }
              >
                {labels[result.type]}
              </span>
              {result.page && <span>第 {result.page} 页</span>}
            </div>
            <button
              onClick={() =>
                onOpenSource(
                  result.source ?? {
                    paperId: result.paperId,
                    page: result.page,
                    quote: result.snippet,
                    title: result.title,
                  },
                )
              }
            >
              <h3>{result.title}</h3>
              <ArrowUpRight size={18} />
            </button>
            <p>{result.snippet}</p>
            <footer>
              <BookOpen size={12} />
              {result.source?.citation ||
                result.source?.title ||
                (result.type === "knowledge"
                  ? "教育学参考资料"
                  : "个人研究资料")}
            </footer>
          </article>
        ))}
      </div>
      {!query && (
        <div className={styles.searchSuggestions}>
          <div>
            {["形成性评价", "课堂教学", "研究方法", "学习动机"].map((value) => (
              <button key={value} onClick={() => onQuery(value)}>
                {value}
                <ArrowUpRight size={12} />
              </button>
            ))}
          </div>
        </div>
      )}
      {!loading && !!query && !results.length && !error && (
        <EmptyState
          title="暂未找到相关资料"
          description="换一个关键词试试，或者先上传论文、确认一条阅读笔记。"
        />
      )}
    </div>
  );
}

export function TasksSettings({
  history,
  papers,
  onRefresh,
  onOpenSource,
  notify,
}: {
  history: ResearchRun[];
  papers: ResearchPaper[];
  onRefresh(): Promise<void>;
  onOpenSource(source: SourceRef): void;
  notify(message: string, error?: boolean): void;
}) {
  const [tab, setTab] = useState("tasks");
  const [settings, setSettings] = useState<ResearchSettings | null>(null);
  const [health, setHealth] = useState<Health | null>(null);
  const [checking, setChecking] = useState(false);
  const [selected, setSelected] = useState<ResearchRun | null>(null);
  const [topic, setTopic] = useState("");
  useEffect(() => {
    void researchApi<{ settings: ResearchSettings; health: Health }>(
      "/settings",
    )
      .then((result) => {
        setSettings(result.settings);
        setHealth(result.health);
        setTopic(result.settings.defaultTopic);
      })
      .catch((error: unknown) => notify(errorText(error), true));
  }, [notify]);
  async function check() {
    setChecking(true);
    try {
      const result = await researchApi<{ health: Health }>("/health");
      setHealth(result.health);
      notify(
        result.health.ok
          ? result.health.configured
            ? "分析服务正常，模型配置已载入。"
            : "分析服务正常，请按设置页说明接入自己的模型。"
          : "分析服务尚未就绪，请检查本地启动状态。",
        !result.health.ok,
      );
      await onRefresh();
    } catch (error) {
      notify(errorText(error), true);
    } finally {
      setChecking(false);
    }
  }
  async function saveSettings() {
    try {
      const result = await patchJson<{ settings: ResearchSettings }>(
        "/settings",
        { defaultTopic: topic, version: settings?.version },
      );
      setSettings(result.settings);
      notify("工作区偏好已保存。");
    } catch (error) {
      notify(errorText(error), true);
    }
  }
  return (
    <div className={styles.standardPage}>
      <div className={styles.pageHeading}>
        <div>
          <h1>任务与设置</h1>
        </div>
        <button
          className={styles.secondaryButton}
          onClick={() => void check()}
          disabled={checking}
        >
          <RefreshCw size={15} className={checking ? styles.spin : ""} />
          检查分析服务
        </button>
      </div>
      <div className={styles.scopeTabs}>
        <button
          className={tab === "tasks" ? styles.scopeActive : ""}
          onClick={() => setTab("tasks")}
        >
          <Activity size={16} />
          分析任务<span>{history.length}</span>
        </button>
        <button
          className={tab === "settings" ? styles.scopeActive : ""}
          onClick={() => setTab("settings")}
        >
          <Settings size={16} />
          工作区设置
        </button>
        <button
          className={tab === "planner" ? styles.scopeActive : ""}
          onClick={() => setTab("planner")}
        >
          <Clock3 size={16} />
          研究待办
        </button>
      </div>
      {tab === "planner" ? (
        <ResearchPlanner
          papers={papers}
          onOpenSource={onOpenSource}
          notify={notify}
        />
      ) : tab === "tasks" ? (
        <div className={styles.taskPanel}>
          <div className={styles.panelHeading}>
            <h3>任务记录</h3>
            <span className={styles.mutedSmall}>真实执行状态与结果</span>
          </div>
          {[...history]
            .sort((a, b) => b.createdAt.localeCompare(a.createdAt))
            .map((run) => (
              <button
                className={styles.taskRow}
                key={run.id}
                onClick={() => setSelected(run)}
              >
                <span
                  className={
                    isRunActive(run)
                      ? styles.statIconIndigo
                      : run.status === "completed"
                        ? styles.statIconTeal
                        : styles.statIconAmber
                  }
                >
                  {isRunActive(run) ? (
                    <LoaderCircle size={17} className={styles.spin} />
                  ) : run.status === "completed" ? (
                    <Check size={17} />
                  ) : (
                    <Clock3 size={17} />
                  )}
                </span>
                <div>
                  <strong>
                    {studyLabel(run.question) ?? run.question.slice(0, 90)}
                  </strong>
                  <p>
                    {papers.find((paper) => paper.id === run.paperId)?.title ||
                      "研究论文"}
                  </p>
                </div>
                <span
                  className={
                    isRunActive(run) ? styles.runningTag : styles.mutedSmall
                  }
                >
                  {runLabels[run.status]}
                </span>
                <small>{displayDate(run.createdAt)}</small>
                <ChevronRight size={16} />
              </button>
            ))}
          {!history.length && (
            <EmptyState
              icon={<Activity size={24} />}
              title="暂无分析任务"
              description=""
            />
          )}
        </div>
      ) : (
        <div className={styles.settingsGrid}>
          <section className={styles.settingsCard}>
            <div className={styles.panelHeading}>
              <h3>
                <Sparkles size={17} />
                分析服务
              </h3>
              <span
                className={health?.ok ? styles.confirmedTag : styles.draftTag}
              >
                {health?.ok ? "服务就绪" : "待检查"}
              </span>
            </div>
            <div className={styles.settingsBody}>
              <dl>
                <div>
                  <dt>当前模型</dt>
                  <dd>{health?.model || settings?.model || "尚未载入"}</dd>
                </div>
                <div>
                  <dt>分析核心</dt>
                  <dd>本地标准库智能体</dd>
                </div>
                <div>
                  <dt>模型配置</dt>
                  <dd>{health?.configured ? "已配置" : "请检查本地配置"}</dd>
                </div>
              </dl>
              <div className={styles.softInfo}>
                <p>
                  接入自己的模型：在项目目录打开 <code>private/model.env</code>
                  ，填写接口根地址、模型 ID 和自己的令牌。
                </p>
                <p>
                  对应字段为 <code>PAPERFLOW_LLM_BASE_URL</code>、
                  <code>PAPERFLOW_LLM_DEFAULT_MODEL</code>、
                  <code>PAPERFLOW_LLM_API_KEY</code>。保存后运行
                  <code> docker compose restart paperflow</code>，再点击检查。
                </p>
                <p>
                  <a
                    href="https://github.com/Muhaymenul/openhai#首次接入自己的-ai"
                    target="_blank"
                    rel="noreferrer"
                  >
                    查看接入说明
                  </a>
                  。论文片段在分析时发送给模型服务；资料保存在本机。
                </p>
              </div>
            </div>
          </section>
          <section className={styles.settingsCard}>
            <div className={styles.panelHeading}>
              <h3>
                <FolderOpen size={17} />
                工作区与数据
              </h3>
            </div>
            <div className={styles.settingsBody}>
              <label className={styles.formLabel}>
                默认研究主题
                <input
                  value={topic}
                  onChange={(event) => setTopic(event.target.value)}
                  placeholder="我的教育研究"
                />
              </label>
              <button
                className={styles.secondaryButton}
                onClick={() => void saveSettings()}
              >
                <Check size={14} />
                保存偏好
              </button>
              <div className={styles.dataLocation}>
                <span>本地数据位置</span>
                <code>{settings?.dataLocation || "本机工作区"}</code>
              </div>
            </div>
          </section>
          <section className={styles.settingsCard}>
            <div className={styles.panelHeading}>
              <h3>
                <ShieldCheck size={17} />
                备份与导出
              </h3>
            </div>
            <div className={styles.settingsBody}>
              <div className={styles.actionRow}>
                <a
                  href="/api/research/backup"
                  download
                  className={styles.primaryButton}
                >
                  <Download size={15} />
                  下载工作区备份
                </a>
                <a
                  href="/api/research/export?format=markdown"
                  download
                  className={styles.secondaryButton}
                >
                  导出 Markdown
                </a>
              </div>
            </div>
          </section>
        </div>
      )}
      {selected && (
        <Modal
          title={runLabels[selected.status]}
          subtitle={
            papers.find((paper) => paper.id === selected.paperId)?.title
          }
          onClose={() => setSelected(null)}
          wide
        >
          <div className={styles.modalBody}>
            <h3>{studyLabel(selected.question) ?? selected.question}</h3>
            <div className={styles.articleBody}>
              <StudyMarkdown
                content={
                  selected.answer || selected.error || "任务还没有生成结果。"
                }
              />
            </div>
            <button
              className={styles.secondaryButton}
              onClick={() => {
                onOpenSource({ paperId: selected.paperId });
                setSelected(null);
              }}
            >
              <BookOpen size={14} />
              返回论文
            </button>
          </div>
        </Modal>
      )}
    </div>
  );
}

"use client";

import type { SourceRef } from "@/lib/research/types";
import {
  ArrowUpRight,
  BookOpen,
  Check,
  CircleAlert,
  LoaderCircle,
  X,
} from "lucide-react";
import { useEffect, useRef, type ReactNode } from "react";
import styles from "./styles";

export function EmptyState({
  icon,
  title,
  description,
  action,
}: {
  icon?: ReactNode;
  title: string;
  description: string;
  action?: ReactNode;
}) {
  return (
    <div className={styles.empty}>
      <div className={styles.emptyIcon}>{icon ?? <BookOpen size={24} />}</div>
      <h3>{title}</h3>
      {description && <p>{description}</p>}
      {action}
    </div>
  );
}

export function Loading({ label = "正在载入工作区…" }: { label?: string }) {
  return (
    <div className={styles.loading}>
      <LoaderCircle size={21} className={styles.spin} />
      <span>{label}</span>
    </div>
  );
}

export function SourceChips({
  sources,
  onOpen,
}: {
  sources: SourceRef[];
  onOpen(source: SourceRef): void;
}) {
  return (
    <div className={styles.sourceChips}>
      {sources.map((source, index) => (
        <button
          key={source.anchorId ?? source.url ?? String(index)}
          className={styles.sourceChip}
          onClick={() => onOpen(source)}
          title={
            source.quote ?? source.title ?? source.citation ?? "查看资料来源"
          }
        >
          <BookOpen size={12} />
          {source.page
            ? "第 " + source.page + " 页"
            : source.title || source.citation || "资料来源"}
          <ArrowUpRight size={11} />
        </button>
      ))}
    </div>
  );
}

export function Modal({
  title,
  subtitle,
  children,
  onClose,
  wide = false,
}: {
  title: string;
  subtitle?: string;
  children: ReactNode;
  onClose(): void;
  wide?: boolean;
}) {
  const dialog = useRef<HTMLDivElement>(null);
  const closeRef = useRef(onClose);
  useEffect(() => {
    closeRef.current = onClose;
  }, [onClose]);
  useEffect(() => {
    const previous = document.activeElement;
    dialog.current?.focus();
    const onKey = (event: KeyboardEvent) => {
      if (event.key === "Escape") closeRef.current();
      if (event.key !== "Tab") return;
      const elements = dialog.current?.querySelectorAll<HTMLElement>(
        'button:not([disabled]), input, textarea, select, a[href], [tabindex="0"]',
      );
      if (!elements?.length) return;
      const first = elements[0],
        last = elements[elements.length - 1];
      if (event.shiftKey && document.activeElement === first) {
        event.preventDefault();
        last.focus();
      }
      if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault();
        first.focus();
      }
    };
    document.addEventListener("keydown", onKey);
    return () => {
      document.removeEventListener("keydown", onKey);
      if (previous instanceof HTMLElement) previous.focus();
    };
  }, []);
  return (
    <div
      className={styles.modalBackdrop}
      onMouseDown={(event) => {
        if (event.target === event.currentTarget) onClose();
      }}
    >
      <div
        className={wide ? styles.modalWide : styles.modal}
        ref={dialog}
        tabIndex={-1}
        role="dialog"
        aria-modal="true"
        aria-label={title}
      >
        <div className={styles.modalHeader}>
          <div>
            <h2>{title}</h2>
            {subtitle && <p>{subtitle}</p>}
          </div>
          <button
            className={styles.iconButton}
            onClick={onClose}
            aria-label="关闭对话框"
          >
            <X size={19} />
          </button>
        </div>
        {children}
      </div>
    </div>
  );
}

export function Toast({
  message,
  error,
  onClose,
}: {
  message: string;
  error: boolean;
  onClose(): void;
}) {
  useEffect(() => {
    const timer = setTimeout(onClose, error ? 9000 : 4500);
    return () => clearTimeout(timer);
  }, [message, error, onClose]);
  return (
    <div
      className={error ? styles.toastError : styles.toast}
      role={error ? "alert" : "status"}
    >
      {error ? <CircleAlert size={18} /> : <Check size={18} />}
      <span>{message}</span>
      <button onClick={onClose} aria-label="关闭提示">
        <X size={15} />
      </button>
    </div>
  );
}

"use client";

import type { ResearchNote, SourceRef } from "@/lib/research/types";
import {
  ArrowRight,
  ArrowUpRight,
  CircleAlert,
  GraduationCap,
  Library,
  Menu,
  Network,
  NotebookPen,
  Plus,
  RefreshCw,
  Search,
  Settings,
  CircleHelp,
  ListChecks,
} from "lucide-react";
import { useCallback, useEffect, useRef, useState } from "react";
import Image from "next/image";
import {
  errorText,
  isRunActive,
  patchJson,
  researchApi,
  WORKSPACE_CHANGE_KEY,
  type WorkspaceSnapshot,
} from "./api";
import { ResearchGraph } from "./ResearchGraph";
import { ResearchKnowledge } from "./ResearchKnowledge";
import { ResearchNotes } from "./ResearchNotes";
import { ResearchReader, type ReaderJump } from "./ResearchReader";
import { EmptyState, Loading, Toast } from "./ResearchUi";
import styles from "./styles";

import { LibraryView, UploadModal } from "./ResearchLibrary";
import { SearchView, TasksSettings } from "./ResearchTools";
import { ResearchHelp } from "./help/ResearchHelp";
import { PrintPaperHeading } from "./reader-layout/PrintPaperHeading";
import { ReaderTitle } from "./reader-layout/ReaderTitle";
import { ResearchHome } from "./home/ResearchHome";
import { ReviewWorkspace } from "./review/ReviewWorkspace";
import { parseReviewMarkdown, reviewFromNote } from "./learning/review-actions";

type View =
  | "home"
  | "library"
  | "reader"
  | "notes"
  | "review"
  | "education"
  | "search"
  | "graph"
  | "tasks"
  | "help";
const NAV = [
  { id: "library", label: "文献库", icon: Library },
  { id: "notes", label: "研究笔记", icon: NotebookPen },
  { id: "review", label: "学习复习", icon: ListChecks },
  { id: "education", label: "教育概念库", icon: GraduationCap },
  { id: "search", label: "个人检索", icon: Search },
  { id: "graph", label: "知识图谱", icon: Network },
] as const;
const EMPTY: WorkspaceSnapshot = {
  papers: [],
  notes: [],
  knowledge: [],
  graph: { nodes: [], edges: [], version: 1 },
  history: [],
};

export function ResearchWorkspace() {
  const [data, setData] = useState<WorkspaceSnapshot | null>(null);
  const [loadError, setLoadError] = useState("");
  const [view, setView] = useState<View>("home");
  const [paperId, setPaperId] = useState("");
  const [jump, setJump] = useState<ReaderJump | null>(null);
  const [noteTarget, setNoteTarget] = useState<{
    id: string;
    nonce: number;
  } | null>(null);
  const [reviewTarget, setReviewTarget] = useState<{
    deckId?: string;
    paperId?: string;
    nonce: number;
  }>({ nonce: 0 });
  const navigationNonce = useRef(0);
  const [topic, setTopic] = useState("全部文献");
  const [search, setSearch] = useState("");
  const [uploadOpen, setUploadOpen] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);
  const [toast, setToast] = useState<{
    message: string;
    error: boolean;
  } | null>(null);
  const searchInput = useRef<HTMLInputElement>(null);
  const mainRegion = useRef<HTMLElement>(null);
  const refreshEpoch = useRef(0);
  useEffect(() => {
    mainRegion.current?.scrollTo({ top: 0 });
  }, [view, paperId]);
  const snapshot = data ?? EMPTY;
  const activePaper = snapshot.papers.find((paper) => paper.id === paperId);
  const notify = useCallback(
    (message: string, error = false) => setToast({ message, error }),
    [],
  );
  const closeToast = useCallback(() => setToast(null), []);
  const refresh = useCallback(async () => {
    const epoch = ++refreshEpoch.current;
    try {
      const result = await researchApi<WorkspaceSnapshot>();
      if (epoch !== refreshEpoch.current) return;
      setData({ ...EMPTY, ...result });
      setLoadError("");
    } catch (error) {
      if (epoch === refreshEpoch.current) throw error;
    }
  }, []);
  useEffect(() => {
    const epochState = refreshEpoch;
    queueMicrotask(() => {
      void refresh().catch((error: unknown) => setLoadError(errorText(error)));
    });
    const sync = () => {
      if (document.visibilityState === "visible")
        void refresh().catch(() => undefined);
    };
    const onStorage = (event: StorageEvent) => {
      if (event.key === WORKSPACE_CHANGE_KEY)
        void refresh().catch(() => undefined);
    };
    window.addEventListener("focus", sync);
    document.addEventListener("visibilitychange", sync);
    window.addEventListener("storage", onStorage);
    return () => {
      epochState.current++;
      window.removeEventListener("focus", sync);
      document.removeEventListener("visibilitychange", sync);
      window.removeEventListener("storage", onStorage);
    };
  }, [refresh]);
  useEffect(() => {
    const hydrateLocation = () => {
      const params = new URLSearchParams(window.location.search);
      const initialView = params.get("view");
      if (
        initialView &&
        [
          "home",
          "library",
          "reader",
          "notes",
          "review",
          "education",
          "search",
          "graph",
          "tasks",
          "help",
        ].includes(initialView)
      )
        setView(initialView as View);
      if (initialView === "notes") {
        const initialNoteId = params.get("noteId");
        setNoteTarget(
          initialNoteId
            ? { id: initialNoteId, nonce: ++navigationNonce.current }
            : null,
        );
      }
      if (initialView === "review") {
        setReviewTarget({
          deckId: params.get("deckId") || undefined,
          paperId: params.get("reviewPaperId") || undefined,
          nonce: ++navigationNonce.current,
        });
      }
      const initialPaper = params.get("paperId") ?? params.get("paper");
      if (initialPaper) {
        setPaperId(initialPaper);
        setView("reader");
        const page = Number(params.get("page"));
        if (Number.isInteger(page) && page > 0)
          setJump({ page, nonce: Date.now() });
      }
      if (params.get("q")) setSearch(params.get("q") ?? "");
    };
    queueMicrotask(hydrateLocation);
    window.addEventListener("popstate", hydrateLocation);
    const onKey = (event: KeyboardEvent) => {
      if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === "k") {
        if (
          event.defaultPrevented ||
          !searchInput.current ||
          document.querySelector('[role="dialog"][aria-modal="true"]')
        )
          return;
        event.preventDefault();
        searchInput.current?.focus();
      }
    };
    window.addEventListener("keydown", onKey);
    return () => {
      window.removeEventListener("keydown", onKey);
      window.removeEventListener("popstate", hydrateLocation);
    };
  }, []);
  const navigate = useCallback((next: View) => {
    if (next === "notes") setNoteTarget(null);
    if (next === "review")
      setReviewTarget({ nonce: ++navigationNonce.current });
    setView(next);
    setMenuOpen(false);
    window.history.replaceState(null, "", "/workspace?view=" + next);
  }, []);
  const openSource = useCallback(
    (source: SourceRef) => {
      if (source.url && !source.paperId) {
        try {
          const url = new URL(source.url);
          if (["http:", "https:"].includes(url.protocol)) {
            window.open(url.href, "_blank", "noopener,noreferrer");
            return;
          }
        } catch {
          /* Display unavailable sources without navigating. */
        }
      }
      if (!source.paperId) {
        notify(source.title || source.citation || "这条来源尚未关联本机论文。");
        return;
      }
      const sourcePaper = snapshot.papers.find(
        (paper) => paper.id === source.paperId,
      );
      if (!sourcePaper) {
        notify("文献不在文献库中，请到回收站检查并恢复。", true);
        return;
      }
      setPaperId(source.paperId);
      setJump({ page: source.page, quote: source.quote, nonce: Date.now() });
      setView("reader");
      setMenuOpen(false);
      window.history.replaceState(
        null,
        "",
        "/workspace?paperId=" +
          encodeURIComponent(source.paperId) +
          (source.page ? "&page=" + source.page : ""),
      );
      if (
        sourcePaper &&
        (sourcePaper.readStatus === "unread" ||
          (source.page !== undefined &&
            sourcePaper.lastReadPage !== source.page))
      ) {
        void patchJson("/papers/" + sourcePaper.id, {
          version: sourcePaper.version,
          readStatus:
            sourcePaper.readStatus === "unread"
              ? "reading"
              : sourcePaper.readStatus,
          ...(source.page ? { lastReadPage: source.page } : {}),
        })
          .then(refresh)
          .catch(() => undefined);
      }
    },
    [notify, refresh, snapshot.papers],
  );
  const openNote = useCallback(
    (note: ResearchNote) => {
      if (
        !snapshot.notes.some((entry) => entry.id === note.id) ||
        !snapshot.papers.some((paper) => paper.id === note.paperId)
      ) {
        notify("这份笔记或关联文献已不可用，请刷新或检查回收站。", true);
        return;
      }
      setNoteTarget({ id: note.id, nonce: ++navigationNonce.current });
      setView("notes");
      setMenuOpen(false);
      window.history.replaceState(
        null,
        "",
        "/workspace?view=notes&noteId=" + encodeURIComponent(note.id),
      );
    },
    [notify, snapshot.notes, snapshot.papers],
  );
  const openReview = useCallback(
    (deckId: string, reviewPaperId: string) => {
      if (!snapshot.papers.some((paper) => paper.id === reviewPaperId)) {
        notify("关联文献已不可用，请在回收站恢复后继续复习。", true);
        return;
      }
      setReviewTarget({
        deckId,
        paperId: reviewPaperId,
        nonce: ++navigationNonce.current,
      });
      setView("review");
      setMenuOpen(false);
      const params = new URLSearchParams({
        view: "review",
        deckId,
        reviewPaperId,
      });
      window.history.replaceState(null, "", "/workspace?" + params.toString());
    },
    [notify, snapshot.papers],
  );
  const reviewNote = useCallback(
    async (note: ResearchNote) => {
      const paper = snapshot.papers.find((entry) => entry.id === note.paperId);
      if (!paper) {
        notify("关联文献已不可用，请在回收站恢复后继续复习。", true);
        return;
      }
      try {
        if (parseReviewMarkdown(note.body).length) {
          const deck = await reviewFromNote(note);
          openReview(deck.id, deck.paperId);
        } else {
          openSource({ paperId: paper.id, page: paper.lastReadPage });
          setJump({
            nonce: ++navigationNonce.current,
            learning: {
              task: "quiz",
              source: { kind: "note", noteId: note.id, version: note.version },
            },
          });
        }
      } catch (error) {
        notify(errorText(error), true);
      }
    },
    [notify, openReview, openSource, snapshot.papers],
  );
  const topics = [
    ...new Set(snapshot.papers.map((paper) => paper.topic).filter(Boolean)),
  ];
  const runningCount = snapshot.history.filter(isRunActive).length;
  const title =
    view === "help"
      ? "使用说明"
      : view === "reader"
        ? "阅读工作台"
        : (NAV.find((entry) => entry.id === view)?.label ?? "任务与设置");

  const overlays = (
    <>
      {uploadOpen && (
        <UploadModal
          onClose={() => setUploadOpen(false)}
          onRefresh={refresh}
          notify={notify}
        />
      )}
      {toast && (
        <Toast
          message={toast.message}
          error={toast.error}
          onClose={closeToast}
        />
      )}
    </>
  );
  if (view === "home") {
    return (
      <div
        className={styles.workspaceRoot + " " + styles.coverRoot}
        data-research-workspace
      >
        {loadError && (
          <div className={styles.homeConnectionError} role="alert">
            <span>{loadError}</span>
            <button
              type="button"
              onClick={() =>
                void refresh().catch((error: unknown) =>
                  setLoadError(errorText(error)),
                )
              }
            >
              重新连接
            </button>
          </div>
        )}
        <ResearchHome
          papers={snapshot.papers}
          notes={snapshot.notes}
          graph={snapshot.graph}
          onNavigate={navigate}
          onOpen={(paper) =>
            openSource({ paperId: paper.id, page: paper.lastReadPage })
          }
          onUpload={() => setUploadOpen(true)}
          onOpenNote={openNote}
          onOpenGraph={() => navigate("graph")}
        />
        {overlays}
      </div>
    );
  }

  return (
    <div
      className={styles.workspaceRoot}
      data-research-workspace
      data-reading={view === "reader" && activePaper ? "true" : undefined}
    >
      <PrintPaperHeading paper={view === "reader" ? activePaper : undefined} />
      <aside className={menuOpen ? styles.sidebarOpen : styles.sidebar}>
        <button
          className={styles.brand}
          onClick={() => navigate("home")}
          title="返回首页"
        >
          <span className={styles.brandMark}>
            <Image src="/logo.png" width={44} height={44} sizes="44px" alt="" />
          </span>
          <span>
            <strong>教研阅记</strong>
          </span>
        </button>

        <nav className={styles.navigation} aria-label="主要导航">
          {NAV.map((entry) => (
            <button
              key={entry.id}
              className={
                view === entry.id ||
                (view === "reader" && entry.id === "library")
                  ? styles.navActive
                  : styles.navItem
              }
              aria-current={
                view === entry.id ||
                (view === "reader" && entry.id === "library")
                  ? "page"
                  : undefined
              }
              onClick={() => navigate(entry.id)}
            >
              <entry.icon size={18} />
              <span>{entry.label}</span>
              {entry.id === "library" && (
                <small>{snapshot.papers.length}</small>
              )}
              {entry.id === "notes" && snapshot.notes.length > 0 && (
                <small>{snapshot.notes.length}</small>
              )}
            </button>
          ))}
        </nav>
        <div className={styles.topicHeading}>
          <span>我的研究主题</span>
          <button
            className={styles.iconButton}
            onClick={() => setUploadOpen(true)}
            title="导入新主题的论文"
          >
            <Plus size={14} />
          </button>
        </div>
        <div className={styles.topicList}>
          {topics.slice(0, 7).map((label, index) => (
            <button
              key={label}
              onClick={() => {
                setTopic(label);
                navigate("library");
              }}
              className={
                view === "library" && topic === label ? styles.topicActive : ""
              }
            >
              <i
                className={index % 2 ? styles.topicTeal : styles.topicIndigo}
              />
              <span>{label}</span>
              <small>
                {
                  snapshot.papers.filter((paper) => paper.topic === label)
                    .length
                }
              </small>
            </button>
          ))}
        </div>
        <div className={styles.sidebarSpacer} />
        <button
          className={view === "help" ? styles.navActive : styles.navItem}
          onClick={() => navigate("help")}
        >
          <CircleHelp size={17} />
          <span>使用说明</span>
        </button>

        <button
          className={view === "tasks" ? styles.navActive : styles.navItem}
          onClick={() => navigate("tasks")}
        >
          <Settings size={17} />
          <span>任务与设置</span>
          {runningCount > 0 && <small>{runningCount}</small>}
        </button>
      </aside>
      {menuOpen && (
        <button
          className={styles.menuScrim}
          aria-label="收起导航"
          onClick={() => setMenuOpen(false)}
        />
      )}
      <div className={styles.mainColumn}>
        <header className={styles.topbar}>
          <div className={styles.topbarTitle}>
            <button
              className={styles.mobileMenu}
              onClick={() => setMenuOpen(!menuOpen)}
              aria-label="打开导航"
              aria-expanded={menuOpen}
            >
              <Menu size={21} />
            </button>
            {view === "reader" && activePaper ? (
              <ReaderTitle
                key={activePaper.id}
                paper={activePaper}
                onBack={() => navigate("library")}
              />
            ) : (
              <strong>{title}</strong>
            )}
          </div>
          <form
            className={styles.globalSearch}
            onSubmit={(event) => {
              event.preventDefault();
              navigate("search");
            }}
          >
            {view === "reader" && activePaper ? (
              <button
                type="button"
                className={styles.searchTrigger}
                aria-label="打开研究资料搜索"
                onClick={() => searchInput.current?.focus()}
              >
                <Search size={15} />
              </button>
            ) : (
              <Search size={16} />
            )}
            <input
              ref={searchInput}
              aria-label="搜索研究资料"
              placeholder="搜索论文、笔记、概念…"
              value={search}
              onChange={(event) => setSearch(event.target.value)}
              maxLength={400}
            />
            <kbd>Ctrl K</kbd>
          </form>
          <div className={styles.topbarEnd}>
            {view === "reader" && activePaper && (
              <a
                className={styles.readerPdfLink}
                href={"/api/research/papers/" + activePaper.id + "/pdf"}
                download={activePaper.filename}
                aria-label="打开 PDF"
                title="打开 PDF"
              >
                <ArrowUpRight size={15} />
                <span>PDF</span>
              </a>
            )}
            <button
              className={styles.iconButton}
              onClick={() => navigate("help")}
              aria-label="打开使用说明"
              title="使用说明"
            >
              <CircleHelp size={18} />
            </button>
            <span className={styles.researchBadge}>
              <span />
              本机单人
            </span>
            <button
              className={styles.profileButton}
              onClick={() => navigate("tasks")}
              aria-label="打开任务与设置"
            >
              研
            </button>
          </div>
        </header>
        <main
          ref={mainRegion}
          className={
            view === "reader" ? styles.mainReading : styles.mainContent
          }
          onClickCapture={(event) => {
            if (!(event.target instanceof Element)) return;
            const anchor = event.target.closest("a");
            if (
              !anchor ||
              event.metaKey ||
              event.ctrlKey ||
              event.shiftKey ||
              event.altKey
            )
              return;
            const url = new URL(anchor.href, window.location.origin);
            if (
              url.origin !== window.location.origin ||
              url.pathname !== "/workspace"
            )
              return;
            const targetPaper =
              url.searchParams.get("paperId") ?? url.searchParams.get("paper");
            if (!targetPaper) return;
            event.preventDefault();
            const page = Number(url.searchParams.get("page"));
            openSource({
              paperId: targetPaper,
              page: Number.isInteger(page) && page > 0 ? page : undefined,
            });
          }}
        >
          {!data && !loadError && <Loading />}
          {loadError && (
            <div className={styles.loadError}>
              <EmptyState
                icon={<CircleAlert size={25} />}
                title="工作区暂时无法载入"
                description={loadError}
                action={
                  <button
                    className={styles.primaryButton}
                    onClick={() =>
                      void refresh().catch((error: unknown) =>
                        setLoadError(errorText(error)),
                      )
                    }
                  >
                    <RefreshCw size={15} />
                    重新连接
                  </button>
                }
              />
            </div>
          )}
          {data && (
            <>
              {view === "library" && (
                <LibraryView
                  data={snapshot}
                  topic={topic}
                  setTopic={setTopic}
                  onUpload={() => setUploadOpen(true)}
                  onOpen={(paper) =>
                    openSource({
                      paperId: paper.id,
                    })
                  }
                  onRefresh={refresh}
                  onNotes={() => navigate("notes")}
                  onGraph={() => navigate("graph")}
                  notify={notify}
                />
              )}
              {view === "reader" &&
                (activePaper ? (
                  <ResearchReader
                    key={activePaper.id}
                    paper={activePaper}
                    papers={snapshot.papers}
                    knowledge={snapshot.knowledge}
                    history={snapshot.history}
                    jump={jump}
                    onRefresh={refresh}
                    onOpenSource={openSource}
                    onOpenReview={openReview}
                    notify={notify}
                  />
                ) : (
                  <EmptyState
                    title={
                      paperId ? "文献已移出文献库" : "选择一篇论文开始阅读"
                    }
                    description={paperId ? "可在文献库的回收站中恢复。" : ""}
                    action={
                      <button
                        className={styles.primaryButton}
                        onClick={() => navigate("library")}
                      >
                        前往文献库
                        <ArrowRight size={15} />
                      </button>
                    }
                  />
                ))}
              {view === "notes" && (
                <ResearchNotes
                  key={
                    noteTarget
                      ? noteTarget.id + ":" + noteTarget.nonce
                      : "notes-default"
                  }
                  initialNoteId={noteTarget?.id}
                  notes={snapshot.notes}
                  papers={snapshot.papers}
                  onRefresh={refresh}
                  onOpenSource={openSource}
                  onReview={reviewNote}
                  notify={notify}
                />
              )}
              {view === "review" && (
                <ReviewWorkspace
                  key={reviewTarget.nonce}
                  papers={snapshot.papers}
                  notes={snapshot.notes}
                  initialDeckId={reviewTarget.deckId}
                  initialPaperId={reviewTarget.paperId}
                  onOpenSource={openSource}
                  onOpenPaper={(id) => openSource({ paperId: id })}
                  onRefresh={refresh}
                  notify={notify}
                />
              )}
              {view === "education" && (
                <ResearchKnowledge
                  entries={snapshot.knowledge}
                  onRefresh={refresh}
                  onOpenSource={openSource}
                  notify={notify}
                />
              )}
              {view === "search" && (
                <SearchView
                  query={search}
                  onQuery={setSearch}
                  onOpenSource={openSource}
                />
              )}
              {view === "graph" && (
                <ResearchGraph
                  graph={snapshot.graph}
                  onRefresh={refresh}
                  onOpenSource={openSource}
                  notify={notify}
                />
              )}
              {view === "help" && (
                <ResearchHelp
                  papers={snapshot.papers}
                  onNavigate={navigate}
                  onOpenPaper={(id) => openSource({ paperId: id })}
                />
              )}
              {view === "tasks" && (
                <TasksSettings
                  history={snapshot.history}
                  papers={snapshot.papers}
                  onRefresh={refresh}
                  onOpenSource={openSource}
                  notify={notify}
                />
              )}
            </>
          )}
        </main>
      </div>
      {overlays}
    </div>
  );
}

"use client";

import type { ResearchSelection } from "@/lib/research/types";
import {
  BookmarkPlus,
  Highlighter,
  MessageSquare,
  MoreHorizontal,
  Sparkles,
  X,
} from "lucide-react";
import { useEffect, useRef } from "react";
import styles from "./selection.module.css";
import { HIGHLIGHT_COLORS } from "./useHighlightColor";

export function ReaderSelectionBar({
  selection,
  saving,
  aiBusy,
  onHighlight,
  onComment,
  onExplain,
  onAsk,
  color = "#f6c84c",
  onColor,
  onExcerpt,
  onClear,
}: {
  selection: ResearchSelection;
  saving: boolean;
  aiBusy: boolean;
  onHighlight(): void;
  onComment(): void;
  onExplain(): void;
  onAsk?(): void;
  color?: string;
  onColor?(color: string): void;
  onExcerpt(): void;
  onClear(): void;
}) {
  const more = useRef<HTMLDetailsElement>(null);
  useEffect(() => {
    const close = (event: PointerEvent) => {
      if (
        event.target instanceof Node &&
        !more.current?.contains(event.target) &&
        more.current
      )
        more.current.open = false;
    };
    document.addEventListener("pointerdown", close);
    return () => document.removeEventListener("pointerdown", close);
  }, []);
  return (
    <div className={styles.bar} aria-label="选文操作">
      <span className={styles.page}>第 {selection.page} 页选文</span>
      <div className={styles.actions}>
        <button
          onClick={onHighlight}
          disabled={saving || !selection.rects?.length}
        >
          <Highlighter size={14} />
          <span
            className={styles.colorDot}
            data-highlight-color={color}
            aria-hidden="true"
          />
          {saving ? "保存中…" : "高亮"}
        </button>
        <button onClick={onComment} disabled={saving}>
          <MessageSquare size={14} />
          写想法
        </button>
        <button onClick={onAsk ?? onExplain} disabled={saving || aiBusy}>
          <Sparkles size={14} />
          {onAsk ? "提问" : "解释"}
        </button>
        <details
          ref={more}
          className={styles.more}
          onKeyDown={(event) => {
            if (event.key === "Escape" && more.current) {
              event.preventDefault();
              more.current.open = false;
              more.current.querySelector("summary")?.focus();
            }
          }}
        >
          <summary aria-label="更多选文操作">
            <MoreHorizontal size={16} />
          </summary>
          <div>
            {onColor && (
              <fieldset className={styles.colors}>
                <legend>高亮颜色</legend>
                {HIGHLIGHT_COLORS.map((item) => (
                  <button
                    key={item.value}
                    type="button"
                    aria-label={item.name + "高亮"}
                    aria-pressed={color === item.value}
                    disabled={saving}
                    onClick={() => {
                      onColor(item.value);
                      if (more.current) more.current.open = false;
                    }}
                  >
                    <span
                      className={styles.colorDot}
                      data-highlight-color={item.value}
                      aria-hidden="true"
                    />
                    {item.name}
                  </button>
                ))}
              </fieldset>
            )}
            {onAsk && (
              <button
                onClick={() => {
                  if (more.current) more.current.open = false;
                  onExplain();
                }}
                disabled={saving || aiBusy}
              >
                <Sparkles size={14} />
                直接解释选文
              </button>
            )}
            <button
              onClick={() => {
                if (more.current) more.current.open = false;
                onExcerpt();
              }}
              disabled={saving}
            >
              <BookmarkPlus size={14} />
              保存摘录为笔记
            </button>
          </div>
        </details>
        <button onClick={onClear} disabled={saving} aria-label="取消选区">
          <X size={14} />
        </button>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import type {
  ResearchAnnotation,
  ResearchPaper,
  ResearchSelection,
} from "@/lib/research/types";
import { errorText, postJson, researchApi, type PaperDetail } from "../api";

export interface HighlightNotice {
  annotation: ResearchAnnotation;
  pdfEtag: string;
  created: boolean;
}

export function useQuickHighlight({
  paper,
  detail,
  color = "#f6c84c",
  beforeWrite,
  onSaved,
  notify,
}: {
  paper: ResearchPaper;
  detail: PaperDetail | null;
  color?: string;
  beforeWrite(): boolean;
  onSaved(annotation?: ResearchAnnotation, created?: boolean): Promise<void>;
  notify(message: string, error?: boolean): void;
}) {
  const [saving, setSaving] = useState(false);
  const [undoing, setUndoing] = useState(false);
  const [notice, setNotice] = useState<HighlightNotice | null>(null);
  const locked = useRef(false);
  const lastAction = useRef({ signature: "", id: "" });
  useEffect(() => {
    if (
      !notice ||
      saving ||
      undoing ||
      !detail?.paper.pdfEtag ||
      notice.pdfEtag === detail.paper.pdfEtag
    )
      return;
    let cancelled = false;
    queueMicrotask(() => {
      if (!cancelled)
        setNotice((current) =>
          current?.pdfEtag === notice.pdfEtag ? null : current,
        );
    });
    return () => {
      cancelled = true;
    };
  }, [notice, saving, undoing, detail?.paper.pdfEtag]);
  async function save(selection: ResearchSelection) {
    if (locked.current || !beforeWrite()) return;
    if (!selection.rects?.length) {
      notify("请在 PDF 原文中选中文字后高亮。", true);
      return;
    }
    const input = {
      paperId: paper.id,
      page: selection.page,
      text: selection.text,
      quote: selection.quote,
      rects: selection.rects,
      contentRevision: selection.contentRevision,
      pdfEtag: detail?.paper.pdfEtag ?? selection.pdfEtag ?? paper.pdfEtag,
      kind: "highlight",
      color,
      comment: "",
    };
    const signature = JSON.stringify(input);
    if (lastAction.current.signature !== signature)
      lastAction.current = { signature, id: crypto.randomUUID() };
    locked.current = true;
    setSaving(true);
    try {
      const result = await postJson<{
        annotation: ResearchAnnotation;
        paper: ResearchPaper;
        created?: boolean;
      }>("/annotations", {
        ...input,
        actionId: lastAction.current.id,
      });
      const created = result.created !== false;
      setNotice({
        annotation: result.annotation,
        pdfEtag: result.paper.pdfEtag,
        created,
      });
      try {
        await onSaved(result.annotation, created);
      } catch {
        notify("高亮已保存，列表暂未刷新，请重新打开论文核对。", true);
        return;
      }
      notify(created ? "高亮已保存。" : "此处已有高亮，可直接添加想法。");
    } catch (error) {
      notify(errorText(error), true);
    } finally {
      locked.current = false;
      setSaving(false);
    }
  }
  async function undo() {
    if (locked.current || !notice?.created || !beforeWrite()) return;
    const target = notice;
    locked.current = true;
    setUndoing(true);
    try {
      await researchApi(
        "/annotations/" + encodeURIComponent(target.annotation.id),
        {
          method: "DELETE",
          body: JSON.stringify({
            version: target.annotation.version,
            pdfEtag: target.pdfEtag,
          }),
        },
      );
      setNotice(null);
      try {
        await onSaved();
      } catch {
        notify("已撤销高亮，列表暂未刷新，请重新打开论文核对。", true);
        return;
      }
      notify("已撤销本次高亮。");
    } catch (error) {
      notify("未撤销高亮：" + errorText(error), true);
    } finally {
      locked.current = false;
      setUndoing(false);
    }
  }
  return {
    saving,
    save,
    notice,
    undoing,
    undo,
    dismiss: () => setNotice(null),
  };
}

import type {
  GraphEdge,
  KnowledgeEntry,
  ResearchAnnotation,
  ResearchGraph,
