const normalize = (value: string) => value.normalize("NFKC").toLowerCase();

export function ResearchHelp({
  onNavigate,
  papers = [],
  onOpenPaper,
}: {
  onNavigate(view: HelpDestination): void;
  papers?: Pick<ResearchPaper, "id" | "title">[];
  onOpenPaper?(paperId: string): void;
}) {
  const [query, setQuery] = useState("");
  const [expanded, setExpanded] = useState<string[]>(["reader"]);
  const needle = normalize(query.trim());
  const sections = helpSections.filter(
    (section) =>
      !needle ||
      normalize(
        [
          section.title,
          section.lead,
          ...section.steps,
          section.tip,
          section.keywords,
        ].join(" "),
      ).includes(needle),
  );
  const questions = helpQuestions.filter(
    (item) =>
      !needle || normalize(item.question + item.answer).includes(needle),
  );
  const example = papers[0];
  function toggle(id: string, open: boolean) {
    setExpanded((current) =>
      open
        ? current.includes(id)
          ? current
          : [...current, id]
        : current.filter((value) => value !== id),
    );
  }
  return (
    <div className={styles.helpPage}>
      <header className={styles.heading}>
        <div>
          <h1>使用说明</h1>
          <p>阅读、整理与复习。</p>
        </div>
        <button onClick={() => onNavigate("library")}>
          打开文献库
          <ArrowUpRight size={15} aria-hidden="true" />
        </button>
      </header>
      {!needle && (
        <section
          className={styles.quickStart}
          aria-labelledby="help-start-title"
        >
          <div className={styles.quickTitle}>
            <BookOpen size={18} aria-hidden="true" />
            <h2 id="help-start-title">第一次使用</h2>
          </div>
          <ol>
            <li>
              <strong>打开论文</strong>
              <span>在文献库选择已导入的论文。</span>
            </li>
            <li>
              <strong>读懂一段原文</strong>
              <span>选中文字提问，或直接解释并复述理解。</span>
            </li>
            <li>
              <strong>整理为笔记</strong>
              <span>选择材料范围，编辑、核对并保存草稿。</span>
            </li>
            <li>
              <strong>自测与复习</strong>
              <span>先回答再看答案，自评后继续下一题。</span>
            </li>
          </ol>
          <div className={styles.examples}>
            {onOpenPaper && example && (
              <button onClick={() => onOpenPaper(example.id)}>
                打开已导入论文
                <ArrowUpRight size={14} aria-hidden="true" />
              </button>
            )}
            <button onClick={() => onNavigate("notes")}>
              查看已有笔记
              <ArrowUpRight size={14} aria-hidden="true" />
            </button>
          </div>
        </section>
      )}
      <div className={styles.search}>
        <Search size={17} aria-hidden="true" />
        <input
          aria-label="搜索使用说明"
          type="search"
          value={query}
          onChange={(event) => setQuery(event.target.value)}
          placeholder="查找功能或问题，例如：删除评论、草稿、备份"
        />
        {query && (
          <button aria-label="清空说明搜索" onClick={() => setQuery("")}>
            <X size={15} aria-hidden="true" />
          </button>
        )}
      </div>
      {needle && (
        <p className={styles.resultCount}>
          找到 {sections.length} 个功能主题、{questions.length} 个常见问题
        </p>
      )}
      <div className={styles.contentLayout}>
        <nav className={styles.contents} aria-label="使用说明目录">
          {sections.map((section) => (
            <a
              key={section.id}
              href={"#help-" + section.id}
              onClick={() => toggle(section.id, true)}
            >
              {section.title}
            </a>
          ))}
          {questions.length > 0 && <a href="#help-faq">常见问题</a>}
        </nav>
        <div className={styles.sections}>
          {sections.map((section) => (
            <details
              className={styles.section}
              id={"help-" + section.id}
              key={section.id}
              open={!!needle || expanded.includes(section.id)}
              onToggle={(event) => {
                if (!needle) toggle(section.id, event.currentTarget.open);
              }}
            >
              <summary>
                <span>{section.title}</span>
                <ChevronDown size={17} aria-hidden="true" />
              </summary>
              <div className={styles.sectionBody}>
                <p>{section.lead}</p>
                <ol>
                  {section.steps.map((step) => (
                    <li key={step}>{step}</li>
                  ))}
                </ol>
                {section.tip && <p className={styles.tip}>{section.tip}</p>}
                <button
                  className={styles.sectionAction}
                  onClick={() => onNavigate(section.destination)}
                >
                  {section.action}
                  <ArrowUpRight size={14} aria-hidden="true" />
                </button>
              </div>
            </details>
          ))}
          {questions.length > 0 && (
            <section className={styles.faq} id="help-faq">
              <h2>常见问题</h2>
              {questions.map((item) => (
                <details key={item.question} open={needle ? true : undefined}>
                  <summary>
                    {item.question}
                    <ChevronDown size={16} aria-hidden="true" />
                  </summary>
                  <p>{item.answer}</p>
                </details>
              ))}
            </section>
          )}
          {!sections.length && !questions.length && (
            <p className={styles.empty}>
              没有找到相关说明。试试“评论”“笔记”或“备份”。
            </p>
          )}
        </div>
      </div>
    </div>
  );
}

"use client";

import { Minus, Plus, RotateCcw, X } from "lucide-react";
import Image from "next/image";
import {
  useEffect,
  useId,
  useLayoutEffect,
  useRef,
  useState,
  type KeyboardEvent,
  type PointerEvent,
} from "react";
import styles from "./artwork-viewer.module.css";

const ZOOM_LEVELS = [1, 1.5, 2, 3] as const;

type DragPosition = {
  pointerId: number;
  x: number;
  y: number;
  scrollLeft: number;
  scrollTop: number;
};

export function ArtworkViewer({ onClose }: { onClose(): void }) {
  const titleId = useId();
  const instructionsId = useId();
  const dialogRef = useRef<HTMLDialogElement>(null);
  const viewportRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLDivElement>(null);
  const dragRef = useRef<DragPosition | null>(null);
  const pendingCenterRef = useRef<{ x: number; y: number } | null>(null);
  const [zoomIndex, setZoomIndex] = useState(0);
  const [isDragging, setIsDragging] = useState(false);
  const [imageFailed, setImageFailed] = useState(false);
  const zoom = ZOOM_LEVELS[zoomIndex];

  useEffect(() => {
    const dialog = dialogRef.current;
    const previousFocus = document.activeElement;

    if (dialog && !dialog.open) dialog.showModal();

    return () => {
      if (dialog?.open) dialog.close();
      if (previousFocus instanceof HTMLElement && previousFocus.isConnected) {
        previousFocus.focus({ preventScroll: true });
      }
    };
  }, []);

  useLayoutEffect(() => {
    const viewport = viewportRef.current;
    const canvas = canvasRef.current;
    const center = pendingCenterRef.current;
    if (!viewport || !canvas || !center) return;

    pendingCenterRef.current = null;
    const viewportBounds = viewport.getBoundingClientRect();
    const canvasBounds = canvas.getBoundingClientRect();
    viewport.scrollLeft +=
      canvasBounds.left +
      canvasBounds.width * center.x -
      (viewportBounds.left + viewport.clientLeft + viewport.clientWidth / 2);
    viewport.scrollTop +=
      canvasBounds.top +
      canvasBounds.height * center.y -
      (viewportBounds.top + viewport.clientTop + viewport.clientHeight / 2);
  }, [zoomIndex]);

  function finishDrag() {
    const viewport = viewportRef.current;
    const drag = dragRef.current;
    dragRef.current = null;
    if (viewport && drag && viewport.hasPointerCapture(drag.pointerId)) {
      viewport.releasePointerCapture(drag.pointerId);
    }
    setIsDragging(false);
  }

  function changeZoom(nextIndex: number) {
    const boundedIndex = Math.max(
      0,
      Math.min(nextIndex, ZOOM_LEVELS.length - 1),
    );
    if (boundedIndex === zoomIndex) return;

    finishDrag();
    const viewport = viewportRef.current;
    const canvas = canvasRef.current;
    if (viewport && canvas) {
      const viewportBounds = viewport.getBoundingClientRect();
      const canvasBounds = canvas.getBoundingClientRect();
      pendingCenterRef.current = {
        x:
          (viewportBounds.left +
            viewport.clientLeft +
            viewport.clientWidth / 2 -
            canvasBounds.left) /
          canvasBounds.width,
        y:
          (viewportBounds.top +
            viewport.clientTop +
            viewport.clientHeight / 2 -
            canvasBounds.top) /
          canvasBounds.height,
      };
    }
    setZoomIndex(boundedIndex);
  }

  function startDrag(event: PointerEvent<HTMLDivElement>) {
    if (zoom === 1 || event.pointerType !== "mouse" || event.button !== 0) {
      return;
    }

    event.preventDefault();
    event.currentTarget.focus({ preventScroll: true });
    event.currentTarget.setPointerCapture(event.pointerId);
    dragRef.current = {
      pointerId: event.pointerId,
      x: event.clientX,
      y: event.clientY,
      scrollLeft: event.currentTarget.scrollLeft,
      scrollTop: event.currentTarget.scrollTop,
    };
    setIsDragging(true);
  }

  function moveDrag(event: PointerEvent<HTMLDivElement>) {
    const drag = dragRef.current;
    if (!drag || drag.pointerId !== event.pointerId) return;
    event.currentTarget.scrollLeft = drag.scrollLeft - (event.clientX - drag.x);
    event.currentTarget.scrollTop = drag.scrollTop - (event.clientY - drag.y);
  }

  function handleViewportKey(event: KeyboardEvent<HTMLDivElement>) {
    if (event.altKey || event.ctrlKey || event.metaKey) return;

    if (event.key === "+" || event.key === "=") {
      event.preventDefault();
      changeZoom(zoomIndex + 1);
    } else if (event.key === "-") {
      event.preventDefault();
      changeZoom(zoomIndex - 1);
    } else if (event.key === "0") {
      event.preventDefault();
      changeZoom(0);
    } else if (event.key.startsWith("Arrow")) {
      const viewport = event.currentTarget;
      const distance = event.shiftKey ? 240 : 80;
      const directions: Record<string, readonly [number, number]> = {
        ArrowLeft: [-distance, 0],
        ArrowRight: [distance, 0],
        ArrowUp: [0, -distance],
        ArrowDown: [0, distance],
      };
      const direction = directions[event.key];
      if (!direction) return;
      event.preventDefault();
      viewport.scrollBy({ left: direction[0], top: direction[1] });
    }
  }

  function close() {
    dialogRef.current?.close();
  }

  return (
    <dialog
      ref={dialogRef}
      className={styles.dialog}
      aria-labelledby={titleId}
      onClose={() => {
        // Ignore a queued cleanup event if Strict Mode has reopened the dialog.
        if (!dialogRef.current?.open) onClose();
      }}
      onClick={(event) => {
        if (event.target !== event.currentTarget) return;
        const bounds = event.currentTarget.getBoundingClientRect();
        if (
          event.clientX < bounds.left ||
          event.clientX > bounds.right ||
          event.clientY < bounds.top ||
          event.clientY > bounds.bottom
        ) {
          close();
        }
      }}
    >
      <div className={styles.viewer}>
        <header className={styles.header}>
          <h2 id={titleId} className={styles.visuallyHidden}>
            画作细节
          </h2>
          <div
            className={styles.toolbar}
            role="group"
            aria-label="画作查看工具"
          >
            <button
              className={styles.control}
              type="button"
              aria-label="缩小画作"
              title="缩小（－）"
              disabled={zoomIndex === 0}
              onClick={() => changeZoom(zoomIndex - 1)}
            >
              <Minus size={18} aria-hidden="true" />
            </button>
            <output
              className={styles.zoomValue}
              aria-label="当前缩放比例"
              aria-live="polite"
              aria-atomic="true"
            >
              {zoom * 100}%
            </output>
            <button
              className={styles.control}
              type="button"
              aria-label="放大画作"
              title="放大（＋）"
              disabled={zoomIndex === ZOOM_LEVELS.length - 1}
              onClick={() => changeZoom(zoomIndex + 1)}
            >
              <Plus size={18} aria-hidden="true" />
            </button>
            <span className={styles.separator} aria-hidden="true" />
            <button
              className={`${styles.control} ${styles.reset}`}
              type="button"
              aria-label="还原至适合窗口"
              title="还原（0）"
              onClick={() => changeZoom(0)}
            >
              <RotateCcw size={16} aria-hidden="true" />
              <span>还原</span>
            </button>
            <button
              className={styles.control}
              type="button"
              aria-label="关闭观画窗口"
              title="关闭（Esc）"
              onClick={close}
            >
              <X size={20} aria-hidden="true" />
            </button>
          </div>
        </header>
        <div
          ref={viewportRef}
          className={styles.viewport}
          role="region"
          aria-label="画作细节"
          aria-describedby={instructionsId}
          tabIndex={0}
          data-zoom={zoom}
          data-dragging={isDragging}
          onKeyDown={handleViewportKey}
          onPointerDown={startDrag}
          onPointerMove={moveDrag}
          onPointerUp={finishDrag}
          onPointerCancel={finishDrag}
          onLostPointerCapture={finishDrag}
        >
          <div className={styles.stage}>
            <div ref={canvasRef} className={styles.canvas}>
              <Image
                className={styles.artwork}
                src="/vendor/research-cover/school-of-athens.webp"
                alt="古典拱廊下，哲学家们聚集交谈、阅读与思考。"
                width={3820}
                height={2964}
                loading="eager"
                unoptimized
                draggable={false}
                onError={() => setImageFailed(true)}
              />
            </div>
          </div>
          {imageFailed && (
            <p className={styles.error} role="alert">
              画作暂时无法显示，请关闭后重试。
            </p>
          )}
        </div>
        <p id={instructionsId} className={styles.visuallyHidden}>
          放大后拖动画作查看细节；键盘 ＋ / － 缩放，0 还原，方向键移动。
        </p>
      </div>
    </dialog>
  );
}

"use client";

/* eslint-disable @next/next/no-img-element -- These bundled, offline paintings need their real img elements for decode() and a continuous two-layer crossfade. */

import {
  useEffect,
  useId,
  useLayoutEffect,
  useRef,
  useState,
  useSyncExternalStore,
} from "react";
import { COVER_ARTWORKS } from "./cover-artworks";
import styles from "./gallery.module.css";

const HOLD_MS = 6_000;
const FADE_MS = 1_800;
const REDUCED_MOTION_RATE = 12;
const MOTION_QUERY = "(prefers-reduced-motion: reduce)";
const INITIAL_INDEX = Math.max(
  0,
  COVER_ARTWORKS.findIndex((artwork) =>
    artwork.src.includes("school-of-athens"),
  ),
);

type GalleryView = { current: number; incoming: number | null };

function subscribeToVisibility(onChange: () => void) {
  document.addEventListener("visibilitychange", onChange);
  return () => document.removeEventListener("visibilitychange", onChange);
}

function subscribeToMotion(onChange: () => void) {
  const preference = window.matchMedia(MOTION_QUERY);
  preference.addEventListener("change", onChange);
  return () => preference.removeEventListener("change", onChange);
}

function subscribeToMount() {
  return () => {};
}

const readMounted = () => true;
const readNotMounted = () => false;
const readVisible = () => document.visibilityState === "visible";
const readServerVisible = () => true;
const readReducedMotion = () => window.matchMedia(MOTION_QUERY).matches;
const readServerMotion = () => false;

function artworkAt(index: number, offset = 0) {
  return COVER_ARTWORKS[
    (index + offset + COVER_ARTWORKS.length) % COVER_ARTWORKS.length
  ];
}

/** Keys keep the fully decoded incoming element alive when it becomes the base. */
function ArtworkLayers({
  current,
  incoming,
  offset = 0,
  decorative = false,
}: GalleryView & { offset?: number; decorative?: boolean }) {
  const layers = [
    { artwork: artworkAt(current, offset), entering: false },
    ...(incoming === null
      ? []
      : [{ artwork: artworkAt(incoming, offset), entering: true }]),
  ];

  return layers.map(({ artwork, entering }) => (
    <img
      key={artwork.id}
      src={artwork.src}
      alt={decorative || entering ? "" : artwork.alt}
      aria-hidden={decorative || entering ? true : undefined}
      className={`${decorative ? styles.wingImage : styles.mainImage} ${entering ? styles.incoming : styles.outgoing}`}
      data-artwork={artwork.id}
      data-gallery-incoming={entering ? "true" : undefined}
      decoding="async"
      loading="eager"
      fetchPriority={!decorative && !entering ? "high" : "auto"}
      draggable={false}
    />
  ));
}

export function FloatingGallery({
  suspended = false,
}: {
  suspended?: boolean;
}) {
  const descriptionId = useId();
  const galleryRef = useRef<HTMLDivElement>(null);
  const [view, setView] = useState<GalleryView>({
    current: INITIAL_INDEX,
    incoming: null,
  });
  const { current: currentIndex, incoming: incomingIndex } = view;
  const [playbackOverride, setPlaybackOverride] = useState<boolean | null>(
    null,
  );
  const [inView, setInView] = useState(true);
  const mounted = useSyncExternalStore(
    subscribeToMount,
    readMounted,
    readNotMounted,
  );
  const pageVisible = useSyncExternalStore(
    subscribeToVisibility,
    readVisible,
    readServerVisible,
  );
  const reducedMotion = useSyncExternalStore(
    subscribeToMotion,
    readReducedMotion,
    readServerMotion,
  );
  const wantsToPlay = playbackOverride ?? !reducedMotion;
  const playing = mounted && wantsToPlay && pageVisible && inView && !suspended;
  const playbackRef = useRef({ playing: false, reducedMotion: false });
  const animationsRef = useRef<Animation[]>([]);
  const nextArtworkRef = useRef((INITIAL_INDEX + 1) % COVER_ARTWORKS.length);
  const countdownRef = useRef<{
    timer: ReturnType<typeof setTimeout> | null;
    startedAt: number;
    remaining: number;
  }>({ timer: null, startedAt: 0, remaining: HOLD_MS });

  // Pause the animation itself, retaining the exact blend rather than restarting it.
  // The ref also applies the current preference if an image finishes decoding later.
  useLayoutEffect(() => {
    playbackRef.current = { playing, reducedMotion };
    for (const animation of animationsRef.current) {
      animation.playbackRate = reducedMotion ? REDUCED_MOTION_RATE : 1;
      if (playing) animation.play();
      else animation.pause();
    }
  }, [playing, reducedMotion]);

  useEffect(() => {
    const gallery = galleryRef.current;
    if (!gallery || typeof IntersectionObserver === "undefined") return;
    const observer = new IntersectionObserver(
      ([entry]) => setInView(entry.isIntersecting),
      { threshold: 0 },
    );
    observer.observe(gallery);
    return () => observer.disconnect();
  }, []);

  // A dwell is a countdown, not a repeating interval: backgrounding or pausing
  // consumes none of the remaining six seconds.
  useEffect(() => {
    if (!playing || incomingIndex !== null || COVER_ARTWORKS.length < 2) return;
    const countdown = countdownRef.current;
    countdown.startedAt = performance.now();
    const timer = setTimeout(() => {
      countdown.timer = null;
      countdown.remaining = 0;
      let next = nextArtworkRef.current;
      if (next === currentIndex) next = (next + 1) % COVER_ARTWORKS.length;
      nextArtworkRef.current = (next + 1) % COVER_ARTWORKS.length;
      setView({ current: currentIndex, incoming: next });
    }, countdown.remaining);
    countdown.timer = timer;

    return () => {
      if (countdown.timer !== timer) return;
      clearTimeout(timer);
      countdown.timer = null;
      countdown.remaining = Math.max(
        0,
        countdown.remaining - (performance.now() - countdown.startedAt),
      );
    };
  }, [playing, currentIndex, incomingIndex]);

  useEffect(() => {
    if (incomingIndex === null) return;
    const next = incomingIndex;
    const gallery = galleryRef.current;
    if (!gallery) return;
    let disposed = false;
    let animations: Animation[] = [];
    const incomingImages = Array.from(
      gallery.querySelectorAll<HTMLImageElement>("[data-gallery-incoming]"),
    );

    async function crossfade() {
      // Keep every old image opaque until all three new images are ready to paint.
      await Promise.all(incomingImages.map((image) => image.decode()));
      if (disposed) return;

      if (
        incomingImages.every((image) => typeof image.animate === "function")
      ) {
        animations = incomingImages.map((image) =>
          image.animate([{ opacity: 0 }, { opacity: 1 }], {
            duration: FADE_MS,
            easing: "ease-in-out",
            fill: "both",
          }),
        );
        animationsRef.current = animations;
        for (const animation of animations) {
          animation.playbackRate = playbackRef.current.reducedMotion
            ? REDUCED_MOTION_RATE
            : 1;
          if (!playbackRef.current.playing) animation.pause();
        }
        await Promise.all(animations.map((animation) => animation.finished));
      }

      if (disposed) return;
      countdownRef.current.remaining = HOLD_MS;
      setView({ current: next, incoming: null });
    }

    void crossfade().catch(() => {
      if (disposed) return;
      // A missing or corrupt local asset must never replace the visible painting.
      // Retry the following artwork after a full dwell instead of spinning on it.
      countdownRef.current.remaining = HOLD_MS;
      setView({ current: currentIndex, incoming: null });
    });

    return () => {
      disposed = true;
      if (animationsRef.current === animations) animationsRef.current = [];
      for (const animation of animations) animation.cancel();
    };
  }, [currentIndex, incomingIndex]);

  const currentArtwork = artworkAt(view.current);

  return (
    <div
      ref={galleryRef}
      className={`${styles.gallery}${playing ? "" : ` ${styles.paused}`}`}
      data-home-gallery
      data-playing={playing ? "true" : "false"}
      data-artwork={currentArtwork.id}
      data-transitioning={view.incoming === null ? "false" : "true"}
      data-reduced-motion={reducedMotion ? "true" : "false"}
    >
      <button
        type="button"
        className={styles.stageButton}
        onClick={() => setPlaybackOverride(!wantsToPlay)}
        aria-label={playing ? "暂停画廊播放" : "继续画廊播放"}
        aria-pressed={!playing}
        aria-describedby={descriptionId}
      >
        <span className={styles.leftWing} aria-hidden="true">
          <ArtworkLayers {...view} offset={-1} decorative />
        </span>
        <span className={styles.mainFrame}>
          <ArtworkLayers {...view} />
        </span>
        <span className={styles.rightWing} aria-hidden="true">
          <ArtworkLayers {...view} offset={1} decorative />
        </span>
      </button>
      <span id={descriptionId} className={styles.srOnly}>
        {currentArtwork.alt}
      </span>
    </div>
  );
}

"use client";

import type {
  GraphNode,
  ResearchGraph,
  ResearchNote,
  ResearchPaper,
} from "@/lib/research/types";
import { ArrowRight, ArrowUpRight, X } from "lucide-react";
import type { Ref } from "react";
import {
  homeGraphConcepts,
  recentHomeNotes,
  searchHomePapers,
} from "./home-data";
import styles from "./home-interactive.module.css";

export type HomeDestination = "library" | "notes" | "graph";

const labels = {
  library: "最近更新的论文",
  notes: "最近的研究笔记",
  graph: "已确认的概念",
};
const entryLabels = {
  library: "打开文献库",
  notes: "打开研究笔记",
  graph: "打开知识图谱",
};

export function HomePreview({
  destination,
  papers,
  notes,
  graph,
  panelRef,
  onNavigate,
  onOpen,
  onOpenNote,
  onOpenGraph,
  onClose,
}: {
  destination: HomeDestination;
  papers: ResearchPaper[];
  notes: ResearchNote[];
  graph?: ResearchGraph;
  panelRef: Ref<HTMLElement>;
  onNavigate(view: HomeDestination): void;
  onOpen(paper: ResearchPaper): void;
  onOpenNote?(note: ResearchNote): void;
  onOpenGraph?(node?: GraphNode): void;
  onClose(): void;
}) {
  const recentPapers = searchHomePapers(papers, "").slice(0, 3);
  const recentNotes = recentHomeNotes(notes, papers).slice(0, 3);
  const concepts = homeGraphConcepts(graph, papers).slice(0, 3);
  const isEmpty =
    destination === "library"
      ? !recentPapers.length
      : destination === "notes"
        ? !recentNotes.length
        : !concepts.length;

  return (
    <section
      id="home-preview"
      ref={panelRef}
      tabIndex={-1}
      className={styles.preview}
      aria-labelledby="home-preview-title"
      onKeyDown={(event) => {
        if (event.key === "Escape") {
          event.stopPropagation();
          onClose();
        }
      }}
    >
      <div className={styles.previewHeader}>
        <h2 id="home-preview-title">{labels[destination]}</h2>
        <button
          type="button"
          className={styles.close}
          onClick={onClose}
          aria-label="关闭首页预览"
        >
          <X size={18} aria-hidden="true" />
        </button>
      </div>
      <div className={styles.previewItems}>
        {destination === "library" &&
          recentPapers.map((paper) => (
            <button key={paper.id} type="button" onClick={() => onOpen(paper)}>
              <span>
                <strong>{paper.title}</strong>
                <small>
                  {[paper.authors, paper.year].filter(Boolean).join(" · ") ||
                    paper.topic}
                </small>
              </span>
              <ArrowUpRight size={18} aria-hidden="true" />
            </button>
          ))}
        {destination === "notes" &&
          recentNotes.map((note) => (
            <button
              key={note.id}
              type="button"
              onClick={() =>
                onOpenNote ? onOpenNote(note) : onNavigate("notes")
              }
            >
              <span>
                <strong>{note.title || "未命名笔记"}</strong>
                <small>
                  {papers.find((paper) => paper.id === note.paperId)?.title}
                </small>
              </span>
              <ArrowUpRight size={18} aria-hidden="true" />
            </button>
          ))}
        {destination === "graph" &&
          concepts.map((node) => (
            <button
              key={node.id}
              type="button"
              onClick={() =>
                onOpenGraph ? onOpenGraph(node) : onNavigate("graph")
              }
              aria-label={"打开知识图谱，查看概念：" + node.label}
            >
              <span>
                <strong>{node.label}</strong>
                {node.topic ? <small>{node.topic}</small> : null}
              </span>
              <ArrowUpRight size={18} aria-hidden="true" />
            </button>
          ))}
        {isEmpty ? (
          <p className={styles.empty}>
            {destination === "library"
              ? "还没有论文。进入文献库，导入第一篇。"
              : destination === "notes"
                ? "还没有笔记。阅读时可以保存摘录与想法。"
                : "还没有已确认的概念。可在图谱中检查并确认概念关系。"}
          </p>
        ) : null}
      </div>
      <button
        type="button"
        className={styles.previewEnter}
        onClick={() => onNavigate(destination)}
      >
        {entryLabels[destination]}
        <ArrowRight size={18} aria-hidden="true" />
      </button>
    </section>
  );
}

"use client";

import type { ResearchPaper } from "@/lib/research/types";
import { ArrowUpRight, Search } from "lucide-react";
import { useEffect, useRef, useState } from "react";
import { Modal } from "../ResearchUi";
import { searchHomePapers } from "./home-data";
import styles from "./home-interactive.module.css";

export function HomeSearch({
  papers,
  onOpen,
  onClose,
}: {
  papers: ResearchPaper[];
  onOpen(paper: ResearchPaper): void;
  onClose(): void;
}) {
  const [query, setQuery] = useState("");
  const input = useRef<HTMLInputElement>(null);
  const resultsRef = useRef<HTMLDivElement>(null);
  const results = searchHomePapers(papers, query);
  useEffect(() => {
    // Focus after the shared modal has established its focus trap.
    const frame = requestAnimationFrame(() => input.current?.focus());
    return () => cancelAnimationFrame(frame);
  }, []);
  const open = (paper: ResearchPaper) => {
    onClose();
    onOpen(paper);
  };

  return (
    <Modal title="查找论文" onClose={onClose}>
      <form
        className={styles.searchForm}
        onSubmit={(event) => {
          event.preventDefault();
          if (results[0]) open(results[0]);
        }}
      >
        <label htmlFor="home-paper-query" className={styles.searchLabel}>
          题名、作者或标签
        </label>
        <div className={styles.searchInput}>
          <Search size={19} aria-hidden="true" />
          <input
            id="home-paper-query"
            ref={input}
            value={query}
            onChange={(event) => setQuery(event.target.value)}
            onKeyDown={(event) => {
              if (event.key === "ArrowDown" && results.length) {
                event.preventDefault();
                resultsRef.current?.querySelector("button")?.focus();
              }
            }}
            placeholder="搜索本机文献库…"
            autoComplete="off"
            aria-describedby="home-search-status"
          />
          <button type="submit" disabled={!results.length}>
            打开
          </button>
        </div>
      </form>
      <p id="home-search-status" className={styles.searchStatus} role="status">
        {query.trim()
          ? results.length
            ? "找到 " + results.length + " 篇论文"
            : "未找到论文，试试其他题名、作者或标签。"
          : results.length
            ? "最近更新"
            : "文献库为空，导入论文后即可搜索。"}
      </p>
      <div ref={resultsRef} className={styles.searchResults}>
        {results.slice(0, 20).map((paper) => (
          <button
            key={paper.id}
            type="button"
            className={styles.searchResult}
            onClick={() => open(paper)}
          >
            <span>
              <strong>{paper.title}</strong>
              <small>
                {[paper.authors, paper.year, paper.topic]
                  .filter(Boolean)
                  .join(" · ")}
              </small>
            </span>
            <ArrowUpRight size={19} aria-hidden="true" />
          </button>
        ))}
      </div>
      {results.length > 20 ? (
        <p className={styles.searchStatus}>
          显示前 20 篇，请继续输入以缩小范围。
        </p>
      ) : null}
    </Modal>
  );
}

