"use client";
import { useState } from "react";
import type { LearningRequest } from "@/lib/research/learning-types";
import { Modal } from "../ResearchUi";
import styles from "../styles";
import local from "./learning.module.css";
export function ExplanationActions({
  active,
  onRequest,
}: {
  active: boolean;
  onRequest(request: LearningRequest): Promise<boolean>;
}) {
  const [open, setOpen] = useState(false);
  const [text, setText] = useState("");
  const [busy, setBusy] = useState(false);
  async function check() {
    if (!text.trim() || busy) return;
    setBusy(true);
    try {
      if (
        await onRequest({
          task: "understanding",
          source: { kind: "selection" },
          reflection: text,
        })
      )
        setOpen(false);
    } finally {
      setBusy(false);
    }
  }
  return (
    <>
      <div className={local.explanationActions}>
        <button
          disabled={active}
          onClick={() =>
            void onRequest({
              task: "explain",
              source: { kind: "selection" },
              detail: "example",
            })
          }
        >
          举个例子
        </button>
        <button
          disabled={active}
          onClick={() =>
            void onRequest({
              task: "explain",
              source: { kind: "selection" },
              detail: "deep",
            })
          }
        >
          深入解释
        </button>
        <button disabled={active} onClick={() => setOpen(true)}>
          检查我的理解
        </button>
      </div>
      {open && (
        <Modal
          title="用自己的话说明理解"
          onClose={() => !busy && setOpen(false)}
        >
          <div className={styles.modalBody}>
            <label className={styles.formLabel}>
              我的理解
              <textarea
                aria-label="我的理解"
                rows={6}
                value={text}
                onChange={(event) => setText(event.target.value)}
                maxLength={8000}
              />
            </label>
            <p className={local.hint}>
              参考原文指出准确、遗漏和需要修正之处，不自动评分。
            </p>
          </div>
          <div className={styles.modalFooter}>
            <button
              className={styles.secondaryButton}
              onClick={() => setOpen(false)}
              disabled={busy}
            >
              取消
            </button>
            <button
              className={styles.primaryButton}
              disabled={busy || !text.trim()}
              onClick={() => void check()}
            >
              {busy ? "正在提交…" : "检查理解"}
            </button>
          </div>
        </Modal>
      )}
    </>
  );
}

"use client";

import type {
  LearningRequest,
  LearningSource,
} from "@/lib/research/learning-types";
import type { ResearchPaper, ResearchSelection } from "@/lib/research/types";
import { useState } from "react";
import type { PaperDetail } from "../api";
import { Modal } from "../ResearchUi";
import styles from "../styles";
import local from "./learning.module.css";

export function LearningComposer({
  paper,
  detail,
  selection,
  initial,
  onClose,
  onGenerate,
}: {
  paper: ResearchPaper;
  detail: PaperDetail | null;
  selection: ResearchSelection | null;
  initial: LearningRequest;
  onClose(): void;
  onGenerate(request: LearningRequest): Promise<boolean>;
}) {
  const [source, setSource] = useState<LearningSource>(initial.source);
  const [count, setCount] = useState<3 | 5 | 8>(initial.count ?? 5);
  const [busy, setBusy] = useState(false);
  const notes = detail?.notes ?? [];
  const annotations = (detail?.annotations ?? []).filter(
    (entry) => entry.contentRevision === paper.contentRevision,
  );
  const selected = source.kind === "annotations" ? source.ids : [];
  function change(kind: string) {
    if (kind === "note" && notes[0])
      setSource({
        kind: "note",
        noteId: notes[0].id,
        version: notes[0].version,
      });
    else if (kind === "annotations")
      setSource({
        kind,
        ids: annotations.map((entry) => entry.id).slice(0, 30),
        versions: Object.fromEntries(
          annotations.map((entry) => [entry.id, entry.version]),
        ),
      });
    else if (kind === "selection") setSource({ kind });
    else setSource({ kind: "paper" });
  }
  async function generate() {
    if (busy) return;
    setBusy(true);
    try {
      if (
        await onGenerate({
          ...initial,
          source,
          ...(initial.task === "quiz" ? { count } : {}),
        })
      )
        onClose();
    } finally {
      setBusy(false);
    }
  }
  const valid =
    source.kind === "annotations"
      ? selected.length > 0 && selected.length <= 30
      : source.kind === "selection"
        ? !!selection
        : source.kind === "note"
          ? notes.some((note) => note.id === source.noteId)
          : true;
  return (
    <Modal
      title={initial.task === "notes" ? "整理阅读笔记" : "生成自测题"}
      onClose={() => !busy && onClose()}
    >
      <div className={styles.modalBody}>
        <p className={local.paperTitle}>{paper.title}</p>
        <label className={styles.formLabel}>
          材料范围
          <select
            aria-label="学习材料范围"
            value={source.kind}
            onChange={(event) => change(event.target.value)}
            disabled={busy}
          >
            <option value="paper">整篇论文</option>
            <option value="selection" disabled={!selection}>
              当前选文{selection ? ` · 第${selection.page}页` : ""}
            </option>
            <option value="annotations" disabled={!annotations.length}>
              已有批注 · {annotations.length}条
            </option>
            <option value="note" disabled={!notes.length}>
              已保存笔记
            </option>
          </select>
        </label>
        {source.kind === "note" && (
          <label className={styles.formLabel}>
            选择笔记
            <select
              aria-label="学习来源笔记"
              value={source.noteId}
              onChange={(event) => {
                const note = notes.find(
                  (entry) => entry.id === event.target.value,
                );
                if (note)
                  setSource({
                    kind: "note",
                    noteId: note.id,
                    version: note.version,
                  });
              }}
              disabled={busy}
            >
              {notes.map((note) => (
                <option key={note.id} value={note.id}>
                  {note.title}
                </option>
              ))}
            </select>
          </label>
        )}
        {source.kind === "annotations" && (
          <fieldset className={local.annotationChoices} disabled={busy}>
            <legend>选择批注</legend>
            {annotations.map((annotation) => (
              <label key={annotation.id}>
                <input
                  type="checkbox"
                  checked={selected.includes(annotation.id)}
                  disabled={
                    !selected.includes(annotation.id) && selected.length >= 30
                  }
                  onChange={(event) =>
                    setSource({
                      kind: "annotations",
                      ids: event.target.checked
                        ? [...selected, annotation.id]
                        : selected.filter((id) => id !== annotation.id),
                      versions: Object.fromEntries(
                        annotations.map((entry) => [entry.id, entry.version]),
                      ),
                    })
                  }
                />
                <span>
                  第{annotation.page}页 ·{" "}
                  {(
                    annotation.quote ||
                    annotation.comment ||
                    annotation.text
                  ).slice(0, 110)}
                </span>
              </label>
            ))}
          </fieldset>
        )}
        {initial.task === "quiz" && (
          <label className={styles.formLabel}>
            题目数量
            <select
              aria-label="自测题目数量"
              value={count}
              onChange={(event) =>
                setCount(Number(event.target.value) as 3 | 5 | 8)
              }
              disabled={busy}
            >
              <option value={3}>3题</option>
              <option value={5}>5题</option>
              <option value={8}>8题</option>
            </select>
          </label>
        )}
        <p className={local.hint}>
          {initial.task === "notes"
            ? "生成后先编辑、核对来源，再保存笔记。"
            : "生成后点击“开始逐题复习”，作答和进度保存在本机。"}
        </p>
      </div>
      <div className={styles.modalFooter}>
        <button
          className={styles.secondaryButton}
          disabled={busy}
          onClick={onClose}
        >
          取消
        </button>
        <button
          className={styles.primaryButton}
          disabled={busy || !valid}
          onClick={() => void generate()}
        >
          {busy
            ? "正在提交…"
            : initial.task === "notes"
              ? "生成笔记草稿"
              : "生成自测题"}
        </button>
      </div>
    </Modal>
  );
}

"use client";

import type { ResearchNote, ResearchPaper } from "@/lib/research/types";
import { useEffect, useRef, useState } from "react";
import { localNoteKey, type LocalNoteDraft } from "./note-drafts";
import type { NoteEditorController } from "./use-note-editor";
import styles from "./learning.module.css";

export function NoteLeaveConfirm({
  onContinue,
  onCancel,
  disabled = false,
}: {
  onContinue(): void;
  onCancel(): void;
  disabled?: boolean;
}) {
  const cancel = useRef<HTMLButtonElement>(null);
  useEffect(() => {
    cancel.current?.focus();
    cancel.current?.scrollIntoView({ block: "nearest" });
  }, []);
  return (
    <div className={styles.draftWarning} role="alert">
      <p>当前修改尚未安全暂存，离开可能丢失。</p>
      <button ref={cancel} onClick={onCancel} disabled={disabled}>
        继续编辑
      </button>
      <button onClick={onContinue} disabled={disabled}>
        继续离开
      </button>
    </div>
  );
}

export function NoteDraftStatus({ editor }: { editor: NoteEditorController }) {
  const label = editor.busy
    ? "正在保存…"
    : !editor.ready
      ? "正在读取…"
      : !editor.unsaved
        ? editor.model.id
          ? "已保存"
          : "未保存"
        : editor.status === "local"
          ? "本机草稿"
          : "未保存";
  return (
    <span
      role="status"
      title={
        editor.unsaved && editor.status === "local"
          ? "仅暂存于当前浏览器，尚未保存到工作区"
          : undefined
      }
    >
      {label}
    </span>
  );
}
export function NoteDraftFeedback({
  editor,
  onSaveCopy,
}: {
  editor: NoteEditorController;
  onSaveCopy(): void;
}) {
  return (
    <>
      {editor.restored && (
        <p className={styles.draftHint}>已恢复本机草稿，尚未保存到工作区。</p>
      )}
      {editor.status === "unavailable" && (
        <p className={styles.draftWarning} role="status">
          浏览器无法暂存，未提交的修改需手动保存。
        </p>
      )}
      {editor.status === "conflict" && (
        <div className={styles.draftWarning} role="alert">
          <span>本机草稿已在另一窗口改变，当前文字仍在本页。</span>
          <button onClick={() => editor.localCopy()} disabled={editor.busy}>
            另存本机草稿
          </button>
        </div>
      )}
      {editor.server && (
        <div className={styles.draftWarning} role="alert">
          <p>笔记已有新版本。当前文字仍在编辑器，未覆盖工作区内容。</p>
          <details>
            <summary>查看当前版本</summary>
            <strong>{editor.server.title}</strong>
            <pre>{editor.server.body}</pre>
          </details>
          <button
            onClick={() => void editor.useCurrentVersion()}
            disabled={editor.busy}
          >
            保留草稿并打开新版本
          </button>
          <button onClick={onSaveCopy} disabled={editor.busy}>
            将草稿另存为新笔记
          </button>
        </div>
      )}
      {editor.error && (
        <p className={styles.error} role="alert">
          {editor.error}
          {editor.blocked && <button onClick={editor.retry}>重新读取</button>}
        </p>
      )}
    </>
  );
}
export function NoteDraftShelf({
  editor,
  papers,
  notes,
  onRecover,
}: {
  editor: NoteEditorController;
  papers: ResearchPaper[];
  notes: ResearchNote[];
  onRecover(entry: LocalNoteDraft): void;
}) {
  const [discarding, setDiscarding] = useState<string | null>(null);
  const paperIds = new Set(papers.map((paper) => paper.id));
  const noteIds = new Set(notes.map((note) => note.id));
  const drafts = editor.drafts.filter(
    (entry) =>
      entry.key !== localNoteKey(editor.model) &&
      (!entry.model.paperId || paperIds.has(entry.model.paperId)) &&
      (!entry.model.id || noteIds.has(entry.model.id)) &&
      entry.model.sources.every(
        (source) => !source.paperId || paperIds.has(source.paperId),
      ),
  );
  if (!drafts.length) return null;
  return (
    <details className={styles.draftShelf}>
      <summary>
        本机草稿 <span>{drafts.length}</span>
      </summary>
      <ul>
        {drafts.map((entry) => (
          <li key={entry.key}>
            <div>
              <strong>{entry.model.title || "未命名笔记"}</strong>
              <span>
                {
                  papers.find((paper) => paper.id === entry.model.paperId)
                    ?.title
                }
              </span>
            </div>
            <button disabled={editor.busy} onClick={() => onRecover(entry)}>
              恢复
            </button>
            <button
              disabled={editor.busy}
              onClick={() => setDiscarding(entry.key)}
            >
              丢弃
            </button>
            {discarding === entry.key && (
              <div className={styles.draftWarning} role="alert">
                <span>丢弃这份本机草稿？已保存的笔记不受影响。</span>
                <button onClick={() => setDiscarding(null)}>保留</button>
                <button
                  onClick={() => {
                    editor.discard(entry);
                    setDiscarding(null);
                  }}
                >
                  丢弃草稿
                </button>
              </div>
            )}
          </li>
        ))}
      </ul>
    </details>
  );
}

"use client";

import type {
  ResearchNote,
  ResearchPaper,
  SourceRef,
} from "@/lib/research/types";
import { Check, Eye, FilePenLine } from "lucide-react";
import { useEffect, useState } from "react";
import { Modal, SourceChips } from "../ResearchUi";
import { StudyMarkdown } from "../study/StudyMarkdown";
import styles from "../styles";
import learningStyles from "./learning.module.css";
import { generatedNoteOrigin } from "./note-drafts";
import {
  NoteDraftFeedback,
  NoteDraftStatus,
  NoteLeaveConfirm,
} from "./NoteDraftFeedback";
import { useNoteEditor } from "./use-note-editor";

export interface NoteDraft {
  id?: string;
  version?: number;
  title: string;
  body: string;
  sources: SourceRef[];
  runId?: string;
  origin?: string;
  kind?: ResearchNote["kind"];
  confirmed?: boolean;
}
export function NoteEditor({
  paper,
  draft,
  onClose,
  onSaved,
  onOpenSource,
  notify,
  beforeSave,
}: {
  paper: ResearchPaper;
  draft: NoteDraft;
  onClose(): void;
  onSaved(note: ResearchNote): Promise<void>;
  onOpenSource(source: SourceRef): void;
  notify(message: string, error?: boolean): void;
  beforeSave?(): Promise<boolean>;
}) {
  const editor = useNoteEditor({
    ...draft,
    paperId: paper.id,
    kind: draft.kind ?? "reading",
    confirmed: draft.confirmed ?? false,
    origin: generatedNoteOrigin(draft, draft.origin),
  });
  const [preview, setPreview] = useState(false);
  const [pendingLeave, setPendingLeave] = useState<(() => void) | null>(null);
  const { model, busy, unsaved } = editor;
  const disabled = busy || !editor.ready || editor.blocked;
  async function save(asNew = false) {
    await editor.save({ asNew, beforeSave, onSaved, notify });
  }
  useEffect(() => {
    const keydown = (event: KeyboardEvent) => {
      if (
        (event.ctrlKey || event.metaKey) &&
        event.key.toLowerCase() === "s" &&
        !event.altKey
      ) {
        event.preventDefault();
        event.stopImmediatePropagation();
        void editor.save({ beforeSave, onSaved, notify });
      }
    };
    window.addEventListener("keydown", keydown, true);
    return () => window.removeEventListener("keydown", keydown, true);
  }, [editor, beforeSave, onSaved, notify]);
  function close() {
    if (busy) return;
    if (pendingLeave && editor.protectLeave) {
      setPendingLeave(null);
      return;
    }
    requestLeave(onClose);
  }
  function requestLeave(action: () => void) {
    if (busy) return;
    if (editor.protectLeave) {
      setPendingLeave(() => action);
      return;
    }
    setPendingLeave(null);
    action();
  }
  return (
    <Modal
      title={model.id ? "编辑研究笔记" : "编辑阅读笔记"}
      wide
      onClose={close}
    >
      <div className={styles.modalBody}>
        <label className={styles.formLabel}>
          笔记标题
          <input
            aria-label="笔记标题"
            value={model.title}
            onChange={(event) => editor.change({ title: event.target.value })}
            maxLength={500}
            disabled={disabled}
          />
        </label>
        <div className={learningStyles.editorTabs}>
          <button
            type="button"
            aria-pressed={!preview}
            onClick={() => setPreview(false)}
          >
            <FilePenLine size={14} />
            编辑
          </button>
          <button
            type="button"
            aria-pressed={preview}
            onClick={() => setPreview(true)}
          >
            <Eye size={14} />
            预览
          </button>
          <NoteDraftStatus editor={editor} />
        </div>
        <NoteDraftFeedback editor={editor} onSaveCopy={() => void save(true)} />
        {pendingLeave && editor.protectLeave && (
          <NoteLeaveConfirm
            disabled={busy}
            onCancel={() => setPendingLeave(null)}
            onContinue={() => {
              if (busy) return;
              setPendingLeave(null);
              pendingLeave();
            }}
          />
        )}
        {preview ? (
          <div className={learningStyles.notePreview}>
            <StudyMarkdown content={model.body || "暂无正文"} />
          </div>
        ) : (
          <textarea
            aria-label="阅读笔记正文"
            className={learningStyles.noteBody}
            rows={13}
            value={model.body}
            onChange={(event) => editor.change({ body: event.target.value })}
            maxLength={200000}
            disabled={disabled}
          />
        )}
        {model.sources.length > 0 && (
          <div className={learningStyles.sourceRow}>
            <SourceChips
              sources={model.sources}
              onOpen={(source) => {
                if (disabled) return;
                requestLeave(() => {
                  onClose();
                  onOpenSource(source);
                });
              }}
            />
          </div>
        )}
      </div>
      <div className={styles.modalFooter}>
        <span className={learningStyles.saveShortcut}>Ctrl / ⌘ + S</span>
        <button
          className={styles.secondaryButton}
          onClick={close}
          disabled={busy}
        >
          关闭
        </button>
        <button
          className={styles.primaryButton}
          onClick={() => void save()}
          disabled={
            disabled ||
            !!editor.server ||
            !model.title.trim() ||
            !model.body.trim() ||
            !unsaved
          }
        >
          <Check size={14} />
          {busy ? "保存中…" : model.id ? "保存修改" : "保存草稿"}
        </button>
      </div>
    </Modal>
  );
}

