import { z } from "zod";
import { idSchema, sourceSchema } from "@/lib/research/schemas";
import type { ResearchNote, SourceRef } from "@/lib/research/types";

export interface EditableNote {
  id?: string;
  version?: number;
  paperId: string;
  title: string;
  body: string;
  kind: ResearchNote["kind"];
  sources: SourceRef[];
  runId?: string;
  confirmed: boolean;
  origin: string;
  slot?: string;
}

const editableSchema = z
  .object({
    id: idSchema.optional(),
    version: z.number().int().positive().optional(),
    paperId: z.union([idSchema, z.literal("")]),
    title: z.string().max(500),
    body: z.string().max(200000),
    kind: z.enum(["reading", "card", "concept", "reflection", "analysis"]),
    sources: z.array(sourceSchema).max(200),
    runId: idSchema.optional(),
    confirmed: z.boolean(),
    origin: z.string().min(1).max(200),
    slot: idSchema.optional(),
  })
  .refine(
    (model) => !!model.id === (model.version !== undefined),
    "已有笔记需要编辑开始时的版本",
  );
const pendingSchema = z.object({
  actionId: idSchema,
  model: editableSchema,
  confirmed: z.boolean(),
});
export type PendingNoteCreate = z.infer<typeof pendingSchema>;
const draftSchema = z.object({
  schema: z.literal(1),
  type: z.literal("draft"),
  key: z.string().max(700),
  token: z.string().min(1).max(100),
  model: editableSchema,
  pendingCreate: pendingSchema.optional(),
  updatedAt: z.string().datetime(),
});
const bindingSchema = z.object({
  schema: z.literal(1),
  type: z.literal("binding"),
  key: z.string().max(700),
  paperId: idSchema,
  noteId: idSchema,
});
export type LocalNoteDraft = z.infer<typeof draftSchema>;
export type NoteDraftBinding = z.infer<typeof bindingSchema>;
export type NoteDraftEntry = LocalNoteDraft | NoteDraftBinding;
export type DraftStorage = Pick<
  Storage,
  "getItem" | "setItem" | "removeItem" | "key" | "length"
>;
export const NOTE_DRAFT_PREFIX = "jiaoyan:note-draft:v1:";
export function needsNoteLeaveProtection(
  unsaved: boolean,
  status: "local" | "memory" | "unavailable" | "conflict",
  busy = false,
): boolean {
  return busy || (unsaved && status !== "local");
}

// This is a local UI identity, never a security token. The stored model and paper
// are checked again when reading a key, so identities cannot cross papers/notes.
function fingerprint(content: string): string {
  let first = 2166136261;
  let second = 2246822519;
  for (let index = 0; index < content.length; index++) {
    first = Math.imul(first ^ content.charCodeAt(index), 16777619);
    second = Math.imul(second ^ content.charCodeAt(index), 3266489917);
  }
  return `${(first >>> 0).toString(16)}${(second >>> 0).toString(16)}-${content.length}`;
}
export function generatedNoteOrigin(
  note: Pick<EditableNote, "title" | "body" | "sources" | "runId">,
  explicitOrigin?: string,
): string {
  if (explicitOrigin) return explicitOrigin;
  return note.runId
    ? `run-${note.runId}`
    : `source-${fingerprint(JSON.stringify([note.title, note.body, note.sources]))}`;
}
/** Keep excerpts separate from the full-answer binding, while reopening the same excerpt reliably. */
export function excerptNoteOrigin(runId: string, excerpt: string): string {
  return `run-${runId.slice(0, 100)}-excerpt-${fingerprint(JSON.stringify([runId, excerpt]))}`;
}
export function localNoteKey(
  model: Pick<EditableNote, "paperId" | "id" | "origin" | "slot">,
): string {
  return (
    NOTE_DRAFT_PREFIX +
    encodeURIComponent(model.paperId) +
    ":" +
    encodeURIComponent(model.id ? `note-${model.id}` : `new-${model.origin}`) +
    (model.slot ? ":slot-" + model.slot : "")
  );
}
export function noteTabSlot(
  storage: Pick<Storage, "getItem" | "setItem">,
): string {
  const key = "jiaoyan:note-editor-tab:v1";
  const previous = storage.getItem(key);
  if (previous && idSchema.safeParse(previous).success) return previous;
  const slot = crypto.randomUUID();
  storage.setItem(key, slot);
  return slot;
}
export function editableNote(note: ResearchNote): EditableNote {
  return {
    id: note.id,
    version: note.version,
    paperId: note.paperId,
    title: note.title,
    body: note.body,
    kind: note.kind,
    sources: note.sources,
    runId: note.runId,
    confirmed: note.confirmed,
    origin: `note-${note.id}`,
  };
}
export function sameNoteContent(
  first: EditableNote,
  second: EditableNote,
): boolean {
  return (
    first.paperId === second.paperId &&
    first.title === second.title &&
    first.body === second.body &&
    first.kind === second.kind &&
    JSON.stringify(first.sources) === JSON.stringify(second.sources)
  );
}
export function hasUnsavedNote(
  model: EditableNote,
  baseline: EditableNote,
): boolean {
  return (
    !sameNoteContent(model, baseline) ||
    (!model.id && !!(model.title.trim() || model.body.trim()))
  );
}
export function noteVersionConflict(
  model: EditableNote,
  note: Pick<ResearchNote, "id" | "paperId" | "version">,
): boolean {
  return (
    model.id === note.id &&
    (model.paperId !== note.paperId || model.version !== note.version)
  );
}
export function readLocalNote(
  storage: DraftStorage,
  key: string,
): NoteDraftEntry | null {
  const raw = storage.getItem(key);
  if (!raw) return null;
  try {
    const entry = z.union([draftSchema, bindingSchema]).parse(JSON.parse(raw));
    if (entry.key !== key || !key.startsWith(NOTE_DRAFT_PREFIX)) return null;
    if (entry.type === "draft" && localNoteKey(entry.model) !== key)
      return null;
    if (
      entry.type === "binding" &&
      !key.startsWith(
        NOTE_DRAFT_PREFIX + encodeURIComponent(entry.paperId) + ":new-",
      )
    )
      return null;
    if (
      entry.type === "draft" &&
      entry.pendingCreate &&
      (entry.model.id ||
        entry.pendingCreate.model.paperId !== entry.model.paperId)
    )
      return null;
    return entry;
  } catch {
    return null;
  }
}
export function listLocalNotes(storage: DraftStorage): LocalNoteDraft[] {
  const drafts: LocalNoteDraft[] = [];
  for (let index = 0; index < storage.length; index++) {
    const key = storage.key(index);
    if (!key?.startsWith(NOTE_DRAFT_PREFIX)) continue;
    const entry = readLocalNote(storage, key);
    if (
      entry?.type === "draft" &&
      (entry.model.title.trim() ||
        entry.model.body.trim() ||
        entry.pendingCreate)
    )
      drafts.push(entry);
  }
  return drafts.sort((a, b) => b.updatedAt.localeCompare(a.updatedAt));
}
export class LocalNoteConflict extends Error {}
export function writeLocalNote(
  storage: DraftStorage,
  entry: LocalNoteDraft,
  expectedToken: string | null,
): void {
  draftSchema.parse(entry);
  const current = readLocalNote(storage, entry.key);
  if ((current?.type === "draft" ? current.token : null) !== expectedToken)
    throw new LocalNoteConflict(
      "另一个窗口已有本机草稿，当前文字仍保留在编辑器。",
    );
  storage.setItem(entry.key, JSON.stringify(entry));
}
export function removeLocalNote(
  storage: DraftStorage,
  key: string,
  expectedToken: string | null,
): boolean {
  const current = readLocalNote(storage, key);
  if (current?.type !== "draft" || current.token !== expectedToken)
    return false;
  storage.removeItem(key);
  return true;
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import type { ResearchNote } from "@/lib/research/types";
import { errorText, patchJson, postJson, researchApi } from "../api";
import {
  editableNote,
  hasUnsavedNote,
  listLocalNotes,
  LocalNoteConflict,
  localNoteKey,
  noteVersionConflict,
  needsNoteLeaveProtection,
  noteTabSlot,
  readLocalNote,
  removeLocalNote,
  sameNoteContent,
  writeLocalNote,
  NOTE_DRAFT_PREFIX,
  type EditableNote,
  type LocalNoteDraft,
  type NoteDraftEntry,
  type PendingNoteCreate,
} from "./note-drafts";

type SaveOptions = {
  confirmed?: boolean;
  asNew?: boolean;
  beforeSave?(): Promise<boolean>;
  onSaved(note: ResearchNote): Promise<void>;
  notify(message: string, error?: boolean): void;
};
export function useNoteEditor(
  initial: EditableNote,
  latestNotes?: ResearchNote[],
) {
  const initialRef = useRef(initial);
  const seedRef = useRef(initial);
  const modelRef = useRef(initial);
  const baselineRef = useRef(initial);
  const keyRef = useRef(localNoteKey(initial));
  const tokenRef = useRef<string | null>(null);
  const pendingRef = useRef<PendingNoteCreate | undefined>(undefined);
  const lock = useRef(false);
  const epoch = useRef(0);
  const tabSlot = useRef<string | null>(null);
  const [model, setModel] = useState(initial);
  const [baseline, setBaseline] = useState(initial);
  const [ready, setReady] = useState(false);
  const [blocked, setBlocked] = useState(false);
  const [busy, setBusy] = useState(false);
  const [status, setStatus] = useState<
    "local" | "memory" | "unavailable" | "conflict"
  >("memory");
  const [error, setError] = useState("");
  const [server, setServer] = useState<EditableNote | null>(null);
  const [restored, setRestored] = useState(false);
  const [drafts, setDrafts] = useState<LocalNoteDraft[]>([]);
  const unsaved = hasUnsavedNote(model, baseline);
  const protectLeave = needsNoteLeaveProtection(unsaved, status, busy);

  const refreshDrafts = useCallback(() => {
    try {
      setDrafts(listLocalNotes(window.localStorage));
    } catch {
      setStatus("unavailable");
    }
  }, []);
  const persist = useCallback(
    (next: EditableNote, pending = pendingRef.current) => {
      const key = localNoteKey(next);
      const entry: LocalNoteDraft = {
        schema: 1,
        type: "draft",
        key,
        model: next,
        pendingCreate: pending,
        token: crypto.randomUUID(),
        updatedAt: new Date().toISOString(),
      };
      try {
        writeLocalNote(
          window.localStorage,
          entry,
          key === keyRef.current ? tokenRef.current : null,
        );
        const previousKey = keyRef.current;
        const previousToken = tokenRef.current;
        keyRef.current = key;
        tokenRef.current = entry.token;
        if (key !== previousKey) {
          const removed = removeLocalNote(
            window.localStorage,
            previousKey,
            previousToken,
          );
          if (removed && next.id && previousKey.includes(":new-"))
            window.localStorage.setItem(
              previousKey,
              JSON.stringify({
                schema: 1,
                type: "binding",
                key: previousKey,
                paperId: next.paperId,
                noteId: next.id,
              }),
            );
        }
        setStatus("local");
      } catch (cause) {
        setStatus(
          cause instanceof LocalNoteConflict ? "conflict" : "unavailable",
        );
      }
    },
    [],
  );
  const open = useCallback(
    async (seed: EditableNote, recovered?: LocalNoteDraft) => {
      if (lock.current) return;
      if (!tabSlot.current) {
        try {
          tabSlot.current = noteTabSlot(window.sessionStorage);
        } catch {
          tabSlot.current = crypto.randomUUID();
        }
      }
      seed = { ...seed, slot: seed.slot ?? tabSlot.current };
      const currentEpoch = ++epoch.current;
      seedRef.current = seed;
      setReady(false);
      setBlocked(false);
      setError("");
      setServer(null);
      setRestored(false);
      let nextSeed = seed;
      let key = localNoteKey(seed);
      let entry: NoteDraftEntry | null | undefined;
      try {
        entry = recovered ?? readLocalNote(window.localStorage, key);
        if (entry?.type === "binding") {
          // A generated draft already saved once must reopen that ID, never POST again.
          const result = await researchApi<{ note: ResearchNote }>(
            "/notes/" + entry.noteId,
          );
          if (currentEpoch !== epoch.current) return;
          if (result.note.paperId !== seed.paperId)
            throw new Error("本机草稿与已保存笔记的论文不匹配。");
          nextSeed = { ...editableNote(result.note), slot: seed.slot };
          key = localNoteKey(nextSeed);
          entry = readLocalNote(window.localStorage, key);
        }
        setStatus("memory");
      } catch (cause) {
        if (currentEpoch !== epoch.current) return;
        if (entry?.type === "binding") {
          setError(
            "已保存笔记暂时无法读取，请重试；不会另建重复笔记。 " +
              errorText(cause),
          );
          setBlocked(true);
        } else setStatus("unavailable");
      }
      if (currentEpoch !== epoch.current) return;
      const local = entry?.type === "draft" ? entry : undefined;
      if (local) key = local.key;
      const next = local?.model ?? nextSeed;
      keyRef.current = key;
      tokenRef.current = local?.token ?? null;
      pendingRef.current = local?.pendingCreate;
      modelRef.current = next;
      baselineRef.current = nextSeed;
      setModel(next);
      setBaseline(nextSeed);
      setRestored(!!local);
      if (
        local &&
        nextSeed.id &&
        nextSeed.version &&
        noteVersionConflict(next, {
          id: nextSeed.id,
          paperId: nextSeed.paperId,
          version: nextSeed.version,
        })
      )
        setServer(nextSeed);
      setReady(true);
      if (local) setStatus("local");
      else if (hasUnsavedNote(next, nextSeed) && entry?.type !== "binding")
        persist(next);
      refreshDrafts();
    },
    [persist, refreshDrafts],
  );
  useEffect(() => {
    let disposed = false;
    queueMicrotask(() => {
      if (!disposed) void open(initialRef.current);
    });
    return () => {
      disposed = true;
      epoch.current = -1;
    };
  }, [open]);
  useEffect(() => {
    const latestNote = latestNotes?.find((note) => note.id === model.id);
    if (!latestNote) return;
    if (noteVersionConflict(modelRef.current, latestNote))
      queueMicrotask(() => {
        if (noteVersionConflict(modelRef.current, latestNote))
          setServer(editableNote(latestNote));
      });
  }, [latestNotes, model.id]);
  useEffect(() => {
    const changed = (event: StorageEvent) => {
      if (event.key && !event.key.startsWith(NOTE_DRAFT_PREFIX)) return;
      refreshDrafts();
      if (
        (!event.key || event.key === keyRef.current) &&
        hasUnsavedNote(modelRef.current, baselineRef.current)
      )
        setStatus("conflict");
    };
    window.addEventListener("storage", changed);
    return () => window.removeEventListener("storage", changed);
  }, [refreshDrafts]);
  useEffect(() => {
    if (!protectLeave) return;
    const prevent = (event: BeforeUnloadEvent) => {
      event.preventDefault();
      event.returnValue = "";
    };
    window.addEventListener("beforeunload", prevent);
    return () => window.removeEventListener("beforeunload", prevent);
  }, [protectLeave]);

  function change(
    patch: Partial<Pick<EditableNote, "title" | "body" | "kind" | "paperId">>,
  ) {
    if (!ready || blocked || lock.current) return;
    if (
      patch.paperId &&
      patch.paperId !== modelRef.current.paperId &&
      pendingRef.current
    ) {
      setError("请先重试保存这份草稿，再更改关联论文。");
      return;
    }
    const next = { ...modelRef.current, ...patch };
    if (next.paperId !== modelRef.current.paperId && !next.id)
      next.origin = "manual-" + crypto.randomUUID();
    modelRef.current = next;
    setModel(next);
    setRestored(false);
    if (hasUnsavedNote(next, baselineRef.current) || pendingRef.current)
      persist(next);
    else {
      try {
        removeLocalNote(window.localStorage, keyRef.current, tokenRef.current);
        tokenRef.current = null;
        setStatus("memory");
      } catch {
        setStatus("unavailable");
      }
    }
  }
  function localCopy(asNew = false) {
    if (lock.current) return;
    const next = {
      ...modelRef.current,
      slot: crypto.randomUUID(),
      ...(asNew
        ? {
            id: undefined,
            version: undefined,
            confirmed: false,
            origin: "copy-" + crypto.randomUUID(),
          }
        : {}),
    };
    keyRef.current = localNoteKey(next);
    tokenRef.current = null;
    if (asNew) pendingRef.current = undefined;
    modelRef.current = next;
    if (asNew) baselineRef.current = next;
    setModel(next);
    if (asNew) {
      setBaseline(next);
      setServer(null);
    }
    setError("");
    persist(next);
    refreshDrafts();
  }
  function complete(note: ResearchNote) {
    const previousKey = keyRef.current;
    const next = {
      ...editableNote(note),
      slot: modelRef.current.slot ?? tabSlot.current ?? undefined,
    };
    try {
      const removed = removeLocalNote(
        window.localStorage,
        previousKey,
        tokenRef.current,
      );
      if (removed && previousKey.includes(":new-"))
        window.localStorage.setItem(
          previousKey,
          JSON.stringify({
            schema: 1,
            type: "binding",
            key: previousKey,
            paperId: note.paperId,
            noteId: note.id,
          }),
        );
    } catch {
      setStatus("unavailable");
    }
    modelRef.current = next;
    baselineRef.current = next;
    keyRef.current = localNoteKey(next);
    tokenRef.current = null;
    pendingRef.current = undefined;
    setModel(next);
    setBaseline(next);
    setServer(null);
    setError("");
    setRestored(false);
    refreshDrafts();
  }
  async function useCurrentVersion() {
    if (!server || lock.current) return;
    const copy = {
      ...modelRef.current,
      slot: crypto.randomUUID(),
    };
    const entry: LocalNoteDraft = {
      schema: 1,
      type: "draft",
      key: localNoteKey(copy),
      model: copy,
      token: crypto.randomUUID(),
      updatedAt: new Date().toISOString(),
    };
    try {
      writeLocalNote(window.localStorage, entry, null);
      removeLocalNote(window.localStorage, keyRef.current, tokenRef.current);
      await open(server);
    } catch {
      setError("无法保留本机草稿，请先复制文字或另存为新笔记。");
    }
  }
  async function save(options: SaveOptions): Promise<ResearchNote | null> {
    if (lock.current || !ready || blocked) return null;
    if (server && !options.asNew) {
      setError("笔记已有新版本。当前草稿已保留，请先核对或另存为新笔记。");
      return null;
    }
    if (options.asNew) localCopy(true);
    const snapshot = modelRef.current;
    if (!snapshot.title.trim() || !snapshot.body.trim() || !snapshot.paperId) {
      setError("请填写标题、正文，并关联一篇论文。");
      return null;
    }
    if (
      !hasUnsavedNote(snapshot, baselineRef.current) &&
      (!options.confirmed || snapshot.confirmed)
    )
      return null;
    lock.current = true;
    setBusy(true);
    setError("");
    try {
      if (options.beforeSave && !(await options.beforeSave())) return null;
      const confirmed = options.confirmed || snapshot.confirmed;
      const fields = (value: EditableNote, isConfirmed: boolean) => ({
        paperId: value.paperId,
        title: value.title.trim(),
        body: value.body,
        kind: value.kind,
        sources: value.sources,
        runId: value.runId,
        confirmed: isConfirmed,
        status: isConfirmed ? "confirmed" : "draft",
      });
      let note: ResearchNote;
      if (snapshot.id) {
        const latest = await researchApi<{ note: ResearchNote }>(
          "/notes/" + snapshot.id,
        );
        if (noteVersionConflict(snapshot, latest.note)) {
          setServer(editableNote(latest.note));
          throw new Error("笔记已有新版本，当前草稿已保留；未覆盖服务器内容。");
        }
        note = (
          await patchJson<{ note: ResearchNote }>("/notes/" + snapshot.id, {
            ...fields(snapshot, confirmed),
            version: snapshot.version,
          })
        ).note;
      } else {
        // Keep an exact POST snapshot across lost responses, edits, and reloads.
        // Replaying it obtains the same note ID before applying any later edits.
        const pending = pendingRef.current ?? {
          model: snapshot,
          actionId: crypto.randomUUID(),
          confirmed,
        };
        pendingRef.current = pending;
        persist(snapshot, pending);
        note = (
          await postJson<{ note: ResearchNote }>("/notes", {
            ...fields(pending.model, pending.confirmed),
            actionId: pending.actionId,
          })
        ).note;
        if (
          note.version !== 1 &&
          !sameNoteContent(editableNote(note), {
            ...pending.model,
            title: pending.model.title.trim(),
          })
        ) {
          const old = { ...snapshot, id: note.id, version: 1 };
          modelRef.current = old;
          setModel(old);
          pendingRef.current = undefined;
          persist(old);
          setServer(editableNote(note));
          throw new Error(
            "这份已创建的笔记又有更新；草稿已保留，请核对后另存。",
          );
        }
        if (
          !sameNoteContent(snapshot, pending.model) ||
          confirmed !== pending.confirmed
        ) {
          if (note.version !== 1) {
            const old = { ...snapshot, id: note.id, version: 1 };
            modelRef.current = old;
            setModel(old);
            pendingRef.current = undefined;
            persist(old);
            setServer(editableNote(note));
            throw new Error(
              "这份已创建的笔记又有更新；草稿已保留，请核对后另存。",
            );
          }
          note = (
            await patchJson<{ note: ResearchNote }>("/notes/" + note.id, {
              ...fields(snapshot, confirmed),
              version: note.version,
            })
          ).note;
        }
      }
      complete(note);
      try {
        await options.onSaved(note);
      } catch {
        options.notify("笔记已保存，列表暂未刷新，请稍后重新载入。", true);
        return note;
      }
      options.notify(
        options.confirmed
          ? "笔记已确认，已加入个人研究知识库。"
          : "笔记已保存。",
      );
      return note;
    } catch (cause) {
      setError(errorText(cause));
      return null;
    } finally {
      lock.current = false;
      setBusy(false);
    }
  }
  function discard(entry: LocalNoteDraft) {
    try {
      removeLocalNote(window.localStorage, entry.key, entry.token);
      refreshDrafts();
    } catch {
      setStatus("unavailable");
    }
  }
  return {
    model,
    ready,
    blocked,
    busy,
    unsaved,
    protectLeave,
    status,
    error,
    server,
    restored,
    drafts,
    change,
    open,
    save,
    localCopy,
    useCurrentVersion,
    discard,
    retry: () => void open(seedRef.current),
  };
}
