  connectionWarning,
  reviewSaving,
  onPrepare: prepareProposal,
  onPermission: permission,
  onReview: openRunReview,
  onNote: prepareNote,
  onComment: prepareComment,
  onExplain,
  onOpenSource,
  onUseSources,
}: {
  run: ResearchRun;
  paper: ResearchPaper;
  papers: ResearchPaper[];
  currentRevision: string;
  active: boolean;
  permissionPending: string;
  connectionWarning: string;
  reviewSaving: boolean;
  onPrepare(proposal: ResearchProposal): void;
  onPermission(id: string, decision: "allow_once" | "deny_once"): Promise<void>;
  onReview(run: ResearchRun): Promise<void>;
  onNote(
    body: string,
    title: string,
    sources?: SourceRef[],
    run?: ResearchRun,
    origin?: string,
  ): void;
  onComment(text: string): void;
  onExplain(
    request: LearningRequest,
    selection?: ResearchSelection,
  ): Promise<boolean>;
  onOpenSource(source: SourceRef): void;
  onUseSources(): void;
}) {
  const answerRoot = useRef<HTMLDivElement>(null);
  const [excerpt, setExcerpt] = useState<{
    runId: string;
    text: string;
  } | null>(null);
  const selectedAnswer = excerpt?.runId === run.id ? excerpt.text : "";
  function saveDiscussion(answer = run.answer, excerptOnly = false) {
    const draft = discussionNote(run, paper, answer);
    prepareNote(
      draft.body,
      paper.title.slice(0, 24) + " · 阅读讨论",
      draft.sources,
      run,
      excerptOnly ? excerptNoteOrigin(run.id, answer) : undefined,
    );
  }
  const sources = run.answer
    ? responseSources(run.answer, {
        ...paper,
        contentRevision: run.contentRevision ?? paper.contentRevision,
      })
    : [];
  return (
    <>
      {run && (
        <div className={styles.analysisResult}>
          <ReaderRunOverview
            key={run.id}
            run={run}
            paper={paper}
            papers={papers}
            onOpenSource={onOpenSource}
            onUseSources={onUseSources}
          />
          <div className={styles.resultIdentity}>
            <span className={styles.assistantAvatar}>
              <Sparkles size={15} />
            </span>
            <strong>阅读助手</strong>
            <span
              className={
                isRunActive(run) ? styles.runningTag : styles.mutedSmall
              }
            >
              {isRunActive(run) && (
                <LoaderCircle size={11} className={styles.spin} />
              )}
              {runLabels[run.status]}
            </span>
          </div>
          {(run.permissions ?? []).map((request) => (
            <div className={styles.permissionCard} key={request.toolUseId}>
              <strong>
                <ShieldCheck size={16} />
                需要你的确认
              </strong>
              <p>{request.toolName}</p>
              <pre>{JSON.stringify(request.args, null, 2)}</pre>
              <span>允许生成草稿不等于已写入 PDF。</span>
              <div className={styles.actionRow}>
                <button
                  className={styles.primaryButton}
                  disabled={permissionPending === request.toolUseId}
                  onClick={() =>
                    void permission(request.toolUseId, "allow_once")
                  }
                >
                  允许本次
                </button>
                <button
                  className={styles.secondaryButton}
                  disabled={permissionPending === request.toolUseId}
                  onClick={() =>
                    void permission(request.toolUseId, "deny_once")
                  }
                >
                  拒绝
                </button>
              </div>
            </div>
          ))}
          <ProposalCards
            run={run}
            paper={paper}
            currentRevision={currentRevision}
            onPrepare={prepareProposal}
          />
          {run.learning?.task === "quiz" ? (
            <p className={styles.mutedSmall}>
              {isRunActive(run)
                ? "正在依据所选材料准备题目…"
                : run.status === "completed"
                  ? "题目已就绪，进入复习后逐题作答。"
                  : "本次出题未完成，可重新生成。"}
            </p>
          ) : run.answer ? (
            <div
              className={styles.answerBody}
              ref={answerRoot}
              onPointerUpCapture={() => {
                const selected = window.getSelection();
                const text = selected?.toString().trim() ?? "";
                setExcerpt(
                  text &&
                    text.length <= 20000 &&
                    selected?.anchorNode &&
                    selected?.focusNode &&
                    answerRoot.current?.contains(selected.anchorNode) &&
                    answerRoot.current?.contains(selected.focusNode)
                    ? { runId: run.id, text }
                    : null,
                );
              }}
            >
              <StudyMarkdown content={run.answer} highlightCode={!active} />
            </div>
          ) : (
            <div className={styles.thinking}>
              <LoaderCircle size={17} className={styles.spin} />
              <span>
                {isRunActive(run)
                  ? "正在阅读原文、整理依据…"
                  : run.error || "这次任务没有生成回答。"}
              </span>
            </div>
          )}
          {run.error && <div className={styles.inlineError}>{run.error}</div>}
          {connectionWarning && (
            <div className={styles.softInfo}>{connectionWarning}</div>
          )}
          {!!sources.length && (
            <div className={styles.answerSources}>
              <span>回答中提到的原文页</span>
              <SourceChips sources={sources} onOpen={onOpenSource} />
            </div>
          )}
          {run.status === "completed" &&
            run.selection &&
            (run.learning?.task === "explain" ||
              run.learning?.task === "understanding") && (
              <ExplanationActions
                active={active}
                onRequest={(request) => onExplain(request, run.selection)}
              />
            )}
          {run.answer && !isRunActive(run) && (
            <div className={styles.resultActions}>
              {selectedAnswer && (
                <button
                  className={styles.primaryButton}
                  onClick={() => saveDiscussion(selectedAnswer, true)}
                >
                  <NotebookPen size={14} />
                  保存选中的回答
                </button>
              )}
              {run.status === "completed" &&
                parseReviewMarkdown(run.answer).length > 0 && (
                  <button
                    className={styles.primaryButton}
                    disabled={reviewSaving}
                    onClick={() => void openRunReview(run)}
                  >
                    {reviewSaving ? "正在准备…" : "开始逐题复习"}
                  </button>
                )}
              <button
                className={styles.secondaryButton}
                onClick={() =>
                  run.mode === "ask" &&
                  run.learning?.task !== "quiz" &&
                  run.learning?.task !== "notes"
                    ? saveDiscussion()
                    : prepareNote(
                        run.answer,
                        paper.title.slice(0, 24) +
                          (run.learning
                            ? " · " + learningTitle(run.learning)
                            : studyLabel(run.question)
                              ? " · " + studyLabel(run.question)
                              : run.mode === "card"
                                ? " · 论文卡"
                                : " · 阅读笔记"),
                        undefined,
                        run,
                      )
                }
              >
                <NotebookPen size={14} />
                编辑为笔记
              </button>
              <button
                className={styles.textButton}
                onClick={() => prepareComment(run.answer)}
              >
                <MessageSquare size={14} />
                写入 PDF 评论
              </button>
            </div>
          )}
        </div>
      )}
    </>
  );
}

import type { ReactNode, RefObject } from "react";
import { BookOpen, Send, Square, X } from "lucide-react";
import type { ResearchSelection } from "@/lib/research/types";
import styles from "../styles";
import local from "./question.module.css";

export function ReaderQuestionComposer({
  selection,
  question,
  inputRef,
  active,
  sources,
  status,
  available,
  controls,
  onQuestion,
  onClearSelection,
  onSend,
  onStop,
  onFocus,
}: {
  selection: ResearchSelection | null;
  question: string;
  inputRef: RefObject<HTMLTextAreaElement | null>;
  active: boolean;
  sources: number;
  status: string;
  available: boolean;
  controls?: ReactNode;
  onQuestion(value: string): void;
  onClearSelection(): void;
  onSend(): void;
  onStop(): void;
  onFocus?(): void;
}) {
  return (
    <div className={styles.aiComposer}>
      {controls}
      <div className={local.scope} aria-label="本次提问范围">
        <BookOpen size={12} />
        <strong>
          {selection ? `选文 · 第 ${selection.page} 页` : `${sources} 篇论文`}
        </strong>
        {selection && (
          <>
            <span title={selection.text ?? selection.quote}>
              {(selection.text ?? selection.quote ?? "").slice(0, 45)}
            </span>
            <button onClick={onClearSelection} aria-label="移除选文上下文">
              <X size={12} />
            </button>
          </>
        )}
      </div>
      <textarea
        ref={inputRef}
        aria-label="向阅读助手提问"
        placeholder={selection ? "针对这段选文提问…" : "向论文提问…"}
        value={question}
        onFocus={onFocus}
        onPointerDownCapture={onFocus}
        onChange={(event) => onQuestion(event.target.value)}
        rows={3}
        maxLength={30000}
        onKeyDown={(event) => {
          if (
            event.key === "Enter" &&
            !event.shiftKey &&
            !event.nativeEvent.isComposing
          ) {
            event.preventDefault();
            onSend();
          }
        }}
      />
      <div>
        <span>Enter 发送 · Shift + Enter 换行</span>
        {active ? (
          <button className={styles.stopButton} onClick={onStop}>
            <Square size={11} />
            停止
          </button>
        ) : (
          <button
            className={styles.sendButton}
            disabled={!question.trim()}
            onClick={onSend}
            aria-label="发送问题"
          >
            <Send size={16} />
          </button>
        )}
      </div>
      {status && (
        <small
          className={available ? local.status : local.warning}
          role="status"
        >
          {status}
        </small>
      )}
    </div>
  );
}

"use client";

import type { AnswerStyle, KnowledgeEntry } from "@/lib/research/types";
import { pickReferenceConcepts } from "@/lib/research/discussion/concepts";
import { ChevronDown, X } from "lucide-react";
import { useEffect, useRef } from "react";
import styles from "./discussion.module.css";

export function DiscussionControls({
  answerStyle,
  knowledge,
  query,
  referenceConceptIds,
  onStyle,
  onConcepts,
}: {
  answerStyle: AnswerStyle;
  knowledge: KnowledgeEntry[];
  query: string;
  referenceConceptIds?: string[];
  onStyle(style: AnswerStyle): void;
  onConcepts(ids: string[] | undefined): void;
}) {
  const menu = useRef<HTMLDetailsElement>(null);
  useEffect(() => {
    const close = (event: PointerEvent) => {
      if (
        event.target instanceof Node &&
        menu.current &&
        !menu.current.contains(event.target)
      )
        menu.current.open = false;
    };
    document.addEventListener("pointerdown", close);
    return () => document.removeEventListener("pointerdown", close);
  }, []);
  const chosen = pickReferenceConcepts(knowledge, query, referenceConceptIds);
  const ids = chosen.map((entry) => entry.id);
  return (
    <div className={styles.controls}>
      <div className={styles.row}>
        <strong title="可以结合模型知识讨论、解释和举例；论文引用仍需原文依据。">
          {answerStyle === "discussion" ? "自由讨论" : "原文核对"}
        </strong>
        <details
          hidden={answerStyle === "grounded"}
          ref={menu}
          className={styles.concepts}
          onKeyDown={(event) => {
            if (event.key === "Escape" && menu.current) {
              event.preventDefault();
              menu.current.open = false;
              menu.current.querySelector("summary")?.focus();
            }
          }}
        >
          <summary aria-label="选择参考概念">
            概念{chosen.length ? ` ${chosen.length}` : ""}
            <ChevronDown size={11} />
          </summary>
          <div className={styles.options}>
            <div className={styles.optionTools}>
              <button
                type="button"
                aria-pressed={referenceConceptIds === undefined}
                onClick={() => onConcepts(undefined)}
              >
                自动匹配
              </button>
              <button
                type="button"
                aria-pressed={referenceConceptIds?.length === 0}
                onClick={() => onConcepts([])}
              >
                不参考
              </button>
            </div>
            {knowledge.map((entry) => (
              <label key={entry.id}>
                <input
                  type="checkbox"
                  checked={ids.includes(entry.id)}
                  disabled={!ids.includes(entry.id) && ids.length >= 4}
                  onChange={(event) =>
                    onConcepts(
                      event.target.checked
                        ? [...ids, entry.id]
                        : ids.filter((id) => id !== entry.id),
                    )
                  }
                />
                <span>{entry.title}</span>
              </label>
            ))}
            {!knowledge.length && <p>概念库暂无条目。</p>}
            <small>最多参考 4 个概念</small>
          </div>
        </details>
        <label
          className={styles.strict}
          title="开启后，仅依据所选论文和笔记回答。"
        >
          <input
            type="checkbox"
            checked={answerStyle === "grounded"}
            onChange={(event) =>
              onStyle(event.target.checked ? "grounded" : "discussion")
            }
          />
          仅依据原文
        </label>
      </div>
      {answerStyle === "discussion" && !!chosen.length && (
        <div className={styles.chips} aria-label="本次参考概念">
          {chosen.map((entry) => (
            <span key={entry.id}>
              {entry.title}
              <button
                type="button"
                aria-label={`移除参考概念 ${entry.title}`}
                onClick={() => onConcepts(ids.filter((id) => id !== entry.id))}
              >
                <X size={10} />
              </button>
            </span>
          ))}
        </div>
      )}
    </div>
  );
}

import type {
  ResearchPaper,
  ResearchRun,
  SourceRef,
} from "@/lib/research/types";
import { responseSources } from "../../reader-context";
import { runContextMetadata } from "../run-context";

export function discussionNote(
  run: ResearchRun,
  paper: ResearchPaper,
  answer = run.answer,
) {
  const metadata = runContextMetadata(run);
  const quote = run.selection?.quote || run.selection?.text;
  const sources: SourceRef[] = responseSources(answer, {
    ...paper,
    contentRevision: run.contentRevision ?? paper.contentRevision,
  });
  if (quote && run.selection)
    sources.unshift({
      paperId: paper.id,
      page: run.selection.page,
      quote,
      contentRevision: run.contentRevision ?? run.selection.contentRevision,
      title: paper.title,
    });
  const body = [
    quote
      ? `## 原文\n\n${quote
          .split(/\r?\n/)
          .map((line) => "> " + line)
          .join(
            "\n",
          )}\n\n[返回原文第 ${run.selection?.page} 页](/workspace?paperId=${paper.id}&page=${run.selection?.page})`
      : "",
    `## 问题\n\n${metadata.question}`,
    `## ${run.answerStyle === "discussion" ? "阅读讨论" : "回答"}\n\n${answer}`,
    "## 我的思考\n\n",
  ]
    .filter(Boolean)
    .join("\n\n");
  return {
    body,
    sources: sources.filter(
      (source, index) =>
        sources.findIndex(
          (entry) =>
            entry.paperId === source.paperId && entry.page === source.page,
        ) === index,
    ),
  };
}

import type {
  AnswerStyle,
  ResearchPaper,
  ResearchRun,
  ResearchSelection,
} from "@/lib/research/types";

function passageText(selection: ResearchSelection): string {
  return (selection.quote?.trim() || selection.text || "")
    .normalize("NFKC")
    .replace(/\s+/g, "");
}

/** Restore only a completed discussion bound to this exact passage and source version. */
export function findPassageDiscussion(
  history: ResearchRun[],
  paper: ResearchPaper,
  selection: ResearchSelection | null,
  answerStyle: AnswerStyle,
  referenceConceptIds?: string[],
): ResearchRun | null {
  if (
    !selection ||
    (selection.contentRevision &&
      selection.contentRevision !== paper.contentRevision)
  )
    return null;
  const quote = passageText(selection);
  if (!quote) return null;
  const concepts = referenceConceptIds
    ? JSON.stringify([...referenceConceptIds].sort())
    : undefined;
  let latest: ResearchRun | null = null;
  let latestTime = Number.NEGATIVE_INFINITY;
  for (const entry of history) {
    if (
      entry.paperId !== paper.id ||
      !entry.contentRevision ||
      entry.contentRevision !== paper.contentRevision ||
      !entry.selection ||
      (entry.selection.contentRevision &&
        entry.selection.contentRevision !== paper.contentRevision) ||
      entry.selection.page !== selection.page ||
      passageText(entry.selection) !== quote ||
      entry.mode !== "ask" ||
      entry.status !== "completed" ||
      (entry.learning && entry.learning.task !== "explain") ||
      (entry.answerStyle ?? "grounded") !== answerStyle ||
      (concepts !== undefined &&
        JSON.stringify([...(entry.referenceConceptIds ?? [])].sort()) !==
          concepts)
    )
      continue;
    const timestamp = Date.parse(entry.createdAt);
    if (Number.isFinite(timestamp) && timestamp > latestTime) {
      latest = entry;
      latestTime = timestamp;
    }
  }
  return latest;
}

import { z } from "zod";
import { idSchema, runSchema } from "@/lib/research/schemas";
import type { AnswerStyle, ResearchSelection } from "@/lib/research/types";

export interface QuestionInput {
  question: string;
  selection: ResearchSelection | null;
  sourcePaperIds: string[];
  answerStyle?: AnswerStyle;
  referenceConceptIds?: string[];
}
const storedQuestion = z.object({
  schema: z.literal(1),
  paperId: idSchema,
  contentRevision: z.string(),
  question: z.string().max(30000),
  selection: runSchema.shape.selection.nullable(),
  sourcePaperIds: z.array(idSchema).max(4),
  answerStyle: z.enum(["discussion", "grounded"]).optional(),
  referenceConceptIds: z.array(idSchema).max(4).optional(),
});
export function questionDraftKey(paperId: string) {
  return "jiaoyan:question-draft:v1:" + paperId;
}
export function questionSignature(input: QuestionInput): string {
  const selected = input.selection;
  return JSON.stringify({
    question: input.question,
    sources: [...input.sourcePaperIds].sort(),
    answerStyle: input.answerStyle ?? "discussion",
    concepts: input.referenceConceptIds
      ? [...input.referenceConceptIds].sort()
      : "auto",
    selection: selected
      ? {
          page: selected.page,
          text: selected.text,
          quote: selected.quote,
          revision: selected.contentRevision,
        }
      : null,
  });
}
export function readQuestionDraft(
  raw: string | null,
  paperId: string,
  contentRevision: string,
): { input: QuestionInput; sourceChanged: boolean } | null {
  if (!raw) return null;
  let value: unknown;
  try {
    value = JSON.parse(raw);
  } catch {
    return null;
  }
  const parsed = storedQuestion.safeParse(value);
  if (
    !parsed.success ||
    parsed.data.paperId !== paperId ||
    !parsed.data.question.trim()
  )
    return null;
  const record = parsed.data;
  const sourceChanged =
    !!record.selection &&
    (record.contentRevision !== contentRevision ||
      record.selection.contentRevision !== contentRevision);
  return {
    input: {
      question: record.question,
      selection: sourceChanged ? null : (record.selection ?? null),
      sourcePaperIds: record.sourcePaperIds,
      ...(record.answerStyle ? { answerStyle: record.answerStyle } : {}),
      ...(record.referenceConceptIds
        ? { referenceConceptIds: record.referenceConceptIds }
        : {}),
    },
    sourceChanged,
  };
}
export function writeQuestionDraft(
  storage: Pick<Storage, "setItem" | "removeItem">,
  paperId: string,
  contentRevision: string,
  input: QuestionInput,
) {
  const key = questionDraftKey(paperId);
  if (!input.question.trim()) storage.removeItem(key);
  else
    storage.setItem(
      key,
      JSON.stringify({ schema: 1, paperId, contentRevision, ...input }),
    );
}

import { learningTitle } from "@/lib/research/learning-types";
import type { ResearchPaper, ResearchRun } from "@/lib/research/types";
import { studyLabel, studyPurpose } from "../study/frameworks";

type SavedScope = { policy?: string; sources?: string[] };

function savedScope(value?: string): SavedScope {
  if (!value) return {};
  try {
    const parsed: unknown = JSON.parse(value);
    if (!parsed || typeof parsed !== "object") return {};
    const record = parsed as Record<string, unknown>;
    return {
      policy: typeof record.policy === "string" ? record.policy : undefined,
      sources:
        Array.isArray(record.sources) &&
        record.sources.every((id) => typeof id === "string" && !!id)
          ? (record.sources as string[])
          : undefined,
    };
  } catch {
    return {};
  }
}

function visibleQuestion(run: ResearchRun) {
  if (run.learning) return learningTitle(run.learning);
  const purpose = studyPurpose(run.question);
  if (purpose) return purpose + " · " + studyLabel(run.question);
  if (/^\s*\[学习讲解\]/.test(run.question)) return "解释选文";
  if (/^\s*\[理解反馈\]/.test(run.question)) return "检查我的理解";
  return run.question;
}

function suppliedSourceIds(run: ResearchRun): string[] | undefined {
  return Array.isArray(run.sourcePaperIds) ? run.sourcePaperIds : undefined;
}

function recordedSourceIds(run: ResearchRun): string[] {
  const supplied = suppliedSourceIds(run);
  return [
    ...new Set(supplied?.filter((id) => typeof id === "string" && !!id) ?? []),
  ];
}

function hasKnownScopePolicy(scope: SavedScope): boolean {
  return [
    "explicit-source-scope-v4",
    "explicit-source-scope-v5",
    "explicit-source-scope-v6",
  ].includes(scope.policy ?? "");
}

function sourcesAreComplete(
  run: ResearchRun,
  scope: SavedScope,
  recordedIds: string[],
): boolean {
  if (!hasKnownScopePolicy(scope)) return false;
  const scopedIds = scope.sources ?? [];
  const supplied = suppliedSourceIds(run);
  if (!scopedIds.length || new Set(scopedIds).size !== scopedIds.length)
    return false;
  if (!supplied?.length || supplied.length !== recordedIds.length) return false;
  if (!recordedIds.includes(run.paperId)) return false;
  if (scopedIds.length !== recordedIds.length) return false;
  return scopedIds.every((id) => recordedIds.includes(id));
}

function availablePapers(
  run: ResearchRun,
  paper?: ResearchPaper,
  papers: ResearchPaper[] = [],
): Map<string, ResearchPaper> {
  return new Map(
    [...papers, ...(paper?.id === run.paperId ? [paper] : [])]
      .filter((item) => !item.trashedAt)
      .map((item) => [item.id, item]),
  );
}

function savedSelectionPage(run: ResearchRun): number | undefined {
  const page = run.selection?.page;
  return page && Number.isInteger(page) && page > 0 ? page : undefined;
}

function versionMatchesCurrent(
  run: ResearchRun,
  current: ResearchPaper | undefined,
  revision: string | undefined,
): boolean {
  return (
    !!current &&
    !!revision &&
    revision === current.contentRevision &&
    (!run.selection?.contentRevision ||
      run.selection.contentRevision === current.contentRevision)
  );
}

function sourceScopeLabel(
  run: ResearchRun,
  selected: boolean,
  selectionPage: number | undefined,
  materialKind: string | undefined,
  legacyRangeMissing: boolean,
): string {
  if (selected) {
    return selectionPage ? `选文 · 第${selectionPage}页` : "选文 · 页码未保存";
  }
  if (materialKind === "note") return "已保存笔记";
  if (materialKind === "annotations") {
    const ids =
      run.learning?.source.kind === "annotations"
        ? run.learning.source.ids
        : [];
    return `所选批注 · ${new Set(ids).size}条`;
  }
  if (legacyRangeMissing) return "范围未完整保存";
  return run.answerStyle === "discussion" ? "按问题查阅原文" : "整篇论文";
}

type SourceState = {
  sourceComplete: boolean;
  sources: Array<{ paper?: ResearchPaper }>;
  revision: string | undefined;
  versionMatches: boolean;
  selected: boolean;
  selectionPage: number | undefined;
  quote: string;
  current: ResearchPaper | undefined;
  legacyRangeMissing: boolean;
  materialKind: string | undefined;
};

function selectionIsIncomplete(state: SourceState): boolean {
  if (!state.selected) return false;
  if (!state.selectionPage || !state.quote) return true;
  return state.selectionPage > (state.current?.pageCount ?? 0);
}

function sourceRecordProblem(state: SourceState): string {
  if (!state.sourceComplete) return "来源记录不完整，请重新选择提问材料。";
  if (state.sources.some((source) => !source.paper))
    return "部分来源已不可用，请检查文献库或回收站。";
  if (!state.revision) return "这条记录未保存原文版本，请重新选择来源。";
  if (!state.versionMatches) return "原文已有更新，请重新选择来源。";
  return "";
}

function sourceBlockReason(state: SourceState): string {
  const recordProblem = sourceRecordProblem(state);
  if (recordProblem) return recordProblem;
  if (selectionIsIncomplete(state))
    return "这条记录未保存完整选文，请重新选择原文。";
  if (state.legacyRangeMissing) return "旧记录未保存选文范围，请重新选择来源。";
  if (state.materialKind === "note" || state.materialKind === "annotations")
    return "请在论文中核对笔记或批注版本后重新选择来源。";
  if (state.sources.length > 4) return "请重新选择最多4篇论文作为提问来源。";
  const unreadySource = state.sources.some(
    (source) => source.paper?.textStatus !== "ready",
  );
  if (unreadySource && !state.selected)
    return "部分来源正文暂不可用，请先检查论文解析结果。";
  return "";
}

function sourceNotice(
  state: SourceState & { sourceComplete: boolean },
): string {
  if (state.current && state.revision && !state.versionMatches)
    return "显示当时的提问快照；原文已有更新。";
  if (state.selected && (!state.selectionPage || !state.quote))
    return "这条旧记录未保存完整选文，无法还原当时的范围。";
  if (state.legacyRangeMissing)
    return "这条旧记录未保存选文范围，无法确认当时是否使用了选文。";
  if (!state.sourceComplete) return "这条记录的来源信息不完整。";
  return "";
}

function selectionQuote(run: ResearchRun): string {
  return (run.selection?.quote || run.selection?.text || "").trim();
}

function selectionPresent(run: ResearchRun): boolean {
  return !!run.selection || run.learning?.source.kind === "selection";
}

function legacyRangeMissing(run: ResearchRun, scope: SavedScope): boolean {
  if (run.learning || run.selection) return false;
  return !["explicit-source-scope-v5", "explicit-source-scope-v6"].includes(
    scope.policy ?? "",
  );
}

function learningReflection(run: ResearchRun): string | undefined {
  return run.learning?.task === "understanding"
    ? run.learning.reflection
    : undefined;
}

function sourceEntries(
  available: Map<string, ResearchPaper>,
  sourceIds: string[],
  currentId: string,
) {
  return sourceIds.map((id) => ({
    id,
    paper: available.get(id),
    title:
      available.get(id)?.title ??
      (id === currentId ? "本篇论文（暂不可用）" : "来源文献暂不可用"),
  }));
}

function selectionIsOpenable(
  current: ResearchPaper | undefined,
  selectionPage: number | undefined,
): boolean {
  if (!current || !selectionPage) return false;
  return selectionPage <= current.pageCount;
}

/** Describe the saved submission; never substitute the reader's live selection. */
export function runContextMetadata(
  run: ResearchRun,
  paper?: ResearchPaper,
  papers: ResearchPaper[] = [],
) {
  const scope = savedScope(run.contextScope);
  const recordedIds = recordedSourceIds(run);
  const sourceComplete = sourcesAreComplete(run, scope, recordedIds);
  const sourceIds = [...new Set([run.paperId, ...recordedIds])];
  const available = availablePapers(run, paper, papers);
  const current = available.get(run.paperId);
  const revision = run.contentRevision ?? run.selection?.contentRevision;
  const selectionPage = savedSelectionPage(run);
  const quote = selectionQuote(run);
  const selected = selectionPresent(run);
  const legacyMissing = legacyRangeMissing(run, scope);
  const materialKind = run.learning?.source.kind;
  const versionMatches = versionMatchesCurrent(run, current, revision);
  const sources = sourceEntries(available, sourceIds, run.paperId);
  const state: SourceState = {
    sourceComplete,
    sources,
    revision,
    versionMatches,
    selected,
    selectionPage,
    quote,
    current,
    legacyRangeMissing: legacyMissing,
    materialKind,
  };
  const cannotUseReason = sourceBlockReason(state);

  return {
    question: visibleQuestion(run),
    reflection: learningReflection(run),
    scopeLabel: sourceScopeLabel(
      run,
      selected,
      selectionPage,
      materialKind,
      legacyMissing,
    ),
    sources,
    hasRecordedSources: recordedIds.length > 0,
    sourceComplete,
    selectionPage,
    quote,
    revision,
    versionMatches,
    notice: sourceNotice(state),
    canUseSources: !cannotUseReason,
    cannotUseReason,
    canOpenSelection: selectionIsOpenable(current, selectionPage),
  };
}

"use client";
import { useCallback, useEffect, useRef, useState } from "react";
import type {
  AnswerStyle,
  ResearchPaper,
  ResearchSelection,
} from "@/lib/research/types";
import {
  questionDraftKey,
  questionSignature,
  readQuestionDraft,
  writeQuestionDraft,
  type QuestionInput,
} from "./question-draft";

export function useQuestionDraft(
  paper: ResearchPaper,
  papers: ResearchPaper[],
) {
  const [input, setInput] = useState<QuestionInput>({
    question: "",
    selection: null,
    sourcePaperIds: [paper.id],
    answerStyle: "discussion",
  });
  const current = useRef(input);
  const initialized = useRef(false);
  const touched = useRef(false);
  const [available, setAvailable] = useState(true);
  const [status, setStatus] = useState("");
  const allowed = papers
    .map((entry) => entry.id)
    .sort()
    .join(",");
  const clean = useCallback(
    (value: QuestionInput): QuestionInput => ({
      ...value,
      sourcePaperIds: [
        paper.id,
        ...new Set(
          value.sourcePaperIds.filter(
            (id) => id !== paper.id && allowed.split(",").includes(id),
          ),
        ),
      ].slice(0, 4),
    }),
    [paper.id, allowed],
  );
  const update = useCallback(
    (value: QuestionInput) => {
      touched.current = true;
      const next = clean(value);
      current.current = next;
      setInput(next);
      try {
        writeQuestionDraft(
          window.localStorage,
          paper.id,
          paper.contentRevision,
          next,
        );
        setAvailable(true);
        setStatus(next.question.trim() ? "已暂存本机" : "");
      } catch {
        setAvailable(false);
        setStatus(next.question.trim() ? "问题尚未暂存" : "");
      }
    },
    [clean, paper.id, paper.contentRevision],
  );
  useEffect(() => {
    let disposed = false;
    queueMicrotask(() => {
      if (disposed) return;
      if (initialized.current) {
        const live = current.current;
        if (
          live.selection?.contentRevision &&
          live.selection.contentRevision !== paper.contentRevision
        ) {
          update({ ...live, selection: null });
          setStatus("原文已更新，请重新选择；问题草稿已保留。");
        }
        return;
      }
      initialized.current = true;
      if (touched.current) return;
      try {
        const restored = readQuestionDraft(
          window.localStorage.getItem(questionDraftKey(paper.id)),
          paper.id,
          paper.contentRevision,
        );
        if (!restored) return;
        const next = clean(restored.input);
        current.current = next;
        setInput(next);
        setStatus(
          restored.sourceChanged
            ? "原文已更新，请重新选择；问题草稿已恢复。"
            : "已恢复本机问题草稿",
        );
      } catch {
        setAvailable(false);
        setStatus("浏览器无法暂存问题草稿");
      }
    });
    return () => {
      disposed = true;
    };
  }, [clean, paper.id, paper.contentRevision, update]);
  const setQuestion = useCallback(
    (question: string) => {
      update({ ...current.current, question });
    },
    [update],
  );
  const setSelection = useCallback(
    (selection: ResearchSelection | null) => {
      if (current.current.selection === selection) return;
      const previous = current.current.selection;
      const samePassage =
        previous?.page === selection?.page &&
        (previous?.text ?? previous?.quote) ===
          (selection?.text ?? selection?.quote) &&
        previous?.contentRevision === selection?.contentRevision;
      update({
        ...current.current,
        selection,
        referenceConceptIds: samePassage
          ? current.current.referenceConceptIds
          : undefined,
      });
    },
    [update],
  );
  const setAnswerStyle = useCallback(
    (answerStyle: AnswerStyle) => {
      update({
        ...current.current,
        answerStyle,
        referenceConceptIds: answerStyle === "grounded" ? [] : undefined,
      });
    },
    [update],
  );
  const setReferenceConceptIds = useCallback(
    (referenceConceptIds: string[] | undefined) => {
      update({ ...current.current, referenceConceptIds });
    },
    [update],
  );
  const setSourcePaperIds = useCallback(
    (sourcePaperIds: string[]) => {
      update({ ...current.current, sourcePaperIds });
    },
    [update],
  );
  const capture = useCallback(
    () => ({
      ...current.current,
      sourcePaperIds: [...current.current.sourcePaperIds],
      referenceConceptIds: current.current.referenceConceptIds
        ? [...current.current.referenceConceptIds]
        : undefined,
    }),
    [],
  );
  const clearAccepted = useCallback(
    (submitted: QuestionInput) => {
      if (questionSignature(current.current) === questionSignature(submitted))
        setQuestion("");
    },
    [setQuestion],
  );
  return {
    ...input,
    setQuestion,
    setSelection,
    setSourcePaperIds,
    setAnswerStyle,
    setReferenceConceptIds,
    capture,
    clearAccepted,
    status,
    available,
  };
}

import type {
  ResearchPaper,
  ResearchRun,
  ResearchSelection,
  SourceRef,
} from "@/lib/research/types";
import type { PaperDetail } from "./api";
import { workspaceCitationTarget } from "./study/workspace-links";
import { selectionBoundaryMessage } from "./selection-boundary";

export interface ResearchProposal {
  id: string;
  kind: "note" | "annotation";
  title: string;
  body: string;
  quote: string;
  page?: number;
  document_id: string;
  run_id: string;
  requires_confirmation: true;
}

/** Tool output is untrusted: accept only drafts bound to this paper and run. */
export function readerProposals(
  run: ResearchRun,
  paper: ResearchPaper,
): ResearchProposal[] {
  const seen = new Set<string>();
  return (run.proposals ?? []).flatMap((value): ResearchProposal[] => {
    if (!value || typeof value !== "object" || Array.isArray(value)) return [];
    const item = value as Record<string, unknown>;
    if (
      typeof item.id !== "string" ||
      !/^[A-Za-z0-9_-]{1,100}$/.test(item.id) ||
      seen.has(item.id) ||
      (item.kind !== "note" && item.kind !== "annotation") ||
      typeof item.title !== "string" ||
      !item.title.trim() ||
      item.title.length > 500 ||
      typeof item.body !== "string" ||
      !item.body.trim() ||
      item.body.length > 60000 ||
      typeof item.quote !== "string" ||
      item.quote.length > 20000 ||
      item.document_id !== paper.id ||
      item.run_id !== run.id ||
      item.requires_confirmation !== true
    )
      return [];
    if (
      item.page != null &&
      (typeof item.page !== "number" ||
        !Number.isInteger(item.page) ||
        item.page < 1 ||
        item.page > paper.pageCount)
    )
      return [];
    seen.add(item.id);
    return [
      {
        id: item.id,
        kind: item.kind,
        title: item.title,
        body: item.body,
        quote: item.quote,
        page: typeof item.page === "number" ? item.page : undefined,
        document_id: paper.id,
        run_id: run.id,
        requires_confirmation: true,
      },
    ];
  });
}

/** Keep current-paper page markers alongside explicit cross-paper citations. */
export function responseSources(
  answer: string,
  paper: ResearchPaper,
): SourceRef[] {
  const sources: SourceRef[] = [];
  const prose = answer.replace(
    /\[([^\]]+)\]\(([^\s()]+)\)/g,
    (_link, title: string, target: string) => {
      const citation = workspaceCitationTarget(target);
      const paperId = citation?.paperId;
      const page = citation?.page;
      if (
        paperId &&
        page !== undefined &&
        Number.isInteger(page) &&
        page > 0 &&
        (paperId !== paper.id || page <= paper.pageCount)
      )
        sources.push({
          paperId,
          page,
          title,
          contentRevision:
            paperId === paper.id ? paper.contentRevision : undefined,
        });
      // A link label such as [p.2] belongs to its target, never implicitly to
      // the current paper. Remove it before collecting unlinked page markers.
      return "";
    },
  );
  for (const match of prose.matchAll(
    /第\s*(\d+)\s*页|\[p\.?\s*(\d+)\]|\(p\.?\s*(\d+)\)/gi,
  )) {
    const page = Number(match[1] || match[2] || match[3]);
    if (page >= 1 && page <= paper.pageCount)
      sources.push({
        paperId: paper.id,
        page,
        contentRevision: paper.contentRevision,
        title: paper.title,
      });
  }
  const seen = new Set<string>();
  return sources
    .filter((source) => {
      const key = source.paperId + ":" + source.page;
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    })
    .slice(0, 16);
}

/** Map the PDF.js text layer back to PDF coordinates, including rotated pages. */
export function readPdfSelection(
  root: HTMLElement,
  detail: PaperDetail | null,
  paper: ResearchPaper,
  onInvalid?: (message: string) => void,
): ResearchSelection | null {
  const selected = window.getSelection();
  if (!selected || selected.isCollapsed || !selected.rangeCount) return null;
  const range = selected.getRangeAt(0);
  const startInside = root.contains(range.startContainer);
  const endInside = root.contains(range.endContainer);
  if (!startInside && !endInside) return null;
  if (!startInside || !endInside || selected.rangeCount !== 1) {
    onInvalid?.("请在同一页内选取文字");
    return null;
  }
  const startElement =
    range.startContainer instanceof Element
      ? range.startContainer
      : range.startContainer.parentElement;
  const endElement =
    range.endContainer instanceof Element
      ? range.endContainer
      : range.endContainer.parentElement;
  const pageElement =
    startElement?.closest<HTMLElement>(".page[data-page-number]") ?? null;
  const endPage =
    endElement?.closest<HTMLElement>(".page[data-page-number]") ?? null;
  const text = selected.toString().trim();
  if (!text) return null;
  const boundary = {
    startPage: pageElement,
    endPage,
    startTextLayer: startElement?.closest(".textLayer") ?? null,
    endTextLayer: endElement?.closest(".textLayer") ?? null,
    text,
  };
  const invalid = selectionBoundaryMessage(boundary);
  if (invalid) {
    onInvalid?.(invalid);
    return null;
  }
  if (!pageElement) return null;
  const page = Number(pageElement.dataset.pageNumber);
  if (!Number.isInteger(page) || page < 1 || page > paper.pageCount)
    return null;
  const box = pageElement.getBoundingClientRect();
  const metadata = detail?.pages.find((item) => item.page === page);
  const width = metadata?.width ?? 595.28,
    height = metadata?.height ?? 841.89;
  const rotation = Number(pageElement.dataset.mainRotation ?? 0);
  const point = (x: number, y: number): [number, number] => {
    const u = Math.max(0, Math.min(1, (x - box.left) / box.width));
    const v = Math.max(0, Math.min(1, (y - box.top) / box.height));
    if (rotation === 90) return [v * width, u * height];
    if (rotation === 180) return [(1 - u) * width, v * height];
    if (rotation === 270) return [(1 - v) * width, (1 - u) * height];
    return [u * width, (1 - v) * height];
  };
  const rects = [...range.getClientRects()]
    .filter(
      (rect) =>
        rect.width > 1 &&
        rect.height > 1 &&
        rect.top >= box.top - 1 &&
        rect.bottom <= box.bottom + 1,
    )
    .map((rect) => {
      const a = point(rect.left, rect.top),
        b = point(rect.right, rect.bottom);
      return [
        Math.min(a[0], b[0]),
        Math.min(a[1], b[1]),
        Math.max(a[0], b[0]),
        Math.max(a[1], b[1]),
      ];
    });
  const invalidRects = selectionBoundaryMessage({
    ...boundary,
    rectCount: rects.length,
  });
  if (invalidRects) {
    onInvalid?.(invalidRects);
    return null;
  }
  return {
    page,
    text,
    quote: text,
    rects,
    pdfEtag: detail?.paper.pdfEtag ?? paper.pdfEtag,
    contentRevision: detail?.paper.contentRevision ?? paper.contentRevision,
  };
}

"use client";

import { Check } from "lucide-react";
import { useState } from "react";
import { Modal } from "../ResearchUi";
import styles from "../styles";
import commentStyles from "../annotations/comment.module.css";

export function ReaderCommentDialog({
  pageCount,
  page,
  text,
  quote,
  proposal,
  saving,
  onPage,
  onText,
  onClose,
  onSave,
}: {
  pageCount: number;
  page: number;
  text: string;
  quote?: string;
  proposal: boolean;
  saving: boolean;
  onPage(page: number): void;
  onText(text: string): void;
  onClose(): void;
  onSave(): void;
}) {
  const [discardPending, setDiscardPending] = useState(false);
  function close() {
    if (saving) return;
    if (text.trim()) {
      setDiscardPending((current) => !current);
      return;
    }
    onClose();
  }
  return (
    <Modal title="写想法" onClose={close}>
      <div
        className={styles.modalBody}
        onKeyDown={(event) => {
          if (
            (event.ctrlKey || event.metaKey) &&
            event.key === "Enter" &&
            !event.nativeEvent.isComposing &&
            !saving &&
            text.trim()
          ) {
            event.preventDefault();
            onSave();
          }
        }}
      >
        {discardPending && (
          <div
            className={commentStyles.discard}
            role="alertdialog"
            aria-label="放弃未保存的想法"
          >
            <p>想法尚未保存。</p>
            <button type="button" onClick={() => setDiscardPending(false)}>
              继续编辑
            </button>
            <button type="button" onClick={onClose}>
              放弃修改
            </button>
          </div>
        )}
        <div className={commentStyles.location}>
          <span>
            第 {page} 页{quote ? " · 已关联选文" : ""}
          </span>
          {!quote && (
            <details>
              <summary>更改页码</summary>
              <label className={styles.formLabel}>
                页码
                <select
                  aria-label="评论页码"
                  value={page}
                  onChange={(event) => onPage(Number(event.target.value))}
                  disabled={saving}
                >
                  {Array.from(
                    { length: Math.max(1, pageCount) },
                    (_, index) => (
                      <option value={index + 1} key={index}>
                        {index + 1}页
                      </option>
                    ),
                  )}
                </select>
              </label>
            </details>
          )}
        </div>
        {quote && (
          <div className={styles.evidenceQuote + " " + commentStyles.quote}>
            <p>{quote}</p>
          </div>
        )}
        {proposal && <span className={commentStyles.hint}>关联到当前页</span>}
        <label className={styles.formLabel}>
          我的想法
          <textarea
            autoFocus
            aria-label="评论内容"
            rows={5}
            value={text}
            onChange={(event) => onText(event.target.value)}
            maxLength={10000}
            disabled={saving}
            placeholder="写下想法或疑问…"
          />
        </label>
      </div>
      <div className={styles.modalFooter}>
        <span className={commentStyles.shortcut}>Ctrl / ⌘ + Enter 保存</span>
        <button
          className={styles.secondaryButton}
          onClick={close}
          disabled={saving}
        >
          取消
        </button>
        <button
          className={styles.primaryButton}
          disabled={saving || !text.trim()}
          onClick={onSave}
        >
          <Check size={15} />
          {saving ? "保存中…" : "保存想法"}
        </button>
      </div>
    </Modal>
  );
}

"use client";

import { ArrowLeft, Info } from "lucide-react";
import { useEffect, useRef } from "react";
import type { ResearchPaper } from "@/lib/research/types";
import styles from "./reader-title.module.css";

export function ReaderTitle({
  paper,
  onBack,
}: {
  paper: ResearchPaper;
  onBack(): void;
}) {
  const details = useRef<HTMLDetailsElement>(null);
  useEffect(() => {
    const closeOutside = (event: PointerEvent) => {
      if (
        event.target instanceof Node &&
        !details.current?.contains(event.target) &&
        details.current
      )
        details.current.open = false;
    };
    document.addEventListener("pointerdown", closeOutside);
    return () => document.removeEventListener("pointerdown", closeOutside);
  }, []);
  return (
    <div className={styles.titlebar}>
      <button
        type="button"
        className={styles.back}
        aria-label="返回文献库"
        title="返回文献库"
        onClick={onBack}
      >
        <ArrowLeft size={17} />
      </button>
      <h1 title={paper.title}>{paper.title}</h1>
      <details
        ref={details}
        className={styles.information}
        onKeyDown={(event) => {
          if (event.key === "Escape" && details.current) {
            details.current.open = false;
            event.preventDefault();
          }
        }}
      >
        <summary aria-label="查看论文信息" title="论文信息">
          <Info size={16} />
        </summary>
        <section className={styles.card} aria-label="论文信息">
          <h2>{paper.title}</h2>
          <dl>
            <div>
              <dt>作者</dt>
              <dd>{paper.authors || "待补充"}</dd>
            </div>
            <div>
              <dt>年份</dt>
              <dd>{paper.year || "待补充"}</dd>
            </div>
            <div>
              <dt>页数</dt>
              <dd>{paper.pageCount || "待解析"}</dd>
            </div>
            <div>
              <dt>主题</dt>
              <dd>{paper.topic || "未分类"}</dd>
            </div>
          </dl>
        </section>
      </details>
    </div>
  );
}

"use client";

import {
  Children,
  useEffect,
  useRef,
  useState,
  type KeyboardEvent,
  type PointerEvent,
  type ReactNode,
} from "react";
import { GripHorizontal, GripVertical, RotateCcw } from "lucide-react";
import {
  clampReaderPercent,
  DEFAULT_READER_LAYOUT,
  dragReaderPercent,
  keyReaderPercent,
  readReaderLayout,
  readerPercentBounds,
  saveReaderLayout,
  type ReaderLayoutAxis,
} from "./layout-preferences";
import styles from "./reader-layout.module.css";

export function ResizableReader({
  children,
  className = "",
}: {
  children: ReactNode;
  className?: string;
}) {
  const [pdf, assistant] = Children.toArray(children);
  const root = useRef<HTMLDivElement>(null);
  const drag = useRef<{
    pointer: number;
    axis: ReaderLayoutAxis;
    start: number;
    percent: number;
  } | null>(null);
  const [preferences, setPreferences] = useState({ ...DEFAULT_READER_LAYOUT });
  const [geometry, setGeometry] = useState({
    width: 0,
    height: 0,
    axis: "columns" as ReaderLayoutAxis,
  });
  const [ready, setReady] = useState(false);
  const [dragging, setDragging] = useState(false);
  const width = clampReaderPercent(
    preferences.widthPercent,
    readerPercentBounds("columns", geometry.width),
  );
  const height = clampReaderPercent(
    preferences.heightPercent,
    readerPercentBounds("rows", geometry.height),
  );
  const axis = geometry.axis;
  const percent = axis === "columns" ? width : height;
  const bounds = readerPercentBounds(
    axis,
    axis === "columns" ? geometry.width : geometry.height,
  );

  useEffect(() => {
    let initialized = false;
    const measure = () => {
      const box = root.current?.getBoundingClientRect();
      if (!box) return;
      if (!initialized) {
        initialized = true;
        try {
          setPreferences(readReaderLayout(window.localStorage));
        } catch {
          /* Private browsing can deny storage access. */
        }
        setReady(true);
      }
      const nextAxis: ReaderLayoutAxis = window.matchMedia("(max-width: 750px)")
        .matches
        ? "rows"
        : "columns";
      setGeometry((current) =>
        current.width === box.width &&
        current.height === box.height &&
        current.axis === nextAxis
          ? current
          : { width: box.width, height: box.height, axis: nextAxis },
      );
    };
    const observer =
      typeof ResizeObserver === "undefined"
        ? null
        : new ResizeObserver(measure);
    if (root.current) observer?.observe(root.current);
    window.addEventListener("resize", measure);
    const frame = requestAnimationFrame(measure);
    return () => {
      cancelAnimationFrame(frame);
      observer?.disconnect();
      window.removeEventListener("resize", measure);
    };
  }, []);
  useEffect(() => {
    if (!ready || dragging) return;
    try {
      saveReaderLayout(window.localStorage, preferences);
    } catch {
      /* Resizing still works without persistence. */
    }
  }, [preferences, ready, dragging]);

  function change(nextAxis: ReaderLayoutAxis, value: number) {
    const box = root.current?.getBoundingClientRect();
    const total = nextAxis === "columns" ? box?.width : box?.height;
    const next = clampReaderPercent(
      value,
      readerPercentBounds(nextAxis, total ?? 0),
    );
    setPreferences((current) =>
      nextAxis === "columns"
        ? { ...current, widthPercent: next }
        : { ...current, heightPercent: next },
    );
  }
  function endDrag(event: PointerEvent<HTMLDivElement>) {
    if (drag.current?.pointer !== event.pointerId) return;
    drag.current = null;
    setDragging(false);
    if (event.currentTarget.hasPointerCapture(event.pointerId))
      event.currentTarget.releasePointerCapture(event.pointerId);
  }
  function startDrag(event: PointerEvent<HTMLDivElement>) {
    if (event.button !== 0) return;
    event.preventDefault();
    event.currentTarget.focus();
    drag.current = {
      pointer: event.pointerId,
      axis,
      start: axis === "columns" ? event.clientX : event.clientY,
      percent,
    };
    setDragging(true);
    event.currentTarget.setPointerCapture(event.pointerId);
  }
  function moveDrag(event: PointerEvent<HTMLDivElement>) {
    const active = drag.current;
    if (!active || active.pointer !== event.pointerId) return;
    if (active.axis !== axis) {
      endDrag(event);
      return;
    }
    const box = root.current?.getBoundingClientRect();
    if (!box) return;
    event.preventDefault();
    const total = axis === "columns" ? box.width : box.height;
    const position = axis === "columns" ? event.clientX : event.clientY;
    change(
      axis,
      dragReaderPercent(
        active.percent,
        position - active.start,
        total,
        readerPercentBounds(axis, total),
      ),
    );
  }
  function onKey(event: KeyboardEvent<HTMLDivElement>) {
    const next = keyReaderPercent(
      axis,
      event.key,
      percent,
      bounds,
      event.shiftKey,
    );
    if (next === null) return;
    event.preventDefault();
    change(axis, next);
  }
  function reset() {
    setPreferences({ ...DEFAULT_READER_LAYOUT });
  }
  return (
    <div
      ref={root}
      className={`${className} ${styles.layout}`}
      data-reader-split="true"
      data-pdf-width={width}
      data-pdf-height={height}
      data-dragging={dragging ? "true" : undefined}
    >
      {pdf}
      <div className={styles.rail}>
        <div
          className={styles.separator}
          role="separator"
          tabIndex={0}
          aria-label={
            axis === "columns"
              ? "调整 PDF 与阅读助手宽度"
              : "调整 PDF 与阅读助手高度"
          }
          aria-orientation={axis === "columns" ? "vertical" : "horizontal"}
          aria-valuemin={bounds.min}
          aria-valuemax={bounds.max}
          aria-valuenow={percent}
          aria-valuetext={`PDF 区域 ${percent}%`}
          title="拖动调整；方向键微调，Home / End 调至边界；双击恢复默认"
          onPointerDown={startDrag}
          onPointerMove={moveDrag}
          onPointerUp={endDrag}
          onPointerCancel={endDrag}
          onLostPointerCapture={endDrag}
          onKeyDown={onKey}
          onDoubleClick={reset}
        >
          <GripVertical
            className={styles.columnGrip}
            size={18}
            aria-hidden="true"
          />
          <GripHorizontal
            className={styles.rowGrip}
            size={20}
            aria-hidden="true"
          />
        </div>
        <button
          className={styles.resetButton}
          type="button"
          aria-label="恢复默认阅读布局"
          title="恢复默认阅读布局"
          onClick={reset}
        >
          <RotateCcw size={14} />
        </button>
      </div>
      {assistant}
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import {
  ArrowRight,
  BookOpen,
  Check,
  Eye,
  FilePenLine,
  Pause,
  RotateCcw,
} from "lucide-react";
import type {
  ReviewDeck,
  ReviewQuestion,
  ReviewRating,
} from "@/lib/research/review/types";
import type { SourceRef } from "@/lib/research/types";
import { Markdown } from "@/components/chat/Markdown";
import { SourceChips } from "../ResearchUi";
import { normalizeWorkspaceCitationHref } from "../study/workspace-links";
import shared from "../styles";
import styles from "./review.module.css";
import { ReviewQuestionEditor } from "./ReviewQuestionEditor";
import { useReviewMutation } from "./use-review-mutation";
import {
  currentReviewQuestion,
  firstReviewQuestionId,
  nextReviewQuestionId,
  parseReviewDraft,
  reviewCounts,
  reviewDraftKey,
} from "./review-session";

type QuestionActions = {
  saveResponse(response: string): Promise<boolean>;
  rate(
    response: string,
    rating: ReviewRating,
    actionId: string,
  ): Promise<boolean>;
  next(response: string): Promise<boolean>;
};

function QuestionBody({
  deckId,
  question,
  busy,
  nextLabel,
  onEdit,
  onPause,
  actions,
  onOpenSource,
}: {
  deckId: string;
  question: ReviewQuestion;
  busy: boolean;
  nextLabel: string;
  onEdit(): void;
  onPause(): void;
  actions: QuestionActions;
  onOpenSource(source: SourceRef): void;
}) {
  const [response, setResponse] = useState(question.response);
  const [revealed, setRevealed] = useState(false);
  const [ratedThisVisit, setRatedThisVisit] = useState(false);
  const [localDraft, setLocalDraft] = useState(false);
  const [storageAvailable, setStorageAvailable] = useState(true);
  const pendingAction = useRef({ signature: "", id: "" });
  const key = reviewDraftKey(deckId, question.id);
  useEffect(() => {
    let disposed = false;
    queueMicrotask(() => {
      try {
        const draft = parseReviewDraft(
          window.localStorage.getItem(key),
          question.question,
          question.answer,
        );
        if (!disposed && draft !== null) {
          setResponse(draft);
          setLocalDraft(true);
        }
      } catch {
        if (!disposed) setStorageAvailable(false);
      }
    });
    return () => {
      disposed = true;
    };
  }, [key, question.question, question.answer]);

  function changeResponse(value: string) {
    setResponse(value);
    setRatedThisVisit(false);
    try {
      window.localStorage.setItem(
        key,
        JSON.stringify({
          question: question.question,
          answer: question.answer,
          response: value,
        }),
      );
      setLocalDraft(true);
    } catch {
      setStorageAvailable(false);
    }
  }
  function savedResponse(value: string) {
    try {
      const draft = parseReviewDraft(
        window.localStorage.getItem(key),
        question.question,
        question.answer,
      );
      if (draft === value) window.localStorage.removeItem(key);
      setLocalDraft(false);
    } catch {
      /* A server-saved response is safe even when local storage is restricted. */
    }
  }
  async function reveal() {
    if (await actions.saveResponse(response)) {
      savedResponse(response);
      setRevealed(true);
    }
  }
  async function rate(rating: ReviewRating) {
    const signature = JSON.stringify([question.id, response, rating]);
    if (signature !== pendingAction.current.signature)
      pendingAction.current = { signature, id: crypto.randomUUID() };
    if (await actions.rate(response, rating, pendingAction.current.id)) {
      savedResponse(response);
      setRatedThisVisit(true);
    }
  }
  async function next() {
    if (await actions.next(response)) savedResponse(response);
  }

  return (
    <>
      <div className={styles.questionToolbar}>
        <span>
          {question.reviewedAt
            ? `上次自评：${question.rating === "good" ? "会了" : "还不会"}`
            : "尚未自评"}
        </span>
        <div>
          <button
            type="button"
            className={shared.textButton}
            onClick={onEdit}
            disabled={busy}
          >
            <FilePenLine size={14} />
            编辑题目
          </button>
          <button
            type="button"
            className={shared.textButton}
            onClick={onPause}
            disabled={busy}
          >
            <Pause size={14} />
            暂停此题
          </button>
        </div>
      </div>
      <h2 className={styles.questionTitle}>{question.question}</h2>
      <label className={styles.responseLabel}>
        我的回答
        <textarea
          value={response}
          onChange={(event) => changeResponse(event.target.value)}
          maxLength={20000}
          disabled={busy}
          placeholder="写下你的理解，也可以先在心中作答。"
          aria-label="我的自测回答"
        />
      </label>
      <div className={styles.responseStatus} aria-live="polite">
        {busy
          ? "正在保存…"
          : localDraft
            ? "回答已暂存于当前浏览器"
            : response
              ? "回答已保存"
              : "参考答案默认隐藏"}
        {!storageAvailable && !busy && (
          <span>浏览器无法暂存，请先查看答案以保存回答。</span>
        )}
      </div>
      {!revealed ? (
        <div className={styles.questionActions}>
          <button
            className={shared.primaryButton}
            onClick={() => void reveal()}
            disabled={busy}
          >
            <Eye size={15} />
            查看参考答案
          </button>
          <button
            className={shared.textButton}
            onClick={() => void next()}
            disabled={busy}
          >
            {question.reviewedAt ? nextLabel : "暂时跳过"}
            <ArrowRight size={14} />
          </button>
        </div>
      ) : (
        <>
          <section className={styles.answer} aria-label="参考答案">
            <div className={styles.answerHeading}>
              <strong>参考答案</strong>
              <span>对照原文，自行判断掌握程度</span>
            </div>
            <Markdown
              content={question.answer}
              highlightCode={false}
              resolveLinkHref={normalizeWorkspaceCitationHref}
            />
            {question.sources.length > 0 && (
              <div className={styles.answerSources}>
                <BookOpen size={13} aria-hidden="true" />
                <SourceChips sources={question.sources} onOpen={onOpenSource} />
              </div>
            )}
          </section>
          <div className={styles.ratingBar}>
            <span>
              {ratedThisVisit && question.dueAt ? (
                <>
                  下次复习：
                  <time dateTime={question.dueAt}>
                    {new Intl.DateTimeFormat("zh-CN", {
                      month: "short",
                      day: "numeric",
                      hour: "2-digit",
                      minute: "2-digit",
                    }).format(new Date(question.dueAt))}
                  </time>
                </>
              ) : ratedThisVisit ? (
                "自评已记录"
              ) : (
                "这道题掌握了吗？"
              )}
            </span>
            <div>
              <button
                className={shared.secondaryButton}
                disabled={busy}
                onClick={() => void rate("again")}
                aria-pressed={ratedThisVisit && question.rating === "again"}
              >
                <RotateCcw size={15} />
                还不会
              </button>
              <button
                className={shared.secondaryButton}
                disabled={busy}
                onClick={() => void rate("good")}
                aria-pressed={ratedThisVisit && question.rating === "good"}
              >
                <Check size={15} />
                会了
              </button>
              <button
                className={shared.primaryButton}
                disabled={busy || !ratedThisVisit}
                onClick={() => void next()}
              >
                {nextLabel}
                <ArrowRight size={15} />
              </button>
            </div>
          </div>
        </>
      )}
    </>
  );
}

export function ReviewPlayer({
  deck,
  onUpdate,
  onOpenSource,
}: {
  deck: ReviewDeck;
  onUpdate(deck: ReviewDeck): void;
  onOpenSource(source: SourceRef): void;
}) {
  const mutation = useReviewMutation(deck, onUpdate);
  const [editing, setEditing] = useState(false);
  const counts = reviewCounts(deck);
  const question = currentReviewQuestion(deck);
  const index = question
    ? deck.questions
        .filter((item) => !item.excluded)
        .findIndex((item) => item.id === question.id) + 1
    : 0;
  const nextId = question ? nextReviewQuestionId(deck, question.id) : null;
  const excluded = deck.questions.filter((item) => item.excluded);

  async function begin(onlyMissed: boolean) {
    await mutation.mutate("session", {
      currentQuestionId: firstReviewQuestionId(deck, onlyMissed),
      onlyMissed,
    });
  }
  async function pause() {
    if (question)
      await mutation.mutate("question", {
        questionId: question.id,
        excluded: true,
      });
  }
  const actions: QuestionActions = {
    saveResponse: async (response) =>
      !!question &&
      !!(await mutation.mutate("response", {
        questionId: question.id,
        response,
      })),
    rate: async (response, rating, actionId) =>
      !!question &&
      !!(await mutation.mutate("attempt", {
        questionId: question.id,
        response,
        rating,
        actionId,
      })),
    next: async (response) => {
      if (!question) return false;
      const saved = await mutation.mutate("response", {
        questionId: question.id,
        response,
      });
      if (!saved) return false;
      return !!(await mutation.mutate("session", {
        currentQuestionId: nextReviewQuestionId(saved, question.id),
        onlyMissed: saved.session.onlyMissed,
      }));
    },
  };

  return (
    <section
      className={styles.player}
      aria-label="逐题复习"
      data-review-deck={deck.id}
    >
      <header className={styles.playerHeading}>
        <div>
          <span className={styles.overline}>
            {deck.session.onlyMissed ? "未掌握题目" : "论文自测"}
          </span>
          <h2>{deck.title}</h2>
        </div>
        <span className={styles.total}>{counts.total} 题</span>
      </header>
      <div className={styles.progressRow}>
        <span>
          已掌握 {counts.good} / {counts.total}
        </span>
        <progress
          value={counts.good}
          max={Math.max(counts.total, 1)}
          aria-label="已掌握题目比例"
        />
      </div>
      {deck.stale && (
        <p className={styles.warning}>
          来源已有更新。这组题目保留了原内容，请核对原文后再复习或重新出题。
        </p>
      )}
      {mutation.error && (
        <div className={styles.error} role="alert">
          <span>{mutation.error} 当前回答仍保留在浏览器。</span>
          <button
            className={shared.textButton}
            onClick={() => void mutation.reload()}
            disabled={mutation.busy}
          >
            重新载入
          </button>
        </div>
      )}
      {question ? (
        <>
          <div className={styles.questionPosition} aria-live="polite">
            题目 {index} / {counts.total}
          </div>
          <QuestionBody
            key={question.id + question.question + question.answer}
            deckId={deck.id}
            question={question}
            busy={mutation.busy}
            nextLabel={nextId ? "下一题" : "完成本轮"}
            actions={actions}
            onEdit={() => setEditing(true)}
            onPause={() => void pause()}
            onOpenSource={onOpenSource}
          />
        </>
      ) : (
        <div className={styles.finished}>
          <Check size={32} aria-hidden="true" />
          <h3>{counts.total ? "本轮复习已完成" : "暂时没有可练习的题目"}</h3>
          <p>
            会了 {counts.good} 题 · 还不会 {counts.again} 题 · 未作答{" "}
            {counts.unanswered} 题
          </p>
          <div className={styles.questionActions}>
            <button
              className={shared.primaryButton}
              disabled={mutation.busy || counts.good === counts.total}
              onClick={() => void begin(true)}
            >
              重练未掌握
              <RotateCcw size={15} />
            </button>
            <button
              className={shared.secondaryButton}
              disabled={mutation.busy || !counts.total}
              onClick={() => void begin(false)}
            >
              全部再练一遍
            </button>
          </div>
        </div>
      )}
      {excluded.length > 0 && (
        <details className={styles.paused}>
          <summary>已暂停 {excluded.length} 题</summary>
          <ul>
            {excluded.map((item) => (
              <li key={item.id}>
                <span>{item.question}</span>
                <button
                  className={shared.textButton}
                  disabled={mutation.busy}
                  onClick={() =>
                    void mutation.mutate("question", {
                      questionId: item.id,
                      excluded: false,
                    })
                  }
                >
                  恢复题目
                </button>
              </li>
            ))}
          </ul>
        </details>
      )}
      {editing && question && (
        <ReviewQuestionEditor
          question={question}
          busy={mutation.busy}
          error={mutation.error}
          onClose={() => setEditing(false)}
          onSave={async (input) => {
            const saved = await mutation.mutate("question", {
              questionId: question.id,
              ...input,
            });
            if (saved) setEditing(false);
            return !!saved;
          }}
        />
      )}
    </section>
  );
}

"use client";

import { useState } from "react";
import type { ReviewQuestion } from "@/lib/research/review/types";
import { Modal } from "../ResearchUi";
import shared from "../styles";
import styles from "./review.module.css";

export function ReviewQuestionEditor({
  question,
  busy,
  error,
  onSave,
  onClose,
}: {
  question: ReviewQuestion;
  busy: boolean;
  error: string;
  onSave(input: { question: string; answer: string }): Promise<boolean>;
  onClose(): void;
}) {
  const [prompt, setPrompt] = useState(question.question);
  const [answer, setAnswer] = useState(question.answer);
  return (
    <Modal title="编辑自测题" onClose={() => !busy && onClose()} wide>
      <form
        onSubmit={(event) => {
          event.preventDefault();
          void onSave({ question: prompt.trim(), answer: answer.trim() });
        }}
      >
        <div className={shared.modalBody}>
          <label className={shared.formLabel}>
            题目
            <textarea
              className={styles.editQuestion}
              value={prompt}
              onChange={(event) => setPrompt(event.target.value)}
              maxLength={3000}
              required
              disabled={busy}
            />
          </label>
          <label className={shared.formLabel}>
            参考答案
            <textarea
              className={styles.editAnswer}
              value={answer}
              onChange={(event) => setAnswer(event.target.value)}
              maxLength={20000}
              required
              disabled={busy}
            />
          </label>
          <p className={styles.hint}>修改后需重新自评，原作答记录会保留。</p>
          {error && (
            <p className={styles.error} role="alert">
              {error}
            </p>
          )}
        </div>
        <div className={shared.modalFooter}>
          <button
            type="button"
            className={shared.secondaryButton}
            onClick={onClose}
            disabled={busy}
          >
            取消
          </button>
          <button
            type="submit"
            className={shared.primaryButton}
            disabled={busy || !prompt.trim() || !answer.trim()}
          >
            {busy ? "保存中…" : "保存题目"}
          </button>
        </div>
      </form>
    </Modal>
  );
}

"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import {
  ArrowRight,
  BookOpen,
  ListFilter,
  RefreshCw,
  RotateCcw,
} from "lucide-react";
import type {
  ResearchNote,
  ResearchPaper,
  SourceRef,
} from "@/lib/research/types";
import type { ReviewDeck } from "@/lib/research/review/types";
import { errorText, patchJson, researchApi } from "../api";
import { EmptyState, Loading } from "../ResearchUi";
import shared from "../styles";
import styles from "./review.module.css";
import { ReviewPlayer } from "./ReviewPlayer";
import { firstReviewQuestionId, reviewCounts } from "./review-session";

export interface ReviewWorkspaceProps {
  papers: ResearchPaper[];
  notes?: ResearchNote[];
  initialDeckId?: string;
  initialPaperId?: string;
  initialNoteId?: string;
  onOpenSource(source: SourceRef): void;
  onOpenPaper(paperId: string): void;
  onRefresh?(): Promise<void>;
  notify(message: string, error?: boolean): void;
}

export function ReviewWorkspace({
  papers,
  notes = [],
  initialDeckId,
  initialPaperId,
  initialNoteId,
  onOpenSource,
  onOpenPaper,
  notify,
}: ReviewWorkspaceProps) {
  const [decks, setDecks] = useState<ReviewDeck[]>([]);
  const [activeId, setActiveId] = useState(initialDeckId ?? "");
  const [paperFilter, setPaperFilter] = useState(initialPaperId ?? "all");
  const [noteFilter, setNoteFilter] = useState(initialNoteId ?? "all");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [refreshId, setRefreshId] = useState(0);
  const [opening, setOpening] = useState("");
  const openLock = useRef(false);
  const [catalogOpen, setCatalogOpen] = useState(false);

  useEffect(() => {
    queueMicrotask(() => {
      if (initialDeckId) setActiveId(initialDeckId);
      if (initialPaperId) setPaperFilter(initialPaperId);
      if (initialNoteId) setNoteFilter(initialNoteId);
    });
  }, [initialDeckId, initialPaperId, initialNoteId]);

  useEffect(() => {
    const controller = new AbortController();
    queueMicrotask(() => {
      if (controller.signal.aborted) return;
      setLoading(true);
      setError("");
    });
    void researchApi<{ decks: ReviewDeck[] }>("/review", {
      signal: controller.signal,
    })
      .then((result) => {
        if (!controller.signal.aborted) setDecks(result.decks);
      })
      .catch((cause: unknown) => {
        if (!controller.signal.aborted) setError(errorText(cause));
      })
      .finally(() => {
        if (!controller.signal.aborted) setLoading(false);
      });
    return () => controller.abort();
  }, [initialDeckId, initialPaperId, initialNoteId, refreshId]);

  const activePapers = useMemo(
    () =>
      new Map(
        papers
          .filter((paper) => !paper.trashedAt)
          .map((paper) => [paper.id, paper]),
      ),
    [papers],
  );
  const available = decks.filter(
    (deck) =>
      activePapers.has(deck.paperId) &&
      deck.questions.every((question) =>
        question.sources.every(
          (source) => !source.paperId || activePapers.has(source.paperId),
        ),
      ),
  );
  const visible = available.filter(
    (deck) =>
      (paperFilter === "all" || deck.paperId === paperFilter) &&
      (noteFilter === "all" || deck.noteId === noteFilter),
  );
  const active = visible.find((deck) => deck.id === activeId) ?? visible[0];
  const noteSources = [
    ...new Map(
      available
        .filter(
          (deck) =>
            deck.noteId &&
            (paperFilter === "all" || deck.paperId === paperFilter),
        )
        .map((deck) => [
          deck.noteId!,
          notes.find((note) => note.id === deck.noteId)?.title ?? deck.title,
        ]),
    ).entries(),
  ];

  function updateDeck(deck: ReviewDeck) {
    setDecks((current) =>
      current.map((item) => (item.id === deck.id ? deck : item)),
    );
  }
  async function openMissed(deck: ReviewDeck) {
    if (openLock.current) return;
    openLock.current = true;
    setOpening(deck.id);
    try {
      const result = await patchJson<{ deck: ReviewDeck }>(
        `/review/${deck.id}/session`,
        {
          currentQuestionId: firstReviewQuestionId(deck, true),
          onlyMissed: true,
          version: deck.version,
        },
      );
      updateDeck(result.deck);
      setActiveId(deck.id);
      setCatalogOpen(false);
    } catch (cause) {
      notify(errorText(cause), true);
      setRefreshId((value) => value + 1);
    } finally {
      openLock.current = false;
      setOpening("");
    }
  }

  return (
    <div className={styles.page} data-review-workspace>
      <header className={styles.pageHeading}>
        <h1>学习复习</h1>
        <div>
          {visible.length > 0 && (
            <button
              className={`${shared.secondaryButton} ${styles.catalogToggle}`}
              onClick={() => setCatalogOpen((value) => !value)}
              aria-expanded={catalogOpen}
            >
              <ListFilter size={15} />
              {catalogOpen ? "当前复习" : "选择复习集"}
            </button>
          )}
          <button
            className={shared.textButton}
            onClick={() => setRefreshId((value) => value + 1)}
            disabled={loading || !!opening}
            aria-label="刷新复习集"
          >
            <RefreshCw size={15} />
            刷新
          </button>
        </div>
      </header>
      <div className={styles.filters}>
        <label>
          <span>论文</span>
          <select
            value={paperFilter}
            onChange={(event) => {
              setPaperFilter(event.target.value);
              setNoteFilter("all");
            }}
            aria-label="筛选复习论文"
          >
            <option value="all">全部论文</option>
            {papers.map((paper) => (
              <option key={paper.id} value={paper.id}>
                {paper.title}
              </option>
            ))}
          </select>
        </label>
        {noteSources.length > 0 && (
          <label>
            <span>笔记</span>
            <select
              value={noteFilter}
              onChange={(event) => setNoteFilter(event.target.value)}
              aria-label="筛选复习笔记"
            >
              <option value="all">全部来源</option>
              {noteSources.map(([id, title]) => (
                <option key={id} value={id}>
                  {title}
                </option>
              ))}
            </select>
          </label>
        )}
        <span className={styles.collectionCount} aria-live="polite">
          {loading ? "正在读取…" : visible.length + " 组复习集"}
        </span>
      </div>
      {error && (
        <div className={styles.error} role="alert">
          <span>{error}</span>
          <button
            className={shared.textButton}
            onClick={() => setRefreshId((value) => value + 1)}
          >
            重新载入
          </button>
        </div>
      )}
      {loading ? (
        <Loading label="正在读取复习记录…" />
      ) : visible.length ? (
        <div
          className={styles.layout}
          data-catalog-open={catalogOpen ? "true" : "false"}
        >
          <aside className={styles.catalog} aria-label="复习集列表">
            {visible.map((deck) => {
              const counts = reviewCounts(deck);
              const paper = activePapers.get(deck.paperId);
              return (
                <article
                  key={deck.id}
                  className={
                    active?.id === deck.id ? styles.selectedDeck : styles.deck
                  }
                >
                  <button
                    className={styles.deckMain}
                    onClick={() => {
                      setActiveId(deck.id);
                      setCatalogOpen(false);
                    }}
                    aria-current={active?.id === deck.id ? "true" : undefined}
                  >
                    <span className={styles.deckOrigin}>
                      {deck.noteId ? "来自阅读笔记" : "来自论文"}
                      {deck.stale ? " · 来源已更新" : ""}
                    </span>
                    <h2>{deck.title}</h2>
                    <p>{paper?.title}</p>
                    <span className={styles.deckCounts}>
                      {counts.total} 题 · 已掌握 {counts.good} 题
                    </span>
                  </button>
                  <div className={styles.deckActions}>
                    <button
                      className={shared.textButton}
                      onClick={() => {
                        setActiveId(deck.id);
                        setCatalogOpen(false);
                      }}
                    >
                      {deck.session.currentQuestionId === null
                        ? "查看结果"
                        : deck.questions.some(
                              (question) => question.attemptCount > 0,
                            )
                          ? "继续复习"
                          : "开始复习"}
                      <ArrowRight size={13} />
                    </button>
                    {counts.good < counts.total && (
                      <button
                        className={shared.textButton}
                        onClick={() => void openMissed(deck)}
                        disabled={!!opening}
                      >
                        <RotateCcw size={12} />
                        只练未掌握
                      </button>
                    )}
                  </div>
                </article>
              );
            })}
          </aside>
          {active && (
            <ReviewPlayer
              key={active.id}
              deck={active}
              onUpdate={updateDeck}
              onOpenSource={onOpenSource}
            />
          )}
        </div>
      ) : !error ? (
        <EmptyState
          icon={<BookOpen size={25} />}
          title={available.length ? "这个范围里还没有复习集" : "还没有自测题"}
          description="从论文或阅读笔记中生成自测题，再来逐题练习。"
          action={
            papers.length ? (
              <button
                className={shared.primaryButton}
                onClick={() =>
                  onOpenPaper(
                    paperFilter !== "all" && activePapers.has(paperFilter)
                      ? paperFilter
                      : papers[0].id,
                  )
                }
              >
                打开论文出题
                <ArrowRight size={15} />
              </button>
            ) : undefined
          }
        />
      ) : null}
    </div>
  );
}

import type { ReviewDeck, ReviewQuestion } from "@/lib/research/review/types";

export function reviewCounts(deck: ReviewDeck) {
  const questions = deck.questions.filter((question) => !question.excluded);
  const good = questions.filter(
    (question) => question.rating === "good",
  ).length;
  const again = questions.filter(
    (question) => question.rating === "again",
  ).length;
  return {
    total: questions.length,
    good,
    again,
    unanswered: questions.length - good - again,
  };
}

export function currentReviewQuestion(deck: ReviewDeck): ReviewQuestion | null {
  if (deck.session.currentQuestionId === null) return null;
  return (
    deck.questions.find(
      (question) =>
        question.id === deck.session.currentQuestionId && !question.excluded,
    ) ??
    deck.questions.find(
      (question) =>
        !question.excluded &&
        (!deck.session.onlyMissed || question.rating !== "good"),
    ) ??
    null
  );
}

export function nextReviewQuestionId(
  deck: ReviewDeck,
  questionId: string,
): string | null {
  const current = deck.questions.findIndex(
    (question) => question.id === questionId,
  );
  return (
    deck.questions
      .slice(current + 1)
      .find(
        (question) =>
          !question.excluded &&
          (!deck.session.onlyMissed || question.rating !== "good"),
      )?.id ?? null
  );
}

export function firstReviewQuestionId(
  deck: ReviewDeck,
  onlyMissed: boolean,
): string | null {
  return (
    deck.questions.find(
      (question) =>
        !question.excluded && (!onlyMissed || question.rating !== "good"),
    )?.id ?? null
  );
}

export function reviewDraftKey(deckId: string, questionId: string): string {
  return `jiaoyan:review-response:v1:${deckId}:${questionId}`;
}

export function parseReviewDraft(
  raw: string | null,
  question: string,
  answer: string,
): string | null {
  if (!raw) return null;
  try {
    const value: unknown = JSON.parse(raw);
    if (
      !value ||
      typeof value !== "object" ||
      !("question" in value) ||
      !("answer" in value) ||
      !("response" in value)
    )
      return null;
    return value.question === question &&
      value.answer === answer &&
      typeof value.response === "string"
      ? value.response
      : null;
  } catch {
    return null;
  }
}

"use client";

import { useEffect, useRef, useState } from "react";
import type { ReviewDeck } from "@/lib/research/review/types";
import { errorText, patchJson, researchApi } from "../api";

export function useReviewMutation(
  deck: ReviewDeck,
  onUpdate: (deck: ReviewDeck) => void,
) {
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const locked = useRef(false);
  const current = useRef(deck);
  useEffect(() => {
    current.current = deck;
  }, [deck]);
  async function mutate(
    action: "response" | "attempt" | "session" | "question",
    input: Record<string, unknown>,
  ): Promise<ReviewDeck | null> {
    if (locked.current) return null;
    locked.current = true;
    setBusy(true);
    setError("");
    try {
      const result = await patchJson<{ deck: ReviewDeck }>(
        `/review/${deck.id}/${action}`,
        { ...input, version: current.current.version },
      );
      current.current = result.deck;
      onUpdate(result.deck);
      return result.deck;
    } catch (cause) {
      setError(errorText(cause));
      return null;
    } finally {
      locked.current = false;
      setBusy(false);
    }
  }
  async function reload() {
    if (locked.current) return;
    locked.current = true;
    setBusy(true);
    setError("");
    try {
      const result = await researchApi<{ deck: ReviewDeck }>(
        `/review/${deck.id}`,
      );
      current.current = result.deck;
      onUpdate(result.deck);
    } catch (cause) {
      setError(errorText(cause));
    } finally {
      locked.current = false;
      setBusy(false);
    }
  }
  return { busy, error, mutate, reload };
}

"use client";

import type {
  ResearchAnnotation,
  ResearchPaper,
  SourceRef,
} from "@/lib/research/types";
import {
  ArrowUpRight,
  Highlighter,
  MessageSquare,
  NotebookPen,
  PencilLine,
  RefreshCw,
  Trash2,
} from "lucide-react";
import { useEffect, useRef, useState } from "react";
import { errorText, researchApi, type PaperDetail } from "../api";
import { NoteEditor } from "../learning/NoteEditor";
import { EmptyState, Modal } from "../ResearchUi";
import styles from "../styles";
import {
  annotationNoteDraft,
  type AnnotationNoteDraft,
} from "./annotation-note";
import local from "./annotation-note.module.css";
import { filterAnnotations } from "../annotations/filter-annotations";

function annotationQuote(annotation: ResearchAnnotation): string {
  return (
    annotation.quote.trim() ||
    (annotation.kind === "highlight" ? annotation.text.trim() : "")
  );
}

function annotationThought(annotation: ResearchAnnotation): string {
  if (annotation.comment.trim()) return annotation.comment.trim();
  const text = annotation.text.trim();
  return annotation.kind === "comment" && text !== annotationQuote(annotation)
    ? text
    : "";
}

export function ReaderAnnotations({
  detail,
  paper,
  onAdd,
  onOpenSource,
  beforeWrite,
  onSaved,
  notify,
  onAsk,
  currentPage,
}: {
  detail: PaperDetail | null;
  paper: ResearchPaper;
  onAdd(): void;
  onOpenSource(source: SourceRef): void;
  beforeWrite(): boolean;
  onSaved(): Promise<void>;
  notify(message: string, error?: boolean): void;
  onAsk?(annotation: ResearchAnnotation): void;
  currentPage?: number;
}) {
  const [pending, setPending] = useState<{
    annotation: ResearchAnnotation;
    pdfEtag: string;
    action: "edit" | "delete";
    initialComment: string;
  } | null>(null);
  const [comment, setComment] = useState("");
  const [discardPending, setDiscardPending] = useState(false);
  const [saving, setSaving] = useState(false);
  const [refreshing, setRefreshing] = useState(false);
  const [selecting, setSelecting] = useState(false);
  const [excludedIds, setExcludedIds] = useState<string[]>([]);
  const [noteDraft, setNoteDraft] = useState<AnnotationNoteDraft | null>(null);
  const [query, setQuery] = useState("");
  const [onlyCurrentPage, setOnlyCurrentPage] = useState(false);
  const actionLock = useRef(false);
  const allAnnotations = (detail?.annotations ?? []).filter(
    (item) => item.paperId === paper.id,
  );
  const annotations = filterAnnotations(
    allAnnotations,
    query,
    onlyCurrentPage ? currentPage : undefined,
  );
  const selected = annotations.filter((item) => !excludedIds.includes(item.id));
  const locked = saving || refreshing || !!pending || !!noteDraft;
  const dirtyComment =
    pending?.action === "edit" && comment !== pending.initialComment;
  useEffect(() => {
    if (!dirtyComment) return;
    const prevent = (event: BeforeUnloadEvent) => {
      event.preventDefault();
      event.returnValue = "";
    };
    window.addEventListener("beforeunload", prevent);
    return () => window.removeEventListener("beforeunload", prevent);
  }, [dirtyComment]);

  function prepareNote() {
    if (locked || !beforeWrite()) return;
    try {
      setNoteDraft(annotationNoteDraft(detail?.paper ?? paper, selected));
    } catch (error) {
      notify(errorText(error), true);
    }
  }
  function prepare(annotation: ResearchAnnotation, action: "edit" | "delete") {
    if (locked || !beforeWrite()) return;
    const initialComment = annotationThought(annotation);
    setDiscardPending(false);
    setComment(initialComment);
    setPending({
      annotation,
      action,
      initialComment,
      pdfEtag: detail?.paper.pdfEtag ?? paper.pdfEtag,
    });
  }
  function closePending() {
    if (saving || actionLock.current) return;
    if (dirtyComment) {
      setDiscardPending((current) => !current);
      return;
    }
    setDiscardPending(false);
    setPending(null);
  }
  async function refresh() {
    if (locked || actionLock.current || !beforeWrite()) return;
    actionLock.current = true;
    setRefreshing(true);
    try {
      await onSaved();
    } catch (error) {
      notify(errorText(error), true);
    } finally {
      actionLock.current = false;
      setRefreshing(false);
    }
  }
  async function commit() {
    if (!pending || actionLock.current || !beforeWrite()) return;
    actionLock.current = true;
    setSaving(true);
    try {
      await researchApi(
        "/annotations/" + encodeURIComponent(pending.annotation.id),
        {
          method: pending.action === "delete" ? "DELETE" : "PATCH",
          body: JSON.stringify({
            version: pending.annotation.version,
            pdfEtag: pending.pdfEtag,
            ...(pending.action === "edit" ? { comment: comment.trim() } : {}),
          }),
        },
      );
      setPending(null);
      await onSaved();
      notify(
        pending.action === "delete" ? "批注已删除。" : "想法已保存并写入 PDF。",
      );
    } catch (error) {
      notify(errorText(error), true);
    } finally {
      actionLock.current = false;
      setSaving(false);
    }
  }
  return (
    <div className={styles.sidebarScroll}>
      <div className={local.heading}>
        <h3>
          批注 <span>{annotations.length}</span>
        </h3>
        <div className={local.toolbar}>
          {!selecting && annotations.length > 0 && (
            <button
              className={local.textButton}
              disabled={locked}
              onClick={() => {
                setExcludedIds([]);
                setSelecting(true);
              }}
            >
              <NotebookPen size={14} />
              整理成笔记
            </button>
          )}
          <button
            className={styles.iconButton}
            aria-label="重新载入批注"
            title="重新载入批注"
            disabled={locked}
            onClick={() => void refresh()}
          >
            <RefreshCw size={15} />
          </button>
          <button
            className={local.textButton}
            onClick={onAdd}
            disabled={locked}
          >
            <MessageSquare size={14} />
            添加评论
          </button>
        </div>
      </div>
      {allAnnotations.length > 0 && (
        <div className={local.filters}>
          <input
            aria-label="搜索批注"
            placeholder="搜索原文或想法…"
            value={query}
            disabled={locked}
            onChange={(event) => {
              setQuery(event.target.value);
              setSelecting(false);
            }}
          />
          <button
            type="button"
            disabled={locked || !currentPage}
            aria-pressed={onlyCurrentPage}
            onClick={() => {
              setOnlyCurrentPage((value) => !value);
              setSelecting(false);
            }}
            title={currentPage ? `第 ${currentPage} 页` : undefined}
          >
            当前页
          </button>
        </div>
      )}
      {selecting && (
        <div className={local.selectionBar} aria-label="选择要整理的批注">
          <label>
            <input
              type="checkbox"
              aria-label="全选批注"
              checked={
                annotations.length > 0 && selected.length === annotations.length
              }
              disabled={!annotations.length || locked}
              onChange={(event) =>
                setExcludedIds(
                  event.target.checked
                    ? []
                    : annotations.map((item) => item.id),
                )
              }
            />
            全选{" "}
            <span>
              {selected.length} / {annotations.length}
            </span>
          </label>
          <div className={local.selectionActions}>
            <button
              disabled={locked}
              onClick={() => {
                setSelecting(false);
                setExcludedIds([]);
              }}
            >
              取消
            </button>
            <button
              className={local.primaryButton}
              disabled={!selected.length || locked}
              onClick={prepareNote}
            >
              生成草稿
            </button>
          </div>
        </div>
      )}
      <div className={local.annotationList}>
        {annotations.map((annotation, index) => {
          const quote = annotationQuote(annotation);
          const thought = annotationThought(annotation);
          const isHighlight = annotation.kind === "highlight";
          return (
            <article className={local.annotationCard} key={annotation.id}>
              <div className={local.cardHeader}>
                <div className={local.annotationKind}>
                  {selecting && (
                    <input
                      className={local.selectAnnotation}
                      type="checkbox"
                      aria-label={
                        "选择第 " + annotation.page + " 页批注 " + (index + 1)
                      }
                      checked={!excludedIds.includes(annotation.id)}
                      disabled={locked}
                      onChange={(event) =>
                        setExcludedIds((current) =>
                          event.target.checked
                            ? current.filter((id) => id !== annotation.id)
                            : [...current, annotation.id],
                        )
                      }
                    />
                  )}
                  {isHighlight ? (
                    <Highlighter size={13} />
                  ) : (
                    <MessageSquare size={13} />
                  )}
                  <span>{isHighlight ? "高亮" : "评论"}</span>
                  {isHighlight && (
                    <span
                      className={local.colorDot}
                      data-highlight-color={annotation.color}
                      aria-hidden="true"
                    />
                  )}
                </div>
                <button
                  className={local.pageLink}
                  disabled={locked}
                  onClick={() =>
                    onOpenSource({
                      paperId: paper.id,
                      page: annotation.page,
                      ...(quote ? { quote } : {}),
                    })
                  }
                >
                  第 {annotation.page} 页 <ArrowUpRight size={12} />
                </button>
              </div>
              {quote && (
                <div className={local.excerpt}>
                  <span>原文</span>
                  {quote.length > 180 ? (
                    <details className={local.longExcerpt}>
                      <summary>
                        <span>{quote.slice(0, 110)}…</span>
                        <small>展开原文</small>
                      </summary>
                      <blockquote>{quote}</blockquote>
                    </details>
                  ) : (
                    <blockquote>{quote}</blockquote>
                  )}
                </div>
              )}
              {thought && (
                <div className={local.thought}>
                  <span>我的想法</span>
                  <p>{thought}</p>
                </div>
              )}
              <div className={local.cardFooter}>
                <span className={local.savedState}>
                  {annotation.pdfSaved ? "已写入 PDF" : "工作区记录"}
                </span>
                <div className={local.cardActions}>
                  {onAsk && (
                    <button
                      onClick={() => onAsk(annotation)}
                      disabled={locked || !quote}
                      aria-label={`对第 ${annotation.page} 页批注提问`}
                    >
                      <MessageSquare size={13} />
                      提问
                    </button>
                  )}
                  <button
                    onClick={() => prepare(annotation, "edit")}
                    disabled={locked}
                    aria-label={
                      (thought ? "编辑" : "添加") +
                      "第 " +
                      annotation.page +
                      " 页想法"
                    }
                  >
                    <PencilLine size={13} />
                    {thought ? "编辑" : "添加想法"}
                  </button>
                  <button
                    onClick={() => prepare(annotation, "delete")}
                    disabled={locked}
                    aria-label={
                      "删除第 " +
                      annotation.page +
                      " 页" +
                      (isHighlight ? "高亮" : "评论")
                    }
                  >
                    <Trash2 size={13} />
                    删除
                  </button>
                </div>
              </div>
            </article>
          );
        })}
      </div>
      {!annotations.length && (
        <EmptyState
          icon={<Highlighter size={24} />}
          title={allAnnotations.length ? "没有匹配的批注" : "暂无批注"}
          description={
            allAnnotations.length
              ? "试试其他关键词，或查看全部页面。"
              : "选中文字后，可高亮或写想法。"
          }
        />
      )}
      {noteDraft && (
        <NoteEditor
          paper={detail?.paper ?? paper}
          draft={noteDraft}
          onClose={() => setNoteDraft(null)}
          onOpenSource={onOpenSource}
          beforeSave={async () => beforeWrite()}
          onSaved={async () => {
            setSelecting(false);
            setExcludedIds([]);
            await onSaved();
          }}
          notify={notify}
        />
      )}
      {pending && (
        <Modal
          title={
            pending.action === "delete"
              ? "删除这条" +
                (pending.annotation.kind === "highlight" ? "高亮？" : "评论？")
              : pending.initialComment
                ? "编辑想法"
                : "添加想法"
          }
          onClose={closePending}
        >
          <div className={styles.modalBody}>
            <p className={styles.mutedSmall}>第 {pending.annotation.page} 页</p>
            {discardPending && (
              <div className={styles.softInfo} role="alert">
                <p>想法尚未保存。</p>
                <button
                  className={styles.secondaryButton}
                  onClick={() => setDiscardPending(false)}
                >
                  继续编辑
                </button>{" "}
                <button
                  className={styles.textButton}
                  onClick={() => {
                    setDiscardPending(false);
                    setPending(null);
                  }}
                >
                  放弃修改
                </button>
              </div>
            )}
            {pending.action === "delete" ? (
              <p>这条批注将从工作区和 PDF 中一并移除。</p>
            ) : (
              <label className={styles.formLabel}>
                我的想法
                <textarea
                  rows={7}
                  maxLength={10000}
                  value={comment}
                  onChange={(event) => setComment(event.target.value)}
                  autoFocus
                  disabled={saving}
                />
              </label>
            )}
          </div>
          <div className={styles.modalFooter}>
            <button
              className={styles.secondaryButton}
              disabled={saving}
              onClick={closePending}
            >
              取消
            </button>
            <button
              className={
                pending.action === "delete"
                  ? styles.dangerButton
                  : styles.primaryButton
              }
              disabled={
                saving ||
                (pending.action === "edit" &&
                  !comment.trim() &&
                  pending.annotation.kind !== "highlight")
              }
              onClick={() => void commit()}
            >
              {saving
                ? "正在保存…"
                : pending.action === "delete"
                  ? "删除批注"
                  : "保存想法"}
            </button>
          </div>
        </Modal>
      )}
    </div>
  );
}

