  return framework && framework in studyFrameworks
    ? studyFrameworks[framework as StudyFramework].title
    : null;
}

export type StudyPart =
  | { type: "markdown"; content: string }
  | { type: "question"; question: string; answer: string };

/** Only the explicit question-heading format becomes a closed answer card. */
export function studyParts(content: string): StudyPart[] {
  const lines = content.split(/\r?\n/);
  const parts: StudyPart[] = [];
  let prose: string[] = [];
  let question = "";
  let answer: string[] = [];
  let fence = "";
  function flush() {
    if (question) {
      const body = answer.join("\n").trim();
      if (body) {
        parts.push({
          type: "question",
          question,
          answer: body.replace(/^答案\s*[：:]\s*/, ""),
        });
      } else prose.push("### " + question);
      question = "";
      answer = [];
    }
    if (prose.join("\n").trim())
      parts.push({ type: "markdown", content: prose.join("\n") });
    prose = [];
  }
  for (const line of lines) {
    const marker = line.match(/^\s*(`{3,}|~{3,})/);
    if (marker) {
      if (!fence) fence = marker[1][0];
      else if (marker[1][0] === fence) fence = "";
    }
    const match = !fence && line.match(/^###\s+问题\s*\d+\s*[：:]\s*(.+)$/);
    if (match) {
      flush();
      question = match[1].trim();
    } else if (question && !fence && /^#{1,3}\s+/.test(line)) {
      flush();
      prose.push(line);
    } else if (question) answer.push(line);
    else prose.push(line);
  }
  flush();
  return parts;
}

export interface WorkspaceCitationTarget {
  paperId: string;
  page: number;
}

/** Recognize only our local source route and the model's exact workspace-host typo. */
export function workspaceCitationTarget(
  href: string,
): WorkspaceCitationTarget | null {
  const value = href.replaceAll("&amp;", "&");
  const local = value.startsWith("/workspace?");
  const mistyped = /^https?:\/\/workspace\/?\?/i.test(value);
  if (!local && !mistyped) return null;
  let url: URL;
  try {
    url = new URL(value, "http://local.invalid");
  } catch {
    return null;
  }
  if (url.username || url.password || url.hash || url.port) return null;
  if (
    local &&
    (url.origin !== "http://local.invalid" || url.pathname !== "/workspace")
  )
    return null;
  if (mistyped && (url.hostname !== "workspace" || url.pathname !== "/"))
    return null;
  if (
    [...url.searchParams.keys()].some(
      (key) => !["paperId", "paper", "page"].includes(key),
    )
  )
    return null;
  const paperIds = [
    ...url.searchParams.getAll("paperId"),
    ...url.searchParams.getAll("paper"),
  ];
  const pages = url.searchParams.getAll("page");
  if (
    paperIds.length !== 1 ||
    pages.length !== 1 ||
    !/^[A-Za-z0-9_-]{1,100}$/.test(paperIds[0]) ||
    !/^\d+$/.test(pages[0])
  )
    return null;
  const page = Number(pages[0]);
  if (!Number.isSafeInteger(page) || page < 1) return null;
  return { paperId: paperIds[0], page };
}

/** Repair a source citation, never an arbitrary external URL or example text. */
export function normalizeWorkspaceCitationHref(href: string): string {
  if (!/^https?:\/\/workspace\/?\?/i.test(href)) return href;
  const target = workspaceCitationTarget(href);
  return target
    ? `/workspace?paperId=${encodeURIComponent(target.paperId)}&page=${target.page}`
    : href;
}

"use client";

import { useState } from "react";
import Link from "next/link";
import styles from "./ImportReading.module.css";

export function ImportOnInstance({ mode }: { mode: "fork" | "collaborate" }) {
  const [instance, setInstance] = useState("");
  const [error, setError] = useState("");
  function openImport(event: React.FormEvent) {
    event.preventDefault();
    try {
      const origin = new URL(instance);
      if (
        origin.protocol !== "https:" ||
        origin.username ||
        origin.password ||
        origin.search ||
        origin.hash ||
        origin.pathname !== "/"
      )
        throw new Error();
      const target = new URL("/sharing/import", origin);
      const source = new URL(window.location.href);
      source.search = "";
      source.hash = "";
      target.searchParams.set("url", source.toString());
      target.searchParams.set("mode", mode);
      window.location.assign(target.toString());
    } catch {
      setError(
        "Enter your Papernook HTTPS address, for example https://papers.example.org.",
      );
    }
  }
  return (
    <section className={styles.invitation}>
      <h2>Open in your Papernook</h2>
      <p>
        {mode === "fork"
          ? "Keep an independent copy of this reading, including the selected chats. Your changes stay in your library."
          : "Request access to annotate together, or keep an independent copy. The owner must approve collaboration after verifying your code."}
      </p>
      <form onSubmit={openImport}>
        <label>
          Your Papernook address
          <input
            type="url"
            required
            value={instance}
            onChange={(event) => setInstance(event.target.value)}
            placeholder="https://papers.example.org"
          />
        </label>
        <button type="submit">Open import</button>
      </form>
      {error && <p role="alert">{error}</p>}
    </section>
  );
}

export function ImportReading({
  initialUrl,
  initialMode,
  topics,
}: {
  initialUrl: string;
  initialMode: string;
  topics: string[];
}) {
  const [url, setUrl] = useState(initialUrl);
  const [topic, setTopic] = useState(topics[0] ?? "shared");
  const [mode, setMode] = useState(
    initialMode === "collaborate" ? "collaborate" : "fork",
  );
  const [acknowledged, setAcknowledged] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  async function submit(event: React.FormEvent) {
    event.preventDefault();
    setBusy(true);
    setError("");
    try {
      const response = await fetch("/api/v1/shares/import", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          url,
          topic,
          mode,
          acknowledgePublicAnnotations: acknowledged,
        }),
      });
      const data: unknown = await response.json();
      if (
        !response.ok ||
        !data ||
        typeof data !== "object" ||
        !("href" in data) ||
        typeof data.href !== "string"
      )
        throw new Error(
          data &&
            typeof data === "object" &&
            "error" in data &&
            typeof data.error === "string"
            ? data.error
            : "Could not import the shared reading.",
        );
      if (!/^\/paper\/[a-z0-9-]+\/[a-z0-9-]+$/.test(data.href))
        throw new Error("The import returned an invalid destination.");
      window.location.assign(data.href);
    } catch (cause) {
      setError(
        cause instanceof Error
          ? cause.message
          : "Could not import the shared reading.",
      );
      setBusy(false);
    }
  }
  return (
    <div className={styles.root}>
      <Link href="/">← Library</Link>
      <p className={styles.eyebrow}>A reading from another library</p>
      <h1>Bring the paper with you.</h1>
      <p>Import the annotated PDF and the conversations its owner selected.</p>
      <form onSubmit={(event) => void submit(event)}>
        <label>
          Sharing link
          <input
            type="url"
            required
            value={url}
            onChange={(event) => setUrl(event.target.value)}
            placeholder="https://papers.example.org/share/…"
          />
        </label>
        <label>
          Topic
          <input
            required
            pattern={"[a-z0-9][a-z0-9\\-]{0,79}"}
            list="sharing-topics"
            value={topic}
            onChange={(event) => setTopic(event.target.value)}
          />
          <datalist id="sharing-topics">
            {topics.map((value) => (
              <option key={value} value={value} />
            ))}
          </datalist>
        </label>
        <fieldset>
          <legend>How to add it</legend>
          <label className={styles.choice}>
            <input
              type="radio"
              name="import-mode"
              checked={mode === "fork"}
              onChange={() => setMode("fork")}
            />
            <span>
              <strong>Independent fork</strong>
              <small>
                Your edits and new chats stay in your library. Copies keep
                working if the original link is revoked.
              </small>
            </span>
          </label>
          <label className={styles.choice}>
            <input
              type="radio"
              name="import-mode"
              checked={mode === "collaborate"}
              onChange={() => setMode("collaborate")}
            />
            <span>
              <strong>Collaborate</strong>
              <small>
                The owner approves your verification code. PDF annotations sync
                through their server. Chats stay private until published.
              </small>
            </span>
          </label>
        </fieldset>
        {mode === "collaborate" && (
          <label className={styles.choice}>
            <input
              type="checkbox"
              required
              checked={acknowledged}
              onChange={(event) => setAcknowledged(event.target.checked)}
            />
            <span>
              I understand that collaborative annotations also appear through
              the owner’s public reading links. I will verify my code with the
              owner.
            </span>
          </label>
        )}
        {error && (
          <p role="alert" className={styles.error}>
            {error}
          </p>
        )}
        <button
          type="submit"
          disabled={busy || (mode === "collaborate" && !acknowledged)}
        >
          {busy
            ? "Importing…"
            : mode === "collaborate"
              ? "Import and request access"
              : "Import independent fork"}
        </button>
      </form>
    </div>
  );
}

"use client";

import { useRef, useState } from "react";
import styles from "./ShareButton.module.css";
import { Participants } from "./SharingControls";

interface ChatHeader {
  id: string;
  title: string;
  createdAt: string;
}

interface ShareSummary {
  id: string;
  href: string;
  createdAt: string;
  conversations: { id: string; title: string }[];
  mode: "view" | "fork" | "collaborate";
  revoked?: boolean;
}

interface ShareButtonProps {
  topic: string;
  slug: string;
}

export function ShareButton({ topic, slug }: ShareButtonProps) {
  const dialogRef = useRef<HTMLDialogElement>(null);
  const base = `/api/v1/papers/${topic}/${slug}`;
  const [chats, setChats] = useState<ChatHeader[]>([]);
  const [shares, setShares] = useState<ShareSummary[]>([]);
  const [includeChats, setIncludeChats] = useState(false);
  const [includeArtifacts, setIncludeArtifacts] = useState(false);
  const [selectedChatIds, setSelectedChatIds] = useState<Set<string>>(
    new Set(),
  );
  const [loading, setLoading] = useState(false);
  const [creating, setCreating] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [copiedId, setCopiedId] = useState<string | null>(null);
  const [mode, setMode] = useState<ShareSummary["mode"]>("view");
  const [acknowledged, setAcknowledged] = useState(false);

  async function openDialog(): Promise<void> {
    dialogRef.current?.showModal();
    setLoading(true);
    setError(null);
    try {
      const [chatResponse, shareResponse] = await Promise.all([
        fetch(`${base}/chats`, { credentials: "include" }),
        fetch(`${base}/shares`, { credentials: "include" }),
      ]);
      if (!chatResponse.ok || !shareResponse.ok) {
        throw new Error("Could not load sharing options.");
      }
      const chatData = (await chatResponse.json()) as { chats?: ChatHeader[] };
      const shareData = (await shareResponse.json()) as {
        shares?: ShareSummary[];
      };
      const nextChats = chatData.chats ?? [];
      setChats(nextChats);
      setShares(shareData.shares ?? []);
      setIncludeChats(false);
      setSelectedChatIds(new Set(nextChats.map((chat) => chat.id)));
    } catch (cause) {
      setError(
        cause instanceof Error
          ? cause.message
          : "Could not load sharing options.",
      );
    } finally {
      setLoading(false);
    }
  }

  function toggleChat(chatId: string): void {
    setSelectedChatIds((current) => {
      const next = new Set(current);
      if (next.has(chatId)) next.delete(chatId);
      else next.add(chatId);
      return next;
    });
  }

  async function copyShare(share: ShareSummary): Promise<void> {
    try {
      await navigator.clipboard.writeText(
        `${window.location.origin}${share.href}`,
      );
      setCopiedId(share.id);
      window.setTimeout(() => setCopiedId(null), 1800);
    } catch {
      setError("Copy failed. Open the link and copy it from the address bar.");
    }
  }

  async function create(): Promise<void> {
    setCreating(true);
    setError(null);
    try {
      const response = await fetch(`${base}/shares`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({
          chatIds: includeChats ? [...selectedChatIds] : [],
          mode,
          includeArtifacts,
          acknowledgePublicAnnotations: acknowledged,
        }),
      });
      const data = (await response.json().catch(() => ({}))) as {
        share?: ShareSummary;
        error?: string;
      };
      if (!response.ok || !data.share) {
        throw new Error(data.error ?? "Could not create the link.");
      }
      setShares((current) => [data.share as ShareSummary, ...current]);
      await copyShare(data.share);
    } catch (cause) {
      setError(
        cause instanceof Error ? cause.message : "Could not create the link.",
      );
    } finally {
      setCreating(false);
    }
  }

  async function revoke(share: ShareSummary): Promise<void> {
    if (
      !window.confirm("Revoke this link? Anyone using it will lose access.")
    ) {
      return;
    }
    setError(null);
    const response = await fetch(`${base}/shares/${share.id}`, {
      method: "DELETE",
      credentials: "include",
    });
    if (!response.ok) {
      setError("Could not revoke the link.");
      return;
    }
    setShares((current) => current.filter((item) => item.id !== share.id));
  }

  return (
    <>
      <button className={styles.trigger} type="button" onClick={openDialog}>
        Share
      </button>
      <dialog
        className={styles.dialog}
        ref={dialogRef}
        aria-labelledby="share-dialog-title"
      >
        <div className={styles.dialogInner}>
          <header className={styles.header}>
            <div>
              <p className={styles.eyebrow}>Pass the paper on</p>
              <h2 id="share-dialog-title">
                {mode === "view"
                  ? "Create a view-only reading"
                  : mode === "fork"
                    ? "Share an independent copy"
                    : "Read and work together"}
              </h2>
            </div>
            <button
              className={styles.close}
              type="button"
              aria-label="Close sharing dialog"
              onClick={() => dialogRef.current?.close()}
            >
              ×
            </button>
          </header>

          {loading ? (
            <p className={styles.loading}>Opening the sharing desk…</p>
          ) : (
            <>
              <fieldset className={styles.modes}>
                <legend>Sharing mode</legend>
                {(
                  [
                    [
                      "view",
                      "View only",
                      "Read without an account. Editing and new messages are disabled.",
                    ],
                    [
                      "fork",
                      "Independent fork",
                      "Import into another Papernook. Future changes stay separate.",
                    ],
                    [
                      "collaborate",
                      "Collaborate",
                      "Approve each participant. Annotations, canvas, exercises and published chats stay in sync.",
                    ],
                  ] as const
                ).map(([value, label, description]) => (
                  <label key={value}>
                    <input
                      type="radio"
                      name="sharing-mode"
                      value={value}
                      checked={mode === value}
                      onChange={() => {
                        setMode(value);
                        setIncludeArtifacts(value === "fork");
                        setAcknowledged(false);
                      }}
                    />
                    <span>
                      <strong>{label}</strong>
                      <small>{description}</small>
                    </span>
                  </label>
                ))}
              </fieldset>
              <section className={styles.permission}>
                <div className={styles.permissionMark} aria-hidden="true">
                  ◇
                </div>
                <div>
                  <strong>
                    {mode === "view"
                      ? "View only"
                      : mode === "fork"
                        ? "Copies are independent"
                        : "Editing requires approval"}
                  </strong>
                  <p>
                    {mode === "view"
                      ? "The link shows the current annotated PDF. It cannot edit the paper or conversations."
                      : mode === "fork"
                        ? "The recipient keeps their copy after you revoke the link. Their changes never return to your library."
                        : "A link can request access. Approve only after checking the verification code with the person you invited. Names alone do not verify identity."}
                  </p>
                </div>
              </section>

              <label className={styles.includeRow}>
                <input
                  type="checkbox"
                  checked={includeArtifacts}
                  onChange={(event) =>
                    setIncludeArtifacts(event.target.checked)
                  }
                />
                <span>
                  <strong>Include canvas and exercise snapshots</strong>
                  <small>
                    {mode === "collaborate"
                      ? "Approved participants always sync these. This also includes initial snapshots in the public preview and independent copies."
                      : "Include saved canvas media, exercises and their annotated PDF. Later changes stay private."}
                  </small>
                </span>
              </label>

              <label className={styles.includeRow}>
                <input
                  type="checkbox"
                  checked={includeChats}
                  onChange={(event) => setIncludeChats(event.target.checked)}
                />
                <span>
                  <strong>
                    {mode === "collaborate"
                      ? "Include selected conversations"
                      : "Include conversation snapshots"}
                  </strong>
                  <small>
                    {mode === "collaborate"
                      ? "Approved participants see future turns in selected chats. The public preview keeps the initial snapshots."
                      : "Later messages stay private unless you create a new link."}
                  </small>
                </span>
              </label>

              {includeChats && (
                <div className={styles.chatList}>
                  {chats.length === 0 ? (
                    <p>No conversations to include yet.</p>
                  ) : (
                    chats.map((chat) => (
                      <label className={styles.chatRow} key={chat.id}>
                        <input
                          type="checkbox"
                          checked={selectedChatIds.has(chat.id)}
                          onChange={() => toggleChat(chat.id)}
                        />
                        <span>
                          <strong>{chat.title}</strong>
                          <small>
                            {new Date(chat.createdAt).toLocaleDateString()}
                          </small>
                        </span>
                      </label>
                    ))
                  )}
                </div>
              )}

              {mode === "collaborate" && (
                <label className={styles.includeRow}>
                  <input
                    type="checkbox"
                    checked={acknowledged}
                    onChange={(event) => setAcknowledged(event.target.checked)}
                  />
                  <span>
                    <strong>Share the same annotated PDF</strong>
                    <small>
                      Collaborative annotations also appear through existing
                      public reading links. Only publish chats you want
                      participants to read.
                    </small>
                  </span>
                </label>
              )}
              <button
                className={styles.create}
                type="button"
                disabled={
                  creating ||
                  (mode === "collaborate" && !acknowledged) ||
                  (includeChats &&
                    selectedChatIds.size === 0 &&
                    chats.length > 0)
                }
                onClick={create}
              >
                {creating ? "Creating…" : "Create link & copy"}
              </button>

              {error && (
                <p className={styles.error} role="alert">
                  {error}
                </p>
              )}

              {shares.length > 0 && (
                <section className={styles.activeShares}>
                  <h3>Active links</h3>
                  <ul>
                    {shares.map((share) => (
                      <li key={share.id}>
                        <div>
                          <strong>
                            {share.revoked
                              ? "Revoked. Cleanup pending."
                              : share.mode === "collaborate"
                                ? "Collaboration"
                                : share.mode === "fork"
                                  ? "Independent fork"
                                  : share.conversations.length === 0
                                    ? "Annotated paper"
                                    : `${share.conversations.length} conversation ${
                                        share.conversations.length === 1
                                          ? "snapshot"
                                          : "snapshots"
                                      }`}
                          </strong>
                          <small>
                            Created{" "}
                            {new Date(share.createdAt).toLocaleDateString()}
                          </small>
                        </div>
                        <div className={styles.shareActions}>
                          <button
                            type="button"
                            onClick={() => void copyShare(share)}
                          >
                            {copiedId === share.id ? "Copied" : "Copy"}
                          </button>
                          <a
                            href={share.href}
                            target="_blank"
                            rel="noopener noreferrer"
                          >
                            Open
                          </a>
                          <button
                            className={styles.revoke}
                            type="button"
                            onClick={() => void revoke(share)}
                          >
                            Revoke
                          </button>
                        </div>
                        {share.mode === "collaborate" && (
                          <Participants
                            endpoint={`${base}/shares/${share.id}/participants`}
                          />
                        )}
                      </li>
                    ))}
                  </ul>
                </section>
              )}
            </>
          )}
        </div>
      </dialog>
    </>
  );
}

"use client";

import { useCallback, useEffect, useState } from "react";
import Image from "next/image";
import { Markdown } from "@/components/chat/Markdown";
import type { PublishedThread } from "@/lib/sharing/schema";
import styles from "./SharingControls.module.css";

interface Participant {
  id: string;
  requestedName: string;
  name: string;
  status: "pending" | "approved" | "revoked";
}
interface Collaboration {
  connected: boolean;
  status: string;
  participantId?: string;
  ownActorId?: string;
  mirrorConflict?: boolean;
  syncErrors?: string[];
  shares: { id: string; createdAt: string }[];
  threads: (PublishedThread & { shareId?: string })[];
}

function threadKey(thread: PublishedThread & { shareId?: string }): string {
  return `${thread.shareId ?? "connected"}-${thread.actorId}-${thread.id}`;
}

async function responseJson<Result>(response: Response): Promise<Result> {
  const data: unknown = await response.json();
  if (!response.ok)
    throw new Error(
      data &&
        typeof data === "object" &&
        "error" in data &&
        typeof data.error === "string"
        ? data.error
        : "The sharing request failed.",
    );
  return data as Result;
}

export function Participants({ endpoint }: { endpoint: string }) {
  const [participants, setParticipants] = useState<Participant[] | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  async function load() {
    setError(null);
    try {
      setParticipants(
        (
          await responseJson<{ participants: Participant[] }>(
            await fetch(endpoint),
          )
        ).participants,
      );
    } catch (cause) {
      setError(
        cause instanceof Error ? cause.message : "Could not load requests.",
      );
    }
  }
  async function update(
    participant: Participant,
    status: "approved" | "revoked",
  ) {
    const message =
      status === "approved"
        ? `Approve ${participant.requestedName}? First verify code ${participant.id} with them. They will be able to annotate this paper and publish conversations.`
        : `Revoke ${participant.name}'s access? Existing downloaded copies cannot be recalled.`;
    if (!window.confirm(message)) return;
    setBusy(true);
    setError(null);
    try {
      setParticipants(
        (
          await responseJson<{ participants: Participant[] }>(
            await fetch(endpoint, {
              method: "PATCH",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({ id: participant.id, status }),
            }),
          )
        ).participants,
      );
    } catch (cause) {
      setError(
        cause instanceof Error ? cause.message : "Could not update access.",
      );
    } finally {
      setBusy(false);
    }
  }
  return (
    <div className={styles.participants}>
      <button type="button" onClick={() => void load()}>
        Manage participants
      </button>
      {participants && (
        <>
          <p>
            Check each code with the person requesting access before approving.
          </p>
          {participants.length === 0 && <p>No access requests.</p>}
          {participants.map((participant) => (
            <div className={styles.participant} key={participant.id}>
              <span>
                <strong>{participant.name}</strong>
                <small>
                  {participant.status} · <code>{participant.id}</code>
                </small>
              </span>
              {participant.status === "pending" && (
                <button
                  disabled={busy}
                  type="button"
                  onClick={() => void update(participant, "approved")}
                >
                  Approve
                </button>
              )}
              {participant.status !== "revoked" && (
                <button
                  disabled={busy}
                  type="button"
                  onClick={() => void update(participant, "revoked")}
                >
                  Revoke
                </button>
              )}
            </div>
          ))}
        </>
      )}
      {error && (
        <p role="alert" className={styles.error}>
          {error}
        </p>
      )}
    </div>
  );
}

export function CollaborationPanel({
  topic,
  slug,
  connected,
}: {
  topic: string;
  slug: string;
  connected: boolean;
}) {
  const base = `/api/v1/papers/${topic}/${slug}`;
  const [data, setData] = useState<Collaboration | null>(null);
  const [expanded, setExpanded] = useState<Set<string>>(() => new Set());
  const [error, setError] = useState<string | null>(null);
  const [chats, setChats] = useState<{ id: string; title: string }[]>([]);
  const [chatId, setChatId] = useState("");
  const [shareId, setShareId] = useState("");
  const [busy, setBusy] = useState(false);
  const load = useCallback(async () => {
    try {
      const next = await responseJson<Collaboration>(
        await fetch(`${base}/collaboration`),
      );
      setData(next);
      setError(null);
    } catch (cause) {
      setError(
        cause instanceof Error
          ? cause.message
          : "Could not refresh collaboration.",
      );
    }
  }, [base]);
  useEffect(() => {
    const initial = window.setTimeout(() => void load(), 0);
    const interval = window.setInterval(() => void load(), 30_000);
    return () => {
      window.clearTimeout(initial);
      window.clearInterval(interval);
    };
  }, [load]);
  async function loadChats() {
    try {
      setChats(
        (
          await responseJson<{ chats: { id: string; title: string }[] }>(
            await fetch(`${base}/chats`),
          )
        ).chats,
      );
    } catch (cause) {
      setError(
        cause instanceof Error
          ? cause.message
          : "Could not load conversations.",
      );
    }
  }
  async function publish() {
    setBusy(true);
    setError(null);
    try {
      await responseJson(
        await fetch(`${base}/collaboration`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            chatId,
            ...(data?.connected
              ? {}
              : { shareId: shareId || data?.shares[0]?.id }),
          }),
        }),
      );
      await load();
    } catch (cause) {
      setError(
        cause instanceof Error
          ? cause.message
          : "Could not publish the conversation.",
      );
    } finally {
      setBusy(false);
    }
  }
  async function refresh() {
    setBusy(true);
    try {
      if (data?.status !== "pending")
        await responseJson<unknown>(
          await fetch(`${base}/collaboration`, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ action: "sync" }),
          }),
        );
      await load();
      await loadChats();
    } catch (cause) {
      setError(
        cause instanceof Error ? cause.message : "Could not sync this reading.",
      );
    } finally {
      setBusy(false);
    }
  }
  if (!connected && !data?.shares.length && !error) return null;
  async function unpublish(
    thread: Pick<PublishedThread, "id"> & { shareId?: string },
  ) {
    if (
      !window.confirm(
        "Stop sharing this conversation? Previously downloaded copies cannot be recalled.",
      )
    )
      return;
    setBusy(true);
    try {
      await responseJson<unknown>(
        await fetch(`${base}/collaboration`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            action: "unpublish",
            chatId: thread.id,
            ...(thread.shareId ? { shareId: thread.shareId } : {}),
          }),
        }),
      );
      await load();
    } catch (cause) {
      setError(
        cause instanceof Error
          ? cause.message
          : "Could not withdraw the conversation.",
      );
    } finally {
      setBusy(false);
    }
  }
  async function detach() {
    if (
      !window.confirm(
        "Keep an independent local copy and stop syncing? Your cached PDF and personal chats will remain. Published copies held by others cannot be recalled.",
      )
    )
      return;
    setBusy(true);
    try {
      const result = await responseJson<{ warning: string | null }>(
        await fetch(`${base}/collaboration`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ action: "disconnect" }),
        }),
      );
      if (result.warning) window.alert(result.warning);
      window.location.reload();
    } catch (cause) {
      setError(
        cause instanceof Error ? cause.message : "Could not detach this copy.",
      );
      setBusy(false);
    }
  }
  return (
    <details className={styles.collaboration} open={connected}>
      <summary>
        Collaboration {data?.status === "pending" ? "· awaiting approval" : ""}
      </summary>
      <div className={styles.body}>
        {data?.syncErrors?.map((message, index) => (
          <p key={index} role="alert" className={styles.error}>
            {message}
          </p>
        ))}
        {data?.mirrorConflict && (
          <p role="alert" className={styles.error}>
            The local PDF has changes from outside collaboration. They have been
            preserved and will not be uploaded. Keep an independent copy to work
            with them.
          </p>
        )}
        {data?.participantId && (
          <p>
            Your verification code: <code>{data.participantId}</code>. Give this
            code to the owner before they approve access.
          </p>
        )}
        <p>
          Annotations are shared with every participant and anyone holding an
          existing reading link. Chats stay private until you publish them.
          Published chats include future turns.
        </p>
        {connected && (
          <p>
            Browser edits use your approved identity. Canvas and exercises sync
            with this reading. The WebDAV PDFs are reading mirrors.
          </p>
        )}
        <button type="button" disabled={busy} onClick={() => void refresh()}>
          Refresh sharing
        </button>
        {data && data.status !== "pending" && (
          <div className={styles.publish}>
            <label>
              Publish a conversation
              <select
                value={chatId}
                onFocus={() => void loadChats()}
                onChange={(event) => setChatId(event.target.value)}
              >
                <option value="">Choose one of your chats</option>
                {chats.map((chat) => (
                  <option value={chat.id} key={chat.id}>
                    {chat.title}
                  </option>
                ))}
              </select>
            </label>
            {(data?.shares.length ?? 0) > 1 && (
              <label>
                Collaboration
                <select
                  value={shareId}
                  onChange={(event) => setShareId(event.target.value)}
                >
                  {data?.shares.map((share) => (
                    <option value={share.id} key={share.id}>
                      {new Date(share.createdAt).toLocaleString()}
                    </option>
                  ))}
                </select>
              </label>
            )}
            <button
              disabled={!chatId || busy}
              type="button"
              onClick={() => void publish()}
            >
              {busy ? "Publishing…" : "Publish and sync"}
            </button>
            <button
              disabled={!chatId || busy}
              type="button"
              onClick={() =>
                void unpublish({
                  id: chatId,
                  ...(shareId || data.shares[0]?.id
                    ? { shareId: shareId || data.shares[0]?.id }
                    : {}),
                })
              }
            >
              Stop sharing selected conversation
            </button>
          </div>
        )}
        {error && (
          <p role="alert" className={styles.error}>
            {error}
          </p>
        )}
        {connected && (
          <button disabled={busy} type="button" onClick={() => void detach()}>
            Keep an independent copy
          </button>
        )}
        {data?.threads.map((thread) => (
          <details
            className={styles.thread}
            key={threadKey(thread)}
            onToggle={(event) => {
              const open = event.currentTarget.open;
              setExpanded((current) => {
                const next = new Set(current);
                if (open) next.add(threadKey(thread));
                else next.delete(threadKey(thread));
                return next;
              });
            }}
          >
            <summary>
              {thread.chat.header.title}
              <small>
                {thread.author} · {thread.actorId}
              </small>
            </summary>
            {thread.actorId === data.ownActorId && (
              <button
                disabled={busy}
                type="button"
                onClick={() => void unpublish(thread)}
              >
                Stop sharing conversation
              </button>
            )}
            {expanded.has(threadKey(thread)) &&
              thread.chat.messages.map((message, index) => (
                <article key={index}>
                  <strong>
                    {message.role === "user"
                      ? thread.author
                      : `AI · ${thread.author}`}
                  </strong>
                  <Markdown
                    content={message.content}
                    renderThree={false}
                    decorateRefs={false}
                    paperRefs={false}
                  />
                  {message.images?.map((image) => {
                    const name = image.slice(6);
                    const content = thread.assets[name];
                    const extension = name.split(".").at(-1);
                    return content ? (
                      <Image
                        width={1200}
                        height={900}
                        unoptimized
                        key={name}
                        src={`data:image/${extension === "jpg" ? "jpeg" : extension};base64,${content}`}
                        alt="Shared conversation attachment"
                      />
                    ) : null;
                  })}
                </article>
              ))}
          </details>
        ))}
      </div>
    </details>
  );
}

"use client";
import { useEffect, useRef, useState } from "react";
import dynamicImport from "next/dynamic";
import { PdfReader } from "@/components/pdf/PdfReader";
import { Markdown } from "@/components/chat/Markdown";
import type { ExerciseRecord } from "@/lib/library/exercises/schema";
import styles from "./StudyArtifacts.module.css";

const SharedCanvas = dynamicImport(
  () => import("./SharedCanvas").then((module) => module.SharedCanvas),
  { ssr: false, loading: () => <p>Opening canvas…</p> },
);

export function PublicStudyArtifacts({
  endpoint,
  licenseKey,
}: {
  endpoint: string;
  licenseKey: string | null;
}) {
  const [value, setValue] = useState<{
    document: unknown;
    exercises: ExerciseRecord[];
    hasPdf: boolean;
  } | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [opened, setOpened] = useState(false);
  useEffect(() => {
    if (!opened) return;
    const controller = new AbortController();
    void fetch(endpoint, { cache: "no-store", signal: controller.signal })
      .then(async (response) => {
        if (!response.ok)
          throw new Error("This shared snapshot is unavailable.");
        setValue(await response.json());
      })
      .catch((error) => {
        if (!controller.signal.aborted)
          setError(
            error instanceof Error
              ? error.message
              : "The snapshot could not be loaded.",
          );
      });
    return () => controller.abort();
  }, [endpoint, opened]);
  return (
    <section className={styles.root} aria-label="Shared canvas and exercises">
      <h2>Canvas and exercises</h2>
      <p>These are the snapshots the owner included when creating this link.</p>
      {!opened && (
        <button type="button" onClick={() => setOpened(true)}>
          View canvas and exercises
        </button>
      )}
      {error && (
        <p role="alert" className={styles.error}>
          {error}
        </p>
      )}
      {opened && !value && !error && (
        <p role="status">Loading shared snapshots…</p>
      )}
      {value?.document ? (
        <SharedCanvas document={value.document} licenseKey={licenseKey} />
      ) : null}
      {value?.exercises.map((record) => (
        <article className={styles.record} key={record.operationId}>
          <p className={styles.author}>{record.author}</p>
          <Markdown content={record.markdown} />
        </article>
      ))}
      {value?.hasPdf && (
        <div className={styles.pdf}>
          <PdfReader src={`${endpoint}?pdf=1`} title="Shared exercise PDF" />
        </div>
      )}
      {value && !value.document && !value.exercises.length && !value.hasPdf && (
        <p>No canvas or exercises were saved in this snapshot.</p>
      )}
    </section>
  );
}

export function PaperExercises({
  topic,
  slug,
  editable,
}: {
  topic: string;
  slug: string;
  editable: boolean;
}) {
  const endpoint = `/api/v1/papers/${topic}/${slug}/exercises`;
  const [records, setRecords] = useState<ExerciseRecord[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [opened, setOpened] = useState(false);
  const [markdown, setMarkdown] = useState("");
  const [saving, setSaving] = useState(false);
  const operation = useRef<string | null>(null);
  const [refreshVersion, setRefreshVersion] = useState(0);
  useEffect(() => {
    if (!opened) return;
    let stopped = false;
    const controller = new AbortController();
    const refresh = async () => {
      try {
        const response = await fetch(endpoint, {
          cache: "no-store",
          signal: controller.signal,
        });
        if (!response.ok)
          throw new Error(
            "Exercises could not sync. Check collaboration access and local changes.",
          );
        const data = (await response.json()) as { records: ExerciseRecord[] };
        if (!stopped) {
          setRecords(data.records);
          setError(null);
        }
      } catch (error) {
        if (!stopped)
          setError(
            error instanceof Error
              ? error.message
              : "Exercises could not be loaded.",
          );
      }
    };
    void refresh();
    const interval = window.setInterval(() => void refresh(), 30_000);
    return () => {
      stopped = true;
      controller.abort();
      window.clearInterval(interval);
    };
  }, [endpoint, opened, refreshVersion]);
  const save = async () => {
    if (saving || !markdown.trim()) return;
    setSaving(true);
    setError(null);
    try {
      operation.current ??= Array.from(
        crypto.getRandomValues(new Uint8Array(16)),
        (value) => value.toString(16).padStart(2, "0"),
      ).join("");
      const response = await fetch(endpoint, {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ markdown, operationId: operation.current }),
      });
      const payload = (await response.json()) as { error?: string };
      if (!response.ok)
        throw new Error(
          payload.error ??
            "The exercise could not be saved. Retry to recover the same save.",
        );
      setMarkdown("");
      operation.current = null;
      setRefreshVersion((version) => version + 1);
    } catch (error) {
      setError(
        error instanceof Error
          ? error.message
          : "The exercise could not be saved.",
      );
    } finally {
      setSaving(false);
    }
  };
  return (
    <details
      className={styles.root}
      onToggle={(event) => setOpened(event.currentTarget.open)}
    >
      <summary>Exercises</summary>
      {editable && (
        <form
          onSubmit={(event) => {
            event.preventDefault();
            void save();
          }}
        >
          <label htmlFor={`exercise-${topic}-${slug}`}>Add an exercise</label>
          <textarea
            id={`exercise-${topic}-${slug}`}
            value={markdown}
            maxLength={100_000}
            disabled={saving}
            onChange={(event) => {
              setMarkdown(event.target.value);
              operation.current = null;
            }}
          />
          <button type="submit" disabled={saving || !markdown.trim()}>
            {saving ? "Saving exercise…" : "Save exercise"}
          </button>
        </form>
      )}
      {error && (
        <p role="alert" className={styles.error}>
          {error}
        </p>
      )}
      {records.map((record) => (
        <article className={styles.record} key={record.operationId}>
          <p className={styles.author}>{record.author}</p>
          <Markdown content={record.markdown} />
        </article>
      ))}
      {records.length > 0 && (
        <div className={styles.pdf}>
          <PdfReader
            src={`${endpoint}/pdf`}
            title="Exercise PDF"
            editable={editable}
          />
        </div>
      )}
      {opened && !records.length && !error && <p>No exercises saved yet.</p>}
    </details>
  );
}

import { randomUUID } from "node:crypto";
import {
  ProviderRegistry,
  type CredentialValues,
  type GenerationRequest,
  type Message,
} from "thesidedoor-core/ai";
import { apiProviders } from "thesidedoor-core/ai/providers";
import { PROVIDER_METADATA } from "thesidedoor-core/ai/catalog";
import {
  defineTool,
  ToolRuntime,
  type ToolRuntimeEvent,
} from "thesidedoor-core/ai/tools";
import { readImageBase64 } from "./attachments";
import { configuredModel, readAiState } from "./config";
import { credentialCodec } from "./platform/vault";
import { dataRoot } from "../data-dir";
import {
  invocationMetrics,
  closeInvocationMetrics,
  profileMetricConsumer,
} from "./platform/metrics";
import { executeWebTool, WEB_TOOLS } from "./web/tools";
import {
  DEFAULT_TIMEOUT_MS,
  type AgentProvider,
  type AgentTurn,
  type ProviderId,
} from "./types";

type ApiProviderId = Exclude<ProviderId, "claude-code" | "codex">;
const DEFAULT_MODELS = { anthropic: "claude-opus-4-8", openai: "gpt-5.5" };

export function apiCredentials(
  provider: ApiProviderId,
  state = readAiState(),
): CredentialValues {
  return credentialCodec(state, dataRoot()).resolveState(
    state.credentials,
    provider,
  );
}

function messages(turn: AgentTurn): Message[] {
  const content: Message["content"][number][] = (turn.images ?? []).map(
    (file) => {
      const { mediaType, data } = readImageBase64(file);
      return { type: "image", mediaType, data: Buffer.from(data, "base64") };
    },
  );
  content.push({ type: "text", text: turn.prompt });
  return [
    ...(turn.system
      ? [
          {
            role: "system" as const,
            content: [{ type: "text" as const, text: turn.system }],
          },
        ]
      : []),
    { role: "user", content },
  ];
}

function warningSuffix(warnings: string[]): string {
  return warnings.length
    ? "\n\nWeb access warning: " + warnings.join("; ")
    : "";
}

function invocation(
  provider: ApiProviderId,
  turn: AgentTurn,
  streaming: boolean,
  metrics: ReturnType<typeof invocationMetrics>,
) {
  const state = readAiState();
  const model =
    configuredModel(state.selection) ||
    (provider in DEFAULT_MODELS
      ? DEFAULT_MODELS[provider as keyof typeof DEFAULT_MODELS]
      : PROVIDER_METADATA[provider]?.models[0]?.id);
  if (!model)
    throw new Error(
      provider + ": select a model in Settings before using this provider",
    );
  const values = apiCredentials(provider, state);
  const responses = provider === "openai" && !values.baseUrl;
  const adapters = apiProviders({
    openaiTransport: responses ? "responses" : "chat",
    streaming,
    maxTokensParameter: "max_completion_tokens",
  });
  const adapter = adapters.find((entry) => entry.descriptor.id === provider);
  if (!adapter) throw new Error("Unknown AI provider: " + provider);
  const webTools = Boolean(
    turn.allowWeb && !adapter.descriptor.capabilities.includes("web"),
  );
  const signal = turn.signal
    ? AbortSignal.any([
        turn.signal,
        AbortSignal.timeout(turn.timeoutMs ?? DEFAULT_TIMEOUT_MS),
      ])
    : AbortSignal.timeout(turn.timeoutMs ?? DEFAULT_TIMEOUT_MS);
  const registry = new ProviderRegistry({
    metrics: metrics?.collector,
    providers: adapters,
    credentials: {
      async resolve() {
        return values;
      },
    },
  });
  const request: GenerationRequest = {
    provider,
    model,
    messages: messages(turn),
    signal,
    consumerId:
      turn.metricOwner === "instance"
        ? "instance"
        : turn.metricOwner
          ? profileMetricConsumer(turn.metricOwner)
          : "unattributed",
    conversationId: randomUUID(),
    credentialOwnerId: "instance",
    timeoutMs: turn.timeoutMs ?? DEFAULT_TIMEOUT_MS,
    maxOutputTokens: turn.maxOutputTokens,
    adaptiveThinking: provider === "anthropic",
    responseFormat: turn.responseFormat,
    allowWeb: Boolean(turn.allowWeb && !webTools),
  };
  const warnings: string[] = [];
  const tools = WEB_TOOLS.map((tool) => {
    if (tool.type !== "function")
      throw new Error("Unsupported web tool definition");
    return defineTool<Record<string, unknown>, string>({
      name: tool.function.name,
      description: tool.function.description ?? tool.function.name,
      schema: tool.function.parameters ?? { type: "object" },
      effect: "read",
      parse(input) {
        if (!input || typeof input !== "object" || Array.isArray(input))
          throw new Error("Invalid web tool arguments");
        return input as Record<string, unknown>;
      },
      async authorize() {
        signal.throwIfAborted();
      },
      async execute(input, context) {
        try {
          return await executeWebTool(
            tool.function.name,
            input,
            context.signal,
          );
        } catch (error) {
          context.signal.throwIfAborted();
          const warning =
            tool.function.name +
            " failed: " +
            (error instanceof Error ? error.message : String(error));
          warnings.push(warning);
          return JSON.stringify({ error: warning });
        }
      },
    });
  });
  const runtime = new ToolRuntime({
    registry,
    tools,
    maxToolRounds: 6,
    maxCalls: 256,
    toolTimeoutMs: turn.timeoutMs ?? DEFAULT_TIMEOUT_MS,
    finalAnswerOnLimit: true,
    structuredFinalAnswer: true,
  });
  return {
    events: webTools
      ? runtime.stream(request, "instance")
      : registry.generate(request),
    warnings,
    responses,
  };
}

async function* events(
  provider: ApiProviderId,
  turn: AgentTurn,
  streaming: boolean,
): AsyncGenerator<ToolRuntimeEvent> {
  const metrics = invocationMetrics(turn.metricOwner);
  const started = performance.now();
  let prepared = false;
  try {
    const run = invocation(provider, turn, streaming, metrics);
    prepared = true;
    for await (const event of run.events) {
      if (event.type === "tool_limit")
        run.warnings.push(
          event.limit === "rounds"
            ? "web tool limit reached (6 rounds)"
            : "web tool call limit reached (256 calls)",
        );
      if (
        event.type === "finish" &&
        event.reason === "length" &&
        (run.responses || turn.responseFormat)
      )
        throw new Error(provider + ": response incomplete");
      yield event;
    }
    if (!turn.responseFormat && run.warnings.length)
      yield { type: "text", text: warningSuffix(run.warnings) };
  } catch (error) {
    if (!prepared)
      metrics?.collector.record({
        version: 1,
        id: randomUUID(),
        timestamp: Date.now(),
        kind: "execution",
        operation: "prepare",
        provider,
        outcome: turn.signal?.aborted ? "cancelled" : "error",
        consumerId:
          turn.metricOwner === "instance"
            ? "instance"
            : turn.metricOwner
              ? profileMetricConsumer(turn.metricOwner)
              : undefined,
        credentialOwnerId: "instance",
        durationMs: performance.now() - started,
        inputTokens: null,
        outputTokens: null,
        estimatedCost: null,
        errorCode: "preparation_failed",
      });
    throw error;
  } finally {
    await closeInvocationMetrics(metrics);
  }
}

async function execute(
  provider: ApiProviderId,
  turn: AgentTurn,
): Promise<string> {
  let text = "";
  for await (const event of events(provider, turn, false)) {
    if (event.type === "tool_status" && event.status === "running") text = "";
    if (event.type === "text") text += event.text;
  }
  return text;
}

async function* stream(
  provider: ApiProviderId,
  turn: AgentTurn,
): AsyncGenerator<string> {
  if (turn.responseFormat && turn.allowWeb) {
    yield await execute(provider, turn);
    return;
  }
  for await (const event of events(provider, turn, true))
    if (event.type === "text") yield event.text;
}

export function provider(id: ApiProviderId): AgentProvider {
  return {
    id,
    capabilities: { web: true, vision: true, unboundedContext: false },
    execute: (turn) => execute(id, turn),
    stream: (turn) => stream(id, turn),
  };
}
export const openaiProvider = provider("openai");
export const ollamaProvider = provider("ollama");
export const vllmProvider = provider("vllm");

