const IMPORT_LOCK_WAIT_MS = 60_000;
const MAX_ANNOTATION_CHARS = 20_000;
const MAX_ANNOTATION_RECORDS = 10_000;

interface ZoteroCatalogEntry {
  key: string;
  title: string;
  authors: string[];
  year: number | null;
  annotationCount: number;
  hasStoredPdf: boolean;
  imported: { topic: string; slug: string } | null;
}

export interface ZoteroCatalogPage {
  items: ZoteroCatalogEntry[];
  total: number;
  importable: number;
  imported: number;
  page: number;
  limit: number;
  refreshedAt: string | null;
}

function paperForAssociation(
  association: ZoteroAssociation | undefined,
): Paper | null {
  if (!association) return null;
  return (
    listPapers().find(
      (paper) =>
        paper.topic === association.topic && paper.slug === association.slug,
    ) ?? null
  );
}

function annotationCounts(library: ZoteroCatalogLibrary): Map<string, number> {
  const attachmentParents = new Map<string, string>();
  for (const record of Object.values(library.records)) {
    if (
      record.itemType === "attachment" &&
      record.contentType === "application/pdf"
    ) {
      attachmentParents.set(record.key, record.parentItem ?? record.key);
    }
  }
  const counts = new Map<string, number>();
  for (const record of Object.values(library.records)) {
    if (record.itemType !== "annotation" || !record.parentItem) continue;
    const parent = attachmentParents.get(record.parentItem);
    if (parent) counts.set(parent, (counts.get(parent) ?? 0) + 1);
  }
  return counts;
}

function emptyPage(page: number, limit: number): ZoteroCatalogPage {
  return {
    items: [],
    total: 0,
    importable: 0,
    imported: 0,
    page,
    limit,
    refreshedAt: null,
  };
}

export async function listCatalogItems(
  capability: ProfileCapability,
  query: string,
  page: number,
  limit: number,
): Promise<ZoteroCatalogPage> {
  const identity = new PapernookIdentityStore(dataRoot());
  return withProfileActivity(identity, capability, async () => {
    const { username } = capability;
    const profile = getProfile(username);
    if (!profile?.zotero) return emptyPage(page, limit);
    const target = targetOf(profile.zotero);
    const catalog = await readZoteroCatalog(capability);
    const library = catalog.libraries[libraryIdentity(target)];
    if (!library) return emptyPage(page, limit);
    const counts = annotationCounts(library);
    const normalizedQuery = query.trim().toLocaleLowerCase();
    const entries = visibleParentRecords(profile.zotero, library)
      .map((item): ZoteroCatalogEntry => {
        const paper = paperForAssociation(
          associationFor(catalog.associations, target, item.key),
        );
        const yearMatch = item.date?.match(/\b(\d{4})\b/);
        return {
          key: item.key,
          title:
            optional(item.title) ?? optional(item.filename) ?? "Untitled PDF",
          authors: citationAuthors(item).map(
            (author) =>
              author.literal ??
              [author.given, author.family].filter(Boolean).join(" "),
          ),
          year: yearMatch ? Number(yearMatch[1]) : null,
          annotationCount: counts.get(item.key) ?? 0,
          hasStoredPdf: storedAttachmentKeys(library, item).length > 0,
          imported: paper?.topic
            ? { topic: paper.topic, slug: paper.slug }
            : null,
        };
      })
      .filter((item) => {
        if (!normalizedQuery) return true;
        return `${item.title} ${item.authors.join(" ")}`
          .toLocaleLowerCase()
          .includes(normalizedQuery);
      })
      .sort(
        (a, b) => a.title.localeCompare(b.title) || a.key.localeCompare(b.key),
      );
    const offset = (page - 1) * limit;
    return withProfileFiles(identity, capability, () => ({
      items: entries.slice(offset, offset + limit),
      total: entries.length,
      importable: entries.filter((item) => item.hasStoredPdf).length,
      imported: entries.filter((item) => item.imported).length,
      page,
      limit,
      refreshedAt: library.refreshedAt,
    }));
  });
}

export class ZoteroCatalogItemNotFoundError extends ZoteroError {}
export class ZoteroImportUnavailableError extends ZoteroError {}

export interface ZoteroImportResult {
  created: boolean;
  topic: string;
  slug: string;
}

async function importLocked(
  username: string,
  itemKey: string,
  activity: ProfileActivity,
): Promise<ZoteroImportResult> {
  const profile = getProfile(username);
  const cfg = profile?.zotero;
  if (!profile || !cfg) {
    throw new ZoteroCatalogItemNotFoundError("Zotero is not connected.");
  }
  const target = targetOf(cfg);
  const catalog = await readZoteroCatalog(activity.capability);
  const library = catalog.libraries[libraryIdentity(target)];
  const item = library
    ? visibleParentRecords(cfg, library).find(
        (candidate) => candidate.key === itemKey,
      )
    : undefined;
  if (!library || !item) {
    throw new ZoteroCatalogItemNotFoundError(
      "That item is not in the active Zotero catalog.",
    );
  }
  const associated = paperForAssociation(
    associationFor(catalog.associations, target, item.key),
  );
  if (associated?.topic) {
    return { created: false, topic: associated.topic, slug: associated.slug };
  }
  const existing = existingPaperFor(username, target, item);
  if (existing?.topic) {
    associate(catalog, target, item.key, existing);
    await writeZoteroCatalog(activity.capability, catalog);
    return { created: false, topic: existing.topic, slug: existing.slug };
  }
  const attachmentKeys = storedAttachmentKeys(library, item);
  if (attachmentKeys.length === 0) {
    throw new ZoteroImportUnavailableError(
      "This item has no stored Zotero PDF available to download.",
    );
  }
  let bytes: Buffer | null = null;
  let lastError: unknown = null;
  for (const attachmentKey of attachmentKeys) {
    try {
      bytes = await downloadAttachment(cfg, attachmentKey);
      break;
    } catch (error) {
      if (error instanceof ZoteroPdfTooLargeError) throw error;
      lastError = error;
    }
  }
  if (!bytes) {
    throw new ZoteroImportUnavailableError(
      lastError instanceof Error
        ? lastError.message
        : "Zotero could not provide this PDF.",
    );
  }
  const captured = await capturePdf(
    bytes,
    {
      sourceUrl:
        optional(item.url) ??
        `https://www.zotero.org/${target.type === "user" ? "users" : "groups"}/${target.id}/items/${item.key}`,
      username,
      arxivId: arxivIdOf(item),
      capability: activity.capability,
      autoFile: true,
      source: sourceOf(item, target, collectionMap(library)),
      overrides: overridesOf(item),
      sourceTags: sourceTags(item),
    },
    activity,
  );
  if (activity.cancelled()) {
    removeOwnedCapture(username, captured.slug, captured.proposedTopic);
    throw new ZoteroCatalogItemNotFoundError(
      "The importing profile was deleted.",
    );
  }
  const paper = listPapers().find(
    (candidate) =>
      candidate.slug === captured.slug &&
      candidate.topic === captured.proposedTopic,
  );
  if (!paper?.topic) {
    throw new ZoteroError("Imported Zotero paper could not be found.");
  }
  associate(catalog, target, item.key, paper);
  await writeZoteroCatalog(activity.capability, catalog);
  rebuildIndex();
  return { created: true, topic: paper.topic, slug: paper.slug };
}

export async function importCatalogItem(
  capability: ProfileCapability,
  itemKey: string,
): Promise<ZoteroImportResult> {
  const { username } = capability;
  const activity = beginProfileActivity(capability);
  if (!activity) {
    throw new ZoteroCatalogItemNotFoundError(
      "The importing profile was deleted.",
    );
  }
  try {
    return await withZoteroLock(profileLockKey(username), 0, async () => {
      const profile = getProfile(username);
      const target = profile?.zotero ? targetOf(profile.zotero) : null;
      if (!target) {
        throw new ZoteroCatalogItemNotFoundError("Zotero is not connected.");
      }
      return withZoteroLock(
        itemLockKey(target.type, target.id, itemKey),
        IMPORT_LOCK_WAIT_MS,
        () => importLocked(username, itemKey, activity),
      );
    });
  } finally {
    activity.finish();
  }
}

export interface ZoteroAnnotationContext {
  pageLabel: string | null;
  text: string;
  comment: string;
}

function cleanAnnotation(value: string | undefined): string {
  return (value ?? "")
    .replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g, "")
    .trim()
    .slice(0, 4_000);
}

export async function annotationsForPaper(
  capability: ProfileCapability,
  paper: Paper,
): Promise<ZoteroAnnotationContext[]> {
  const identity = new PapernookIdentityStore(dataRoot());
  return withProfileActivity(identity, capability, async () => {
    const { username } = capability;
    const profile = getProfile(username);
    const cfg = profile?.zotero;
    if (!cfg || !paper.topic) return [];
    const target = targetOf(cfg);
    const catalog = await readZoteroCatalog(capability);
    const association = Object.values(catalog.associations).find(
      (candidate) =>
        candidate.libraryType === target.type &&
        candidate.libraryId === target.id &&
        candidate.topic === paper.topic &&
        candidate.slug === paper.slug,
    );
    const library = catalog.libraries[libraryIdentity(target)];
    if (!association || !library) return [];
    const item = library.records[association.itemKey];
    if (
      !item ||
      !visibleParentRecords(cfg, library).some(
        (candidate) => candidate.key === association.itemKey,
      )
    ) {
      return [];
    }
    const attachmentKeys = new Set(
      attachmentsFor(library, item).map((attachment) => attachment.key),
    );
    const matching = [];
    for (const record of Object.values(library.records)) {
      if (
        record.itemType === "annotation" &&
        record.parentItem &&
        attachmentKeys.has(record.parentItem)
      ) {
        matching.push(record);
        if (matching.length >= MAX_ANNOTATION_RECORDS) break;
      }
    }
    matching.sort(
      (a, b) =>
        (a.annotationSortIndex ?? "").localeCompare(
          b.annotationSortIndex ?? "",
        ) || a.key.localeCompare(b.key),
    );
    const annotations: ZoteroAnnotationContext[] = [];
    let chars = 0;
    for (const record of matching) {
      const annotation = {
        pageLabel: optional(record.annotationPageLabel) ?? null,
        text: cleanAnnotation(record.annotationText),
        comment: cleanAnnotation(record.annotationComment),
      };
      if (!annotation.text && !annotation.comment) continue;
      const nextChars =
        chars +
        annotation.text.length +
        annotation.comment.length +
        (annotation.pageLabel?.length ?? 0);
      if (nextChars > MAX_ANNOTATION_CHARS) break;
      chars = nextChars;
      annotations.push(annotation);
    }
    return withProfileFiles(identity, capability, () => annotations);
  });
}

export async function disconnectZotero(
  token: string,
  capability: ProfileCapability,
): Promise<void> {
  const { username } = capability;
  const identity = new PapernookIdentityStore(dataRoot());
  return withProfileActivity(identity, capability, () =>
    withZoteroLock(profileLockKey(username), 0, async () => {
      await setZoteroConfig(username, null, token);
      await deleteZoteroCatalog(capability);
    }),
  );
}

export class ZoteroConfigConflictError extends Error {
  constructor() {
    super("Zotero settings changed. Refresh and try again.");
  }
}

export async function saveZoteroConfig(
  token: string,
  capability: ProfileCapability,
  config: ZoteroProfileConfig,
  expected: ZoteroProfileConfig | undefined,
): Promise<Profile> {
  const { username } = capability;
  const identity = new PapernookIdentityStore(dataRoot());
  return withProfileActivity(identity, capability, () =>
    withZoteroLock(profileLockKey(username), 0, async () => {
      if (!isDeepStrictEqual(getProfile(username)?.zotero, expected))
        throw new ZoteroConfigConflictError();
      return setZoteroConfig(username, config, token);
    }),
  );
}

import { z } from "zod";
import {
  listProfiles,
  type ZoteroLibraryTarget,
  type ZoteroProfileConfig,
} from "../auth/users";
import {
  beginProfileActivity,
  type ProfileActivity,
} from "../auth/profile-activity";
import {
  profileCapability,
  type ProfileCapability,
} from "../auth/profile-capability";
import { PapernookIdentityStore } from "../auth/identity-store";
import { dataRoot } from "../data-dir";
import { rebuildIndex } from "../library/index-db";
import {
  listPapers,
  updateMeta,
  type CitationAuthor,
  type CitationMeta,
  type CitationType,
  type Paper,
  type PaperMeta,
  type PaperSource,
} from "../library/papers";
import { MAX_PDF_BYTES } from "./download";
import { readBoundedResponse, ResponseTooLargeError } from "./bounded-response";
import {
  associationIdentity,
  catalogRecordSchema,
  emptyLibrary,
  libraryIdentity,
  MAX_CATALOG_BYTES,
  MAX_CATALOG_RECORDS,
  readZoteroCatalog,
  writeZoteroCatalog,
  type ZoteroAssociation,
  type ZoteroCatalogLibrary,
  type ZoteroCatalogRecord,
} from "./zotero-catalog";
import { profileLockKey, withZoteroLock, ZoteroBusyError } from "./zotero-lock";
import {
  collectionSchema,
  groupSchema,
  itemSchema,
  keyResponseSchema,
  type ZoteroItemData,
} from "./zotero/schemas";

/**
 * Metadata-first Zotero bridge. Scheduled work refreshes only a compact,
 * profile-private catalog. A PDF and its AI analysis enter Papernook only
 * after the profile explicitly imports one catalog item.
 */

const API = "https://api.zotero.org";
const SYNC_INTERVAL_MS = 30 * 60 * 1000;

export type ZoteroConfig = ZoteroProfileConfig;

export interface VerifiedZoteroKey {
  userId: string;
  username: string;
  personalLibrary: boolean;
  personalFiles: boolean;
}

export interface ZoteroCollectionOption {
  key: string;
  name: string;
  parentCollection: string | null;
}

export class ZoteroError extends Error {}
export class ZoteroPdfTooLargeError extends ZoteroError {}

export function targetOf(cfg: ZoteroConfig): ZoteroLibraryTarget {
  return (
    cfg.target ?? {
      type: "user",
      id: cfg.userId,
      name: "My Library",
    }
  );
}

function libraryPrefix(target: ZoteroLibraryTarget): string {
  return target.type === "user"
    ? `/users/${target.id}`
    : `/groups/${target.id}`;
}

function sortedUnique(values: string[] | undefined): string[] {
  return [...new Set(values ?? [])].sort((a, b) => a.localeCompare(b));
}

async function apiFetch(
  apiKey: string,
  pathname: string,
  search: Record<string, string> = {},
): Promise<Response> {
  const url = new URL(`${API}${pathname}`);
  for (const [key, value] of Object.entries(search)) {
    url.searchParams.set(key, value);
  }
  const response = await fetch(url, {
    headers: {
      "Zotero-API-Key": apiKey,
      "Zotero-API-Version": "3",
    },
    signal: AbortSignal.timeout(60_000),
  });
  if (!response.ok) {
    throw new ZoteroError(`Zotero API ${response.status} for ${pathname}`);
  }
  return response;
}

async function zoteroFetch(
  cfg: ZoteroConfig,
  pathname: string,
  search: Record<string, string> = {},
): Promise<Response> {
  return apiFetch(
    cfg.apiKey,
    `${libraryPrefix(targetOf(cfg))}${pathname}`,
    search,
  );
}

/** Validate a key, discover its owner, and retain the permissions we require. */
export async function verifyKey(
  apiKey: string,
): Promise<VerifiedZoteroKey | null> {
  const response = await fetch(`${API}/keys/current`, {
    headers: {
      "Zotero-API-Key": apiKey,
      "Zotero-API-Version": "3",
    },
  });
  if (!response.ok) return null;
  const parsed = keyResponseSchema.safeParse(await response.json());
  if (!parsed.success) return null;
  return {
    userId: String(parsed.data.userID),
    username: parsed.data.username ?? "",
    personalLibrary: parsed.data.access?.user?.library === true,
    personalFiles: parsed.data.access?.user?.files === true,
  };
}

/** Personal library plus groups visible to this key. */
export async function listLibraryTargets(
  cfg: ZoteroConfig,
  includePersonal = true,
): Promise<ZoteroLibraryTarget[]> {
  const groups: z.infer<typeof groupSchema>[] = [];
  for (let start = 0; ;) {
    const response = await apiFetch(cfg.apiKey, `/users/${cfg.userId}/groups`, {
      format: "json",
      limit: "100",
      start: String(start),
    });
    const parsed = z.array(groupSchema).safeParse(await response.json());
    if (!parsed.success) {
      throw new ZoteroError("Zotero returned invalid group libraries.");
    }
    groups.push(...parsed.data);
    start += parsed.data.length;
    if (parsed.data.length < 100) break;
  }
  return [
    ...(includePersonal
      ? [{ type: "user" as const, id: cfg.userId, name: "My Library" }]
      : []),
    ...groups
      .map((group): ZoteroLibraryTarget => ({
        type: "group",
        id: String(group.id),
        name: group.data.name,
      }))
      .sort((a, b) => a.name.localeCompare(b.name)),
  ];
}

export async function listCollections(
  cfg: ZoteroConfig,
): Promise<ZoteroCollectionOption[]> {
  const collections: ZoteroCollectionOption[] = [];
  let snapshotVersion: number | null = null;
  for (let start = 0; ;) {
    const response = await zoteroFetch(cfg, "/collections", {
      format: "json",
      limit: "100",
      start: String(start),
    });
    const headerVersion = Number(response.headers.get("Last-Modified-Version"));
    if (Number.isInteger(headerVersion) && headerVersion >= 0) {
      if (snapshotVersion !== null && snapshotVersion !== headerVersion) {
        throw new ZoteroError(
          "Zotero changed during collection pagination; retry later.",
        );
      }
      snapshotVersion = headerVersion;
    }
    const parsed = z.array(collectionSchema).safeParse(await response.json());
    if (!parsed.success) {
      throw new ZoteroError("Zotero returned invalid collections.");
    }
    collections.push(
      ...parsed.data.map(({ data }) => ({
        key: data.key,
        name: data.name,
        parentCollection:
          typeof data.parentCollection === "string"
            ? data.parentCollection
            : null,
      })),
    );
    start += parsed.data.length;
    if (parsed.data.length < 100) break;
  }
  return collections.sort((a, b) => a.name.localeCompare(b.name));
}

async function listChangedItems(
  cfg: ZoteroConfig,
  since: number,
): Promise<{
  records: Record<string, ZoteroCatalogRecord>;
  count: number;
  version: number;
}> {
  const records: Record<string, ZoteroCatalogRecord> = {};
  let projectedBytes = 0;
  let count = 0;
  let version = since;
  let snapshotVersion: number | null = null;
  for (let start = 0; ;) {
    const response = await zoteroFetch(cfg, "/items", {
      since: String(since),
      format: "json",
      limit: "100",
      start: String(start),
    });
    const headerVersion = Number(response.headers.get("Last-Modified-Version"));
    if (Number.isInteger(headerVersion) && headerVersion >= 0) {
      if (snapshotVersion !== null && snapshotVersion !== headerVersion) {
        throw new ZoteroError(
          "Zotero changed during catalog pagination; retrying later.",
        );
      }
      snapshotVersion = headerVersion;
      version = headerVersion;
    }
    const parsed = z.array(itemSchema).safeParse(await response.json());
    if (!parsed.success) {
      throw new ZoteroError("Zotero returned invalid items.");
    }
    for (const { data } of parsed.data) {
      const record = projectRecord(data);
      if (!records[data.key]) count += 1;
      records[data.key] = record;
      projectedBytes +=
        Buffer.byteLength(JSON.stringify(record), "utf8") + data.key.length + 8;
      if (count > MAX_CATALOG_RECORDS || projectedBytes > MAX_CATALOG_BYTES) {
        throw new ZoteroError(
          "Zotero metadata exceeds the local catalog safety limit.",
        );
      }
    }
    start += parsed.data.length;
    if (parsed.data.length < 100) break;
  }
  return { records, count, version };
}

const deletedSchema = z.object({
  items: z.array(z.string().min(1).max(64)).max(200_000).default([]),
});

async function listDeletedItems(
  cfg: ZoteroConfig,
  since: number,
): Promise<{ itemKeys: string[]; version: number }> {
  const response = await zoteroFetch(cfg, "/deleted", {
    since: String(since),
  });
  const parsed = deletedSchema.safeParse(await response.json());
  if (!parsed.success) {
    throw new ZoteroError("Zotero returned invalid deletion metadata.");
  }
  const headerVersion = Number(response.headers.get("Last-Modified-Version"));
  return {
    itemKeys: parsed.data.items,
    version:
      Number.isInteger(headerVersion) && headerVersion >= 0
        ? headerVersion
        : since,
  };
}

function attachmentPriority(item: ZoteroItemData): number {
  if (item.linkMode?.startsWith("imported_")) return 0;
  if (!item.linkMode) return 1;
  return 2;
}

function orderedAttachmentKeys(items: ZoteroItemData[]): string[] {
  return [...items]
    .sort(
      (a, b) =>
        attachmentPriority(a) - attachmentPriority(b) ||
        a.key.localeCompare(b.key),
    )
    .map((item) => item.key);
}

export async function downloadAttachment(
  cfg: ZoteroConfig,
  attachmentKey: string,
): Promise<Buffer> {
  const response = await zoteroFetch(cfg, `/items/${attachmentKey}/file`);
  let bytes: Buffer;
  try {
    bytes = await readBoundedResponse(response, MAX_PDF_BYTES);
  } catch (error) {
    if (error instanceof ResponseTooLargeError) {
      throw new ZoteroPdfTooLargeError(error.message);
    }
    throw error;
  }
  const contentType = response.headers.get("content-type") ?? "";
  if (
    !contentType.includes("application/pdf") &&
    bytes.subarray(0, 5).toString("latin1") !== "%PDF-"
  ) {
    throw new ZoteroError("Zotero attachment is not a PDF.");
  }
  return bytes;
}

function sourceMatches(
  paper: Paper,
  target: ZoteroLibraryTarget,
  username: string,
  key?: string,
): boolean {
  const source = paper.meta.source;
  if (source?.provider !== "zotero") return false;
  if (key && source.key !== key) return false;
  if (source.libraryType && source.libraryId) {
    return source.libraryType === target.type && source.libraryId === target.id;
  }
  return (
    target.type === "user" &&
    paper.meta.addedBy === username &&
    source.libraryId === undefined
  );
}

export function arxivIdOf(item: ZoteroItemData): string | null {
  const haystack = `${item.url ?? ""} ${item.extra ?? ""}`;
  const match = haystack.match(/arxiv[^0-9]{0,15}(\d{4}\.\d{4,5})/i);
  return match ? match[1] : null;
}

const TYPE_MAP: Record<string, CitationType> = {
  journalArticle: "article-journal",
  conferencePaper: "paper-conference",
  book: "book",
  bookSection: "chapter",
  thesis: "thesis",
  report: "report",
  manuscript: "manuscript",
  webpage: "webpage",
  dataset: "dataset",
  preprint: "article",
};

export function optional(value: string | undefined): string | undefined {
  const trimmed = value?.trim();
  return trimmed || undefined;
}

function normalizedDoi(value: string | undefined): string | undefined {
  const doi = value
    ?.trim()
    .replace(/^https?:\/\/(?:dx\.)?doi\.org\//i, "")
    .replace(/^doi:\s*/i, "");
  return doi && /^10\.\d{4,9}\/\S+$/i.test(doi) ? doi : undefined;
}

export function citationAuthors(item: ZoteroItemData): CitationAuthor[] {
  return (item.creators ?? [])
    .filter(
      (creator) => !creator.creatorType || creator.creatorType === "author",
    )
    .map<CitationAuthor>((creator) => {
      const literal = optional(creator.name);
      if (literal) return { literal };
      const family = optional(creator.lastName);
      const given = optional(creator.firstName);
      return {
        ...(family ? { family } : {}),
        ...(given ? { given } : {}),
      };
    })
    .filter((creator) => creator.literal || creator.family || creator.given);
}

function citationOf(item: ZoteroItemData): CitationMeta {
  const DOI = normalizedDoi(item.DOI);
  const containerTitle = [
    item.publicationTitle,
    item.conferenceName,
    item.university,
  ]
    .map(optional)
    .find(Boolean);
  const publisher = [item.publisher, item.institution]
    .map(optional)
    .find(Boolean);
  const volume = optional(item.volume);
  const issue = optional(item.issue);
  const pages = optional(item.pages);
  const publisherPlace = optional(item.place);
  const abstract = optional(item.abstractNote);
  const URL = optional(item.url);
  const language = optional(item.language);
  const ISBN = optional(item.ISBN);
  const ISSN = optional(item.ISSN);
  return {
    type: TYPE_MAP[item.itemType] ?? "document",
    authors: citationAuthors(item),
    ...(DOI ? { DOI } : {}),
    ...(containerTitle ? { containerTitle } : {}),
    ...(volume ? { volume } : {}),
    ...(issue ? { issue } : {}),
    ...(pages ? { pages } : {}),
    ...(publisher ? { publisher } : {}),
    ...(publisherPlace ? { publisherPlace } : {}),
    ...(abstract ? { abstract } : {}),
    ...(URL ? { URL } : {}),
    ...(language ? { language } : {}),
    ...(ISBN ? { ISBN } : {}),
    ...(ISSN ? { ISSN } : {}),
  };
}

export function overridesOf(item: ZoteroItemData): Partial<PaperMeta> {
  const title = optional(item.title);
  const authors = citationAuthors(item).map(
    (author) =>
      author.literal ?? [author.given, author.family].filter(Boolean).join(" "),
  );
  const year = item.date?.match(/\b(\d{4})\b/);
  const venue = optional(
    item.publicationTitle ?? item.conferenceName ?? item.university,
  );
  return {
    ...(title ? { title } : {}),
    authors,
    year: year ? Number(year[1]) : null,
    venue: venue ?? null,
    citation: citationOf(item),
  };
}

export function sourceTags(item: ZoteroItemData): string[] {
  const tags = new Map<string, string>();
  for (const { tag: raw } of item.tags ?? []) {
    const tag = raw.trim();
    if (tag && !tags.has(tag.toLocaleLowerCase())) {
      tags.set(tag.toLocaleLowerCase(), tag);
    }
  }
  return [...tags.values()];
}

function collectionNamesFor(
  keys: string[],
  collections: Map<string, ZoteroCollectionOption>,
): string[] {
  return keys
    .map((key) => collections.get(key)?.name)
    .filter((name): name is string => Boolean(name))
    .sort((a, b) => a.localeCompare(b));
}

export function sourceOf(
  item: ZoteroItemData,
  target: ZoteroLibraryTarget,
  collections: Map<string, ZoteroCollectionOption>,
): PaperSource {
  const collectionKeys = sortedUnique(item.collections);
  return {
    provider: "zotero",
    key: item.key,
    version: item.version,
    libraryType: target.type,
    libraryId: target.id,
    collectionKeys,
    collections: collectionNamesFor(collectionKeys, collections),
    tags: sourceTags(item),
  };
}

function mergeRefreshedTags(
  current: string[],
  previousSourceTags: string[] | undefined,
  nextSourceTags: string[],
): string[] {
  const previous = new Set(
    (previousSourceTags ?? []).map((tag) => tag.toLocaleLowerCase()),
  );
  const merged = new Map<string, string>();
  for (const tag of current) {
    if (!previous.has(tag.toLocaleLowerCase())) {
      merged.set(tag.toLocaleLowerCase(), tag);
    }
  }
  for (const tag of nextSourceTags) {
    merged.set(tag.toLocaleLowerCase(), tag);
  }
  return [...merged.values()];
}

function refreshPaper(
  paper: Paper,
  item: ZoteroItemData,
  target: ZoteroLibraryTarget,
  collections: Map<string, ZoteroCollectionOption>,
): void {
  const overrides = overridesOf(item);
  const source = sourceOf(item, target, collections);
  updateMeta(paper.topic, paper.slug, (current) => ({
    ...current,
    ...overrides,
    sourceUrl: optional(item.url) ?? current.sourceUrl,
    tags: mergeRefreshedTags(
      current.tags,
      current.source?.tags,
      source.tags ?? [],
    ),
    source,
  }));
}

function expandedCollectionKeys(
  selected: string[],
  collections: Map<string, ZoteroCollectionOption>,
): Set<string> | null {
  if (selected.length === 0) return null;
  for (const key of selected) {
    if (!collections.has(key)) {
      throw new ZoteroError(
        `Selected Zotero collection ${key} is no longer accessible.`,
      );
    }
  }
  const expanded = new Set(selected);
  let changed = true;
  while (changed) {
    changed = false;
    for (const collection of collections.values()) {
      if (
        collection.parentCollection &&
        expanded.has(collection.parentCollection) &&
        !expanded.has(collection.key)
      ) {
        expanded.add(collection.key);
        changed = true;
      }
    }
  }
  return expanded;
}

function inSelectedCollections(
  item: ZoteroItemData,
  selected: Set<string> | null,
): boolean {
  if (!selected) return true;
  return (item.collections ?? []).some((key) => selected.has(key));
}

function isBibliographic(item: ZoteroItemData): boolean {
  return !["attachment", "note", "annotation"].includes(item.itemType);
}

function isPdfAttachment(item: ZoteroItemData): boolean {
  return (
    item.itemType === "attachment" && item.contentType === "application/pdf"
  );
}

function projectRecord(item: ZoteroItemData): ZoteroCatalogRecord {
  return catalogRecordSchema.parse(item);
}

export function collectionMap(
  library: ZoteroCatalogLibrary,
): Map<string, ZoteroCollectionOption> {
  return new Map(
    library.collections.map((collection) => [collection.key, collection]),
  );
}

function selectedCollections(
  cfg: ZoteroConfig,
  library: ZoteroCatalogLibrary,
): Set<string> | null {
  return expandedCollectionKeys(
    sortedUnique(cfg.collectionKeys),
    collectionMap(library),
  );
}

function isStandalonePdf(item: ZoteroCatalogRecord): boolean {
  return isPdfAttachment(item) && !item.parentItem;
}

export function visibleParentRecords(
  cfg: ZoteroConfig,
  library: ZoteroCatalogLibrary,
): ZoteroCatalogRecord[] {
  const selected = selectedCollections(cfg, library);
  return Object.values(library.records).filter(
    (item) =>
      (isBibliographic(item) || isStandalonePdf(item)) &&
      inSelectedCollections(item, selected),
  );
}

export function attachmentsFor(
  library: ZoteroCatalogLibrary,
  item: ZoteroCatalogRecord,
): ZoteroCatalogRecord[] {
  if (isStandalonePdf(item)) return [item];
  return Object.values(library.records).filter(
    (candidate) =>
      candidate.parentItem === item.key && isPdfAttachment(candidate),
  );
}

export function storedAttachmentKeys(
  library: ZoteroCatalogLibrary,
  item: ZoteroCatalogRecord,
): string[] {
  return orderedAttachmentKeys(attachmentsFor(library, item)).filter((key) => {
    const attachment = library.records[key];
    return attachment?.linkMode !== "linked_file";
  });
}

export function associationFor(
  associations: Record<string, ZoteroAssociation>,
  target: ZoteroLibraryTarget,
  itemKey: string,
): ZoteroAssociation | undefined {
  return associations[associationIdentity(target, itemKey)];
}

export function existingPaperFor(
  username: string,
  target: ZoteroLibraryTarget,
  item: ZoteroCatalogRecord,
): Paper | null {
  const exact = listPapers().find((paper) =>
    sourceMatches(paper, target, username, item.key),
  );
  if (exact) return exact;
  const arxivId = arxivIdOf(item);
  if (arxivId) {
    const arxiv = listPapers().find((paper) => paper.meta.arxivId === arxivId);
    if (arxiv) return arxiv;
  }
  const doi = normalizedDoi(item.DOI);
  if (!doi) return null;
  return (
    listPapers().find(
      (paper) =>
        normalizedDoi(paper.meta.citation?.DOI)?.toLocaleLowerCase() ===
        doi.toLocaleLowerCase(),
    ) ?? null
  );
}

export function associate(
  catalog: Awaited<ReturnType<typeof readZoteroCatalog>>,
  target: ZoteroLibraryTarget,
  itemKey: string,
  paper: Paper,
): void {
  if (!paper.topic) {
    throw new ZoteroError("Imported Zotero paper is not filed.");
  }
  catalog.associations[associationIdentity(target, itemKey)] = {
    libraryType: target.type,
    libraryId: target.id,
    itemKey,
    topic: paper.topic,
    slug: paper.slug,
  };
}

function paperNeedsRefresh(
  paper: Paper,
  item: ZoteroCatalogRecord,
  collections: Map<string, ZoteroCollectionOption>,
): boolean {
  const source = paper.meta.source;
  if (!source) return false;
  return (
    source.version !== item.version ||
    JSON.stringify(source.collectionKeys ?? []) !==
      JSON.stringify(sortedUnique(item.collections)) ||
    JSON.stringify(source.collections ?? []) !==
      JSON.stringify(
        collectionNamesFor(sortedUnique(item.collections), collections),
      ) ||
    JSON.stringify(source.tags ?? []) !== JSON.stringify(sourceTags(item))
  );
}

function associateMaterializedPapers(
  username: string,
  target: ZoteroLibraryTarget,
  library: ZoteroCatalogLibrary,
  catalog: Awaited<ReturnType<typeof readZoteroCatalog>>,
): void {
  for (const paper of listPapers()) {
    if (!paper.topic || !sourceMatches(paper, target, username)) continue;
    const item = library.records[paper.meta.source!.key];
    if (!item || !isBibliographic(item)) continue;
    associate(catalog, target, item.key, paper);
  }
}

function refreshMaterializedPapers(
  username: string,
  target: ZoteroLibraryTarget,
  library: ZoteroCatalogLibrary,
): number {
  const collections = collectionMap(library);
  let refreshed = 0;
  for (const paper of listPapers()) {
    if (!paper.topic || !sourceMatches(paper, target, username)) continue;
    const item = library.records[paper.meta.source!.key];
    if (!item || !isBibliographic(item)) continue;
    if (!paperNeedsRefresh(paper, item, collections)) continue;
    refreshPaper(paper, item, target, collections);
    refreshed += 1;
  }
  return refreshed;
}

const inFlight = new Set<string>();
const cancelled = new Set<string>();

export interface ZoteroSyncResult {
  /** Scheduled refreshes never import PDFs. */
  imported: 0;
  discovered: number;
  updated: number;
  skipped: number;
  removed: number;
  available: number;
  failed: number;
}

const lastResults = new Map<string, ZoteroSyncResult>();

export function isSyncing(username: string): boolean {
  return inFlight.has(username);
}

export function lastSyncResult(username: string): ZoteroSyncResult | null {
  return lastResults.get(username) ?? null;
}

/** Stop and forget transient sync state before a profile is erased. */
export function cancelProfileSync(username: string): void {
  if (inFlight.has(username)) cancelled.add(username);
  else cancelled.delete(username);
  lastResults.delete(username);
}

async function refreshCatalog(
  capability: ProfileCapability,
  cfg: ZoteroConfig,
  isCancelled: () => boolean,
): Promise<ZoteroSyncResult | null> {
  const { username } = capability;
  const target = targetOf(cfg);
  const identity = libraryIdentity(target);
  const catalog = await readZoteroCatalog(capability);
  const previous = catalog.libraries[identity] ?? emptyLibrary(target);
  const previousVisible = previous.refreshedAt
    ? visibleParentRecords(cfg, previous).length
    : 0;
  const [collections, changed, deleted] = await Promise.all([
    listCollections(cfg),
    listChangedItems(cfg, previous.lastVersion),
    listDeletedItems(cfg, previous.lastVersion),
  ]);
  if (isCancelled()) return null;
  const records = { ...previous.records };
  for (const key of deleted.itemKeys) delete records[key];
  Object.assign(records, changed.records);
  const safeVersion = Math.min(changed.version, deleted.version);
  const library: ZoteroCatalogLibrary = {
    target,
    lastVersion: safeVersion,
    refreshedAt: new Date().toISOString(),
    collections,
    records,
  };
  catalog.libraries[identity] = library;
  const available = visibleParentRecords(cfg, library).filter(
    (item) => storedAttachmentKeys(library, item).length > 0,
  ).length;
  associateMaterializedPapers(username, target, library, catalog);
  await writeZoteroCatalog(capability, catalog);
  if (isCancelled()) return null;
  const refreshedPapers = refreshMaterializedPapers(username, target, library);
  if (refreshedPapers > 0) rebuildIndex();
  const visible = visibleParentRecords(cfg, library).length;
  return {
    imported: 0,
    discovered: Math.max(0, visible - previousVisible),
    updated: changed.count + refreshedPapers,
    skipped: 0,
    removed: deleted.itemKeys.length + Math.max(0, previousVisible - visible),
    available,
    failed: 0,
  };
}

/** Refresh compact metadata only; no PDF bytes or AI provider are touched. */
export async function syncProfile(
  username: string,
  admission?: ProfileCapability,
): Promise<ZoteroSyncResult | null> {
  if (inFlight.has(username)) return null;
  cancelled.delete(username);
  inFlight.add(username);
  let activity: ProfileActivity | null = null;
  try {
    const snapshot = await new PapernookIdentityStore(dataRoot()).read();
    const profile = snapshot.profiles.find(
      (entry) => entry.username === username,
    );
    if (!profile || (admission && admission.username !== username)) return null;
    activity = beginProfileActivity(
      admission ?? profileCapability(snapshot, username),
    );
    if (!activity) return null;
    const lease = activity;
    const isCancelled = () => cancelled.has(username) || lease.cancelled();
    const result = await withZoteroLock(
      profileLockKey(username),
      0,
      async () => {
        const current = await new PapernookIdentityStore(dataRoot()).read();
        if (isCancelled()) return null;
        const cfg = current.profiles.find(
          (entry) => entry.username === username,
        )?.zotero;
        if (!cfg) return null;
        return refreshCatalog(lease.capability, cfg, isCancelled);
      },
    );
    if (!result || isCancelled()) return null;
    lastResults.set(username, result);
    return result;
  } catch (error) {
    if (error instanceof ZoteroBusyError) return null;
    lastResults.set(username, {
      imported: 0,
      discovered: 0,
      updated: 0,
      skipped: 0,
      removed: 0,
      available: 0,
      failed: 1,
    });
    throw error;
  } finally {
    inFlight.delete(username);
    cancelled.delete(username);
    activity?.finish();
  }
}

/** Boot + every 30 min: sync every profile that connected Zotero. */
export function startZoteroSync(): () => void {
  const tick = async () => {
    for (const profile of listProfiles()) {
      if (!profile.zotero) continue;
      try {
        await syncProfile(profile.username);
      } catch (error) {
        console.error(`zotero sync failed for ${profile.username}:`, error);
      }
    }
  };
  void tick();
  const timer = setInterval(() => void tick(), SYNC_INTERVAL_MS);
  timer.unref?.();
  return () => clearInterval(timer);
}

/**
 * Turns a chat answer into something pdf.js can save as a FreeText
 * annotation. The worker builds the appearance stream with the standard
 * Helvetica font in WinAnsiEncoding and bails out of drawing any line it
 * cannot encode, so the text is transliterated to that repertoire; it also
 * draws each line as-is (shrinking the font when a line overflows the
 * rect), so lines are wrapped here rather than by the viewer.
 */

import { findPaperRefs, type PaperRefKind } from "@/lib/pdf/paper-refs";

export const NOTE_FONT_SIZE = 9;
/** pdf.js LINE_FACTOR: the worker lays FreeText lines out at 1.35 × size. */
export const NOTE_LINE_HEIGHT = 1.35 * NOTE_FONT_SIZE;
export const NOTE_WIDTH = 150;
const NOTE_MARGIN = 12;
export const NOTE_CHARS_PER_LINE = 30;
export const NOTE_MAX_LINES = 40;

const TRANSLITERATIONS: [RegExp, string][] = [
  [/[\u2010-\u2015\u2212]/g, "-"],
  [/[‘’‚‛′]/g, "'"],
  [/[“”„‟″]/g, '"'],
  [/…/g, "..."],
  [/≤/g, "<="],
  [/≥/g, ">="],
  [/≠/g, "!="],
  [/≈/g, "~"],
  [/→/g, "->"],
  [/←/g, "<-"],
  [/↔/g, "<->"],
  [/⇒/g, "=>"],
  [/•/g, "-"],
  [/[\u00a0\u2000-\u200b\u202f\u3000]/g, " "],
  [/⁄/g, "/"],
  // Soft hyphens survive copy-paste from PDFs but Helvetica's WinAnsi map has
  // no glyph for U+00AD (0xAD is a plain hyphen), which voids the appearance.
  [/\u00ad/g, ""],
];

// WinAnsi covers printable ASCII, Latin-1 (U+00A0..U+00FF) and a handful of
// typographic characters mapped into 0x80..0x9F.
const WINANSI_HIGH = new Set("€‚ƒ„…†‡ˆ‰Š‹ŒŽ‘’“”•–—˜™š›œžŸ");

function isWinAnsi(char: string): boolean {
  const code = char.codePointAt(0) ?? 0;
  if (code >= 0x20 && code <= 0x7e) return true;
  if (code >= 0xa0 && code <= 0xff) return true;
  return WINANSI_HIGH.has(char);
}

function stripMarkdown(markdown: string): string {
  return (
    markdown
      .replace(/\r\n?/g, "\n")
      // Fence markers go, their content stays as plain text.
      .replace(/^[ \t]*(?:```|~~~)[^\n]*$/gm, "")
      // Only tag-shaped runs (`<br>`, `</sup>`, `<a href="…">`): inline
      // inequalities such as "a<b and c>d" must survive.
      .replace(
        /<\/?[A-Za-z][A-Za-z0-9-]*(?:\s+[A-Za-z-]+="[^"\n]*")*\s*\/?>/g,
        "",
      )
      .replace(/!\[([^\]]*)\]\([^)]*\)/g, "$1")
      .replace(/\[([^\]]+)\]\([^)]*\)/g, "$1")
      .replace(/^[ \t]{0,3}#{1,6}[ \t]+/gm, "")
      .replace(/^[ \t]*>[ \t]?/gm, "")
      .replace(/^[ \t]*[-*+][ \t]+/gm, "- ")
      .replace(/^[ \t]*(\d+)[.)][ \t]+/gm, "$1. ")
      .replace(/(\*\*|__)(?=\S)([\s\S]*?\S)\1/g, "$2")
      .replace(/(^|[^\w*])\*(?=\S)([^*\n]*?\S)\*/g, "$1$2")
      .replace(/(^|[^\w_])_(?=\S)([^_\n]*?\S)_/g, "$1$2")
      .replace(/~~(?=\S)([^~\n]*?\S)~~/g, "$1")
      .replace(/`([^`\n]*)`/g, "$1")
      .replace(/^[ \t]*(?:[-*_][ \t]*){3,}$/gm, "")
  );
}

/** Plain WinAnsi text: markdown syntax stripped, typography flattened. */
export function marginNoteText(markdown: string): string {
  let text = stripMarkdown(markdown);
  for (const [pattern, replacement] of TRANSLITERATIONS) {
    text = text.replace(pattern, replacement);
  }
  text = Array.from(text)
    .filter((char) => char === "\n" || char === "\t" || isWinAnsi(char))
    .join("")
    .replace(/\t/g, "  ");
  return text
    .split("\n")
    .map((line) => line.replace(/[ ]{2,}/g, " ").trim())
    .join("\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

function wrapParagraph(paragraph: string, charsPerLine: number): string[] {
  const lines: string[] = [];
  let current = "";
  const push = () => {
    if (current) lines.push(current);
    current = "";
  };
  for (const word of paragraph.split(" ")) {
    let rest = word;
    while (rest.length > charsPerLine) {
      push();
      lines.push(rest.slice(0, charsPerLine));
      rest = rest.slice(charsPerLine);
    }
    if (!rest) continue;
    if (!current) {
      current = rest;
    } else if (current.length + 1 + rest.length <= charsPerLine) {
      current += ` ${rest}`;
    } else {
      push();
      current = rest;
    }
  }
  push();
  return lines;
}

/**
 * Word-wrap into at most `maxLines` lines of at most `charsPerLine`
 * characters; blank lines separate paragraphs. A truncated note ends in an
 * ellipsis so the reader knows to open the chat for the rest.
 */
export function wrapNote(
  text: string,
  charsPerLine = NOTE_CHARS_PER_LINE,
  maxLines = NOTE_MAX_LINES,
): string[] {
  const lines: string[] = [];
  for (const paragraph of text.split("\n")) {
    if (paragraph.trim() === "") {
      if (lines.length > 0 && lines[lines.length - 1] !== "") lines.push("");
      continue;
    }
    lines.push(...wrapParagraph(paragraph.trim(), charsPerLine));
  }
  while (lines.length > 0 && lines[lines.length - 1] === "") lines.pop();
  if (lines.length <= maxLines) return lines;
  const kept = lines.slice(0, maxLines);
  const last = kept[maxLines - 1] ?? "";
  kept[maxLines - 1] =
    `${last.slice(0, Math.max(0, charsPerLine - 3)).trimEnd()}...`;
  return kept;
}

/**
 * PDF-space rect `[x1, y1, x2, y2]` for a note of `lines` lines hugging the
 * page's right margin. Top-aligned with `anchorTop` (a resolved
 * destination's y) when given, else just below the page's top edge; always
 * kept inside `pageView` (`[x0, y0, x1, y1]`, origin bottom-left).
 */
export function noteRect(
  pageView: readonly [number, number, number, number],
  lines: number,
  anchorTop: number | null = null,
): [number, number, number, number] {
  const [left, bottom, right, top] = pageView;
  const width = Math.min(NOTE_WIDTH, right - left);
  const x2 = right - Math.min(NOTE_MARGIN, (right - left - width) / 2);
  const x1 = x2 - width;
  const height = Math.max(1, lines) * NOTE_LINE_HEIGHT;
  const maxTop = top - NOTE_MARGIN;
  const minBottom = bottom + NOTE_MARGIN;
  let y2 = anchorTop === null ? maxTop : Math.min(anchorTop, maxTop);
  let y1 = y2 - height;
  if (y1 < minBottom) {
    y1 = minBottom;
    y2 = Math.min(maxTop, y1 + height);
  }
  const round = (value: number) => Math.round(value * 100) / 100;
  return [round(x1), round(y1), round(x2), round(y2)];
}

/** The first in-paper reference an answer mentions — where the note goes. */
export function firstLocator(
  markdown: string,
): { kind: PaperRefKind; label: string } | null {
  const ref = findPaperRefs(markdown)[0];
  return ref ? { kind: ref.kind, label: ref.label } : null;
}

/**
 * Pure helpers behind the "Sources & related work" card under an assistant
 * message: which external works an answer links to, minus the paper that is
 * already open. Shared with the Markdown renderer, which hides links back to
 * the current paper for the same reason.
 */

export type SourceKind = "arxiv" | "doi" | "github" | "web";

export interface Source {
  url: string;
  title: string;
  kind: SourceKind;
  host: string;
}

const MAX_TITLE_CHARS = 120;

/**
 * Canonical identity of a web URL so the same work linked two ways collapses
 * to one entry: arXiv abs/pdf/versioned → `arxiv:<id>`, DOI resolvers →
 * `doi:<doi>`, everything else host + path without trailing slash or
 * fragment.
 */
export function normalizedPaperIdentity(value: string): string | null {
  try {
    const url = new URL(value);
    if (url.protocol !== "http:" && url.protocol !== "https:") return null;
    const host = url.hostname.toLowerCase().replace(/^www\./, "");
    if (host === "arxiv.org") {
      const match = url.pathname.match(
        /^\/(?:abs|pdf)\/([^/]+?)(?:v\d+)?(?:\.pdf)?\/?$/i,
      );
      if (match?.[1]) return `arxiv:${match[1].toLowerCase()}`;
    }
    if (host === "doi.org" || host === "dx.doi.org") {
      const doi = decodeURIComponent(url.pathname.replace(/^\/+/, ""));
      if (doi) return `doi:${doi.toLowerCase()}`;
    }
    const path = url.pathname.replace(/\/+$/, "") || "/";
    return `${host}${path}`;
  } catch {
    return null;
  }
}

export function linksToCurrentPaper(
  href: string,
  paperSourceUrl?: string,
): boolean {
  if (!paperSourceUrl) return false;
  const hrefIdentity = normalizedPaperIdentity(href);
  return (
    hrefIdentity !== null &&
    hrefIdentity === normalizedPaperIdentity(paperSourceUrl)
  );
}

function sourceKind(url: string): SourceKind {
  const host = hostOf(url);
  if (host === "arxiv.org") return "arxiv";
  if (host === "doi.org" || host === "dx.doi.org") return "doi";
  if (host === "github.com") return "github";
  return "web";
}

/**
 * A GitHub file permalink ("/blob/<sha>/path#L1-L2") is an inline code
 * citation the answer already links beside its excerpt, not a work to
 * list; only repository-level links qualify as sources.
 */
function isRepositoryFileLink(url: string): boolean {
  if (hostOf(url) !== "github.com") return false;
  try {
    return /^\/[^/]+\/[^/]+\/(blob|tree|blame|raw)\//.test(
      new URL(url).pathname,
    );
  } catch {
    return false;
  }
}

function hostOf(url: string): string {
  try {
    return new URL(url).hostname.toLowerCase().replace(/^www\./, "");
  } catch {
    return "";
  }
}

/** Readable stand-in for a bare URL the model did not title. */
function titleFromUrl(url: string, kind: SourceKind): string {
  const identity = normalizedPaperIdentity(url) ?? url;
  if (kind === "arxiv" && identity.startsWith("arxiv:")) {
    return `arXiv:${identity.slice("arxiv:".length)}`;
  }
  if (kind === "doi" && identity.startsWith("doi:")) {
    return `doi:${identity.slice("doi:".length)}`;
  }
  const bare = url.replace(/^https?:\/\/(?:www\.)?/i, "").replace(/\/+$/, "");
  return bare.length > MAX_TITLE_CHARS
    ? `${bare.slice(0, MAX_TITLE_CHARS - 1)}…`
    : bare;
}

/**
 * Fenced blocks, inline code, and embedded images never hold citations worth
 * surfacing: an `![alt](https://…/figure.png)` is a picture, not a source.
 */
function withoutCode(markdown: string): string {
  return markdown
    .replace(/^(```|~~~)[^\n]*\n[\s\S]*?^\1[ \t]*$/gm, " ")
    .replace(/`[^`\n]*`/g, " ")
    .replace(/!\[[^\]\n]*\]\([^)\n]*\)/g, " ");
}

/** Trailing punctuation that prose attaches to a bare URL is not part of it. */
function trimBareUrl(raw: string): string {
  let url = raw.replace(/[.,;:!?'"’”]+$/, "");
  while (url.endsWith(")") && countChar(url, "(") < countChar(url, ")")) {
    url = url.slice(0, -1).replace(/[.,;:!?'"’”]+$/, "");
  }
  return url;
}

function countChar(value: string, char: string): number {
  let count = 0;
  for (const c of value) if (c === char) count += 1;
  return count;
}

function cleanTitle(raw: string): string {
  const text = raw
    .replace(/[*_~`]/g, "")
    .replace(/\s+/g, " ")
    .trim();
  return text.length > MAX_TITLE_CHARS
    ? `${text.slice(0, MAX_TITLE_CHARS - 1)}…`
    : text;
}

/**
 * URLs a sources card still needs a library answer for: paper links (arXiv /
 * DOI) whose lookup is not already cached, deduplicated in first-appearance
 * order so one batched request covers the whole card.
 */
export function pendingLookupUrls(
  sources: readonly Source[],
  cachedKeys: ReadonlySet<string>,
): string[] {
  const pending: string[] = [];
  for (const source of sources) {
    if (source.kind !== "arxiv" && source.kind !== "doi") continue;
    if (cachedKeys.has(source.url) || pending.includes(source.url)) continue;
    pending.push(source.url);
  }
  return pending;
}

const MARKDOWN_LINK_RE =
  /\[([^\]\n]+)\]\((https?:\/\/[^\s)]+)(?:\s+"[^"\n]*")?\)/g;
const BARE_URL_RE = /https?:\/\/[^\s<>()[\]]+(?:\([^\s()]*\))?[^\s<>()[\]]*/g;

/**
 * Every external work an answer points at, in order of first appearance:
 * Markdown links first (their text becomes the title), then bare URLs the
 * model left unlinked. Links to the open paper are dropped; duplicates
 * collapse to the first mention, preferring a titled one.
 */
export function collectSources(
  markdown: string,
  paperSourceUrl?: string,
): Source[] {
  const prose = withoutCode(markdown);
  const seen = new Map<string, Source>();
  const sources: Source[] = [];

  function add(url: string, title: string | null): void {
    if (!/^https?:\/\//i.test(url)) return;
    if (linksToCurrentPaper(url, paperSourceUrl)) return;
    if (isRepositoryFileLink(url)) return;
    const identity = normalizedPaperIdentity(url);
    if (!identity) return;
    const kind = sourceKind(url);
    const existing = seen.get(identity);
    const isBareTitle = title === null;
    if (existing) {
      if (!isBareTitle && existing.title === titleFromUrl(existing.url, kind)) {
        existing.title = cleanTitle(title);
      }
      return;
    }
    const source: Source = {
      url,
      title: isBareTitle ? titleFromUrl(url, kind) : cleanTitle(title),
      kind,
      host: hostOf(url),
    };
    seen.set(identity, source);
    sources.push(source);
  }

  for (const match of prose.matchAll(MARKDOWN_LINK_RE)) {
    const title = cleanTitle(match[1]);
    add(match[2], /^https?:\/\//i.test(title) ? null : title);
  }
  const linkless = prose.replace(MARKDOWN_LINK_RE, " ");
  for (const match of linkless.matchAll(BARE_URL_RE)) {
    add(trimBareUrl(match[0]), null);
  }

  return sources;
}

import { unified } from "unified";
import remarkParse from "remark-parse";
import remarkGfm from "remark-gfm";
import remarkMath from "remark-math";

interface SyntaxNode {
  type: string;
  position?: { start: { offset?: number }; end: { offset?: number } };
  children?: SyntaxNode[];
}

const parser = unified().use(remarkParse).use(remarkGfm).use(remarkMath);
const protectedTypes = new Set([
  "code",
  "inlineCode",
  "html",
  "link",
  "image",
  "definition",
  "linkReference",
  "imageReference",
  "math",
  "inlineMath",
]);

/** Accept exported LaTeX delimiters without changing code or saved source. */
export function normalizeMath(content: string): string {
  if (!/\\[([]/.test(content)) return content;
  const protectedRanges: [number, number][] = [];
  function visit(node: SyntaxNode) {
    const start = node.position?.start.offset;
    const end = node.position?.end.offset;
    if (
      protectedTypes.has(node.type) &&
      start !== undefined &&
      end !== undefined
    ) {
      protectedRanges.push([start, end]);
      return;
    }
    node.children?.forEach(visit);
  }
  visit(parser.parse(content));
  function convert(text: string) {
    return text.replace(
      /(?<!\\)\\\(([\s\S]*?)(?<!\\)\\\)|(?<!\\)\\\[([\s\S]*?)(?<!\\)\\\]/g,
      (
        match,
        inline: string | undefined,
        display: string | undefined,
        offset: number,
      ) => {
        const math = (inline ?? display ?? "").trim();
        if (!math || math.includes("$")) return match;
        if (inline !== undefined) return `$${math}$`;
        const before = text.slice(
          text.lastIndexOf("\n", offset - 1) + 1,
          offset,
        );
        const nextLine = text.indexOf("\n", offset + match.length);
        const after = text.slice(
          offset + match.length,
          nextLine < 0 ? text.length : nextLine,
        );
        // Keep equations embedded in list items and quotes in their container.
        if (before || after.trim()) return `$$${math}$$`;
        return `$$\n${math}\n$$`;
      },
    );
  }
  let cursor = 0;
  let result = "";
  for (const [start, end] of protectedRanges) {
    result += convert(content.slice(cursor, start)) + content.slice(start, end);
    cursor = end;
  }
  return result + convert(content.slice(cursor));
}

/**
 * Contract for the chat → PDF reference bridge. Chat decorations carry
 * their payload in data attributes; ChatPanel turns an activated button
 * into a `papernook:paper-ref` CustomEvent; PdfReader's bridge validates
 * the detail before acting. Chat content is AI output influenced by
 * web-downloaded paper text, so every field is treated as untrusted:
 * whitelisted kinds, bounded lengths, and shape checks — never trust
 * a parsed JSON blob structurally.
 */

import { NOTE_CHARS_PER_LINE, NOTE_MAX_LINES } from "@/lib/chat/margin-note";
import type { CitationKey } from "@/lib/pdf/citations";
import type { PaperRefKind } from "@/lib/pdf/paper-refs";

export const PAPER_REF_EVENT = "papernook:paper-ref";
/** PdfReader publishes the scanned bibliography for citation gating. */
export const BIBLIOGRAPHY_EVENT = "papernook:bibliography";

export type PaperRefAction = "goto" | "preview";

export type PaperRefEventDetail =
  | { action: PaperRefAction; ref: { kind: PaperRefKind; label: string } }
  | { action: "preview"; citation: CitationKey };

const KINDS: readonly PaperRefKind[] = [
  "figure",
  "table",
  "equation",
  "section",
  "algorithm",
  "appendix",
  "theorem",
  "lemma",
  "proposition",
  "definition",
  "corollary",
];

const LABEL_SHAPE = /^(?:\d+(?:\.\d+)*|[A-Z](?:(?:\.\d+)+|\d*)?)$/;

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

function parsePaperRef(
  value: unknown,
): { kind: PaperRefKind; label: string } | null {
  if (!isRecord(value)) return null;
  const { kind, label } = value;
  if (typeof kind !== "string" || typeof label !== "string") return null;
  if (!(KINDS as readonly string[]).includes(kind)) return null;
  if (label.length > 16 || !LABEL_SHAPE.test(label)) return null;
  return { kind: kind as PaperRefKind, label };
}

function parseCitationKey(value: unknown): CitationKey | null {
  if (!isRecord(value)) return null;
  if (value.kind === "numeric") {
    const { number } = value;
    if (typeof number !== "number" || !Number.isInteger(number)) return null;
    if (number < 1 || number > 999) return null;
    return { kind: "numeric", number };
  }
  if (value.kind === "authorYear") {
    const { surname, year, suffix } = value;
    if (typeof surname !== "string" || surname.length === 0) return null;
    if (surname.length > 80) return null;
    if (typeof year !== "string" || !/^(?:19|20)\d{2}$/.test(year)) {
      return null;
    }
    if (suffix !== null && (typeof suffix !== "string" || suffix.length > 1)) {
      return null;
    }
    return { kind: "authorYear", surname, year, suffix };
  }
  return null;
}

/** Validate a CustomEvent detail from the chat side. Null: ignore it. */
export function parsePaperRefEvent(
  detail: unknown,
): PaperRefEventDetail | null {
  if (!isRecord(detail)) return null;
  const { action } = detail;
  if ("ref" in detail && (action === "goto" || action === "preview")) {
    const ref = parsePaperRef(detail.ref);
    return ref ? { action, ref } : null;
  }
  if ("citation" in detail && action === "preview") {
    const citation = parseCitationKey(detail.citation);
    return citation ? { action: "preview", citation } : null;
  }
  return null;
}

function parseJson(raw: string | undefined): unknown {
  if (!raw || raw.length > 200) return null;
  try {
    return JSON.parse(raw) as unknown;
  } catch {
    return null;
  }
}

/**
 * Build the event detail for an activated decoration button.
 * `dataset.paperRef` / `dataset.citation` hold the JSON the rehype
 * decorator emitted; citations only ever preview.
 */
export function detailFromDataset(
  dataset: { paperRef?: string; citation?: string },
  action: PaperRefAction,
): PaperRefEventDetail | null {
  const ref = parsePaperRef(parseJson(dataset.paperRef));
  if (ref) return { action, ref };
  const citation = parseCitationKey(parseJson(dataset.citation));
  if (citation) return { action: "preview", citation };
  return null;
}

/**
 * Reverse direction: any surface (a reference popover, a text selection)
 * hands the chat composer a prompt. The chat fills its input, focuses it,
 * and sends immediately only when the requester asks for it.
 */
export const CHAT_PROMPT_EVENT = "papernook:chat-prompt";
export const CHAT_PROMPT_MAX_CHARS = 4000;

export interface ChatPromptDetail {
  text: string;
  send: boolean;
}

export function chatPromptDetail(
  text: string,
  options: { send?: boolean } = {},
): ChatPromptDetail {
  return {
    text: text.slice(0, CHAT_PROMPT_MAX_CHARS),
    send: options.send === true,
  };
}

export function requestChatPrompt(
  text: string,
  options: { send?: boolean } = {},
): void {
  window.dispatchEvent(
    new CustomEvent(CHAT_PROMPT_EVENT, {
      detail: chatPromptDetail(text, options),
    }),
  );
}

/** Validate a chat-prompt CustomEvent detail. Null: ignore it. */
export function parseChatPromptEvent(detail: unknown): ChatPromptDetail | null {
  if (!isRecord(detail)) return null;
  const { text, send } = detail;
  if (typeof text !== "string" || text.trim().length === 0) return null;
  if (text.length > CHAT_PROMPT_MAX_CHARS) return null;
  return { text, send: send === true };
}

/**
 * Chat → PDF: save an answer into the paper as a FreeText margin note. The
 * chat pre-wraps the text (see `@/lib/chat/margin-note`); `ref` is the
 * answer's first in-paper locator so the note lands on the page it talks
 * about, else the reader's current page. The bounds are exactly what the
 * composer can emit: `wrapNote`'s line cap and its per-line width plus the
 * newline joining each line.
 */
export const MARGIN_NOTE_EVENT = "papernook:margin-note";
export const MARGIN_NOTE_MAX_LINES = NOTE_MAX_LINES;
export const MARGIN_NOTE_MAX_CHARS = NOTE_MAX_LINES * (NOTE_CHARS_PER_LINE + 1);

export interface MarginNoteDetail {
  text: string;
  ref: { kind: PaperRefKind; label: string } | null;
}

export function requestMarginNote(detail: MarginNoteDetail): void {
  window.dispatchEvent(new CustomEvent(MARGIN_NOTE_EVENT, { detail }));
}

/** Validate a margin-note CustomEvent detail. Null: ignore it. */
export function parseMarginNoteEvent(detail: unknown): MarginNoteDetail | null {
  if (!isRecord(detail)) return null;
  const { text } = detail;
  if (typeof text !== "string" || text.trim().length === 0) return null;
  if (text.length > MARGIN_NOTE_MAX_CHARS) return null;
  if (text.split("\n").length > MARGIN_NOTE_MAX_LINES) return null;
  return { text, ref: "ref" in detail ? parsePaperRef(detail.ref) : null };
}

import type { Element, Root } from "hast";

function headingLevel(node: Element): number | null {
  const match = /^h([1-6])$/.exec(node.tagName);
  return match ? Number(match[1]) : null;
}

function numberedSectionLevel(node: Element): number | null {
  const level = headingLevel(node);
  if (level !== null && /^\d+[.)]\s/.test(textContent(node))) return level;
  const first = node.children[0];
  if (
    node.tagName === "p" &&
    first?.type === "element" &&
    first.tagName === "strong" &&
    /^\d+[.)]\s/.test(textContent(node))
  ) {
    return 2;
  }
  return null;
}

function textContent(node: Element): string {
  return node.children
    .map((child) => {
      if (child.type === "text") return child.value;
      if (child.type === "element") return textContent(child);
      return "";
    })
    .join("");
}

/** Wrap numbered Markdown headings and their following section in a disclosure. */
export function rehypeCollapsibleNumberedSections() {
  return (tree: Root): void => {
    const output: Root["children"] = [];
    for (let index = 0; index < tree.children.length; index += 1) {
      const node = tree.children[index];
      if (node.type !== "element") {
        output.push(node);
        continue;
      }
      const level = numberedSectionLevel(node);
      if (level === null) {
        output.push(node);
        continue;
      }
      const section: Element["children"] = [];
      index += 1;
      while (index < tree.children.length) {
        const next = tree.children[index];
        if (next.type === "doctype") {
          output.push(next);
          index += 1;
          continue;
        }
        if (
          next.type === "element" &&
          numberedSectionLevel(next) !== null &&
          (numberedSectionLevel(next) as number) <= level
        ) {
          index -= 1;
          break;
        }
        section.push(next);
        index += 1;
      }
      output.push({
        type: "element",
        tagName: "details",
        properties: { className: ["collapsibleSection"], open: true },
        children: [
          {
            type: "element",
            tagName: "summary",
            properties: {},
            children: node.children,
          },
          ...section,
        ],
      });
    }
    tree.children = output;
  };
}

import { fetchPublicUrl } from "@/lib/capture/download";
import { readBoundedResponse } from "@/lib/capture/bounded-response";
import {
  MAX_TRANSCRIPT_BYTES,
  sourceSchema,
  type ConversationSource,
} from "./store";

type ObjectValue = Record<string, unknown>;
function object(value: unknown): ObjectValue | null {
  return value && typeof value === "object" && !Array.isArray(value)
    ? (value as ObjectValue)
    : null;
}
export function shareProvider(input: string): "chatgpt" | "claude" {
  const url = new URL(input);
  if (
    url.protocol !== "https:" ||
    url.username ||
    url.password ||
    url.port ||
    url.search ||
    url.hash
  )
    throw new Error(
      "Use a canonical HTTPS public share URL without query parameters.",
    );
  if (
    url.hostname === "chatgpt.com" &&
    /^\/share\/[a-f0-9-]{36}\/?$/.test(url.pathname)
  )
    return "chatgpt";
  if (
    url.hostname === "claude.ai" &&
    /^\/share\/[a-f0-9-]{36}\/?$/.test(url.pathname)
  )
    return "claude";
  throw new Error(
    "Supported share links are https://chatgpt.com/share/... and https://claude.ai/share/...",
  );
}
function textContent(value: unknown): string {
  if (typeof value === "string") return value;
  if (Array.isArray(value))
    return value.map(textContent).filter(Boolean).join("\n\n");
  const record = object(value);
  const type = record?.type ?? record?.content_type;
  if (
    typeof type === "string" &&
    /^(thinking|redacted_thinking|thoughts|reasoning_recap|model_editable_context|tool_use|tool_result)$/.test(
      type,
    )
  )
    return "";
  if (
    typeof type === "string" &&
    /^(image|image_url|image_asset_pointer|input_image|output_image|file|input_file|document|attachment|audio|video)(_|$)/.test(
      type,
    )
  )
    return "[Attachment unavailable in imported share]";
  return record
    ? textContent(record.parts ?? record.text ?? record.content)
    : "";
}
function message(
  value: unknown,
): ConversationSource["messages"][number] | null {
  const record = object(value);
  if (!record) return null;
  const metadata = object(record.metadata);
  if (
    metadata?.is_visually_hidden_from_conversation === true ||
    metadata?.is_redacted === true ||
    record.channel === "analysis" ||
    (typeof record.recipient === "string" && record.recipient !== "all")
  )
    return null;
  const author = object(record.author);
  const role =
    author?.role ??
    record.role ??
    (record.sender === "human" ? "user" : record.sender);
  if (role !== "user" && role !== "assistant") return null;
  const content = textContent(record.content ?? record.text).trim();
  return content ? { role, content } : null;
}
function transcript(value: unknown): ConversationSource["messages"] | null {
  const record = object(value);
  if (!record) return null;
  const mapping = object(record.mapping);
  if (mapping && typeof record.current_node === "string") {
    const nodes: unknown[] = [];
    const visited = new Set<string>();
    let id: unknown = record.current_node;
    while (typeof id === "string") {
      if (visited.has(id))
        throw new Error("Transcript contains a cyclic message branch.");
      visited.add(id);
      const node = object(mapping[id]);
      if (!node) throw new Error("Transcript message branch is incomplete.");
      nodes.push(node.message);
      id = node.parent;
    }
    return nodes.reverse().flatMap((value) => {
      const parsed = message(value);
      return parsed ? [parsed] : [];
    });
  }
  const messages =
    record.chat_messages ?? record.messages ?? record.linear_conversation;
  return Array.isArray(messages)
    ? messages.flatMap((value) => {
        const parsed = message(object(value)?.message ?? value);
        return parsed ? [parsed] : [];
      })
    : null;
}
function findTranscript(
  value: unknown,
): { title: string; messages: ConversationSource["messages"] } | null {
  const queue: unknown[] = [value];
  const seen = new Set<unknown>();
  for (let count = 0; queue.length && count < 100_000; count++) {
    const current = queue.shift();
    if (!current || typeof current !== "object" || seen.has(current)) continue;
    seen.add(current);
    const found = transcript(current);
    if (found?.length) {
      const record = object(current);
      return {
        title:
          typeof record?.title === "string"
            ? record.title
            : typeof record?.name === "string"
              ? record.name
              : "Imported conversation",
        messages: found,
      };
    }
    queue.push(...Object.values(current));
  }
  return null;
}
function decodeReferences(table: unknown[]): unknown {
  const cache = new Map<number, unknown>();
  function resolve(index: number, depth = 0): unknown {
    if (depth > 200) throw new Error("Share payload nesting is too deep.");
    if (index < 0) return null;
    if (cache.has(index)) return cache.get(index);
    const raw = table[index];
    if (!raw || typeof raw !== "object") return raw;
    const result: unknown[] | ObjectValue = Array.isArray(raw) ? [] : {};
    cache.set(index, result);
    for (const [key, value] of Object.entries(raw)) {
      const name = key.startsWith("_")
        ? String(table[Number(key.slice(1))])
        : key;
      if (
        name === "__proto__" ||
        name === "constructor" ||
        name === "prototype"
      )
        continue;
      (result as ObjectValue)[name] =
        typeof value === "number" ? resolve(value, depth + 1) : value;
    }
    return result;
  }
  return resolve(0);
}
export function parseShareHtml(
  html: string,
  provider: "chatgpt" | "claude",
): ConversationSource {
  const candidates: unknown[] = [];
  for (const match of html.matchAll(
    /streamController\.enqueue\(("(?:[^"\\]|\\.)*")\)/g,
  )) {
    try {
      const table: unknown = JSON.parse(JSON.parse(match[1]));
      if (Array.isArray(table)) candidates.push(decodeReferences(table));
    } catch {
      /* Other stream events do not contain transcript tables. */
    }
  }
  for (const match of html.matchAll(
    /(?:self\.)?__next_f\.push\(\[\d+,\s*("(?:[^"\\]|\\.)*")\]\)/g,
  )) {
    try {
      const flight: unknown = JSON.parse(match[1]);
      if (typeof flight !== "string") continue;
      for (const line of flight.split("\n")) {
        const row = /^[a-f0-9]+:(.*)$/.exec(line)?.[1];
        if (!row || !["{", "["].includes(row[0])) continue;
        try {
          candidates.push(JSON.parse(row));
        } catch {
          /* Non-JSON Flight rows are not transcript data. */
        }
      }
    } catch {
      /* Reject unsupported share payloads below. */
    }
  }
  for (const match of html.matchAll(
    /<script\b[^>]*type=["']application\/json["'][^>]*>([\s\S]*?)<\/script>/gi,
  )) {
    try {
      candidates.push(JSON.parse(match[1]));
    } catch {
      /* Reject unsuccessful extraction below. */
    }
  }
  for (const candidate of candidates) {
    const found = findTranscript(candidate);
    if (found)
      return sourceSchema.parse({
        ...found,
        provider,
        topic: "Uncategorized",
        tags: [],
      });
  }
  throw new Error(
    "The provider did not expose a readable conversation. It may require login or block automated access. Import an exported JSON or Markdown transcript instead.",
  );
}
let inflight = 0;
export async function importShare(url: string): Promise<ConversationSource> {
  const provider = shareProvider(url);
  if (inflight >= 3)
    throw new Error("Too many imports are running. Try again shortly.");
  inflight++;
  try {
    const fetched = await fetchPublicUrl(url);
    if (!fetched.response.ok) {
      await fetched.response.body?.cancel();
      await fetched.close();
      throw new Error(
        `Share provider returned HTTP ${fetched.response.status}. Import an exported transcript instead.`,
      );
    }
    try {
      if (shareProvider(fetched.url) !== provider)
        throw new Error("Unexpected share redirect.");
    } catch (error) {
      await fetched.response.body?.cancel();
      await fetched.close();
      throw error;
    }
    const html = (
      await readBoundedResponse(
        fetched.response,
        8 * 1024 * 1024,
        fetched.close,
      )
    ).toString("utf8");
    return { ...parseShareHtml(html, provider), sourceUrl: url };
  } finally {
    inflight--;
  }
}
export function importTranscript(
  content: string,
  format: "json" | "markdown",
): ConversationSource {
  if (Buffer.byteLength(content) > MAX_TRANSCRIPT_BYTES)
    throw new Error("Transcript exceeds the 4 MB limit.");
  if (format === "markdown")
    return sourceSchema.parse({
      title: "Imported transcript",
      topic: "Uncategorized",
      tags: [],
      provider: "transcript",
      messages: [{ role: "user", content: content.trim() }],
    });
  let value: unknown;
  try {
    value = JSON.parse(content);
  } catch {
    value = content
      .split("\n")
      .filter((line) => line.trim())
      .map((line) => JSON.parse(line) as unknown);
  }
  if (Array.isArray(value)) {
    const messages = value.flatMap((entry) => {
      const record = object(entry);
      const payload = object(record?.payload);
      if (record?.type !== "response_item" || payload?.type !== "message")
        return [];
      const parsed = message(payload);
      return parsed ? [parsed] : [];
    });
    if (messages.length)
      return sourceSchema.parse({
        title: "Imported Codex session",
        topic: "Uncategorized",
        tags: [],
        provider: "codex",
        messages,
      });
  }
  const direct = sourceSchema.safeParse(value);
  if (direct.success) return direct.data;
  const found = findTranscript(value);
  if (!found)
    throw new Error(
      "JSON must contain a messages array with user/assistant roles and text content.",
    );
  return sourceSchema.parse({
    ...found,
    topic: "Uncategorized",
    tags: [],
    provider: "transcript",
  });
}

import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";
import { z } from "zod";
import { usersRoot, dataRoot } from "@/lib/data-dir";
import {
  acquireFileLockSync,
  FileLockBusyError,
} from "thesidedoor-core/storage";
import { assertSlug } from "@/lib/library/slug";
import type { Chat, ChatMessage } from "@/lib/library/chats";

const sourceMessageSchema = z.object({
  role: z.enum(["user", "assistant"]),
  content: z.string().min(1).max(500_000),
});
export const metadataSchema = z.object({
  title: z.string().trim().min(1).max(200),
  topic: z.string().trim().min(1).max(80),
  tags: z.array(z.string().trim().min(1).max(60)).max(30),
});
export const sourceSchema = metadataSchema.extend({
  provider: z.enum(["chatgpt", "claude", "codex", "transcript"]),
  sourceUrl: z
    .string()
    .url()
    .refine(
      (value) => /^https?:\/\//i.test(value),
      "Source URL must use HTTP or HTTPS.",
    )
    .optional(),
  messages: z.array(sourceMessageSchema).min(1).max(2000),
});
export type ConversationSource = z.infer<typeof sourceSchema>;
export type Conversation = ConversationSource & {
  id: string;
  version: 1;
  importedAt: string;
};
const recordSchema = sourceSchema.extend({
  id: z.string(),
  version: z.literal(1),
  importedAt: z.string(),
});
export const MAX_TRANSCRIPT_BYTES = 4 * 1024 * 1024;

function root(username: string): string {
  assertSlug(username);
  return path.join(usersRoot(), username, "conversations");
}
function directory(username: string, id: string): string {
  assertSlug(id);
  return path.join(root(username), id);
}
function atomic(file: string, value: string): void {
  const temp = `${file}.${crypto.randomUUID()}.tmp`;
  try {
    fs.writeFileSync(temp, value, { mode: 0o600 });
    fs.renameSync(temp, file);
  } finally {
    fs.rmSync(temp, { force: true });
  }
}
export function createConversation(
  username: string,
  input: ConversationSource,
): Conversation {
  const source = sourceSchema.parse(input);
  if (Buffer.byteLength(JSON.stringify(source)) > MAX_TRANSCRIPT_BYTES)
    throw new Error("Transcript exceeds the 4 MB limit.");
  const record: Conversation = {
    ...source,
    id: crypto.randomBytes(12).toString("hex"),
    version: 1,
    importedAt: new Date().toISOString(),
  };
  const dir = directory(username, record.id);
  fs.mkdirSync(dir, { recursive: true, mode: 0o700 });
  atomic(path.join(dir, "source.json"), JSON.stringify(record));
  return record;
}
export function getConversation(
  username: string,
  id: string,
): Conversation | null {
  const dir = directory(username, id);
  if (!fs.existsSync(path.join(dir, "source.json"))) return null;
  const source = recordSchema.parse(
    JSON.parse(fs.readFileSync(path.join(dir, "source.json"), "utf8")),
  );
  const meta = path.join(dir, "meta.json");
  return fs.existsSync(meta)
    ? {
        ...source,
        ...metadataSchema.parse(JSON.parse(fs.readFileSync(meta, "utf8"))),
      }
    : source;
}
export function listConversations(username: string): Conversation[] {
  const dir = root(username);
  if (!fs.existsSync(dir)) return [];
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  if (entries.length > 10_000)
    throw new Error("Conversation library exceeds the scan limit.");
  return entries
    .filter((entry) => entry.isDirectory())
    .flatMap((entry) => {
      const record = getConversation(username, entry.name);
      return record ? [record] : [];
    })
    .sort((a, b) => b.importedAt.localeCompare(a.importedAt));
}
export function updateConversation(
  username: string,
  id: string,
  metadata: z.infer<typeof metadataSchema>,
): Conversation {
  if (!getConversation(username, id))
    throw new Error("Conversation not found.");
  atomic(
    path.join(directory(username, id), "meta.json"),
    JSON.stringify(metadataSchema.parse(metadata)),
  );
  return getConversation(username, id)!;
}
export function lockConversation(username: string, id: string): () => void {
  assertSlug(username);
  assertSlug(id);
  try {
    return acquireFileLockSync(
      path.join(dataRoot(), "locks", "conversations", username, `${id}.guard`),
    );
  } catch (error) {
    if (error instanceof FileLockBusyError)
      throw new Error("A reply is already running. Wait for it to finish.");
    throw error;
  }
}
export function deleteConversation(username: string, id: string): void {
  const release = lockConversation(username, id);
  try {
    fs.rmSync(directory(username, id), { recursive: true, force: true });
  } finally {
    release();
  }
}
export function listConversationChats(username: string, id: string): Chat[] {
  if (!getConversation(username, id)) return [];
  const dir = path.join(directory(username, id), "chats");
  if (!fs.existsSync(dir)) return [];
  return fs
    .readdirSync(dir)
    .filter((name) => /^[a-f0-9]{16}\.jsonl$/.test(name))
    .map((name) => {
      const [header, ...messages] = fs
        .readFileSync(path.join(dir, name), "utf8")
        .trim()
        .split("\n")
        .map((line) => JSON.parse(line));
      return { header, messages } as Chat;
    });
}
export function saveConversationTurn(
  username: string,
  id: string,
  chatId: string | undefined,
  query: string,
  answer: string,
  images?: string[],
): Chat {
  if (!getConversation(username, id))
    throw new Error("Conversation not found.");
  const existing = chatId
    ? listConversationChats(username, id).find(
        (chat) => chat.header.id === chatId,
      )
    : undefined;
  if (chatId && !existing) throw new Error("Chat not found.");
  const at = new Date().toISOString();
  const chat: Chat = existing ?? {
    header: {
      id: crypto.randomBytes(8).toString("hex"),
      username,
      title: Array.from(query).slice(0, 72).join(""),
      titleSource: "manual",
      createdAt: at,
    },
    messages: [],
  };
  const messages: ChatMessage[] = [
    { role: "user", content: query, images, at },
    { role: "assistant", content: answer, at },
  ];
  chat.messages.push(...messages);
  const dir = path.join(directory(username, id), "chats");
  fs.mkdirSync(dir, { recursive: true, mode: 0o700 });
  atomic(
    path.join(dir, `${chat.header.id}.jsonl`),
    [chat.header, ...chat.messages]
      .map((value) => JSON.stringify(value))
      .join("\n") + "\n",
  );
  return chat;
}

export interface ExternalLinkProps {
  target: "_blank";
  rel: string;
}

/**
 * Browser-safe attributes for links that leave the current HTTP(S) origin.
 * Relative and non-web URLs stay in the current tab. When no current origin
 * is available, absolute and protocol-relative web URLs are external.
 */
export function externalLinkProps(
  href: string,
  currentOrigin?: string,
  nofollow = false,
): ExternalLinkProps | Record<string, never> {
  const value = href.trim();
  if (!value) return {};

  let destination: URL;
  try {
    if (currentOrigin) {
      destination = new URL(value, currentOrigin);
    } else if (/^https?:\/\//i.test(value)) {
      destination = new URL(value);
    } else if (value.startsWith("//")) {
      destination = new URL(`https:${value}`);
    } else {
      return {};
    }
  } catch {
    return {};
  }

  if (destination.protocol !== "http:" && destination.protocol !== "https:") {
    return {};
  }
  if (currentOrigin) {
    try {
      if (destination.origin === new URL(currentOrigin).origin) return {};
    } catch {
      return {};
    }
  }

  return {
    target: "_blank",
    rel: `noopener noreferrer${nofollow ? " nofollow" : ""}`,
  };
}

import crypto from "node:crypto";
import fs from "node:fs/promises";
import path from "node:path";
import { dataRoot } from "./data-dir";

const LOCK_STALE_MS = 15 * 60_000;
const HEARTBEAT_MS = 30_000;
const POLL_MS = 100;

export class FilesystemBusyError extends Error {}

export function filesystemLockPath(namespace: string, key: string): string {
  if (!/^[a-z][a-z0-9-]*$/.test(namespace)) {
    throw new Error(`Invalid lock namespace: ${namespace}`);
  }
  const digest = crypto.createHash("sha256").update(key).digest("hex");
  return path.join(dataRoot(), ".locks", `${namespace}-${digest}`);
}

async function removeStaleLock(lock: string): Promise<void> {
  try {
    const stat = await fs.stat(lock);
    if (Date.now() - stat.mtimeMs > LOCK_STALE_MS) {
      const stale = `${lock}.stale-${crypto.randomUUID()}`;
      await fs.rename(lock, stale);
      await fs.rm(stale, { recursive: true, force: true });
    }
  } catch {
    // The lock disappeared or was renewed between inspection and removal.
  }
}

async function ownsLock(lock: string, token: string): Promise<boolean> {
  try {
    const raw = await fs.readFile(path.join(lock, "owner.json"), "utf8");
    return (JSON.parse(raw) as { token?: unknown }).token === token;
  } catch {
    return false;
  }
}

async function acquire(
  namespace: string,
  key: string,
  waitMs: number,
): Promise<() => Promise<void>> {
  const lock = filesystemLockPath(namespace, key);
  await fs.mkdir(path.dirname(lock), { recursive: true });
  const deadline = Date.now() + waitMs;

  while (true) {
    try {
      await fs.mkdir(lock);
      const token = crypto.randomUUID();
      await fs.writeFile(
        path.join(lock, "owner.json"),
        JSON.stringify({
          token,
          pid: process.pid,
          acquiredAt: new Date().toISOString(),
        }),
        { mode: 0o600 },
      );
      const heartbeat = setInterval(() => {
        void ownsLock(lock, token).then((owned) => {
          if (!owned) return;
          const now = new Date();
          return fs.utimes(lock, now, now).catch(() => undefined);
        });
      }, HEARTBEAT_MS);
      heartbeat.unref();

      return async () => {
        clearInterval(heartbeat);
        if (await ownsLock(lock, token)) {
          await fs.rm(lock, { recursive: true, force: true });
        }
      };
    } catch (error) {
      if (
        !(error instanceof Error) ||
        !("code" in error) ||
        error.code !== "EEXIST"
      ) {
        throw error;
      }
      await removeStaleLock(lock);
      if (Date.now() >= deadline) {
        throw new FilesystemBusyError(
          "Another filesystem operation is still running.",
        );
      }
      await new Promise((resolve) => setTimeout(resolve, POLL_MS));
    }
  }
}

export async function withFilesystemLock<T>(
  namespace: string,
  key: string,
  waitMs: number,
  operation: () => Promise<T>,
): Promise<T> {
  const release = await acquire(namespace, key, waitMs);
  try {
    return await operation();
  } finally {
    await release();
  }
}

