async function handleReview(ctx: ResearchRequestContext) {
  return handleReviewRequest(ctx.request, ctx.segments.slice(1));
}

async function handleWorkspace() {
  await withPaperLifecycle(async () => {
    await recoverResearchImports();
    await recoverAnnotations();
  });
  const indexReady = ensureResearchIndex();
  const state = activeWorkspace();
  const graph = await getResearchGraph();
  const paperIds = new Set(state.papers.map((paper) => paper.id));
  const history = (await getResearchHistory(undefined, false)).filter((run) =>
    visibleRun(run, paperIds),
  );
  return json({
    papers: state.papers,
    notes: state.notes,
    knowledge: state.knowledge,
    annotations: state.annotations,
    graph,
    history,
    settings: state.settings,
    indexReady,
  });
}

async function handleHealth() {
  return json({ health: await getResearchHealth() });
}

function handleTrash() {
  return json({ papers: listTrashedPapers() });
}

async function handleExamplesImport() {
  const dir = path.resolve(
    process.env.RESEARCH_EXAMPLES_DIR ||
      path.join(process.cwd(), "..", "examples"),
  );
  if (!fs.existsSync(dir))
    throw new ResearchError("样例目录尚未准备，请上传自己的PDF", 404);
  const files = fs
    .readdirSync(dir)
    .filter((name) => name.toLowerCase().endsWith(".pdf"))
    .slice(0, 10);
  const papers = [];
  for (const filename of files) {
    const full = path.join(dir, filename);
    if (!fs.lstatSync(full).isFile()) continue;
    const bytes = new Uint8Array(fs.readFileSync(full));
    const parsed = await parsePdf(bytes);
    papers.push(
      await importPaper({
        bytes,
        filename,
        topic: "教育研究样例",
        ...parsed,
      }),
    );
  }
  return json({ papers }, 201);
}

async function handlePaperCollection(ctx: ResearchRequestContext) {
  if (ctx.method === "GET") return json({ papers: activeWorkspace().papers });
  if (ctx.method === "POST") {
    const form = await ctx.request.formData();
    const parsed = z
      .object({
        file: z
          .instanceof(File)
          .refine(
            (f) => f.size > 0 && f.size <= 100 * 1024 * 1024,
            "PDF大小应在1字节至100MB之间",
          ),
        title: z.string().trim().max(500).optional(),
        topic: z.string().trim().max(500).optional(),
        tags: z.string().max(3000).optional(),
      })
      .parse({
        file: form.get("file"),
        title: form.get("title") || undefined,
        topic: form.get("topic") || undefined,
        tags: form.get("tags") || undefined,
      });
    const bytes = new Uint8Array(await parsed.file.arrayBuffer());
    const extracted = await parsePdf(bytes);
    const paper = await importPaper({
      bytes,
      filename: parsed.file.name,
      topic: parsed.topic,
      tags: parsed.tags
        ?.split(/[,，]/)
        .map((s) => s.trim())
        .filter(Boolean),
      ...extracted,
      title: parsed.title || extracted.title,
    });
    return json({ paper }, 201, { etag: `"${paper.version}"` });
  }
  throw notFound();
}

async function paperLifecycleResponse(
  request: Request,
  id: string,
  detail: string | undefined,
  method: string,
): Promise<Response | undefined> {
  const isLifecycle =
    (!detail && method === "DELETE") ||
    (detail === "restore" && method === "POST");
  if (!isLifecycle) return undefined;
  const input = paperLifecycleSchema.parse(await body(request));
  const version = versionFromRequest(request, input.version);
  const updated =
    detail === "restore"
      ? await restoreResearchPaper(id, version)
      : await trashResearchPaper(id, version);
  return json({ paper: updated }, 200, { etag: `"${updated.version}"` });
}

async function paperMediaResponse(
  request: Request,
  id: string,
  detail: string | undefined,
  method: string,
): Promise<Response | undefined> {
  if (detail === "cover" && (method === "GET" || method === "HEAD"))
    return await researchCoverResponse(request, id);
  if (detail === "pdf") {
    if (method === "GET" || method === "HEAD")
      return researchPdfResponse(request, id);
    if (method === "PUT") {
      const saved = await withPaperLifecycle(() =>
        saveResearchPdf(request, id),
      );
      return json(saved, 200, { etag: saved.etag });
    }
  }
  return paperCommentResponse(request, id, detail, method);
}

async function paperCommentResponse(
  request: Request,
  id: string,
  detail: string | undefined,
  method: string,
): Promise<Response | undefined> {
  if (detail === "comments" && method === "GET") {
    const comments = await readResearchComments(id);
    return json(comments, 200, { etag: comments.etag });
  }
  if (detail === "comments" && method === "POST") {
    const action = pdfCommentActionSchema.parse(await body(request));
    const expected = z
      .string()
      .regex(/^"[a-f0-9]{64}"$/)
      .parse(request.headers.get("if-match"));
    const saved = await withPaperLifecycle(() =>
      saveNativeComment(id, action, expected),
    );
    return json(saved, 200, { etag: saved.etag });
  }
  return undefined;
}

async function paperRecordResponse(
  request: Request,
  id: string,
  detail: string | undefined,
  method: string,
  paper: ReturnType<typeof paperById>,
): Promise<Response> {
  if (detail === "text" && method === "GET")
    return json({
      pages: paperPages(paper),
      status: paper.textStatus,
      warning: paper.textWarning,
    });
  if (detail === "annotations" && method === "GET")
    return json({
      annotations: activeWorkspace().annotations.filter(
        (a) => a.paperId === id,
      ),
    });
  if (!detail && method === "GET") {
    const state = activeWorkspace();
    return json(
      {
        paper,
        pages: paperPages(paper),
        notes: state.notes.filter((n) => n.paperId === id),
        annotations: state.annotations.filter((a) => a.paperId === id),
      },
      200,
      { etag: `"${paper.version}"` },
    );
  }
  if (!detail && method === "PATCH") {
    const input = paperPatchSchema.parse(await body(request));
    const updated = await updatePaper(id, {
      ...input,
      version: versionFromRequest(request, input.version),
    });
    return json({ paper: updated }, 200, { etag: `"${updated.version}"` });
  }
  throw notFound();
}

async function handlePaperItem(ctx: ResearchRequestContext) {
  const { request, id, detail, method } = ctx;
  if (!id) throw notFound();
  idSchema.parse(id);
  const lifecycle = await paperLifecycleResponse(request, id, detail, method);
  if (lifecycle) return lifecycle;
  const paper = paperById(id);
  const media = await paperMediaResponse(request, id, detail, method);
  if (media) return media;
  return paperRecordResponse(request, id, detail, method, paper);
}

async function handleNoteItem(
  request: Request,
  id: string,
  detail: string | undefined,
  method: string,
): Promise<Response> {
  idSchema.parse(id);
  const state = readWorkspace();
  const note = state.notes.find((n) => n.id === id);
  if (!note) throw new ResearchError("笔记不存在", 404);
  paperById(note.paperId, state);
  if (detail === "history" && method === "GET")
    return json({ versions: state.noteHistory[id] || [] });
  if (method === "GET")
    return json({ note }, 200, { etag: `"${note.version}"` });
  if (method === "PATCH") {
    const input = notePatchSchema.parse(await body(request));
    const updated = await updateNote(id, {
      ...input,
      version: versionFromRequest(request, input.version),
    });
    return json({ note: updated }, 200, { etag: `"${updated.version}"` });
  }
  throw notFound();
}

async function handleNotes(ctx: ResearchRequestContext) {
  const { request, url, id, detail, method } = ctx;
  if (!id && method === "GET") {
    const paperId = z
      .string()
      .optional()
      .parse(url.searchParams.get("paperId") || undefined);
    return json({
      notes: activeWorkspace().notes.filter(
        (n) => !paperId || n.paperId === paperId,
      ),
    });
  }
  if (!id && method === "POST")
    return json(
      { note: await createNote(noteSchema.parse(await body(request))) },
      201,
    );
  if (id) return handleNoteItem(request, id, detail, method);
  throw notFound();
}

async function handleAnnotations(ctx: ResearchRequestContext) {
  const { request, id, method } = ctx;
  if (id && ["PATCH", "DELETE"].includes(method)) {
    idSchema.parse(id);
    const input = annotationMutationSchema.parse(await body(request));
    return json(
      await withPaperLifecycle(() =>
        mutateAnnotation(id, input, method === "DELETE"),
      ),
    );
  }
  if (!id && method === "POST") {
    const input = annotationSchema.parse(await body(request));
    return json(await withPaperLifecycle(() => createAnnotation(input)), 201);
  }
  if (method === "GET")
    return json({ annotations: activeWorkspace().annotations });
  throw notFound();
}

async function handleKnowledgeItem(
  request: Request,
  id: string,
  method: string,
): Promise<Response> {
  if (method === "GET") {
    const entry = activeWorkspace().knowledge.find((k) => k.id === id);
    if (!entry) throw new ResearchError("概念不存在", 404);
    return json({ entry });
  }
  if (method === "PATCH") {
    idSchema.parse(id);
    const input = knowledgePatchSchema.parse(await body(request));
    const existing = readWorkspace().knowledge.find((k) => k.id === id);
    if (!existing) throw new ResearchError("概念不存在", 404);
    return json({
      entry: await saveKnowledge(
        {
          ...input,
          title: input.title ?? existing.title,
          version: versionFromRequest(request, input.version),
        },
        id,
      ),
    });
  }
  throw notFound();
}

async function handleKnowledge(ctx: ResearchRequestContext) {
  const { request, id, method } = ctx;
  if (!id && method === "GET")
    return json({ knowledge: activeWorkspace().knowledge });
  if (!id && method === "POST")
    return json(
      {
        entry: await saveKnowledge(knowledgeSchema.parse(await body(request))),
      },
      201,
    );
  if (id) return handleKnowledgeItem(request, id, method);
  throw notFound();
}

function handleSearch(ctx: ResearchRequestContext) {
  const query = z
    .object({
      q: z.string().max(500).default(""),
      scope: z.enum(["all", "education", "personal"]).default("all"),
    })
    .parse({
      q: ctx.url.searchParams.get("q") || "",
      scope: ctx.url.searchParams.get("scope") || "all",
    });
  return json({ results: searchResearch(query.q, query.scope) });
}

async function handleGraph(ctx: ResearchRequestContext) {
  const { request, method } = ctx;
  if (method === "GET") return json(await getResearchGraph());
  if (method === "POST") {
    const input = graphActionSchema.parse(await body(request));
    if (input.action === "suggest")
      return json(await suggestGraph(input.paperId));
    if (input.action === "add")
      return json(
        await addManualGraphEdge({
          source: z.string().min(1).parse(input.source),
          target: z.string().min(1).parse(input.target),
          kind: input.kind,
          label: input.label,
          rationale: input.rationale,
          evidence: input.evidence || [],
        }),
      );
    return json(
      await decideGraphEdge(
        idSchema.parse(input.edgeId),
        input.action === "confirm"
          ? "confirmed"
          : input.action === "reject"
            ? "rejected"
            : "candidate",
        input.version,
      ),
    );
  }
  throw notFound();
}

type RunInput = z.infer<typeof runSchema>;

function discussionDocuments(context: ReturnType<typeof researchContext>) {
  return [
    {
      document_id: context.paper.id,
      title: context.paper.title,
      content_revision: context.paper.contentRevision,
      pages: context.pages,
    },
    ...(context.related ?? []).map((entry) => ({
      document_id: entry.paper.id,
      title: entry.paper.title,
      content_revision: entry.paper.contentRevision,
      pages: paperPages(entry.paper),
    })),
  ];
}

function assertAnalyzableText(
  context: ReturnType<typeof researchContext>,
  prepared: ReturnType<typeof prepareLearningInput>,
) {
  if (context.paper.textStatus === "ready") return;
  if (prepared.selection?.text || prepared.selection?.quote) return;
  if (prepared.context.studyMaterials?.length) return;
  throw new ResearchError(
    "此PDF没有可分析的文字层。请上传文字PDF或提供选区文字。",
    422,
  );
}

async function createResearchRun(input: RunInput) {
  const context = researchContext(
    input.paperId,
    input.mode === "graph" ? undefined : input.question,
    input.learning ? [input.paperId] : input.sourcePaperIds,
  );
  if (input.selection && input.selection.page > context.paper.pageCount)
    throw new ResearchError("选区页码超出论文范围");
  if (effectiveAnswerStyle(input) === "discussion")
    context.sourceDocuments = discussionDocuments(context);
  const prepared = prepareLearningInput(
    prepareQuestionInput({ ...input, context }),
  );
  assertAnalyzableText(context, prepared);
  return startResearchRun(prepared);
}

async function startRunResponse(request: Request): Promise<Response> {
  const input = runSchema.parse(await body(request));
  if (
    input.sourcePaperIds &&
    (input.mode !== "ask" || !input.sourcePaperIds.includes(input.paperId))
  )
    throw new ResearchError("来源选择用于问答，且必须包含当前论文");
  const run = await withPaperLifecycle(() => createResearchRun(input));
  return json({ run }, 202);
}

async function handleRunItem(
  request: Request,
  id: string,
  detail: string | undefined,
  method: string,
): Promise<Response> {
  idSchema.parse(id);
  const local = (await getResearchHistory(undefined, false)).find(
    (run) => run.id === id,
  );
  if (!local) throw new ResearchError("分析记录不存在", 404);
  paperById(local.paperId);
  const visible = visibleRun(
    local,
    new Set(activeWorkspace().papers.map((paper) => paper.id)),
  );
  if (!visible)
    throw new ResearchError("分析来源论文已移入回收站，请先恢复后再查看", 410);
  if (detail === "permission" && method === "POST") {
    const input = z
      .object({
        toolUseId: idSchema,
        decision: z.enum(["allow_once", "deny_once"]),
      })
      .parse(await body(request));
    return json({
      run: await respondResearchPermission(id, input.toolUseId, input.decision),
    });
  }
  if (method === "GET") {
    const run = await getResearchRun(id);
    await applyGraphRun(run);
    return json({ run });
  }
  if (method === "POST" && (!detail || detail === "cancel")) {
    z.object({ action: z.literal("cancel").optional() }).parse(
      await body(request),
    );
    return json({ run: await cancelResearchRun(id) });
  }
  throw notFound();
}

async function handleRuns(ctx: ResearchRequestContext) {
  const { request, url, id, detail, method } = ctx;
  if (!id && method === "GET") {
    const paperId = url.searchParams.get("paperId") || undefined;
    if (paperId) paperById(idSchema.parse(paperId));
    const history = await getResearchHistory(paperId);
    const ids = new Set(activeWorkspace().papers.map((paper) => paper.id));
    return json({ history: history.filter((run) => visibleRun(run, ids)) });
  }
  if (!id && method === "POST") return startRunResponse(request);
  if (id) return handleRunItem(request, id, detail, method);
  throw notFound();
}

async function handleSettings(ctx: ResearchRequestContext) {
  const { request, id, detail, method } = ctx;
  if (method === "GET")
    return json({
      settings: readWorkspace().settings,
      health: await getResearchHealth().catch(() => ({ available: false })),
    });
  if (method === "PATCH") {
    const input = settingsSchema.parse(await body(request));
    const settings = await mutateWorkspace((state) => {
      expectedVersion(
        state.settings.version,
        versionFromRequest(request, input.version),
      );
      Object.assign(state.settings, input, {
        version: state.settings.version + 1,
      });
      return state.settings;
    });
    return json({ settings });
  }
  if (method === "POST" && detail === undefined && id === "provider") {
    const input = z
      .object({
        base_url: z.url().optional(),
        model: z.string().min(1).max(200).optional(),
        api_key: z.string().max(1000).optional(),
      })
      .parse(await body(request));
    return json({ health: await configureResearchProvider(input) });
  }
  throw notFound();
}

function handleExport(ctx: ResearchRequestContext) {
  const input = z
    .object({
      paperId: idSchema.optional(),
      format: z.literal("markdown").default("markdown"),
    })
    .parse({
      paperId: ctx.url.searchParams.get("paperId") || undefined,
      format: ctx.url.searchParams.get("format") || "markdown",
    });
  return new Response(exportMarkdown(input.paperId), {
    headers: {
      "content-type": "text/markdown; charset=utf-8",
      "content-disposition": `attachment; filename="research-notes.md"; filename*=UTF-8''${encodeURIComponent("教研阅记-研究笔记.md")}`,
      "cache-control": "no-store",
    },
  });
}

async function handleBackup() {
  const backup = await createResearchBackup();
  return new Response(new Uint8Array(backup).buffer, {
    headers: {
      "content-type": "application/zip",
      "content-disposition": 'attachment; filename="research-backup.zip"',
      "cache-control": "no-store",
    },
  });
}

function notFound() {
  return new ResearchError("此研究接口不存在或不支持该操作", 404);
}

type ResearchRoute = {
  match: (ctx: ResearchRequestContext) => boolean;
  handle: (ctx: ResearchRequestContext) => Response | Promise<Response>;
};

const routes: ResearchRoute[] = [
  { match: ({ area }) => area === "review", handle: handleReview },
  {
    match: ({ area, method }) => !area && method === "GET",
    handle: handleWorkspace,
  },
  {
    match: ({ area, method }) => area === "health" && method === "GET",
    handle: handleHealth,
  },
  {
    match: ({ area, id, method }) =>
      area === "trash" && !id && method === "GET",
    handle: handleTrash,
  },
  {
    match: ({ area, id, method }) =>
      area === "examples" && id === "import" && method === "POST",
    handle: handleExamplesImport,
  },
  {
    match: ({ area, id }) => area === "papers" && !id,
    handle: handlePaperCollection,
  },
  {
    match: ({ area, id }) => area === "papers" && !!id,
    handle: handlePaperItem,
  },
  { match: ({ area }) => area === "notes", handle: handleNotes },
  { match: ({ area }) => area === "annotations", handle: handleAnnotations },
  {
    match: ({ area }) => area === "knowledge" || area === "concepts",
    handle: handleKnowledge,
  },
  {
    match: ({ area, method }) => area === "search" && method === "GET",
    handle: handleSearch,
  },
  { match: ({ area }) => area === "graph", handle: handleGraph },
  {
    match: ({ area }) =>
      area === "runs" || area === "tasks" || area === "history",
    handle: handleRuns,
  },
  { match: ({ area }) => area === "settings", handle: handleSettings },
  {
    match: ({ area, method }) => area === "export" && method === "GET",
    handle: handleExport,
  },
  {
    match: ({ area, method }) => area === "backup" && method === "GET",
    handle: handleBackup,
  },
];

export async function dispatchResearchRoute(
  ctx: ResearchRequestContext,
): Promise<Response> {
  for (const route of routes) {
    if (route.match(ctx)) return route.handle(ctx);
  }
  throw notFound();
}

import fs from "node:fs";
import path from "node:path";
import { companionDir } from "../library/papers";
import { withFilesystemLock } from "../filesystem-lock";
import {
  digest,
  getResearchDataDir,
  paperPdfPath,
  readWorkspace,
  ResearchError,
} from "./store";

/** ZIP STORE writer: portable backups without shell commands or an additional native dependency. */
function crc32(bytes: Uint8Array): number {
  let crc = 0xffffffff;
  for (const byte of bytes) {
    crc ^= byte;
    for (let i = 0; i < 8; i++) crc = (crc >>> 1) ^ (crc & 1 ? 0xedb88320 : 0);
  }
  return (crc ^ 0xffffffff) >>> 0;
}
function zip(files: { name: string; bytes: Buffer }[]): Buffer {
  const chunks: Buffer[] = [];
  const central: Buffer[] = [];
  let offset = 0;
  for (const file of files) {
    const name = Buffer.from(file.name, "utf8");
    const crc = crc32(file.bytes);
    const header = Buffer.alloc(30);
    header.writeUInt32LE(0x04034b50, 0);
    header.writeUInt16LE(20, 4);
    header.writeUInt16LE(0x800, 6);
    header.writeUInt16LE(33, 12);
    header.writeUInt32LE(crc, 14);
    header.writeUInt32LE(file.bytes.length, 18);
    header.writeUInt32LE(file.bytes.length, 22);
    header.writeUInt16LE(name.length, 26);
    chunks.push(header, name, file.bytes);
    const entry = Buffer.alloc(46);
    entry.writeUInt32LE(0x02014b50, 0);
    entry.writeUInt16LE(20, 4);
    entry.writeUInt16LE(20, 6);
    entry.writeUInt16LE(0x800, 8);
    entry.writeUInt16LE(33, 14);
    entry.writeUInt32LE(crc, 16);
    entry.writeUInt32LE(file.bytes.length, 20);
    entry.writeUInt32LE(file.bytes.length, 24);
    entry.writeUInt16LE(name.length, 28);
    entry.writeUInt32LE(offset, 42);
    central.push(entry, name);
    offset += header.length + name.length + file.bytes.length;
  }
  const centralSize = central.reduce((size, b) => size + b.length, 0);
  const end = Buffer.alloc(22);
  end.writeUInt32LE(0x06054b50, 0);
  end.writeUInt16LE(files.length, 8);
  end.writeUInt16LE(files.length, 10);
  end.writeUInt32LE(centralSize, 12);
  end.writeUInt32LE(offset, 16);
  return Buffer.concat([...chunks, ...central, end]);
}
function createBackupSnapshot(): Uint8Array {
  const state = readWorkspace();
  const files: { name: string; bytes: Buffer }[] = [];
  let total = 0;
  if (state.pendingAnnotations.length)
    throw new ResearchError("批注正在提交，请保存完成后再备份", 409);
  const add = (name: string, filename: string) => {
    if (!fs.existsSync(filename)) return;
    const stat = fs.statSync(filename);
    if (!stat.isFile()) return;
    total += stat.size;
    if (total > 1024 * 1024 * 1024)
      throw new ResearchError("工作区超过1GB，请使用停止服务后的目录备份", 413);
    files.push({ name, bytes: fs.readFileSync(filename) });
  };
  add(
    "research/workspace.json",
    path.join(getResearchDataDir(), "workspace.json"),
  );
  for (const paper of state.papers) {
    const bytes = fs.readFileSync(paperPdfPath(paper));
    if (`"${digest(bytes)}"` !== paper.pdfEtag)
      throw new ResearchError("PDF版本正在变更，请刷新后再备份", 409);
    total += bytes.length;
    if (total > 1024 * 1024 * 1024)
      throw new ResearchError("工作区超过1GB，请停机备份目录", 413);
    files.push({
      name: `papers/${paper.library.topic}/${paper.library.slug}.pdf`,
      bytes,
    });
    const dir = companionDir(paper.library.topic, paper.library.slug);
    for (const file of [
      "meta.json",
      "text.txt",
      "research-pages.json",
      "research-identity.json",
    ])
      add(
        `library/${paper.library.topic}/${paper.library.slug}/${file}`,
        path.join(dir, file),
      );
  }
  const runs = path.join(getResearchDataDir(), "runs");
  if (fs.existsSync(runs))
    for (const file of fs.readdirSync(runs))
      if (/^[a-zA-Z0-9_-]+\.json$/.test(file))
        add(`research/runs/${file}`, path.join(runs, file));
  files.push({
    name: "恢复说明.txt",
    bytes: Buffer.from(
      "教研阅记备份\n请先停止应用，再将本压缩包中的 papers、library、research 三个目录复制回统一 data 目录。RESEARCH_DATA_DIR 应指向其中 research 目录。模型凭据不在备份中，恢复后请单独配置。原有目录请先另存备份。\n",
      "utf8",
    ),
  });
  return new Uint8Array(zip(files));
}
export async function createResearchBackup(): Promise<Uint8Array> {
  return withFilesystemLock(
    "research-workspace",
    getResearchDataDir(),
    30000,
    async () => createBackupSnapshot(),
  );
}

import {
  PDFDict,
  PDFDocument,
  PDFHexString,
  PDFName,
  PDFRef,
  PDFString,
} from "pdf-lib";
import { readVersionedPdf } from "../library/pdf/file";
import type { PdfCommentProjection } from "../pdf/reader/comment-card";
import { managedMarks } from "./annotation-records";
import { paperById, readWorkspace, ResearchError } from "./store";
import type { ResearchAnnotation } from "./types";

const text = (dict: PDFDict, key: string) =>
  dict.lookupMaybe(PDFName.of(key), PDFString, PDFHexString)?.decodeText() ??
  "";

/** A read-only view: ownership comes exclusively from the existing managed-mark policy. */
export function projectResearchComments(
  document: PDFDocument,
  paperId: string,
  records: ResearchAnnotation[],
): PdfCommentProjection[] {
  const comments: PdfCommentProjection[] = [];
  const ownedIds = new Set<string>();
  for (const group of managedMarks(document)) {
    const record = records.find(
      (item) =>
        item.paperId === paperId &&
        (item.pdfName ?? "jy-" + item.id) === group.name,
    );
    const ids = group.marks.map((mark) => mark.refId);
    ids.forEach((id) => ownedIds.add(id));
    comments.push({
      ids,
      page: group.page,
      text:
        record && !record.comment && group.contents === record.quote
          ? ""
          : group.contents,
      author: text(group.marks[0].dict, "T"),
      editable: true,
      kind: group.kind,
      ...(record ? { annotationId: record.id, quote: record.quote } : {}),
    });
  }
  const foreign = new Map<string, PdfCommentProjection>();
  document.getPages().forEach((page, index) => {
    for (const ref of page.node.Annots()?.asArray() ?? []) {
      if (!(ref instanceof PDFRef)) continue;
      const id = `${ref.objectNumber}R${ref.generationNumber || ""}`;
      if (ownedIds.has(id)) continue;
      const dict = document.context.lookup(ref);
      if (!(dict instanceof PDFDict)) continue;
      const subtype = dict
        .lookupMaybe(PDFName.of("Subtype"), PDFName)
        ?.asString();
      if (subtype === "/Popup") continue;
      const contents = text(dict, "Contents");
      if (!contents.trim()) continue;
      const name = text(dict, "NM");
      const owner = text(dict, "PapernookAuthor");
      const author = text(dict, "T");
      // Foreign marks never join a local group, even when an NM was copied.
      const key = name ? JSON.stringify([index, name, owner, author]) : id;
      const existing = foreign.get(key);
      if (existing) {
        existing.ids.push(id);
        if (subtype === "/Text") existing.text = contents;
        if (subtype === "/Highlight") existing.kind = "highlight";
      } else
        foreign.set(key, {
          ids: [id],
          page: index + 1,
          text: contents,
          author,
          editable: false,
          kind:
            subtype === "/Highlight"
              ? "highlight"
              : subtype === "/Text"
                ? "comment"
                : "other",
        });
    }
  });
  return [...comments, ...foreign.values()];
}

export async function readResearchComments(
  paperId: string,
): Promise<{ etag: string; comments: PdfCommentProjection[] }> {
  const state = readWorkspace();
  const paper = paperById(paperId, state);
  const current = await readVersionedPdf(
    paper.library.topic,
    paper.library.slug,
  );
  if (!current) throw new ResearchError("PDF 不存在", 404);
  // Viewing a signed PDF remains allowed. The write APIs retain their signature guard.
  const document = await PDFDocument.load(current.bytes, {
    updateMetadata: false,
  });
  return {
    etag: current.etag,
    comments: projectResearchComments(document, paperId, state.annotations),
  };
}

import { createHash } from "node:crypto";
import type { ResearchRun, SourceRef, StartResearchRunInput } from "./types";
import { pickReferenceConcepts } from "./discussion/concepts";
import {
  compactDiscussionPages,
  effectiveAnswerStyle,
  passageWindow,
} from "./discussion/context";

function isStudyNote(question: string): boolean {
  return /^\s*\[学习笔记:[^\]]+\]/.test(question);
}
function compactSources(
  sources: SourceRef[],
  discussion: boolean,
): SourceRef[] {
  return discussion
    ? sources.slice(0, 3).map((source) => ({
        paperId: source.paperId,
        page: source.page,
        noteId: source.noteId,
        annotationId: source.annotationId,
        quote: source.quote?.slice(0, 180),
        contentRevision: source.contentRevision,
        url: source.url?.slice(0, 400),
      }))
    : sources;
}

/** Broaden the document scope only when the question explicitly requests it. */
function requestsRelatedPapers(input: StartResearchRunInput): boolean {
  if (input.mode !== "ask" || isStudyNote(input.question)) return false;
  if (input.sourcePaperIds)
    return input.sourcePaperIds.some((id) => id !== input.paperId);
  const question = input.question.normalize("NFKC");
  if (
    /(?:不要|无需|不需要|不必|勿|别|不使用|不结合).{0,12}(?:其他|其它|跨论文|跨文献|多篇|多份)|(?:仅|只)(?:基于|使用|分析|根据|参考)?(?:当前论文|这篇论文|本文|这份材料|本篇论文)/.test(
      question,
    ) ||
    /\b(?:do not|don't|without|avoid)\b.{0,35}\b(?:other|across|multiple|cross[- ]paper|compare)\b/i.test(
      question,
    )
  )
    return false;
  return (
    /跨(?:论文|文献|资料)|(?:其他|其它|别的|不同|多篇|多份|多本|多项|两篇|三篇|几篇|这两篇|这三篇|多篇)(?:的)?(?:论文|文献|资料|材料|研究)|(?:比较|对比).{0,12}(?:多篇|多份|两篇|三篇|几篇|不同|这些|这两篇|这三篇)(?:论文|文献|资料|材料|研究)?/.test(
      question,
    ) ||
    /\b(?:cross[- ](?:paper|document)|other (?:papers?|articles?|documents?|sources?|materials?|studies)|across (?:papers?|articles?|documents?|studies)|(?:multiple|two|three|several) (?:papers?|articles?|documents?|studies))\b/i.test(
      question,
    )
  );
}

function requestsKnowledge(input: StartResearchRunInput): boolean {
  if (input.mode === "concept") return true;
  if (input.mode !== "ask") return false;
  if (
    /(?:不要|无需|不需要|不必|勿|不使用|不结合).{0,12}(?:知识库|概念库|教育知识|教育理论)/.test(
      input.question,
    )
  )
    return false;
  return /教育(?:学)?(?:概念|知识|理论)|(?:我的|本地|系统的?)(?:知识|概念)库|(?:结合|参考|查阅|查询|查|使用|利用|从|检索).{0,5}(?:知识|概念)库|(?:知识|概念)库(?:中的?|里的?|条目)|\b(?:education(?:al)? (?:concepts?|theor(?:y|ies)|knowledge)|(?:our|my|local) (?:knowledge|concept) (?:base|library)|(?:use|consult|from) (?:the )?(?:knowledge|concept) (?:base|library))\b/i.test(
    input.question,
  );
}

export function buildResearchContext(input: StartResearchRunInput) {
  const { paper, pages, notes, knowledge, related } = input.context;
  const discussion = effectiveAnswerStyle(input) === "discussion";
  const selectedPages = discussion ? compactDiscussionPages(input) : pages;
  const concepts =
    (input.mode === "ask" || input.mode === "concept") &&
    (discussion || input.referenceConceptIds !== undefined)
      ? pickReferenceConcepts(
          knowledge,
          input.question +
            "\n" +
            (input.selection?.text ?? input.selection?.quote ?? ""),
          input.referenceConceptIds,
        )
      : requestsKnowledge(input)
        ? knowledge.slice(0, 12)
        : [];
  let remaining = 100_000;
  const pageText = selectedPages
    .map((page) => {
      const text = page.text.slice(0, Math.max(0, remaining));
      remaining -= text.length;
      return text ? `\n[p.${page.page}]\n${text}` : "";
    })
    .join("\n");
  return {
    document_id: paper.id,
    content_revision: paper.contentRevision,
    title: paper.title,
    authors: paper.authors,
    year: paper.year,
    selection:
      discussion && input.selection
        ? {
            page: input.selection.page,
            text: input.selection.text ?? input.selection.quote,
            contentRevision: input.selection.contentRevision,
          }
        : input.selection,
    answer_style: effectiveAnswerStyle(input),
    provided_pages: selectedPages.map((page) => page.page),
    ...(input.learning
      ? {
          learning_source: input.learning.source,
          selected_materials: input.context.studyMaterials ?? [],
        }
      : {}),
    education_library: concepts.map((item) => ({
      id: item.id,
      version: item.version,
      title: item.title,
      text: item.body.slice(0, discussion ? 1000 : 1800),
      sources: compactSources(item.sources, discussion),
    })),
    confirmed_notes: notes
      .filter(
        (note) =>
          note.paperId === paper.id &&
          (note.confirmed || note.status === "confirmed"),
      )
      .slice(0, discussion ? 2 : 12)
      .map((note) => ({
        title: note.title,
        body: note.body.slice(0, discussion ? 500 : 2200),
        sources: compactSources(note.sources, discussion),
      })),
    related_papers: requestsRelatedPapers(input)
      ? (related ?? [])
          .filter(
            (item) =>
              !input.sourcePaperIds ||
              input.sourcePaperIds.includes(item.paper.id),
          )
          .filter((item) => item.paper.id !== paper.id)
          .slice(0, 3)
          .map((item) => ({
            document_id: item.paper.id,
            title: item.paper.title,
            content_revision: item.paper.contentRevision,
            pages: (discussion
              ? compactDiscussionPages({
                  ...input,
                  selection: undefined,
                  context: {
                    ...input.context,
                    paper: item.paper,
                    pages: item.pages,
                  },
                }).slice(0, 2)
              : item.pages.slice(0, 4)
            ).map((page) => ({
              page: page.page,
              text: discussion
                ? passageWindow(page.text, input.question, 700)
                : page.text.slice(0, 4500),
              citation_link: `/workspace?paperId=${item.paper.id}&page=${page.page}`,
            })),
            notes: item.notes
              .filter(
                (note) =>
                  note.paperId === item.paper.id &&
                  (note.confirmed || note.status === "confirmed"),
              )
              .slice(0, discussion ? 1 : 4)
              .map((note) => ({
                title: note.title,
                text: note.body.slice(0, discussion ? 300 : 1000),
                sources: compactSources(note.sources, discussion),
              })),
          }))
      : [],
    paper_pages: pageText,
    context_truncated:
      !!input.context.studyTruncated ||
      (discussion
        ? selectedPages.reduce((sum, page) => sum + page.text.length, 0) <
          pages.reduce((sum, page) => sum + page.text.length, 0)
        : pages.reduce((sum, page) => sum + page.text.length, 0) > 100_000),
  };
}

/** New runs do not inherit pre-policy or broader-scope provider conversations. */
export function researchContextScope(input: StartResearchRunInput): string {
  const context = buildResearchContext(input);
  return JSON.stringify({
    policy: "explicit-source-scope-v6",
    answerStyle: effectiveAnswerStyle(input),
    ...(input.learning && effectiveAnswerStyle(input) !== "discussion"
      ? {
          learning: input.learning,
          learningEvidence: createHash("sha256")
            .update(
              JSON.stringify({
                selection: input.selection,
                pages: input.context.pages,
                materials: input.context.studyMaterials,
              }),
            )
            .digest("hex"),
        }
      : {}),
    // Keep the passage identity stable across PDF annotation and layout changes.
    ...(input.selection &&
    (!input.learning || effectiveAnswerStyle(input) === "discussion")
      ? {
          selectionEvidence: createHash("sha256")
            .update(
              JSON.stringify({
                page: input.selection.page,
                text: input.selection.text ?? input.selection.quote ?? "",
                quote: input.selection.quote ?? input.selection.text ?? "",
                contentRevision:
                  input.selection.contentRevision ??
                  input.context.paper.contentRevision,
              }),
            )
            .digest("hex"),
        }
      : {}),
    study: isStudyNote(input.question),
    related: context.related_papers.map((paper) => paper.document_id).sort(),
    education: context.education_library.map((entry) => entry.title).sort(),
    concepts: context.education_library
      .map((entry) => ({
        id: entry.id,
        version: entry.version,
        digest: createHash("sha256")
          .update(JSON.stringify(entry))
          .digest("hex"),
      }))
      .sort((a, b) => a.id.localeCompare(b.id)),
    relatedRevisions: context.related_papers.map((entry) => ({
      id: entry.document_id,
      revision: entry.content_revision,
    })),
    sources: researchSourcePaperIds(input),
  });
}

/** Source documents actually sent, including cross-references in confirmed notes. */
export function researchSourcePaperIds(input: StartResearchRunInput): string[] {
  const context = buildResearchContext(input);
  const sources = [
    ...context.confirmed_notes.flatMap((note) => note.sources),
    ...context.education_library.flatMap((entry) => entry.sources),
    ...context.related_papers.flatMap((paper) =>
      paper.notes.flatMap((note) => note.sources),
    ),
    ...(input.context.studyMaterials ?? []).flatMap(
      (material) => material.sources,
    ),
  ];
  return [
    ...new Set([
      input.paperId,
      ...context.related_papers.map((paper) => paper.document_id),
      ...sources.flatMap((source) => (source.paperId ? [source.paperId] : [])),
    ]),
  ].sort();
}

/** Older v2 records retain selected related papers inside their scope string. */
export function recordedRunPaperIds(run: ResearchRun): string[] {
  const ids = new Set([run.paperId, ...(run.sourcePaperIds || [])]);
  if (run.contextScope) {
    try {
      const scope: unknown = JSON.parse(run.contextScope);
      if (scope && typeof scope === "object") {
        const record = scope as Record<string, unknown>;
        for (const key of ["related", "sources"] as const) {
          const values = record[key];
          if (Array.isArray(values))
            for (const value of values)
              if (typeof value === "string") ids.add(value);
        }
      }
    } catch {
      /* Historical opaque scopes still keep their primary document. */
    }
  }
  return [...ids];
}

export function canReuseResearchSession(
  run: ResearchRun,
  input: StartResearchRunInput,
  scope: string,
): boolean {
  return (
    input.mode === "ask" &&
    (!input.learning ||
      (input.learning.task === "explain" &&
        effectiveAnswerStyle(input) === "discussion")) &&
    !isStudyNote(input.question) &&
    run.mode === "ask" &&
    (!run.learning ||
      (run.learning.task === "explain" && run.answerStyle === "discussion")) &&
    run.status === "completed" &&
    !!run.sessionId &&
    run.paperId === input.paperId &&
    run.contentRevision === input.context.paper.contentRevision &&
    run.contextScope === scope
  );
}

import { execFile } from "node:child_process";
import { createHash } from "node:crypto";
import { createReadStream } from "node:fs";
import fs from "node:fs/promises";
import path from "node:path";
import { inboxRoot, papersRoot } from "../data-dir";
import { MAX_PDF_BYTES } from "../pdf-limits";
import { readVersionedPdfFile } from "../library/pdf/file";
import { idSchema } from "./schemas";
import {
  getResearchDataDir,
  paperById,
  paperPdfPath,
  ResearchError,
} from "./store";

const COVER_VERSION = "first-page-v1";
const MAX_IMAGE_BYTES = 3 * 1024 * 1024;
const MAX_EDGE = 900;
export const COVER_RENDER_TIMEOUT_MS = 12_000;
const inflight = new Map<string, Promise<Cover>>();
let activeRenders = 0;
const waiting: {
  resolve(release: () => void): void;
  timer: ReturnType<typeof setTimeout>;
}[] = [];

interface Cover {
  bytes: Uint8Array;
  etag: string;
  pdfEtag: string;
}

function releaseSlot(): void {
  const next = waiting.shift();
  if (next) {
    clearTimeout(next.timer);
    next.resolve(releaseSlot);
  } else activeRenders--;
}

function renderSlot(): Promise<() => void> {
  if (activeRenders < 2) {
    activeRenders++;
    return Promise.resolve(releaseSlot);
  }
  if (waiting.length >= 32)
    return Promise.reject(new ResearchError("封面正在准备，请稍后重试", 503));
  return new Promise((resolve, reject) => {
    const entry = {
      resolve,
      timer: setTimeout(() => {
        const index = waiting.indexOf(entry);
        if (index >= 0) waiting.splice(index, 1);
        reject(new ResearchError("封面正在准备，请稍后重试", 503));
      }, 20_000),
    };
    waiting.push(entry);
  });
}

function within(root: string, filename: string): boolean {
  const relative = path.relative(root, filename);
  return (
    relative !== "" &&
    relative !== ".." &&
    !relative.startsWith(`..${path.sep}`) &&
    !path.isAbsolute(relative)
  );
}

async function checkedPdfPath(filename: string): Promise<string> {
  const actual = await fs.realpath(filename);
  const roots = await Promise.all(
    [papersRoot(), inboxRoot()].map((root) =>
      fs.realpath(root).catch(() => path.resolve(root)),
    ),
  );
  if (!roots.some((root) => within(root, actual)))
    throw new ResearchError("论文文件路径无效", 422);
  const stat = await fs.stat(actual);
  if (!stat.isFile() || stat.size <= 0 || stat.size > MAX_PDF_BYTES)
    throw new ResearchError("论文文件无法生成封面", 422);
  return actual;
}

async function fileEtag(filename: string): Promise<string> {
  const hash = createHash("sha256");
  for await (const chunk of createReadStream(filename)) hash.update(chunk);
  return `"${hash.digest("hex")}"`;
}

async function readImage(filename: string): Promise<Uint8Array | null> {
  try {
    const stat = await fs.lstat(filename);
    if (!stat.isFile() || stat.size > MAX_IMAGE_BYTES || stat.size < 24)
      return null;
    const bytes = await fs.readFile(filename);
    const signature = Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]);
    if (!bytes.subarray(0, 8).equals(signature)) return null;
    const width = bytes.readUInt32BE(16);
    const height = bytes.readUInt32BE(20);
    if (width < 1 || height < 1 || width > MAX_EDGE || height > MAX_EDGE)
      return null;
    return bytes;
  } catch (error) {
    if (error instanceof Error && "code" in error && error.code === "ENOENT")
      return null;
    throw error;
  }
}

function renderFirstPage(pdf: string, prefix: string): Promise<void> {
  return new Promise((resolve, reject) => {
    // No shell, caller-supplied path or model service is involved. Poppler sees
    // an immutable private copy, one page and a bounded output resolution.
    execFile(
      "pdftoppm",
      [
        "-f",
        "1",
        "-l",
        "1",
        "-singlefile",
        "-scale-to",
        String(MAX_EDGE),
        "-png",
        pdf,
        prefix,
      ],
      {
        windowsHide: true,
        timeout: COVER_RENDER_TIMEOUT_MS,
        killSignal: "SIGKILL",
        maxBuffer: 64 * 1024,
      },
      (error) => {
        if (error) reject(new ResearchError("封面暂时不可用", 503));
        else resolve();
      },
    );
  });
}

async function pruneOldCovers(
  directory: string,
  current: string,
): Promise<void> {
  const files = await fs.readdir(directory);
  const cached = await Promise.all(
    files
      .filter((file) => /^[a-f0-9]{64}\.png$/.test(file))
      .map(async (file) => ({
        filename: path.join(directory, file),
        modified: (await fs.stat(path.join(directory, file))).mtimeMs,
      })),
  );
  cached.sort((a, b) => b.modified - a.modified);
  for (const file of cached.slice(2))
    if (file.filename !== current)
      await fs.unlink(file.filename).catch(() => undefined);
}

async function prepareCover(
  paperId: string,
  source: { path: string; etag: string },
  directory: string,
  cacheFile: string,
): Promise<Cover> {
  const etag = `"${COVER_VERSION}-${createHash("sha256").update(source.etag).digest("hex")}"`;
  const cached = await readImage(cacheFile);
  if (cached) return { bytes: cached, etag, pdfEtag: source.etag };
  const release = await renderSlot();
  let temporary: string | undefined;
  try {
    await fs.mkdir(directory, { recursive: true, mode: 0o700 });
    temporary = await fs.mkdtemp(path.join(directory, ".render-"));
    const snapshot = path.join(temporary, "source.pdf");
    await fs.copyFile(await checkedPdfPath(source.path), snapshot);
    await fs.chmod(snapshot, 0o600);
    if ((await fileEtag(snapshot)) !== source.etag)
      throw new ResearchError("论文正在更新，请稍后重试", 409);
    const handle = await fs.open(snapshot, "r");
    try {
      const header = Buffer.alloc(1024);
      await handle.read(header, 0, header.length, 0);
      if (!header.includes(Buffer.from("%PDF-")))
        throw new ResearchError("论文文件不是有效 PDF", 422);
    } finally {
      await handle.close();
    }
    const prefix = path.join(temporary, "cover");
    await renderFirstPage(snapshot, prefix);
    const bytes = await readImage(`${prefix}.png`);
    if (!bytes) throw new ResearchError("封面暂时不可用", 503);
    // Never publish a cover under an old PDF version after an external save.
    const paper = paperById(paperId);
    await checkedPdfPath(paperPdfPath(paper));
    const current = await readVersionedPdfFile(
      paper.library.topic,
      paper.library.slug,
    );
    if (current?.etag !== source.etag)
      throw new ResearchError("论文正在更新，请稍后重试", 409);
    await fs.chmod(`${prefix}.png`, 0o600);
    await fs.rename(`${prefix}.png`, cacheFile);
    await pruneOldCovers(directory, cacheFile).catch(() => undefined);
    return { bytes, etag, pdfEtag: source.etag };
  } finally {
    if (temporary && within(directory, temporary))
      await fs
        .rm(temporary, { recursive: true, force: true })
        .catch(() => undefined);
    release();
  }
}

export async function researchCoverResponse(
  request: Request,
  paperId: string,
): Promise<Response> {
  idSchema.parse(paperId);
  const paper = paperById(paperId);
  // Resolve only a known library record; URL parameters never select files.
  await checkedPdfPath(paperPdfPath(paper));
  const source = await readVersionedPdfFile(
    paper.library.topic,
    paper.library.slug,
  );
  if (!source) throw new ResearchError("论文文件不存在", 404);
  await checkedPdfPath(source.path);
  const directory = path.join(
    getResearchDataDir(),
    "cache",
    "covers",
    COVER_VERSION,
    paperId,
  );
  const filename = createHash("sha256").update(source.etag).digest("hex");
  const cacheFile = path.join(directory, `${filename}.png`);
  const key = cacheFile;
  let pending = inflight.get(key);
  if (!pending) {
    pending = prepareCover(paperId, source, directory, cacheFile);
    inflight.set(key, pending);
    void pending.finally(() => inflight.delete(key)).catch(() => undefined);
  }
  const cover = await pending;
  const version = new URL(request.url).searchParams.get("v");
  const headers = {
    "content-type": "image/png",
    "content-length": String(cover.bytes.byteLength),
    etag: cover.etag,
    "cache-control":
      version === cover.pdfEtag
        ? "private, max-age=86400, immutable"
        : "private, no-cache",
    "x-content-type-options": "nosniff",
  };
  if (
    request.headers
      .get("if-none-match")
      ?.split(/\s*,\s*/)
      .includes(cover.etag)
  )
    return new Response(null, { status: 304, headers });
  return new Response(
    request.method === "HEAD" ? null : new Uint8Array(cover.bytes).buffer,
    { headers },
  );
}

import type {
  AnswerStyle,
  ResearchPage,
  StartResearchRunInput,
} from "../types";
import { discussionSearchTerms } from "./concepts";

export function effectiveAnswerStyle(
  input: Pick<
    StartResearchRunInput,
    "answerStyle" | "mode" | "question" | "learning"
  >,
): AnswerStyle {
  if (
    input.mode !== "ask" ||
    /^\s*\[学习笔记:/.test(input.question) ||
    (input.learning && input.learning.task !== "explain")
  )
    return "grounded";
  return input.answerStyle ?? "discussion";
}

export function passageWindow(
  text: string,
  query: string,
  maximum: number,
): string {
  if (text.length <= maximum) return text;
  const terms = discussionSearchTerms(query);
  const lower = text.normalize("NFKC").toLowerCase();
  const hit =
    terms.map((term) => lower.indexOf(term)).find((index) => index >= 0) ?? 0;
  const start = Math.max(
    0,
    Math.min(hit - Math.floor(maximum / 3), text.length - maximum),
  );
  return text.slice(start, start + maximum);
}

/** Keep the exact selection plus small real-page excerpts, never a fabricated page. */
export function compactDiscussionPages(
  input: StartResearchRunInput,
): ResearchPage[] {
  const { pages } = input.context;
  const selected = input.selection;
  const question = input.question.replace(/^\[[^\]]+\]\s*/, "");
  const terms = discussionSearchTerms(
    question + "\n" + (selected?.text ?? selected?.quote ?? "").slice(0, 700),
  );
  const ranked = pages
    .map((page) => {
      const lower = page.text.normalize("NFKC").toLowerCase();
      return {
        page,
        score: terms.reduce(
          (sum, term) =>
            sum + (lower.includes(term) ? Math.min(10, term.length) : 0),
          0,
        ),
      };
    })
    .filter((entry) => entry.score > 0)
    .sort((a, b) => b.score - a.score || a.page.page - b.page.page);
  const picked = new Map<number, ResearchPage>();
  if (selected) {
    const original = pages.find((page) => page.page === selected.page);
    if (original)
      picked.set(original.page, {
        ...original,
        text: passageWindow(
          original.text,
          selected.text ?? selected.quote ?? "",
          1800,
        ),
      });
  }
  for (const entry of ranked) {
    if (picked.size >= (selected ? 3 : 4)) break;
    if (!picked.has(entry.page.page))
      picked.set(entry.page.page, {
        ...entry.page,
        text: passageWindow(entry.page.text, question, selected ? 900 : 1800),
      });
  }
  if (!picked.size && pages[0])
    picked.set(pages[0].page, {
      ...pages[0],
      text: pages[0].text.slice(0, 1800),
    });
  return [...picked.values()];
}

import { ResearchError, validateSources, readWorkspace } from "../store";
import type { StartResearchRunInput } from "../types";
import { effectiveAnswerStyle } from "./context";

/** Validate selected evidence and concept IDs before any model call. */
export function prepareQuestionInput(
  input: StartResearchRunInput,
): StartResearchRunInput {
  const answerStyle = effectiveAnswerStyle(input);
  const referenceConceptIds =
    input.mode === "ask" || input.mode === "concept"
      ? input.referenceConceptIds
      : undefined;
  if (
    answerStyle === "discussion" &&
    (input.selection?.text ?? input.selection?.quote ?? "").length > 6000
  )
    throw new ResearchError(
      "选文较长，请选择不超过6000字的一段原文；可分段继续讨论",
    );
  if (
    referenceConceptIds?.some(
      (id) => !input.context.knowledge.some((entry) => entry.id === id),
    )
  )
    throw new ResearchError("部分参考概念已不存在，请重新选择", 404);
  let selection = input.selection;
  if (input.mode === "ask" && !input.learning && selection) {
    const text = (selection.text ?? selection.quote ?? "").trim();
    if (!text) throw new ResearchError("选文为空，请重新选择");
    if (
      selection.contentRevision &&
      selection.contentRevision !== input.context.paper.contentRevision
    )
      throw new ResearchError("选文已过期，请重新选择", 409);
    validateSources(
      [
        {
          paperId: input.paperId,
          page: selection.page,
          quote: text,
          contentRevision: selection.contentRevision,
        },
      ],
      readWorkspace(),
      input.paperId,
    );
    selection = {
      ...selection,
      text,
      quote: text,
      contentRevision: input.context.paper.contentRevision,
    };
  }
  return { ...input, answerStyle, referenceConceptIds, selection };
}

import { z } from "zod";
import {
  activeWorkspace,
  digest,
  expectedVersion,
  mutateWorkspace,
  paperById,
  paperPages,
  ResearchError,
  validateSources,
  type WorkspaceState,
} from "./store";
import type {
  GraphEdge,
  GraphNode,
  ResearchGraph,
  ResearchRun,
  SourceRef,
} from "./types";

function normalize(value: string) {
  return value
    .normalize("NFKC")
    .toLowerCase()
    .replace(/[\s\p{P}]+/gu, "");
}
function conceptId(name: string) {
  return `concept-${digest(normalize(name)).slice(0, 24)}`;
}
function knowledgeNodeId(
  state: WorkspaceState,
  entry: { id: string; title: string },
) {
  return (
    state.graph.nodes.find((n) => n.knowledgeId === entry.id)?.id ||
    conceptId(entry.title)
  );
}
function edgeId(source: string, target: string, kind: string) {
  return `edge-${digest([source, target, kind]).slice(0, 32)}`;
}
function attachNode(state: WorkspaceState, node: GraphNode) {
  if (!state.graph.nodes.some((n) => n.id === node.id))
    state.graph.nodes.push(node);
}
function attachEdge(
  state: WorkspaceState,
  edge: Omit<GraphEdge, "id" | "createdAt" | "updatedAt" | "version">,
  conceptKey?: string,
): GraphEdge {
  const id = edgeId(
    edge.source,
    edge.target,
    conceptKey ? `${edge.kind}:${conceptKey}` : edge.kind,
  );
  const existing = state.graph.edges.find((e) => e.id === id);
  if (existing) {
    for (const source of edge.evidence)
      if (!existing.evidence.some((s) => digest(s) === digest(source)))
        existing.evidence.push(source);
    // Confirmation and rejection are user decisions; reruns cannot reset either.
    return existing;
  }
  const now = new Date().toISOString();
  const created: GraphEdge = {
    ...edge,
    id,
    version: 1,
    createdAt: now,
    updatedAt: now,
  };
  state.graph.edges.push(created);
  return created;
}
function baseGraph(state: WorkspaceState) {
  const confirmedNotes = new Set(
    state.notes.filter((n) => n.confirmed).map((n) => n.id),
  );
  const removed = new Set(
    state.graph.nodes
      .filter((n) => n.noteId && !confirmedNotes.has(n.noteId))
      .map((n) => n.id),
  );
  state.graph.nodes = state.graph.nodes.filter((n) => !removed.has(n.id));
  state.graph.edges = state.graph.edges.filter(
    (e) => !removed.has(e.source) && !removed.has(e.target),
  );
  for (const paper of state.papers)
    attachNode(state, {
      id: `paper-${paper.id}`,
      kind: "paper",
      label: paper.title,
      title: paper.title,
      paperId: paper.id,
      topic: paper.topic,
    });
  for (const entry of state.knowledge)
    attachNode(state, {
      id: knowledgeNodeId(state, entry),
      kind: "concept",
      label: entry.title,
      title: entry.title,
      knowledgeId: entry.id,
      definition: entry.body,
    });
  for (const note of state.notes.filter((n) => n.confirmed)) {
    attachNode(state, {
      id: `note-${note.id}`,
      kind: "note",
      label: note.title,
      title: note.title,
      paperId: note.paperId,
      noteId: note.id,
    });
    attachEdge(state, {
      source: `note-${note.id}`,
      target: `paper-${note.paperId}`,
      kind: "source",
      label: "来源于",
      status: "confirmed",
      origin: "source",
      rationale: "用户确认的研究笔记",
      evidence: note.sources.length
        ? note.sources
        : [{ paperId: note.paperId, noteId: note.id }],
    });
  }
  // Reflect renamed papers/concepts and remove stale derived note nodes without discarding decisions.
  for (const node of state.graph.nodes) {
    if (node.kind === "paper") {
      const p = state.papers.find((p) => p.id === node.paperId);
      if (p)
        Object.assign(node, { label: p.title, title: p.title, topic: p.topic });
    }
    if (node.knowledgeId) {
      const k = state.knowledge.find((k) => k.id === node.knowledgeId);
      if (k)
        Object.assign(node, {
          label: k.title,
          title: k.title,
          definition: k.body,
        });
    }
    if (node.noteId) {
      const n = state.notes.find((n) => n.id === node.noteId);
      if (n) Object.assign(node, { label: n.title, title: n.title });
    }
  }
  for (const edge of state.graph.edges) {
    const stale = edge.evidence.some(
      (source) =>
        source.paperId &&
        source.contentRevision &&
        state.papers.find((p) => p.id === source.paperId)?.contentRevision !==
          source.contentRevision,
    );
    edge.stale =
      edge.kind === "shared_concept" ? Boolean(edge.stale || stale) : stale;
  }
}
/** Evidence-backed topical overlap, never an inferred citation or claim of agreement. */
function sharedConceptEdges(state: WorkspaceState, create: boolean): void {
  const literal = (value: string) =>
    value.normalize("NFKC").replace(/\s+/g, "").toLowerCase();
  const pagesByPaper = new Map<string, ReturnType<typeof paperPages>>();
  const memberships = new Map<string, Map<string, SourceRef[]>>();
  for (const edge of state.graph.edges) {
    if (edge.kind !== "mentions" || edge.status === "rejected" || edge.stale)
      continue;
    const paperNode = state.graph.nodes.find(
      (n) => n.id === edge.source && n.kind === "paper",
    );
    const concept = state.graph.nodes.find(
      (n) => n.id === edge.target && n.kind === "concept",
    );
    if (!paperNode?.paperId || !concept) continue;
    const paper = state.papers.find((p) => p.id === paperNode.paperId);
    if (!paper) continue;
    const entry = state.knowledge.find((k) => k.id === concept.knowledgeId);
    const names = [
      entry?.title || concept.label,
      ...(entry?.aliases || []),
    ].filter((n) => n.trim().length > 1);
    if (!pagesByPaper.has(paper.id))
      pagesByPaper.set(paper.id, paperPages(paper));
    const pages = pagesByPaper.get(paper.id) || [];
    const valid = edge.evidence.filter((source) => {
      if (
        source.paperId !== paper.id ||
        source.contentRevision !== paper.contentRevision ||
        !source.page ||
        !source.quote
      )
        return false;
      const page = pages.find((p) => p.page === source.page);
      return Boolean(
        page &&
        literal(page.text).includes(literal(source.quote)) &&
        names.some((name) =>
          literal(source.quote || "").includes(literal(name)),
        ),
      );
    });
    if (!valid.length) continue;
    const papers =
      memberships.get(concept.id) || new Map<string, SourceRef[]>();
    papers.set(paperNode.id, valid);
    memberships.set(concept.id, papers);
  }
  const active = new Set<string>();
  for (const [conceptKey, papers] of memberships) {
    const ids = [...papers.keys()].sort();
    const label =
      state.graph.nodes.find((n) => n.id === conceptKey)?.label || "同一概念";
    for (let i = 0; i < ids.length; i++)
      for (let j = i + 1; j < ids.length; j++) {
        const source = ids[i],
          target = ids[j];
        const id = edgeId(source, target, `shared_concept:${conceptKey}`);
        active.add(id);
        if (!create) continue;
        const evidence = [papers.get(source)![0], papers.get(target)![0]];
        const existing = state.graph.edges.find((e) => e.id === id);
        const changed = Boolean(
          existing && digest(existing.evidence) !== digest(evidence),
        );
        const edge = attachEdge(
          state,
          {
            source,
            target,
            kind: "shared_concept",
            label: "共同涉及概念",
            status: "candidate",
            origin: "source",
            rationale: `双方原文均涉及“${label}”。此关系只表示共同主题，不表示论文之间存在引用、因果、支持或反驳关系，请核对双方原文。`,
            evidence,
          },
          conceptKey,
        );
        if (changed) {
          edge.stale = true;
          edge.version++;
          edge.updatedAt = new Date().toISOString();
        }
      }
  }
  for (const edge of state.graph.edges) {
    if (edge.kind === "shared_concept" && !active.has(edge.id) && !edge.stale) {
      edge.stale = true;
      edge.version++;
      edge.updatedAt = new Date().toISOString();
    }
  }
}
export async function getResearchGraph(): Promise<ResearchGraph> {
  return mutateWorkspace((state) => {
    baseGraph(state);
    sharedConceptEdges(state, false);
    return activeWorkspace(state).graph;
  });
}
export async function suggestGraph(paperId?: string): Promise<ResearchGraph> {
  return mutateWorkspace((state) => {
    baseGraph(state);
    const papers = paperId
      ? [paperById(paperId, state)]
      : activeWorkspace(state).papers;
    for (const paper of papers) {
      const pages = paperPages(paper);
      for (const entry of state.knowledge) {
        const names = [entry.title, ...entry.aliases].filter(
          (n) => n.trim().length > 1,
        );
        const evidence: SourceRef[] = [];
        for (const page of pages) {
          const found = names.find((n) =>
            page.text.toLowerCase().includes(n.toLowerCase()),
          );
          if (!found) continue;
          const start = page.text.toLowerCase().indexOf(found.toLowerCase());
          evidence.push({
            paperId: paper.id,
            page: page.page,
            quote: page.text.slice(
              Math.max(0, start - 50),
              start + found.length + 100,
            ),
            contentRevision: paper.contentRevision,
          });
          if (evidence.length >= 3) break;
        }
        if (evidence.length)
          attachEdge(state, {
            source: `paper-${paper.id}`,
            target: knowledgeNodeId(state, entry),
            kind: "mentions",
            label: "涉及概念",
            status: "candidate",
            origin: "source",
            rationale:
              "通过原文中的概念名称及别名匹配得到；出现术语不代表验证该理论，请核对来源后确认。",
            evidence,
          });
      }
    }
    sharedConceptEdges(state, true);
    state.graph.version++;
    return activeWorkspace(state).graph;
  });
}
const extractionSchema = z.object({
  concepts: z
    .array(
      z.object({
        name: z.string().min(1).max(200),
        definition: z.string().max(4000),
        page: z.number().int().positive(),
        quote: z.string().min(2).max(5000),
        relation: z.enum(["discusses", "uses_method", "reports"]),
      }),
    )
    .max(30),
});
function parseExtraction(text: string) {
  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/i)?.[1];
  const raw =
    fenced || text.slice(text.indexOf("{"), text.lastIndexOf("}") + 1);
  try {
    return extractionSchema.safeParse(JSON.parse(raw) as unknown);
  } catch {
    return null;
  }
}
export async function applyGraphRun(run: ResearchRun): Promise<void> {
  if (run.mode !== "graph" || run.status !== "completed") return;
  const parsed = parseExtraction(run.answer);
  if (!parsed?.success) return;
  await mutateWorkspace((state) => {
    const actionKey = `graph-${run.id}`;
    if (state.actions[actionKey]) return;
    if (state.papers.find((p) => p.id === run.paperId)?.trashedAt) return;
    const paper = paperById(run.paperId, state);
    if (run.contentRevision && run.contentRevision !== paper.contentRevision)
      return;
    const pages = paperPages(paper);
    baseGraph(state);
    for (const concept of parsed.data.concepts) {
      const page = pages.find((p) => p.page === concept.page);
      const literal = (value: string) =>
        value.normalize("NFKC").replace(/\s+/g, "").toLowerCase();
      if (!page || !literal(page.text).includes(literal(concept.quote)))
        continue;
      const existing = state.knowledge.find((k) =>
        [k.title, ...k.aliases].some(
          (n) => normalize(n) === normalize(concept.name),
        ),
      );
      const target = existing
        ? knowledgeNodeId(state, existing)
        : conceptId(concept.name);
      attachNode(state, {
        id: target,
        kind: "concept",
        title: existing?.title || concept.name,
        label: existing?.title || concept.name,
        definition: existing?.body || concept.definition,
        knowledgeId: existing?.id,
      });
      const labels = {
        discusses: "讨论",
        uses_method: "使用方法",
        reports: "报告观点",
      };
      attachEdge(state, {
        source: `paper-${paper.id}`,
        target,
        kind: concept.relation,
        label: labels[concept.relation],
        status: "candidate",
        origin: "ai",
        rationale: "PaperFlow 从原文提取。请人工核对关系是否准确。",
        evidence: [
          {
            paperId: paper.id,
            page: concept.page,
            quote: concept.quote,
            contentRevision: paper.contentRevision,
          },
        ],
      });
    }
    state.actions[actionKey] = {
      kind: "graph",
      id: run.id,
      digest: digest(run.answer),
    };
    state.graph.version++;
  });
}
export async function decideGraphEdge(
  id: string,
  decision: "confirmed" | "rejected" | "candidate",
  version?: number,
): Promise<ResearchGraph> {
  return mutateWorkspace((state) => {
    baseGraph(state);
    sharedConceptEdges(state, false);
    const edge = state.graph.edges.find((e) => e.id === id);
    if (!edge) throw new ResearchError("未找到关系", 404);
    if (!activeWorkspace(state).graph.edges.some((e) => e.id === id))
      throw new ResearchError("关系来源已移入回收站，请先恢复论文", 410);
    expectedVersion(edge.version, version);
    if (decision === "confirmed") {
      if (edge.kind === "shared_concept" && edge.stale)
        throw new ResearchError(
          "共同概念的来源已改变，请重新生成并核对双方原文",
          409,
        );
      if (!edge.evidence.length)
        throw new ResearchError("没有来源证据，无法确认关系");
      for (const source of edge.evidence) {
        if (source.paperId) {
          const paper = paperById(source.paperId, state);
          if (
            source.contentRevision &&
            source.contentRevision !== paper.contentRevision
          )
            throw new ResearchError("来源正文已变更，请重新核对", 409);
        }
      }
    }
    edge.status = decision;
    edge.version++;
    edge.updatedAt = new Date().toISOString();
    state.graph.version++;
    return activeWorkspace(state).graph;
  });
}
export async function addManualGraphEdge(input: {
  source: string;
  target: string;
  kind?: string;
  label?: string;
  rationale?: string;
  evidence: SourceRef[];
}): Promise<ResearchGraph> {
  return mutateWorkspace((state) => {
    baseGraph(state);
    const nodes = activeWorkspace(state).graph.nodes;
    if (
      !nodes.some((n) => n.id === input.source) ||
      !nodes.some((n) => n.id === input.target)
    )
      throw new ResearchError("关系节点不存在");
    if (input.source === input.target)
      throw new ResearchError("不能将节点关联到自身");
    if (!input.evidence.length)
      throw new ResearchError("人工关联也需要注明来源");
    attachEdge(state, {
      source: input.source,
      target: input.target,
      kind: input.kind || "related",
      label: input.label || "人工关联",
      status: "confirmed",
      origin: "user",
      rationale: input.rationale || "",
      evidence: validateSources(input.evidence, state),
    });
    state.graph.version++;
    return activeWorkspace(state).graph;
  });
}
export function graphStats() {
  const graph = activeWorkspace().graph;
  return {
    nodes: graph.nodes.length,
    candidates: graph.edges.filter((e) => e.status === "candidate").length,
    confirmed: graph.edges.filter((e) => e.status === "confirmed").length,
  };
}

import type { ResearchAnnotation } from "./types";

const normalize = (value: string) =>
  value.normalize("NFKC").replace(/\s+/g, "").toLowerCase();
const ordered = (rects: number[][]) =>
  [...rects].sort((a, b) => a[1] - b[1] || a[0] - b[0]);

/** Match a passage by its page, text and PDF coordinates, independent of zoom/color. */
export function sameHighlightSelection(
  annotation: ResearchAnnotation,
  input: {
    paperId: string;
    page: number;
    quote: string;
    rects: number[][];
    contentRevision?: string;
  },
): boolean {
  if (
    annotation.kind !== "highlight" ||
    annotation.paperId !== input.paperId ||
    annotation.page !== input.page ||
    !input.quote.trim() ||
    normalize(annotation.quote || annotation.text) !== normalize(input.quote) ||
    (annotation.contentRevision &&
      input.contentRevision &&
      annotation.contentRevision !== input.contentRevision) ||
    !input.rects.length ||
    annotation.rects.length !== input.rects.length
  )
    return false;
  const previous = ordered(annotation.rects),
    next = ordered(input.rects);
  return previous.every(
    (rect, index) =>
      rect.length === 4 &&
      next[index].length === 4 &&
      rect.every((value, point) => Math.abs(value - next[index][point]) <= 1),
  );
}

import { learningSchema } from "./learning-schema";
