  const local = JSON.parse(
    await fs.readFile(path.join(runsDir(), safeId(runId) + ".json"), "utf8"),
  ) as ResearchRun;
  const remote = await getResearchProvider().cancel(runId);
  const updated = mergeRun(local, remote);
  await saveRun(updated);
  return updated;
}
