const MAX_PDF = 100 * 1024 * 1024;
function runPython(command: string, args: string[]): Promise<string> {
  return new Promise((resolve) => {
    const child = spawn(command, args, {
      windowsHide: true,
      stdio: ["ignore", "pipe", "ignore"],
    });
    let output = "";
    const timer = setTimeout(() => child.kill(), 45000);
    child.stdout.on("data", (chunk: Buffer) => {
      output += chunk.toString("utf8");
      if (output.length > 16 * 1024 * 1024) child.kill();
    });
    child.on("error", () => {
      clearTimeout(timer);
      resolve("");
    });
    child.on("close", (code) => {
      clearTimeout(timer);
      resolve(code === 0 ? output : "");
    });
  });
}
export async function parsePdf(bytes: Uint8Array): Promise<{
  pages: ResearchPage[];
  contentRevision: string;
  textWarning?: string;
  title?: string;
}> {
  if (bytes.byteLength > MAX_PDF)
    throw new ResearchError("PDF 文件不能超过100 MB", 413);
  if (!Buffer.from(bytes.subarray(0, 1024)).includes(Buffer.from("%PDF-")))
    throw new ResearchError("上传内容不是 PDF", 422);
  let doc: PDFDocument;
  try {
    doc = await PDFDocument.load(bytes, { updateMetadata: false });
  } catch {
    throw new ResearchError("PDF 损坏或受密码保护，无法读取", 422);
  }
  const dims = doc.getPages().map((page) => {
    const box = page.getMediaBox();
    return { width: box.width, height: box.height };
  });
  if (dims.length > 1500)
    throw new ResearchError("本地演示版单篇最多支持1500页", 413);
  const temp = path.join(
    getResearchDataDir(),
    "parsing",
    `${randomUUID()}.pdf`,
  );
  atomicWrite(temp, bytes);
  let texts: string[] = [];
  try {
    const poppler = await extractPdfText(temp);
    if (poppler.trim()) texts = poppler.split("\f");
    if (!texts.some((v) => v.trim())) {
      const script =
        'import sys,json\nfrom pypdf import PdfReader\nr=PdfReader(sys.argv[1])\nprint(json.dumps([p.extract_text() or "" for p in r.pages],ensure_ascii=True))';
      const commands = [
        process.env.RESEARCH_PYTHON,
        process.env.PYTHON_EXECUTABLE,
        "python",
        "py",
      ].filter((v): v is string => !!v);
      for (const command of [...new Set(commands)]) {
        const result = await runPython(command, ["-c", script, temp]);
        if (result) {
          try {
            const parsed: unknown = JSON.parse(result);
            if (
              Array.isArray(parsed) &&
              parsed.every((t) => typeof t === "string")
            ) {
              texts = parsed;
              break;
            }
          } catch {
            /* Try the next installed runtime. */
          }
        }
      }
    }
  } finally {
    fs.rmSync(temp, { force: true });
  }
  const pages = dims.map((dim, i) => ({
    page: i + 1,
    text: (texts[i] || "").replace(/\0/g, ""),
    ...dim,
  }));
  const contentRevision = digest(pages);
  return {
    pages,
    contentRevision,
    title: doc.getTitle()?.trim().slice(0, 500) || undefined,
    textWarning: pages.some((p) => p.text.trim())
      ? undefined
      : "没有提取到文字层。文件已保存，可阅读和批注；本版不自动OCR，请上传带文字层的PDF。",
  };
}
export async function researchPdfResponse(
  request: Request,
  paperId: string,
): Promise<Response> {
  const paper = paperById(paperId);
  const file = await readVersionedPdfFile(
    paper.library.topic,
    paper.library.slug,
  );
  if (!file) throw new ResearchError("PDF文件不存在", 404);
  if (request.method === "HEAD")
    return new Response(null, {
      headers: {
        etag: file.etag,
        "content-length": String(file.size),
        "accept-ranges": "bytes",
        "cache-control": "private, no-cache",
      },
    });
  return fileResponse({
    path: file.path,
    size: file.size,
    etag: file.etag,
    headers: request.headers,
    contentType: "application/pdf",
    filename: `${paper.library.slug}.pdf`,
    cacheControl: "private, no-cache",
    extraHeaders: {
      "content-disposition": `inline; filename="${paper.library.slug}.pdf"; filename*=UTF-8''${encodeURIComponent(paper.filename)}`,
    },
  });
}
export async function saveResearchPdf(
  request: Request,
  paperId: string,
): Promise<{ etag: string }> {
  const paper = paperById(paperId);
  const expected = request.headers.get("if-match");
  if (!expected || !/^"[a-f0-9]{64}"$/.test(expected))
    throw new ResearchError("保存PDF需要If-Match版本", 428);
  if (!request.headers.get("content-type")?.startsWith("application/pdf"))
    throw new ResearchError("请提交application/pdf", 415);
  const declared = Number(request.headers.get("content-length") || 0);
  if (declared > MAX_PDF) throw new ResearchError("PDF超过100MB", 413);
  const bytes = new Uint8Array(await request.arrayBuffer());
  if (bytes.byteLength > MAX_PDF) throw new ResearchError("PDF超过100MB", 413);
  // Parse the replacement before commit. Annotation-only saves retain the same text/layout revision.
  const parsed = await parsePdf(bytes);
  const result = await replacePdf(
    paper.library.topic,
    paper.library.slug,
    expected,
    bytes,
  );
  await mutateWorkspace((state) => {
    const current = paperById(paperId, state);
    Object.assign(current, {
      // Publish the new ETag only with the annotation reconciliation below.
      // If interrupted here, recovery still notices the PDF-side change.
      contentRevision: parsed.contentRevision,
      pageCount: parsed.pages.length,
      textStatus: parsed.pages.some((p) => p.text.trim()) ? "ready" : "empty",
      textWarning: parsed.textWarning,
      version: current.version + 1,
      updatedAt: new Date().toISOString(),
    });
    writePaperPages(current, parsed.pages);
  });
  await synchronizeAnnotations(paperId);
  ensureResearchIndex(true);
  return result;
}
export async function saveNativeComment(
  paperId: string,
  action: PdfCommentAction,
  expected: string,
): Promise<{ etag: string }> {
  const paper = paperById(paperId);
  const result = await rewritePdf(
    paper.library.topic,
    paper.library.slug,
    (bytes) => rewriteResearchComment(bytes, action),
    expected,
  );
  await synchronizeAnnotations(paperId);
  return result;
}
function annotationName(bytes: Uint8Array, id: string): Promise<boolean> {
  return PDFDocument.load(bytes, { updateMetadata: false }).then((doc) =>
    doc.getPages().some((page) => {
      const annots = page.node.Annots();
      if (!annots) return false;
      return annots.asArray().some((ref) => {
        const object = doc.context.lookup(ref);
        if (!object || !("lookupMaybe" in object)) return false;
        const value = (object as import("pdf-lib").PDFDict).lookupMaybe(
          PDFName.of("NM"),
          PDFString,
          PDFHexString,
        );
        return value?.decodeText() === `jy-${id}`;
      });
    }),
  );
}
async function appendAnnotation(
  bytes: Uint8Array,
  a: ResearchAnnotation,
): Promise<Uint8Array> {
  // Pure highlights need no Text pin; both paths retain signed/encrypted-PDF protection.
  const createCompanion = !a.rects.length || !!a.comment.trim();
  const doc = createCompanion
    ? await PDFDocument.load(
        await updatePdfComment(
          bytes,
          {
            action: "create",
            page: a.page,
            x: a.rects[0]?.[0] ?? 20,
            y: a.rects[0]?.[1] ?? 20,
            text: a.comment || a.quote || "阅读批注",
          },
          "教研阅记",
          "local",
        ),
        { updateMetadata: false },
      )
    : await loadEditablePdf(bytes);
  const page = doc.getPages()[a.page - 1];
  if (!page) throw new ResearchError("批注页码无效");
  if (createCompanion) {
    const textAnnotations = page.node.Annots();
    const companion = textAnnotations?.lookup(textAnnotations.size() - 1);
    if (companion && "set" in companion)
      (companion as import("pdf-lib").PDFDict).set(
        PDFName.of("NM"),
        PDFString.of(`jy-${a.id}`),
      );
  }
  if (a.rects.length) {
    const [r, g, b] = [1, 3, 5].map(
      (offset) => parseInt(a.color.slice(offset, offset + 2), 16) / 255,
    );
    const box = page.getCropBox();
    for (const rect of a.rects) {
      const [x1, y1, x2, y2] = rect;
      if (
        x1 >= x2 ||
        y1 >= y2 ||
        x1 < box.x - 1 ||
        y1 < box.y - 1 ||
        x2 > box.x + box.width + 1 ||
        y2 > box.y + box.height + 1
      )
        throw new ResearchError("高亮位置超出PDF页面");
      const annotation = doc.context.obj({
        Type: "Annot",
        Subtype: "Highlight",
        Rect: rect,
        QuadPoints: [x1, y2, x2, y2, x1, y1, x2, y1],
        C: [r, g, b],
        CA: 0.35,
        F: 4,
        Contents: PDFHexString.fromText(a.comment || a.quote),
        T: PDFHexString.fromText("教研阅记"),
        NM: PDFString.of(`jy-${a.id}`),
      });
      page.node.addAnnot(doc.context.register(annotation));
    }
  }
  return doc.save();
}
export async function recoverAnnotations(): Promise<void> {
  const pending = activeWorkspace().pendingAnnotations;
  for (const item of pending) {
    const paper = paperById(item.annotation.paperId);
    const current = await readVersionedPdf(
      paper.library.topic,
      paper.library.slug,
    );
    if (!current) continue;
    if (await annotationName(current.bytes, item.annotation.id))
      await commitAnnotation(item.annotation, current.etag);
    else if (Date.now() - Date.parse(item.annotation.createdAt) > 5 * 60 * 1000)
      await mutateWorkspace((state) => {
        state.pendingAnnotations = state.pendingAnnotations.filter(
          (p) => p.annotation.id !== item.annotation.id,
        );
        delete state.actions[item.annotation.id];
      });
  }
  await recoverChangedAnnotations();
}
async function commitAnnotation(
  annotation: ResearchAnnotation,
  etag: string,
): Promise<void> {
  await mutateWorkspace((state) => {
    const paper = paperById(annotation.paperId, state);
    paper.pdfEtag = etag;
    paper.version++;
    paper.updatedAt = new Date().toISOString();
    if (!state.annotations.some((a) => a.id === annotation.id))
      state.annotations.push({ ...annotation, pdfSaved: true });
    state.pendingAnnotations = state.pendingAnnotations.filter(
      (a) => a.annotation.id !== annotation.id,
    );
  });
}
export async function createAnnotation(
  input: z.infer<typeof annotationSchema>,
): Promise<{
  annotation: ResearchAnnotation;
  paper: ReturnType<typeof paperById>;
  created: boolean;
}> {
  await recoverAnnotations();
  const paper = paperById(input.paperId);
  const fingerprint = digest({ ...input, actionId: undefined });
  const id = input.actionId || randomUUID();
  const existing = readWorkspace().actions[id];
  if (existing) {
    if (existing.digest !== fingerprint)
      throw new ResearchError("此动作 ID 已用于不同批注", 409);
    const saved = readWorkspace().annotations.find((a) => a.id === existing.id);
    if (saved)
      return { annotation: saved, paper: paperById(paper.id), created: false };
    if (
      readWorkspace().pendingAnnotations.some(
        (p) => p.annotation.id === existing.id,
      )
    )
      throw new ResearchError("这条批注正在保存，请稍后刷新", 409);
    throw new ResearchError("这条批注已被删除，原提交不会重新创建它", 410);
  }
  if (input.page > paper.pageCount)
    throw new ResearchError("批注页码超出论文范围");
  const version = await readVersionedPdf(
    paper.library.topic,
    paper.library.slug,
  );
  if (!version) throw new ResearchError("PDF不存在", 404);
  const expected = input.pdfEtag;
  if (!expected)
    throw new ResearchError("批注保存需要pdfEtag，请刷新论文", 428);
  if (expected !== version.etag)
    throw new ResearchError("PDF已改变，请刷新核对后再保存", 412);
  if (input.contentRevision && input.contentRevision !== paper.contentRevision)
    throw new ResearchError("正文已改变，请重新选择原文", 409);
  const quote = input.quote ?? input.text ?? "";
  const text = paperPages(paper).find((p) => p.page === input.page)?.text || "";
  const norm = (v: string) =>
    v.normalize("NFKC").replace(/\s+/g, "").toLowerCase();
  if (quote && text && !norm(text).includes(norm(quote)))
    throw new ResearchError("所选文字未在指定页找到，请核对页码");
  const rects = input.rects.length
    ? input.rects
    : (input.quads || []).map((q) => [
        Math.min(q[0], q[2], q[4], q[6]),
        Math.min(q[1], q[3], q[5], q[7]),
        Math.max(q[0], q[2], q[4], q[6]),
        Math.max(q[1], q[3], q[5], q[7]),
      ]);
  // Different clicks/action IDs on the same passage must not add a second PDF layer.
  // The lifecycle lock serializes this check with all research annotation writes;
  // ownership is rechecked in the actual PDF rather than inferred from UI records.
  if (rects.length) {
    const document = await loadEditablePdf(version.bytes);
    const owned = new Set(managedMarks(document).map((mark) => mark.name));
    const duplicate = readWorkspace().annotations.find(
      (annotation) =>
        owned.has(annotation.pdfName ?? `jy-${annotation.id}`) &&
        sameHighlightSelection(annotation, {
          paperId: paper.id,
          page: input.page,
          quote,
          rects,
          contentRevision: paper.contentRevision,
        }),
    );
    if (duplicate) {
      let saved = duplicate;
      if (
        input.comment.trim() &&
        input.comment.trim() !== duplicate.comment.trim()
      ) {
        if (duplicate.comment.trim())
          throw new ResearchError(
            "此处已有想法，请打开高亮后编辑，避免重复批注。",
            409,
          );
        const updated = await mutateAnnotation(
          duplicate.id,
          {
            version: duplicate.version,
            pdfEtag: expected,
            comment: input.comment.trim(),
          },
          false,
        );
        if ("annotation" in updated && updated.annotation)
          saved = updated.annotation;
      }
      await mutateWorkspace((state) => {
        if (state.actions[id] && state.actions[id].digest !== fingerprint)
          throw new ResearchError("此动作ID已用于不同内容", 409);
        state.actions[id] = {
          kind: "annotation",
          id: saved.id,
          digest: fingerprint,
        };
      });
      return { annotation: saved, paper: paperById(paper.id), created: false };
    }
  }
  const now = new Date().toISOString();
  const annotation: ResearchAnnotation = {
    id,
    paperId: paper.id,
    page: input.page,
    text: quote,
    quote,
    comment: input.comment,
    color: input.color,
    rects,
    kind: rects.length ? "highlight" : "comment",
    pdfName: `jy-${id}`,
    contentRevision: paper.contentRevision,
    createdAt: now,
    updatedAt: now,
    version: 1,
    pdfSaved: false,
  };
  await mutateWorkspace((state) => {
    if (state.actions[id] && state.actions[id].digest !== fingerprint)
      throw new ResearchError("此动作ID已用于不同内容", 409);
    if (!state.pendingAnnotations.some((p) => p.annotation.id === id))
      state.pendingAnnotations.push({ annotation, expectedEtag: expected });
    state.actions[id] = { kind: "annotation", id, digest: fingerprint };
  });
  try {
    const result = await rewritePdf(
      paper.library.topic,
      paper.library.slug,
      (bytes) => appendAnnotation(bytes, annotation),
      expected,
    );
    await commitAnnotation(annotation, result.etag);
    return {
      annotation: { ...annotation, pdfSaved: true },
      paper: paperById(paper.id),
      created: true,
    };
  } catch (error) {
    // Only a recoverable prepared record remains if the process died after committing the PDF.
    const current = await readVersionedPdf(
      paper.library.topic,
      paper.library.slug,
    ).catch(() => null);
    if (current && (await annotationName(current.bytes, id))) {
      await commitAnnotation(annotation, current.etag);
      return {
        annotation: { ...annotation, pdfSaved: true },
        paper: paperById(paper.id),
        created: true,
      };
    } else
      await mutateWorkspace((state) => {
        state.pendingAnnotations = state.pendingAnnotations.filter(
          (p) => p.annotation.id !== id,
        );
        delete state.actions[id];
      });
    throw error;
  }
}

import { z } from "zod";
import { FilesystemBusyError } from "../../filesystem-lock";
import { ResearchError } from "../store";
import {
  createPlannerTask,
  listPlannerTasks,
  plannerCalendar,
  plannerCreateSchema,
  plannerPatchSchema,
  updatePlannerTask,
} from "./core";

export async function handlePlannerRequest(
  request: Request,
  path: string[] = [],
) {
  const json = (value: unknown, status = 200) =>
    Response.json(value, { status, headers: { "cache-control": "no-store" } });
  try {
    const url = new URL(request.url);
    const host = request.headers.get("host") || url.host;
    if (!/^(localhost|127\.0\.0\.1|\[::1\])(?::\d+)?$/i.test(host))
      throw new ResearchError("研究待办仅允许本机访问", 403);
    if (request.method !== "GET" && request.method !== "HEAD") {
      const origin = request.headers.get("origin");
      if (
        (origin && origin !== `${url.protocol}//${host}`) ||
        request.headers.get("sec-fetch-site") === "cross-site"
      )
        throw new ResearchError("跨来源保存已拒绝", 403);
    }
    z.array(z.string().regex(/^[a-zA-Z0-9_-]{1,100}$/))
      .max(1)
      .parse(path);
    const [id] = path;
    if (request.method === "GET" && !id)
      return json({ tasks: listPlannerTasks() });
    if (request.method === "GET" && id === "calendar")
      return new Response(plannerCalendar(), {
        headers: {
          "content-type": "text/calendar; charset=utf-8",
          "content-disposition": 'attachment; filename="research-tasks.ics"',
          "cache-control": "no-store",
        },
      });
    if (Number(request.headers.get("content-length") || 0) > 65536)
      throw new ResearchError("待办内容过长", 413);
    if (request.method === "POST" && !id)
      return json(
        {
          task: await createPlannerTask(
            plannerCreateSchema.parse(await request.json()),
          ),
        },
        201,
      );
    if (request.method === "PATCH" && id)
      return json({
        task: await updatePlannerTask(
          id,
          plannerPatchSchema.parse(await request.json()),
        ),
      });
    throw new ResearchError("待办操作不存在", 404);
  } catch (error) {
    if (error instanceof ResearchError)
      return json({ error: error.message }, error.status);
    if (error instanceof z.ZodError || error instanceof SyntaxError)
      return json({ error: "请填写标题及有效的截止时间" }, 400);
    if (error instanceof FilesystemBusyError)
      return json({ error: "工作区正在保存，请稍后重试" }, 409);
    return json({ error: "待办未保存，请稍后重试" }, 500);
  }
}

/** Local, deterministic suggestions only. The user confirms the resulting form. */
export function parseDeadlineText(text: string, now = new Date()) {
  const normalized = text.replace(
    /([零一二两三四五六七八九十]{1,3})(?=[点时分])/g,
    (_match, value: string) => {
      const digits = "零一二三四五六七八九";
      const number = value.replaceAll("两", "二");
      const parts = number.split("十");
      const hour =
        parts.length === 2
          ? (parts[0] ? digits.indexOf(parts[0]) : 1) * 10 +
            (parts[1] ? digits.indexOf(parts[1]) : 0)
          : digits.indexOf(number);
      return String(hour);
    },
  );
  const localNow = new Date(now.getTime() + 8 * 60 * 60 * 1000);
  const today = Date.UTC(
    localNow.getUTCFullYear(),
    localNow.getUTCMonth(),
    localNow.getUTCDate(),
  );
  let day: Date | undefined;
  const absolute = /(\d{4})[-年/](\d{1,2})[-月/](\d{1,2})日?/.exec(text);
  if (absolute) {
    const year = Number(absolute[1]);
    const month = Number(absolute[2]);
    const date = Number(absolute[3]);
    const candidate = new Date(Date.UTC(year, month - 1, date));
    if (
      candidate.getUTCFullYear() === year &&
      candidate.getUTCMonth() === month - 1 &&
      candidate.getUTCDate() === date
    )
      day = candidate;
  } else if (/后天/.test(text)) day = new Date(today + 2 * 86400000);
  else if (/明天/.test(text)) day = new Date(today + 86400000);
  else if (/今天/.test(text)) day = new Date(today);
  else {
    const week = /(下周|本周|这周|周|星期)([一二三四五六日天])/.exec(text);
    if (week) {
      const weekday = "日一二三四五六".indexOf(
        week[2] === "天" ? "日" : week[2],
      );
      const current = new Date(today).getUTCDay();
      let delta = (weekday - current + 7) % 7;
      if (week[1] === "下周")
        delta = ((weekday + 6) % 7) - ((current + 6) % 7) + 7;
      if (week[1] === "本周" || week[1] === "这周")
        delta = ((weekday + 6) % 7) - ((current + 6) % 7);
      day = new Date(today + delta * 86400000);
    }
  }
  const time =
    /(上午|下午|晚上|中午|早上)?\s*(\d{1,2})(?::(\d{2})(?!\d)|[点时](半|\d{1,2}分?)?)/.exec(
      normalized,
    );
  let hour = time ? Number(time[2]) : 17;
  let minute = time?.[3]
    ? Number(time[3])
    : time?.[4] === "半"
      ? 30
      : Number(time?.[4]?.replace("分", "") || 0);
  if (time?.[1] && /下午|晚上|中午/.test(time[1]) && hour < 12) hour += 12;
  if (time?.[1] && /上午|早上/.test(time[1]) && hour === 12) hour = 0;
  const unsupportedTime =
    !time && /(上午|下午|晚上|中午|早上|\d[点时]|\d:\d)/.test(normalized);
  const leftoverTime =
    time &&
    /^(?:[零一二两三四五六七八九十\d]|半|刻)/.test(
      normalized.slice(time.index + time[0].length),
    );
  if (hour > 23 || minute > 59 || unsupportedTime || leftoverTime) {
    day = undefined;
    hour = 17;
    minute = 0;
  }
  const datePart = day?.toISOString().slice(0, 10);
  const dueLocal = datePart
    ? `${datePart}T${String(hour).padStart(2, "0")}:${String(minute).padStart(2, "0")}`
    : "";
  const title = normalized
    .replace(/(\d{4})[-年/](\d{1,2})[-月/](\d{1,2})日?/, "")
    .replace(/今天|明天|后天|(下周|本周|这周|周|星期)[一二三四五六日天]/, "")
    .replace(
      /(上午|下午|晚上|中午|早上)?\s*\d{1,2}(?::\d{2}|[点时](?:半|\d{1,2}分?)?)/,
      "",
    )
    .replace(/之前|以前|截止|到期|请提醒我|提醒我|我要|我需要/g, "")
    .replace(/^[，,\s]+|[，,\s]+$/g, "");
  return {
    title: title || text.trim(),
    dueLocal,
    priority: /紧急|重要|优先/.test(text)
      ? ("high" as const)
      : ("normal" as const),
  };
}

export function shanghaiInput(iso: string): string {
  return new Date(new Date(iso).getTime() + 8 * 3600000)
    .toISOString()
    .slice(0, 16);
}

import { z } from "zod";
import { idSchema } from "../schemas";
import { ResearchError } from "../store";
import {
  createReviewDeck,
  getReviewDeck,
  listReviewDecks,
  saveReviewAttempt,
  saveReviewResponse,
  saveReviewSession,
  updateReviewQuestion,
} from "./core";
import {
  reviewAttemptSchema,
  reviewCreateSchema,
  reviewQuestionSchema,
  reviewResponseSchema,
  reviewSessionSchema,
} from "./schemas";

/** Called only after the research API's local-host and mutation origin guard. */
export async function handleReviewRequest(
  request: Request,
  segments: string[],
): Promise<Response> {
  const json = (value: unknown, status = 200) =>
    Response.json(value, {
      status,
      headers: { "cache-control": "no-store" },
    });
  const [id, action] = segments;
  if (segments.length > 2) throw new ResearchError("复习操作不存在", 404);
  if (id) idSchema.parse(id);
  const url = new URL(request.url);
  if (request.method === "GET") {
    if (id && !action) return json({ deck: getReviewDeck(id) });
    if (!id) {
      const filter = z
        .object({ paperId: idSchema.optional(), noteId: idSchema.optional() })
        .parse({
          paperId: url.searchParams.get("paperId") || undefined,
          noteId: url.searchParams.get("noteId") || undefined,
        });
      return json({ decks: listReviewDecks(filter.paperId, filter.noteId) });
    }
  }
  if (Number(request.headers.get("content-length") || 0) > 2 * 1024 * 1024)
    throw new ResearchError("题组内容过长", 413);
  let input: unknown;
  try {
    input = await request.json();
  } catch {
    throw new ResearchError("请求必须包含有效 JSON");
  }
  if (request.method === "POST" && !id) {
    const deck = await createReviewDeck(reviewCreateSchema.parse(input));
    return json({ deck: getReviewDeck(deck.id) }, 201);
  }
  if (request.method === "PATCH" && id && action) {
    if (action === "attempt")
      await saveReviewAttempt(id, reviewAttemptSchema.parse(input));
    else if (action === "response")
      await saveReviewResponse(id, reviewResponseSchema.parse(input));
    else if (action === "session")
      await saveReviewSession(id, reviewSessionSchema.parse(input));
    else if (action === "question")
      await updateReviewQuestion(id, reviewQuestionSchema.parse(input));
    else throw new ResearchError("复习操作不存在", 404);
    return json({ deck: getReviewDeck(id) });
  }
  throw new ResearchError("复习操作不存在或不支持此方法", 404);
}

import { randomUUID } from "node:crypto";
import type { z } from "zod";
import { recordedRunPaperIds } from "../context-scope";
import { getResearchHistory } from "../paperflow-client";
import {
  activeWorkspace,
  digest,
  expectedVersion,
  mutateWorkspace,
  paperById,
  readWorkspace,
  ResearchError,
  safeId,
  validateSources,
  type WorkspaceState,
} from "../store";
import type { SourceRef } from "../types";
import { citedReviewPages, parseReviewMarkdown } from "./parse";
import type {
  reviewAttemptSchema,
  reviewCreateSchema,
  reviewQuestionSchema,
  reviewResponseSchema,
  reviewSessionSchema,
} from "./schemas";
import type { ReviewDeck, ReviewQuestion, ReviewQuestionInput } from "./types";

type CreateInput = z.infer<typeof reviewCreateSchema>;
type AttemptInput = z.infer<typeof reviewAttemptSchema>;

function visibleDecks(state: WorkspaceState): ReviewDeck[] {
  return (activeWorkspace(state).reviewDecks ?? []).map((deck) => {
    const paper = paperById(deck.paperId, state);
    const note = state.notes.find((entry) => entry.id === deck.noteId);
    const stale =
      paper.contentRevision !== deck.contentRevision ||
      (!!deck.noteId && (!note || note.version !== deck.noteVersion)) ||
      deck.questions.some((question) =>
        question.sources.some((source) =>
          source.paperId && source.contentRevision
            ? state.papers.find((entry) => entry.id === source.paperId)
                ?.contentRevision !== source.contentRevision
            : false,
        ),
      );
    return { ...deck, stale };
  });
}

export function listReviewDecks(
  paperId?: string,
  noteId?: string,
): ReviewDeck[] {
  const state = readWorkspace();
  if (paperId) paperById(safeId(paperId), state);
  if (noteId) safeId(noteId);
  return visibleDecks(state)
    .filter(
      (deck) =>
        (!paperId || deck.paperId === paperId) &&
        (!noteId || deck.noteId === noteId),
    )
    .sort((a, b) => b.updatedAt.localeCompare(a.updatedAt));
}

function getDeck(state: WorkspaceState, id: string): ReviewDeck {
  safeId(id);
  const deck = state.reviewDecks?.find((entry) => entry.id === id);
  if (!deck) throw new ResearchError("复习题组不存在", 404);
  if (!visibleDecks(state).some((entry) => entry.id === id))
    throw new ResearchError("关联资料已移入回收站，请恢复后再复习", 410);
  return deck;
}

export function getReviewDeck(id: string): ReviewDeck {
  const state = readWorkspace();
  getDeck(state, id);
  return visibleDecks(state).find((entry) => entry.id === id)!;
}

function getQuestion(deck: ReviewDeck, id: string): ReviewQuestion {
  safeId(id);
  const question = deck.questions.find((entry) => entry.id === id);
  if (!question) throw new ResearchError("题目不存在", 404);
  return question;
}

function checkedSources(
  sources: SourceRef[],
  state: WorkspaceState,
  paperId: string,
): SourceRef[] {
  const checked = validateSources(sources, state, paperId);
  for (const source of checked) {
    if (source.noteId) {
      const note = activeWorkspace(state).notes.find(
        (entry) => entry.id === source.noteId,
      );
      if (!note || note.paperId !== source.paperId)
        throw new ResearchError("题目来源笔记不匹配或暂不可用", 409);
    }
    if (source.annotationId) {
      const annotation = state.annotations.find(
        (entry) => entry.id === source.annotationId,
      );
      if (!annotation || annotation.paperId !== source.paperId)
        throw new ResearchError("题目来源批注不匹配或已移除", 409);
    }
  }
  const unique = new Map<string, SourceRef>();
  for (const source of checked) {
    const key = digest([
      source.paperId,
      source.page,
      source.noteId,
      source.annotationId,
      source.url,
    ]);
    if (!unique.has(key) || (source.quote && !unique.get(key)?.quote))
      unique.set(key, source);
  }
  return [...unique.values()];
}

function existingAction(
  state: WorkspaceState,
  actionId: string,
  kind: string,
  fingerprint: string,
): ReviewDeck | undefined {
  const action = state.actions[actionId];
  if (!action) return;
  if (action.kind !== kind || action.digest !== fingerprint)
    throw new ResearchError("此提交编号已用于其他内容", 409);
  return getDeck(state, action.id);
}

export async function createReviewDeck(
  input: CreateInput,
): Promise<ReviewDeck> {
  // Reading local completed records does not contact the model provider.
  const run = input.runId
    ? (await getResearchHistory(undefined, false)).find(
        (entry) => entry.id === input.runId,
      )
    : undefined;
  const fingerprint = digest({ ...input, actionId: undefined });
  return mutateWorkspace((state) => {
    const duplicate = existingAction(
      state,
      input.actionId,
      "review-create",
      fingerprint,
    );
    if (duplicate) return duplicate;
    const paper = paperById(input.paperId, state);
    const runSource = run?.learning?.source;
    const sourceNote = runSource?.kind === "note" ? runSource : undefined;
    if (sourceNote && input.noteId && sourceNote.noteId !== input.noteId)
      throw new ResearchError("题组关联的笔记与分析来源不一致", 409);
    const noteId = input.noteId ?? sourceNote?.noteId;
    const note = noteId
      ? activeWorkspace(state).notes.find((entry) => entry.id === noteId)
      : undefined;
    if (noteId && (!note || note.paperId !== paper.id))
      throw new ResearchError("来源笔记不存在或不属于这篇论文", 409);
    if (note && input.noteVersion !== undefined)
      expectedVersion(note.version, input.noteVersion);
    if (sourceNote && note?.version !== sourceNote.version)
      throw new ResearchError("来源笔记在出题后已修改，请重新生成自测题", 409);
    if (note) checkedSources(note.sources, state, paper.id);
    let questions: ReviewQuestionInput[] = input.questions;
    if (input.runId) {
      if (!run || run.paperId !== paper.id)
        throw new ResearchError("分析记录与论文不匹配", 409);
      if (run.status !== "completed")
        throw new ResearchError("请等待分析完成后再加入复习", 409);
      if (!run.contentRevision || run.contentRevision !== paper.contentRevision)
        throw new ResearchError(
          "分析依据的论文版本已变化，请重新生成自测题",
          409,
        );
      recordedRunPaperIds(run).forEach((id) => paperById(id, state));
      if (runSource?.kind === "annotations") {
        for (const annotationId of runSource.ids) {
          const annotation = state.annotations.find(
            (entry) => entry.id === annotationId && entry.paperId === paper.id,
          );
          if (
            !annotation ||
            (runSource.versions?.[annotationId] !== undefined &&
              annotation.version !== runSource.versions[annotationId])
          )
            throw new ResearchError(
              "来源批注在出题后已修改或删除，请重新生成自测题",
              409,
            );
        }
      }
      const parsed = parseReviewMarkdown(run.answer);
      questions = input.questions.map((question) => {
        const match = parsed.find(
          (candidate) =>
            candidate.question === question.question &&
            candidate.answer === question.answer,
        );
        if (!match)
          throw new ResearchError(
            "这条分析中没有匹配的自测题，请先生成问题与答案",
            409,
          );
        return {
          ...question,
          sources: [
            ...(question.sources ?? []),
            ...citedReviewPages(match.answer).map((page) => ({
              paperId: paper.id,
              page,
              contentRevision: paper.contentRevision,
              title: paper.title,
            })),
          ],
        };
      });
    }
    const now = new Date().toISOString();
    const deck: ReviewDeck = {
      id: randomUUID(),
      paperId: paper.id,
      noteId: note?.id,
      noteVersion: note?.version,
      runId: run?.id,
      title: input.title || paper.title + " · 自测复习",
      contentRevision: paper.contentRevision,
      questions: questions.map((question) => ({
        id: randomUUID(),
        question: question.question,
        answer: question.answer,
        sources: checkedSources(
          question.sources?.length
            ? question.sources
            : note?.sources.length
              ? note.sources
              : [{ paperId: paper.id, title: paper.title }],
          state,
          paper.id,
        ),
        response: "",
        attemptCount: 0,
        attempts: [],
        excluded: false,
      })),
      session: { onlyMissed: false },
      version: 1,
      createdAt: now,
      updatedAt: now,
    };
    deck.session.currentQuestionId = deck.questions[0].id;
    (state.reviewDecks ??= []).unshift(deck);
    state.actions[input.actionId] = {
      kind: "review-create",
      id: deck.id,
      digest: fingerprint,
    };
    return deck;
  });
}

function changed(deck: ReviewDeck): ReviewDeck {
  deck.version++;
  deck.updatedAt = new Date().toISOString();
  return deck;
}

export async function saveReviewAttempt(
  id: string,
  input: AttemptInput,
): Promise<ReviewDeck> {
  const fingerprint = digest({
    id,
    ...input,
    version: undefined,
    actionId: undefined,
  });
  return mutateWorkspace((state) => {
    const deck = getDeck(state, id);
    const duplicate = existingAction(
      state,
      input.actionId,
      "review-attempt",
      fingerprint,
    );
    if (duplicate) return duplicate;
    expectedVersion(deck.version, input.version);
    const question = getQuestion(deck, input.questionId);
    if (question.excluded) throw new ResearchError("这道题已移出本轮复习", 409);
    const now = new Date();
    if (input.response !== undefined) question.response = input.response;
    question.rating = input.rating;
    question.reviewedAt = now.toISOString();
    // A transparent, basic reminder interval, not an FSRS prediction.
    question.dueAt = new Date(
      now.getTime() +
        (input.rating === "again" ? 10 * 60_000 : 24 * 60 * 60_000),
    ).toISOString();
    question.attemptCount++;
    question.attempts = [
      ...question.attempts,
      {
        id: input.actionId,
        response: question.response,
        rating: input.rating,
        createdAt: now.toISOString(),
      },
    ].slice(-20);
    state.actions[input.actionId] = {
      kind: "review-attempt",
      id: deck.id,
      digest: fingerprint,
    };
    return changed(deck);
  });
}

export async function saveReviewResponse(
  id: string,
  input: z.infer<typeof reviewResponseSchema>,
): Promise<ReviewDeck> {
  return mutateWorkspace((state) => {
    const deck = getDeck(state, id);
    expectedVersion(deck.version, input.version);
    const question = getQuestion(deck, input.questionId);
    if (question.excluded) throw new ResearchError("这道题已移出本轮复习", 409);
    if (question.response === input.response) return deck;
    question.response = input.response;
    return changed(deck);
  });
}

export async function saveReviewSession(
  id: string,
  input: z.infer<typeof reviewSessionSchema>,
): Promise<ReviewDeck> {
  return mutateWorkspace((state) => {
    const deck = getDeck(state, id);
    expectedVersion(deck.version, input.version);
    if (input.currentQuestionId) {
      const question = getQuestion(deck, input.currentQuestionId);
      if (question.excluded)
        throw new ResearchError("这道题已移出本轮复习", 409);
    }
    if (input.currentQuestionId !== undefined)
      deck.session.currentQuestionId = input.currentQuestionId;
    if (input.onlyMissed !== undefined)
      deck.session.onlyMissed = input.onlyMissed;
    return changed(deck);
  });
}

export async function updateReviewQuestion(
  id: string,
  input: z.infer<typeof reviewQuestionSchema>,
): Promise<ReviewDeck> {
  return mutateWorkspace((state) => {
    const deck = getDeck(state, id);
    expectedVersion(deck.version, input.version);
    const question = getQuestion(deck, input.questionId);
    const contentChanged =
      (input.question !== undefined && input.question !== question.question) ||
      (input.answer !== undefined && input.answer !== question.answer);
    if (input.question !== undefined) question.question = input.question;
    if (input.answer !== undefined) question.answer = input.answer;
    if (input.sources !== undefined)
      question.sources = checkedSources(input.sources, state, deck.paperId);
    if (input.excluded !== undefined) question.excluded = input.excluded;
    if (contentChanged) {
      delete question.rating;
      delete question.reviewedAt;
      delete question.dueAt;
    }
    if (question.excluded && deck.session.currentQuestionId === question.id)
      deck.session.currentQuestionId =
        deck.questions.find(
          (item) =>
            !item.excluded &&
            (!deck.session.onlyMissed || item.rating !== "good"),
        )?.id ?? null;
    return changed(deck);
  });
}

import type { ReviewQuestionInput } from "./types";

/** Import explicit Q/A Markdown only; prose never silently becomes a quiz. */
export function parseReviewMarkdown(content: string): ReviewQuestionInput[] {
  const result: ReviewQuestionInput[] = [];
  let question = "";
  let answer: string[] = [];
  let fence = "";
  const flush = () => {
    const body = answer.join("\n").trim();
    if (question && /^答案\s*[：:]/.test(body)) {
      const cleaned = body.replace(/^答案\s*[：:]\s*/, "").trim();
      if (cleaned) result.push({ question, answer: cleaned });
    }
    question = "";
    answer = [];
  };
  for (const line of content.split(/\r?\n/)) {
    const marker = line.match(/^\s*(`{3,}|~{3,})/);
    if (marker) {
      if (!fence) fence = marker[1][0];
      else if (fence === marker[1][0]) fence = "";
      if (question) answer.push(line);
      continue;
    }
    const heading = !fence && line.match(/^###\s+问题\s*\d+\s*[：:]\s*(.+)$/);
    if (heading) {
      flush();
      question = heading[1].trim();
    } else if (!fence && /^#{1,3}\s+/.test(line)) flush();
    else if (question) answer.push(line);
  }
  flush();
  return result;
}

export function citedReviewPages(content: string): number[] {
  const pages = new Set<number>();
  // Explicit links already identify their source; never rebind their page label.
  const plain = content.replace(/\[[^\]]*\]\([^)]*\)/g, "");
  for (const match of plain.matchAll(/\[p\.\s*(\d+)(?:\s*[-–—]\s*(\d+))?\]/g)) {
    const first = Number(match[1]);
    const last = match[2] ? Number(match[2]) : first;
    if (first < 1 || last < first || last - first > 100) continue;
    for (let page = first; page <= last; page++) pages.add(page);
  }
  return [...pages].sort((a, b) => a - b);
}

import fs from "node:fs";
import path from "node:path";
import { createHash, randomUUID } from "node:crypto";
import { withFilesystemLock } from "../filesystem-lock";
import {
  companionDir,
  listPapers,
  pdfPath,
  writeMeta,
  type PaperMeta,
} from "../library/papers";
import { dataRoot, ensureDataDirs } from "../data-dir";
import {
  closeIndex,
  rebuildIndex,
  searchChunks,
  searchIndex,
} from "../library/index-db";
import { educationSeeds } from "./seed";
import { registerInitialPdfWrite } from "../library/pdf/file";
import type {
  KnowledgeEntry,
  ResearchAnnotation,
  ResearchContext,
  ResearchGraph,
  ResearchNote,
  ResearchPage,
  ResearchPaper,
  ResearchSettings,
  SearchResult,
  SourceRef,
} from "./types";

export class ResearchError extends Error {
  constructor(
    message: string,
    public status = 400,
  ) {
    super(message);
  }
}
export interface PendingAnnotation {
  annotation: ResearchAnnotation;
  expectedEtag: string;
}
export interface WorkspaceState {
  schemaVersion: 1;
  version: number;
  papers: ResearchPaper[];
  notes: ResearchNote[];
  noteHistory: Record<string, ResearchNote[]>;
  knowledge: KnowledgeEntry[];
  annotations: ResearchAnnotation[];
  graph: ResearchGraph;
  actions: Record<string, { kind: string; id: string; digest: string }>;
  pendingAnnotations: PendingAnnotation[];
  plannerTasks?: import("./planner/types").PlannerTask[];
  reviewDecks?: import("./review/types").ReviewDeck[];
  settings: ResearchSettings;
}
export function getResearchDataDir(): string {
  return path.resolve(
    process.env.RESEARCH_DATA_DIR ||
      path.join(process.cwd(), "data", "research"),
  );
}
export function atomicWrite(
  filename: string,
  contents: string | Uint8Array,
): void {
  fs.mkdirSync(path.dirname(filename), { recursive: true });
  const tmp = `${filename}.${randomUUID()}.tmp`;
  const fd = fs.openSync(tmp, "wx", 0o600);
  try {
    fs.writeFileSync(fd, contents);
    fs.fsyncSync(fd);
  } finally {
    fs.closeSync(fd);
  }
  try {
    fs.renameSync(tmp, filename);
  } catch (error) {
    fs.rmSync(tmp, { force: true });
    throw error;
  }
}
export function digest(value: unknown): string {
  return createHash("sha256")
    .update(
      typeof value === "string" || value instanceof Uint8Array
        ? value
        : JSON.stringify(value),
    )
    .digest("hex");
}
export function safeId(id: string): string {
  if (!/^[a-zA-Z0-9_-]{1,100}$/.test(id))
    throw new ResearchError("无效的记录 ID");
  return id;
}
function stateFile() {
  return path.join(getResearchDataDir(), "workspace.json");
}
let indexedRoot = "";
let indexedSignature = "";
/** Rebuildable Papernook FTS5 index; JSON/PDF files remain authoritative. No model calls. */
export function ensureResearchIndex(force = false): boolean {
  const root = dataRoot();
  const file = path.join(root, "index.db");
  const signature = digest(
    readWorkspace().papers.map((p) => [
      p.id,
      p.title,
      p.authors,
      p.year,
      p.tags,
      p.contentRevision,
    ]),
  );
  try {
    if (root !== indexedRoot || !fs.existsSync(file)) {
      closeIndex();
      indexedSignature = "";
    }
    if (
      force ||
      root !== indexedRoot ||
      indexedSignature !== signature ||
      !fs.existsSync(file)
    ) {
      rebuildIndex();
      indexedRoot = root;
      indexedSignature = signature;
    }
    return true;
  } catch {
    return false;
  }
}
function initialState(): WorkspaceState {
  const now = new Date().toISOString();
  return {
    schemaVersion: 1,
    version: 1,
    papers: [],
    notes: [],
    noteHistory: {},
    knowledge: educationSeeds(now),
    annotations: [],
    graph: { nodes: [], edges: [], version: 1 },
    actions: {},
    pendingAnnotations: [],
    settings: {
      productName: "教研阅记",
      model: "未配置",
      provider: "PaperFlow · 自备接口",
      theme: "light",
      defaultTopic: "教育研究",
      dataLocation: getResearchDataDir(),
      version: 1,
    },
  };
}
export function readWorkspace(): WorkspaceState {
  const file = stateFile();
  if (!fs.existsSync(file)) {
    fs.mkdirSync(path.dirname(file), { recursive: true });
    // Exclusive creation prevents simultaneous initial requests replacing an established workspace.
    try {
      fs.writeFileSync(file, JSON.stringify(initialState(), null, 2), {
        flag: "wx",
        mode: 0o600,
      });
    } catch (error) {
      if (!(
        error instanceof Error &&
        "code" in error &&
        error.code === "EEXIST"
      ))
        throw error;
    }
  }
  let state: WorkspaceState;
  try {
    state = JSON.parse(fs.readFileSync(file, "utf8")) as WorkspaceState;
  } catch {
    throw new ResearchError(
      "工作区记录无法读取。原文件已保留，请从备份恢复，系统不会清空数据。",
      500,
    );
  }
  if (
    state.schemaVersion !== 1 ||
    !Array.isArray(state.papers) ||
    !Array.isArray(state.notes)
  )
    throw new ResearchError("工作区数据格式不受支持，原数据已保留。", 500);
  return state;
}
export async function mutateWorkspace<T>(
  operation: (state: WorkspaceState) => T | Promise<T>,
): Promise<T> {
  return withFilesystemLock(
    "research-workspace",
    getResearchDataDir(),
    30000,
    async () => {
      const state = readWorkspace();
      const result = await operation(state);
      state.version++;
      atomicWrite(stateFile(), JSON.stringify(state, null, 2));
      return result;
    },
  );
}
export function paperById(id: string, state = readWorkspace()): ResearchPaper {
  safeId(id);
  const paper = state.papers.find((p) => p.id === id);
  if (!paper) throw new ResearchError("未找到论文", 404);
  if (paper.trashedAt)
    throw new ResearchError("论文已移入回收站，请先恢复后再打开或编辑", 410);
  return paper;
}
/** A read projection only: never persist it in place of the full workspace. */
export function activeWorkspace(state = readWorkspace()): WorkspaceState {
  const ids = new Set(
    state.papers.filter((p) => !p.trashedAt).map((p) => p.id),
  );
  const visibleSources = (sources: SourceRef[]) =>
    sources.every((s) => !s.paperId || ids.has(s.paperId));
  const notes = state.notes.filter(
    (n) => ids.has(n.paperId) && visibleSources(n.sources),
  );
  const noteIds = new Set(notes.map((n) => n.id));
  const knowledge = state.knowledge.filter((k) => visibleSources(k.sources));
  const knowledgeIds = new Set(knowledge.map((k) => k.id));
  let nodes = state.graph.nodes.filter(
    (n) =>
      (!n.paperId || ids.has(n.paperId)) &&
      (!n.noteId || noteIds.has(n.noteId)) &&
      (!n.knowledgeId || knowledgeIds.has(n.knowledgeId)),
  );
  const nodeIds = new Set(nodes.map((n) => n.id));
  const edges = state.graph.edges.filter(
    (e) =>
      nodeIds.has(e.source) &&
      nodeIds.has(e.target) &&
      visibleSources(e.evidence),
  );
  const connected = new Set(edges.flatMap((e) => [e.source, e.target]));
  const wasConnected = new Set(
    state.graph.edges.flatMap((e) => [e.source, e.target]),
  );
  nodes = nodes.filter(
    (n) =>
      n.kind !== "concept" ||
      n.knowledgeId ||
      !wasConnected.has(n.id) ||
      connected.has(n.id),
  );
  return {
    ...state,
    papers: state.papers.filter((p) => ids.has(p.id)),
    notes,
    knowledge,
    annotations: state.annotations.filter((a) => ids.has(a.paperId)),
    pendingAnnotations: state.pendingAnnotations.filter((a) =>
      ids.has(a.annotation.paperId),
    ),
    plannerTasks: state.plannerTasks?.filter(
      (t) => !t.paperId || ids.has(t.paperId),
    ),
    reviewDecks: state.reviewDecks?.filter(
      (deck) =>
        ids.has(deck.paperId) &&
        (!deck.noteId || noteIds.has(deck.noteId)) &&
        deck.questions.every(
          (question) =>
            visibleSources(question.sources) &&
            question.sources.every(
              (source) => !source.noteId || noteIds.has(source.noteId),
            ),
        ),
    ),
    graph: { ...state.graph, nodes, edges },
  };
}
export function paperPdfPath(paper: ResearchPaper): string {
  return pdfPath(paper.library.topic, paper.library.slug);
}
export function paperPages(paper: ResearchPaper): ResearchPage[] {
  const file = path.join(
    companionDir(paper.library.topic, paper.library.slug),
    "research-pages.json",
  );
  try {
    return JSON.parse(fs.readFileSync(file, "utf8")) as ResearchPage[];
  } catch (error) {
    if (error instanceof Error && "code" in error && error.code === "ENOENT")
      return [];
    throw new ResearchError("论文逐页文本读取失败，原文件已保留", 500);
  }
}
export function writePaperPages(
  paper: ResearchPaper,
  pages: ResearchPage[],
): void {
  const dir = companionDir(paper.library.topic, paper.library.slug);
  atomicWrite(
    path.join(dir, "research-pages.json"),
    JSON.stringify(pages, null, 2),
  );
  atomicWrite(path.join(dir, "text.txt"), pages.map((p) => p.text).join("\f"));
}
/** Recover an import that finished its companion files but crashed before publishing the workspace. */
export async function recoverResearchImports(): Promise<void> {
  const state = readWorkspace();
  const known = new Set(state.papers.map((p) => p.id));
  const recovered: ResearchPaper[] = [];
  for (const native of listPapers()) {
    const file = path.join(native.companionDir, "research-identity.json");
    if (!fs.existsSync(file)) continue;
    try {
      const paper = JSON.parse(fs.readFileSync(file, "utf8")) as ResearchPaper;
      safeId(paper.id);
      if (
        known.has(paper.id) ||
        paper.library?.slug !== native.slug ||
        paper.library?.topic !== native.topic
      )
        continue;
      if (!Array.isArray(paperPages(paper))) continue;
      paper.pdfEtag = `"${digest(fs.readFileSync(native.pdfPath))}"`;
      recovered.push(paper);
      known.add(paper.id);
    } catch {
      /* An incomplete companion remains untouched for manual recovery. */
    }
  }
  if (recovered.length)
    await mutateWorkspace((current) => {
      for (const paper of recovered)
        if (!current.papers.some((p) => p.id === paper.id))
          current.papers.push(paper);
    });
}
function nativeMeta(paper: ResearchPaper): PaperMeta {
  return {
    title: paper.title,
    authors: paper.authors
      ? paper.authors
          .split(/[;,；]/)
          .map((v) => v.trim())
          .filter(Boolean)
      : [],
    year: /^\d{4}$/.test(paper.year) ? Number(paper.year) : null,
    venue: null,
    arxivId: null,
    bibtex: null,
    tags: paper.tags,
    related: [],
    sourceUrl: "",
    addedAt: paper.createdAt,
    addedBy: "local",
  };
}
export async function importPaper(input: {
  bytes: Uint8Array;
  filename: string;
  title?: string;
  topic?: string;
  tags?: string[];
  pages: ResearchPage[];
  textWarning?: string;
  contentRevision: string;
}): Promise<ResearchPaper> {
  const now = new Date().toISOString();
  const id = randomUUID();
  const originalHash = digest(input.bytes);
  const existing = readWorkspace().papers.find(
    (p) =>
      p.originalHash === originalHash ||
      (!p.originalHash && p.pdfEtag === `"${originalHash}"`),
  );
  if (existing) {
    if (existing.trashedAt)
      throw new ResearchError("这篇论文已在回收站中，请先恢复后再导入", 409);
    ensureResearchIndex();
    return existing;
  }
  const paper: ResearchPaper = {
    id,
    title: input.title?.trim() || input.filename.replace(/\.pdf$/i, ""),
    filename: path.basename(input.filename),
    authors: "",
    year: "",
    topic: input.topic?.trim() || "教育研究",
    tags: input.tags || [],
    readStatus: "unread",
    pageCount: input.pages.length,
    textStatus: input.pages.some((p) => p.text.trim()) ? "ready" : "empty",
    textWarning: input.textWarning,
    pdfEtag: `"${originalHash}"`,
    originalHash,
    contentRevision: input.contentRevision,
    version: 1,
    lastReadPage: 1,
    createdAt: now,
    updatedAt: now,
    library: { topic: "research", slug: `paper-${id}` },
  };
  const imported = await mutateWorkspace(async (state) => {
    const duplicate = state.papers.find(
      (p) =>
        p.originalHash === originalHash ||
        (!p.originalHash && p.pdfEtag === `"${originalHash}"`),
    );
    if (duplicate) {
      if (duplicate.trashedAt)
        throw new ResearchError("这篇论文已在回收站中，请先恢复后再导入", 409);
      return duplicate;
    }
    ensureDataDirs();
    const filename = paperPdfPath(paper);
    atomicWrite(filename, input.bytes);
    writeMeta(paper.library.topic, paper.library.slug, nativeMeta(paper));
    writePaperPages(paper, input.pages);
    // A companion identity file allows recovering imports even if the index was lost.
    atomicWrite(
      path.join(
        companionDir(paper.library.topic, paper.library.slug),
        "research-identity.json",
      ),
      JSON.stringify(paper, null, 2),
    );
    await registerInitialPdfWrite(
      paper.library.topic,
      paper.library.slug,
      paper.pdfEtag,
    );
    state.papers.unshift(paper);
    return paper;
  });
  ensureResearchIndex(true);
  return imported;
}
export function expectedVersion(current: number, supplied?: number): void {
  if (supplied === undefined)
    throw new ResearchError("保存需要当前版本，请刷新后重试", 428);
  if (supplied !== current)
    throw new ResearchError(
      "记录已被修改。请刷新后核对，系统未覆盖新内容。",
      409,
    );
}
export async function updatePaper(
  id: string,
  input: Partial<
    Pick<
      ResearchPaper,
      | "title"
      | "authors"
      | "year"
      | "topic"
      | "tags"
      | "readStatus"
      | "lastReadPage"
    >
  > & { version?: number },
): Promise<ResearchPaper> {
  const updated = await mutateWorkspace((state) => {
    const paper = paperById(id, state);
    expectedVersion(paper.version, input.version);
    const changes = { ...input };
    delete changes.version;
    Object.assign(paper, changes, {
      version: paper.version + 1,
      updatedAt: new Date().toISOString(),
    });
    if (paper.lastReadPage > paper.pageCount && paper.pageCount > 0)
      paper.lastReadPage = paper.pageCount;
    writeMeta(paper.library.topic, paper.library.slug, nativeMeta(paper));
    return paper;
  });
  ensureResearchIndex(true);
  return updated;
}
export async function synchronizePdf(
  id: string,
  etag: string,
): Promise<ResearchPaper> {
  return mutateWorkspace((state) => {
    const paper = paperById(id, state);
    if (paper.pdfEtag !== etag)
      Object.assign(paper, {
        pdfEtag: etag,
        version: paper.version + 1,
        updatedAt: new Date().toISOString(),
      });
    return paper;
  });
}
export function validateSources(
  sources: SourceRef[],
  state: WorkspaceState,
  fallbackPaper?: string,
): SourceRef[] {
  return sources.map((source) => {
    const paperId = source.paperId || fallbackPaper;
    if (!paperId) return source;
    const paper = paperById(paperId, state);
    if (source.page && (source.page < 1 || source.page > paper.pageCount))
      throw new ResearchError("来源页码超出论文范围");
    if (
      source.contentRevision &&
      source.contentRevision !== paper.contentRevision
    )
      throw new ResearchError("来源对应旧版论文，请重新选择原文", 409);
    if (source.quote && source.page) {
      const text =
        paperPages(paper).find((p) => p.page === source.page)?.text || "";
      const normalize = (v: string) =>
        v.normalize("NFKC").replace(/\s+/g, "").toLowerCase();
      if (text && !normalize(text).includes(normalize(source.quote)))
        throw new ResearchError("引用文字未在指定页找到，请核对原文");
    }
    return { ...source, paperId, contentRevision: paper.contentRevision };
  });
}
type NoteInput = Partial<ResearchNote> & {
  paperId: string;
  title: string;
  body?: string;
  content?: string;
  actionId?: string;
};
export async function createNote(input: NoteInput): Promise<ResearchNote> {
  return mutateWorkspace((state) => {
    paperById(input.paperId, state);
    const content = input.body ?? input.content ?? "";
    const fingerprint = digest({ ...input, actionId: undefined });
    if (input.actionId && state.actions[input.actionId]) {
      const action = state.actions[input.actionId];
      if (action.digest !== fingerprint)
        throw new ResearchError("此动作 ID 已用于不同内容", 409);
      const existing = state.notes.find((n) => n.id === action.id);
      if (existing) return existing;
    }
    const now = new Date().toISOString();
    const confirmed = input.confirmed ?? input.status === "confirmed";
    const note: ResearchNote = {
      id: randomUUID(),
      paperId: input.paperId,
      title: input.title,
      body: content,
      content,
      kind: input.kind || "reading",
      status: confirmed ? "confirmed" : "draft",
      confirmed,
      sources: validateSources(input.sources || [], state, input.paperId),
      version: 1,
      createdAt: now,
      updatedAt: now,
      runId: input.runId,
    };
    state.notes.unshift(note);
    state.noteHistory[note.id] = [];
    if (input.actionId)
      state.actions[input.actionId] = {
        kind: "note",
        id: note.id,
        digest: fingerprint,
      };
    return note;
  });
}
export async function updateNote(
  id: string,
  input: Partial<ResearchNote> & { version?: number },
): Promise<ResearchNote> {
  safeId(id);
  return mutateWorkspace((state) => {
    const note = state.notes.find((n) => n.id === id);
    if (!note) throw new ResearchError("未找到笔记", 404);
    paperById(note.paperId, state);
    expectedVersion(note.version, input.version);
    (state.noteHistory[id] ??= []).push(structuredClone(note));
    const confirmed =
      input.confirmed ??
      (input.status ? input.status === "confirmed" : note.confirmed);
    const content = input.body ?? input.content ?? note.body;
    Object.assign(note, {
      ...input,
      id: note.id,
      paperId: note.paperId,
      body: content,
      content,
      confirmed,
      status: confirmed ? "confirmed" : "draft",
      sources: validateSources(
        input.sources || note.sources,
        state,
        note.paperId,
      ),
      version: note.version + 1,
      updatedAt: new Date().toISOString(),
    });
    return note;
  });
}
export async function saveKnowledge(
  input: Partial<KnowledgeEntry> & { title: string },
  id?: string,
): Promise<KnowledgeEntry> {
  return mutateWorkspace((state) => {
    const existing = id ? state.knowledge.find((k) => k.id === id) : undefined;
    if (id && !existing) throw new ResearchError("未找到概念", 404);
    if (existing) expectedVersion(existing.version, input.version);
    const now = new Date().toISOString();
    const body = input.body ?? input.definition ?? existing?.body ?? "";
    const sources = validateSources(
      input.sources ?? existing?.sources ?? [],
      state,
    );
    const entry: KnowledgeEntry = {
      id: existing?.id || randomUUID(),
      title: input.title,
      aliases: input.aliases ?? existing?.aliases ?? [],
      body,
      definition: body,
      category: input.category ?? existing?.category ?? "教育学概念",
      sources,
      source:
        input.source ||
        sources
          .map((s) => s.citation || s.title || s.url)
          .filter(Boolean)
          .join("\n"),
      origin: existing?.origin || "user",
      version: (existing?.version || 0) + 1,
      createdAt: existing?.createdAt || now,
      updatedAt: now,
    };
    if (existing) state.knowledge[state.knowledge.indexOf(existing)] = entry;
    else state.knowledge.push(entry);
    return entry;
  });
}
export function researchContext(
  paperId: string,
  question?: string,
  sourcePaperIds?: string[],
): ResearchContext {
  const full = readWorkspace();
  const paper = paperById(paperId, full);
  const state = activeWorkspace(full);
  const related: NonNullable<ResearchContext["related"]> = [];
  if (question || sourcePaperIds) {
    const matches = question
      ? searchResearch(question, "personal").filter(
          (r) => r.paperId && r.paperId !== paperId,
        )
      : [];
    const ids = sourcePaperIds
      ? [...new Set(sourcePaperIds)].filter((id) => id !== paperId)
      : [
          ...new Set(
            matches.map((r) => r.paperId).filter((id): id is string => !!id),
          ),
        ].slice(0, 3);
    if (ids.length > 3) throw new ResearchError("一次最多选择4篇论文");
    for (const id of ids) {
      const other = paperById(id, state);
      const hits = matches.filter((r) => r.paperId === id);
      const pages = new Set(
        hits
          .map((h) => h.page || h.source?.page)
          .filter((p): p is number => !!p),
      );
      const allPages = paperPages(other);
      const matchedPages = allPages.filter((p) => pages.has(p.page));
      related.push({
        paper: other,
        pages: (matchedPages.length
          ? matchedPages
          : sourcePaperIds
            ? allPages
            : []
        ).slice(0, 4),
        notes: state.notes
          .filter(
            (n) =>
              n.paperId === id &&
              n.confirmed &&
              (sourcePaperIds || hits.some((h) => h.id === n.id)),
          )
          .slice(0, 5),
      });
    }
  }
  return {
    paper,
    pages: paperPages(paper),
    notes: state.notes.filter((n) => n.paperId === paperId && n.confirmed),
    knowledge: state.knowledge,
    related,
  };
}
function searchScore(text: string, query: string): number {
  const lower = text.toLowerCase().normalize("NFKC");
  const q = query.toLowerCase().normalize("NFKC").trim();
  if (!q) return 1;
  if (lower.includes(q)) return 30 + q.length;
  const tokens = q.match(/[a-z0-9]+|[\u3400-\u9fff]{2,}/gi) || [];
  let score = 0;
  for (const t of tokens) {
    if (lower.includes(t)) score += Math.min(15, t.length);
    else if (/[\u3400-\u9fff]/.test(t)) {
      for (let i = 0; i < t.length - 1; i++)
        if (lower.includes(t.slice(i, i + 2))) score++;
    }
  }
  return score;
}
export function searchResearch(query: string, scope = "all"): SearchResult[] {
  const state = activeWorkspace();
  const results: SearchResult[] = [];
  const push = (
    item: Omit<SearchResult, "score" | "snippet">,
    text: string,
  ) => {
    const score = searchScore(`${item.title}\n${text}`, query);
    if (score > 0) {
      const at = Math.max(
        0,
        text.toLowerCase().indexOf(query.toLowerCase()) - 70,
      );
      results.push({ ...item, score, snippet: text.slice(at, at + 350) });
    }
  };
  if (scope !== "personal")
    for (const entry of state.knowledge)
      push(
        {
          id: entry.id,
          type: "knowledge",
          title: entry.title,
          source: entry.sources[0],
        },
        entry.body + " " + entry.aliases.join(" "),
      );
  if (scope !== "education") {
    if (ensureResearchIndex()) {
      try {
        const matched = searchIndex(query);
        matched.forEach((hit, rank) => {
          const paper = state.papers.find((p) => p.library.slug === hit.slug);
          if (!paper) return;
          results.push({
            id: paper.id,
            type: "paper",
            title: paper.title,
            paperId: paper.id,
            snippet: hit.summarySnippet || paper.tags.join(" "),
            score: 100 - rank,
          });
          const pages = paperPages(paper);
          for (const chunk of searchChunks(hit.slug, query, 6)) {
            let cursor = 0;
            for (const page of pages) {
              const end = cursor + page.text.length;
              if (
                chunk.start <= end &&
                chunk.start + chunk.body.length >= cursor
              )
                results.push({
                  id: `${paper.id}-${page.page}`,
                  type: "page",
                  title: paper.title,
                  paperId: paper.id,
                  page: page.page,
                  snippet: chunk.body.slice(0, 350),
                  score: 90 - rank,
                  source: {
                    paperId: paper.id,
                    page: page.page,
                    contentRevision: paper.contentRevision,
                  },
                });
              cursor = end + 1;
            }
          }
        });
      } catch {
        /* Chinese term segmentation can miss; the local literal/bigram search below is retained. */
      }
    }
    for (const p of state.papers) {
      push(
        { id: p.id, type: "paper", title: p.title, paperId: p.id },
        `${p.authors} ${p.topic} ${p.tags.join(" ")}`,
      );
      for (const page of paperPages(p))
        push(
          {
            id: `${p.id}-${page.page}`,
            type: "page",
            title: p.title,
            paperId: p.id,
            page: page.page,
            source: {
              paperId: p.id,
              page: page.page,
              contentRevision: p.contentRevision,
            },
          },
          page.text,
        );
    }
    for (const n of state.notes.filter((n) => n.confirmed))
      push(
        {
          id: n.id,
          type: "note",
          title: n.title,
          paperId: n.paperId,
          source: n.sources[0],
        },
        n.body,
      );
    for (const a of state.annotations)
      push(
        {
          id: a.id,
          type: "annotation",
          title: a.comment || a.quote,
          paperId: a.paperId,
          page: a.page,
          source: { paperId: a.paperId, page: a.page, quote: a.quote },
        },
        a.quote + " " + a.comment,
      );
  }
  const unique = new Map<string, SearchResult>();
  for (const result of results.sort((a, b) => b.score - a.score))
    if (!unique.has(result.id)) unique.set(result.id, result);
  return [...unique.values()].slice(0, 100);
}
export function exportMarkdown(paperId?: string): string {
  const full = readWorkspace();
  if (paperId) paperById(paperId, full);
  const state = activeWorkspace(full);
  const papers = paperId ? [paperById(paperId, state)] : state.papers;
  return (
    "# 教研阅记 · 研究笔记\n\n" +
    papers
      .map((p) => {
        const notes = state.notes.filter((n) => n.paperId === p.id);
        const annotations = state.annotations.filter((a) => a.paperId === p.id);
        return (
          `## ${p.title}\n\n主题：${p.topic}\n\n文档 ID：${p.id}\n\n` +
          annotations
            .map(
              (a) =>
                `> 第 ${a.page} 页：${a.quote.replace(/\n/g, "\n> ")}\n\n${a.comment}\n`,
            )
            .join("\n") +
          notes
            .map(
              (n) =>
                `### ${n.title}\n\n状态：${n.confirmed ? "已确认" : "草稿"} · 版本 ${n.version}\n\n${n.body}\n\n` +
                n.sources
                  .map(
                    (s) =>
                      `- 来源：${s.title || p.title}${s.page ? `，第 ${s.page} 页` : ""}${s.quote ? `\n  > ${s.quote}` : ""}${s.url ? ` (${s.url})` : ""}`,
                  )
                  .join("\n"),
            )
            .join("\n\n")
        );
      })
      .join("\n\n---\n\n")
  );
}

import { randomUUID } from "node:crypto";
import {
  PDFArray,
  PDFDict,
  PDFDocument,
  PDFHexString,
  PDFName,
  PDFNumber,
  PDFRef,
  PDFString,
} from "pdf-lib";
import { z } from "zod";
import { SharingError, labelSchema } from "./protocol/values";

const point = z.number().finite().min(-100_000).max(100_000);
const annotationSchema = z.object({
  type: z.enum([
    "Text",
    "FreeText",
    "Highlight",
    "Underline",
    "StrikeOut",
    "Squiggly",
    "Ink",
  ]),
  rect: z.tuple([point, point, point, point]),
  text: z.string().max(10_000),
  color: z.array(z.number().finite().min(0).max(1)).length(3),
  opacity: z.number().finite().min(0).max(1),
  width: z.number().finite().min(0.1).max(30),
  size: z.number().finite().min(1).max(200),
  quads: z.array(point).max(16_000),
  ink: z.array(z.array(point).min(4).max(20_000)).max(200),
});
type Annotation = z.infer<typeof annotationSchema>;
interface Entry {
  key: string;
  page: number;
  dict: PDFDict;
  ref: PDFRef;
}

function textValue(dict: PDFDict, key: string): string {
  return (
    dict.lookupMaybe(PDFName.of(key), PDFString, PDFHexString)?.decodeText() ??
    ""
  );
}
function numbers(dict: PDFDict, key: string): number[] {
  const values = dict.lookupMaybe(PDFName.of(key), PDFArray);
  return values
    ? values.asArray().map((v) => {
        if (!(v instanceof PDFNumber))
          throw new SharingError("Invalid annotation coordinates.");
        return v.asNumber();
      })
    : [];
}
function number(dict: PDFDict, key: string, fallback: number): number {
  return dict.lookupMaybe(PDFName.of(key), PDFNumber)?.asNumber() ?? fallback;
}
function entries(document: PDFDocument): Entry[] {
  const result: Entry[] = [];
  const used = new Set<string>();
  for (const [page, value] of document.getPages().entries()) {
    const annotations = value.node.Annots();
    for (let i = 0; annotations && i < annotations.size(); i++) {
      const ref = annotations.get(i);
      if (!(ref instanceof PDFRef))
        throw new SharingError("Annotations must have stable references.");
      const dict = annotations.lookup(i, PDFDict);
      const name = textValue(dict, "NM");
      const key = name ? `name:${name}` : `ref:${ref.toString()}`;
      if (used.has(key))
        throw new SharingError("Duplicate annotation identity.");
      used.add(key);
      result.push({ key, page, dict, ref });
      if (result.length > 5000)
        throw new SharingError("Too many annotations.", 413);
    }
  }
  return result;
}

function annotationValue(dict: PDFDict): Annotation {
  const type = dict.lookupMaybe(PDFName.of("Subtype"), PDFName)?.decodeText();
  const color = numbers(dict, "C");
  const border = dict.lookupMaybe(PDFName.of("BS"), PDFDict);
  const strokes = dict.lookupMaybe(PDFName.of("InkList"), PDFArray);
  const ink =
    strokes?.asArray().map((stroke) => {
      if (!(stroke instanceof PDFArray))
        throw new SharingError("Invalid ink stroke.");
      return stroke.asArray().map((v) => {
        if (!(v instanceof PDFNumber))
          throw new SharingError("Invalid ink point.");
        return v.asNumber();
      });
    }) ?? [];
  const da = textValue(dict, "DA");
  const rgb = /([\d.]+)\s+([\d.]+)\s+([\d.]+)\s+rg/.exec(da);
  const gray = /([\d.]+)\s+g(?:\s|$)/.exec(da);
  const textColor = rgb
    ? rgb.slice(1).map(Number)
    : gray
      ? [Number(gray[1]), Number(gray[1]), Number(gray[1])]
      : null;
  const size = /([\d.]+)\s+Tf/.exec(da)?.[1];
  const value = annotationSchema.safeParse({
    type,
    rect: numbers(dict, "Rect"),
    text: textValue(dict, "Contents"),
    color:
      type === "FreeText" && textColor
        ? textColor
        : color.length === 0
          ? type === "Text" || type === "Highlight"
            ? [1, 0.85, 0]
            : [0, 0, 0]
          : color.length === 1
            ? [color[0], color[0], color[0]]
            : color,
    opacity: number(dict, "CA", 1),
    width: border ? number(border, "W", 1) : 1,
    size: size ? Number(size) : 12,
    quads: numbers(dict, "QuadPoints"),
    ink,
  });
  if (!value.success)
    throw new SharingError(
      "This annotation type or geometry cannot be shared safely.",
      422,
    );
  if (
    value.data.quads.length % 8 ||
    value.data.ink.some((stroke) => stroke.length % 2)
  )
    throw new SharingError("Invalid annotation geometry.", 422);
  return value.data;
}

/** Compare only inert annotation data. Remote dictionaries and streams never cross this boundary. */
function signature(entry: Entry): string {
  const dict = entry.dict;
  return JSON.stringify({
    page: entry.page,
    type: dict.get(PDFName.of("Subtype"))?.toString(),
    rect: numbers(dict, "Rect"),
    contents: textValue(dict, "Contents"),
    color: numbers(dict, "C"),
    opacity: number(dict, "CA", 1),
    quads: numbers(dict, "QuadPoints"),
    ink: dict.get(PDFName.of("InkList"))?.toString(),
    da: textValue(dict, "DA"),
    border: dict.get(PDFName.of("BS"))?.toString(),
  });
}

function assertBounds(
  annotation: Annotation,
  document: PDFDocument,
  pageIndex: number,
): void {
  const box = document.getPage(pageIndex).getCropBox();
  const inside = (x: number, y: number) =>
    x >= box.x - 1 &&
    y >= box.y - 1 &&
    x <= box.x + box.width + 1 &&
    y <= box.y + box.height + 1;
  const [x1, y1, x2, y2] = annotation.rect;
  if (x2 <= x1 || y2 <= y1 || !inside(x1, y1) || !inside(x2, y2))
    throw new SharingError("Annotation is outside the page.", 422);
  const coordinates = [...annotation.quads, ...annotation.ink.flat()];
  for (let i = 0; i < coordinates.length; i += 2)
    if (!inside(coordinates[i], coordinates[i + 1]))
      throw new SharingError("Annotation points are outside the page.", 422);
  if (
    (annotation.type === "Ink" && annotation.ink.length === 0) ||
    (["Highlight", "Underline", "StrikeOut", "Squiggly"].includes(
      annotation.type,
    ) &&
      annotation.quads.length === 0)
  )
    throw new SharingError("Annotation geometry is missing.", 422);
}

/** Apply a proposed editor save as primitive operations on the trusted original PDF. */
export async function applyCollaborativeAnnotations(
  current: Uint8Array,
  proposed: Uint8Array,
  actor: { id: string; name: string },
  owner = false,
): Promise<Uint8Array> {
  labelSchema.parse(actor.name);
  let trusted: PDFDocument;
  let remote: PDFDocument;
  try {
    trusted = await PDFDocument.load(current, {
      updateMetadata: false,
      throwOnInvalidObject: true,
    });
    remote = await PDFDocument.load(proposed, {
      updateMetadata: false,
      throwOnInvalidObject: true,
    });
  } catch {
    throw new SharingError("Cannot share an encrypted or invalid PDF.", 422);
  }
  if (remote.context.enumerateIndirectObjects().length > 100_000)
    throw new SharingError("The PDF is too complex.", 413);
  if (trusted.getPageCount() !== remote.getPageCount())
    throw new SharingError("Collaboration can change annotations only.", 422);
  for (let i = 0; i < trusted.getPageCount(); i++) {
    if (
      JSON.stringify(trusted.getPage(i).getCropBox()) !==
        JSON.stringify(remote.getPage(i).getCropBox()) ||
      trusted.getPage(i).getRotation().angle !==
        remote.getPage(i).getRotation().angle
    )
      throw new SharingError(
        "Collaboration cannot resize or rotate pages.",
        422,
      );
  }
  // Rewriting signed PDFs would invalidate signatures. Never do that silently.
  for (const [, object] of trusted.context.enumerateIndirectObjects())
    if (
      object instanceof PDFDict &&
      (object.has(PDFName.of("ByteRange")) ||
        object.get(PDFName.of("Type")) === PDFName.of("Sig"))
    )
      throw new SharingError(
        "Signed PDFs cannot be collaboratively annotated.",
        422,
      );
  const existing = entries(trusted);
  const next = entries(remote);
  const byKey = new Map(next.map((entry) => [entry.key, entry]));
  const mutations: { before?: Entry; after?: Entry; value?: Annotation }[] = [];
  for (const before of existing) {
    const after = byKey.get(before.key);
    byKey.delete(before.key);
    if (after && signature(before) === signature(after)) continue;
    if (!owner && textValue(before.dict, "PapernookAuthor") !== actor.id)
      throw new SharingError(
        "Only the author can change this annotation.",
        403,
      );
    if (after) {
      const value = annotationValue(after.dict);
      assertBounds(value, trusted, after.page);
      mutations.push({ before, after, value });
    } else mutations.push({ before });
  }
  for (const after of byKey.values()) {
    const value = annotationValue(after.dict);
    assertBounds(value, trusted, after.page);
    mutations.push({ after, value });
  }
  if (mutations.length > 1000)
    throw new SharingError("Too many annotation changes in one save.", 413);
  if (mutations.length === 0) return current;
  for (const mutation of mutations) {
    if (mutation.before)
      trusted
        .getPage(mutation.before.page)
        .node.removeAnnot(mutation.before.ref);
    if (!mutation.after || !mutation.value) continue;
    const value = mutation.value;
    const name = mutation.before
      ? textValue(mutation.before.dict, "NM") || `papernook-${randomUUID()}`
      : `papernook-${randomUUID()}`;
    const annotation = trusted.context.obj({
      Type: "Annot",
      Subtype: value.type,
      Rect: value.rect,
      F: 4,
      NM: PDFString.of(name),
      T: PDFHexString.fromText(actor.name),
      PapernookAuthor: PDFString.of(actor.id),
      Contents: PDFHexString.fromText(value.text),
      C: value.color,
      CA: value.opacity,
      BS: { W: value.width, S: "S" },
      ...(value.type === "Text" ? { Name: "Comment" } : {}),
      ...(value.type === "FreeText"
        ? {
            DA: PDFString.of(
              `/Helv ${value.size} Tf ${value.color.join(" ")} rg`,
            ),
            Q: 0,
          }
        : {}),
      ...(value.quads.length ? { QuadPoints: value.quads } : {}),
      ...(value.ink.length ? { InkList: value.ink } : {}),
    });
    trusted
      .getPage(mutation.after.page)
      .node.addAnnot(trusted.context.register(annotation));
  }
  return trusted.save();
}

import { z } from "zod";
import { withShareFiles, type PaperShare } from "../../library/shares";
import { readCanvasAsset } from "../../canvas/assets";
import {
  canvasAssetNameSchema,
  MAX_SHARED_ASSET_BYTES,
} from "../../canvas/media";
import { getPaper } from "../../library/papers";
import {
  exerciseMarkdownSchema,
  exerciseOperationSchema,
} from "../../library/exercises/schema";
import { authenticateParticipant, type Participant } from "../storage";
import { base64Schema, SharingError } from "../protocol/values";
import { artifactVersions, snapshotArtifacts } from "./snapshot";
import {
  readSourceCanvas,
  saveSourceCanvas,
  uploadSourceAsset,
  deleteSourceAsset,
  createSourceExercise,
  recoverSourceExercises,
} from "./source";

export const artifactOperations = [
  z.object({ action: z.literal("artifact-versions") }).strict(),
  z.object({ action: z.literal("artifacts") }).strict(),
  z.object({ action: z.literal("canvas") }).strict(),
  z
    .object({
      action: z.literal("save-canvas"),
      version: z.string().regex(/^"(?:empty|[a-zA-Z0-9_-]{43})"$/),
      document: z.unknown(),
    })
    .strict(),
  z
    .object({ action: z.literal("canvas-asset"), name: canvasAssetNameSchema })
    .strict(),
  z
    .object({
      action: z.literal("upload-canvas-asset"),
      bytes: base64Schema,
      mime: z.string().max(100),
    })
    .strict(),
  z
    .object({
      action: z.literal("delete-canvas-asset"),
      name: canvasAssetNameSchema,
    })
    .strict(),
  z
    .object({
      action: z.literal("create-exercise"),
      markdown: exerciseMarkdownSchema,
      operationId: exerciseOperationSchema,
    })
    .strict(),
] as const;
const operationSchema = z.discriminatedUnion("action", artifactOperations);

/** Called under collaboration admission; every final filesystem commit rechecks authority. */
export async function exchangeArtifact(
  share: PaperShare,
  token: string,
  participant: Participant,
  value: unknown,
): Promise<unknown> {
  const body = operationSchema.parse(value);
  const { topic, slug } = share;
  const actor = { id: `participant:${participant.id}`, name: participant.name };
  const commit = (operation: () => void) =>
    withShareFiles(share, () => {
      authenticateParticipant(share, token);
      operation();
    });
  if (body.action === "artifact-versions") {
    await recoverSourceExercises(topic, slug, commit);
    return artifactVersions(topic, slug);
  }
  if (body.action === "artifacts") {
    await recoverSourceExercises(topic, slug, commit);
    const versions = await artifactVersions(topic, slug);
    const artifacts = await snapshotArtifacts(topic, slug);
    const after = await artifactVersions(topic, slug);
    if (JSON.stringify(versions) !== JSON.stringify(after))
      throw new SharingError(
        "The shared artifacts changed while reading. Try again.",
        409,
      );
    return { versions, artifacts };
  }
  if (body.action === "canvas") return readSourceCanvas(topic, slug);
  if (body.action === "save-canvas")
    return saveSourceCanvas(
      topic,
      slug,
      body.version,
      body.document,
      actor,
      commit,
    );
  if (body.action === "create-exercise")
    return createSourceExercise(
      topic,
      slug,
      body.markdown,
      body.operationId,
      actor,
      commit,
    );
  if (body.action === "upload-canvas-asset") {
    if (body.bytes.length > Math.ceil(MAX_SHARED_ASSET_BYTES / 3) * 4)
      throw new SharingError(
        "Shared canvas uploads support at most 8 MB.",
        413,
      );
    return {
      name: uploadSourceAsset(
        topic,
        slug,
        Buffer.from(body.bytes, "base64"),
        body.mime,
        actor,
        commit,
      ),
    };
  }
  if (body.action === "delete-canvas-asset") {
    deleteSourceAsset(topic, slug, body.name, actor, commit);
    return { deleted: true };
  }
  const paper = getPaper(topic, slug);
  if (!paper) throw new SharingError("Unknown paper.", 404);
  const asset = readCanvasAsset(paper.companionDir, body.name, true);
  return {
    name: asset.name,
    mime: asset.mime,
    bytes: asset.bytes.toString("base64"),
  };
}

import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";
import { z } from "zod";
import { syncDirectory } from "thesidedoor-core/storage";
import {
  getPaper,
  exercisesPdfPath,
  withPaperMutation,
} from "../../library/papers";
import { readCanvas } from "../../canvas/document";
import { readExerciseRecords } from "../../library/exercises";
import { readVersionedPdf, replacePdf, pdfEtag } from "../../library/pdf/file";
import {
  withProfileFiles,
  type ProfileCapability,
} from "../../auth/profile-capability";
import { PapernookIdentityStore } from "../../auth/identity-store";
import { dataRoot } from "../../data-dir";
import {
  saveConnection,
  assertCurrentConnection,
  writeJson,
  type Connection,
} from "../storage";
import { base64Schema, SharingError } from "../protocol/values";
import {
  artifactVersionsSchema,
  type ArtifactVersions,
  type ArtifactSnapshot,
} from "./schema";
import { artifactVersions, artifactFiles } from "./snapshot";
import { packageCanvas } from "./canvas";

const fileSchema = z
  .object({
    name: z
      .string()
      .regex(
        /^(?:canvas\.json|paper\.exercises\.pdf|exercises\/(?:state\.json|[a-z0-9][a-z0-9-]{0,79}\.md)|canvas-assets\/[a-f0-9]{64}\.(?:png|jpg|gif|webp|mov|mp4|webm))$/,
      ),
    before: z
      .string()
      .regex(/^"[a-f0-9]{64}"$/)
      .nullable(),
    bytes: base64Schema.nullable(),
  })
  .strict();
const journalSchema = z
  .object({
    tokenHash: z.string().regex(/^[a-f0-9]{64}$/),
    username: z.string(),
    generation: z.number().int().nonnegative(),
    source: artifactVersionsSchema,
    files: z.array(fileSchema).max(1200),
  })
  .strict();
type Journal = z.infer<typeof journalSchema>;

function hashFile(file: string): string | null {
  try {
    const stat = fs.lstatSync(file);
    if (!stat.isFile() || stat.size > 32 * 1024 * 1024)
      throw new SharingError(
        "A local shared artifact is invalid or too large.",
        409,
      );
    return pdfEtag(fs.readFileSync(file));
  } catch (error) {
    if (error instanceof Error && "code" in error && error.code === "ENOENT")
      return null;
    throw error;
  }
}
function targetFile(
  directory: string,
  topic: string,
  slug: string,
  name: string,
): string {
  return name === "paper.exercises.pdf"
    ? exercisesPdfPath(topic, slug)
    : path.join(directory, name);
}
function tokenHash(connection: Connection) {
  return crypto.createHash("sha256").update(connection.token).digest("hex");
}
function readJournal(file: string, connection: Connection): Journal | null {
  if (!fs.existsSync(file)) return null;
  const stat = fs.lstatSync(file);
  if (!stat.isFile() || stat.size > 100 * 1024 * 1024)
    throw new SharingError("Artifact recovery data is invalid.", 409);
  const journal = journalSchema.parse(
    JSON.parse(fs.readFileSync(file, "utf8")),
  );
  if (
    journal.tokenHash !== tokenHash(connection) ||
    journal.username !== connection.username ||
    journal.generation !== connection.generation
  )
    throw new SharingError(
      "Artifact recovery belongs to a different connection. Preserve it before reconnecting.",
      409,
    );
  if (
    new Set(journal.files.map((file) => file.name)).size !==
    journal.files.length
  )
    throw new SharingError("Artifact recovery contains duplicate paths.", 409);
  return journal;
}

/** A durable intent permits retry after interruption, while preserving unexpected local writes. */
async function applyJournal(
  topic: string,
  slug: string,
  capability: ProfileCapability,
  connection: Connection,
  journal: Journal,
  journalFile: string,
): Promise<void> {
  const paper = getPaper(topic, slug);
  if (!paper) throw new SharingError("Unknown paper.", 404);
  const filePath = (name: string) =>
    targetFile(paper.companionDir, topic, slug, name);
  const verify = () => {
    for (const file of journal.files) {
      const current = hashFile(filePath(file.name));
      const desired =
        file.bytes === null ? null : pdfEtag(Buffer.from(file.bytes, "base64"));
      if (current !== file.before && current !== desired)
        throw new SharingError(
          "A local canvas, exercise or PDF changed outside collaboration. Preserve that copy before syncing.",
          409,
        );
    }
  };
  const pdfEntry = journal.files.find(
    (file) => file.name === "paper.exercises.pdf",
  );
  const currentPdf = await readVersionedPdf(topic, slug, "exercises");
  const next = { ...connection };
  const commit = (replace?: () => void) =>
    saveConnection(topic, slug, capability, next, false, () => {
      verify();
      writeJson(journalFile, journal);
      for (const entry of journal.files) {
        const file = filePath(entry.name);
        if (entry.name === "paper.exercises.pdf" && replace) {
          replace();
          continue;
        }
        const desired =
          entry.bytes === null
            ? null
            : pdfEtag(Buffer.from(entry.bytes, "base64"));
        if (hashFile(file) === desired) continue;
        if (entry.bytes === null) {
          fs.rmSync(file, { force: true });
          syncDirectory(path.dirname(file));
          continue;
        }
        fs.mkdirSync(path.dirname(file), { recursive: true, mode: 0o700 });
        const temp = `${file}.${crypto.randomUUID()}.tmp`;
        try {
          fs.writeFileSync(temp, Buffer.from(entry.bytes, "base64"), {
            flag: "wx",
            mode: 0o600,
            flush: true,
          });
          fs.renameSync(temp, file);
          syncDirectory(path.dirname(file));
        } finally {
          fs.rmSync(temp, { force: true });
        }
      }
      next.artifacts = {
        source: journal.source,
        mirror: {
          canvas: readCanvas(topic, slug).version,
          exercises: readExerciseRecords(topic, slug).revision,
          exercisePdf: hashFile(exercisesPdfPath(topic, slug)),
        },
      };
    });
  verify();
  if (
    pdfEntry?.bytes &&
    (currentPdf?.etag ?? null) !==
      pdfEtag(Buffer.from(pdfEntry.bytes, "base64"))
  )
    await replacePdf(
      topic,
      slug,
      currentPdf?.etag ?? null,
      Buffer.from(pdfEntry.bytes, "base64"),
      commit,
      "exercises",
    );
  else commit();
  Object.assign(connection, next);
  withProfileFiles(new PapernookIdentityStore(dataRoot()), capability, () =>
    withPaperMutation(slug, () => {
      assertCurrentConnection(topic, slug, capability, connection);
      fs.rmSync(journalFile, { force: true });
      syncDirectory(path.dirname(journalFile));
    }),
  );
}

export async function installArtifacts(
  topic: string,
  slug: string,
  capability: ProfileCapability,
  connection: Connection,
  source: ArtifactVersions,
  artifacts: ArtifactSnapshot,
): Promise<void> {
  withProfileFiles(new PapernookIdentityStore(dataRoot()), capability, () =>
    assertCurrentConnection(topic, slug, capability, connection),
  );
  const paper = getPaper(topic, slug);
  if (!paper) throw new SharingError("Unknown paper.", 404);
  const directory = paper.companionDir;
  const journalFile = path.join(
    directory,
    "collaboration",
    "artifacts-pending.json",
  );
  const pending = readJournal(journalFile, connection);
  if (pending)
    await applyJournal(
      topic,
      slug,
      capability,
      connection,
      pending,
      journalFile,
    );
  const local = await artifactVersions(topic, slug);
  const baseline = connection.artifacts?.mirror;
  if (
    baseline
      ? JSON.stringify(local) !== JSON.stringify(baseline)
      : readCanvas(topic, slug).document !== null ||
        readExerciseRecords(topic, slug).records.length ||
        local.exercisePdf
  )
    throw new SharingError(
      "A local canvas or exercise changed outside collaboration. Preserve that copy before syncing.",
      409,
    );
  if (JSON.stringify(connection.artifacts?.source) === JSON.stringify(source))
    return;
  const desiredFiles = artifactFiles(artifacts, topic, slug);
  const oldCanvas = packageCanvas(
    readCanvas(topic, slug).document,
    directory,
    topic,
    slug,
  );
  const names = new Set([
    "canvas.json",
    "paper.exercises.pdf",
    "exercises/state.json",
    ...readExerciseRecords(topic, slug).records.map(
      (record) => `exercises/${record.name}`,
    ),
    ...Object.values(oldCanvas.sourceNames).map(
      (name) => `canvas-assets/${name}`,
    ),
    ...artifacts.exercises.map((record) => `exercises/${record.name}`),
    ...Object.keys(artifacts.assets).map((name) => `canvas-assets/${name}`),
  ]);
  const files = [...names].map((name) => ({
    name,
    before: hashFile(targetFile(directory, topic, slug, name)),
    bytes: desiredFiles.get(name)?.toString("base64") ?? null,
  }));
  const journal = journalSchema.parse({
    tokenHash: tokenHash(connection),
    username: capability.username,
    generation: capability.generation,
    source,
    files,
  });
  // Check the baseline again under the commit guard, before recording intent.
  const initialCanvas = local.canvas;
  const initialExercises = local.exercises;
  withProfileFiles(new PapernookIdentityStore(dataRoot()), capability, () =>
    withPaperMutation(slug, () => {
      assertCurrentConnection(topic, slug, capability, connection);
      if (
        readCanvas(topic, slug).version !== initialCanvas ||
        readExerciseRecords(topic, slug).revision !== initialExercises ||
        hashFile(exercisesPdfPath(topic, slug)) !== local.exercisePdf
      )
        throw new SharingError("Local artifacts changed while syncing.", 409);
      writeJson(journalFile, journal);
    }),
  );
  await applyJournal(topic, slug, capability, connection, journal, journalFile);
}

import crypto from "node:crypto";
import { getPaper } from "../../library/papers";
import { readCanvas, saveCanvas } from "../../canvas/document";
import {
  readCanvasAsset,
  storeCanvasAsset,
  removeCanvasAsset,
} from "../../canvas/assets";
import { attributeCanvas, validateSharedCanvas } from "../../canvas/validation";
import { portableAssetNameSchema } from "../../canvas/media";
import {
  readExerciseRecords,
  findExerciseOperation,
  commitExerciseOperation,
  pendingExerciseOperations,
} from "../../library/exercises";
import {
  exerciseMarkdownSchema,
  exerciseOperationSchema,
  ExerciseError,
} from "../../library/exercises/schema";
import {
  readVersionedPdf,
  replacePdf,
  pdfEtag,
  verifyPdfVersion,
} from "../../library/pdf/file";
import { withFilesystemLock } from "../../filesystem-lock";
import { renderSharedExercises } from "../sandbox";
import { SharingError } from "../protocol/values";
import { localizeCanvas, packageCanvas } from "./canvas";

export interface ArtifactActor {
  id: string;
  name: string;
}
export type ArtifactCommit = (operation: () => void) => void;

export function readSourceCanvas(topic: string, slug: string) {
  const paper = getPaper(topic, slug);
  if (!paper) throw new SharingError("Unknown paper.", 404);
  const current = readCanvas(topic, slug);
  const packed = packageCanvas(
    current.document,
    paper.companionDir,
    topic,
    slug,
  );
  return {
    document: packed.canvas,
    assets: packed.assets,
    version: current.version,
  };
}

export function saveSourceCanvas(
  topic: string,
  slug: string,
  version: string,
  value: unknown,
  actor: ArtifactActor,
  commit: ArtifactCommit,
  portable = true,
) {
  const paper = getPaper(topic, slug);
  if (!paper) throw new SharingError("Unknown paper.", 404);
  const current = readCanvas(topic, slug);
  const previous = packageCanvas(
    current.document,
    paper.companionDir,
    topic,
    slug,
  );
  const names = { ...previous.sourceNames };
  const next = portable
    ? validateSharedCanvas(value, (source) => {
        if (!source.startsWith("/canvas-assets/"))
          throw new SharingError("Invalid canvas media address.", 422);
        const name = portableAssetNameSchema.parse(source.slice(15));
        const original = names[name] ?? name;
        const asset = readCanvasAsset(paper.companionDir, original, true);
        if (asset.name !== name)
          throw new SharingError("Invalid canvas media digest.", 422);
        names[name] = original;
        return source;
      })
    : packageCanvas(value, paper.companionDir, topic, slug).canvas;
  if (!next)
    throw new SharingError("A shared canvas must contain a document.", 422);
  const document = attributeCanvas(next, previous.canvas, actor);
  const localized = localizeCanvas(document, topic, slug, names);
  // Repackage enforces the aggregate asset limit on this exact new document.
  packageCanvas(localized, paper.companionDir, topic, slug);
  let saved = "";
  commit(() => {
    saved = saveCanvas(topic, slug, version, localized);
  });
  return { document, version: saved };
}

export function uploadSourceAsset(
  topic: string,
  slug: string,
  bytes: Uint8Array,
  mime: string,
  actor: ArtifactActor,
  commit: ArtifactCommit,
): string {
  let name = "";
  commit(() => {
    name = storeCanvasAsset(topic, slug, bytes, mime, actor.id, true);
  });
  return name;
}

export function deleteSourceAsset(
  topic: string,
  slug: string,
  name: string,
  actor: ArtifactActor,
  commit: ArtifactCommit,
): void {
  commit(() => removeCanvasAsset(topic, slug, name, actor.id));
}

/** Append pages in the isolated PDF worker. Existing ink and coordinates survive. */
export async function createSourceExercise(
  topic: string,
  slug: string,
  markdown: string,
  operationId: string,
  actor: ArtifactActor,
  commit: ArtifactCommit,
) {
  const content = exerciseMarkdownSchema.parse(markdown);
  exerciseOperationSchema.parse(operationId);
  return withFilesystemLock("exercises", `${topic}/${slug}`, 2000, async () => {
    const paper = getPaper(topic, slug);
    if (!paper) throw new SharingError("Unknown paper.", 404);
    const current = readExerciseRecords(topic, slug);
    const previous = findExerciseOperation(topic, slug, operationId);
    if (
      previous &&
      (previous.actorId !== actor.id ||
        previous.markdownHash !==
          crypto.createHash("sha256").update(content).digest("hex"))
    )
      throw new ExerciseError(
        "This exercise operation was already used for different content.",
        409,
      );
    if (previous?.status === "complete") {
      let saved = "";
      commit(() => {
        saved = commitExerciseOperation(
          topic,
          slug,
          {
            operationId,
            markdown: content,
            actorId: actor.id,
            author: actor.name,
            createdAt: previous.createdAt,
          },
          current.revision,
        );
      });
      return { saved };
    }
    if (current.pending && !previous)
      throw new ExerciseError(
        "Retry the incomplete exercise save before adding another.",
        409,
      );
    const pdf = await readVersionedPdf(topic, slug, "exercises");
    const entry = { operationId, markdown: content };
    const entries = pdf
      ? [entry]
      : [
          ...current.records.filter(
            (record) => record.operationId !== operationId,
          ),
          entry,
        ];
    const bytes = await renderSharedExercises(
      pdf?.bytes ?? null,
      paper.meta.title,
      entries,
    );
    let saved = "";
    const record = {
      ...entry,
      actorId: actor.id,
      author: actor.name,
      createdAt: previous?.createdAt ?? new Date().toISOString(),
    };
    if (pdf && pdfEtag(bytes) === pdf.etag) {
      await verifyPdfVersion(
        topic,
        slug,
        pdf.etag,
        (verify) =>
          commit(() => {
            verify();
            saved = commitExerciseOperation(
              topic,
              slug,
              record,
              current.revision,
            );
          }),
        "exercises",
      );
    } else {
      await replacePdf(
        topic,
        slug,
        pdf?.etag ?? null,
        bytes,
        (replace) =>
          commit(() => {
            saved = commitExerciseOperation(
              topic,
              slug,
              record,
              current.revision,
              replace,
            );
          }),
        "exercises",
      );
    }
    return { saved };
  });
}

/** Finish only content already durably accepted under the original contributor. */
export async function recoverSourceExercises(
  topic: string,
  slug: string,
  commit: ArtifactCommit,
): Promise<void> {
  for (const pending of pendingExerciseOperations(topic, slug))
    await createSourceExercise(
      topic,
      slug,
      pending.markdown,
      pending.operationId,
      { id: pending.actorId, name: pending.author },
      commit,
    );
}

import fs from "node:fs";
import path from "node:path";
import { randomBytes } from "node:crypto";
import { z } from "zod";
import {
  type Chat,
  readChat,
  createChat,
  appendMessage,
} from "../library/chats";
import { type PaperShare, withShareFiles } from "../library/shares";
import {
  getPaper,
  readText,
  uniqueSlug,
  companionDir,
  writeMeta,
  writeSummary,
  writeText,
  acceptFromInbox,
} from "../library/papers";
import { readVersionedPdf, pdfEtag } from "../library/pdf/file";
import { validateSharedPdf } from "./protocol/pdf";
export { validateSharedPdf } from "./protocol/pdf";
import { dataRoot } from "../data-dir";
import { getProfile } from "../auth/users";
import { writeCaptureOwner } from "../capture/jobs/ownership";
import { PapernookIdentityStore } from "../auth/identity-store";
import {
  withProfileActivity,
  withProfileFiles,
  type ProfileCapability,
} from "../auth/profile-capability";
import { digest, ownerActorId } from "./storage";
import {
  snapshotArtifacts,
  stageArtifacts,
  validateArtifacts,
} from "./artifacts/snapshot";
import { readPublishedArtifacts } from "./artifacts/publication";
import {
  bundleSchema,
  conversationSchema,
  MAX_CHAT_BYTES,
  type PaperBundle,
  type PublishedThread,
  SharingError,
  idSchema,
  MAX_BUNDLE_BYTES,
} from "./schema";

/** Export only referenced local raster images. No private companion traversal. */
export function packageConversation(
  chat: Chat,
  directory: string,
): { chat: PublishedThread["chat"]; assets: PublishedThread["assets"] } {
  const assets: Record<string, string> = {};
  const messages = chat.messages.map((message) => ({
    role: message.role,
    content: message.content,
    at: message.at,
    images: message.images?.map((image) => {
      const match =
        /^crops\/([a-zA-Z0-9][a-zA-Z0-9._-]{0,199}\.(png|jpg|jpeg|webp|gif))$/.exec(
          image,
        );
      if (!match)
        throw new SharingError(
          "A conversation contains an unsupported attachment.",
        );
      const file = path.join(directory, "crops", match[1]);
      const stat = fs.lstatSync(file);
      if (!stat.isFile() || stat.size > MAX_CHAT_BYTES)
        throw new SharingError(
          "A conversation attachment is unavailable or too large.",
        );
      const bytes = fs.readFileSync(file);
      const name = `${digest(bytes)}.${match[2]}`;
      assets[name] = bytes.toString("base64");
      return `crops/${name}`;
    }),
  }));
  const packaged = {
    chat: conversationSchema.parse({ header: chat.header, messages }),
    assets,
  };
  if (Buffer.byteLength(JSON.stringify(packaged)) > MAX_CHAT_BYTES)
    throw new SharingError(
      "The conversation exceeds the 8 MB sharing limit.",
      413,
    );
  return packaged;
}

export function validateAssets(
  thread: Pick<PublishedThread, "chat" | "assets">,
): void {
  const references = new Set(
    thread.chat.messages
      .flatMap((message) => message.images ?? [])
      .map((p) => p.slice(6)),
  );
  const names = Object.keys(thread.assets);
  if (
    names.length !== references.size ||
    names.some((name) => !references.has(name))
  )
    throw new SharingError("Only referenced chat images can be shared.");
  for (const [name, encoded] of Object.entries(thread.assets)) {
    const bytes = Buffer.from(encoded, "base64");
    if (digest(bytes) !== name.split(".")[0])
      throw new SharingError("A shared image has an invalid digest.");
    const extension = name.split(".").at(-1);
    const valid =
      extension === "png"
        ? bytes
            .subarray(0, 8)
            .equals(Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]))
        : extension === "jpg" || extension === "jpeg"
          ? bytes[0] === 255 && bytes[1] === 216 && bytes[2] === 255
          : extension === "gif"
            ? /^GIF8[79]a$/.test(bytes.subarray(0, 6).toString("ascii"))
            : bytes.subarray(0, 4).toString("ascii") === "RIFF" &&
              bytes.subarray(8, 12).toString("ascii") === "WEBP";
    if (!valid)
      throw new SharingError("A shared image does not match its file type.");
  }
}

export function sourceThreads(
  share: PaperShare,
  live: boolean,
): PublishedThread[] {
  return withShareFiles(share, () => {
    const file = path.join(
      companionDir(share.topic, share.slug),
      "collaboration",
      share.id,
      "owner-chats.json",
    );
    const extraIds =
      live && fs.existsSync(file)
        ? z
            .array(idSchema)
            .max(20)
            .parse(JSON.parse(fs.readFileSync(file, "utf8")))
        : [];
    const snapshots = [
      ...share.conversations,
      ...extraIds.flatMap((id) => {
        const chat = readChat(share.topic, share.slug, share.ownerUsername, id);
        return chat ? [chat] : [];
      }),
    ];
    return snapshots.flatMap((snapshot) => {
      const current = live
        ? readChat(
            share.topic,
            share.slug,
            share.ownerUsername,
            snapshot.header.id,
          )
        : snapshot;
      if (!current) return [];
      return [packageOwnerThread(share, current as Chat)];
    });
  });
}

export function packageOwnerThread(
  share: PaperShare,
  chat: Chat,
): PublishedThread {
  const packaged = packageConversation(
    chat,
    companionDir(share.topic, share.slug),
  );
  return {
    ...packaged,
    id: chat.header.id,
    actorId: ownerActorId(share),
    author: getProfile(share.ownerUsername)?.displayName ?? share.ownerUsername,
    revision: pdfEtag(Buffer.from(JSON.stringify(packaged))),
  };
}

export async function exportBundle(
  share: PaperShare,
  conversations?: PublishedThread[],
): Promise<PaperBundle> {
  if (share.mode === "view")
    throw new SharingError("This link permits viewing only.", 403);
  const pdf = await readVersionedPdf(share.topic, share.slug);
  if (!pdf) throw new SharingError("Unknown paper.", 404);
  const artifacts =
    conversations !== undefined
      ? await snapshotArtifacts(share.topic, share.slug)
      : readPublishedArtifacts(share);
  return withShareFiles(share, () => {
    const paper = getPaper(share.topic, share.slug);
    if (!paper) throw new SharingError("Unknown paper.", 404);
    const { title, authors, year, venue, arxivId, bibtex, tags, sourceUrl } =
      paper.meta;
    const bundle = bundleSchema.parse({
      version: 1,
      mode: share.mode,
      slug: share.slug,
      meta: { title, authors, year, venue, arxivId, bibtex, tags, sourceUrl },
      summary: paper.summary,
      text: readText(share.topic, share.slug),
      pdf: Buffer.from(pdf.bytes).toString("base64"),
      etag: pdf.etag,
      conversations: conversations ?? sourceThreads(share, false),
      artifacts,
    });
    if (Buffer.byteLength(JSON.stringify(bundle)) > MAX_BUNDLE_BYTES)
      throw new SharingError(
        "This reading exceeds the sharing transfer limit.",
        413,
      );
    return bundle;
  });
}

export async function importBundle(
  bundle: PaperBundle,
  topic: string,
  capability: ProfileCapability,
  linked = false,
) {
  const parsed = bundleSchema.parse(bundle);
  const pdf = Buffer.from(parsed.pdf, "base64");
  validateSharedPdf(pdf, parsed.etag);
  for (const thread of parsed.conversations) validateAssets(thread);
  const artifacts = validateArtifacts(parsed.artifacts);
  const identity = new PapernookIdentityStore(dataRoot());
  return withProfileActivity(identity, capability, async () => {
    const base = uniqueSlug(parsed.slug);
    let slug = base;
    let directory = companionDir(null, slug);
    fs.mkdirSync(path.dirname(directory), { recursive: true });
    for (;;) {
      try {
        fs.mkdirSync(directory, { mode: 0o700 });
        break;
      } catch (error) {
        if (
          !(error instanceof Error) ||
          !("code" in error) ||
          error.code !== "EEXIST"
        )
          throw error;
        slug = `${base.slice(0, 62)}-${randomBytes(6).toString("hex")}`;
        directory = companionDir(null, slug);
      }
    }
    try {
      return withProfileFiles(identity, capability, () => {
        writeCaptureOwner(directory, capability);
        fs.writeFileSync(path.join(directory, "paper.pdf"), pdf, {
          mode: 0o600,
          flag: "wx",
        });
        writeMeta(null, slug, {
          ...parsed.meta,
          addedBy: capability.username,
          addedAt: new Date().toISOString(),
          related: [],
        });
        if (parsed.summary) writeSummary(null, slug, parsed.summary);
        if (parsed.text) writeText(null, slug, parsed.text);
        stageArtifacts(directory, artifacts, topic, slug);
        if (!linked)
          for (const thread of parsed.conversations) {
            const header = createChat(
              null,
              slug,
              capability.username,
              `${thread.author}: ${thread.chat.header.title}`.slice(0, 120),
            );
            for (const message of thread.chat.messages)
              appendMessage(
                null,
                slug,
                capability.username,
                header.id,
                message,
              );
            for (const [name, data] of Object.entries(thread.assets)) {
              fs.mkdirSync(path.join(directory, "crops"), { recursive: true });
              fs.writeFileSync(
                path.join(directory, "crops", name),
                Buffer.from(data, "base64"),
                { mode: 0o600 },
              );
            }
          }
        return withProfileFiles(identity, capability, () =>
          acceptFromInbox(slug, topic),
        );
      });
    } catch (error) {
      fs.rmSync(directory, { recursive: true, force: true });
      throw error;
    }
  });
}

import fs from "node:fs";
import { z } from "zod";
import { requestIdentity } from "../auth/access";
import {
  withConnection,
  readConnection,
  saveConnection,
  type Connection,
  assertCurrentConnection,
  participantSchema,
} from "./storage";
import { exchange } from "./transport";
import {
  base64Schema,
  revisionSchema,
  SharingError,
  sharingFailure,
  publishedThreadSchema,
} from "./schema";
import {
  pdfEtag,
  readVersionedPdf,
  replacePdf,
  type PdfKind,
} from "../library/pdf/file";
import { getPaper, withPaperMutation } from "../library/papers";
import { PapernookIdentityStore } from "../auth/identity-store";
import { withProfileFiles } from "../auth/profile-capability";
import { dataRoot } from "../data-dir";
import { validateSharedPdf, validateAssets } from "./bundle";
import type { PdfCommentAction } from "../library/pdf/comments";
import type { ProfileCapability } from "../auth/profile-capability";
import { MAX_COLLABORATIVE_PDF_BYTES } from "./sandbox";
import { syncConnectedArtifacts } from "./artifacts/gateway";

const saveResultSchema = z
  .object({
    etag: revisionSchema,
    pdf: base64Schema,
    canonicalized: z.literal(true),
  })
  .strict();

export function connectionExchange(
  topic: string,
  slug: string,
  capability: ProfileCapability,
  connection: Connection,
  operation: unknown,
) {
  return exchange(connection.url, operation, connection.token, () =>
    withProfileFiles(new PapernookIdentityStore(dataRoot()), capability, () =>
      assertCurrentConnection(topic, slug, capability, connection),
    ),
  );
}

export async function connectedState(
  topic: string,
  slug: string,
  capability: ProfileCapability,
  connection: Connection,
) {
  const value = z
    .object({
      participant: participantSchema.omit({ tokenHash: true }),
      threads: z.array(publishedThreadSchema).max(100),
    })
    .strict()
    .parse(
      await connectionExchange(topic, slug, capability, connection, {
        action: "threads",
      }),
    );
  for (const thread of value.threads) validateAssets(thread);
  return value;
}

/** A WebDAV writer cannot identify a person. Preserve unrecognized local edits. */
export async function updateMirror(
  topic: string,
  slug: string,
  connection: Connection,
  bytes: Uint8Array,
  etag: string,
  capability: ProfileCapability,
  kind: PdfKind = "paper",
) {
  validateSharedPdf(bytes, etag);
  const current = await readVersionedPdf(topic, slug, kind);
  if (!current) throw new SharingError("The local paper was removed.", 404);
  const expected =
    kind === "paper"
      ? connection.mirrorEtag
      : connection.artifacts?.mirror.exercisePdf;
  if (current.etag !== expected && current.etag !== etag)
    throw new SharingError(
      "The local PDF changed outside collaboration. Preserve that copy before reconnecting; it has not been uploaded.",
      409,
    );
  if (current.etag !== etag)
    await replacePdf(
      topic,
      slug,
      current.etag,
      bytes,
      (commit) =>
        withProfileFiles(
          new PapernookIdentityStore(dataRoot()),
          capability,
          () =>
            withPaperMutation(slug, () => {
              assertCurrentConnection(topic, slug, capability, connection);
              commit();
            }),
        ),
      kind,
    );
  const next = { ...connection };
  if (kind === "paper") next.mirrorEtag = etag;
  else if (next.artifacts)
    next.artifacts = {
      mirror: { ...next.artifacts.mirror, exercisePdf: etag },
      source: next.artifacts.source
        ? { ...next.artifacts.source, exercisePdf: etag }
        : null,
    };
  saveConnection(topic, slug, capability, next);
  Object.assign(connection, next);
}

export async function connectedPdfResponse(
  request: Request,
  topic: string,
  slug: string,
  kind: PdfKind = "paper",
): Promise<Response | null> {
  if (!readConnection(topic, slug)) return null;
  try {
    const admission = await requestIdentity();
    if (!admission?.capability) throw new SharingError("Not signed in.", 401);
    return await withConnection(
      topic,
      slug,
      admission.capability,
      async (connection) => {
        if (kind === "exercises" && request.method !== "HEAD")
          await syncConnectedArtifacts(
            topic,
            slug,
            admission.capability!,
            connection,
          );
        if (request.method === "HEAD") {
          const version = z
            .object({ etag: revisionSchema })
            .strict()
            .parse(
              await connectionExchange(
                topic,
                slug,
                admission.capability!,
                connection,
                { action: "version", kind },
              ),
            );
          return new Response(null, {
            headers: {
              etag: version.etag,
              "cache-control": "private, no-store",
            },
          });
        }
        const bundle = z
          .object({ etag: revisionSchema, pdf: base64Schema })
          .strict()
          .parse(
            await connectionExchange(
              topic,
              slug,
              admission.capability!,
              connection,
              { action: "pdf", kind },
            ),
          );
        const bytes = Buffer.from(bundle.pdf, "base64");
        if (pdfEtag(bytes) !== bundle.etag)
          throw new SharingError(
            "The sharing server returned an invalid PDF version.",
            502,
          );
        await updateMirror(
          topic,
          slug,
          connection,
          bytes,
          bundle.etag,
          admission.capability!,
          kind,
        );
        return new Response(request.method === "HEAD" ? null : bytes, {
          headers: {
            "Content-Type": "application/pdf",
            etag: bundle.etag,
            "cache-control": "private, no-store",
          },
        });
      },
    );
  } catch (error) {
    return sharingFailure(error);
  }
}

export async function saveConnectedPdf(
  topic: string,
  slug: string,
  expected: string,
  bytes: Uint8Array,
  kind: PdfKind = "paper",
): Promise<{ etag: string; canonicalized: true } | null> {
  if (!readConnection(topic, slug)) return null;
  if (bytes.byteLength > MAX_COLLABORATIVE_PDF_BYTES)
    throw new SharingError(
      "Collaborative annotation saves support PDFs up to 32 MB.",
      413,
    );
  return saveConnected(
    topic,
    slug,
    {
      action: "save-pdf",
      etag: expected,
      pdf: Buffer.from(bytes).toString("base64"),
      kind,
    },
    kind,
  );
}

export async function saveConnectedComment(
  topic: string,
  slug: string,
  expected: string,
  comment: PdfCommentAction,
) {
  return saveConnected(topic, slug, {
    action: "comment",
    etag: expected,
    comment,
  });
}

async function saveConnected(
  topic: string,
  slug: string,
  operation: unknown,
  kind: PdfKind = "paper",
): Promise<{ etag: string; canonicalized: true } | null> {
  if (!readConnection(topic, slug)) return null;
  const admission = await requestIdentity();
  if (!admission?.capability) throw new SharingError("Not signed in.", 401);
  return withConnection(
    topic,
    slug,
    admission.capability,
    async (connection) => {
      const result = saveResultSchema.parse(
        await connectionExchange(
          topic,
          slug,
          admission.capability!,
          connection,
          operation,
        ),
      );
      const canonical = Buffer.from(result.pdf, "base64");
      if (pdfEtag(canonical) !== result.etag)
        throw new SharingError(
          "The saved PDF version could not be verified.",
          502,
        );
      await updateMirror(
        topic,
        slug,
        connection,
        canonical,
        result.etag,
        admission.capability!,
        kind,
      );
      return { etag: result.etag, canonicalized: true };
    },
  );
}

export function localMirrorChanged(
  topic: string,
  slug: string,
  connection: Connection,
): boolean {
  const paper = getPaper(topic, slug);
  return (
    !paper || pdfEtag(fs.readFileSync(paper.pdfPath)) !== connection.mirrorEtag
  );
}

import { z } from "zod";
import DecodeStream from "pdf-lib/cjs/core/streams/DecodeStream";
import { applyCollaborativeAnnotations } from "./annotations";
import { base64Schema, labelSchema, SharingError } from "./protocol/values";
import {
  pdfCommentActionSchema,
  updatePdfComment,
  PdfCommentError,
} from "../library/pdf/comments";
import {
  renderExerciseDocument,
  ExerciseRenderError,
} from "../library/exercises/render";

const descriptor = Object.getOwnPropertyDescriptor(
  DecodeStream.prototype,
  "ensureBuffer",
);
const original: unknown = descriptor?.value;
if (typeof original !== "function")
  throw new Error("The PDF decompression budget could not be installed.");
const allocate = original as (
  this: DecodeStream,
  requested: number,
) => Uint8Array;
const allocations = new WeakMap<DecodeStream, number>();
let allocatedBytes = 0;
let decodingRejected = false;
// Keep the canonical decompressor, but reject oversized allocations before it runs.
Object.defineProperty(DecodeStream.prototype, "ensureBuffer", {
  ...descriptor,
  value: function (this: DecodeStream, requested: number): Uint8Array {
    const reject = () => {
      decodingRejected = true;
      throw new SharingError("The PDF exceeds the decompression budget.", 413);
    };
    if (
      decodingRejected ||
      !Number.isSafeInteger(requested) ||
      requested < 0 ||
      requested > 16 * 1024 * 1024
    )
      return reject();
    let capacity = 512;
    const minimum: unknown = Reflect.get(this, "minBufferLength");
    if (
      typeof minimum !== "number" ||
      !Number.isSafeInteger(minimum) ||
      minimum < 0 ||
      minimum > 16 * 1024 * 1024
    )
      return reject();
    capacity = Math.max(capacity, minimum);
    while (capacity < requested) capacity *= 2;
    if (capacity > (allocations.get(this) ?? 0)) {
      allocatedBytes += capacity;
      if (allocatedBytes > 128 * 1024 * 1024) return reject();
      allocations.set(this, capacity);
    }
    return allocate.call(this, requested);
  },
});

const baseSchema = z
  .object({
    current: base64Schema,
    actor: z.object({ id: z.string().max(100), name: labelSchema }).strict(),
  })
  .strict();
const inputSchema = z.discriminatedUnion("action", [
  baseSchema.extend({
    action: z.literal("annotations"),
    proposed: base64Schema,
    owner: z.boolean(),
  }),
  baseSchema.extend({
    action: z.literal("comment"),
    comment: pdfCommentActionSchema,
  }),
  z
    .object({
      action: z.literal("exercises"),
      current: base64Schema,
      title: z.string().max(2000),
      entries: z
        .array(
          z
            .object({
              operationId: z.string().regex(/^[a-zA-Z0-9._-]{1,100}$/),
              markdown: z.string().min(1).max(100_000),
            })
            .strict(),
        )
        .max(100),
    })
    .strict(),
]);
const chunks: Buffer[] = [];
let size = 0;
process.stdin.on("data", (chunk: Buffer) => {
  size += chunk.byteLength;
  if (size > 90 * 1024 * 1024) process.exit(1);
  chunks.push(chunk);
});
process.stdin.on("end", () => {
  void (async () => {
    try {
      const input = inputSchema.parse(
        JSON.parse(Buffer.concat(chunks).toString("utf8")),
      );
      const pdf =
        input.action === "exercises"
          ? await renderExerciseDocument(
              input.title,
              input.entries,
              input.current ? Buffer.from(input.current, "base64") : undefined,
            )
          : input.action === "comment"
            ? await updatePdfComment(
                Buffer.from(input.current, "base64"),
                input.comment,
                input.actor.name,
                input.actor.id,
              )
            : await applyCollaborativeAnnotations(
                Buffer.from(input.current, "base64"),
                Buffer.from(input.proposed, "base64"),
                input.actor,
                input.owner,
              );
      if (decodingRejected)
        throw new SharingError(
          "The PDF exceeds the decompression budget.",
          413,
        );
      process.stdout.write(
        JSON.stringify({ ok: true, pdf: Buffer.from(pdf).toString("base64") }),
      );
    } catch (error) {
      process.stdout.write(
        JSON.stringify({
          ok: false,
          status: decodingRejected
            ? 413
            : error instanceof SharingError
              ? error.status
              : 422,
          message: decodingRejected
            ? "The PDF exceeds the decompression budget."
            : error instanceof SharingError ||
                error instanceof PdfCommentError ||
                error instanceof ExerciseRenderError
              ? error.message
              : "The PDF contains unsupported or invalid annotation data.",
        }),
      );
    }
  })();
});

import { spawn } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import { z } from "zod";
import { base64Schema, SharingError } from "./schema";
import type { PdfCommentAction } from "../library/pdf/comments";
import type { ExerciseRenderEntry } from "../library/exercises/render";

export const MAX_COLLABORATIVE_PDF_BYTES = 32 * 1024 * 1024;

/** Parse untrusted PDF object streams outside the web server, with no ambient credentials. */
export async function reconstructAnnotations(
  current: Uint8Array,
  proposed: Uint8Array,
  actor: { id: string; name: string },
  owner = false,
): Promise<Uint8Array> {
  if (proposed.byteLength > MAX_COLLABORATIVE_PDF_BYTES)
    throw new SharingError(
      "Collaborative annotation saves support PDFs up to 32 MB.",
      413,
    );
  return runWorker(current, {
    action: "annotations",
    proposed: Buffer.from(proposed).toString("base64"),
    actor,
    owner,
  });
}

export function reconstructComment(
  current: Uint8Array,
  comment: PdfCommentAction,
  actor: { id: string; name: string },
): Promise<Uint8Array> {
  return runWorker(current, { action: "comment", comment, actor });
}

export function renderSharedExercises(
  current: Uint8Array | null,
  title: string,
  entries: ExerciseRenderEntry[],
): Promise<Uint8Array> {
  return runWorker(current ?? new Uint8Array(), {
    action: "exercises",
    title,
    entries,
  });
}

type WorkerOperation =
  | {
      action: "annotations";
      proposed: string;
      actor: { id: string; name: string };
      owner: boolean;
    }
  | {
      action: "comment";
      comment: PdfCommentAction;
      actor: { id: string; name: string };
    }
  | { action: "exercises"; title: string; entries: ExerciseRenderEntry[] };

async function runWorker(
  current: Uint8Array,
  operation: WorkerOperation,
): Promise<Uint8Array> {
  if (current.byteLength > MAX_COLLABORATIVE_PDF_BYTES)
    throw new SharingError(
      "Collaborative annotation saves support PDFs up to 32 MB.",
      413,
    );
  const runtimeWorker = path.resolve("scripts/sharing-worker.cjs");
  const worker = fs.existsSync(runtimeWorker)
    ? runtimeWorker
    : path.resolve("build/sharing-worker.cjs");
  if (!fs.existsSync(worker))
    throw new SharingError(
      "The annotation worker is unavailable. Rebuild Papernook before enabling collaboration.",
      503,
    );
  return new Promise((resolve, reject) => {
    const child = spawn(
      process.execPath,
      [
        "--max-old-space-size=256",
        "--experimental-permission",
        `--allow-fs-read=${worker}`,
        worker,
      ],
      { env: { NODE_ENV: "production" }, stdio: ["pipe", "pipe", "ignore"] },
    );
    const chunks: Buffer[] = [];
    let size = 0;
    let settled = false;
    const finish = (error?: Error, bytes?: Uint8Array) => {
      if (settled) return;
      settled = true;
      clearTimeout(timeout);
      child.kill("SIGKILL");
      if (error) reject(error);
      else resolve(bytes!);
    };
    const timeout = setTimeout(
      () =>
        finish(
          new SharingError(
            "Annotation processing timed out. No changes were saved.",
            422,
          ),
        ),
      15_000,
    );
    child.on("error", () =>
      finish(new SharingError("The annotation worker could not start.", 503)),
    );
    child.stdin.on("error", () =>
      finish(
        new SharingError(
          "The annotation worker could not process this PDF.",
          422,
        ),
      ),
    );
    child.stdout.on("data", (chunk: Buffer) => {
      size += chunk.byteLength;
      if (size > 48 * 1024 * 1024) {
        finish(
          new SharingError(
            "The annotated PDF exceeds the processing limit.",
            413,
          ),
        );
        return;
      }
      chunks.push(chunk);
    });
    child.on("close", (code) => {
      if (settled) return;
      if (code !== 0) {
        finish(
          new SharingError(
            "The annotation worker rejected this PDF. No changes were saved.",
            422,
          ),
        );
        return;
      }
      try {
        const result = z
          .discriminatedUnion("ok", [
            z.object({ ok: z.literal(true), pdf: base64Schema }).strict(),
            z
              .object({
                ok: z.literal(false),
                status: z.number().int().min(400).max(599),
                message: z.string().max(300),
              })
              .strict(),
          ])
          .parse(JSON.parse(Buffer.concat(chunks).toString("utf8")));
        if (result.ok) {
          const bytes = Buffer.from(result.pdf, "base64");
          if (bytes.byteLength > MAX_COLLABORATIVE_PDF_BYTES)
            finish(
              new SharingError(
                "The annotated PDF exceeds the 32 MB collaboration limit.",
                413,
              ),
            );
          else finish(undefined, bytes);
        } else finish(new SharingError(result.message, result.status));
      } catch {
        finish(
          new SharingError(
            "The annotation worker returned an invalid result.",
            422,
          ),
        );
      }
    });
    child.stdin.end(
      JSON.stringify({
        current: Buffer.from(current).toString("base64"),
        ...operation,
      }),
    );
  });
}

import fs from "node:fs";
import path from "node:path";
import {
  createHash,
  randomBytes,
  randomUUID,
  timingSafeEqual,
} from "node:crypto";
import { z } from "zod";
import { guardStream } from "thesidedoor-core/runtime/stream";
import {
  acquireFileLock,
  acquireFileLockSync,
  FileLockBusyError,
  syncDirectory,
} from "thesidedoor-core/storage";
import { dataRoot } from "../data-dir";
import { PapernookIdentityStore } from "../auth/identity-store";
import {
  withProfileActivity,
  withProfileFiles,
  type ProfileCapability,
} from "../auth/profile-capability";
import {
  companionDir,
  getPaper,
  visitPaperCompanions,
  withPaperMutation,
} from "../library/papers";
import { getShare, withShareFiles, type PaperShare } from "../library/shares";
import { pdfEtag } from "../library/pdf/file";
import { artifactVersionsSchema } from "./artifacts/schema";
import {
  idSchema,
  labelSchema,
  secretSchema,
  slugSchema,
  revisionSchema,
  SharingError,
  sharingStatusSchema,
} from "./schema";

export const participantSchema = z
  .object({
    id: idSchema,
    tokenHash: secretSchema,
    requestedName: labelSchema,
    name: labelSchema,
    status: z.enum(["pending", "approved", "revoked"]),
    createdAt: z.string().datetime(),
  })
  .strict();
export type Participant = z.infer<typeof participantSchema>;
const connectionSchema = z
  .object({
    version: z.literal(1),
    url: z.string().url(),
    token: secretSchema,
    participantId: idSchema,
    username: slugSchema,
    generation: z.number().int().nonnegative(),
    mirrorEtag: revisionSchema,
    artifacts: z
      .object({
        source: artifactVersionsSchema.nullable(),
        mirror: artifactVersionsSchema,
      })
      .strict()
      .optional(),
  })
  .strict();
export type Connection = z.infer<typeof connectionSchema>;

export function digest(value: string | Uint8Array): string {
  return createHash("sha256").update(value).digest("hex");
}
export function newSecret(): string {
  return randomBytes(32).toString("hex");
}
export function participantId(token: string): string {
  return digest(token).slice(0, 16);
}

export function ownerActorId(
  share: Pick<PaperShare, "ownerUsername" | "ownerGeneration">,
): string {
  return digest(`owner:${share.ownerUsername}:${share.ownerGeneration}`).slice(
    0,
    16,
  );
}

export function ensureCollaborationOwner(share: PaperShare): void {
  const file = path.join(collaborationDir(share), "owner.json");
  const expected = {
    username: share.ownerUsername,
    generation: share.ownerGeneration,
    shareId: share.id,
  };
  if (fs.existsSync(file)) {
    const parsed = z
      .object({
        username: slugSchema,
        generation: z.number().int().nonnegative(),
        shareId: secretSchema,
      })
      .strict()
      .parse(JSON.parse(fs.readFileSync(file, "utf8")));
    if (
      parsed.username !== expected.username ||
      parsed.generation !== expected.generation ||
      parsed.shareId !== expected.shareId
    )
      throw new SharingError("Collaboration ownership is inconsistent.", 409);
    return;
  }
  withShareFiles(share, () => writeJson(file, expected));
}

export function writeJson(file: string, value: unknown): void {
  fs.mkdirSync(path.dirname(file), { recursive: true, mode: 0o700 });
  const temp = `${file}.${randomUUID()}.tmp`;
  try {
    fs.writeFileSync(temp, JSON.stringify(value), {
      mode: 0o600,
      flag: "wx",
      flush: true,
    });
    fs.renameSync(temp, file);
    syncDirectory(path.dirname(file));
  } finally {
    fs.rmSync(temp, { force: true });
  }
}

export function collaborationDir(share: PaperShare): string {
  return path.join(
    companionDir(share.topic, share.slug),
    "collaboration",
    share.id,
  );
}

export function requireCollaboration(
  topic: string,
  slug: string,
  shareId: string,
): PaperShare {
  const share = getShare(topic, slug, shareId);
  if (!share || share.mode !== "collaborate")
    throw new SharingError("Unknown collaboration.", 404);
  return share;
}

export function readParticipants(share: PaperShare): Participant[] {
  const file = path.join(collaborationDir(share), "participants.json");
  if (!fs.existsSync(file)) return [];
  return z
    .array(participantSchema)
    .max(32)
    .parse(JSON.parse(fs.readFileSync(file, "utf8")));
}

export function authenticateParticipant(
  share: PaperShare,
  token: string,
  approved = true,
): Participant {
  if (!secretSchema.safeParse(token).success)
    throw new SharingError("Invalid collaboration credential.", 401);
  const hash = digest(token);
  if (fs.existsSync(path.join(collaborationDir(share), "revoked", hash)))
    throw new SharingError(
      "This collaboration credential has been revoked.",
      403,
    );
  const participant = readParticipants(share).find((p) =>
    timingSafeEqual(Buffer.from(p.tokenHash, "hex"), Buffer.from(hash, "hex")),
  );
  if (!participant || participant.status === "revoked")
    throw new SharingError(
      "Collaboration access was revoked or is unknown.",
      403,
    );
  if (
    participant.status === "pending" &&
    Date.now() - Date.parse(participant.createdAt) > 24 * 60 * 60_000
  )
    throw new SharingError("The collaboration request expired.", 403);
  if (approved && participant.status !== "approved")
    throw new SharingError("Waiting for owner approval.", 403);
  return participant;
}

/** Authority lock is shared by remote commits, approval and link revocation. */
export async function withCollaboration<Result>(
  share: PaperShare,
  operation: () => Promise<Result>,
): Promise<Result> {
  if (share.ownerGeneration === undefined)
    throw new SharingError("Unknown collaboration.", 404);
  const identity = new PapernookIdentityStore(dataRoot());
  return withProfileActivity(
    identity,
    { username: share.ownerUsername, generation: share.ownerGeneration },
    async () => {
      const release = await acquireFileLock(
        path.join(dataRoot(), "locks", "collaboration", `${share.id}.guard`),
      );
      try {
        withShareFiles(share, () => undefined);
        ensureCollaborationOwner(share);
        return await operation();
      } finally {
        await release();
      }
    },
  );
}

export function requestParticipant(
  share: PaperShare,
  token: string,
  name: string,
): Participant {
  secretSchema.parse(token);
  if (
    fs.existsSync(path.join(collaborationDir(share), "revoked", digest(token)))
  )
    throw new SharingError(
      "This collaboration credential has been revoked.",
      403,
    );
  const label = labelSchema.parse(name);
  return withShareFiles(share, () => {
    const participants = readParticipants(share).filter(
      (p) =>
        p.status === "approved" ||
        (p.status === "pending" &&
          Date.now() - Date.parse(p.createdAt) <= 24 * 60 * 60_000),
    );
    const existing = participants.find((p) => p.tokenHash === digest(token));
    if (existing) return authenticateParticipant(share, token, false);
    if (participants.length >= 32)
      throw new SharingError(
        "This collaboration has reached its request limit.",
        429,
      );
    const participant: Participant = {
      id: participantId(token),
      tokenHash: digest(token),
      requestedName: label,
      name: label,
      status: "pending",
      createdAt: new Date().toISOString(),
    };
    writeJson(path.join(collaborationDir(share), "participants.json"), [
      ...participants,
      participant,
    ]);
    return participant;
  });
}

export function setParticipant(
  share: PaperShare,
  id: string,
  status: "approved" | "revoked",
  name?: string,
): void {
  idSchema.parse(id);
  const participants = readParticipants(share);
  const participant = participants.find((p) => p.id === id);
  if (!participant) throw new SharingError("Unknown participant.", 404);
  if (
    status === "approved" &&
    (participant.status === "revoked" ||
      (Date.now() - Date.parse(participant.createdAt) > 24 * 60 * 60_000 &&
        participant.status === "pending"))
  )
    throw new SharingError(
      "This credential cannot be approved. Request access again.",
      409,
    );
  participant.status = status;
  if (status === "revoked") {
    const folder = path.join(collaborationDir(share), "revoked");
    fs.mkdirSync(folder, { recursive: true, mode: 0o700 });
    const file = path.join(folder, participant.tokenHash);
    if (!fs.existsSync(file))
      fs.writeFileSync(file, "", { flag: "wx", mode: 0o600, flush: true });
    syncDirectory(folder);
  }
  if (name !== undefined) participant.name = labelSchema.parse(name);
  withShareFiles(share, () =>
    writeJson(
      path.join(collaborationDir(share), "participants.json"),
      participants.filter((entry) => entry.status !== "revoked"),
    ),
  );
}

export function leaveCollaboration(
  share: PaperShare,
  participant: Participant,
): void {
  if (participant.status === "approved") {
    setParticipant(share, participant.id, "revoked");
    return;
  }
  withShareFiles(share, () =>
    writeJson(
      path.join(collaborationDir(share), "participants.json"),
      readParticipants(share).filter((entry) => entry.id !== participant.id),
    ),
  );
}

/** Bound aggregate buffering and PDF parsing across requests and processes. */
function acquireSharingTransfer(
  direction: "incoming" | "outgoing",
): () => void {
  for (let slot = 0; slot < 2; slot++) {
    let release: () => void;
    try {
      release = acquireFileLockSync(
        path.join(
          dataRoot(),
          "locks",
          "sharing-transfer",
          `${direction}-${slot}.guard`,
        ),
      );
    } catch (error) {
      if (error instanceof FileLockBusyError) continue;
      throw error;
    }
    let released = false;
    return () => {
      if (released) return;
      released = true;
      release();
    };
  }
  throw new SharingError("Sharing is busy. Try again in a moment.", 429);
}

export async function withSharingTransfer<Result>(
  operation: () => Promise<Result>,
  direction: "incoming" | "outgoing" = "incoming",
): Promise<Result> {
  const release = acquireSharingTransfer(direction);
  try {
    return await operation();
  } finally {
    release();
  }
}

/** Keep large response buffers admitted until the transport drains or cancels. */
export async function withSharingResponse(
  operation: () => Promise<Response>,
): Promise<Response> {
  const release = acquireSharingTransfer("incoming");
  try {
    const response = await operation();
    if (!response.ok || !response.body) {
      release();
      return response;
    }
    return streamTransferResponse(response, release);
  } catch (error) {
    release();
    throw error;
  }
}

function streamTransferResponse(
  response: Response,
  release: () => void,
): Response {
  const reader = response.body!.getReader();
  let pending: Uint8Array | null = null;
  let offset = 0;
  let stopped = false;
  let cleanup: Promise<void> | null = null;
  let released = false;
  let deadline: ReturnType<typeof setTimeout>;
  const releaseOnce = () => {
    if (released) return;
    released = true;
    clearTimeout(deadline);
    release();
  };
  const stop = (reason: unknown): Promise<void> => {
    stopped = true;
    pending = null;
    offset = 0;
    cleanup ??= (async () => {
      try {
        await reader.cancel(reason);
      } finally {
        reader.releaseLock();
      }
    })();
    return cleanup;
  };
  const copied = new ReadableStream<Uint8Array>(
    {
      start(controller) {
        deadline = setTimeout(() => {
          if (stopped) return;
          const error = new SharingError("Sharing response timed out.", 408);
          controller.error(error);
          void stop(error)
            .finally(releaseOnce)
            .catch(() => {
              console.error("papernook sharing: response cleanup failed");
            });
        }, 60_000);
      },
      async pull(controller) {
        try {
          if (stopped) return;
          if (!pending) {
            const next = await reader.read();
            if (stopped) return;
            if (next.done) {
              stopped = true;
              reader.releaseLock();
              controller.close();
              return;
            }
            pending = next.value;
            offset = 0;
          }
          const end = Math.min(pending.byteLength, offset + 64 * 1024);
          // A view would keep the entire serialized response alive in Node's
          // blocked write. Each socket may retain only its bounded copy.
          const chunk = Uint8Array.from(pending.subarray(offset, end));
          offset = end;
          if (offset === pending.byteLength) {
            pending = null;
            offset = 0;
          }
          controller.enqueue(chunk);
        } catch (error) {
          await stop(error).catch(() => undefined);
          throw error;
        }
      },
      cancel(reason) {
        return stop(reason);
      },
    },
    { highWaterMark: 0 },
  );
  return new Response(
    guardStream(copied, { validate: () => undefined, release: releaseOnce }),
    {
      status: response.status,
      statusText: response.statusText,
      headers: response.headers,
    },
  );
}

export function publicParticipant(participant: Participant) {
  return {
    id: participant.id,
    requestedName: participant.requestedName,
    name: participant.name,
    status: participant.status,
    createdAt: participant.createdAt,
  };
}

function connectionPath(topic: string, slug: string): string {
  return path.join(
    companionDir(topic, slug),
    "collaboration",
    "connection.json",
  );
}
export function readConnection(topic: string, slug: string): Connection | null {
  const file = connectionPath(topic, slug);
  try {
    return connectionSchema.parse(JSON.parse(fs.readFileSync(file, "utf8")));
  } catch (error) {
    if (error instanceof Error && "code" in error && error.code === "ENOENT")
      return null;
    throw new SharingError(
      "The saved collaboration binding is unavailable or invalid. Repair it before editing this paper.",
      503,
    );
  }
}
export function withConnection<Result>(
  topic: string,
  slug: string,
  capability: ProfileCapability,
  operation: (connection: Connection) => Promise<Result>,
): Promise<Result> {
  return withProfileActivity(
    new PapernookIdentityStore(dataRoot()),
    capability,
    async () => {
      const connection = readConnection(topic, slug);
      if (
        !getPaper(topic, slug) ||
        !connection ||
        connection.username !== capability.username ||
        connection.generation !== capability.generation
      )
        throw new SharingError(
          "This collaboration belongs to another profile.",
          403,
        );
      const release = await acquireFileLock(
        path.join(dataRoot(), "locks", "sharing-connection", `${slug}.guard`),
        { signal: AbortSignal.timeout(60_000) },
      );
      try {
        const identity = new PapernookIdentityStore(dataRoot());
        const latest = withProfileFiles(identity, capability, () => {
          assertCurrentConnection(topic, slug, capability, connection);
          return readConnection(topic, slug)!;
        });
        const result = await operation(latest);
        withProfileFiles(identity, capability, () => undefined);
        return result;
      } finally {
        await release();
      }
    },
  );
}
export function saveConnection(
  topic: string,
  slug: string,
  capability: ProfileCapability,
  connection: Connection,
  initial = false,
  before?: () => void,
): void {
  withProfileFiles(new PapernookIdentityStore(dataRoot()), capability, () =>
    withPaperMutation(slug, () => {
      if (!getPaper(topic, slug))
        throw new SharingError("The connected paper was removed.", 404);
      if (!initial)
        assertCurrentConnection(topic, slug, capability, connection);
      const paper = getPaper(topic, slug);
      if (
        !paper ||
        pdfEtag(fs.readFileSync(paper.pdfPath)) !== connection.mirrorEtag
      )
        throw new SharingError(
          "The local PDF changed while syncing. Try again.",
          409,
        );
      before?.();
      writeJson(
        connectionPath(topic, slug),
        connectionSchema.parse(connection),
      );
    }),
  );
}

export function assertCurrentConnection(
  topic: string,
  slug: string,
  capability: ProfileCapability,
  expected: Connection,
): void {
  const current = readConnection(topic, slug);
  if (
    !getPaper(topic, slug) ||
    !current ||
    current.token !== expected.token ||
    current.participantId !== expected.participantId ||
    current.username !== capability.username ||
    current.generation !== capability.generation
  )
    throw new SharingError("This collaboration was removed or replaced.", 403);
}

export function publicationIds(topic: string, slug: string): string[] {
  const file = path.join(
    companionDir(topic, slug),
    "collaboration",
    "publications.json",
  );
  if (!fs.existsSync(file)) return [];
  return z
    .array(idSchema)
    .max(100)
    .parse(JSON.parse(fs.readFileSync(file, "utf8")));
}

export function rememberPublication(
  topic: string,
  slug: string,
  id: string,
): void {
  const ids = publicationIds(topic, slug);
  if (!ids.includes(id))
    writeJson(
      path.join(
        companionDir(topic, slug),
        "collaboration",
        "publications.json",
      ),
      [...ids, id],
    );
}

export function eraseSharingConnections(username: string): void {
  visitPaperCompanions(({ directory }) => {
    const folder = path.join(directory, "collaboration");
    if (!fs.existsSync(folder)) return;
    for (const name of fs.readdirSync(folder)) {
      if (/^artifacts-pending\.json(?:\.[a-f0-9-]{36}\.tmp)?$/.test(name)) {
        const file = path.join(folder, name);
        const stat = fs.lstatSync(file);
        if (!stat.isFile() || stat.size > 100 * 1024 * 1024)
          throw new SharingError(
            "Artifact recovery ownership is unavailable during profile erasure.",
            503,
          );
        const owner = z
          .object({
            username: slugSchema,
            generation: z.number().int().nonnegative(),
          })
          .parse(JSON.parse(fs.readFileSync(file, "utf8")));
        if (owner.username === username) fs.unlinkSync(file);
        continue;
      }
      if (
        name !== "connection.json" &&
        !/^connection\.json\.[a-f0-9-]{36}\.tmp$/.test(name)
      )
        continue;
      const file = path.join(folder, name);
      const binding = connectionSchema.parse(
        JSON.parse(fs.readFileSync(file, "utf8")),
      );
      if (binding.username === username) fs.unlinkSync(file);
    }
    syncDirectory(folder);
  });
}

export function forgetPublication(
  topic: string,
  slug: string,
  id: string,
): void {
  writeJson(
    path.join(companionDir(topic, slug), "collaboration", "publications.json"),
    publicationIds(topic, slug).filter((value) => value !== id),
  );
}

export function disconnect(
  topic: string,
  slug: string,
  capability: ProfileCapability,
  connection: Connection,
): void {
  withProfileFiles(new PapernookIdentityStore(dataRoot()), capability, () =>
    withPaperMutation(slug, () => {
      assertCurrentConnection(topic, slug, capability, connection);
      fs.unlinkSync(connectionPath(topic, slug));
      syncDirectory(path.dirname(connectionPath(topic, slug)));
    }),
  );
}

export function connectionSyncStatus(topic: string, slug: string) {
  const file = path.join(
    companionDir(topic, slug),
    "collaboration",
    "sync-status.json",
  );
  return fs.existsSync(file)
    ? sharingStatusSchema.parse(JSON.parse(fs.readFileSync(file, "utf8")))
    : null;
}

export function setConnectionSyncStatus(
  topic: string,
  slug: string,
  capability: ProfileCapability,
  connection: Connection,
  error: string | null,
): void {
  withProfileFiles(new PapernookIdentityStore(dataRoot()), capability, () =>
    withPaperMutation(slug, () => {
      assertCurrentConnection(topic, slug, capability, connection);
      writeJson(
        path.join(
          companionDir(topic, slug),
          "collaboration",
          "sync-status.json",
        ),
        { error, at: new Date().toISOString() },
      );
    }),
  );
}

import fs from "node:fs";
import path from "node:path";
import { syncDirectory } from "thesidedoor-core/storage";
import { pdfEtag } from "../library/pdf/file";
import { withShareFiles, getShare, type PaperShare } from "../library/shares";
import { validateAssets, sourceThreads, packageOwnerThread } from "./bundle";
import {
  collaborationDir,
  writeJson,
  type Participant,
  ownerActorId,
} from "./storage";
import type { Chat } from "../library/chats";
import {
  publishedThreadSchema,
  type PublishedThread,
  SharingError,
  idSchema,
  sharingStatusSchema,
} from "./schema";

export function readPublishedThreads(share: PaperShare): PublishedThread[] {
  const directory = path.join(collaborationDir(share), "threads");
  if (!fs.existsSync(directory)) return [];
  return fs
    .readdirSync(directory)
    .filter((name) => /^[a-f0-9]{16}-[a-f0-9]{16}\.json$/.test(name))
    .map((name) =>
      publishedThreadSchema.parse(
        JSON.parse(fs.readFileSync(path.join(directory, name), "utf8")),
      ),
    );
}

export function unpublishThread(
  share: PaperShare,
  participant: Pick<Participant, "id">,
  id: string,
): void {
  idSchema.parse(id);
  const file = path.join(
    collaborationDir(share),
    "threads",
    `${participant.id}-${id}.json`,
  );
  withShareFiles(share, () => {
    if (fs.existsSync(file)) {
      fs.unlinkSync(file);
      syncDirectory(path.dirname(file));
    }
  });
}

export function collaborationThreads(share: PaperShare): PublishedThread[] {
  return withShareFiles(share, () => readPublishedThreads(share));
}

/** The approved actor owns this namespace. Names in a submitted chat have no authority. */
export function publicationRevision(
  value: Pick<PublishedThread, "chat" | "assets">,
  actorId: string,
): string {
  const chat = {
    ...value.chat,
    header: { ...value.chat.header, username: actorId },
  };
  return pdfEtag(Buffer.from(JSON.stringify({ chat, assets: value.assets })));
}

export function publishThread(
  share: PaperShare,
  participant: Pick<Participant, "id" | "name">,
  value: Pick<PublishedThread, "chat" | "assets">,
  expected: string | null,
): PublishedThread {
  validateAssets(value);
  const chat = {
    ...value.chat,
    header: { ...value.chat.header, username: participant.id },
  };
  const revision = publicationRevision(value, participant.id);
  const published: PublishedThread = {
    id: chat.header.id,
    actorId: participant.id,
    author: participant.name,
    revision,
    chat,
    assets: value.assets,
  };
  const file = path.join(
    collaborationDir(share),
    "threads",
    `${participant.id}-${published.id}.json`,
  );
  const current = fs.existsSync(file)
    ? publishedThreadSchema.parse(JSON.parse(fs.readFileSync(file, "utf8")))
    : null;
  if (current?.revision === revision) return current;
  if ((current?.revision ?? null) !== expected)
    throw new SharingError(
      "This shared conversation changed elsewhere. Refresh before publishing.",
      409,
    );
  if (!current && readPublishedThreads(share).length >= 100)
    throw new SharingError(
      "This collaboration has reached its conversation limit.",
      413,
    );
  const total = readPublishedThreads(share)
    .filter(
      (thread) =>
        thread.actorId !== participant.id || thread.id !== published.id,
    )
    .reduce(
      (bytes, thread) => bytes + Buffer.byteLength(JSON.stringify(thread)),
      0,
    );
  if (total + Buffer.byteLength(JSON.stringify(published)) > 32 * 1024 * 1024)
    throw new SharingError(
      "This collaboration has reached its 32 MB conversation limit.",
      413,
    );
  withShareFiles(share, () => writeJson(file, published));
  return published;
}

export function publishOwnerSnapshot(share: PaperShare, chat: Chat): void {
  const thread = packageOwnerThread(share, chat);
  const existing = readPublishedThreads(share).find(
    (entry) => entry.actorId === thread.actorId && entry.id === thread.id,
  );
  publishThread(
    share,
    { id: thread.actorId, name: thread.author },
    thread,
    existing?.revision ?? null,
  );
}

export function sharingSyncStatus(share: PaperShare) {
  const file = path.join(collaborationDir(share), "sync-status.json");
  return fs.existsSync(file)
    ? sharingStatusSchema.parse(JSON.parse(fs.readFileSync(file, "utf8")))
    : null;
}

export function synchronizeOwnerThreads(share: PaperShare): void {
  // Refresh after acquiring authority so queued work follows current selections.
  const latest = withShareFiles(share, () =>
    getShare(share.topic, share.slug, share.id),
  );
  if (!latest) throw new SharingError("Unknown collaboration.", 404);
  share = latest;
  try {
    const desired = sourceThreads(share, true);
    const actorId = ownerActorId(share);
    const existing = readPublishedThreads(share);
    for (const thread of desired) {
      const previous = existing.find(
        (entry) => entry.actorId === actorId && entry.id === thread.id,
      );
      publishThread(
        share,
        { id: actorId, name: thread.author },
        thread,
        previous?.revision ?? null,
      );
    }
    for (const thread of existing)
      if (
        thread.actorId === actorId &&
        !desired.some((entry) => entry.id === thread.id)
      )
        unpublishThread(share, { id: actorId }, thread.id);
    withShareFiles(share, () =>
      writeJson(path.join(collaborationDir(share), "sync-status.json"), {
        error: null,
        at: new Date().toISOString(),
      }),
    );
  } catch (error) {
    withShareFiles(share, () =>
      writeJson(path.join(collaborationDir(share), "sync-status.json"), {
        error:
          "A published conversation could not sync. Check the sharing limits or stop sharing that conversation.",
        at: new Date().toISOString(),
      }),
    );
    throw error;
  }
}

import { fetchPublicUrl } from "../capture/download";
import { readBoundedResponse } from "../capture/bounded-response";
import { MAX_BUNDLE_BYTES, SharingError } from "./schema";
import { withSharingTransfer } from "./storage";

export function parseShareUrl(raw: string): {
  url: URL;
  topic: string;
  slug: string;
  shareId: string;
} {
  let url: URL;
  try {
    url = new URL(raw);
  } catch {
    throw new SharingError("Enter a valid Papernook sharing link.");
  }
  const match =
    /^\/share\/([a-z0-9][a-z0-9-]{0,79})\/([a-z0-9][a-z0-9-]{0,79})\/([a-f0-9]{64})\/?$/.exec(
      url.pathname,
    );
  if (
    url.protocol !== "https:" ||
    url.username ||
    url.password ||
    url.search ||
    url.hash ||
    !match
  )
    throw new SharingError(
      "Use an HTTPS Papernook sharing link without credentials or extra parameters.",
    );
  return { url, topic: match[1], slug: match[2], shareId: match[3] };
}

export async function exchange(
  raw: string,
  body: unknown,
  token?: string,
  authorize?: () => void,
): Promise<unknown> {
  return withSharingTransfer(
    () => exchangeRequest(raw, body, token, authorize),
    "outgoing",
  );
}

async function exchangeRequest(
  raw: string,
  body: unknown,
  token?: string,
  authorize?: () => void,
): Promise<unknown> {
  const { url, topic, slug, shareId } = parseShareUrl(raw);
  url.pathname = `/api/v1/shares/${topic}/${slug}/${shareId}/exchange`;
  const allowlist = (process.env.PAPERNOOK_SHARING_TRUSTED_ORIGINS ?? "")
    .split(",")
    .map((origin) => origin.trim())
    .filter(Boolean);
  try {
    const fetched = await fetchPublicUrl(
      url.toString(),
      AbortSignal.timeout(60_000),
      {
        body: JSON.stringify(body),
        token,
        authorize,
        trustedOrigin: allowlist.includes(url.origin) ? url.origin : undefined,
      },
    );
    const bytes = await readBoundedResponse(
      fetched.response,
      MAX_BUNDLE_BYTES,
      fetched.close,
    );
    let value: unknown;
    try {
      value = JSON.parse(bytes.toString("utf8"));
    } catch {
      throw new SharingError(
        "The sharing server returned an invalid response.",
        502,
      );
    }
    if (!fetched.response.ok) {
      const message =
        fetched.response.status === 403
          ? "The sharing server denied this operation. Check your approval status and whether the annotation belongs to another contributor."
          : fetched.response.status === 404
            ? "The shared paper is no longer available."
            : fetched.response.status === 409 || fetched.response.status === 412
              ? "The shared paper changed elsewhere. Reload before saving."
              : fetched.response.status === 429
                ? "The sharing server is busy. Try again later."
                : fetched.response.status === 413
                  ? "This reading or conversation exceeds a sharing limit. Reduce its size or stop sharing the oversized conversation."
                  : "The sharing server rejected the request.";
      throw new SharingError(
        message,
        fetched.response.status >= 400 && fetched.response.status < 500
          ? fetched.response.status
          : 502,
      );
    }
    return value;
  } catch (error) {
    if (error instanceof SharingError) throw error;
    throw new SharingError(
      "Could not reach the sharing server securely. Check HTTPS, connectivity, and the administrator's trusted-origin settings.",
      502,
    );
  }
}

import { runTaskLoop } from "thesidedoor-core/runtime/task-loop";
import { z } from "zod";
import { listPapers, companionDir } from "../library/papers";
import { listShares } from "../library/shares";
import { listProfiles } from "../auth/users";
import { readChat } from "../library/chats";
import { dataRoot } from "../data-dir";
import { PapernookIdentityStore } from "../auth/identity-store";
import { withProfileFiles } from "../auth/profile-capability";
import { updateMirror, connectionExchange } from "./gateway";
import { readVersionedPdfFile } from "../library/pdf/file";
import { base64Schema, idSchema, revisionSchema, SharingError } from "./schema";
import { packageConversation } from "./bundle";
import {
  publicationIds,
  readConnection,
  withConnection,
  forgetPublication,
  withCollaboration,
  setConnectionSyncStatus,
} from "./storage";
import { synchronizeOwnerThreads, publicationRevision } from "./threads";
import { artifactVersionsSchema } from "./artifacts/schema";
import { syncConnectedArtifacts } from "./artifacts/gateway";

const changesSchema = z
  .object({
    etag: revisionSchema,
    artifacts: artifactVersionsSchema,
    threads: z
      .array(
        z
          .object({ id: idSchema, actorId: idSchema, revision: revisionSchema })
          .strict(),
      )
      .max(100),
  })
  .strict();
const pdfSchema = z
  .object({ etag: revisionSchema, pdf: base64Schema })
  .strict();

interface Worker {
  controller: AbortController;
  completion: Promise<void>;
  directory: string;
}
const runtime = globalThis as typeof globalThis & {
  papernookSharingWorker?: Worker;
};

export async function syncConnectedPaper(
  topic: string,
  slug: string,
): Promise<void> {
  const binding = readConnection(topic, slug);
  if (!binding) return;
  const capability = {
    username: binding.username,
    generation: binding.generation,
  };
  await withConnection(topic, slug, capability, async (connection) => {
    try {
      const changes = changesSchema.parse(
        await connectionExchange(topic, slug, capability, connection, {
          action: "changes",
        }),
      );
      const local = await readVersionedPdfFile(topic, slug);
      if (
        !local ||
        (local.etag !== connection.mirrorEtag && local.etag !== changes.etag)
      )
        throw new SharingError(
          "The local PDF changed outside collaboration. Preserve that copy before reconnecting.",
          409,
        );
      if (local.etag !== changes.etag) {
        const pdf = pdfSchema.parse(
          await connectionExchange(topic, slug, capability, connection, {
            action: "pdf",
          }),
        );
        await updateMirror(
          topic,
          slug,
          connection,
          Buffer.from(pdf.pdf, "base64"),
          pdf.etag,
          capability,
        );
      }
      const identity = new PapernookIdentityStore(dataRoot());
      if (
        JSON.stringify(connection.artifacts?.source) !==
        JSON.stringify(changes.artifacts)
      )
        await syncConnectedArtifacts(
          topic,
          slug,
          capability,
          connection,
          changes.artifacts,
        );
      for (const id of publicationIds(topic, slug)) {
        const packaged = withProfileFiles(identity, capability, () => {
          const chat = readChat(topic, slug, capability.username, id);
          return chat
            ? packageConversation(chat, companionDir(topic, slug))
            : null;
        });
        if (!packaged) {
          await connectionExchange(topic, slug, capability, connection, {
            action: "unpublish",
            id,
          });
          withProfileFiles(identity, capability, () =>
            forgetPublication(topic, slug, id),
          );
          continue;
        }
        const current = changes.threads.find(
          (thread) =>
            thread.actorId === connection.participantId && thread.id === id,
        );
        if (
          current?.revision ===
          publicationRevision(packaged, connection.participantId)
        )
          continue;
        await connectionExchange(topic, slug, capability, connection, {
          action: "publish",
          ...packaged,
          expected: current?.revision ?? null,
        });
      }
      setConnectionSyncStatus(topic, slug, capability, connection, null);
    } catch (error) {
      setConnectionSyncStatus(
        topic,
        slug,
        capability,
        connection,
        "A paper, canvas, exercise or published conversation could not sync. Check access, local changes, and sharing limits.",
      );
      throw error;
    }
  });
}

export function startSharingWorker(): void {
  if (process.env.NEXT_PHASE === "phase-production-build") return;
  const existing = runtime.papernookSharingWorker;
  if (existing) {
    if (existing.directory !== dataRoot())
      throw new Error("Sharing worker is running for another data directory.");
    return;
  }
  const controller = new AbortController();
  const worker: Worker = {
    controller,
    completion: Promise.resolve(),
    directory: dataRoot(),
  };
  runtime.papernookSharingWorker = worker;
  worker.completion = runTaskLoop({
    intervalMs: 30_000,
    signal: controller.signal,
    task: async (signal) => {
      const profiles = listProfiles();
      for (const paper of listPapers()) {
        if (signal.aborted) break;
        if (!paper.topic) continue;
        if (!readConnection(paper.topic, paper.slug)) {
          for (const profile of profiles)
            for (const share of listShares(
              paper.topic,
              paper.slug,
              profile.username,
            ).filter(
              (entry) => entry.mode === "collaborate" && !entry.revoked,
            )) {
              if (signal.aborted) break;
              try {
                await withCollaboration(share, async () =>
                  synchronizeOwnerThreads(share),
                );
              } catch {
                console.error(
                  "papernook sharing: an owner publication could not sync; open its collaboration panel for details",
                );
              }
            }
          continue;
        }
        try {
          await syncConnectedPaper(paper.topic, paper.slug);
        } catch {
          console.error(
            "papernook sharing: a connected paper could not sync; open its collaboration panel for details",
          );
        }
      }
    },
    onError: () => {
      console.error("papernook sharing: storage unavailable; retry scheduled");
    },
  }).catch(() =>
    console.error("papernook sharing: worker stopped unexpectedly"),
  );
}

import { NextResponse, type NextRequest } from "next/server";
import { SESSION_COOKIE, verifySessionToken } from "@/lib/auth/session";
import { crossSiteMutation } from "@/lib/auth/request-security";
import { clientIp } from "@/lib/auth/request-security";
import { consumeRequestLimit, publicRequestLimit } from "@/lib/auth/rate-limit";
export { publicRequestLimit } from "@/lib/auth/rate-limit";

/**
 * Gate everything behind a profile session except: the login/picker page, the
 * session + profile APIs it needs, static assets, and /add (which carries its
 * own per-profile capture token and is validated in the route).
 */

const PUBLIC_PATHS = new Set([
  "/login",
  "/api/v1/session",
  "/api/v1/profiles",
  "/api/v1/health",
]);

function contentSecurityPolicy(nonce: string): string {
  return [
    "default-src 'self'",
    "base-uri 'self'",
    "connect-src 'self' ws: wss:",
    "font-src 'self' data:",
    "form-action 'self'",
    "frame-ancestors 'none'",
    "img-src 'self' data: blob: https:",
    "media-src 'self' blob:",
    "object-src 'none'",
    `script-src 'self' 'nonce-${nonce}' 'strict-dynamic'${
      process.env.NODE_ENV === "development" ? " 'unsafe-eval'" : ""
    }`,
    "style-src 'self' 'unsafe-inline'",
    "worker-src 'self' blob:",
  ].join("; ");
}

function secureResponse(response: NextResponse, csp: string): NextResponse {
  response.headers.set("Content-Security-Policy", csp);
  return response;
}

function continueRequest(request: NextRequest, csp: string): NextResponse {
  const requestHeaders = new Headers(request.headers);
  const nonce = /'nonce-([^']+)'/.exec(csp)?.[1];
  if (nonce) requestHeaders.set("x-nonce", nonce);
  requestHeaders.set("Content-Security-Policy", csp);
  return secureResponse(
    NextResponse.next({ request: { headers: requestHeaders } }),
    csp,
  );
}

export const config = {
  matcher: [
    "/((?!api/v1/shares/[^/]+/[^/]+/[^/]+/exchange/?$|_next/|avatars/|vendor/|offline/|favicon\\.ico|icon\\.svg|apple-icon\\.png|logo\\.(?:svg|png)|manifest\\.webmanifest|sw\\.js).*)",
  ],
};

export async function proxy(request: NextRequest): Promise<NextResponse> {
  const nonce = Buffer.from(crypto.randomUUID()).toString("base64");
  const csp = contentSecurityPolicy(nonce);
  const { pathname } = request.nextUrl;
  if (
    process.env.RESEARCH_LOCAL_MODE === "1" &&
    (pathname === "/" ||
      pathname === "/workspace" ||
      pathname.startsWith("/workspace/") ||
      pathname.startsWith("/api/research"))
  ) {
    const host = request.headers.get("host") || "";
    if (!/^(localhost|127\.0\.0\.1|\[::1\])(?::\d+)?$/i.test(host)) {
      return secureResponse(
        NextResponse.json(
          { error: "研究工作区仅允许本机访问。" },
          { status: 403 },
        ),
        csp,
      );
    }
    if (
      !["GET", "HEAD", "OPTIONS"].includes(request.method) &&
      crossSiteMutation(request)
    ) {
      return secureResponse(
        NextResponse.json({ error: "不允许跨站写入。" }, { status: 403 }),
        csp,
      );
    }
    return continueRequest(request, csp);
  }
  const wait = consumeRequestLimit(
    `request:${clientIp(request)}`,
    publicRequestLimit(),
    60_000,
  );
  if (wait > 0) {
    return secureResponse(
      NextResponse.json(
        { error: "Too many requests." },
        {
          status: 429,
          headers: { "Retry-After": String(Math.ceil(wait / 1000)) },
        },
      ),
      csp,
    );
  }
  if (
    !["GET", "HEAD", "OPTIONS"].includes(request.method) &&
    pathname !== "/add" &&
    pathname !== "/add/confirm" &&
    pathname !== "/add/status" &&
    crossSiteMutation(request)
  ) {
    return secureResponse(
      NextResponse.json(
        { error: "Cross-site request rejected." },
        { status: 403 },
      ),
      csp,
    );
  }
  if (
    PUBLIC_PATHS.has(pathname) ||
    /^\/api\/v1\/access\/[a-z-]+$/.test(pathname) ||
    pathname === "/add" ||
    pathname === "/add/confirm" ||
    pathname === "/add/status" ||
    // Invite links must reach the gate route itself to open it.
    pathname === "/invite" ||
    // A share link's unguessable id IS its credential: the point is handing a
    // single reading to someone who has no account here. Mutations under
    // /api/v1/shares stay authenticated inside the route.
    pathname === "/share" ||
    pathname.startsWith("/share/") ||
    pathname === "/api/v1/shares" ||
    pathname.startsWith("/api/v1/shares/")
  ) {
    const response = continueRequest(request, csp);
    response.headers.set("Cache-Control", "private, no-store");
    response.headers.set("Referrer-Policy", "no-referrer");
    response.headers.set("X-Robots-Tag", "noindex, nofollow");
    return response;
  }
  const token = request.cookies.get(SESSION_COOKIE)?.value;
  if (token && (await verifySessionToken(token))) {
    return continueRequest(request, csp);
  }
  if (pathname.startsWith("/api/")) {
    return secureResponse(
      NextResponse.json({ error: "Not signed in." }, { status: 401 }),
      csp,
    );
  }
  const login = request.nextUrl.clone();
  login.pathname = "/login";
  login.search = "";
  return secureResponse(NextResponse.redirect(login), csp);
}

