    } finally {
      await page.request.delete(`/api/v1${conversationPath}`);
    }
  });

  test("downloaded paper and chat survive a complete Chromium browser restart", async ({
    browserName,
    baseURL,
  }) => {
    test.skip(
      browserName !== "chromium",
