interface WireChoice {
  index?: number;
  message?: { content?: string | null; tool_calls?: unknown[] };
  delta?: { content?: string; tool_calls?: unknown[] };
  finish_reason?: string | null;
}
function eventResponse(events: unknown[]): Response {
  return new Response(
    events.map((event) => "data: " + JSON.stringify(event) + "\n\n").join("") +
      "data: [DONE]\n\n",
    { headers: { "content-type": "text/event-stream" } },
  );
}
function responseBody(value: unknown) {
  const result = value as {
    status?: string;
    output_text?: string;
    error?: unknown;
  };
  return {
    id: "response1",
    status: result.status ?? "completed",
    error: result.error,
    ...(result.status === "incomplete"
      ? { incomplete_details: { reason: "max_output_tokens" } }
      : {}),
    output: [
      {
        type: "message",
        id: "message1",
        role: "assistant",
        status: "completed",
        content: [
          {
            type: "output_text",
            text: result.output_text ?? "",
            annotations: [],
          },
        ],
      },
    ],
    usage: { input_tokens: 10, output_tokens: 5 },
  };
}
function mockOpenAI(
  responseCalls: ApiCall[],
  chatCalls: ApiCall[],
  chatResponses: unknown[] = [],
  responseEvents: Array<{
    type: string;
    delta?: string;
    response?: unknown;
  }> = [{ type: "response.output_text.delta", delta: "streamed answer" }],
  responseResult: unknown = { output_text: "openai answer" },
): void {
  vi.stubGlobal(
    "fetch",
    async (input: RequestInfo | URL, init?: RequestInit) => {
      const request = new Request(input, init);
      const url = new URL(request.url);
      if (url.pathname === "/search") {
        webCalls.push({
          name: "web_search",
          argumentsValue: { query: url.searchParams.get("q") },
        });
        if (searchFailure) return new Response("", { status: 503 });
        return Response.json({
          results: [
            {
              title: "EDGS",
              url: "https://example.test/repo",
              content: "Source",
            },
          ],
        });
      }
      const body = (await request.json()) as ApiCall;
      if (request.url.endsWith("/responses")) {
        responseCalls.push(body);
        if (!body.stream) return Response.json(responseBody(responseResult));
        const events: unknown[] = [...responseEvents];
        if (
          !responseEvents.some((event) =>
            ["error", "response.failed", "response.incomplete"].includes(
              event.type,
            ),
          )
        ) {
          events.push({
            type: "response.completed",
            response: responseBody({
              output_text: responseEvents
                .map((event) => event.delta ?? "")
                .join(""),
            }),
          });
        }
        return eventResponse(events);
      }
      if (!request.url.endsWith("/chat/completions"))
        throw new Error("Unexpected provider URL");
      chatCalls.push(body);
      const value = chatResponses.shift();
      if (!value || typeof value !== "object")
        throw new Error("No mocked chat response remains.");
      if (Symbol.asyncIterator in value) {
        const chunks: unknown[] = [];
        let hasTools = false;
        for await (const chunk of value as AsyncIterable<{
          choices: WireChoice[];
        }>) {
          hasTools ||= chunk.choices.some((choice) =>
            Boolean(choice.delta?.tool_calls?.length),
          );
          chunks.push({
            id: "chat1",
            object: "chat.completion.chunk",
            choices: chunk.choices.map((choice) => ({ index: 0, ...choice })),
          });
        }
        chunks.push({
          id: "chat1",
          object: "chat.completion.chunk",
          choices: [
            {
              index: 0,
              delta: {},
              finish_reason: hasTools ? "tool_calls" : "stop",
            },
          ],
        });
        return eventResponse(chunks);
      }
      const completion = value as { choices: WireChoice[] };
      return Response.json({
        id: "chat1",
        object: "chat.completion",
        choices: completion.choices.map((choice) => ({
          index: 0,
          finish_reason: choice.message?.tool_calls?.length
            ? "tool_calls"
            : "stop",
          ...choice,
        })),
        usage: { prompt_tokens: 10, completion_tokens: 5 },
      });
    },
  );
}

describe("API provider web access", () => {
  it.each(["gpt-6.1-sol", "gpt-6-astra", "gpt-6-sol", "gpt-6-luna"])(
    "uses %s with Responses web search without storing the response",
    async (model) => {
      await configureTestAgent(
        { provider: "openai", model },
        { apiKey: "test-openai-key" },
      );
      const responseCalls: ApiCall[] = [];
      mockOpenAI(responseCalls, []);
      const { openaiProvider } = await import("@/lib/agent/api");

      await expect(
        openaiProvider.execute({
          system: "Ground answers in sources.",
          prompt: "Find the implementation repository.",
          allowWeb: true,
        }),
      ).resolves.toBe("openai answer");

      expect(responseCalls).toHaveLength(1);
      expect(responseCalls[0].store).toBe(false);
      expect(responseCalls[0].model).toBe(model);
      expect(responseCalls[0].tools).toEqual([{ type: "web_search" }]);

      const chunks: string[] = [];
      for await (const chunk of openaiProvider.stream({
        system: "Ground answers in sources.",
        prompt: "Find the implementation repository.",
        allowWeb: true,
      })) {
        chunks.push(chunk);
      }
      expect(chunks.join("")).toBe("streamed answer");
      expect(responseCalls[1].stream).toBe(true);
      expect(responseCalls[1].model).toBe(model);
      expect(responseCalls[1].tools).toEqual([{ type: "web_search" }]);
    },
  );

  it("runs local-model web tools until the model returns an answer", async () => {
    const toolCalls = webCalls;
    const chatCalls: ApiCall[] = [];
    mockOpenAI([], chatCalls, [
      {
        choices: [
          {
            message: {
              content: null,
              tool_calls: [
                {
                  id: "search-1",
                  type: "function",
                  function: {
                    name: "web_search",
                    arguments: '{"query":"EDGS GitHub"}',
                  },
                },
              ],
            },
          },
        ],
      },
      { choices: [{ message: { content: "Verified repository code." } }] },
    ]);
    await configureTestAgent({ provider: "ollama", model: "qwen3:4b" });
    const { ollamaProvider } = await import("@/lib/agent/api");

    await expect(
      ollamaProvider.execute({
        system: "",
        prompt: "Find the repository.",
        allowWeb: true,
      }),
    ).resolves.toBe("Verified repository code.");

    expect(toolCalls).toEqual([
      { name: "web_search", argumentsValue: { query: "EDGS GitHub" } },
    ]);
    expect(chatCalls).toHaveLength(2);
    expect(chatCalls[1].messages?.map((message) => message.role)).toEqual([
      "user",
      "assistant",
      "tool",
    ]);
  });

  it("does not send web tools when a local-model turn disables web access", async () => {
    const chatCalls: ApiCall[] = [];
    mockOpenAI([], chatCalls, [
      { choices: [{ message: { content: "Offline answer." } }] },
    ]);
    await configureTestAgent({ provider: "ollama", model: "qwen3:4b" });
    const { ollamaProvider } = await import("@/lib/agent/api");

    await expect(
      ollamaProvider.execute({
        system: "",
        prompt: "Answer.",
        allowWeb: false,
      }),
    ).resolves.toBe("Offline answer.");

    expect(chatCalls[0].tools).toBeUndefined();
  });

  it("returns a visible warning when a local web tool fails", async () => {
    searchFailure = true;
    const chatCalls: ApiCall[] = [];
    mockOpenAI([], chatCalls, [
      {
        choices: [
          {
            message: {
              content: null,
              tool_calls: [
                {
                  id: "search-1",
                  type: "function",
                  function: {
                    name: "web_search",
                    arguments: '{"query":"EDGS"}',
                  },
                },
              ],
            },
          },
        ],
      },
      {
        choices: [
          { message: { content: "I could not verify the repository." } },
        ],
      },
    ]);
    await configureTestAgent({ provider: "ollama", model: "qwen3:4b" });
    const { ollamaProvider } = await import("@/lib/agent/api");

    const answer = await ollamaProvider.execute({
      system: "",
      prompt: "Find the repository.",
      allowWeb: true,
    });

    expect(answer).toContain("I could not verify the repository.");
    expect(answer).toContain(
      "Web access warning: web_search failed: web_search failed with status 503",
    );
    expect(chatCalls[1].messages?.at(-1)?.content).toContain(
      "web_search failed with status 503",
    );
  });

  it("streams local answers after accumulating streamed tool-call arguments", async () => {
    const toolCalls = webCalls;
    const firstStream = {
      async *[Symbol.asyncIterator]() {
        yield {
          choices: [
            {
              delta: {
                tool_calls: [
                  {
                    index: 0,
                    id: "search-1",
                    type: "function",
                    function: { name: "web_search", arguments: '{"query":' },
                  },
                ],
              },
            },
          ],
        };
        yield {
          choices: [
            {
              delta: {
                tool_calls: [{ index: 0, function: { arguments: '"EDGS"}' } }],
              },
            },
          ],
        };
      },
    };
    const answerStream = {
      async *[Symbol.asyncIterator]() {
        yield { choices: [{ delta: { content: "Verified " } }] };
        yield { choices: [{ delta: { content: "repository." } }] };
      },
    };
    const chatCalls: ApiCall[] = [];
    mockOpenAI([], chatCalls, [firstStream, answerStream]);
    await configureTestAgent({ provider: "ollama", model: "qwen3:4b" });
    const { ollamaProvider } = await import("@/lib/agent/api");

    const chunks: string[] = [];
    for await (const chunk of ollamaProvider.stream({
      system: "",
      prompt: "Find the repository.",
      allowWeb: true,
    })) {
      chunks.push(chunk);
    }

    expect(chunks).toEqual(["Verified ", "repository."]);
    expect(toolCalls).toEqual([
      { name: "web_search", argumentsValue: { query: "EDGS" } },
    ]);
  });

  it("forces a tool-free final answer after the local tool-round limit", async () => {
    const toolResponses = Array.from({ length: 6 }, (_, index) => ({
      choices: [
        {
          message: {
            content: null,
            tool_calls: [
              {
                id: `search-${index}`,
                type: "function",
                function: { name: "web_search", arguments: '{"query":"EDGS"}' },
              },
            ],
          },
        },
      ],
    }));
    const chatCalls: ApiCall[] = [];
    mockOpenAI([], chatCalls, [
      ...toolResponses,
      { choices: [{ message: { content: "Final answer." } }] },
    ]);
    await configureTestAgent({ provider: "ollama", model: "qwen3:4b" });
    const { ollamaProvider } = await import("@/lib/agent/api");

    const answer = await ollamaProvider.execute({
      system: "",
      prompt: "Find the repository.",
      allowWeb: true,
    });

    expect(chatCalls).toHaveLength(7);
    expect(chatCalls[6].tools).toBeUndefined();
    expect(answer).toContain("Final answer.");
    expect(answer).toContain("web tool limit reached (6 rounds)");
  });

  it("applies JSON response formatting only to the tool-free final request", async () => {
    const chatCalls: ApiCall[] = [];
    mockOpenAI([], chatCalls, [
      { choices: [{ message: { content: "draft" } }] },
      { choices: [{ message: { content: '{"result":"final"}' } }] },
    ]);
    await configureTestAgent({ provider: "ollama", model: "qwen3:4b" });
    const { ollamaProvider } = await import("@/lib/agent/api");

    await expect(
      ollamaProvider.execute({
        system: "Return JSON.",
        prompt: "Classify this paper.",
        allowWeb: true,
        responseFormat: "json_object",
      }),
    ).resolves.toBe('{"result":"final"}');

    expect(chatCalls[0].response_format).toBeUndefined();
    expect(chatCalls[1].response_format).toEqual({ type: "json_object" });
    expect(chatCalls[1].tools).toBeUndefined();
  });

  it("surfaces OpenAI streaming failures", async () => {
    mockOpenAI(
      [],
      [],
      [],
      [
        {
          type: "response.failed",
          response: { error: { message: "upstream unavailable" } },
        },
      ],
    );
    const { openaiProvider } = await import("@/lib/agent/api");

    const consume = async () => {
      for await (const chunk of openaiProvider.stream({
        system: "",
        prompt: "Search.",
        allowWeb: true,
      })) {
        void chunk;
      }
    };

    await expect(consume()).rejects.toThrow("provider failed");
  });

  it("surfaces incomplete non-streaming OpenAI responses", async () => {
    mockOpenAI([], [], [], undefined, {
      status: "incomplete",
      output_text: "partial answer",
    });
    const { openaiProvider } = await import("@/lib/agent/api");

    await expect(
      openaiProvider.execute({
        system: "",
        prompt: "Search.",
        allowWeb: true,
      }),
    ).rejects.toThrow("openai: response incomplete");
  });
});

import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

let tmpDir: string;
let syncDir: string;
let runtimeHome: string;

beforeEach(() => {
  tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), "papernook-credentials-"));
  syncDir = path.join(tmpDir, "sync");
  runtimeHome = path.join(tmpDir, "home");
  fs.mkdirSync(path.join(syncDir, "requests"), { recursive: true });
  fs.mkdirSync(path.join(syncDir, "responses"), { recursive: true });
  fs.writeFileSync(path.join(syncDir, "supports-claude"), "");
  fs.writeFileSync(path.join(syncDir, "supports-codex"), "");
  vi.stubEnv("PAPERNOOK_CREDENTIAL_SYNC_DIR", syncDir);
  vi.stubEnv("HOME", runtimeHome);
  vi.resetModules();
});

afterEach(() => {
  vi.unstubAllEnvs();
  fs.rmSync(tmpDir, { recursive: true, force: true });
});

async function answerSync(
  provider: "claude-code" | "codex",
  snapshot: object | null,
): Promise<void> {
  const requests = path.join(syncDir, "requests");
  let request: string | undefined;
  for (let attempt = 0; attempt < 50 && !request; attempt += 1) {
    request = fs.readdirSync(requests)[0];
    if (!request) await new Promise((resolve) => setTimeout(resolve, 10));
  }
  if (!request) throw new Error("Credential reload did not request a sync.");
  const snapshotPath = path.join(
    syncDir,
    provider === "claude-code" ? "claude-credentials.json" : "codex-auth.json",
  );
  if (snapshot) fs.writeFileSync(snapshotPath, JSON.stringify(snapshot));
  else fs.rmSync(snapshotPath, { force: true });
  fs.writeFileSync(path.join(syncDir, "responses", request), "");
}

describe("CLI credential reload", () => {
  it("installs the sidecar snapshot atomically into the CLI home", async () => {
    const credentials = await import("@/lib/agent/credentials");
    const reload = credentials.reloadProviderCredentials("claude-code");
    await answerSync("claude-code", {
      claudeAiOauth: { accessToken: "new-token" },
    });
    await reload;

    const installed = fs.readFileSync(
      path.join(runtimeHome, ".claude", ".credentials.json"),
      "utf8",
    );
    expect(JSON.parse(installed)).toEqual({
      claudeAiOauth: { accessToken: "new-token" },
    });
  });

  it("refuses a host snapshot older than the rotated runtime token", async () => {
    // The host mount is read-only, so it never receives rotations. Restoring it
    // over a newer runtime file hands back a token the server already retired.
    const runtime = path.join(runtimeHome, ".claude", ".credentials.json");
    fs.mkdirSync(path.dirname(runtime), { recursive: true });
    const rotated = JSON.stringify({
      claudeAiOauth: { refreshToken: "rotated", refreshTokenExpiresAt: 2000 },
    });
    fs.writeFileSync(runtime, rotated);

    const credentials = await import("@/lib/agent/credentials");
    const reload = credentials.reloadProviderCredentials("claude-code");
    await answerSync("claude-code", {
      claudeAiOauth: { refreshToken: "retired", refreshTokenExpiresAt: 1000 },
    });

    expect(await reload).toBe("skipped");
    expect(fs.readFileSync(runtime, "utf8")).toBe(rotated);
  });

  it("refuses a Codex snapshot older than the rotated runtime token", async () => {
    const runtime = path.join(runtimeHome, ".codex", "auth.json");
    fs.mkdirSync(path.dirname(runtime), { recursive: true });
    const rotated = JSON.stringify({
      tokens: { refresh_token: "rotated" },
      last_refresh: "2026-08-20T00:00:00.000Z",
    });
    fs.writeFileSync(runtime, rotated);

    const credentials = await import("@/lib/agent/credentials");
    const reload = credentials.reloadProviderCredentials("codex");
    await answerSync("codex", {
      tokens: { refresh_token: "retired" },
      last_refresh: "2026-08-12T00:00:00.000Z",
    });

    expect(await reload).toBe("skipped");
    expect(fs.readFileSync(runtime, "utf8")).toBe(rotated);
  });

  it("reloads Codex into CODEX_HOME, the directory the CLI actually rotates", async () => {
    // codex.ts hands CODEX_HOME to the CLI as its config directory. If reload
    // wrote $HOME/.codex instead, a custom CODEX_HOME would split the file the
    // CLI rotates from the one reload refreshes, and neither would stay valid.
    const codexHome = path.join(tmpDir, "custom-codex");
    vi.stubEnv("CODEX_HOME", codexHome);
    const credentials = await import("@/lib/agent/credentials");
    const reload = credentials.reloadProviderCredentials("codex");
    await answerSync("codex", {
      tokens: { refresh_token: "fresh" },
      last_refresh: "2026-08-21T00:00:00.000Z",
    });

    expect(await reload).toBe("installed");
    expect(
      JSON.parse(fs.readFileSync(path.join(codexHome, "auth.json"), "utf8")),
    ).toMatchObject({ tokens: { refresh_token: "fresh" } });
  });

  it("removes runtime credentials when the host is logged out", async () => {
    const runtime = path.join(runtimeHome, ".claude", ".credentials.json");
    fs.mkdirSync(path.dirname(runtime), { recursive: true });
    fs.writeFileSync(runtime, '{"stale":true}');
    const credentials = await import("@/lib/agent/credentials");
    const reload = credentials.reloadProviderCredentials("claude-code");
    await answerSync("claude-code", null);
    await reload;

    expect(fs.existsSync(runtime)).toBe(false);
  });

  it("reloads Codex login into its CLI home", async () => {
    const credentials = await import("@/lib/agent/credentials");
    const reload = credentials.reloadProviderCredentials("codex");
    await answerSync("codex", {
      tokens: { access_token: "new-codex-token" },
    });
    await reload;

    const installed = fs.readFileSync(
      path.join(runtimeHome, ".codex", "auth.json"),
      "utf8",
    );
    expect(JSON.parse(installed)).toEqual({
      tokens: { access_token: "new-codex-token" },
    });
  });

  it("serializes different providers without treating one as the other", async () => {
    const credentials = await import("@/lib/agent/credentials");
    const claudeReload = credentials.reloadProviderCredentials("claude-code");
    const codexReload = credentials.reloadProviderCredentials("codex");

    await answerSync("claude-code", { claude: "fresh" });
    await claudeReload;
    await answerSync("codex", { codex: "fresh" });
    await codexReload;

    expect(
      JSON.parse(
        fs.readFileSync(
          path.join(runtimeHome, ".claude", ".credentials.json"),
          "utf8",
        ),
      ),
    ).toEqual({ claude: "fresh" });
    expect(
      JSON.parse(
        fs.readFileSync(path.join(runtimeHome, ".codex", "auth.json"), "utf8"),
      ),
    ).toEqual({ codex: "fresh" });
  });

  it("does not offer local credential reload for SSH providers", async () => {
    vi.stubEnv("CLAUDE_CODE_SSH_HOST", "agent-host");
    vi.resetModules();
    const { credentialReloadAvailable } =
      await import("@/lib/agent/credentials");

    expect(credentialReloadAvailable("claude-code")).toBe(false);
    expect(credentialReloadAvailable("anthropic")).toBe(false);
  });

  it("does not offer local credential reload for SSH Codex", async () => {
    vi.stubEnv("CODEX_SSH_HOST", "agent-host");
    vi.resetModules();
    const { credentialReloadAvailable } =
      await import("@/lib/agent/credentials");

    expect(credentialReloadAvailable("codex")).toBe(false);
  });
});

import {
  existsSync,
  mkdirSync,
  mkdtempSync,
  readFileSync,
  writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

/**
 * `codex exec -s read-only` blocks writes, not reads, and the turn it runs is
 * steered by paper text an attacker may control. Whatever the sandbox lets it
 * read, the app's secrets must not be sitting in its environment.
 */

const SECRETS = {
  WEBDAV_PASS: "the-webdav-password",
  SESSION_SECRET: "s".repeat(64),
  OPENAI_API_KEY: "sk-openai-secret",
  AWS_SECRET_ACCESS_KEY: "aws-secret",
};

beforeEach(() => {
  vi.resetModules();
  vi.stubEnv("PATH", "/usr/bin");
  vi.stubEnv("HOME", "/home/node");
  for (const [key, value] of Object.entries(SECRETS)) vi.stubEnv(key, value);
});

afterEach(() => {
  vi.unstubAllEnvs();
});

describe("CLI provider environment", () => {
  it("hands codex no app secret, only what it needs to run", async () => {
    vi.stubEnv("CODEX_HOME", "/home/node/.codex");
    vi.stubEnv("CODEX_SSH_HOST", "you@vps");
    vi.stubEnv("CODEX_INTERNAL_TOKEN", "a-future-secret");
    const { codexEnvironment } = await import("@/lib/agent/codex");

    const env = codexEnvironment();

    for (const key of Object.keys(SECRETS)) {
      expect(env[key], key).toBeUndefined();
    }
    // Named keys, not a CODEX_ prefix sweep: a variable added later is
    // absent by default rather than inherited because of how it is spelled.
    expect(env.CODEX_INTERNAL_TOKEN).toBeUndefined();
    // The app reads the SSH host to build the argv; the child never needs it.
    expect(env.CODEX_SSH_HOST).toBeUndefined();
    // Still runnable.
    expect(env.PATH).toBe("/usr/bin");
    expect(env.HOME).toBe("/home/node");
    expect(env.CODEX_HOME).toBe("/home/node/.codex");
  });

  it("hands claude-code its own credentials but no unrelated secret", async () => {
    vi.stubEnv("CLAUDE_CODE_OAUTH_TOKEN", "claude-oauth-token");
    vi.stubEnv("ANTHROPIC_API_KEY", "sk-ant-key");
    const { createClaudeInvocation } = await import("@/lib/agent/claude-code");

    const invocation = createClaudeInvocation();
    const env = invocation.env;
    invocation.release();

    expect(env.WEBDAV_PASS).toBeUndefined();
    expect(env.SESSION_SECRET).toBeUndefined();
    expect(env.OPENAI_API_KEY).toBeUndefined();
    // The provider's own auth must still reach it, or every turn fails.
    expect(env.CLAUDE_CODE_OAUTH_TOKEN).toBe("claude-oauth-token");
    expect(env.ANTHROPIC_API_KEY).toBe("sk-ant-key");
    expect(env.PATH).toBe("/usr/bin");
  });

  it("preserves the container's credential path for claude-code", async () => {
    // How production actually authenticates: docker-entrypoint.sh copies the
    // host credentials to /home/node/.claude/.credentials.json and the CLI
    // finds them through HOME. Stripping HOME would silently break every
    // chat with a "needs login" that looks like an expired token.
    vi.stubEnv("HOME", "/home/node");
    const { createClaudeInvocation } = await import("@/lib/agent/claude-code");

    const invocation = createClaudeInvocation();
    expect(invocation.env.HOME).toBe("/home/node");
    invocation.release();
  });

  it("seeds inline credentials onto the durable path without forwarding them", async () => {
    // The macOS-Docker path: the raw OAuth JSON arrives in the environment and
    // seeds the credentials file each invocation is copied from. It lands under
    // CLAUDE_HOME, which is a persistent volume in the container, so a rotation
    // outlives the container. The credential must not continue into the child.
    const home = mkdtempSync(join(tmpdir(), "papernook-claude-home-"));
    vi.stubEnv("CLAUDE_HOME", home);
    const seed = '{"claudeAiOauth":{"refreshTokenExpiresAt":1000}}';
    vi.stubEnv("CLAUDE_CODE_CREDENTIALS_JSON", seed);
    const { createClaudeInvocation } = await import("@/lib/agent/claude-code");

    const invocation = createClaudeInvocation();
    const env = invocation.env;
    invocation.release();

    expect(env.CLAUDE_CODE_CREDENTIALS_JSON).toBeUndefined();
    expect(Object.values(env)).not.toContain(seed);
    expect(
      readFileSync(join(home, ".claude", ".credentials.json"), "utf8"),
    ).toBe(seed);
  });

  it("keeps a rotated token instead of reseeding from the configured secret", async () => {
    // The CLI retires the previous refresh token when it rotates, so restoring
    // the frozen secret over a newer file hands back a dead credential.
    const home = mkdtempSync(join(tmpdir(), "papernook-claude-home-"));
    const credentials = join(home, ".claude", ".credentials.json");
    mkdirSync(dirname(credentials), { recursive: true });
    const rotated = '{"claudeAiOauth":{"refreshTokenExpiresAt":2000}}';
    writeFileSync(credentials, rotated);
    vi.stubEnv("CLAUDE_HOME", home);
    vi.stubEnv(
      "CLAUDE_CODE_CREDENTIALS_JSON",
      '{"claudeAiOauth":{"refreshTokenExpiresAt":1000}}',
    );
    const { createClaudeInvocation } = await import("@/lib/agent/claude-code");

    const invocation = createClaudeInvocation();
    invocation.release();

    expect(readFileSync(credentials, "utf8")).toBe(rotated);
  });
});

describe("claude-code invocation isolation", () => {
  function seedClaudeHome(credentials: string): string {
    const home = mkdtempSync(join(tmpdir(), "claude-home-"));
    const dir = join(home, ".claude");
    mkdirSync(dir, { recursive: true });
    writeFileSync(join(dir, ".credentials.json"), credentials);
    return home;
  }

  it("gives every invocation its own config dir", async () => {
    // The CLI rewrites its config on startup: two concurrent turns sharing a
    // config dir corrupt each other and exit 1 with an empty stderr.
    vi.stubEnv("CLAUDE_HOME", seedClaudeHome('{"token":"a"}'));
    const { createClaudeInvocation } = await import("@/lib/agent/claude-code");

    const first = createClaudeInvocation();
    const second = createClaudeInvocation();
    const dirs = [first.env.CLAUDE_CONFIG_DIR, second.env.CLAUDE_CONFIG_DIR];

    expect(dirs[0]).toBeTruthy();
    expect(dirs[0]).not.toBe(dirs[1]);
    // Seeded with the shared credentials, so the CLI authenticates.
    expect(
      readFileSync(join(dirs[0] as string, ".credentials.json"), "utf8"),
    ).toBe('{"token":"a"}');

    first.release();
    second.release();
    expect(existsSync(dirs[0] as string)).toBe(false);
  });

  it("finds the credentials under HOME when CLAUDE_HOME is unset", async () => {
    // Production: the entrypoint copies the host credentials to
    // $HOME/.claude/.credentials.json and leaves CLAUDE_HOME empty, so keying
    // isolation off CLAUDE_HOME alone would silently disable it there.
    const home = seedClaudeHome('{"token":"from-home"}');
    vi.stubEnv("HOME", home);
    const { createClaudeInvocation } = await import("@/lib/agent/claude-code");

    const invocation = createClaudeInvocation();
    const dir = invocation.env.CLAUDE_CONFIG_DIR as string;
    const seeded = readFileSync(join(dir, ".credentials.json"), "utf8");
    invocation.release();

    expect(seeded).toBe('{"token":"from-home"}');
  });

  it("drops the Anthropic API key when OAuth credentials are present", async () => {
    // Otherwise an expired OAuth session silently falls back to API-key
    // billing and fails with "Credit balance is too low" instead of an auth
    // error the reader can act on.
    vi.stubEnv("CLAUDE_HOME", seedClaudeHome('{"token":"a"}'));
    vi.stubEnv("ANTHROPIC_API_KEY", "sk-ant-key");
    vi.stubEnv("ANTHROPIC_AUTH_TOKEN", "auth-token");
    const { createClaudeInvocation } = await import("@/lib/agent/claude-code");

    const invocation = createClaudeInvocation();
    const env = invocation.env;
    invocation.release();

    expect(env.ANTHROPIC_API_KEY).toBeUndefined();
    expect(env.ANTHROPIC_AUTH_TOKEN).toBeUndefined();
  });

  it("writes a refreshed token back to the shared credentials", async () => {
    const home = seedClaudeHome('{"token":"old"}');
    vi.stubEnv("CLAUDE_HOME", home);
    const { createClaudeInvocation } = await import("@/lib/agent/claude-code");

    const invocation = createClaudeInvocation();
    // Stand in for the CLI refreshing the OAuth token mid-turn.
    writeFileSync(
      join(invocation.env.CLAUDE_CONFIG_DIR as string, ".credentials.json"),
      '{"token":"new"}',
    );
    invocation.release();

    expect(
      readFileSync(join(home, ".claude", ".credentials.json"), "utf8"),
    ).toBe('{"token":"new"}');
  });
});

