  expect(() =>
    withProfileFiles(store, capability, () => fs.readFileSync(file, "utf8")),
  ).toThrow("profile was replaced");
  expect(() =>
    withProfileFiles(store, capability, () => fs.unlinkSync(file)),
  ).toThrow("profile was replaced");
});

