  const identity = new PapernookIdentityStore(directory);
  await identity.initializeCanonical();
  const access = new AccessService({ store: identity.accessStore() });
  await access.claimOwner(
    await access.issueOperatorToken(),
    "owner",
    password,
    "household",
  );
  await identity.transact((state) => {
    Object.assign(state.profiles[0]!, profilePreferences);
  });
  profile = structuredClone((await identity.read()).profiles[0]!);
});
afterEach(() => {
  vi.unstubAllEnvs();
  fs.rmSync(directory, { recursive: true, force: true });
});

it("keeps the first Admin claim as the only shared password", async () => {
  vi.stubEnv(
    "PAPERNOOK_PASSWORD",
    "environment password must not override claim",
  );
  const store = new PapernookIdentityStore(directory);
  await store.initializeCanonical();
  const access = new AccessService({ store: store.accessStore() });
  await expect(
    access.enterHousehold("environment password must not override claim"),
  ).rejects.toMatchObject({ code: "unauthorized" });
  const admitted = await access.enterHousehold(password);
  await new HouseholdProfileService(access).select(admitted, "owner");
  expect((await access.authenticate(admitted, true)).principal?.role).toBe(
    "owner",
  );
});

it("restores Admin authority for the first profile when its stored owner binding is missing", async () => {
  const file = path.join(directory, "identity.json");
  const stored = JSON.parse(fs.readFileSync(file, "utf8")) as IdentityState;
  stored.access.householdProfiles = stored.access.householdProfiles?.map(
    (entry) => ({ id: entry.id, name: entry.name, epoch: entry.epoch }),
  );
  fs.writeFileSync(file, JSON.stringify(stored));

  const identity = new PapernookIdentityStore(directory);
  await identity.initializeCanonical();
  const state = await identity.read();
  const owner = state.access.principals.find(
    (principal) => principal.role === "owner",
  )!;
  expect(
    state.access.householdProfiles?.find((entry) => entry.id === "owner"),
  ).toMatchObject({ ownerPrincipalId: owner.id });
  const access = new AccessService({ store: identity.accessStore() });
  const token = await adminSession(access);
  expect(
    access.householdOwnerFromState((await identity.read()).access, token),
  ).toBe(true);
});

it("permits household profile creation and erasure without granting owner-account deletion", async () => {
  const store = new PapernookIdentityStore(directory);
  await store.initializeCanonical();
  const access = new AccessService({ store: store.accessStore() });
  const profiles = new HouseholdProfileService(access);
  const operations = new ProfileOperations(store);
  const guest = await access.enterHousehold(password);
  await profiles.select(guest, "owner");
  await expect(operations.remove(guest, "owner")).rejects.toMatchObject({
    code: "forbidden",
  });
  const created = await operations.create(guest, "New Reader");
  await profiles.select(guest, created.username);
  await operations.remove(guest, created.username);
  expect(await profiles.selected(guest)).toBeNull();
  await expect(operations.create(guest, "New Reader")).rejects.toMatchObject({
    code: "conflict",
  });
});

it("allows household erasure while rejecting an individual profile password", async () => {
  const store = new PapernookIdentityStore(directory);
  await store.initializeCanonical();
  const access = new AccessService({ store: store.accessStore() });
  const owner = await adminSession(access);
  const operations = new ProfileOperations(store);
  const guest = await access.enterHousehold(password);
  const profile = await operations.create(guest, "Reader");
  await new HouseholdProfileService(access).select(guest, profile.username);
  const id = Object.entries((await store.read()).bindings).find(
    ([, username]) => username === profile.username,
  )![0];
  const results = await Promise.allSettled([
    operations.remove(guest, profile.username),
    new PrincipalManagement(access).mutate(owner, {
      kind: "update",
      id,
      password: "individual reader password",
    }),
  ]);
  expect(
    results.filter((result) => result.status === "fulfilled"),
  ).toHaveLength(1);
  const current = (await store.read()).access.principals.find(
    (principal) => principal.id === id,
  );
  expect(results[0]?.status).toBe("fulfilled");
  expect(results[1]?.status).toBe("rejected");
  expect(current).toBeUndefined();
});

it("keeps the first Admin and rejects a second Admin account", async () => {
  const store = new PapernookIdentityStore(directory);
  await store.initializeCanonical();
  const access = new AccessService({ store: store.accessStore() });
  const first = await adminSession(access);
  await expect(
    new PrincipalManagement(access).mutate(first, {
      kind: "create",
      name: "Second Owner",
      role: "owner",
      password: "second owner password",
    }),
  ).rejects.toMatchObject({ code: "forbidden" });
  const operations = new ProfileOperations(store);
  await expect(operations.remove(first, "owner")).rejects.toMatchObject({
    code: "forbidden",
  });
  expect(
    (await store.read()).access.principals.filter(
      (principal) => principal.role === "owner",
    ),
  ).toHaveLength(1);
});

it("rejects rebinding or replacing a live identity without erasure", async () => {
  const store = new PapernookIdentityStore(directory);
  await store.initializeCanonical();
  const ownerId = Object.entries((await store.read()).bindings).find(
    ([, username]) => username === "owner",
  )![0];
  await expect(
    store.transact((state) => {
      state.bindings[ownerId] = "someone-else";
    }),
  ).rejects.toThrow("cannot be rebound");
  await expect(
    store.transact((state) => {
      state.profiles[0]!.sessionEpoch = "replacement";
    }),
  ).rejects.toThrow("erasure workflow");
  await expect(
    store.transact((state) => {
      state.generations.owner = 0;
    }),
  ).rejects.toThrow("cannot be removed or decreased");
  expect((await store.read()).profiles).toEqual([profile]);
});

it("keeps the owner's existing profile and tombstones removed member identities", async () => {
  const store = new PapernookIdentityStore(directory);
  await store.initializeCanonical();
  const access = new AccessService({ store: store.accessStore() });
  const owner = await adminSession(access);
  expect((await access.authenticate(owner, true)).principal?.role).toBe(
    "owner",
  );
  expect((await store.read()).profiles).toEqual([profile]);
  const management = new PrincipalManagement(access);
  const id = await management.mutate(owner, {
    kind: "create",
    name: "../New reader",
  });
  const before = await store.read();
  const username = before.bindings[id]!;
  expect(username).toBe("new-reader");
  expect(
    before.profiles.find((entry) => entry.username === username)?.captureToken,
  ).toMatch(/^[a-f0-9]{48}$/);
  const household = await access.enterHousehold(password);
  const selection = new HouseholdProfileService(access);
  await selection.select(household, username);
  await management.mutate(owner, { kind: "delete", id });
  const after = await store.read();
  expect(after.profiles.some((entry) => entry.username === username)).toBe(
    false,
  );
  expect(after.erasures).toContainEqual({ username, generation: 2 });
  expect(await selection.selected(household)).toBeNull();
});

it("keeps claimed access authority across restarts", async () => {
  const first = new PapernookIdentityStore(directory);
  await first.initializeCanonical();
  await first.read();
  const restarted = new PapernookIdentityStore(directory);
  const restartedAccess = new AccessService({ store: restarted.accessStore() });
  await expect(
    restartedAccess.enterHousehold("different household password"),
  ).rejects.toMatchObject({ code: "unauthorized" });
  const token = await restartedAccess.enterHousehold(password);
  expect((await restartedAccess.authenticate(token)).principal).toBeNull();
  expect((await first.read()).profiles).toEqual([profile]);
});

it("commits profile generations and selection invalidation in the same file", async () => {
  const store = new PapernookIdentityStore(directory);
  await store.initializeCanonical();
  const access = new AccessService({ store: store.accessStore() });
  const token = await access.enterHousehold(password);
  const selection = new HouseholdProfileService(access);
  await selection.select(token, "owner");
  await expect(
    store.transact((state) => {
      state.generations.owner++;
      state.profiles[0]!.displayName = "Uncommitted";
      throw new Error("injected transaction failure");
    }),
  ).rejects.toThrow("injected transaction failure");
  expect(await selection.selected(token)).toEqual({
    id: "owner",
    name: "Original owner",
  });
  await store.transact((state) => {
    state.generations.owner++;
  });
  expect(await selection.selected(token)).toBeNull();
});

import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { NextRequest } from "next/server";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { createTestProfile, mockTestSession } from "../../helpers/access";

let tmpDir: string;

beforeEach(() => {
  tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), "papernook-avatar-route-"));
  vi.stubEnv("PAPERNOOK_DATA_DIR", tmpDir);
  vi.resetModules();
});

afterEach(() => {
  vi.doUnmock("next/headers");
  vi.unstubAllEnvs();
  vi.clearAllMocks();
  fs.rmSync(tmpDir, { recursive: true, force: true });
});

async function routeAs(username: "ana" | "ben" | null) {
  await createTestProfile("Ana", "jaguar");
  await createTestProfile("Ben", "toucan");
  await mockTestSession(username);
  return import("@/app/api/v1/profiles/[username]/route");
}

function request(
  username: string,
  body: unknown,
  headers: Record<string, string> = {},
): NextRequest {
  return new NextRequest(`http://localhost/api/v1/profiles/${username}`, {
    method: "PATCH",
    headers: {
      "Content-Type": "application/json",
      Origin: "http://localhost",
      ...headers,
    },
    body: JSON.stringify(body),
  });
}

const params = (username: string) => ({
  params: Promise.resolve({ username }),
});

describe("profile avatar settings route", () => {
  it("requires a signed-in owner", async () => {
    const anonymous = await routeAs(null);
    expect(
      (
        await anonymous.PATCH(
          request("ana", { avatarSlug: "frog" }),
          params("ana"),
        )
      ).status,
    ).toBe(401);
  });

  it("does not let another profile change the avatar", async () => {
    const route = await routeAs("ben");
    const response = await route.PATCH(
      request("ana", { avatarSlug: "frog" }),
      params("ana"),
    );

    expect(response.status).toBe(403);
    const users = await import("@/lib/auth/users");
    expect(users.getProfile("ana")?.avatarSlug).toBe("jaguar");
  });

  it("rejects cross-site and invalid avatar changes", async () => {
    const route = await routeAs("ana");
    const crossSite = await route.PATCH(
      request(
        "ana",
        { avatarSlug: "frog" },
        { Origin: "https://attacker.example" },
      ),
      params("ana"),
    );
    expect(crossSite.status).toBe(403);

    const invalid = await route.PATCH(
      request("ana", { avatarSlug: "unknown" }),
      params("ana"),
    );
    expect(invalid.status).toBe(400);
  });

  it("persists and returns the owner's selected avatar", async () => {
    const route = await routeAs("ana");
    const response = await route.PATCH(
      request("ana", { avatarSlug: "frog" }),
      params("ana"),
    );

    expect(response.status).toBe(200);
    expect(await response.json()).toMatchObject({
      profile: { username: "ana", avatarSlug: "frog" },
    });
    const users = await import("@/lib/auth/users");
    expect(users.getProfile("ana")?.avatarSlug).toBe("frog");
  });
});

import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { NextRequest } from "next/server";
import { createTestProfile, mockTestSession } from "../../helpers/access";

let tmpDir: string;
const png = Buffer.from(
  "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+a6i0AAAAASUVORK5CYII=",
  "base64",
);

beforeEach(async () => {
  tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), "papernook-canvas-"));
  process.env.PAPERNOOK_DATA_DIR = tmpDir;
  vi.resetModules();
  await createTestProfile("Andres");
  await mockTestSession("andres");
  const papers = await import("@/lib/library/papers");
  papers.writeMeta("ml", "paper", {
    title: "Paper",
    authors: [],
    year: null,
    venue: null,
    arxivId: null,
    bibtex: null,
    tags: [],
    related: [],
    sourceUrl: "https://example.test/paper.pdf",
    addedAt: new Date().toISOString(),
    addedBy: "andres",
  });
  const pdf = papers.pdfPath("ml", "paper");
  fs.mkdirSync(path.dirname(pdf), { recursive: true });
  fs.writeFileSync(pdf, "%PDF-1.4");
});

afterEach(() => {
  vi.doUnmock("next/headers");
  fs.rmSync(tmpDir, { recursive: true, force: true });
});

const params = {
  params: Promise.resolve({ topic: "ml", slug: "paper" }),
};

describe("shared canvas persistence", () => {
  it("stores document state without session state and rejects stale saves", async () => {
    const route =
      await import("@/app/api/v1/papers/[topic]/[slug]/canvas/route");
    const initial = await route.GET(
      new NextRequest("http://localhost/canvas"),
      params,
    );
    expect(await initial.json()).toEqual({ document: null });
    expect(initial.headers.get("etag")).toBe('"empty"');
    expect(initial.headers.get("x-canvas-version")).toBe('"empty"');

    const saved = await route.PUT(
      new NextRequest("http://localhost/canvas", {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
          "X-Canvas-Version": '"empty"',
        },
        body: JSON.stringify({
          document: { store: { "shape:one": { typeName: "shape" } } },
        }),
      }),
      params,
    );
    expect(saved.status).toBe(200);
    expect(saved.headers.get("etag")).not.toBe('"empty"');
    expect(saved.headers.get("x-canvas-version")).toBe(
      saved.headers.get("etag"),
    );

    const stale = await route.PUT(
      new NextRequest("http://localhost/canvas", {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
          "X-Canvas-Version": '"empty"',
        },
        body: JSON.stringify({ document: { store: {} } }),
      }),
      params,
    );
    expect(stale.status).toBe(409);
    expect(stale.headers.get("x-canvas-version")).toBe(
      saved.headers.get("etag"),
    );

    const reloaded = await route.GET(
      new NextRequest("http://localhost/canvas"),
      params,
    );
    const reloadedPayload = await reloaded.json();
    expect(reloadedPayload).toEqual({
      document: { store: { "shape:one": { typeName: "shape" } } },
    });
    expect(JSON.stringify(reloadedPayload)).not.toContain("session");
    expect(reloaded.headers.get("x-canvas-version")).toBe(
      saved.headers.get("etag"),
    );
  });

  it("prefers the canonical canvas version and retains If-Match compatibility", async () => {
    const route =
      await import("@/app/api/v1/papers/[topic]/[slug]/canvas/route");
    const first = await route.PUT(
      new NextRequest("http://localhost/canvas", {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
          "X-Canvas-Version": '"empty"',
          "If-Match": '"empty-gzip"',
        },
        body: JSON.stringify({ document: { store: {} } }),
      }),
      params,
    );
    expect(first.status).toBe(200);
    const firstVersion = first.headers.get("x-canvas-version");
    expect(firstVersion).toBeTruthy();

    const compatible = await route.PUT(
      new NextRequest("http://localhost/canvas", {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
          "If-Match": firstVersion!,
        },
        body: JSON.stringify({
          document: { store: { "shape:two": { typeName: "shape" } } },
        }),
      }),
      params,
    );
    expect(compatible.status).toBe(200);
  });

  it("stores uploaded canvas images outside canvas.json and serves them", async () => {
    const assets =
      await import("@/app/api/v1/papers/[topic]/[slug]/canvas/assets/route");
    const uploaded = await assets.POST(
      new NextRequest("http://localhost/assets", {
        method: "POST",
        headers: { "Content-Type": "image/png" },
        body: png,
      }),
      params,
    );
    expect(uploaded.status).toBe(200);
    const payload = (await uploaded.json()) as { src: string };
    const filename = payload.src.split("/").at(-1);
    expect(filename).toMatch(/^[0-9a-f]{64}\.png$/);

    const duplicate = await assets.POST(
      new NextRequest("http://localhost/assets", {
        method: "POST",
        headers: { "Content-Type": "image/png" },
        body: png,
      }),
      params,
    );
    expect((await duplicate.json()) as { src: string }).toEqual(payload);

    const assetRoute =
      await import("@/app/api/v1/papers/[topic]/[slug]/canvas/assets/[asset]/route");
    const response = await assetRoute.GET(
      new NextRequest(`http://localhost${payload.src}`),
      {
        params: Promise.resolve({
          topic: "ml",
          slug: "paper",
          asset: filename!,
        }),
      },
    );
    expect(response.status).toBe(200);
    expect(response.headers.get("content-type")).toBe("image/png");
    expect(response.headers.get("x-content-type-options")).toBe("nosniff");
    expect(Buffer.from(await response.arrayBuffer())).toEqual(png);

    const deleted = await assetRoute.DELETE(
      new NextRequest(`http://localhost${payload.src}`, { method: "DELETE" }),
      {
        params: Promise.resolve({
          topic: "ml",
          slug: "paper",
          asset: filename!,
        }),
      },
    );
    expect(deleted.status).toBe(204);
    const missing = await assetRoute.GET(
      new NextRequest(`http://localhost${payload.src}`),
      {
        params: Promise.resolve({
          topic: "ml",
          slug: "paper",
          asset: filename!,
        }),
      },
    );
    expect(missing.status).toBe(404);
  });

  it("rejects oversized canvas assets before reading their body", async () => {
    const assets =
      await import("@/app/api/v1/papers/[topic]/[slug]/canvas/assets/route");
    const response = await assets.POST(
      new NextRequest("http://localhost/assets", {
        method: "POST",
        headers: {
          "Content-Type": "video/mp4",
          "Content-Length": String(51 * 1024 * 1024),
        },
        body: Buffer.from("small declared-as-oversized body"),
      }),
      params,
    );
    expect(response.status).toBe(413);
    expect(await response.json()).toEqual({
      error: "Canvas assets must be between 1 byte and 50 MB.",
    });
  });

  it("surfaces a corrupt saved canvas instead of overwriting it", async () => {
    const papers = await import("@/lib/library/papers");
    const paper = papers.getPaper("ml", "paper");
    fs.writeFileSync(path.join(paper!.companionDir, "canvas.json"), "{broken");
    const route =
      await import("@/app/api/v1/papers/[topic]/[slug]/canvas/route");
    const response = await route.GET(
      new NextRequest("http://localhost/canvas"),
      params,
    );
    expect(response.status).toBe(500);
    expect(await response.json()).toEqual({
      error: "The saved canvas is invalid.",
    });
    expect(
      fs.readFileSync(path.join(paper!.companionDir, "canvas.json"), "utf8"),
    ).toBe("{broken");
  });
});

import { describe, expect, it, vi } from "vitest";
import { reconcileStartupMigration } from "@/lib/canvas/startup";

class ConflictError extends Error {}

describe("canvas startup migration", () => {
  it("saves a migrated canvas against its loaded version", async () => {
    const save = vi.fn(async () => '"saved"');
    const reload = vi.fn(async () => '"latest"');

    const etag = await reconcileStartupMigration({
      etag: '"loaded"',
      migrate: async () => true,
      save,
      reload,
      isConflict: (error) => error instanceof ConflictError,
    });

    expect(etag).toBe('"saved"');
    expect(save).toHaveBeenCalledWith('"loaded"');
    expect(reload).not.toHaveBeenCalled();
  });

  it("accepts a competing mount's completed migration", async () => {
    const migrate = vi
      .fn<() => Promise<boolean>>()
      .mockResolvedValueOnce(true)
      .mockResolvedValueOnce(false);
    const save = vi.fn(async () => {
      throw new ConflictError();
    });
    const reload = vi.fn(async () => '"latest"');

    const etag = await reconcileStartupMigration({
      etag: '"loaded"',
      migrate,
      save,
      reload,
      isConflict: (error) => error instanceof ConflictError,
    });

    expect(etag).toBe('"latest"');
    expect(save).toHaveBeenCalledTimes(1);
    expect(reload).toHaveBeenCalledTimes(1);
  });

  it("reapplies migration to the latest canvas before retrying", async () => {
    const save = vi
      .fn<(etag: string) => Promise<string>>()
      .mockRejectedValueOnce(new ConflictError())
      .mockResolvedValueOnce('"saved-latest"');
    const reload = vi.fn(async () => '"latest"');

    const etag = await reconcileStartupMigration({
      etag: '"loaded"',
      migrate: async () => true,
      save,
      reload,
      isConflict: (error) => error instanceof ConflictError,
    });

    expect(etag).toBe('"saved-latest"');
    expect(save).toHaveBeenNthCalledWith(1, '"loaded"');
    expect(save).toHaveBeenNthCalledWith(2, '"latest"');
    expect(reload).toHaveBeenCalledTimes(1);
  });

  it("does not hide non-conflict failures", async () => {
    await expect(
      reconcileStartupMigration({
        etag: '"loaded"',
        migrate: async () => true,
        save: async () => {
          throw new Error("storage unavailable");
        },
        reload: async () => '"latest"',
        isConflict: (error) => error instanceof ConflictError,
      }),
    ).rejects.toThrow("storage unavailable");
  });

  it("stops after three competing migration saves", async () => {
    const save = vi.fn(async () => {
      throw new ConflictError();
    });
    const reload = vi.fn(async () => '"latest"');

    await expect(
      reconcileStartupMigration({
        etag: '"loaded"',
        migrate: async () => true,
        save,
        reload,
        isConflict: (error) => error instanceof ConflictError,
      }),
    ).rejects.toBeInstanceOf(ConflictError);

    expect(save).toHaveBeenCalledTimes(3);
    expect(reload).toHaveBeenCalledTimes(3);
  });
});

import { createTLSchema, type TLStoreSnapshot } from "@tldraw/tlschema";
import { describe, expect, it } from "vitest";
import { attributeCanvas, validateSharedCanvas } from "@/lib/canvas/validation";

const schema = createTLSchema();
function canvas(): TLStoreSnapshot {
  const document = schema.types.document.create({
    id: schema.types.document.createId("document"),
    name: "Shared notes",
  });
  const page = schema.types.page.create({
    id: schema.types.page.createId("main"),
    name: "Page 1",
    index: "a1",
  });
  const shape = schema.types.shape.create({
    id: schema.types.shape.createId("note"),
    type: "text",
    index: "a1",
    parentId: page.id,
    props: {
      color: "black",
      size: "m",
      font: "draw",
      textAlign: "start",
      w: 200,
      richText: {
        type: "doc",
        content: [
          {
            type: "paragraph",
            content: [{ type: "text", text: "A shared note" }],
          },
        ],
      },
      scale: 1,
      autoSize: true,
    },
  });
  return {
    schema: schema.serialize(),
    store: { [document.id]: document, [page.id]: page, [shape.id]: shape },
  };
}
function textShape(document: TLStoreSnapshot) {
  const record = Object.values(document.store).find(
    (entry) => entry.typeName === "shape" && entry.type === "text",
  );
  if (!record || record.typeName !== "shape" || record.type !== "text")
    throw new Error("Text fixture missing");
  return record;
}
const identity = (source: string) => source;

describe("portable canvas validation", () => {
  it("accepts nested frames and groups while rejecting cyclic containers", () => {
    const document = canvas();
    const note = textShape(document);
    const frame = schema.types.shape.create({
      id: schema.types.shape.createId("frame"),
      type: "frame",
      index: "a2",
      parentId: note.parentId,
