      "https://arxiv.org/abs/1706.03762",
      testProfileCapability("andres"),
    );
    expect(jobs.readCaptureJob(slug)?.state).toBe("analyzing");

    await waitFor(() => jobs.readCaptureJob(slug)?.state === "done");
    const done = jobs.readCaptureJob(slug);
    expect(done?.finalSlug).toBe("attention-is-all-you-need");
    const papers = await import("@/lib/library/papers");
    const paper = papers.getPaper(null, "attention-is-all-you-need");
    expect(paper?.meta.title).toBe(ANALYSIS.title);
    // The traveled marker must not make the real paper read as a job.
    expect(jobs.readCaptureJob("attention-is-all-you-need")).toBeNull();
  });

  it("keeps the polling handle at the provisional slug across the title rename", async () => {
    await mockPipeline();
    const { ensureDataDirs } = await import("@/lib/data-dir");
    ensureDataDirs();
    await createTestProfile("Andres");
    const { capturePdf } = await import("@/lib/capture");
    const jobs = await import("@/lib/capture/jobs");

    // The async flow writes the marker, then runs capturePdf, then writes
    // "done" over it. In between, a status poll may land at any moment —
    // if the marker travels to the title slug with the renamed dir, the
    // poll reads "job vanished" and the UI reports a finishing capture lost.
    jobs.writeCaptureJob({
      slug: "2209-03416",
      state: "analyzing",
      sourceUrl: "https://arxiv.org/pdf/2209.03416",
      addedBy: "andres",
      startedAt: "2026-08-11T10:00:00.000Z",
    });
    const result = await capturePdf(Buffer.from("%PDF-1.4 fake"), {
      sourceUrl: "https://arxiv.org/pdf/2209.03416",
      username: "andres",
      capability: testProfileCapability("andres"),
      provisionalSlug: "2209-03416",
    });
    expect(result.slug).toBe("attention-is-all-you-need");
    expect(jobs.readCaptureJob("2209-03416")?.state).toBe("analyzing");
    expect(jobs.readCaptureJob(result.slug)).toBeNull();
  });

  it("dedupes a double-submit of the same URL while analyzing", async () => {
    let release: () => void = () => {};
    const gate = new Promise<void>((resolve) => {
      release = resolve;
    });
    await mockPipeline({
      download: async () => {
        await gate;
        return {
          bytes: Buffer.from("%PDF-1.4 fake"),
          finalUrl: "https://a.io/x.pdf",
          arxivId: null,
        };
      },
    });
    const { ensureDataDirs } = await import("@/lib/data-dir");
    ensureDataDirs();
    await createTestProfile("Andres");
    const { captureAsync } = await import("@/lib/capture");
    const jobs = await import("@/lib/capture/jobs");

    const first = await captureAsync(
      "https://a.io/x.pdf",
      testProfileCapability("andres"),
    );
    const second = await captureAsync(
      "https://a.io/x.pdf",
      testProfileCapability("andres"),
    );
    expect(second.slug).toBe(first.slug);
    expect(jobs.readCaptureJob(first.slug)?.generation).toBe(
      testProfileCapability("andres").generation,
    );
    release();
    await waitFor(() => jobs.readCaptureJob(first.slug)?.state === "done");
    expect(jobs.readCaptureJob(first.slug)?.generation).toBe(
      testProfileCapability("andres").generation,
    );
  });

  it("records download failures as a failed marker with the real reason", async () => {
    const actual = await vi.importActual<
      typeof import("@/lib/capture/download")
    >("@/lib/capture/download");
    await mockPipeline({
      download: async () => {
        throw new actual.CaptureError("The publisher blocks downloads.");
      },
    });
    const { ensureDataDirs } = await import("@/lib/data-dir");
    ensureDataDirs();
    await createTestProfile("Andres");
    const { captureAsync } = await import("@/lib/capture");
    const jobs = await import("@/lib/capture/jobs");

    const { slug } = await captureAsync(
      "https://paywall.example/x.pdf",
      testProfileCapability("andres"),
    );
    await waitFor(() => jobs.readCaptureJob(slug)?.state === "failed");
    expect(jobs.readCaptureJob(slug)?.error).toBe(
      "The publisher blocks downloads.",
    );
    // The failed marker dir holds no PDF.
    const dir = path.join(tmpDir, "library", "_inbox", slug);
    expect(fs.existsSync(dir)).toBe(false);
  });
});

import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import type { CaptureState } from "@/components/library/useCapture";

type Handler = (url: string, init?: RequestInit) => Response;

function jsonResponse(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { "content-type": "application/json" },
  });
}

let handler: Handler;

beforeEach(() => {
  vi.useFakeTimers();
  vi.resetModules();
  vi.stubGlobal(
    "fetch",
    vi.fn(async (input: string | URL | Request, init?: RequestInit) =>
      handler(String(input), init),
    ),
  );
});

afterEach(() => {
  vi.unstubAllGlobals();
  vi.useRealTimers();
});

async function loadHook() {
  return import("@/components/library/useCapture");
}

/** Let the interval fire once and its fetch/json promises settle. */
async function tick(): Promise<void> {
  await vi.advanceTimersByTimeAsync(2000);
}

describe("useCapture registry", () => {
  it("moves through adding → added with the final slug and notifies subscribers", async () => {
    let polls = 0;
    handler = (url, init) => {
      if (init?.method === "POST") {
        expect(JSON.parse(String(init.body))).toEqual({
          url: "https://arxiv.org/abs/2308.04079",
        });
        return jsonResponse({ slug: "pending-slug" }, 202);
      }
      expect(url).toContain("slug=pending-slug");
      polls += 1;
      return polls < 2
        ? jsonResponse({ state: "analyzing" })
        : jsonResponse({ state: "done", finalSlug: "gaussian-splatting" });
    };
    const hook = await loadHook();
    const seen: CaptureState[] = [];
    hook.subscribeCapture("https://arxiv.org/abs/2308.04079", () => {
      seen.push(hook.captureState("https://arxiv.org/abs/2308.04079"));
    });

    await hook.startCapture("https://arxiv.org/abs/2308.04079");
    expect(hook.captureState("https://arxiv.org/abs/2308.04079")).toEqual({
      status: "adding",
    });
    await tick();
    expect(hook.captureState("https://arxiv.org/abs/2308.04079").status).toBe(
      "adding",
    );
    await tick();
    const final = hook.captureState("https://arxiv.org/abs/2308.04079");
    expect(final).toEqual({ status: "added", finalSlug: "gaussian-splatting" });
    expect(seen.map((s) => s.status)).toEqual(["adding", "added"]);
    expect(hook.captureInboxHref("gaussian-splatting")).toBe(
      "/inbox/gaussian-splatting",
    );

    // Settled captures stop polling and never restart.
    const before = polls;
    await hook.startCapture("https://arxiv.org/abs/2308.04079");
    await tick();
    expect(polls).toBe(before);
  });

  it("starts one job per URL even when several buttons ask at once", async () => {
    let posts = 0;
    handler = (_url, init) => {
      if (init?.method === "POST") {
        posts += 1;
        return jsonResponse({ slug: "s" }, 202);
      }
      return jsonResponse({ state: "analyzing" });
    };
    const hook = await loadHook();
    await Promise.all([
      hook.startCapture("https://doi.org/10.1/abc"),
      hook.startCapture("https://doi.org/10.1/abc"),
    ]);
    expect(posts).toBe(1);
  });

  it("treats a retired job marker as already added, pointing at the inbox", async () => {
    handler = (_url, init) =>
      init?.method === "POST"
        ? jsonResponse({ slug: "s" }, 202)
        : jsonResponse({ error: "no longer pending" }, 404);
    const hook = await loadHook();
    await hook.startCapture("https://doi.org/10.1/retired");
    await tick();
    expect(hook.captureState("https://doi.org/10.1/retired")).toEqual({
      status: "added",
      finalSlug: null,
    });
    expect(hook.captureInboxHref(null)).toBe("/?topic=_inbox");
  });

  it("surfaces server rejections and job failures with their reason", async () => {
    handler = (_url, init) =>
      init?.method === "POST"
        ? jsonResponse({ error: "Too many captures. Try again later." }, 429)
        : jsonResponse({ state: "analyzing" });
    const hook = await loadHook();
    await hook.startCapture("https://doi.org/10.1/limited");
    expect(hook.captureState("https://doi.org/10.1/limited")).toEqual({
      status: "failed",
      error: "Too many captures. Try again later.",
    });

    handler = (_url, init) =>
      init?.method === "POST"
        ? jsonResponse({ slug: "s" }, 202)
        : jsonResponse({ state: "failed", error: "Already in your library." });
    await hook.startCapture("https://doi.org/10.1/dupe");
    await tick();
    expect(hook.captureState("https://doi.org/10.1/dupe")).toEqual({
      status: "failed",
      error: "Already in your library.",
    });

    // A failed capture may be retried.
    handler = (_url, init) =>
      init?.method === "POST"
        ? jsonResponse({ slug: "s2" }, 202)
        : jsonResponse({ state: "done", finalSlug: "dupe" });
    await hook.startCapture("https://doi.org/10.1/dupe");
    await tick();
    expect(hook.captureState("https://doi.org/10.1/dupe").status).toBe("added");
  });

  it("gives up on a job marker stuck in analyzing and offers a retry", async () => {
    handler = (_url, init) =>
      init?.method === "POST"
        ? jsonResponse({ slug: "s" }, 202)
        : jsonResponse({ state: "analyzing" });
    const hook = await loadHook();
    await hook.startCapture("https://doi.org/10.1/stuck");
    await vi.advanceTimersByTimeAsync(9 * 60 * 1000);
    expect(hook.captureState("https://doi.org/10.1/stuck").status).toBe(
      "adding",
    );
    await vi.advanceTimersByTimeAsync(2 * 60 * 1000);
    const state = hook.captureState("https://doi.org/10.1/stuck");
    expect(state.status).toBe("failed");
    expect(state.status === "failed" && state.error).toMatch(/Inbox/);
    const fetchMock = vi.mocked(fetch);
    const callsAtFailure = fetchMock.mock.calls.length;
    await vi.advanceTimersByTimeAsync(60 * 1000);
    expect(fetchMock.mock.calls.length).toBe(callsAtFailure);
  });

  it("keeps polling through a network blip", async () => {
    let polls = 0;
    handler = (_url, init) => {
      if (init?.method === "POST") return jsonResponse({ slug: "s" }, 202);
      polls += 1;
      if (polls === 1) throw new TypeError("offline");
      return jsonResponse({ state: "done", finalSlug: "landed" });
    };
    const hook = await loadHook();
    await hook.startCapture("https://doi.org/10.1/blip");
    await tick();
    expect(hook.captureState("https://doi.org/10.1/blip").status).toBe(
      "adding",
    );
    await tick();
    expect(hook.captureState("https://doi.org/10.1/blip")).toEqual({
      status: "added",
      finalSlug: "landed",
    });
  });
});

