    fs.writeFileSync(path.join(crops, "other.png"), "png");
    chats.appendMessage("ml", "paper", "andres", chatId, {
      role: "user",
      content: "look at this",
      images: ["crops/mine.png"],
      at: "2026-08-10T10:01:00.000Z",
    });

    chats.deleteMessage(
      "ml",
      "paper",
      "andres",
      chatId,
      2,
      "2026-08-10T10:01:00.000Z",
