import { describe, expect, it } from "vitest";
import { rehypePaperRefs, type HastNode } from "@/lib/chat/ref-decorations";
import { detailFromDataset } from "@/lib/chat/paper-ref-events";
import type { Bibliography } from "@/lib/pdf/bibliography";

function paragraph(text: string): HastNode {
  return {
    type: "root",
    children: [
      {
        type: "element",
        tagName: "p",
        properties: {},
        children: [{ type: "text", value: text }],
      },
    ],
  };
}

function buttons(tree: HastNode): HastNode[] {
  const found: HastNode[] = [];
  const visit = (node: HastNode) => {
    if (node.tagName === "button") found.push(node);
    node.children?.forEach(visit);
  };
  visit(tree);
  return found;
}

function textOf(node: HastNode): string {
  if (node.type === "text") return node.value ?? "";
  return (node.children ?? []).map(textOf).join("");
}

const numberedBibliography: Bibliography = {
  style: "numbered",
  entries: [
    {
      pageNumber: 9,
      x: 40,
      y: 700,
      text: "[20] Kheradmand et al. 3D Gaussian Splatting as MCMC. 2024.",
      surname: "Kheradmand",
      year: "2024",
      suffix: null,
      number: 20,
    },
  ],
};

describe("rehypePaperRefs", () => {
  it("wraps paper refs in buttons and keeps surrounding text intact", () => {
    const tree = paragraph("See Figure 3 and Sec. 4.3 for details.");
    rehypePaperRefs()(tree);
    const [figure, section] = buttons(tree);
    expect(textOf(figure!)).toBe("Figure 3");
    expect(figure!.properties?.dataPaperRef).toBe(
      JSON.stringify({ kind: "figure", label: "3" }),
    );
    expect(textOf(section!)).toBe("Sec. 4.3");
    expect(textOf(tree)).toBe("See Figure 3 and Sec. 4.3 for details.");
  });

  it("keeps section titles adjacent and dispatches supplement locators", () => {
    const tree = paragraph(
      "Section 4.3 (Training Schedule) uses Eq. (A.1), Figure S1, and Table S2.",
    );
    rehypePaperRefs()(tree);
    const all = buttons(tree);

    expect(all.map(textOf)).toEqual([
      "Section 4.3",
      "Eq. (A.1)",
      "Figure S1",
      "Table S2",
    ]);
    expect(textOf(tree)).toContain("Section 4.3 (Training Schedule)");
    expect(
      detailFromDataset(
        { paperRef: String(all[1]!.properties?.dataPaperRef) },
        "goto",
      ),
    ).toEqual({ action: "goto", ref: { kind: "equation", label: "A.1" } });
  });

  it("decorates fully repeated grouped locators independently", () => {
    const tree = paragraph("Figure 2, Figure 3, and Figure 4 show the stages.");
    rehypePaperRefs()(tree);
    expect(buttons(tree).map(textOf)).toEqual([
      "Figure 2",
      "Figure 3",
      "Figure 4",
    ]);
  });

  it("decorates citations only when they resolve in the bibliography", () => {
    const tree = paragraph("as shown in [20] but not [7]");
    rehypePaperRefs({ bibliography: numberedBibliography })(tree);
    const all = buttons(tree);
    expect(all).toHaveLength(1);
    expect(all[0]!.properties?.dataCitation).toBe(
      JSON.stringify({ kind: "numeric", number: 20 }),
    );
    expect(all[0]!.properties?.ariaLabel).toContain("Kheradmand");
  });

  it("leaves citations untouched without a bibliography", () => {
    const tree = paragraph("as shown in [20]");
    rehypePaperRefs()(tree);
    expect(buttons(tree)).toHaveLength(0);
  });

  it("skips in-paper refs when refs is false but still decorates citations", () => {
    const tree = paragraph("See Figure 3 and [20].");
    rehypePaperRefs({ bibliography: numberedBibliography, refs: false })(tree);
    const all = buttons(tree);
    expect(all).toHaveLength(1);
    expect(all[0]!.properties?.dataCitation).toBe(
      JSON.stringify({ kind: "numeric", number: 20 }),
    );
    expect(textOf(tree)).toBe("See Figure 3 and [20].");
  });

  it("never rewrites code or katex subtrees", () => {
    const tree: HastNode = {
      type: "root",
      children: [
        {
          type: "element",
          tagName: "code",
          properties: {},
          children: [{ type: "text", value: "plot(Figure 3)" }],
        },
        {
          type: "element",
          tagName: "span",
          properties: { className: ["katex"] },
          children: [{ type: "text", value: "Figure 3" }],
        },
      ],
    };
    rehypePaperRefs()(tree);
    expect(buttons(tree)).toHaveLength(0);
  });

  it("keeps ref and citation decorations ordered and non-overlapping", () => {
    const tree = paragraph("Figure 3 relates to [20].");
    rehypePaperRefs({ bibliography: numberedBibliography })(tree);
    const all = buttons(tree);
    expect(all.map((node) => textOf(node))).toEqual(["Figure 3", "20"]);
    expect(textOf(tree)).toBe("Figure 3 relates to [20].");
  });
});

import { createTestProfile, mockTestSession } from "../../helpers/access";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { NextRequest } from "next/server";

let tmpDir: string;
let releaseProvider: () => void;
let providerCalls: number;
let titleCalls: number;
let capturedSystem: string | undefined;
let capturedTitlePrompt: string | undefined;

beforeEach(async () => {
  tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), "papernook-chat-stream-"));
  process.env.PAPERNOOK_DATA_DIR = tmpDir;
  providerCalls = 0;
  titleCalls = 0;
  capturedSystem = undefined;
  capturedTitlePrompt = undefined;
  vi.resetModules();
  await createTestProfile("Andres");
  await mockTestSession("andres");
  vi.doMock("@/lib/agent/registry", () => ({
    hasConfiguredProvider: () => true,
    getProvider: () => ({
      id: "claude-code",
      capabilities: { web: true, vision: true, unboundedContext: true },
      execute: async (turn: { prompt: string }) => {
        titleCalls += 1;
        capturedTitlePrompt = turn.prompt;
        return "Interpolated vertex optimization";
      },
      stream: async function* (turn: { system?: string }) {
        providerCalls += 1;
        capturedSystem = turn.system;
        await new Promise<void>((resolve) => {
          releaseProvider = resolve;
        });
        yield "answer";
      },
    }),
  }));

  const papers = await import("@/lib/library/papers");
  papers.writeMeta("ml", "paper", {
    title: "Paper",
    authors: [],
    year: null,
    venue: null,
    arxivId: null,
    bibtex: null,
    tags: [],
    related: [],
    sourceUrl: "https://example.test/paper.pdf",
    addedAt: new Date().toISOString(),
    addedBy: "andres",
  });
  const pdf = papers.pdfPath("ml", "paper");
  fs.mkdirSync(path.dirname(pdf), { recursive: true });
  fs.writeFileSync(pdf, "%PDF-1.4");
});

afterEach(async () => {
  vi.doUnmock("next/headers");
  vi.unstubAllEnvs();
  vi.doUnmock("@/lib/agent/registry");
  vi.unstubAllGlobals();
  const { closeIndex } = await import("@/lib/library/index-db");
  closeIndex();
  fs.rmSync(tmpDir, { recursive: true, force: true });
});

describe("chat response streaming", () => {
  it("generates a semantic title from the complete first message only", async () => {
    const chats = await import("@/lib/library/chats");
    const chat = chats.createChat("ml", "paper", "andres", "New chat");
    const route =
      await import("@/app/api/v1/papers/[topic]/[slug]/chats/[chatId]/route");
    const completeMessage = `${"context ".repeat(2400)}main intent at the end`;

    const firstResponse = await route.POST(
      new NextRequest("http://localhost/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ content: completeMessage }),
      }),
      {
        params: Promise.resolve({
          topic: "ml",
          slug: "paper",
          chatId: chat.id,
        }),
      },
    );
    const firstReader = firstResponse.body!.getReader();
    await firstReader.read();
    releaseProvider();
    while (!(await firstReader.read()).done) {
      // Drain the first answer.
    }

    expect(titleCalls).toBe(1);
    expect(capturedTitlePrompt).toBe(completeMessage);
    expect(providerCalls).toBe(1);
    expect(chats.readChat("ml", "paper", "andres", chat.id)?.header).toEqual(
      expect.objectContaining({
        title: "Interpolated vertex optimization",
        titleSource: "generated",
      }),
    );

    const secondResponse = await route.POST(
      new NextRequest("http://localhost/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ content: "A follow-up question" }),
      }),
      {
        params: Promise.resolve({
          topic: "ml",
          slug: "paper",
          chatId: chat.id,
        }),
      },
    );
    const secondReader = secondResponse.body!.getReader();
    await secondReader.read();
    releaseProvider();
    while (!(await secondReader.read()).done) {
      // Drain the follow-up answer.
    }

    expect(titleCalls).toBe(1);
    expect(providerCalls).toBe(2);
    expect(chats.readChat("ml", "paper", "andres", chat.id)?.header.title).toBe(
      "Interpolated vertex optimization",
    );
  });

  it("sends a keepalive before a slow provider responds without persisting it", async () => {
    const chats = await import("@/lib/library/chats");
    const chat = chats.createChat("ml", "paper", "andres", "Slow chat");
    const route =
      await import("@/app/api/v1/papers/[topic]/[slug]/chats/[chatId]/route");
    const response = await route.POST(
      new NextRequest("http://localhost/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ content: "research this" }),
      }),
      {
        params: Promise.resolve({
          topic: "ml",
          slug: "paper",
          chatId: chat.id,
        }),
      },
    );

    const reader = response.body!.getReader();
    const first = await reader.read();
    expect(new TextDecoder().decode(first.value)).toBe("\n");
    expect(first.done).toBe(false);

    releaseProvider();
    const second = await reader.read();
    expect(new TextDecoder().decode(second.value)).toBe("answer");
    expect((await reader.read()).done).toBe(true);

    const stored = chats.readChat("ml", "paper", "andres", chat.id);
    expect(stored?.messages).toEqual([
      expect.objectContaining({ role: "user", content: "research this" }),
      expect.objectContaining({ role: "assistant", content: "answer" }),
    ]);
  });

  it("does not recreate a chat deleted while the provider is responding", async () => {
    const chats = await import("@/lib/library/chats");
    const chat = chats.createChat("ml", "paper", "andres", "Slow chat");
    const route =
      await import("@/app/api/v1/papers/[topic]/[slug]/chats/[chatId]/route");
    const response = await route.POST(
      new NextRequest("http://localhost/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ content: "research this" }),
      }),
      {
        params: Promise.resolve({
          topic: "ml",
          slug: "paper",
          chatId: chat.id,
        }),
      },
    );

    const reader = response.body!.getReader();
    await reader.read();
    expect(chats.deleteChat("ml", "paper", "andres", chat.id)).toBe(true);
    releaseProvider();
    while (!(await reader.read()).done) {
      // Drain the streamed answer so assistant persistence runs.
    }

    expect(chats.readChat("ml", "paper", "andres", chat.id)).toBeNull();
    expect(chats.listChats("ml", "paper", "andres")).toEqual([]);
  });

  it("verifies and injects an entire GitHub file before saving the turn", async () => {
    const sha = "2a810a6c353215685307da3d4cc6ebd73b1c387b";
    vi.stubGlobal(
      "fetch",
      vi
        .fn<typeof fetch>()
        .mockResolvedValueOnce(new Response(JSON.stringify({ sha })))
        .mockResolvedValueOnce(
          new Response(
            JSON.stringify({
              truncated: false,
              tree: [
                { path: "train.py", type: "blob", size: 60 },
                { path: "model.py", type: "blob", size: 28 },
              ],
            }),
          ),
        )
        .mockResolvedValueOnce(
          new Response(
            "def stage_one():\n    pass\n\ndef stage_two():\n    pass\n",
          ),
        )
        .mockResolvedValueOnce(new Response("class Model:\n    pass\n")),
    );
    const chats = await import("@/lib/library/chats");
    const chat = chats.createChat("ml", "paper", "andres", "New chat");
    const route =
      await import("@/app/api/v1/papers/[topic]/[slug]/chats/[chatId]/route");
    const response = await route.POST(
      new NextRequest("http://localhost/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          content:
            "Explain all stages in https://github.com/org/repo/blob/main/train.py",
        }),
      }),
      {
        params: Promise.resolve({
          topic: "ml",
          slug: "paper",
          chatId: chat.id,
        }),
      },
    );
    const reader = response.body!.getReader();
    await reader.read();
    releaseProvider();
    while (!(await reader.read()).done) {
      // Drain the answer so persistence completes.
    }

    expect(providerCalls).toBe(1);
    expect(capturedSystem).toContain("follow every local import");
    expect(capturedSystem).toContain("every stage transition");
    expect(capturedSystem).toContain('"path":"train.py"');
    expect(capturedSystem).toContain('"line":1,"text":"def stage_one():"');
    expect(capturedSystem).toContain('"line":5,"text":"    pass"');
    expect(capturedSystem).toContain('"path":"model.py"');
    expect(capturedSystem).toContain(
      `https://github.com/org/repo/blob/${sha}/train.py`,
    );
    expect(
      chats.readChat("ml", "paper", "andres", chat.id)?.messages[0]
        .repositorySource,
    ).toEqual({ owner: "org", repo: "repo", sha, path: "train.py" });
  });

  it("rejects failed source verification before persistence or provider work", async () => {
    vi.stubGlobal(
      "fetch",
      vi
        .fn<typeof fetch>()
        .mockResolvedValue(new Response(null, { status: 404 })),
    );
    const chats = await import("@/lib/library/chats");
    const chat = chats.createChat("ml", "paper", "andres", "New chat");
    const route =
      await import("@/app/api/v1/papers/[topic]/[slug]/chats/[chatId]/route");
    const response = await route.POST(
      new NextRequest("http://localhost/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          content: "Read https://github.com/org/repo/blob/main/train.py",
        }),
      }),
      {
        params: Promise.resolve({
          topic: "ml",
          slug: "paper",
          chatId: chat.id,
        }),
      },
    );

    expect(response.status).toBe(502);
    expect(await response.json()).toEqual({
      error: "GitHub repository, revision, or file was not found.",
    });
    expect(providerCalls).toBe(0);
    expect(chats.readChat("ml", "paper", "andres", chat.id)?.messages).toEqual(
      [],
    );
  });

  it("pins follow-up analysis to the previously verified commit", async () => {
    const sha = "2a810a6c353215685307da3d4cc6ebd73b1c387b";
    const fetchMock = vi
      .fn<typeof fetch>()
      .mockResolvedValueOnce(
        new Response(
          JSON.stringify({
            truncated: false,
            tree: [{ path: "train.py", type: "blob", size: 22 }],
          }),
        ),
      )
      .mockResolvedValueOnce(new Response("complete pinned source"));
    vi.stubGlobal("fetch", fetchMock);
    const chats = await import("@/lib/library/chats");
    const chat = chats.createChat("ml", "paper", "andres", "Source chat");
    chats.appendMessage("ml", "paper", "andres", chat.id, {
      role: "user",
      content: "original source request",
      repositorySource: { owner: "org", repo: "repo", sha, path: "train.py" },
      at: "2026-08-13T10:00:00.000Z",
    });
    const route =
      await import("@/app/api/v1/papers/[topic]/[slug]/chats/[chatId]/route");
    const response = await route.POST(
      new NextRequest("http://localhost/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ content: "Now trace the stage transition." }),
      }),
      {
        params: Promise.resolve({
          topic: "ml",
          slug: "paper",
          chatId: chat.id,
        }),
      },
    );
    const reader = response.body!.getReader();
    await reader.read();
    releaseProvider();
    while (!(await reader.read()).done) {
      // Drain the answer.
    }

    expect(fetchMock).toHaveBeenCalledTimes(2);
    expect(fetchMock.mock.calls[0][0]).toBe(
      `https://api.github.com/repos/org/repo/git/trees/${sha}?recursive=1`,
    );
    expect(capturedSystem).toContain("complete pinned source");
  });
});

import { describe, it, expect } from "vitest";
import fs from "node:fs";
import path from "node:path";
import nextConfig from "../../../next.config";
import {
  isThreeDiagnostic,
  threeSandboxUrl,
} from "@/components/chat/ThreeSandbox";

const vendorDir = path.join(process.cwd(), "public/vendor");

describe("threejs sandbox", () => {
  it("round-trips arbitrary scene code through the fragment", () => {
    const code =
      "import * as THREE from 'three';\n" +
      'const s = "</script>#%&?"; // ε ≠ noise\n';
    const url = threeSandboxUrl(code);
    expect(url.startsWith("/vendor/three-sandbox.html?v=7#")).toBe(true);
    const [, fragment] = url.split("#");
    expect(decodeURIComponent(fragment)).toBe(code);
    // Nothing may leak unencoded past the fragment marker.
    expect(fragment).not.toContain("<");
    expect(fragment).not.toContain("#");
  });

  it("accepts only data-free diagnostics from untrusted scene code", () => {
    expect(
      isThreeDiagnostic({
        protocol: 1,
        type: "papernook-three-diagnostic",
        kind: "module-evaluation-failed",
        line: 4,
        column: 12,
        resource: "three-runtime",
      }),
    ).toBe(true);
    expect(
      isThreeDiagnostic({
        protocol: 1,
        type: "papernook-three-diagnostic",
        kind: "module-evaluation-failed",
        message: "SECRET PAPER TEXT",
      }),
    ).toBe(false);
    expect(
      isThreeDiagnostic({
        protocol: 1,
        type: "papernook-three-diagnostic",
        kind: "invented-event",
      }),
    ).toBe(false);
  });

  it("ships a self-contained sandbox without remote runtime dependencies", () => {
    const html = fs.readFileSync(
      path.join(vendorDir, "three-sandbox.html"),
      "utf8",
    );
    expect(html).toContain("papernookThreeRuntimeReady");
    expect(html).toContain("WebGLRenderer");
    expect(html).toContain("normalizeSceneOverlays");
    expect(html).not.toContain('type="module"');
    expect(html).not.toContain('src="./three-runtime.js');
    expect(html).not.toMatch(/<script[^>]+src=/);
  });

  it("retains module assets for older cached sandbox pages", () => {
    const moduleSource = fs.readFileSync(
      path.join(vendorDir, "three/three.module.min.js"),
      "utf8",
    );
    // three.module re-exports from the core file; both must ship together.
    expect(moduleSource).toContain("three.core.min.js");
    expect(fs.existsSync(path.join(vendorDir, "three/three.core.min.js"))).toBe(
      true,
    );
    expect(
      fs.existsSync(
        path.join(vendorDir, "three/addons/controls/OrbitControls.js"),
      ),
    ).toBe(true);
