function meta(title: string, tags: string[] = []): PaperMeta {
  return {
    title,
    authors: ["Ada Lovelace"],
    year: 1843,
    venue: "Examples",
    arxivId: null,
    bibtex: null,
    tags,
    related: [],
    sourceUrl: "https://example.org",
    addedAt: "2024-01-01T00:00:00.000Z",
    addedBy: "andres",
    citation: {
      type: "document",
      authors: [{ literal: "Ada Lovelace" }],
      containerTitle: "Examples",
      URL: "https://example.org",
    },
  };
}

async function place(
  topic: string | null,
  slug: string,
  title: string,
  tags: string[] = [],
  text = "",
): Promise<void> {
  const papers = await import("@/lib/library/papers");
  papers.writeMeta(topic, slug, meta(title, tags));
  papers.writeText(topic, slug, text);
  const pdf = papers.pdfPath(topic, slug);
  fs.mkdirSync(path.dirname(pdf), { recursive: true });
  fs.writeFileSync(pdf, "%PDF-1.4");
}

