    const hit = await route.GET(
      resolveUrl(
        `q=${encodeURIComponent("Kerbl, B.: 3D Gaussian splatting. arXiv:2308.04079 (2023)")}`,
      ),
    );
    expect(hit.status).toBe(200);
    expect(await hit.json()).toEqual({
      url: "https://arxiv.org/abs/2308.04079",
      title: null,
    });

    const miss = await route.GET(
      resolveUrl(
        `q=${encodeURIComponent("Doe, A., Roe, B. Robust estimation of planar homographies. IJCV (2011)")}`,
      ),
    );
    expect(await miss.json()).toEqual({ url: null });

    // An upstream outage is a retryable failure, never a "not found".
    vi.stubGlobal("fetch", async () => new Response("", { status: 503 }));
    const outage = await route.GET(
      resolveUrl(
        `q=${encodeURIComponent("Roe, B., Doe, A. Dense estimation of camera motion. CVPR (2012)")}`,
      ),
    );
    expect(outage.status).toBe(502);

    expect((await route.GET(resolveUrl(""))).status).toBe(400);
    expect((await route.GET(resolveUrl("q=too+short"))).status).toBe(400);
    expect((await route.GET(resolveUrl(`q=${"x".repeat(401)}`))).status).toBe(
      400,
    );

    await signedIn(false);
    vi.resetModules();
    const anonymous = await import("@/app/api/v1/citations/resolve/route");
    expect(
      (
        await anonymous.GET(
          resolveUrl(`q=${encodeURIComponent("arXiv:2308.04079 (2023)")}`),
        )
      ).status,
    ).toBe(401);
  });

  it("throttles a reader after 60 lookups in ten minutes", async () => {
    await signedIn(true);
    const route = await import("@/app/api/v1/citations/resolve/route");
    let last = 0;
    for (let i = 0; i < 61; i++) {
      last = (
        await route.GET(
          resolveUrl(
            `q=${encodeURIComponent(`arXiv:2308.0${4000 + i} (2023)`)}`,
          ),
        )
      ).status;
    }
    expect(last).toBe(429);
  });
});

import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

type Resolver = typeof import("@/lib/library/context/reference-resolve");

const ENTRY_NO_URL =
  "Vaswani, A., Shazeer, N., Parmar, N., Uszkoreit, J. Attention is all you need. In: NeurIPS (2017)";

function arxivFeed(entries: { id: string; title: string }[]): string {
  return `<?xml version="1.0"?><feed>${entries
    .map(
      (entry) =>
        `<entry><id>http://arxiv.org/abs/${entry.id}</id><title>${entry.title}</title></entry>`,
    )
    .join("")}</feed>`;
}

function crossrefWorks(items: { doi: string; title: string }[]): string {
  return JSON.stringify({
    message: {
      items: items.map((item) => ({ DOI: item.doi, title: [item.title] })),
    },
  });
}

const fetchedUrls: string[] = [];

function stubFetch(body: string | null): void {
  vi.stubGlobal("fetch", async (url: string) => {
    fetchedUrls.push(url);
    return body === null
      ? new Response("nope", { status: 503 })
      : new Response(body, { status: 200 });
  });
}

/** Route by host: arXiv and Crossref each answer with their body, 503 on null. */
function stubSearches(routes: {
  arxiv: string | null;
  crossref: string | null;
}): void {
  vi.stubGlobal("fetch", async (url: string) => {
    fetchedUrls.push(url);
    const body =
      new URL(url).hostname === "api.crossref.org"
        ? routes.crossref
        : routes.arxiv;
    return body === null
      ? new Response("nope", { status: 503 })
      : new Response(body, { status: 200 });
  });
}

let resolver: Resolver;

beforeEach(async () => {
  vi.resetModules();
  fetchedUrls.length = 0;
  resolver = await import("@/lib/library/context/reference-resolve");
});

afterEach(() => {
  vi.unstubAllGlobals();
});

describe("referenceUrlFromText", () => {
