  it("matches a title wrapped across lines when entries have no markers", async () => {
    await placePaper(
      "nlp",
      "attention",
      "Attention Is All You Need",
      "Body.\n\nReferences\n\n[1] Nothing relevant.",
    );
    await placePaper(
      "nlp",
      "follow-up",
