    const papers = await import("@/lib/library/papers");
    papers.writeText(
      "nlp",
      "draft",
      "Body.\n\nReferences\n\n[1] Vaswani, A. Attention is all you need. NeurIPS 2017.",
    );
    expect(citesEdges(buildLibraryGraph())).toEqual([
      "paper:draft->paper:attention",
    ]);
