import { describe, expect, it } from "vitest";
import {
  resolvePdfDestination,
  resolvePdfDestinationPage,
  type PdfDestinationDocument,
} from "@/lib/pdf/destinations";

function document(
  overrides: Partial<PdfDestinationDocument> = {},
): PdfDestinationDocument {
  return {
    numPages: 12,
    getDestination: async () => null,
    getPageIndex: async () => 0,
    ...overrides,
  };
}

describe("PDF destinations", () => {
  it("resolves a direct zero-based page destination", async () => {
    await expect(
      resolvePdfDestinationPage(document(), [4, { name: "Fit" }]),
    ).resolves.toBe(5);
  });

  it("preserves finite XYZ coordinates for a cropped reference preview", async () => {
    await expect(
      resolvePdfDestination(document(), [
        4,
        { name: "XYZ" },
        314.5,
        418.9,
        1.25,
      ]),
    ).resolves.toEqual({
      pageNumber: 5,
      kind: "XYZ",
      left: 314.5,
      top: 418.9,
      zoom: 1.25,
    });
  });

  it("resolves named destinations without moving the document", async () => {
    const pdf = document({
      getDestination: async (name) =>
        name === "reference-7" ? [{ num: 42, gen: 0 }] : null,
      getPageIndex: async (ref) => (ref.num === 42 ? 8 : 0),
    });

    await expect(resolvePdfDestinationPage(pdf, "reference-7")).resolves.toBe(
      9,
    );
  });

  it("resolves named XYZ destinations and ignores malformed coordinates", async () => {
    const pdf = document({
      getDestination: async () => [
        { num: 42, gen: 0 },
        { name: "XYZ" },
        Number.NaN,
        652,
        null,
      ],
      getPageIndex: async () => 8,
    });

    await expect(resolvePdfDestination(pdf, "reference-7")).resolves.toEqual({
      pageNumber: 9,
      kind: "XYZ",
      left: null,
      top: 652,
      zoom: null,
    });
  });

  it("keeps page-only fallbacks for non-XYZ destinations", async () => {
    await expect(
      resolvePdfDestination(document(), [2, { name: "FitH" }, 510]),
    ).resolves.toEqual({
      pageNumber: 3,
      kind: "FitH",
      left: null,
      top: null,
      zoom: null,
    });
  });

  it("rejects malformed and out-of-range destinations", async () => {
    const pdf = document();

    await expect(resolvePdfDestinationPage(pdf, [])).resolves.toBeNull();
    await expect(
      resolvePdfDestinationPage(pdf, ["not-a-page"]),
    ).resolves.toBeNull();
    await expect(
      resolvePdfDestinationPage(pdf, [99, { name: "Fit" }]),
    ).resolves.toBeNull();
  });

  it("returns null when a page reference cannot be resolved", async () => {
    const pdf = document({
      getPageIndex: async () => {
        throw new Error("missing page");
      },
    });

    await expect(
      resolvePdfDestinationPage(pdf, [{ num: 7, gen: 0 }]),
    ).resolves.toBeNull();
  });
});

import { describe, expect, it, vi } from "vitest";
import { createPdfAutosave } from "@/lib/pdf/autosave";

function deferred(): {
  promise: Promise<void>;
  resolve(): void;
} {
  let resolve = (): void => undefined;
  const promise = new Promise<void>((done) => {
    resolve = done;
  });
  return { promise, resolve };
}

describe("PDF autosave coordinator", () => {
  it("serializes a later edit after an in-flight save", async () => {
    vi.useFakeTimers();
    const first = deferred();
    const saves: Promise<void>[] = [first.promise, Promise.resolve()];
    const save = vi.fn(async () => {
      await saves.shift();
    });
    const states: { dirty: boolean; saving: boolean }[] = [];
    const autosave = createPdfAutosave({
      delayMs: 100,
      save,
      onChange: ({ dirty, saving }) => states.push({ dirty, saving }),
    });

    autosave.markDirty();
    await vi.advanceTimersByTimeAsync(100);
    expect(save).toHaveBeenCalledTimes(1);

    autosave.markDirty();
    first.resolve();
    await first.promise;
    await vi.runAllTimersAsync();

    expect(save).toHaveBeenCalledTimes(2);
    expect(autosave.state()).toMatchObject({ dirty: false, saving: false });
    expect(states).toContainEqual({ dirty: true, saving: false });
    vi.useRealTimers();
  });

  it("retains dirty state after a failed save and retries explicitly", async () => {
    const save = vi
      .fn<() => Promise<void>>()
      .mockRejectedValueOnce(new Error("conflict"))
      .mockResolvedValueOnce();
    const autosave = createPdfAutosave({
      delayMs: 60_000,
      save,
      onChange: () => undefined,
    });

    autosave.markDirty();
    await autosave.flush();
    expect(autosave.state()).toMatchObject({
      dirty: true,
      saving: false,
      error: expect.any(Error),
    });

    await autosave.flush();
    expect(save).toHaveBeenCalledTimes(2);
    expect(autosave.state()).toMatchObject({ dirty: false, error: null });
    autosave.stop();
  });

  it("does not save while remote changes have paused the coordinator", async () => {
    const save = vi.fn(async () => undefined);
    const autosave = createPdfAutosave({
      delayMs: 0,
      save,
      onChange: () => undefined,
    });

    autosave.pause();
    autosave.markDirty();
    await autosave.flush();
    expect(save).not.toHaveBeenCalled();

    autosave.resume();
    await autosave.flush();
    expect(save).toHaveBeenCalledOnce();
    autosave.stop();
  });
});

import { describe, expect, it } from "vitest";
import {
  buildBibliography,
  matchCitation,
  pageLines,
  type Bibliography,
  type BibliographyPage,
} from "@/lib/pdf/bibliography";
import aaaiPages from "./fixtures/aaai-pages.json";
import attentionPages from "./fixtures/attention-pages.json";
import pixworldRefs from "./fixtures/pixworld-refs.json";

// Real extracted text geometry (see fixtures/extract.mjs):
// - aaai-pages: arXiv 2608.07463 — author-year, two columns, no hanging
//   indent, no embedded cite links. Pages 1 (intro), 8-9 (references).
// - attention-pages: arXiv 1706.03762 — numbered [n] bibliography with a
//   hanging indent. Pages 2 (intro), 10-11 (references).
// - pixworld-refs: ICLR template — small-caps "R EFERENCES" heading, single
//   column with a hanging indent, two same-surname entries (Gao 2024/2026).
//   Pages 10-11 (references).
const AAAI = aaaiPages as BibliographyPage[];
const ATTENTION = attentionPages as BibliographyPage[];
const PIXWORLD = pixworldRefs as BibliographyPage[];

function aaaiBibliography(): Bibliography {
  const bibliography = buildBibliography(
    AAAI.filter((page) => page.pageNumber !== 1),
  );
  expect(bibliography).not.toBeNull();
  return bibliography!;
}

function attentionBibliography(): Bibliography {
  const bibliography = buildBibliography(
    ATTENTION.filter((page) => page.pageNumber !== 2),
  );
  expect(bibliography).not.toBeNull();
  return bibliography!;
}

describe("pageLines", () => {
  it("never merges text across columns that share y coordinates", () => {
    const page = AAAI.find((candidate) => candidate.pageNumber === 9)!;
    const lines = pageLines(page);
    // Without per-column clustering these two collide at the same y.
    const artifact = lines.find((line) => line.text.includes("MirrorChu"));
    expect(artifact).toBeUndefined();
    expect(lines.some((line) => line.text.includes("Progressive Mirror"))).toBe(
      true,
    );
  });

  // Two columns at x=50/x=320 where blank chunks and recurring italic runs
  // both sit mid-page. Either one, if allowed to define a column, pulls the
  // right column's base into the gutter — every entry there then reads as a
  // continuation line and the column yields no references at all.
  it("keeps mid-page blanks and italic runs from inventing a column", () => {
    const chunks = [];
    for (let row = 0; row < 6; row += 1) {
      const y = 700 - row * 12;
      chunks.push({ str: `Left author ${row}. 2020. Title.`, x: 50, y });
      // The left column's line tails reach past mid-page, each at its own x.
      chunks.push({ str: "tail", x: 270 + row * 5, y });
      chunks.push({ str: "  ", x: 275, y });
      chunks.push({ str: "ACM Trans. Graph.", x: 195, y });
      chunks.push({ str: `Right author ${row}. 2021. Title.`, x: 320, y });
    }
    const lines = pageLines({ pageNumber: 1, pageWidth: 612, chunks });
    const right = lines.filter((line) => line.text.startsWith("Right author"));
    expect(right).toHaveLength(6);
    expect(right.every((line) => line.x === 320)).toBe(true);
  });
});

describe("buildBibliography (author-year, AAAI)", () => {
  it("detects the style and segments entries without a hanging indent", () => {
    const bibliography = aaaiBibliography();
    expect(bibliography.style).toBe("author-year");
    // The paper cites ~50 works; segmentation must be in that ballpark,
    // not one giant entry or one entry per line.
    expect(bibliography.entries.length).toBeGreaterThan(30);
    expect(bibliography.entries.length).toBeLessThan(70);
  });

  it("parses surname, year, and natbib suffix from entry heads", () => {
    const bibliography = aaaiBibliography();
    const haCohen = bibliography.entries.find(
      (entry) => entry.surname === "HaCohen",
    );
    expect(haCohen).toMatchObject({ year: "2024", pageNumber: 8 });
    expect(haCohen!.text).toContain("LTX-Video");
    const suffixed = bibliography.entries.filter(
      (entry) => entry.surname === "Yang" && entry.year === "2025",
    );
    expect(suffixed.map((entry) => entry.suffix).sort()).toEqual(["a", "b"]);
  });

  it("keeps an entry whole across a column break mid-author-list", () => {
    // The Wan 2025 entry's author list wraps into the next column, where
    // its continuation line ("Xu, X.; Kou, Y.; …") looks like an entry head.
    const bibliography = aaaiBibliography();
    const wan = bibliography.entries.find(
      (entry) => entry.surname === "Wan" && entry.year === "2025",
    );
    expect(wan).toBeDefined();
    expect(wan!.text).toContain("Open and Advanced Large-Scale Video");
    // The continuation line topping the next column must not have become
    // its own entry ("Xu, K. … ZOOM" is a real, different entry).
    expect(
      bibliography.entries.find((entry) => entry.text.startsWith("Xu, X.")),
    ).toBeUndefined();
  });

  it("resolves the paper's own introduction citations", () => {
    const bibliography = aaaiBibliography();
    const yang = matchCitation(bibliography, {
      kind: "authorYear",
      surname: "Yang",
      year: "2025",
      suffix: "b",
    });
    expect(yang?.text).toContain("CogVideoX");
    const haCohen = matchCitation(bibliography, {
      kind: "authorYear",
      surname: "HaCohen",
      year: "2024",
      suffix: null,
    });
    expect(haCohen?.text).toContain("LTX-Video");
    const wan = matchCitation(bibliography, {
      kind: "authorYear",
      surname: "Wan",
      year: "2025",
      suffix: null,
    });
    expect(wan?.text).toContain("Wan");
  });

  it("returns null for ambiguity and for keys with no entry", () => {
    const bibliography = aaaiBibliography();
    // Yang 2025 without a suffix is ambiguous between 2025a and 2025b.
    expect(
      matchCitation(bibliography, {
        kind: "authorYear",
        surname: "Yang",
        year: "2025",
        suffix: null,
      }),
    ).toBeNull();
    expect(
      matchCitation(bibliography, {
        kind: "authorYear",
        surname: "Smith",
        year: "2020",
        suffix: null,
      }),
    ).toBeNull();
    // Numeric keys never resolve against an author-year bibliography —
    // this is what kills [0, 1] math intervals.
    expect(
      matchCitation(bibliography, { kind: "numeric", number: 1 }),
    ).toBeNull();
  });
});

describe("buildBibliography (numbered, hanging indent)", () => {
  it("detects the numbered style and finds the heading mid-page", () => {
    const bibliography = attentionBibliography();
    expect(bibliography.style).toBe("numbered");
    const numbers = bibliography.entries
      .map((entry) => entry.number)
      .filter((number): number is number => number !== null);
    expect(numbers).toContain(1);
    expect(numbers).toContain(5);
    expect(new Set(numbers).size).toBe(numbers.length);
  });

  it("indexes entries across the page break", () => {
    const bibliography = attentionBibliography();
    const two = matchCitation(bibliography, { kind: "numeric", number: 2 });
    expect(two?.pageNumber).toBe(10);
    expect(two?.text).toContain("Bahdanau");
    const five = matchCitation(bibliography, { kind: "numeric", number: 5 });
    expect(five?.pageNumber).toBe(11);
    expect(five?.text).toContain("Learning phrase representations");
  });

  it("rejects out-of-range numbers", () => {
    const bibliography = attentionBibliography();
    expect(
      matchCitation(bibliography, { kind: "numeric", number: 999 }),
    ).toBeNull();
  });
});

describe("buildBibliography guards", () => {
  it("returns null without a References heading", () => {
    const intro = AAAI.filter((page) => page.pageNumber === 1);
    expect(buildBibliography(intro)).toBeNull();
    expect(buildBibliography([])).toBeNull();
  });
});

describe("small-caps headings", () => {
  // The ICLR/NeurIPS templates set section heads in small caps, which the
  // text layer emits as "R EFERENCES" — one chunk per case change. Missing
  // it left the whole paper without a bibliography, so no citation in it
  // could resolve at all.
  it("finds the references section behind a small-caps heading", () => {
    const bibliography = buildBibliography(PIXWORLD);
    expect(bibliography?.style).toBe("author-year");
    expect(bibliography?.entries.length).toBeGreaterThan(20);
  });

  it("disambiguates same-surname entries by year", () => {
    const bibliography = buildBibliography(PIXWORLD)!;
    const cite = (year: string) =>
      matchCitation(bibliography, {
        kind: "authorYear",
        surname: "Gao",
        year,
        suffix: null,
      })?.text;
    expect(cite("2026")).toContain("Sensen Gao");
    expect(cite("2026")).toContain("Oneworld");
    expect(cite("2024")).toContain("Ruiqi Gao");
    expect(cite("2024")).toContain("Cat3d");
  });
});

import { describe, expect, it } from "vitest";
import { findCitations, type CitationKey } from "@/lib/pdf/citations";

function keys(text: string): CitationKey[] {
  return findCitations(text).map((citation) => citation.key);
}

describe("findCitations author-year", () => {
  it("finds every work in an AAAI-style multi-cite group split across lines", () => {
    // Verbatim from arXiv 2608.07463's introduction, with the text layer's
    // line breaks preserved.
    const text =
      "Recent advances in video diffusion models (VDMs) (Yang\n" +
      "et al. 2025b; Wan et al. 2025; Kong et al. 2024; HaCohen\n" +
      "et al. 2024) have enabled high-fidelity video synthesis";
    expect(keys(text)).toEqual([
      { kind: "authorYear", surname: "Yang", year: "2025", suffix: "b" },
      { kind: "authorYear", surname: "Wan", year: "2025", suffix: null },
      { kind: "authorYear", surname: "Kong", year: "2024", suffix: null },
      { kind: "authorYear", surname: "HaCohen", year: "2024", suffix: null },
    ]);
  });

  it("covers the author names with the first hotspot span", () => {
    const text = "supports movie creation (Xiao et al. 2026), and more";
    const [citation] = findCitations(text);
    expect(citation).toBeDefined();
    expect(text.slice(citation!.start, citation!.end)).toBe("Xiao et al. 2026");
  });

  it("finds narrative citations including the parenthesized year", () => {
    const text = "as Vaswani et al. (2017) demonstrated";
    const citations = findCitations(text);
    expect(citations.map((c) => c.key)).toEqual([
      { kind: "authorYear", surname: "Vaswani", year: "2017", suffix: null },
    ]);
    expect(text.slice(citations[0]!.start, citations[0]!.end)).toBe(
      "Vaswani et al. (2017)",
    );
  });

  it("handles APA commas, ampersands, and two-author forms", () => {
    expect(keys("(Smith & Jones, 2024)")).toEqual([
      { kind: "authorYear", surname: "Smith", year: "2024", suffix: null },
    ]);
    expect(keys("(Smith et al., 2020)")).toEqual([
      { kind: "authorYear", surname: "Smith", year: "2020", suffix: null },
    ]);
    expect(keys("(Smith and Jones 2024)")).toEqual([
      { kind: "authorYear", surname: "Smith", year: "2024", suffix: null },
    ]);
  });

  it("emits one citation per year for multi-work cites", () => {
    const text = "(Smith 2020, 2021b)";
    const citations = findCitations(text);
    expect(citations.map((c) => c.key)).toEqual([
      { kind: "authorYear", surname: "Smith", year: "2020", suffix: null },
      { kind: "authorYear", surname: "Smith", year: "2021", suffix: "b" },
    ]);
    expect(text.slice(citations[1]!.start, citations[1]!.end)).toBe("2021b");
  });

  it("keeps diacritics and nobiliary particles in the surname", () => {
    expect(keys("(Gülçehre et al. 2014)")).toEqual([
      { kind: "authorYear", surname: "Gülçehre", year: "2014", suffix: null },
    ]);
    expect(keys("(van der Berg 2019)")).toEqual([
      {
        kind: "authorYear",
        surname: "van der Berg",
        year: "2019",
        suffix: null,
      },
    ]);
  });

  it("re-joins a hyphenated surname split across a line break", () => {
    const [key] = keys("(Parker-\nHolder et al. 2023)");
    expect(key).toMatchObject({ kind: "authorYear", year: "2023" });
    expect((key as { surname: string }).surname.replace(/[\s-]/g, "")).toBe(
      "ParkerHolder",
    );
  });
});

describe("findCitations numeric", () => {
  it("gives each bracket-group member its own citation and span", () => {
    const text = "machine translation [35, 2, 5]. Numerous efforts";
    const citations = findCitations(text);
    expect(citations.map((c) => c.key)).toEqual([
      { kind: "numeric", number: 35 },
      { kind: "numeric", number: 2 },
      { kind: "numeric", number: 5 },
    ]);
    expect(text.slice(citations[0]!.start, citations[0]!.end)).toBe("35");
    expect(text.slice(citations[2]!.start, citations[2]!.end)).toBe("5");
  });

  it("keys a range member to its first number", () => {
    const text = "prior work [1–4, 7] shows";
    const citations = findCitations(text);
    expect(citations.map((c) => c.key)).toEqual([
      { kind: "numeric", number: 1 },
      { kind: "numeric", number: 7 },
    ]);
    expect(text.slice(citations[0]!.start, citations[0]!.end)).toBe("1–4");
  });

  it("finds single citations and hyphen ranges", () => {
    expect(keys("memory [13] and gated recurrent [7] networks")).toEqual([
      { kind: "numeric", number: 13 },
      { kind: "numeric", number: 7 },
    ]);
    expect(keys("architectures [38-40]")).toEqual([
      { kind: "numeric", number: 38 },
    ]);
  });
});

describe("findCitations rejections", () => {
  it("ignores parentheticals without a name-year shape", () => {
    expect(keys("(see Section 3)")).toEqual([]);
    expect(keys("a bare year (2025) is not a citation")).toEqual([]);
    expect(keys("the 2020s were formative")).toEqual([]);
  });

  it("ignores year-like tokens in bibliography prose", () => {
    // Real continuation lines from arXiv 2608.07463's references.
    expect(
      keys(
        "International Conference on Learning Representations, vol-\n" +
          "ume 2025, 102075–102121.",
      ),
    ).toEqual([]);
    expect(keys("arXiv preprint arXiv:2501.00103.")).toEqual([]);
  });

  it("ignores brackets holding anything but citation numbers", () => {
    expect(keys("the interval [0, a] is closed")).toEqual([]);
    expect(keys("tensors of shape [B, T, C]")).toEqual([]);
  });

  it("reports pattern-level look-alikes for the bibliography gate to kill", () => {
    // These are citation-shaped; only bibliography resolution can rule them
    // out, so the detector must keep them.
    expect(keys("the interval [0, 1] is closed")).toEqual([
      { kind: "numeric", number: 0 },
      { kind: "numeric", number: 1 },
    ]);
    expect(keys("(see Smith 2020)")).toEqual([
      { kind: "authorYear", surname: "Smith", year: "2020", suffix: null },
    ]);
  });

  it("returns sorted, non-overlapping citations for mixed styles", () => {
    const text = "Zhu et al. (2013) [40] improved parsing";
    const citations = findCitations(text);
    expect(citations.map((c) => c.key)).toEqual([
      { kind: "authorYear", surname: "Zhu", year: "2013", suffix: null },
      { kind: "numeric", number: 40 },
    ]);
    const [first, second] = citations;
    expect(first!.end).toBeLessThanOrEqual(second!.start);
  });
});

import { afterEach, beforeEach, describe, expect, it } from "vitest";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { fileResponse } from "@/lib/http/file-range";

const BODY = "0123456789ABCDEF";
let tmpDir: string;
let filePath: string;

beforeEach(() => {
  tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), "papernook-range-"));
  filePath = path.join(tmpDir, "paper.pdf");
  fs.writeFileSync(filePath, BODY);
});

afterEach(() => {
  fs.rmSync(tmpDir, { recursive: true, force: true });
});

function serve(headers: Record<string, string> = {}) {
  return fileResponse({
    path: filePath,
    size: BODY.length,
    etag: '"abc"',
    headers: new Headers(headers),
    contentType: "application/pdf",
    filename: "paper.pdf",
    cacheControl: "private, no-cache",
  });
}

describe("fileResponse", () => {
  it("serves the whole file and advertises range support", async () => {
    const response = serve();
    expect(response.status).toBe(200);
    expect(response.headers.get("accept-ranges")).toBe("bytes");
    expect(response.headers.get("content-length")).toBe(String(BODY.length));
    expect(await response.text()).toBe(BODY);
  });

  it("serves only the requested byte range", async () => {
    const response = serve({ range: "bytes=4-7" });
    expect(response.status).toBe(206);
    expect(response.headers.get("content-range")).toBe("bytes 4-7/16");
    expect(response.headers.get("content-length")).toBe("4");
    expect(await response.text()).toBe("4567");
  });

  it("serves an open-ended range to the end of the file", async () => {
    const response = serve({ range: "bytes=12-" });
    expect(response.status).toBe(206);
    expect(response.headers.get("content-range")).toBe("bytes 12-15/16");
    expect(await response.text()).toBe("CDEF");
  });

  it("serves a suffix range as the trailing bytes", async () => {
    const response = serve({ range: "bytes=-4" });
    expect(response.status).toBe(206);
    expect(await response.text()).toBe("CDEF");
  });

  it("clamps a range that runs past the end of the file", async () => {
    const response = serve({ range: "bytes=14-99" });
    expect(response.status).toBe(206);
    expect(response.headers.get("content-range")).toBe("bytes 14-15/16");
    expect(await response.text()).toBe("EF");
  });

  it("rejects a range that starts past the end of the file", async () => {
    const response = serve({ range: "bytes=99-" });
    expect(response.status).toBe(416);
    expect(response.headers.get("content-range")).toBe("bytes */16");
  });

  it("falls back to the whole file for an unparsable range", async () => {
    const response = serve({ range: "pages=1-2" });
    expect(response.status).toBe(200);
    expect(await response.text()).toBe(BODY);
  });

  it("answers a matching if-none-match with an empty 304", async () => {
    const response = serve({ "if-none-match": '"abc"' });
    expect(response.status).toBe(304);
    expect(response.headers.get("etag")).toBe('"abc"');
    expect(await response.text()).toBe("");
  });

  it("sends the file when if-none-match holds a stale version", async () => {
    const response = serve({ "if-none-match": '"stale"' });
    expect(response.status).toBe(200);
    expect(await response.text()).toBe(BODY);
  });
});

import { createTestProfile, mockTestSession } from "../../helpers/access";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { NextRequest } from "next/server";
import { PDFDocument } from "pdf-lib";

let tmpDir: string;

beforeEach(() => {
  tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), "papernook-pdf-file-"));
  process.env.PAPERNOOK_DATA_DIR = tmpDir;
  process.env.SESSION_SECRET = "s".repeat(64);
  vi.resetModules();
});

afterEach(() => {
  vi.doUnmock("next/headers");
  vi.unstubAllEnvs();
  fs.rmSync(tmpDir, { recursive: true, force: true });
});

async function makePdf(label: string): Promise<Uint8Array> {
  const document = await PDFDocument.create();
  const page = document.addPage([400, 600]);
  page.drawText(label, { x: 40, y: 540 });
  return document.save();
}

async function placePaper(): Promise<string> {
  const { ensureDataDirs } = await import("@/lib/data-dir");
  const papers = await import("@/lib/library/papers");
  ensureDataDirs();
  papers.writeMeta("nlp", "attention", {
    title: "Attention",
    authors: [],
    year: 2017,
    venue: null,
    arxivId: null,
    bibtex: null,
    tags: [],
    related: [],
    sourceUrl: "https://example.test/attention.pdf",
    addedAt: new Date().toISOString(),
    addedBy: "andres",
  });
  const pdfPath = papers.pdfPath("nlp", "attention");
  fs.mkdirSync(path.dirname(pdfPath), { recursive: true });
  fs.writeFileSync(pdfPath, await makePdf("original"));
  const old = new Date(Date.now() - 60_000);
  fs.utimesSync(pdfPath, old, old);
  return pdfPath;
}

async function signedInAs(username: string | null): Promise<void> {
  await mockTestSession(username);
}

describe("versioned PDF files", () => {
  it("atomically replaces the expected PDF and returns its new version", async () => {
    const pdfPath = await placePaper();
    const { pdfEtag, readVersionedPdf, replacePdf } =
      await import("@/lib/library/pdf/file");
    const opened = await readVersionedPdf("nlp", "attention");
    const annotated = await makePdf("annotated");

    const saved = await replacePdf("nlp", "attention", opened!.etag, annotated);

    expect(saved.etag).toBe(pdfEtag(annotated));
    expect(await PDFDocument.load(fs.readFileSync(pdfPath))).toBeInstanceOf(
      PDFDocument,
    );
    expect(
      fs
        .readdirSync(path.dirname(pdfPath))
        .some((name) => name.endsWith(".tmp")),
    ).toBe(false);
  });

  it("rejects a PDF truncated in transit and keeps the file intact", async () => {
    const pdfPath = await placePaper();
    const before = fs.readFileSync(pdfPath);
    const { InvalidPdfError, readVersionedPdf, replacePdf } =
      await import("@/lib/library/pdf/file");
    const opened = await readVersionedPdf("nlp", "attention");
    const annotated = await makePdf("annotated");
    const truncated = annotated.subarray(
      0,
      Math.floor(annotated.byteLength / 2),
    );

    await expect(
      replacePdf("nlp", "attention", opened!.etag, truncated),
    ).rejects.toThrow(InvalidPdfError);
    expect(fs.readFileSync(pdfPath)).toEqual(before);
  });

  it("never overwrites a PDF changed after the reader opened it", async () => {
    const pdfPath = await placePaper();
    const { PdfConflictError, readVersionedPdf, replacePdf } =
      await import("@/lib/library/pdf/file");
    const opened = await readVersionedPdf("nlp", "attention");
    const external = await makePdf("new Pencil ink");
    fs.writeFileSync(pdfPath, external);

    await expect(
      replacePdf(
        "nlp",
        "attention",
        opened!.etag,
        await makePdf("stale browser edit"),
      ),
    ).rejects.toThrow(PdfConflictError);
    expect(fs.readFileSync(pdfPath)).toEqual(Buffer.from(external));
  });

  it("rejects a rewrite when another editor saves during the transform", async () => {
    const pdfPath = await placePaper();
    const { PdfConflictError, readVersionedPdf, rewritePdf } =
      await import("@/lib/library/pdf/file");
    const opened = await readVersionedPdf("nlp", "attention");
    const external = await makePdf("new Pencil ink");
    const rewritten = await makePdf("browser comment");
    await expect(
      rewritePdf(
        "nlp",
        "attention",
        async () => {
          fs.writeFileSync(pdfPath, external);
          return rewritten;
        },
        opened!.etag,
      ),
    ).rejects.toThrow(PdfConflictError);
    expect(fs.readFileSync(pdfPath)).toEqual(Buffer.from(external));
  });
});

describe("authenticated PDF route", () => {
  it("reports the current version without returning the PDF body", async () => {
    const pdfPath = await placePaper();
    await createTestProfile("Andres");
    await signedInAs("andres");
    const route = await import("@/app/api/v1/papers/[topic]/[slug]/pdf/route");
    const params = {
      params: Promise.resolve({ topic: "nlp", slug: "attention" }),
    };
    const request = new NextRequest(
      "http://localhost/api/v1/papers/nlp/attention/pdf",
      { method: "HEAD" },
    );

    const opened = await route.GET(request, params);
    const unchanged = await route.HEAD(request, params);

    expect(unchanged.status).toBe(200);
    expect(unchanged.headers.get("etag")).toBe(opened.headers.get("etag"));
    expect(await unchanged.text()).toBe("");

    fs.writeFileSync(pdfPath, await makePdf("external Pencil edit"));
    expect((await route.HEAD(request, params)).status).toBe(409);

    const old = new Date(Date.now() - 60_000);
    fs.utimesSync(pdfPath, old, old);
    const changed = await route.HEAD(request, params);
    expect(changed.status).toBe(200);
    expect(changed.headers.get("etag")).not.toBe(opened.headers.get("etag"));
  });

  it("requires a signed-in profile to check a PDF version", async () => {
    await placePaper();
    await signedInAs(null);
    const route = await import("@/app/api/v1/papers/[topic]/[slug]/pdf/route");
    const response = await route.HEAD(
      new NextRequest("http://localhost/api/v1/papers/nlp/attention/pdf", {
        method: "HEAD",
      }),
      { params: Promise.resolve({ topic: "nlp", slug: "attention" }) },
    );

    expect(response.status).toBe(401);
  });

  it("serves a byte range so the reader can render before the file lands", async () => {
    await placePaper();
    await createTestProfile("Andres");
    await signedInAs("andres");
    const route = await import("@/app/api/v1/papers/[topic]/[slug]/pdf/route");
    const params = {
      params: Promise.resolve({ topic: "nlp", slug: "attention" }),
    };

    const whole = await route.GET(
      new NextRequest("http://localhost/api/v1/papers/nlp/attention/pdf"),
      params,
    );
    expect(whole.headers.get("accept-ranges")).toBe("bytes");
    const body = await whole.text();

    const head = await route.GET(
      new NextRequest("http://localhost/api/v1/papers/nlp/attention/pdf", {
        headers: { range: "bytes=0-7" },
      }),
      params,
    );
    expect(head.status).toBe(206);
    expect(await head.text()).toBe(body.slice(0, 8));
    expect(head.headers.get("etag")).toBe(whole.headers.get("etag"));
  });

  it("answers an unchanged PDF with a 304 instead of the bytes", async () => {
    await placePaper();
    await createTestProfile("Andres");
    await signedInAs("andres");
    const route = await import("@/app/api/v1/papers/[topic]/[slug]/pdf/route");
    const params = {
      params: Promise.resolve({ topic: "nlp", slug: "attention" }),
    };

    const opened = await route.GET(
      new NextRequest("http://localhost/api/v1/papers/nlp/attention/pdf"),
      params,
    );
    const etag = opened.headers.get("etag") ?? "";

    const revalidated = await route.GET(
      new NextRequest("http://localhost/api/v1/papers/nlp/attention/pdf", {
        headers: { "if-none-match": etag },
      }),
      params,
    );
    expect(revalidated.status).toBe(304);
    expect(await revalidated.text()).toBe("");
  });

  it("round-trips a native PDF save and rejects the stale version", async () => {
    await placePaper();
    await createTestProfile("Andres");
    await signedInAs("andres");
    const route = await import("@/app/api/v1/papers/[topic]/[slug]/pdf/route");
    const params = {
      params: Promise.resolve({ topic: "nlp", slug: "attention" }),
    };

    const opened = await route.GET(
      new NextRequest("http://localhost/api/v1/papers/nlp/attention/pdf"),
      params,
    );
    const etag = opened.headers.get("etag");
    expect(opened.status).toBe(200);
    expect(etag).toMatch(/^"[a-f0-9]{64}"$/);
    // no-cache keeps every open revalidating against the save version;
    // no-store would forbid the 304 that spares a 20 MB re-download.
    expect(opened.headers.get("cache-control")).toContain("private");
    expect(opened.headers.get("cache-control")).toContain("no-cache");

    const annotated = await makePdf("web annotation");
    const saved = await route.PUT(
      new NextRequest("http://localhost/api/v1/papers/nlp/attention/pdf", {
        method: "PUT",
        headers: {
          "content-type": "application/pdf",
          "if-match": etag!,
        },
        body: new Uint8Array(annotated).buffer,
      }),
      params,
    );
    expect(saved.status).toBe(200);
    const savedEtag = saved.headers.get("etag");
    expect(savedEtag).not.toBe(etag);

    const savedAgain = await route.PUT(
      new NextRequest("http://localhost/api/v1/papers/nlp/attention/pdf", {
        method: "PUT",
        headers: {
          "content-type": "application/pdf",
          "if-match": savedEtag!,
        },
        body: new Uint8Array(await makePdf("second web annotation")).buffer,
      }),
      params,
    );
    expect(savedAgain.status).toBe(200);

    const stale = await route.PUT(
      new NextRequest("http://localhost/api/v1/papers/nlp/attention/pdf", {
        method: "PUT",
        headers: {
          "content-type": "application/pdf",
          "if-match": etag!,
        },
        body: new Uint8Array(await makePdf("stale")).buffer,
      }),
      params,
    );
    expect(stale.status).toBe(412);
    expect(await stale.json()).toMatchObject({
      error: expect.stringContaining("Reload before saving"),
    });
  });

  it("rejects saves that arrive truncated instead of writing them", async () => {
    const pdfPath = await placePaper();
    const before = fs.readFileSync(pdfPath);
    await createTestProfile("Andres");
    await signedInAs("andres");
    const route = await import("@/app/api/v1/papers/[topic]/[slug]/pdf/route");
    const params = {
      params: Promise.resolve({ topic: "nlp", slug: "attention" }),
    };
    const etag = (
      await route.GET(
        new NextRequest("http://localhost/api/v1/papers/nlp/attention/pdf"),
        params,
      )
    ).headers.get("etag");
    const annotated = await makePdf("web annotation");

    // Body cut off mid-stream: the PDF trailer never arrives.
    const cutOff = await route.PUT(
      new NextRequest("http://localhost/api/v1/papers/nlp/attention/pdf", {
        method: "PUT",
        headers: { "content-type": "application/pdf", "if-match": etag! },
        body: annotated.slice(0, Math.floor(annotated.byteLength / 2))
          .buffer as ArrayBuffer,
      }),
      params,
    );
    expect(cutOff.status).toBe(422);

    // Intact body but shorter than the length the client declared.
    const shortened = await route.PUT(
      new NextRequest("http://localhost/api/v1/papers/nlp/attention/pdf", {
        method: "PUT",
        headers: {
          "content-type": "application/pdf",
          "if-match": etag!,
          "content-length": String(annotated.byteLength * 2),
        },
        body: new Uint8Array(annotated).buffer,
      }),
      params,
    );
    expect(shortened.status).toBe(422);
    expect(await shortened.json()).toMatchObject({
      error: expect.stringContaining("incomplete"),
    });
    expect(fs.readFileSync(pdfPath)).toEqual(before);
  });

  it("requires a signed-in profile, PDF content type, and opened version", async () => {
    await placePaper();
    await signedInAs(null);
    let route = await import("@/app/api/v1/papers/[topic]/[slug]/pdf/route");
    const params = {
      params: Promise.resolve({ topic: "nlp", slug: "attention" }),
    };
    const request = () =>
      new NextRequest("http://localhost/api/v1/papers/nlp/attention/pdf", {
        method: "PUT",
        body: "not a PDF",
      });
    expect((await route.PUT(request(), params)).status).toBe(401);

    vi.resetModules();
    await createTestProfile("Andres");
    await signedInAs("andres");
    route = await import("@/app/api/v1/papers/[topic]/[slug]/pdf/route");
    expect((await route.PUT(request(), params)).status).toBe(400);
  });
});

import { describe, expect, it } from "vitest";
import {
  captionPattern,
  destinationCandidates,
  findPaperRefs,
  type PaperRef,
} from "@/lib/pdf/paper-refs";

function refs(text: string): [PaperRef["kind"], string][] {
  return findPaperRefs(text).map((ref) => [ref.kind, ref.label]);
}

describe("findPaperRefs", () => {
  it("finds figures, tables, and equations in prose", () => {
    expect(
      refs("As Figure 3 shows (cf. Table 2), Eq. (5) bounds the loss."),
    ).toEqual([
      ["figure", "3"],
      ["table", "2"],
      ["equation", "5"],
    ]);
  });

  it("finds abbreviated and parenthesized section refs", () => {
    expect(refs("the paper reports (Sec. 4.3) that pruning breaks")).toEqual([
      ["section", "4.3"],
    ]);
    expect(refs("see §2.1 and Section 5")).toEqual([
      ["section", "2.1"],
      ["section", "5"],
    ]);
  });

  it("finds appendices, algorithms, and theorem-like refs", () => {
    expect(
      refs("Appendix B.2 proves Theorem 1 used by Algorithm 2 and Lemma 3"),
    ).toEqual([
      ["appendix", "B.2"],
      ["theorem", "1"],
      ["algorithm", "2"],
      ["lemma", "3"],
    ]);
  });

  it("finds appendix and supplement-style locators", () => {
    expect(
      refs("Eq. (A.1), Figure S1, and Table S2 support Appendix B."),
    ).toEqual([
      ["equation", "A.1"],
      ["figure", "S1"],
      ["table", "S2"],
      ["appendix", "B"],
    ]);
  });

  it("reports match offsets that cover the whole reference", () => {
    const text = "see Eq. (12) here";
    const [ref] = findPaperRefs(text);
    expect(text.slice(ref!.start, ref!.end)).toBe("Eq. (12)");
  });

  it("skips references into other papers", () => {
    expect(refs("Figure 3 of [12] uses the same setup")).toEqual([]);
    expect(refs("Sec. 2 in Smith et al. defines it")).toEqual([]);
    expect(refs("Figure 3 in the appendix")).toEqual([["figure", "3"]]);
  });

  it("skips words without labels and numeric appendix labels", () => {
    expect(refs("the figure below has no printed locator")).toEqual([]);
    expect(refs("Appendix 3 is not a thing either")).toEqual([]);
  });

  it("requires capitalized reference words", () => {
    expect(refs("a section 2 subgroup of order 4")).toEqual([]);
  });
});

describe("destinationCandidates", () => {
  it("maps sections depth-aware", () => {
    expect(destinationCandidates({ kind: "section", label: "4" })).toEqual([
      "section.4",
    ]);
    expect(destinationCandidates({ kind: "section", label: "4.3" })[0]).toBe(
      "subsection.4.3",
    );
    expect(destinationCandidates({ kind: "section", label: "4.3.1" })[0]).toBe(
      "subsubsection.4.3.1",
    );
  });

  it("treats letter-led section labels as appendices", () => {
    expect(destinationCandidates({ kind: "section", label: "B" })).toEqual([
      "appendix.B",
      "section.B",
    ]);
    expect(destinationCandidates({ kind: "appendix", label: "B.1" })).toEqual([
      "subsection.B.1",
      "appendix.B.1",
    ]);
  });

  it("covers unsectioned equation numbering", () => {
    expect(destinationCandidates({ kind: "equation", label: "5" })).toEqual([
      "equation.5",
      "equation.0.5",
    ]);
    expect(destinationCandidates({ kind: "equation", label: "4.5" })).toEqual([
      "equation.4.5",
    ]);
    expect(destinationCandidates({ kind: "equation", label: "A.1" })).toEqual([
      "equation.A.1",
    ]);
    expect(destinationCandidates({ kind: "figure", label: "S1" })).toEqual([
      "figure.S1",
    ]);
  });

  it("lists common theorem-environment abbreviations", () => {
    expect(destinationCandidates({ kind: "theorem", label: "1" })).toEqual([
      "theorem.1",
      "thm.1",
    ]);
    expect(destinationCandidates({ kind: "algorithm", label: "2" })).toContain(
      "algocf.2",
    );
  });
});

describe("captionPattern", () => {
  it("matches figure captions with either separator", () => {
    const pattern = captionPattern({ kind: "figure", label: "3" })!;
    expect(pattern.test("Figure 3: Overview of the pipeline")).toBe(true);
    expect(pattern.test("Fig. 3. Overview of the pipeline")).toBe(true);
    expect(pattern.test("Figure 30: a different figure")).toBe(false);
    expect(pattern.test("see Figure 3: mid-line mention")).toBe(false);
    expect(
      captionPattern({ kind: "figure", label: "S1" })!.test(
        "Figure S1: Supplementary overview",
      ),
    ).toBe(true);
  });

  it("matches section headings without matching prose", () => {
    const pattern = captionPattern({ kind: "section", label: "4.3" })!;
    expect(pattern.test("4.3 Ablations")).toBe(true);
    expect(pattern.test("4.3.1 More ablations")).toBe(false);
  });

  it("skips author affiliation superscripts when locating Section 1", () => {
    const pattern = captionPattern({ kind: "section", label: "1" })!;
    // LoGo's text layer puts affiliation markers on their own lines.
    const lines = ["1 , 2 ∗ 2 2 2", "1 2", "1 I NTRODUCTION"];
    expect(lines.find((line) => pattern.test(line))).toBe("1 I NTRODUCTION");
  });

  it("accepts heading titles with numeric, quoted, and Unicode first words", () => {
    const section = captionPattern({ kind: "section", label: "1" })!;
    expect(section.test("1. 3D Consistency")).toBe(true);
    expect(section.test("1 “World” Models")).toBe(true);
    const appendix = captionPattern({ kind: "appendix", label: "B" })!;
    expect(appendix.test("B. Étude complémentaire")).toBe(true);
    expect(appendix.test("B 1 2")).toBe(false);
  });

  it("returns null for equations", () => {
    expect(captionPattern({ kind: "equation", label: "5" })).toBeNull();
  });
});

