describe("local note draft from selected annotations", () => {
  it("orders selected passages by page and keeps comments separate from quoted evidence with return links", () => {
    const selected = [annotation("last", 4), annotation("first", 1)];
    const draft = annotationNoteDraft(paper, selected);
    expect(selected.map((item) => item.id)).toEqual(["last", "first"]);
    expect(draft.body.indexOf("## 第 1 页")).toBeLessThan(
      draft.body.indexOf("## 第 4 页"),
    );
    expect(draft.body).toContain("> 原文 first\n> 下一行");
    expect(draft.body).toContain("**批注**\n\n评论 first");
    expect(draft.body).toContain(
      "[返回原文第 4 页](/workspace?paperId=current-paper&page=4)",
    );
    expect(draft.sources).toEqual([
      {
        paperId: paper.id,
        page: 1,
        annotationId: "first",
        contentRevision: paper.contentRevision,
        title: paper.title,
        quote: "原文 first\n下一行",
      },
      {
        paperId: paper.id,
        page: 4,
        annotationId: "last",
        contentRevision: paper.contentRevision,
        title: paper.title,
        quote: "原文 last\n下一行",
      },
    ]);
  });

  it("includes only selected annotations, deduplicates IDs and never invents a source quote for a native comment", () => {
    const native = annotation("native", 2, {
      quote: "",
      text: "",
      comment: "这是我的解释，不是原文。",
    });
    const draft = annotationNoteDraft(paper, [native, native]);
    expect(draft.sources).toHaveLength(1);
    expect(draft.sources[0].quote).toBeUndefined();
    expect(draft.body).toContain("**批注**\n\n这是我的解释，不是原文。");
    expect(draft.body).not.toContain("> 这是我的解释");
    expect(draft.body).not.toContain("未选择的批注");
  });

  it("refuses missing selections, foreign or stale evidence and over-limit drafts instead of dropping content", () => {
    expect(() => annotationNoteDraft(paper, [])).toThrow("请先选择");
    expect(() =>
      annotationNoteDraft(paper, [
        annotation("other", 1, { paperId: "other-paper" }),
      ]),
    ).toThrow("不属于当前论文");
    expect(() =>
      annotationNoteDraft(paper, [
        annotation("old", 1, { contentRevision: "old" }),
      ]),
    ).toThrow("旧版正文");
    expect(() =>
      annotationNoteDraft(paper, [annotation("bad-page", 6)]),
    ).toThrow("页码超出");
    expect(() =>
      annotationNoteDraft(
        paper,
        Array.from({ length: 201 }, (_, i) => annotation(`id-${i}`, 1)),
      ),
    ).toThrow("最多整理 200 条");
    expect(() =>
      annotationNoteDraft(
        paper,
        Array.from({ length: 21 }, (_, i) =>
          annotation(`large-${i}`, 1, { comment: "字".repeat(10000) }),
        ),
      ),
    ).toThrow("内容过长");
  });
});

import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { handleResearchRequest } from "@/lib/research/api";
import { closeIndex } from "@/lib/library/index-db";

let root: string;

beforeEach(() => {
  root = fs.mkdtempSync(path.join(os.tmpdir(), "research-routing-"));
  vi.stubEnv("PAPERNOOK_DATA_DIR", root);
  vi.stubEnv("RESEARCH_DATA_DIR", path.join(root, "research"));
  vi.stubEnv("NODE_ENV", "test");
});

afterEach(() => {
  closeIndex();
  vi.unstubAllEnvs();
  fs.rmSync(root, { recursive: true, force: true });
});

function call(
  segments: string[],
  init?: { method?: string; headers?: HeadersInit; body?: string },
) {
  return new Request(`http://localhost/api/research/${segments.join("/")}`, {
    method: init?.method ?? "GET",
    headers: init?.headers,
    body: init?.body,
  });
}

describe("research API routing", () => {
  it("serves the workspace snapshot at the root", async () => {
    const response = await handleResearchRequest(call([]), []);
    expect(response.status).toBe(200);
    expect(Object.keys(await response.json())).toEqual(
      expect.arrayContaining(["papers", "notes", "history", "settings"]),
    );
  });

  it("routes health to the configured or unavailable service", async () => {
    const response = await handleResearchRequest(call(["health"]), ["health"]);
    expect([200, 503]).toContain(response.status);
    const payload = await response.json();
    expect(payload.health ?? payload.code).toBeDefined();
  });

  it("returns 404 for an unknown area and an unsupported method", async () => {
    const unknown = await handleResearchRequest(call(["nope"]), ["nope"]);
    expect(unknown.status).toBe(404);
    expect((await unknown.json()).error).toContain("不存在");

    const wrongMethod = await handleResearchRequest(
      call(["health"], { method: "POST" }),
      ["health"],
    );
    expect(wrongMethod.status).toBe(404);
  });

  it("rejects malformed path segments before dispatch", async () => {
    const response = await handleResearchRequest(call(["bad segment"]), [
      "bad segment",
    ]);
    expect(response.status).toBe(400);
    expect((await response.json()).details[0].path).toBe("0");
  });

  it("refuses cross-origin writes while allowing same-origin writes", async () => {
    const crossOrigin = await handleResearchRequest(
      call(["settings"], {
        method: "PATCH",
        headers: {
          origin: "https://evil.example",
          "content-type": "application/json",
        },
        body: "{}",
      }),
      ["settings"],
    );
    expect(crossOrigin.status).toBe(403);

    const sameOrigin = await handleResearchRequest(
      call(["settings"], {
        method: "PATCH",
        headers: {
          origin: "http://localhost",
          "content-type": "application/json",
        },
        body: "{}",
      }),
      ["settings"],
    );
    expect(sameOrigin.status).not.toBe(403);
  });
});

import { describe, expect, it } from "vitest";
import { PDFDocument, PDFHexString, PDFName, PDFString } from "pdf-lib";
import { projectResearchComments } from "@/lib/research/comment-view";
import type { ResearchAnnotation } from "@/lib/research/types";

async function fixture() {
  const document = await PDFDocument.create();
  document.addPage([600, 800]);
  const add = (
    subtype: string,
    contents: string,
    name: string,
    owner?: string,
  ) => {
    const annotation = document.context.obj({
      Type: "Annot",
      Subtype: subtype,
      Rect: [40, 650, 240, 670],
      Contents: PDFHexString.fromText(contents),
      NM: PDFString.of(name),
      T: PDFHexString.fromText("同名显示作者"),
      ...(owner ? { PapernookAuthor: PDFString.of(owner) } : {}),
    });
    const ref = document.context.register(annotation);
    document.getPage(0).node.addAnnot(ref);
    return `${ref.objectNumber}R${ref.generationNumber || ""}`;
  };
  return { document, add };
}

const record: ResearchAnnotation = {
  id: "local-record",
  paperId: "paper",
  pdfName: "jy-shared-name",
  page: 1,
  text: "原文摘录",
  quote: "原文摘录",
  comment: "我的解释",
  color: "#f6c84c",
  rects: [[40, 650, 240, 670]],
  kind: "highlight",
  contentRevision: "current",
  version: 1,
  createdAt: "2026-10-31T00:00:00Z",
  updatedAt: "2026-10-31T00:00:00Z",
  pdfSaved: true,
};

describe("read-only PDF comment projection", () => {
  it("combines owned highlight segments and their companion into one card while preserving quote provenance", async () => {
    const { document, add } = await fixture();
    const ids = [
      add("Text", "我的解释", record.pdfName!, "local"),
      add("Highlight", "我的解释", record.pdfName!),
      add("Highlight", "我的解释", record.pdfName!),
    ];
    const projected = projectResearchComments(document, "paper", [record]);
    expect(projected).toEqual([
      {
        ids,
        page: 1,
        text: "我的解释",
        author: "同名显示作者",
        editable: true,
        kind: "highlight",
        annotationId: record.id,
        quote: record.quote,
      },
    ]);
  });

  it("keeps foreign marks readable and readonly even with the same NM and displayed author as an owned mark", async () => {
    const { document, add } = await fixture();
    const own = add("Text", "本机评论", "jy-shared-name", "local");
    const foreign = add(
      "Text",
      "外来评论不能被合并或编辑",
      "jy-shared-name",
      "someone-else",
    );
    const foreignSegment = add(
      "Highlight",
      "外来评论不能被合并或编辑",
      "jy-shared-name",
      "someone-else",
    );
    const underline = add(
      "Underline",
      "另一作者的下划线说明",
      "external-underline",
    );
    const projected = projectResearchComments(document, "paper", [record]);
    expect(projected.find((item) => item.ids.includes(own))?.editable).toBe(
      true,
    );
    expect(projected.find((item) => item.ids.includes(foreign))).toMatchObject({
      ids: [foreign, foreignSegment],
      text: "外来评论不能被合并或编辑",
      editable: false,
    });
    expect(
      projected.find((item) => item.ids.includes(underline)),
    ).toMatchObject({
      text: "另一作者的下划线说明",
      editable: false,
      kind: "other",
    });
    expect(projected).toHaveLength(3);
  });

  it("does not borrow a quote from another paper and allows signed documents to be read without rewriting them", async () => {
    const { document, add } = await fixture();
    add("Text", "原文摘录", "jy-shared-name", "local");
    document.catalog.set(
      PDFName.of("TestSignature"),
      document.context.obj({ Type: "Sig", ByteRange: [0, 1, 2, 3] }),
    );
    const bytes = await document.save();
    const loaded = await PDFDocument.load(bytes, { updateMetadata: false });
    const projected = projectResearchComments(loaded, "paper", [
      { ...record, paperId: "other-paper" },
    ]);
    expect(projected[0]).toMatchObject({ text: "原文摘录", editable: true });
    expect(projected[0].annotationId).toBeUndefined();
    expect(projected[0].quote).toBeUndefined();
    expect(loaded.catalog.has(PDFName.of("TestSignature"))).toBe(true);
    expect(await loaded.save()).toBeInstanceOf(Uint8Array);
  });

  it("leaves a quick highlight without a thought as a quote rather than displaying it as the user's comment", async () => {
    const { document, add } = await fixture();
    add("Text", record.quote, "jy-shared-name", "local");
    add("Highlight", record.quote, "jy-shared-name");
    expect(
      projectResearchComments(document, "paper", [
        { ...record, comment: "" },
      ])[0],
    ).toMatchObject({ text: "", quote: record.quote, kind: "highlight" });
  });
});

