    contentRevision: `${id}-revision`,
    pdfEtag: '"test"',
    version: 1,
    lastReadPage: 1,
    createdAt: now,
    updatedAt: now,
    library: { topic: "research", slug: id },
  };
}
function note(paperId: string, id: string, confirmed = true): ResearchNote {
  return {
    id,
    paperId,
    title: id,
    body: `${id}-body`,
    content: `${id}-body`,
    kind: "reading",
    status: confirmed ? "confirmed" : "draft",
    confirmed,
    sources: [{ paperId, page: 1 }],
    version: 1,
    createdAt: now,
    updatedAt: now,
  };
}
function input(
  mode: StartResearchRunInput["mode"] = "ask",
  question = "Explain the harness feedback loop.",
): StartResearchRunInput {
  const current = paper("harness-paper", "Harness²: AI Systems");
  const other = paper("education-example", "合成教育样例");
  const knowledge: KnowledgeEntry = {
    id: "formative",
    title: "形成性评价",
    aliases: ["feedback"],
    body: "EDUCATION-SEED-MARKER",
    definition: "EDUCATION-SEED-MARKER",
    category: "教育",
    sources: [],
    source: "",
    origin: "seed",
    version: 1,
    createdAt: now,
    updatedAt: now,
  };
  return {
    paperId: current.id,
    answerStyle: "grounded",
    mode,
    question,
    context: {
      paper: current,
      pages: [
        {
          page: 1,
          text: "Harness feedback improves the agent execution loop.",
        },
      ],
      notes: [
        note(current.id, "my-confirmed-note"),
        note(current.id, "private-draft", false),
        note(other.id, "foreign-note"),
      ],
      knowledge: [knowledge],
      related: [
        {
          paper: other,
          pages: [{ page: 2, text: "SYNTHETIC-UNRELATED-MARKER" }],
          notes: [
            note(other.id, "related-confirmed"),
            note(other.id, "related-draft", false),
          ],
        },
      ],
    },
  };
}

describe("explicit research source scope", () => {
  it("honors explicit source checkboxes over automatic keyword broadening", () => {
    const single = {
      ...input("ask", "Compare this with other papers"),
      sourcePaperIds: ["harness-paper"],
    };
    expect(buildResearchContext(single).related_papers).toEqual([]);
    const chosen = {
      ...input("ask", "请整理研究差异"),
      sourcePaperIds: ["harness-paper", "education-example"],
    };
    expect(
      buildResearchContext(chosen).related_papers.map((p) => p.document_id),
    ).toEqual(["education-example"]);
    expect(researchContextScope(single)).not.toBe(researchContextScope(chosen));
    expect(
      buildResearchContext({
        ...chosen,
        sourcePaperIds: ["harness-paper", "a-different-paper"],
      }).related_papers,
    ).toEqual([]);
    expect(
      buildResearchContext({
        ...chosen,
        question: "[学习笔记:cornell] 生成笔记",
      }).related_papers,
    ).toEqual([]);
  });
  it.each(["card", "analyze", "graph"] as const)(
    "grounds %s in the current paper and its confirmed notes",
    (mode) => {
      const context = buildResearchContext(input(mode));
      expect(context.paper_pages).toContain("Harness feedback");
      expect(context.confirmed_notes.map((n) => n.title)).toEqual([
        "my-confirmed-note",
      ]);
      expect(context.related_papers).toEqual([]);
      expect(context.education_library).toEqual([]);
      expect(JSON.stringify(context)).not.toMatch(
        /EDUCATION-SEED-MARKER|SYNTHETIC-UNRELATED-MARKER|private-draft|foreign-note/,
      );
    },
  );

  it("does not confuse generic AI feedback, methods comparison or a technical knowledge base with education context", () => {
    for (const question of [
      "Explain the harness feedback loop.",
      "Compare the two evaluation methods in this paper.",
      "请比较本文中的两种方法。",
      "What does the knowledge base component do in this model?",
    ]) {
      const context = buildResearchContext(input("ask", question));
      expect(context.related_papers).toEqual([]);
      expect(context.education_library).toEqual([]);
    }
  });

  it("preserves explicitly requested cross-paper answers with links and only confirmed related notes", () => {
    for (const question of [
      "请对比本文与其他论文。",
      "请比较这两篇论文。",
      "Compare this paper with other sources.",
      "Compare the two papers.",
    ]) {
      const context = buildResearchContext(input("ask", question));
      expect(context.related_papers).toHaveLength(1);
      expect(context.related_papers[0].pages[0].citation_link).toBe(
        "/workspace?paperId=education-example&page=2",
      );
      expect(context.related_papers[0].notes.map((n) => n.title)).toEqual([
        "related-confirmed",
      ]);
      expect(context.education_library).toEqual([]);
    }
  });

  it("keeps study-note generation and explicit single-paper restrictions inside the current paper", () => {
    for (const question of [
      "[学习笔记:cornell] 生成康奈尔笔记，附上可与其他论文比较的自测题。",
      "不要结合其他论文，只分析本文。",
      "Do not compare other papers; explain this paper.",
    ]) {
      const context = buildResearchContext(input("ask", question));
      expect(context.related_papers).toEqual([]);
      expect(context.education_library).toEqual([]);
      expect(context.confirmed_notes).toHaveLength(1);
    }
  });

  it("uses the concept library only for concept mode or an explicit library or education request", () => {
    for (const request of [
      input("concept"),
      input("ask", "请查询知识库解释教育学概念。"),
      input("ask", "Use the knowledge base to explain this term."),
    ])
      expect(buildResearchContext(request).education_library[0].title).toBe(
        "形成性评价",
      );
    expect(
      buildResearchContext(input("ask", "不要使用教育知识库，只解释本文。"))
        .education_library,
    ).toEqual([]);
  });

  it("does not reuse historical or broader-scope conversations and keeps study generation independent", () => {
    const request = input();
    const scope = researchContextScope(request);
    const previous: ResearchRun = {
      id: "prior",
      paperId: request.paperId,
      mode: "ask",
      status: "completed",
      question: "先前问题",
      answer: "先前回答",
      createdAt: now,
      updatedAt: now,
      sessionId: "session-old",
      contentRevision: request.context.paper.contentRevision,
    };
    expect(canReuseResearchSession(previous, request, scope)).toBe(false);
    const scoped = { ...previous, contextScope: scope };
    expect(canReuseResearchSession(scoped, request, scope)).toBe(true);
    const cross = input("ask", "请与其他论文比较。");
    expect(
      canReuseResearchSession(scoped, cross, researchContextScope(cross)),
    ).toBe(false);
    const study = input("ask", "[学习笔记:feynman] 解释本文");
    expect(
      canReuseResearchSession(
        { ...scoped, contextScope: researchContextScope(study) },
        study,
        researchContextScope(study),
      ),
    ).toBe(false);
    expect(previous).not.toHaveProperty("contextScope");
  });

  it("separates selected passages by evidence while ignoring PDF display and annotation changes", () => {
    const request = input();
    const selection = {
      page: 1,
      text: "Harness feedback improves the agent execution loop.",
      quote: "Harness feedback improves the agent execution loop.",
      contentRevision: request.context.paper.contentRevision,
      rects: [[40, 650, 240, 670]],
      pdfEtag: '"before-annotation"',
    };
    const selected = { ...request, selection };
    const scope = researchContextScope(selected);
    expect(researchContextScope(request)).not.toBe(scope);
    expect(
      researchContextScope({
        ...selected,
        question: "What follows from this same evidence?",
        selection: {
          ...selection,
          rects: [[41, 651, 241, 671]],
          quads: [[41, 671, 241, 671, 41, 651, 241, 651]],
          pdfEtag: '"after-annotation"',
        },
      }),
    ).toBe(scope);
    for (const change of [
      { page: 2 },
      { text: "A different selected passage." },
      { quote: "A different source quotation." },
      { contentRevision: "replaced-paper-text" },
    ]) {
      expect(
        researchContextScope({
          ...selected,
          selection: { ...selection, ...change },
        }),
      ).not.toBe(scope);
    }
  });

  it("reuses a normal selected-passage conversation only within the new matching scope", () => {
    const request = input();
    request.selection = {
      page: 1,
      text: "Harness feedback improves the agent execution loop.",
    };
    const scope = researchContextScope(request);
    const previous: ResearchRun = {
      id: "selected-prior",
      paperId: request.paperId,
      mode: "ask",
      status: "completed",
      question: "先前问题",
      answer: "先前回答",
      createdAt: now,
      updatedAt: now,
      sessionId: "selected-session",
      contentRevision: request.context.paper.contentRevision,
      contextScope: scope,
    };
    expect(canReuseResearchSession(previous, request, scope)).toBe(true);
    const other = { ...request, selection: { ...request.selection, page: 2 } };
    expect(
      canReuseResearchSession(previous, other, researchContextScope(other)),
    ).toBe(false);
    const oldScope = JSON.stringify({
      ...JSON.parse(scope),
      policy: "explicit-source-scope-v4",
    });
    expect(
      canReuseResearchSession(
        { ...previous, contextScope: oldScope },
        request,
        scope,
      ),
    ).toBe(false);
    const learning = {
      ...request,
      learning: {
        task: "explain" as const,
        source: { kind: "selection" as const },
      },
    };
    const learningScope = researchContextScope(learning);
    expect(
      canReuseResearchSession(
        { ...previous, contextScope: learningScope },
        learning,
        learningScope,
      ),
    ).toBe(false);
  });
});

import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { randomUUID } from "node:crypto";
import { createElement } from "react";
import { renderToStaticMarkup } from "react-dom/server";
import { PDFDocument } from "pdf-lib";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import {
  COVER_RENDER_TIMEOUT_MS,
  researchCoverResponse,
} from "@/lib/research/cover";
import { handleResearchRequest } from "@/lib/research/api";
import {
  digest,
  getResearchDataDir,
  importPaper,
  paperPdfPath,
} from "@/lib/research/store";
import { closeIndex } from "@/lib/library/index-db";
import { PaperCover } from "@/components/research/library/PaperCover";
import type { ResearchPaper } from "@/lib/research/types";

const render = vi.hoisted(() => vi.fn());
vi.mock("node:child_process", async (original) => ({
  ...(await original<typeof import("node:child_process")>()),
  execFile: render,
}));

const png = Buffer.from(
  "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+jRZkAAAAASUVORK5CYII=",
  "base64",
);
type Finish = (error: Error | null) => void;
type RenderOptions = { timeout: number; killSignal: string; maxBuffer: number };
let root: string;

beforeEach(() => {
  const temporaryRoot = process.env.RESEARCH_TEST_TMP || os.tmpdir();
  fs.mkdirSync(temporaryRoot, { recursive: true });
  root = fs.mkdtempSync(path.join(temporaryRoot, "research-cover-"));
  vi.stubEnv("PAPERNOOK_DATA_DIR", root);
  vi.stubEnv("RESEARCH_DATA_DIR", path.join(root, "research"));
  vi.stubEnv("NODE_ENV", "test");
  render.mockReset();
  render.mockImplementation(
    (
      _command: string,
      args: string[],
      _options: RenderOptions,
      finish: Finish,
    ) => {
      fs.writeFileSync(`${args.at(-1)}.png`, png);
      queueMicrotask(() => finish(null));
    },
  );
});
afterEach(() => {
  closeIndex();
  vi.unstubAllEnvs();
  fs.rmSync(root, { recursive: true, force: true });
});

async function fixture(): Promise<ResearchPaper> {
  const pdf = await PDFDocument.create();
  pdf.setTitle(randomUUID());
  pdf.addPage([600, 800]);
  const bytes = await pdf.save();
  const pages = [
    { page: 1, text: "A real paper title", width: 600, height: 800 },
  ];
  return importPaper({
    bytes,
    filename: "paper.pdf",
    pages,
    contentRevision: digest(pages),
  });
}
function request(paper: ResearchPaper, headers?: HeadersInit) {
  return new Request(
    `http://127.0.0.1:3000/api/research/papers/${paper.id}/cover?v=${encodeURIComponent(paper.pdfEtag)}`,
    { headers },
  );
}
function cacheFiles(paper: ResearchPaper): string[] {
  const directory = path.join(
    getResearchDataDir(),
    "cache",
    "covers",
    "first-page-v1",
    paper.id,
  );
  return fs.existsSync(directory) ? fs.readdirSync(directory) : [];
}

describe("private local PDF first-page covers", () => {
  it("deduplicates simultaneous requests, caches a bounded complete first page and preserves the PDF", async () => {
    const paper = await fixture();
    const original = fs.readFileSync(paperPdfPath(paper));
    const responses = await Promise.all(
      Array.from({ length: 3 }, () =>
        researchCoverResponse(request(paper), paper.id),
      ),
    );
    expect(render).toHaveBeenCalledTimes(1);
    expect(responses.map((response) => response.status)).toEqual([
      200, 200, 200,
    ]);
    expect(Buffer.from(await responses[0].arrayBuffer())).toEqual(png);
    expect(responses[0].headers.get("cache-control")).toBe(
      "private, max-age=86400, immutable",
    );
    expect(responses[0].headers.get("content-type")).toBe("image/png");
    expect(responses[0].headers.get("x-content-type-options")).toBe("nosniff");
    const [command, args, options] = render.mock.calls[0] as [
      string,
      string[],
      RenderOptions,
    ];
    expect(command).toBe("pdftoppm");
    expect(args.slice(0, 8)).toEqual([
      "-f",
      "1",
      "-l",
      "1",
      "-singlefile",
      "-scale-to",
      "900",
      "-png",
    ]);
    expect(args[8]).not.toBe(paperPdfPath(paper));
    expect(args[8]).toContain(".render-");
    expect(options).toMatchObject({
      timeout: COVER_RENDER_TIMEOUT_MS,
      killSignal: "SIGKILL",
      maxBuffer: 64 * 1024,
    });
    expect(fs.readFileSync(paperPdfPath(paper))).toEqual(original);
    expect(cacheFiles(paper)).toHaveLength(1);
    expect(cacheFiles(paper)[0]).toMatch(/^[a-f0-9]{64}\.png$/);
    const cached = await researchCoverResponse(
      request(paper, { "if-none-match": responses[0].headers.get("etag")! }),
      paper.id,
    );
    expect(cached.status).toBe(304);
    expect(await cached.text()).toBe("");
    const head = await researchCoverResponse(
      new Request(request(paper).url, { method: "HEAD" }),
      paper.id,
    );
    expect(await head.text()).toBe("");
    expect(head.headers.get("content-length")).toBe(String(png.length));
    expect(render).toHaveBeenCalledTimes(1);
  });

  it("invalidates the cache after actual PDF changes even when the workspace ETag is stale", async () => {
    const paper = await fixture();
    const first = await researchCoverResponse(request(paper), paper.id);
    const changed = await PDFDocument.load(
      fs.readFileSync(paperPdfPath(paper)),
    );
    changed.setTitle("A changed first page version");
    fs.writeFileSync(paperPdfPath(paper), await changed.save());
    const second = await researchCoverResponse(request(paper), paper.id);
    expect(second.headers.get("etag")).not.toBe(first.headers.get("etag"));
    expect(second.headers.get("cache-control")).toBe("private, no-cache");
    expect(render).toHaveBeenCalledTimes(2);
    expect(cacheFiles(paper)).toHaveLength(2);
  });

  it("does not publish a cover if an external writer changes the source during rendering", async () => {
    const paper = await fixture();
    render.mockImplementation(
      (
        _command: string,
        args: string[],
        _options: RenderOptions,
        finish: Finish,
      ) => {
        fs.appendFileSync(
          paperPdfPath(paper),
          "\n% changed during thumbnail rendering",
        );
        fs.writeFileSync(`${args.at(-1)}.png`, png);
        finish(null);
      },
    );
    await expect(
      researchCoverResponse(request(paper), paper.id),
    ).rejects.toMatchObject({ status: 409 });
    expect(cacheFiles(paper)).toEqual([]);
  });

  it("returns a safe failure and cleans temporary files when Poppler fails or emits invalid images", async () => {
    const paper = await fixture();
    render.mockImplementationOnce(
      (
        _command: string,
        _args: string[],
        _options: RenderOptions,
        finish: Finish,
      ) => finish(new Error("private process details must stay private")),
    );
    const failed = await handleResearchRequest(request(paper), [
      "papers",
      paper.id,
      "cover",
    ]);
    expect(failed.status).toBe(503);
    expect(await failed.text()).toBe('{"error":"封面暂时不可用"}');
    expect(failed.headers.get("cache-control")).toBe("no-store");
    expect(cacheFiles(paper)).toEqual([]);
    render.mockImplementationOnce(
      (
        _command: string,
        args: string[],
        _options: RenderOptions,
        finish: Finish,
      ) => {
        fs.writeFileSync(`${args.at(-1)}.png`, "not a thumbnail");
        finish(null);
      },
    );
    await expect(
      researchCoverResponse(request(paper), paper.id),
    ).rejects.toMatchObject({ status: 503 });
    expect(cacheFiles(paper)).toEqual([]);
    expect((await researchCoverResponse(request(paper), paper.id)).status).toBe(
      200,
    );
  });

  it("caps simultaneous renderers at two and admits queued work after a renderer finishes", async () => {
    const papers = await Promise.all(Array.from({ length: 4 }, fixture));
    const finishes: (() => void)[] = [];
    render.mockImplementation(
      (
        _command: string,
        args: string[],
        _options: RenderOptions,
        finish: Finish,
      ) => {
        finishes.push(() => {
          fs.writeFileSync(`${args.at(-1)}.png`, png);
          finish(null);
        });
      },
    );
    const pending = papers.map((paper) =>
      researchCoverResponse(request(paper), paper.id),
    );
    await vi.waitFor(() => expect(finishes).toHaveLength(2));
    finishes[0]();
    await vi.waitFor(() => expect(finishes).toHaveLength(3));
    finishes[1]();
    await vi.waitFor(() => expect(finishes).toHaveLength(4));
    finishes[2]();
    finishes[3]();
    expect(
      (await Promise.all(pending)).every((response) => response.status === 200),
    ).toBe(true);
  });

  it("keeps the existing local request guard, rejects unknown IDs and validates PDF size before rendering", async () => {
    const paper = await fixture();
    expect(
      (
        await handleResearchRequest(
          new Request("http://outside.example/api/research/papers/id/cover"),
          ["papers", paper.id, "cover"],
        )
      ).status,
    ).toBe(403);
    expect(
      (
        await handleResearchRequest(request(paper), [
          "papers",
          "not-known",
          "cover",
        ])
      ).status,
    ).toBe(404);
    expect(
      (
        await handleResearchRequest(request(paper), [
          "papers",
          "../../private",
          "cover",
        ])
      ).status,
    ).toBe(400);
    fs.writeFileSync(paperPdfPath(paper), "not a PDF");
    expect(
      (
        await handleResearchRequest(request(paper), [
          "papers",
          paper.id,
          "cover",
        ])
      ).status,
    ).toBe(422);
    const descriptor = fs.openSync(paperPdfPath(paper), "w");
    fs.ftruncateSync(descriptor, 100 * 1024 * 1024 + 1);
    fs.closeSync(descriptor);
    await expect(
      researchCoverResponse(request(paper), paper.id),
    ).rejects.toMatchObject({ status: 422 });
    expect(render).not.toHaveBeenCalled();
  });

  it("renders lazy local image URLs with a visible icon while loading and a version tied to PDF saves", async () => {
    const paper = await fixture();
    const html = renderToStaticMarkup(createElement(PaperCover, { paper }));
    expect(html).toContain(`data-paper-cover="${paper.id}"`);
    expect(html).toContain('data-cover-state="loading"');
    expect(html).toContain('loading="lazy"');
    expect(html).toContain('decoding="async"');
    expect(html).toContain(
      `/api/research/papers/${paper.id}/cover?v=${encodeURIComponent(paper.pdfEtag)}`,
    );
    expect(html).toContain("<svg");
  });

  it("refuses a known paper whose PDF has been redirected outside the paper trees", async () => {
    const paper = await fixture();
    const topicDirectory = path.dirname(paperPdfPath(paper));
    const outside = path.join(root, "outside-papers");
    fs.renameSync(topicDirectory, outside);
    fs.symlinkSync(
      outside,
      topicDirectory,
      process.platform === "win32" ? "junction" : "dir",
    );
    await expect(
      researchCoverResponse(request(paper), paper.id),
    ).rejects.toMatchObject({ status: 422 });
    expect(render).not.toHaveBeenCalled();
  });
});

