describe("free discussion with bounded evidence", () => {
  it("does not carry chosen discussion concepts into paper cards, analysis or graph requests", async () => {
    for (const mode of ["card", "analyze", "graph"] as const) {
      const request = {
        ...input(),
        mode,
        referenceConceptIds: ["srl"],
        question: "请结合知识库整理材料",
      };
      request.context.pages = request.context.pages.map((page) => ({
        ...page,
        text: page.text.slice(0, 300),
      }));
      const run = await startResearchRun(request);
      const packet = boundary.start.mock.calls.at(-1)![0];
      const context = JSON.parse(String(packet.context));
      expect(context.education_library).toEqual([]);
      expect(context.paper_pages).toContain("Learners monitor their progress.");
      expect(packet.answer_style).toBe("grounded");
      expect(run.referenceConceptIds).toEqual([]);
      expect(run.referenceConcepts).toEqual([]);
    }
  });
  it("bounds the tool-only pool and strips private page metadata while keeping a late selected page", () => {
    const documents = Array.from({ length: 4 }, (_, index) => ({
      document_id: index ? "related-" + index : "paper-one",
      title: "test",
      content_revision: "revision",
      pages: Array.from({ length: 2200 }, (_, page) => ({
        page: page + 1,
        text: "x".repeat(1000),
        width: 600,
        height: 800,
      })),
    }));
    const pool = boundedSourceDocuments(documents, "paper-one", 2100);
    expect(pool.truncated).toBe(true);
    expect(pool.documents[0].pages[0].page).toBe(2100);
    expect(
      pool.documents
        .flatMap((doc) => doc.pages)
        .reduce((sum, page) => sum + page.text.length, 0),
    ).toBeLessThanOrEqual(2000000);
    expect(Object.keys(pool.documents[0]).sort()).toEqual([
      "document_id",
      "pages",
      "title",
    ]);
    expect(Object.keys(pool.documents[0].pages[0]).sort()).toEqual([
      "page",
      "text",
    ]);
  });
  it("matches a relevant preset or explicit aliases but does not force generic feedback into education", () => {
    const library = input().context.knowledge;
    expect(
      pickReferenceConcepts(library, "请联系自我调节学习理解这段").map(
        (c) => c.id,
      ),
    ).toEqual(["srl"]);
    expect(
      pickReferenceConcepts(
        library,
        "How does self-regulated learning work?",
      ).map((c) => c.id),
    ).toEqual(["srl"]);
    expect(
      pickReferenceConcepts(library, "Explain the AI harness feedback loop."),
    ).toEqual([]);
    expect(pickReferenceConcepts(library, "SRL", [])).toEqual([]);
    expect(
      pickReferenceConcepts(library, "An unrelated topic", ["fa"]).map(
        (c) => c.id,
      ),
    ).toEqual(["fa"]);
  });
  it("starts from the real selected late page and relevant excerpts, not the first 100000 characters", () => {
    const request = input();
    const context = buildResearchContext(request);
    expect(context.answer_style).toBe("discussion");
    expect(context.provided_pages).toContain(53);
    expect(context.paper_pages).toContain("Learning context before.");
    expect(context.paper_pages).not.toContain("UNRELATED-FIRST-PAGE");
    expect(context.related_papers).toEqual([]);
    expect(context.education_library.map((entry) => entry.id)).toEqual(["srl"]);
    expect(JSON.stringify(context).length).toBeLessThan(12000);
  });
  it("retrieves a relevant later page for a whole-paper question without silently injecting unrelated sources", () => {
    const request = input();
    delete request.selection;
    request.question = "Explain monitoring and reflection";
    const context = buildResearchContext(request);
    expect(context.provided_pages).toContain(54);
    expect(context.paper_pages).not.toContain("UNRELATED-FIRST-PAGE");
    expect(JSON.stringify(context)).not.toContain("UNSELECTED-OTHER-PAPER");
  });
  it("keeps evidence tasks strict even if an old client requests discussion", () => {
    for (const mode of ["graph", "card", "analyze", "concept"] as const)
      expect(effectiveAnswerStyle({ ...input(), mode })).toBe("grounded");
    for (const task of ["notes", "quiz", "understanding"] as const)
      expect(
        effectiveAnswerStyle({
          ...input(),
          learning: { task, source: { kind: "selection" } },
        }),
      ).toBe("grounded");
    expect(effectiveAnswerStyle({ ...input(), answerStyle: "grounded" })).toBe(
      "grounded",
    );
  });
  it("isolates style, concept edits and body revisions while allowing same-passage follow-up after Explain", () => {
    const request = input();
    request.referenceConceptIds = ["srl"];
    const run = previous(request);
    const scope = researchContextScope(request);
    expect(JSON.parse(scope).policy).toBe("explicit-source-scope-v6");
    const explain = {
      ...request,
      learning: {
        task: "explain" as const,
        source: { kind: "selection" as const },
      },
      question: "解释选文",
    };
    expect(researchContextScope(explain)).toBe(scope);
    expect(
      canReuseResearchSession(
        { ...run, learning: explain.learning },
        request,
        scope,
      ),
    ).toBe(true);
    expect(researchContextScope({ ...request, question: "为什么？" })).toBe(
      scope,
    );
    expect(
      researchContextScope({ ...request, answerStyle: "grounded" }),
    ).not.toBe(scope);
    const changed = input();
    changed.referenceConceptIds = ["srl"];
    changed.context.knowledge[0].version++;
    expect(researchContextScope(changed)).not.toBe(scope);
    expect(
      canReuseResearchSession(
        { ...run, contextScope: scope.replace("v6", "v5") },
        request,
        scope,
      ),
    ).toBe(false);
  });
  it("injects compact current evidence into the first model prompt and persists actual style and concepts", async () => {
    const request = input();
    const created = await startResearchRun(request);
    const packet = boundary.start.mock.calls[0][0];
    expect(packet.answer_style).toBe("discussion");
    expect(packet.conversation_question).toBe(request.question);
    expect(packet.prompt).toContain("Learners monitor their progress.");
    expect(packet.prompt).toContain("自我调节学习");
    expect(String(packet.prompt)).not.toContain("只使用本次context");
    expect(String(packet.prompt)).not.toContain("UNRELATED-FIRST-PAGE");
    expect(String(packet.prompt).length).toBeLessThan(15000);
    expect(
      (packet.source_documents as { document_id: string }[]).map(
        (item) => item.document_id,
      ),
    ).toEqual(["paper-one"]);
    expect(await getResearchRun(created.id)).toMatchObject({
      answerStyle: "discussion",
      referenceConceptIds: ["srl"],
      referenceConcepts: [{ id: "srl", title: "自我调节学习", version: 1 }],
      contextSummary: { pages: [53, 54] },
    });
  });
  it("continues a matching discussion and never crosses to source-only mode or a different selection", async () => {
    const request = input();
    request.referenceConceptIds = ["srl"];
    const created = await startResearchRun(request);
    await startResearchRun({ ...request, question: "为什么？" });
    expect(boundary.start.mock.calls[1][0].session_id).toBe(created.sessionId);
    await startResearchRun({ ...request, answerStyle: "grounded" });
    expect(boundary.start.mock.calls[2][0].session_id).toBeUndefined();
    expect(boundary.start.mock.calls[2][0].source_documents).toBeUndefined();
    expect(boundary.start.mock.calls[2][0].prompt).toContain(
      "只使用本次context",
    );
    await startResearchRun({
      ...request,
      selection: { ...request.selection!, page: 54 },
    });
    expect(boundary.start.mock.calls[3][0].session_id).toBeUndefined();
  });
});

import { describe, expect, it } from "vitest";
import {
  filterGraph,
  nodeKindLabel,
  shortNodeLabel,
  type GraphFilters,
} from "../../src/components/research/graph/graph-data";
import type {
  GraphEdge,
  GraphNode,
  ResearchGraph,
} from "../../src/lib/research/types";

function node(id: string, changes: Partial<GraphNode> = {}): GraphNode {
  return { id, label: id, title: id, kind: "concept", ...changes };
}

function edge(
  source: string,
  target: string,
  changes: Partial<GraphEdge> = {},
): GraphEdge {
  return {
    id: `${source}-${target}`,
    source,
    target,
    kind: "related",
    label: "相关",
    status: "confirmed",
    origin: "source",
    evidence: [{ paperId: "paper-one" }],
    rationale: "来自研究记录",
    version: 1,
    createdAt: "2026-11-01T00:00:00Z",
    updatedAt: "2026-11-01T00:00:00Z",
    ...changes,
  };
}

function graph(nodes: GraphNode[], edges: GraphEdge[]): ResearchGraph {
  return { nodes, edges, version: 1 };
}

const defaults: GraphFilters = {
  view: "all",
  paperId: "",
  query: "",
  showCandidates: true,
};
const ids = (nodes: GraphNode[]) => nodes.map((node) => node.id);

describe("research graph filtering", () => {
  it("includes only direct search matches and one-hop neighbors regardless of edge order", () => {
    const nodes = [
      node("a", { label: "Assessment" }),
      node("b"),
      node("c"),
      node("d"),
    ];
    const edges = [edge("a", "b"), edge("b", "c"), edge("d", "a")];
    for (const ordered of [edges, [...edges].reverse()]) {
      const result = filterGraph(graph(nodes, ordered), {
        ...defaults,
        query: "  ASSESSMENT  ",
      });
      expect(ids(result.nodes)).toEqual(["a", "b", "d"]);
      expect(result.matchedIds).toEqual(["a"]);
      expect(result.edges.map((edge) => edge.id).sort()).toEqual([
        "a-b",
        "d-a",
      ]);
    }
  });

  it("matches definitions and returns an empty graph when no node matches", () => {
    const source = graph(
      [node("a", { definition: "Formative feedback" }), node("b")],
      [edge("a", "b")],
    );
    const result = filterGraph(source, { ...defaults, query: " FEEDBACK " });
    expect(ids(result.nodes)).toEqual(["a", "b"]);
    expect(result.matchedIds).toEqual(["a"]);
    expect(filterGraph(source, { ...defaults, query: "missing" })).toEqual({
      nodes: [],
      edges: [],
      matchedIds: [],
    });
  });

  it("scopes paper evidence before searching and retains the selected paper even without links", () => {
    const source = graph(
      [
        node("p1", { kind: "paper", paperId: "paper-one" }),
        node("p2", { kind: "paper", paperId: "paper-two" }),
        node("a", { label: "Target concept" }),
        node("b", { label: "Hidden concept" }),
      ],
      [
        edge("p1", "a"),
        edge("a", "p2", { evidence: [{ paperId: "paper-two" }] }),
        edge("a", "b", { evidence: [{ paperId: "paper-two" }] }),
      ],
    );
    expect(
      ids(filterGraph(source, { ...defaults, paperId: "paper-one" }).nodes),
    ).toEqual(["p1", "a"]);
    const result = filterGraph(source, {
      ...defaults,
      paperId: "paper-one",
      query: "Target",
    });
    expect(ids(result.nodes)).toEqual(["p1", "a"]);
    expect(result.edges.map((edge) => edge.id)).toEqual(["p1-a"]);
    expect(
      filterGraph(source, {
        ...defaults,
        paperId: "paper-one",
        query: "Hidden",
      }).nodes,
    ).toEqual([]);
    expect(
      ids(
        filterGraph(graph(source.nodes, []), {
          ...defaults,
          paperId: "paper-one",
        }).nodes,
      ),
    ).toEqual(["p1"]);
  });

  it("keeps paper-only search inside visible paper-to-paper relationships", () => {
    const source = graph(
      [
        node("p1", { kind: "paper", label: "Target paper" }),
        node("p2", { kind: "paper" }),
        node("p3", { kind: "paper" }),
        node("concept"),
      ],
      [edge("p1", "concept"), edge("concept", "p2"), edge("p1", "p3")],
    );
    const result = filterGraph(source, {
      ...defaults,
      view: "papers",
      query: "Target",
    });
    expect(ids(result.nodes)).toEqual(["p1", "p3"]);
    expect(result.edges.map((edge) => edge.id)).toEqual(["p1-p3"]);
    expect(
      filterGraph(source, {
        ...defaults,
        view: "papers",
        query: "concept",
      }).nodes,
    ).toEqual([]);
  });

  it("never returns rejected edges and cannot expand search through hidden candidates", () => {
    const source = graph(
      [node("a"), node("b"), node("c"), node("d")],
      [
        edge("a", "b"),
        edge("a", "c", { status: "candidate" }),
        edge("a", "d", { status: "rejected" }),
      ],
    );
    const withCandidates = filterGraph(source, { ...defaults, query: "a" });
    expect(ids(withCandidates.nodes)).toEqual(["a", "b", "c"]);
    expect(withCandidates.edges.map((edge) => edge.id)).toEqual(["a-b", "a-c"]);
    const confirmed = filterGraph(source, {
      ...defaults,
      query: "a",
      showCandidates: false,
    });
    expect(ids(confirmed.nodes)).toEqual(["a", "b"]);
    expect(confirmed.edges.map((edge) => edge.id)).toEqual(["a-b"]);
  });

  it("focuses one hop inside the filtered graph and does not revive a hidden focus node", () => {
    const source = graph(
      [node("a"), node("b"), node("c"), node("d")],
      [edge("a", "b"), edge("b", "c"), edge("c", "d")],
    );
    expect(
      ids(filterGraph(source, { ...defaults, focusNodeId: "b" }).nodes),
    ).toEqual(["a", "b", "c"]);
    const focusedSearch = filterGraph(source, {
      ...defaults,
      query: "a",
      focusNodeId: "b",
    });
    expect(ids(focusedSearch.nodes)).toEqual(["a", "b"]);
    expect(focusedSearch.matchedIds).toEqual(["a"]);
    for (const focusNodeId of ["d", "missing"]) {
      expect(
        filterGraph(source, { ...defaults, query: "a", focusNodeId }),
      ).toEqual({ nodes: [], edges: [], matchedIds: [] });
    }
  });

  it("treats blank search as no filter and leaves source records and ordering untouched", () => {
    const source = graph(
      [node("a"), node("b"), node("isolated")],
      [edge("a", "b"), edge("b", "isolated", { status: "rejected" })],
    );
    const before = JSON.stringify(source);
    for (const query of ["", " \t\n "]) {
      const result = filterGraph(source, { ...defaults, query });
      expect(ids(result.nodes)).toEqual(["a", "b", "isolated"]);
      expect(result.edges.map((edge) => edge.id)).toEqual(["a-b"]);
      expect(result.matchedIds).toEqual([]);
    }
    filterGraph(source, { ...defaults, query: "a", focusNodeId: "b" });
    expect(JSON.stringify(source)).toBe(before);
    expect(filterGraph(graph([], []), defaults)).toEqual({
      nodes: [],
      edges: [],
      matchedIds: [],
    });
  });
});

describe("research graph display labels", () => {
  it("uses clear node kinds and preserves short labels", () => {
    expect(nodeKindLabel("paper")).toBe("论文");
    expect(nodeKindLabel("concept")).toBe("概念");
    expect(nodeKindLabel("note")).toBe("笔记");
    expect(shortNodeLabel("形成性评价", "concept")).toBe("形成性评价");
    expect(shortNodeLabel("课堂观察", "note")).toBe("课堂观察");
    expect(shortNodeLabel("", "paper")).toBe("");
  });

  it("adds an ellipsis only beyond the kind's label limit without splitting Unicode characters", () => {
    expect(shortNodeLabel("概".repeat(14), "concept")).toBe("概".repeat(14));
    expect(shortNodeLabel("概".repeat(15), "concept")).toBe(
      "概".repeat(14) + "…",
    );
    expect(shortNodeLabel("文".repeat(20), "paper")).toBe("文".repeat(20));
    expect(shortNodeLabel("文".repeat(21), "paper")).toBe(
      "文".repeat(20) + "…",
    );
    expect(shortNodeLabel("📚".repeat(15), "note")).toBe("📚".repeat(14) + "…");
  });
});

