      filterAndSortPapers(papers, { ...filters, tags: ["教育", "方法"] }).map(
        (value) => value.id,
      ),
    ).toEqual(["first", "third"]);
    expect(
      filterAndSortPapers(papers, { ...filters, tags: ["教育", "不存在"] }),
    ).toEqual([]);
    expect(
      libraryTagOptions(papers).find((tag) => tag.label === "教育")?.count,
    ).toBe(2);
    expect(JSON.stringify(papers)).toBe(before);
  });

  it("combines tags with theme, reading status and case-insensitive metadata search", () => {
    const papers = [
      paper("wanted", {
        title: "课堂研究",
        authors: "Alice Li",
        tags: ["AI", "方法"],
        readStatus: "reading",
      }),
      paper("wrong-topic", {
        title: "课堂研究",
        authors: "Alice Li",
        topic: "课题二",
        tags: ["AI", "方法"],
        readStatus: "reading",
      }),
      paper("wrong-status", {
        title: "课堂研究",
        authors: "Alice Li",
        tags: ["AI", "方法"],
        readStatus: "finished",
      }),
      paper("missing-tag", {
        title: "课堂研究",
        authors: "Alice Li",
        tags: ["AI"],
        readStatus: "reading",
      }),
    ];
    const combined = {
      ...filters,
      topic: "课题一",
      readStatus: "reading" as const,
      query: "  ALICE  ",
      tags: ["ai", "方法"],
    };
    expect(
      filterAndSortPapers(papers, combined).map((value) => value.id),
    ).toEqual(["wanted"]);
    expect(
      filterAndSortPapers(papers, { ...combined, query: "2026" }).map(
        (value) => value.id,
      ),
    ).toEqual(["wanted"]);
    expect(filterAndSortPapers(papers, filters)).toHaveLength(4);
  });

  it("sorts independently by date added, date updated or natural title order", () => {
    const papers = [
      paper("alpha10", {
        title: "Alpha 10",
        createdAt: "2026-10-03T00:00:00Z",
        updatedAt: "2026-10-04T00:00:00Z",
      }),
      paper("alpha2", {
        title: "Alpha 2",
        createdAt: "2026-10-02T00:00:00Z",
        updatedAt: "2026-10-05T00:00:00Z",
      }),
      paper("beta", {
        title: "Beta",
        createdAt: "2026-10-01T00:00:00Z",
        updatedAt: "2026-10-06T00:00:00Z",
      }),
    ];
    expect(
      filterAndSortPapers(papers, filters).map((value) => value.id),
    ).toEqual(["alpha10", "alpha2", "beta"]);
    expect(
      filterAndSortPapers(papers, { ...filters, sort: "updated" }).map(
        (value) => value.id,
      ),
    ).toEqual(["beta", "alpha2", "alpha10"]);
    expect(
      filterAndSortPapers(papers, { ...filters, sort: "title" }).map(
        (value) => value.id,
      ),
    ).toEqual(["alpha2", "alpha10", "beta"]);
  });
});

import { describe, expect, it } from "vitest";
import type { ResearchNote } from "@/lib/research/types";
import {
  editableNote,
  generatedNoteOrigin,
  hasUnsavedNote,
  listLocalNotes,
  LocalNoteConflict,
  localNoteKey,
  noteVersionConflict,
  needsNoteLeaveProtection,
  noteTabSlot,
  readLocalNote,
  removeLocalNote,
  writeLocalNote,
  type DraftStorage,
  type EditableNote,
  type LocalNoteDraft,
} from "@/components/research/learning/note-drafts";

class MemoryStorage implements DraftStorage {
  data = new Map<string, string>();
  get length() {
    return this.data.size;
  }
  key(index: number) {
    return [...this.data.keys()][index] ?? null;
  }
  getItem(key: string) {
    return this.data.get(key) ?? null;
  }
  setItem(key: string, value: string) {
    this.data.set(key, value);
  }
  removeItem(key: string) {
    this.data.delete(key);
  }
}
function model(patch: Partial<EditableNote> = {}): EditableNote {
  return {
    paperId: "paper-a",
    title: "Reading note",
    body: "Original source and my thought",
    kind: "reading",
    sources: [
      {
        paperId: "paper-a",
        page: 2,
        quote: "Original source",
        contentRevision: "text-v1",
      },
    ],
    confirmed: false,
    origin: "manual",
    ...patch,
  };
}
function saved(patch: Partial<ResearchNote> = {}): ResearchNote {
  return {
    id: "note-a",
    version: 3,
    paperId: "paper-a",
    title: "Saved title",
    body: "Saved body",
    content: "Saved body",
    kind: "reading",
    sources: [],
    confirmed: false,
    status: "draft",
    createdAt: "2026-10-31T00:00:00Z",
    updatedAt: "2026-10-31T00:00:00Z",
    ...patch,
  };
}
function draft(value = model(), token = "writer-a"): LocalNoteDraft {
  return {
    schema: 1,
    type: "draft",
    key: localNoteKey(value),
    token,
    model: value,
    updatedAt: "2026-10-31T00:00:00Z",
  };
}

describe("recoverable local note drafts", () => {
  it("allows leaving a locally persisted draft but protects failed storage, conflicts, and in-flight saves", () => {
    expect(needsNoteLeaveProtection(true, "local")).toBe(false);
    expect(needsNoteLeaveProtection(true, "local", true)).toBe(true);
    for (const status of ["memory", "unavailable", "conflict"] as const) {
      expect(needsNoteLeaveProtection(true, status)).toBe(true);
      expect(needsNoteLeaveProtection(false, status)).toBe(false);
    }
    expect(needsNoteLeaveProtection(false, "local")).toBe(false);
    expect(needsNoteLeaveProtection(false, "memory", true)).toBe(true);
  });
  it("keeps a tab's recovery identity across refreshes and isolates separate tab sessions", () => {
    const firstTab = new MemoryStorage();
    const secondTab = new MemoryStorage();
    const firstSlot = noteTabSlot(firstTab);
    expect(noteTabSlot(firstTab)).toBe(firstSlot);
    const secondSlot = noteTabSlot(secondTab);
    expect(secondSlot).not.toBe(firstSlot);
    const note = editableNote(saved());
    expect(localNoteKey({ ...note, slot: firstSlot })).not.toBe(
      localNoteKey({ ...note, slot: secondSlot }),
    );
    const stored = draft({
      ...note,
      slot: firstSlot,
      body: "This tab's unsubmitted edits",
    });
    writeLocalNote(firstTab, stored, null);
    expect(readLocalNote(firstTab, stored.key)).toEqual(stored);
    expect(noteVersionConflict(stored.model, saved({ version: 4 }))).toBe(true);
  });
  it("isolates papers, existing note IDs, and generated materials while keeping repeated opens stable", () => {
    const seed = model();
    const origin = generatedNoteOrigin(seed);
    expect(generatedNoteOrigin({ ...seed })).toBe(origin);
    expect(
      generatedNoteOrigin({ ...seed, body: "A different selected passage" }),
    ).not.toBe(origin);
    expect(
      generatedNoteOrigin({
        ...seed,
        sources: [{ paperId: "paper-a", page: 3 }],
      }),
    ).not.toBe(origin);
    expect(generatedNoteOrigin({ ...seed, runId: "run-a" })).not.toBe(
      generatedNoteOrigin({ ...seed, runId: "run-b" }),
    );
    expect(localNoteKey({ ...seed, origin })).not.toBe(
      localNoteKey({ ...seed, origin, paperId: "paper-b" }),
    );
    expect(localNoteKey(model({ id: "note-a", version: 1 }))).not.toBe(
      localNoteKey(model({ id: "note-b", version: 1 })),
    );
    expect(localNoteKey(model({ id: "note-a", version: 1 }))).toBe(
      localNoteKey(
        model({
          ...seed,
          id: "note-a",
          version: 7,
          origin: "another-surface",
        }),
      ),
    );
  });

  it("restores exact edits and their starting version without rebasing against a newer server note", () => {
    const storage = new MemoryStorage();
    const baseline = editableNote(saved());
    const local = draft({
      ...baseline,
      title: "Local title",
      body: "Unsubmitted local changes",
    });
    writeLocalNote(storage, local, null);
    const recovered = readLocalNote(storage, local.key);
    expect(recovered).toEqual(local);
    if (recovered?.type !== "draft")
      throw new Error("Expected a recoverable draft");
    expect(recovered.model.version).toBe(3);
    expect(
      noteVersionConflict(
        recovered.model,
        saved({ version: 4, body: "Other window" }),
      ),
    ).toBe(true);
    expect(noteVersionConflict(recovered.model, saved())).toBe(false);
    expect(hasUnsavedNote(recovered.model, baseline)).toBe(true);
    expect(hasUnsavedNote(baseline, baseline)).toBe(false);
    expect(hasUnsavedNote(model(), model())).toBe(true);
    expect(
      hasUnsavedNote(
        model({ title: "", body: "" }),
        model({ title: "", body: "" }),
      ),
    ).toBe(false);
    expect(readLocalNote(storage, local.key)).toEqual(local);
  });

  it("refuses a stale local writer and never deletes another window's newer draft", () => {
    const storage = new MemoryStorage();
    const first = draft();
    writeLocalNote(storage, first, null);
    const second = draft(
      { ...first.model, body: "The other window's new text" },
      "writer-b",
    );
    writeLocalNote(storage, second, first.token);
    expect(() =>
      writeLocalNote(
        storage,
        draft({ ...first.model, body: "Old window" }, "writer-c"),
        first.token,
      ),
    ).toThrow(LocalNoteConflict);
    expect(removeLocalNote(storage, first.key, first.token)).toBe(false);
    expect(readLocalNote(storage, first.key)).toEqual(second);
    expect(removeLocalNote(storage, second.key, second.token)).toBe(true);
    expect(readLocalNote(storage, second.key)).toBeNull();
  });

  it("retains the original create request and action ID so a lost response can be retried without another note", () => {
    const storage = new MemoryStorage();
    const initial = model();
    const local = {
      ...draft({ ...initial, body: "Edits made after the first save attempt" }),
      pendingCreate: {
        actionId: "create-one-note",
        model: initial,
        confirmed: false,
      },
    };
    writeLocalNote(storage, local, null);
    const recovered = readLocalNote(storage, local.key);
    expect(recovered?.type).toBe("draft");
    if (recovered?.type !== "draft")
      throw new Error("Missing local request snapshot");
    expect(recovered.pendingCreate?.actionId).toBe("create-one-note");
    expect(recovered.pendingCreate?.model.body).toBe(initial.body);
    expect(recovered.model.body).not.toBe(initial.body);
  });

  it("rejects corrupted or mismatched identities and lists unfinished drafts rather than saved bindings", () => {
    const storage = new MemoryStorage();
    const local = draft();
    writeLocalNote(storage, local, null);
    const bindingKey = localNoteKey(model({ origin: "run-another" }));
    storage.setItem(
      bindingKey,
      JSON.stringify({
        schema: 1,
        type: "binding",
        key: bindingKey,
        paperId: "paper-a",
        noteId: "saved-note",
      }),
    );
    expect(readLocalNote(storage, bindingKey)).toMatchObject({
      type: "binding",
      noteId: "saved-note",
    });
    const wrongKey = localNoteKey(model({ paperId: "paper-b" }));
    storage.setItem(wrongKey, JSON.stringify({ ...local, key: wrongKey }));
    expect(readLocalNote(storage, wrongKey)).toBeNull();
    storage.setItem(local.key + "broken", "{not-json");
    expect(listLocalNotes(storage)).toEqual([local]);
    storage.setItem(
      local.key,
      JSON.stringify({ ...local, model: { ...local.model, id: "saved-note" } }),
    );
    expect(readLocalNote(storage, local.key)).toBeNull();
  });

  it("allows an unassigned manual draft and surfaces blocked or full storage instead of claiming it was saved", () => {
    const storage = new MemoryStorage();
    const local = draft(model({ paperId: "", sources: [] }));
    writeLocalNote(storage, local, null);
    expect(readLocalNote(storage, local.key)).toEqual(local);
    const blocked = {
      ...storage,
      length: 0,
      key: () => null,
      getItem: () => {
        throw new Error("Storage disabled");
      },
      setItem: () => {
        throw new Error("Quota exceeded");
      },
      removeItem: () => {},
    };
    expect(() => readLocalNote(blocked, local.key)).toThrow("Storage disabled");
    expect(() =>
      writeLocalNote({ ...blocked, getItem: () => null }, local, null),
    ).toThrow("Quota exceeded");
    expect(() =>
      writeLocalNote(storage, draft(model({ body: "x".repeat(200001) })), null),
    ).toThrow();
  });
});

import { describe, expect, it } from "vitest";
import type { NoteDraft } from "@/components/research/learning/NoteEditor";
import {
  excerptNoteOrigin,
  generatedNoteOrigin,
  localNoteKey,
  readLocalNote,
  writeLocalNote,
  type DraftStorage,
  type EditableNote,
  type LocalNoteDraft,
} from "@/components/research/learning/note-drafts";

function storage(): DraftStorage {
  const values = new Map<string, string>();
  return {
    get length() {
      return values.size;
    },
    key(index) {
      return [...values.keys()][index] ?? null;
    },
    getItem(key) {
      return values.get(key) ?? null;
    },
    setItem(key, value) {
      values.set(key, value);
    },
    removeItem(key) {
      values.delete(key);
    },
  };
}
function seed(excerpt?: string, runId = "run-one"): EditableNote {
  const draft: NoteDraft = {
    title: "阅读讨论",
    body: excerpt ?? "The complete answer has several paragraphs.",
    runId,
    sources: [{ paperId: "paper-a", page: 2 }],
    ...(excerpt === undefined
      ? {}
      : { origin: excerptNoteOrigin(runId, excerpt) }),
  };
  return {
    ...draft,
    paperId: "paper-a",
    kind: "reading",
    confirmed: false,
    origin: generatedNoteOrigin(draft, draft.origin),
    slot: "tab-one",
  };
}
function bind(store: DraftStorage, model: EditableNote, noteId: string) {
  const key = localNoteKey(model);
  store.setItem(
    key,
    JSON.stringify({
      schema: 1,
      type: "binding",
      key,
      paperId: model.paperId,
      noteId,
    }),
  );
}
describe("independent local identities for answer excerpts", () => {
  it("does not restore a saved complete answer when preparing an excerpt from the same run", () => {
    const store = storage();
    const full = seed();
    bind(store, full, "saved-complete-note");
    const partial = seed("Only the selected paragraph.");
    expect(full.origin).toBe("run-run-one");
    expect(localNoteKey(partial)).not.toBe(localNoteKey(full));
    expect(readLocalNote(store, localNoteKey(partial))).toBeNull();
    const draft: LocalNoteDraft = {
      schema: 1,
      type: "draft",
      key: localNoteKey(partial),
      model: partial,
      token: "excerpt-editor",
      updatedAt: "2026-10-31T10:00:00Z",
    };
    writeLocalNote(store, draft, null);
    const restored = readLocalNote(store, draft.key);
    expect(restored).toMatchObject({
      type: "draft",
      model: { body: "Only the selected paragraph.", runId: "run-one" },
    });
    expect(readLocalNote(store, localNoteKey(full))).toMatchObject({
      type: "binding",
      noteId: "saved-complete-note",
    });
  });
  it("reopens the same saved excerpt reliably while keeping different excerpts and runs separate", () => {
    const store = storage();
    const first = seed("The selected paragraph.");
    bind(store, first, "saved-excerpt-note");
    const reopened = seed("The selected paragraph.");
    expect(readLocalNote(store, localNoteKey(reopened))).toMatchObject({
      type: "binding",
      noteId: "saved-excerpt-note",
    });
    expect(
      readLocalNote(store, localNoteKey(seed("A different paragraph."))),
    ).toBeNull();
    expect(
      readLocalNote(
        store,
        localNoteKey(seed("The selected paragraph.", "run-two")),
      ),
    ).toBeNull();
    expect(seed(undefined, "run-one").origin).toBe("run-run-one");
  });
  it("fits persisted origin limits and keeps maximum-length valid run IDs distinct", () => {
    const runId = "r".repeat(99);
    const first = seed("An excerpt.", runId + "a");
    const second = seed("An excerpt.", runId + "b");
    expect(first.origin.length).toBeLessThanOrEqual(200);
    expect(first.origin).not.toBe(second.origin);
    const store = storage();
    const draft: LocalNoteDraft = {
      schema: 1,
      type: "draft",
      key: localNoteKey(first),
      model: first,
      token: "long-run-editor",
      updatedAt: "2026-10-31T10:00:00Z",
    };
    expect(() => writeLocalNote(store, draft, null)).not.toThrow();
    expect(readLocalNote(store, draft.key)).toMatchObject({
      model: { runId: runId + "a" },
    });
  });
});

