    await trashResearchPaper(paper.id, paper.version);
    expect(
      (await request<{ history: ResearchRun[] }>(["history"])).payload.history,
    ).toEqual([]);
    expect((await request(["runs", "run-lifecycle"])).response.status).toBe(
