  it("matches explicit concept choices while automatic reference mode can restore a passage's existing concepts", () => {
    expect(
      findPassageDiscussion([original], paper, selection, "discussion", [
        "learning",
        "feedback",
      ]),
    ).toBe(original);
    expect(
      findPassageDiscussion([original], paper, selection, "discussion", []),
