describe("local research planner", () => {
  it("persists and deduplicates a task, protects edits and keeps archived records recoverable", async () => {
    const input = plannerCreateSchema.parse({
      title: "完成真实论文精读",
      dueAt: "2026-11-02T17:00:00+08:00",
      actionId: "retry-planner",
    });
    const first = await createPlannerTask(input);
    expect((await createPlannerTask(input)).id).toBe(first.id);
    expect(listPlannerTasks()).toHaveLength(1);
    await expect(
      createPlannerTask({ ...input, title: "另一个操作" }),
    ).rejects.toThrow("用于其他内容");
    const archived = await updatePlannerTask(
      first.id,
      plannerPatchSchema.parse({ status: "archived", version: 1 }),
    );
    await expect(
      updatePlannerTask(
        first.id,
        plannerPatchSchema.parse({ title: "过期覆盖", version: 1 }),
      ),
    ).rejects.toThrow("已被修改");
    const restored = await updatePlannerTask(
      first.id,
      plannerPatchSchema.parse({ status: "todo", version: archived.version }),
    );
    expect(restored.title).toBe(first.title);
    expect(
      JSON.parse(fs.readFileSync(path.join(root, "workspace.json"), "utf8"))
        .plannerTasks[0].status,
    ).toBe("todo");
    await expect(
      createPlannerTask({
        ...input,
        actionId: undefined,
        paperId: "missing-paper",
      }),
    ).rejects.toThrow("未找到论文");
  });
  it("suggests Shanghai dates correctly without silently creating tasks or accepting impossible dates", () => {
    const now = new Date("2026-10-30T17:30:00Z"); // Saturday 01:30 in Shanghai.
    expect(parseDeadlineText("明天下午五点完成精读", now).dueLocal).toBe(
      "2026-11-01T17:00",
    );
    expect(parseDeadlineText("明天下午5点完成精读", now).dueLocal).toBe(
      "2026-11-01T17:00",
    );
    expect(parseDeadlineText("下周五17:00提交笔记", now).dueLocal).toBe(
      "2026-11-06T17:00",
    );
    expect(parseDeadlineText("2026年2月30日完成笔记", now).dueLocal).toBe("");
    expect(parseDeadlineText("明天25:00完成笔记", now).dueLocal).toBe("");
    expect(shanghaiInput("2026-11-01T09:00:00Z")).toBe("2026-11-01T17:00");
    expect(parseDeadlineText("明天下午五点三十分完成精读", now).dueLocal).toBe(
      "2026-11-01T17:30",
    );
    expect(parseDeadlineText("明天18时30分完成精读", now).dueLocal).toBe(
      "2026-11-01T18:30",
    );
    expect(parseDeadlineText("明天上午十二点完成精读", now).dueLocal).toBe(
      "2026-11-01T00:00",
    );
    expect(parseDeadlineText("明天下午五点一刻完成精读", now).dueLocal).toBe(
      "",
    );
    expect(listPlannerTasks()).toEqual([]);
  });
  it("exports valid folded UTF-8 calendar events and rejects cross-site saves", async () => {
    const task = await createPlannerTask(
      plannerCreateSchema.parse({
        title: "论文笔记，方法；证据\nBEGIN:VEVENT " + "中文".repeat(60),
        dueAt: "2026-11-02T17:00:00+08:00",
      }),
    );
    const calendar = plannerCalendar();
    expect(calendar).toContain("DTSTART:20261102T090000Z");
    expect(calendar).toContain("TRIGGER:-PT15M");
    expect(
      calendar.split("\r\n").every((line) => Buffer.byteLength(line) <= 75),
    ).toBe(true);
    const unfolded = calendar.replace(/\r\n /g, "");
    expect(unfolded).toContain("论文笔记，方法；证据");
    expect(unfolded).toContain("\\nBEGIN:VEVENT");
    expect(unfolded.match(/^BEGIN:VEVENT$/gm)).toHaveLength(1);
    await updatePlannerTask(
      task.id,
      plannerPatchSchema.parse({ status: "archived", version: 1 }),
    );
    expect(plannerCalendar()).not.toContain("BEGIN:VEVENT");
    const response = await handlePlannerRequest(
      new Request("http://127.0.0.1:3000/api/research/planner", {
        method: "POST",
        headers: {
          host: "127.0.0.1:3000",
          origin: "https://external.test",
          "content-type": "application/json",
        },
        body: JSON.stringify({
          title: "不应保存",
          dueAt: "2026-11-02T09:00:00Z",
        }),
      }),
    );
    expect(response.status).toBe(403);
    expect(listPlannerTasks()).toHaveLength(1);
  });
});

import { describe, expect, it } from "vitest";
import {
  questionDraftKey,
  questionSignature,
  readQuestionDraft,
  writeQuestionDraft,
  type QuestionInput,
} from "../../src/components/research/qa/question-draft";

function storageBoundary() {
  const values = new Map<string, string>();
  return {
    getItem(key: string) {
      return values.get(key) ?? null;
    },
    setItem(key: string, value: string) {
      values.set(key, value);
    },
    removeItem(key: string) {
      values.delete(key);
    },
  };
}

function input(): QuestionInput {
  return {
    question: "请比较这段证据与另一篇论文的方法。\n保留我的追问草稿。",
    selection: {
      page: 2,
      text: "Selected evidence from the second page.",
      quote: "Selected evidence from the second page.",
      contentRevision: "paper-a-text",
      rects: [[40, 650, 280, 670]],
      pdfEtag: '"original-pdf"',
    },
    sourcePaperIds: ["paper-a", "paper-b"],
  };
}

describe("local question draft persistence and accepted-submission identity", () => {
  it("does not clear a newer draft when its answer style or reference concepts changed during submission", () => {
    const submitted: QuestionInput = {
      ...input(),
      answerStyle: "discussion",
      referenceConceptIds: ["concept-feedback", "concept-learning"],
    };
    const accepted = questionSignature(submitted);
    expect(
      questionSignature({ ...submitted, answerStyle: "grounded" }),
    ).not.toBe(accepted);
    expect(
      questionSignature({
        ...submitted,
        referenceConceptIds: ["concept-feedback"],
      }),
    ).not.toBe(accepted);
    expect(
      questionSignature({ ...submitted, referenceConceptIds: [] }),
    ).not.toBe(accepted);
    expect(
      questionSignature({ ...submitted, referenceConceptIds: undefined }),
    ).not.toBe(accepted);
    expect(
      questionSignature({
        ...submitted,
        referenceConceptIds: ["concept-learning", "concept-feedback"],
      }),
    ).toBe(accepted);
    expect(questionSignature({ ...input(), referenceConceptIds: [] })).not.toBe(
      questionSignature(input()),
    );
  });

  it("restores the chosen response style and explicit concept settings alongside the question", () => {
    const storage = storageBoundary();
    for (const referenceConceptIds of [["concept-feedback"], []]) {
      const draft: QuestionInput = {
        ...input(),
        answerStyle: "grounded",
        referenceConceptIds,
      };
      writeQuestionDraft(storage, "paper-a", "paper-a-text", draft);
      const restored = readQuestionDraft(
        storage.getItem(questionDraftKey("paper-a")),
        "paper-a",
        "paper-a-text",
      );
      expect(restored).toEqual({ input: draft, sourceChanged: false });
      expect(questionSignature(restored!.input)).toBe(questionSignature(draft));
    }
  });

  it("restores the question, submitted selection and chosen sources after a storage round trip", () => {
    const storage = storageBoundary();
    const draft = input();
    writeQuestionDraft(storage, "paper-a", "paper-a-text", draft);
    const raw = storage.getItem(questionDraftKey("paper-a"));
    expect(raw).not.toBeNull();
    const restored = readQuestionDraft(raw, "paper-a", "paper-a-text");
    expect(restored).toEqual({ input: draft, sourceChanged: false });
    expect(questionSignature(restored!.input)).toBe(questionSignature(draft));
  });

  it("retains the question and source choices while dropping an old selection after the source text changes", () => {
    const storage = storageBoundary();
    const draft = input();
    writeQuestionDraft(storage, "paper-a", "paper-a-text", draft);
    const restored = readQuestionDraft(
      storage.getItem(questionDraftKey("paper-a")),
      "paper-a",
      "paper-a-new-text",
    );
    expect(restored).toEqual({
      input: { ...draft, selection: null },
      sourceChanged: true,
    });
    // Also reject an independently stale selection stored under a newer document revision.
    writeQuestionDraft(storage, "paper-a", "paper-a-new-text", draft);
    expect(
      readQuestionDraft(
        storage.getItem(questionDraftKey("paper-a")),
        "paper-a",
        "paper-a-new-text",
      )?.input.selection,
    ).toBeNull();
  });

  it("keeps drafts isolated by paper and refuses a record read under another paper identity", () => {
    const storage = storageBoundary();
    const first = input();
    const second: QuestionInput = {
      question: "第二篇论文的问题",
      selection: null,
      sourcePaperIds: ["paper-b"],
    };
    writeQuestionDraft(storage, "paper-a", "paper-a-text", first);
    writeQuestionDraft(storage, "paper-b", "paper-b-text", second);
    const firstRaw = storage.getItem(questionDraftKey("paper-a"));
    expect(readQuestionDraft(firstRaw, "paper-b", "paper-b-text")).toBeNull();
    expect(
      readQuestionDraft(firstRaw, "paper-a", "paper-a-text")?.input,
    ).toEqual(first);
    expect(
      readQuestionDraft(
        storage.getItem(questionDraftKey("paper-b")),
        "paper-b",
        "paper-b-text",
      )?.input,
    ).toEqual(second);
  });

  it("removes only the current paper's saved draft when the question is cleared or contains only whitespace", () => {
    const storage = storageBoundary();
    writeQuestionDraft(storage, "paper-b", "paper-b-text", {
      question: "保留另一篇的问题",
      selection: null,
      sourcePaperIds: ["paper-b"],
    });
    for (const question of ["", " \n\t "]) {
      writeQuestionDraft(storage, "paper-a", "paper-a-text", input());
      writeQuestionDraft(storage, "paper-a", "paper-a-text", {
        ...input(),
        question,
      });
      expect(storage.getItem(questionDraftKey("paper-a"))).toBeNull();
      expect(
        readQuestionDraft(
          storage.getItem(questionDraftKey("paper-a")),
          "paper-a",
          "paper-a-text",
        ),
      ).toBeNull();
      expect(storage.getItem(questionDraftKey("paper-b"))).not.toBeNull();
    }
  });

  it("matches an accepted submission snapshot but distinguishes newer text, selection and source edits", () => {
    const submitted = input();
    const acceptedSignature = questionSignature(structuredClone(submitted));
    expect(questionSignature(submitted)).toBe(acceptedSignature);
    const changed: QuestionInput[] = [
      { ...submitted, question: submitted.question + "\n提交后新写的问题" },
      { ...submitted, sourcePaperIds: ["paper-a"] },
      { ...submitted, sourcePaperIds: ["paper-a", "paper-c"] },
      { ...submitted, selection: null },
      { ...submitted, selection: { ...submitted.selection!, page: 3 } },
      {
        ...submitted,
        selection: {
          ...submitted.selection!,
          text: "A different selected passage.",
        },
      },
      {
        ...submitted,
        selection: { ...submitted.selection!, quote: "A different quotation." },
      },
      {
        ...submitted,
        selection: {
          ...submitted.selection!,
          contentRevision: "replaced-text",
        },
      },
    ];
    for (const live of changed)
      expect(questionSignature(live)).not.toBe(acceptedSignature);
  });

  it("keeps the semantic submission identity stable when only PDF geometry, ETag or source ordering changes", () => {
    const submitted = input();
    const before = structuredClone(submitted);
    const moved: QuestionInput = {
      ...submitted,
      sourcePaperIds: [...submitted.sourcePaperIds].reverse(),
      selection: {
        ...submitted.selection!,
        rects: [[45, 655, 285, 675]],
        quads: [[45, 675, 285, 675, 45, 655, 285, 655]],
        pdfEtag: '"pdf-after-annotation-save"',
      },
    };
    expect(questionSignature(moved)).toBe(questionSignature(submitted));
    expect(submitted).toEqual(before);
  });
});

import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import {
  PDFArray,
  PDFDict,
  PDFDocument,
  PDFHexString,
  PDFName,
  PDFString,
  StandardFonts,
} from "pdf-lib";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { closeIndex } from "@/lib/library/index-db";
import { handleResearchRequest } from "@/lib/research/api";
import { digest, importPaper, paperPdfPath } from "@/lib/research/store";
import type { ResearchAnnotation, ResearchPaper } from "@/lib/research/types";

const provider = vi.hoisted(() => ({ calls: vi.fn() }));
vi.mock("@/lib/agent/registry", () => ({
  getResearchProvider: () => {
    provider.calls();
    throw new Error("Local annotation must not call a model");
  },
}));

const QUOTE = "Formative assessment informs instruction.";
const RECTS = [
  [40, 698, 180, 714],
  [182, 698, 305, 714],
];
const LIFECYCLE_ACTION = "quick-highlight-lifecycle";
let root: string;

beforeEach(() => {
  root = fs.mkdtempSync(path.join(os.tmpdir(), "research-quick-annotation-"));
  vi.stubEnv("PAPERNOOK_DATA_DIR", root);
  vi.stubEnv("RESEARCH_DATA_DIR", path.join(root, "research"));
  vi.stubEnv("NODE_ENV", "test");
  provider.calls.mockClear();
});
afterEach(() => {
  closeIndex();
  vi.unstubAllEnvs();
  fs.rmSync(root, { recursive: true, force: true });
  expect(provider.calls).not.toHaveBeenCalled();
});

async function fixture(withOtherAuthors = false): Promise<ResearchPaper> {
  const document = await PDFDocument.create();
  const page = document.addPage([600, 800]);
  const font = await document.embedFont(StandardFonts.Helvetica);
  page.drawText(QUOTE, { x: 40, y: 700, size: 12, font });
  if (withOtherAuthors) {
    // Another person's highlight may share an NM; deleting ours must preserve it.
    page.node.addAnnot(
      document.context.register(
        document.context.obj({
          Type: PDFName.of("Annot"),
          Subtype: PDFName.of("Highlight"),
          Rect: [350, 698, 520, 714],
          QuadPoints: [350, 714, 520, 714, 350, 698, 520, 698],
          NM: PDFString.of("jy-" + LIFECYCLE_ACTION),
          Contents: PDFHexString.fromText("另一位研究者的高亮"),
          T: PDFHexString.fromText("另一位研究者"),
          PapernookAuthor: PDFString.of("colleague"),
        }),
      ),
    );
    // Keep a distinct third-party NM at the original tail: inserting a
    // highlight must never rename that pre-existing annotation as its own.
    page.node.addAnnot(
      document.context.register(
        document.context.obj({
          Type: PDFName.of("Annot"),
          Subtype: PDFName.of("Text"),
          Rect: [350, 600, 374, 624],
          NM: PDFString.of("external-reader-comment"),
          Contents: PDFHexString.fromText("第三方阅读器已有的评论"),
          T: PDFHexString.fromText("原论文读者"),
        }),
      ),
    );
  }
  const pages = [{ page: 1, text: QUOTE, width: 600, height: 800 }];
  return importPaper({
    bytes: await document.save(),
    filename: "quick-annotation.pdf",
    pages,
    contentRevision: digest(pages),
  });
}

async function request<T>(
  segments: string[],
  method = "GET",
  body?: unknown,
  headers?: Record<string, string>,
) {
  const response = await handleResearchRequest(
    new Request("http://127.0.0.1:3000/api/research/" + segments.join("/"), {
      method,
      headers: {
        Origin: "http://127.0.0.1:3000",
        "Content-Type": "application/json",
        ...headers,
      },
      body: body === undefined ? undefined : JSON.stringify(body),
    }),
    segments,
  );
  return { status: response.status, value: (await response.json()) as T };
}

type SavedAnnotation = { annotation: ResearchAnnotation; paper: ResearchPaper };
type PaperDetail = { paper: ResearchPaper; annotations: ResearchAnnotation[] };

function quickHighlight(paper: ResearchPaper, actionId: string) {
  return {
    paperId: paper.id,
    page: 1,
    quote: QUOTE,
    comment: "",
    kind: "highlight",
    rects: RECTS,
    contentRevision: paper.contentRevision,
    pdfEtag: paper.pdfEtag,
    actionId,
  };
}

async function pdfMarks(paper: ResearchPaper) {
  const document = await PDFDocument.load(fs.readFileSync(paperPdfPath(paper)));
  const text = (dict: PDFDict, key: string) =>
    dict.lookupMaybe(PDFName.of(key), PDFString, PDFHexString)?.decodeText() ??
    "";
  const numbers = (dict: PDFDict, key: string) =>
    dict
      .lookupMaybe(PDFName.of(key), PDFArray)
      ?.asArray()
      .map((v) => Number(v.toString())) ?? [];
  return (document.getPage(0).node.Annots()?.asArray() ?? []).map((ref) => {
    const dict = document.context.lookup(ref, PDFDict);
    return {
      name: text(dict, "NM"),
      subtype: dict.lookupMaybe(PDFName.of("Subtype"), PDFName)?.asString(),
      contents: text(dict, "Contents"),
      owner: text(dict, "PapernookAuthor"),
      author: text(dict, "T"),
      rect: numbers(dict, "Rect"),
      quads: numbers(dict, "QuadPoints"),
    };
  });
}

describe("quick selection highlighting through the research API", () => {
  it("reuses the same passage across separate clicks without adding another PDF layer or replacing a thought", async () => {
    const paper = await fixture();
    const first = await request<SavedAnnotation>(["annotations"], "POST", {
      ...quickHighlight(paper, "first-click"),
      comment: "Keep this thought.",
    });
    const before = fs.readFileSync(paperPdfPath(paper));
    const input = {
      ...quickHighlight(first.value.paper, "second-click"),
      color: "#8cbce8",
    };
