      chats.appendMessage("nlp", "attention", "ana", own.id, {
        role: "user",
        content: "FUTURE_PRIVATE_TURN" + "c".repeat(2 * 1024 * 1024 - 32),
        at: new Date().toISOString(),
      });
    expect(
      chats.readChat("nlp", "attention", "ana", own.id)?.messages,
    ).toHaveLength(3);
