it("refreshes unchanged collaborations without downloading PDFs or resending published conversations", async () => {
  const f = await fixture();
  const { pdfEtag } = await import("@/lib/library/pdf/file");
  const chats = await import("@/lib/library/chats");
  const { publicationRevision } = await import("@/lib/sharing/threads");
  const { packageConversation } = await import("@/lib/sharing/bundle");
  const original = fs.readFileSync(f.pdf);
  const { artifactVersions } = await import("@/lib/sharing/artifacts/snapshot");
  const artifacts = await artifactVersions("nlp", "attention");
  const connection = {
    version: 1 as const,
    url: link,
    token: f.token,
    participantId: f.participant.id,
    username: "ana",
    generation: f.capability.generation,
    mirrorEtag: pdfEtag(fs.readFileSync(f.pdf)),
    artifacts: { source: artifacts, mirror: artifacts },
  };
  f.storage.saveConnection("nlp", "attention", f.capability, connection, true);
  const chat = chats.createChat(
    "nlp",
    "attention",
    "ana",
    "A shared discussion",
  );
  f.storage.rememberPublication("nlp", "attention", chat.id);
  let revision: string | null = null;
  const transmitted: string[] = [];
  network.fetch.mockImplementation(async (url, options) => {
    expect(new URL(url).origin).toBe("https://papers.example");
    const body = JSON.parse(options.body);
    transmitted.push(body.action);
    if (body.action === "changes")
      return Response.json({
        etag: connection.mirrorEtag,
        artifacts,
        threads: revision
          ? [{ id: chat.id, actorId: f.participant.id, revision }]
          : [],
      });
    if (body.action === "publish") {
      revision = publicationRevision(body, f.participant.id);
      return Response.json({ published: true });
    }
    if (body.action === "artifact-versions") return Response.json(artifacts);
    throw new Error(
      "Unexpected transfer of unchanged PDF or conversation data",
    );
  });
  const { syncConnectedPaper } = await import("@/lib/sharing/worker");
  await syncConnectedPaper("nlp", "attention");
  await syncConnectedPaper("nlp", "attention");
  const { syncConnectedArtifacts } =
    await import("@/lib/sharing/artifacts/gateway");
  await f.storage.withConnection("nlp", "attention", f.capability, (current) =>
    syncConnectedArtifacts("nlp", "attention", f.capability, current),
  );
  expect(transmitted).toEqual([
    "changes",
    "publish",
    "changes",
    "artifact-versions",
  ]);
  const expected = publicationRevision(
    packageConversation(
      chats.readChat("nlp", "attention", "ana", chat.id)!,
      f.papers.companionDir("nlp", "attention"),
    ),
    f.participant.id,
  );
  expect(revision).toBe(expected);
  expect(fs.readFileSync(f.pdf)).toEqual(original);
});

import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { NextRequest } from "next/server";
import { acquireFileLockSync } from "thesidedoor-core/storage";
import {
  createTestProfile,
  testSession,
  testProfileCapability,
} from "../../helpers/access";
import {
  writeCaptureJob,
  readCaptureJob,
  type CaptureJob,
} from "@/lib/capture/jobs";

let directory: string;
const browser = vi.hoisted(() => ({ token: null as string | null }));
vi.mock("next/headers", () => ({
  cookies: async () => ({
    get: (name: string) =>
      name === "papernook_access" && browser.token
        ? { value: browser.token }
        : undefined,
  }),
}));
beforeEach(async () => {
  vi.resetModules();
  directory = fs.mkdtempSync(
    path.join(os.tmpdir(), "papernook-capture-route-"),
  );
  vi.stubEnv("PAPERNOOK_DATA_DIR", directory);
  await createTestProfile("Andres");
  browser.token = await testSession("andres");
});
afterEach(() => {
  vi.unstubAllEnvs();
  vi.unstubAllGlobals();
  fs.rmSync(directory, { recursive: true, force: true });
});

function post(body: unknown) {
  return new NextRequest("http://localhost/api/v1/capture", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
}
function statusGet(slug = "pending-capture") {
  return new NextRequest(
    "http://localhost/api/v1/capture?slug=" + encodeURIComponent(slug),
  );
}
function seedJob(overrides: Partial<CaptureJob> = {}) {
  const job: CaptureJob = {
    slug: "pending-capture",
    state: "analyzing",
    sourceUrl: "https://arxiv.org/pdf/2209.03416",
    addedBy: "andres",
    generation: testProfileCapability("andres").generation,
    startedAt: new Date().toISOString(),
    ...overrides,
  };
  writeCaptureJob(job);
  return job;
}
describe("capture admission and status", () => {
  it("gives bookmarklet users a retryable page when capture is busy", async () => {
    const release = acquireFileLockSync(
      path.join(directory, "locks", "capture-reservation.guard"),
    );
    try {
      const { getProfile } = await import("@/lib/auth/users");
      const route = await import("@/app/add/route");
      const response = await route.POST(
        new NextRequest("http://localhost/add", {
          method: "POST",
          body: new URLSearchParams({
            token: getProfile("andres")!.captureToken,
            url: "https://example.com/paper.pdf",
          }),
        }),
      );
      expect(response.status).toBe(503);
      expect(response.headers.get("retry-after")).toBe("1");
      expect(await response.text()).toContain(
        "Capture is busy. Try again shortly.",
      );
      const { listCaptureJobs } = await import("@/lib/capture/jobs");
      expect(listCaptureJobs()).toEqual([]);
    } finally {
      release();
    }
  }, 15_000);

  it("returns a retryable response when capture reservation remains busy", async () => {
    const release = acquireFileLockSync(
      path.join(directory, "locks", "capture-reservation.guard"),
    );
    try {
      const route = await import("@/app/api/v1/capture/route");
      const response = await route.POST(
        post({ url: "https://example.com/paper.pdf" }),
      );
      expect(response.status).toBe(503);
      expect(response.headers.get("retry-after")).toBe("1");
      expect(await response.json()).toEqual({
        error: "Capture is busy. Try again shortly.",
      });
      const { listCaptureJobs } = await import("@/lib/capture/jobs");
      expect(listCaptureJobs()).toEqual([]);
    } finally {
      release();
    }
  }, 15_000);

  it("requires a persisted session for capture and polling", async () => {
    browser.token = null;
    const route = await import("@/app/api/v1/capture/route");
    expect(
      (await route.POST(post({ url: "https://arxiv.org/pdf/2209.03416" })))
        .status,
    ).toBe(401);
    expect((await route.GET(statusGet())).status).toBe(401);
  });
  it("rejects invalid capture requests and status references", async () => {
    const route = await import("@/app/api/v1/capture/route");
    for (const body of [
      {},
      { url: "nope" },
      { url: "https://arxiv.org/pdf/2209.03416", extra: 1 },
    ])
      expect((await route.POST(post(body))).status).toBe(400);
    expect((await route.GET(statusGet("../etc"))).status).toBe(400);
    expect((await route.GET(statusGet(""))).status).toBe(400);
  });
  it("returns a polling handle and records rejection of a private download address", async () => {
    const route = await import("@/app/api/v1/capture/route");
    const response = await route.POST(
      post({ url: "http://127.0.0.1/private.pdf" }),
    );
    expect(response.status).toBe(202);
    const { slug } = (await response.json()) as { slug: string };
    await vi.waitFor(() => expect(readCaptureJob(slug)?.state).toBe("failed"));
    const status = await route.GET(statusGet(slug));
    expect(await status.json()).toEqual({
      state: "failed",
      error: expect.stringContaining("public internet addresses"),
    });
  });
  it("hides missing, foreign, incomplete and stale-generation jobs without changing them", async () => {
    const route = await import("@/app/api/v1/capture/route");
    expect((await route.GET(statusGet())).status).toBe(404);
    for (const overrides of [
      { addedBy: "another-reader" },
      { generation: undefined },
      { generation: 999 },
    ]) {
      const job = seedJob(overrides);
      expect((await route.GET(statusGet())).status).toBe(404);
      expect(readCaptureJob(job.slug)).toEqual(
        job.generation === undefined
          ? expect.objectContaining({ addedBy: job.addedBy })
          : job,
      );
    }
  });
  it("reports an admitted generation's running and failed jobs", async () => {
    const route = await import("@/app/api/v1/capture/route");
    seedJob();
    expect(await (await route.GET(statusGet())).json()).toEqual({
      state: "analyzing",
    });
    seedJob({ state: "failed", error: "Publisher denied access." });
    expect(await (await route.GET(statusGet())).json()).toEqual({
      state: "failed",
      error: "Publisher denied access.",
    });
  });
  it("retires a completed marker after reporting it once", async () => {
    const route = await import("@/app/api/v1/capture/route");
    const job = seedJob({ state: "done", finalSlug: "finished-paper" });
    expect(await (await route.GET(statusGet())).json()).toEqual({
      state: "done",
      finalSlug: "finished-paper",
    });
    expect(readCaptureJob(job.slug)).toBeNull();
    expect((await route.GET(statusGet())).status).toBe(404);
  });
});

import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { NextRequest } from "next/server";

beforeEach(() => {
  vi.resetModules();
});

afterEach(() => {
  vi.doUnmock("@/lib/auth/session");
  vi.doUnmock("@/lib/capture/download");
});

function mockSession(signedIn: boolean): void {
  vi.doMock("@/lib/auth/session", () => ({
    activeProfile: async () => (signedIn ? { username: "andres" } : null),
  }));
}

class FakeCaptureError extends Error {}

function mockDownload(impl: () => Promise<{ bytes: Buffer }>): void {
  vi.doMock("@/lib/capture/download", () => ({
    CaptureError: FakeCaptureError,
    downloadPdf: impl,
  }));
}

function get(src: string | null): NextRequest {
  const url = new URL("http://localhost/api/v1/viewer/pdf");
  if (src !== null) url.searchParams.set("src", src);
  return new NextRequest(url);
}

describe("viewer PDF proxy", () => {
  it("requires a session", async () => {
    mockSession(false);
    mockDownload(async () => {
      throw new Error("must not fetch");
    });
    const route = await import("@/app/api/v1/viewer/pdf/route");
    expect(
      (await route.GET(get("https://arxiv.org/pdf/1706.03762"))).status,
    ).toBe(401);
  });

  it("rejects missing and non-http src URLs", async () => {
    mockSession(true);
    mockDownload(async () => {
      throw new Error("must not fetch");
    });
    const route = await import("@/app/api/v1/viewer/pdf/route");
    expect((await route.GET(get(null))).status).toBe(400);
    expect((await route.GET(get("not a url"))).status).toBe(400);
    expect((await route.GET(get("file:///etc/passwd"))).status).toBe(400);
  });

  it("maps download failures to 422 with the message", async () => {
    mockSession(true);
    mockDownload(async () => {
      throw new FakeCaptureError("That page has no PDF.");
    });
    const route = await import("@/app/api/v1/viewer/pdf/route");
    const response = await route.GET(get("https://example.com/paper"));
    expect(response.status).toBe(422);
    expect(((await response.json()) as { error: string }).error).toMatch(
      /no PDF/,
    );
  });

  it("streams fetched bytes back as an inline PDF", async () => {
    mockSession(true);
    mockDownload(async () => ({ bytes: Buffer.from("%PDF-1.4 fake") }));
    const route = await import("@/app/api/v1/viewer/pdf/route");
    const response = await route.GET(get("https://example.com/paper.pdf"));
    expect(response.status).toBe(200);
    expect(response.headers.get("content-type")).toBe("application/pdf");
    expect(response.headers.get("cache-control")).toBe("private, max-age=3600");
    expect(response.headers.get("content-length")).toBe(
      String("%PDF-1.4 fake".length),
    );
    expect(Buffer.from(await response.arrayBuffer()).toString()).toContain(
      "%PDF-1.4",
    );
  });

  it("declines to have a huge paper written into the browser cache", async () => {
    mockSession(true);
    const bytes = Buffer.alloc(17 * 1024 * 1024, "a");
    mockDownload(async () => ({ bytes }));
    const route = await import("@/app/api/v1/viewer/pdf/route");
    const response = await route.GET(get("https://example.com/huge.pdf"));
    expect(response.status).toBe(200);
    expect(response.headers.get("cache-control")).toBe("private, no-store");
    expect(response.headers.get("content-length")).toBe(
      String(bytes.byteLength),
    );
  });
});

import { describe, expect, it } from "vitest";
import { optionalWebdavUrl, resolveWebdavUrl } from "@/lib/webdav-url";

describe("WebDAV setup URL", () => {
  it("requires an explicit endpoint for a custom HTTPS domain", () => {
    expect(() => resolveWebdavUrl("https://papernook.example.com")).toThrow(
      /PAPERNOOK_WEBDAV_URL/,
    );
    expect(() => resolveWebdavUrl("https://example.com")).toThrow(
      /PAPERNOOK_WEBDAV_URL/,
    );
  });

  it("uses port 8080 on the same host for local HTTP access", () => {
    expect(resolveWebdavUrl("http://localhost:3000")).toBe(
      "http://localhost:8080",
    );
  });

  it("uses the Tailscale Serve hostname with the raw WebDAV port", () => {
    expect(
      resolveWebdavUrl("https://papernook-server.example-tailnet.ts.net"),
    ).toBe("http://papernook-server.example-tailnet.ts.net:8080");
  });

  it("honors an explicit endpoint for nonstandard proxy layouts", () => {
    expect(
      resolveWebdavUrl(
        "https://papers.example.com",
        "https://storage.example.com/papers/",
      ),
    ).toBe("https://storage.example.com/papers");
  });

  it("rejects an explicit endpoint with a non-WebDAV protocol", () => {
    expect(() =>
      resolveWebdavUrl("https://papers.example.com", "file:///private/papers"),
    ).toThrow(/http or https/);
  });

  it("only advertises optional WebDAV when the full connection is usable", () => {
    expect(
      optionalWebdavUrl(
        "https://papers.example.com",
        undefined,
        "reader",
        "secret",
      ),
    ).toBeNull();
    expect(
      optionalWebdavUrl(
        "https://papers.example.com",
        "https://dav.example.com",
        "reader",
        "secret",
      ),
    ).toBe("https://dav.example.com");
    expect(
      optionalWebdavUrl(
        "https://papers.example.com",
        "https://dav.example.com",
        undefined,
        "secret",
      ),
    ).toBeNull();
  });
});

