    zotero.cancelProfileSync("andres");
    releaseItems?.();
    expect(await syncing).toBeNull();
    const users = await import("@/lib/auth/users");
    await finishErasure();

    expect(users.getProfile("andres")).toBeNull();
    expect(fs.existsSync(path.join(tmpDir, "users", "andres"))).toBe(false);
  });
});

import { execFileSync } from "node:child_process";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { afterAll, beforeAll, beforeEach, describe, expect, it } from "vitest";

const cli = path.resolve(import.meta.dirname, "../../scripts/papernook");

let workspace = "";
let clone = "";
let stubs = "";
let composeLog = "";
let dockerLog = "";
let healthVersion = "";
let runningApp = "";

/**
 * Git exports GIT_DIR, GIT_INDEX_FILE and friends to the hooks it runs, and
 * this suite runs from the pre-push hook. Inheriting them aims every fixture
 * git command at the real repository — `git init` in the fixture then marks
 * the developer's clone bare and `git add -A` stages the whole tree as
 * deleted. Dropping them, and the user's global config with them, keeps the
 * fixture a fixture.
 */
function fixtureEnv(): NodeJS.ProcessEnv {
  const env: NodeJS.ProcessEnv = { ...process.env };
  for (const key of Object.keys(env)) {
    if (key.startsWith("GIT_")) delete env[key];
  }
  env.GIT_CONFIG_GLOBAL = "/dev/null";
  env.GIT_CONFIG_SYSTEM = "/dev/null";
  env.PATH = `${stubs}:${process.env.PATH ?? ""}`;
  return env;
}

function run(args: string[], cwd = clone): string {
  return execFileSync("./scripts/papernook", args, {
    cwd,
    encoding: "utf8",
    env: fixtureEnv(),
    stdio: ["ignore", "pipe", "pipe"],
  });
}

function git(args: string[], cwd: string): string {
  return execFileSync("git", ["-c", "core.hooksPath=/dev/null", ...args], {
    cwd,
    encoding: "utf8",
    env: fixtureEnv(),
  });
}

// A local origin with two releases, cloned at the older one: the shape a
// user who followed the tagged-install instructions ends up with.
beforeAll(() => {
  workspace = fs.mkdtempSync(path.join(os.tmpdir(), "papernook-cli-"));
  const origin = path.join(workspace, "origin");
  fs.mkdirSync(path.join(origin, "scripts"), { recursive: true });
  fs.mkdirSync(path.join(origin, "scripts/runtime"), { recursive: true });
  fs.copyFileSync(cli, path.join(origin, "scripts", "papernook"));
  fs.copyFileSync(
    path.join(path.dirname(cli), "runtime/start-stack.sh"),
    path.join(origin, "scripts/runtime/start-stack.sh"),
  );
  fs.copyFileSync(
    path.join(path.dirname(cli), "backup.sh"),
    path.join(origin, "scripts/backup.sh"),
  );
  fs.chmodSync(path.join(origin, "scripts", "papernook"), 0o755);
  fs.writeFileSync(path.join(origin, "docker-compose.yml"), "services:\n");
  fs.writeFileSync(
    path.join(origin, "package.json"),
    '{\n  "name": "papernook",\n  "version": "1.2.3",\n  "private": true\n}\n',
  );
  git(["init", "-q", "-b", "main"], origin);
  git(["add", "-A"], origin);
  git(
    ["-c", "user.email=t@t", "-c", "user.name=t", "commit", "-qm", "one"],
    origin,
  );
  git(["tag", "v0.1.0"], origin);
  fs.appendFileSync(path.join(origin, "docker-compose.yml"), "  app: {}\n");
  git(["add", "-A"], origin);
  git(
    ["-c", "user.email=t@t", "-c", "user.name=t", "commit", "-qm", "two"],
    origin,
  );
  git(["tag", "v0.9.0"], origin);
  // Development continues past the release, as it does on a real main.
  fs.appendFileSync(path.join(origin, "docker-compose.yml"), "  search: {}\n");
  git(["add", "-A"], origin);
  git(
    ["-c", "user.email=t@t", "-c", "user.name=t", "commit", "-qm", "three"],
    origin,
  );

  clone = path.join(workspace, "clone");
  git(["clone", "-q", "--branch", "v0.1.0", origin, clone], workspace);

  // Stand in for the pieces an update touches on a real host.
  stubs = path.join(workspace, "stubs");
  fs.mkdirSync(stubs);
  // Records the version compose was handed, so the test can prove the
  // running stack is labelled with the commit it was built from.
  composeLog = path.join(workspace, "compose-version");
  // Every compose command, so a test can tell a pull from a build.
  dockerLog = path.join(workspace, "docker-args");
  runningApp = path.join(workspace, "running-app");
  fs.writeFileSync(
    path.join(stubs, "docker"),
    `#!/bin/sh\n` +
      `if [ "$1 $2" = "image inspect" ]; then echo sha256:prepared; exit 0; fi\n` +
      `if [ "$1" = compose ]; then\n` +
      `  printf '%s' "$PAPERNOOK_VERSION" > ${composeLog}\n` +
      `  shift\n` +
      `  if [ "$1" = --project-directory ]; then shift 4; fi\n` +
      `  set -- compose "$@"\n` +
      `fi\n` +
      `echo "$*" >> ${dockerLog}\n` +
      `if [ "$*" = "compose config --format json" ]; then echo '{"name":"fixture","services":{"app":{"image":"papernook-app:local"}}}'; fi\n` +
      `if [ "$*" = "compose ps --status running --quiet app" ] && [ -f ${runningApp} ]; then cat ${runningApp}; fi\nexit 0\n`,
    { mode: 0o755 },
  );
  // The version the "running" stack reports, which the tests below vary to
  // stage a stack that lags its clone.
  healthVersion = path.join(workspace, "health-version");
  fs.writeFileSync(
    path.join(stubs, "curl"),
    `#!/bin/sh\nif [ -f ${healthVersion} ]; then\n` +
      `  printf '{"status":"ok","version":"%s"}\\n' "$(cat ${healthVersion})"\n` +
      `else\n  echo '{"status":"ok"}'\nfi\n`,
    { mode: 0o755 },
  );
});

afterAll(() => {
  fs.rmSync(workspace, { recursive: true, force: true });
});

describe("papernook access", () => {
  beforeEach(() => {
    fs.writeFileSync(dockerLog, "");
    fs.rmSync(runningApp, { force: true });
  });

  it("rejects invalid arguments without starting a container", () => {
    expect(() => run(["access", "recover"])).toThrow();
    expect(fs.readFileSync(dockerLog, "utf8")).toBe("");
  });

  it("runs initialization only while the serving app is stopped", () => {
    run(["access", "initialize"]);
    expect(fs.readFileSync(dockerLog, "utf8")).toContain(
      "compose run --rm --no-deps app node scripts/access.cjs initialize",
    );
    fs.writeFileSync(dockerLog, "");
    fs.writeFileSync(runningApp, "container-id\n");
    expect(() => run(["access", "initialize"])).toThrow(/Stop the app/);
    expect(fs.readFileSync(dockerLog, "utf8")).not.toContain("compose run");
    fs.rmSync(runningApp);
  });

  it("resets the shared password through the running application's terminal", () => {
    fs.writeFileSync(runningApp, "container-id\n");
    run(["access", "reset"]);
    expect(fs.readFileSync(dockerLog, "utf8")).toContain(
      "compose exec --user node app node scripts/access.cjs reset",
    );
    fs.rmSync(runningApp);
  });
});

describe("papernook update", () => {
  it("reports the newer release without touching the clone", () => {
    const output = run(["update", "--check"]);
    expect(output).toContain("v0.1.0 → v0.9.0");
    expect(git(["describe", "--tags"], clone).trim()).toBe("v0.1.0");
  });

  it("refuses to update a clone with uncommitted changes", () => {
    fs.appendFileSync(path.join(clone, "docker-compose.yml"), "# edited\n");
    expect(() => run(["update", "--check"])).toThrow(/uncommitted changes/);
    git(["checkout", "--", "docker-compose.yml"], clone);
  });

  it("moves to the newest release and reports health", () => {
    const output = run(["update", "--no-backup"]);
    expect(git(["describe", "--tags"], clone).trim()).toBe("v0.9.0");
    expect(output).toContain('{"status":"ok"}');
    fs.writeFileSync(
      healthVersion,
      `1.2.3+${git(["rev-parse", "--short", "HEAD"], clone).trim()}`,
    );
    // Re-running a healthy current deployment is a no-op.
    expect(run(["update"])).toContain("Already on the newest release");
  });

  it("labels the rebuilt stack with the release and the commit", () => {
    expect(fs.readFileSync(composeLog, "utf8")).toBe(
      `1.2.3+${git(["rev-parse", "--short", "HEAD"], clone).trim()}`,
    );
  });

  // A clone that follows main sits ahead of the newest tag; a release
  // "update" there would be a downgrade.
  it("refuses to move a branch checkout back to an older release", () => {
    git(["checkout", "-q", "main"], clone);
    git(["merge", "-q", "--ff-only", "origin/main"], clone);
    const head = git(["rev-parse", "HEAD"], clone).trim();
    expect(run(["update"])).toMatch(/refusing to move backwards/);
    expect(git(["rev-parse", "HEAD"], clone).trim()).toBe(head);
    expect(run(["status"])).toContain("already runs newer code");
  });

  // Production hit this: a release tag retagged upstream makes a plain
  // fetch abort with "would clobber existing tag", and every later update
  // with it.
  it("survives a release tag that moved upstream", () => {
    git(["tag", "-f", "v0.1.0", "main"], path.join(workspace, "origin"));
    expect(run(["update", "--main", "--no-backup"])).toContain(
      "Already on the newest main",
    );
  });

  // The update rewrites this very script; bash reads a script lazily, so a
  // body that is not one pre-parsed block resumes at an offset inside new
  // code. Cheap structural check — the failure it prevents is unrepeatable.
  it("parses its whole body before running any of it", () => {
    const source = fs.readFileSync(cli, "utf8");
    expect(source).toMatch(/\n\{\n/);
    expect(source.trimEnd().endsWith("}")).toBe(true);
  });

  it("installs a command that points back at the clone", () => {
    const binDir = path.join(workspace, "bin");
    run(["link", "--bin-dir", binDir]);
    const shim = fs.readFileSync(path.join(binDir, "papernook"), "utf8");
    expect(shim).toContain(clone);
    expect(
      execFileSync(path.join(binDir, "papernook"), ["help"], {
        encoding: "utf8",
      }),
    ).toContain("papernook update");
  });
});

// The production server has 75G for ten projects; a Next.js build there
// costs a build cache and a layer of every intermediate image. With
// PAPERNOOK_IMAGE set an update must pull the published image and never
// build one here.
describe("papernook update (prebuilt image)", () => {
  function stackReports(version: string): void {
    fs.writeFileSync(healthVersion, version);
  }

  function dockerCommands(): string[] {
    const log = fs.existsSync(dockerLog)
      ? fs.readFileSync(dockerLog, "utf8")
      : "";
    return log.split("\n").filter(Boolean);
  }

  beforeEach(() => {
    fs.rmSync(dockerLog, { force: true });
    fs.rmSync(healthVersion, { force: true });
    fs.rmSync(path.join(clone, ".env"), { force: true });
  });

  function currentVersion(): string {
    return `1.2.3+${git(["rev-parse", "--short", "HEAD"], clone).trim()}`;
  }

  it("deploys when the clone is current but the stack lags it", () => {
    stackReports("1.2.3+deadbee");
    const output = run(["update", "--main", "--no-backup"]);
    expect(output).toContain("but the stack runs 1.2.3+deadbee");
    expect(dockerCommands().join(" ")).toContain("up -d");
  });

  it("leaves a stack that already runs the checkout alone", () => {
    stackReports(currentVersion());
    expect(run(["update", "--main"])).toContain("Already on the newest main");
    expect(dockerCommands()).toEqual([]);
  });

  it("pulls the published image instead of building one", () => {
    fs.writeFileSync(
      path.join(clone, ".env"),
      "PAPERNOOK_IMAGE=registry.test/papernook\n",
    );
    stackReports("1.2.3+deadbee");
    const output = run(["update", "--main", "--no-backup"]);
    const commands = dockerCommands();
    // The tag follows the checkout, so image and reported version agree.
    const sha = git(["rev-parse", "--short", "HEAD"], clone).trim();
    expect(output).toContain(`registry.test/papernook:${sha}`);
    expect(commands).toContain("compose pull app");
    expect(commands.join(" ")).toContain("--no-build");
    expect(commands.join(" ")).not.toContain("--build ");
  });

  it("builds locally when no image is configured", () => {
    stackReports("1.2.3+deadbee");
    run(["update", "--main", "--no-backup"]);
    const commands = dockerCommands().join(" ");
    expect(commands).toContain("compose build app");
    expect(commands).not.toContain("compose pull app");
  });
});

import { spawnSync } from "node:child_process";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { afterEach, beforeEach, expect, it } from "vitest";

let directory: string;
beforeEach(() => {
  directory = fs.mkdtempSync(path.join(os.tmpdir(), "papernook-start-"));
  fs.mkdirSync(path.join(directory, "scripts"));
  fs.mkdirSync(path.join(directory, "scripts/runtime"));
  fs.mkdirSync(path.join(directory, "bin"));
  fs.mkdirSync(path.join(directory, "data"));
  fs.writeFileSync(path.join(directory, "data/private.json"), "private-data");
  fs.writeFileSync(path.join(directory, ".env"), "WEBDAV_PASS=test-only\n");
  fs.copyFileSync(
    path.resolve(import.meta.dirname, "../../scripts/runtime/start-stack.sh"),
    path.join(directory, "scripts/runtime/start-stack.sh"),
  );
  fs.copyFileSync(
    path.resolve(import.meta.dirname, "../../scripts/backup.sh"),
    path.join(directory, "scripts/backup.sh"),
  );
  fs.writeFileSync(
    path.join(directory, "bin/docker"),
    `#!/usr/bin/env node
const fs = require('node:fs');
let args = process.argv.slice(2);
if (args[0] === 'image') { console.log('sha256:prepared'); process.exit(0); }
if (args[1] === '--project-directory') {
  const config = JSON.parse(fs.readFileSync(args[4], 'utf8'));
  fs.appendFileSync('configurations', JSON.stringify(config) + '\\n');
  args = ['compose', ...args.slice(5)];
}
const command = args.join(' ');
fs.appendFileSync('commands', command + '\\n');
if (command === 'compose config --format json') {
  console.log(JSON.stringify({name:'fixture', services:{app:{image:'app:mutable', build:'.', environment:{TOKEN:'private-test-value'}}, webdav:{image:'webdav:mutable'}}}));
}
if (command.startsWith('compose ps ')) {
  const service = args.at(-1);
  if (fs.existsSync(service + '.running')) console.log(service);
}
if (command === 'compose stop app webdav') {
  fs.rmSync('app.running', {force:true});
  if (process.env.FAIL_COMMAND === 'partial-stop' && !fs.existsSync('stop-attempted')) {
    fs.writeFileSync('stop-attempted', '1'); process.exit(1);
  }
  fs.rmSync('webdav.running', {force:true});
}
if (command.startsWith('compose up ')) {
  fs.writeFileSync('app.running', '1'); fs.writeFileSync('webdav.running', '1');
}
if (process.env.FAIL_COMMAND && command.includes(process.env.FAIL_COMMAND)) process.exit(1);
`,
    { mode: 0o755 },
  );
});

afterEach(() => fs.rmSync(directory, { recursive: true, force: true }));

function start(failure = "", backup = "no-backup") {
  return spawnSync(
    "bash",
    ["scripts/runtime/start-stack.sh", "build", backup],
    {
      cwd: directory,
      encoding: "utf8",
      env: {
        ...process.env,
        PATH: `${directory}/bin:${process.env.PATH}`,
        FAIL_COMMAND: failure,
      },
    },
  );
}

function commands() {
  return fs.readFileSync(path.join(directory, "commands"), "utf8");
}

it("pins prepared images and retains environment through initialization and healthy startup", () => {
  const result = start();
  expect(result.status, result.stderr).toBe(0);
  expect(commands()).toMatch(
    /build app[\s\S]*stop app webdav[\s\S]*access.cjs initialize[\s\S]*up .*--wait --wait-timeout 90/,
  );
  const configurations = fs
    .readFileSync(path.join(directory, "configurations"), "utf8")
    .trim()
    .split("\n")
    .map((line) => JSON.parse(line));
  const final = configurations.at(-1);
  expect(final.name).toBe("fixture");
  expect(final.services.app.image).toBe("sha256:prepared");
  expect(final.services.webdav.image).toBe("sha256:prepared");
  expect(final.services.app.build).toBeUndefined();
  expect(final.services.app.environment.TOKEN).toBe("private-test-value");
  expect(result.stdout + result.stderr).not.toContain("private-test-value");
});

it.each(["access.cjs initialize", "compose up ", "partial-stop"])(
  "leaves all writers stopped when %s fails",
  (failure) => {
    fs.writeFileSync(path.join(directory, "app.running"), "1");
    fs.writeFileSync(path.join(directory, "webdav.running"), "1");
    const result = start(failure);
    expect(result.status).not.toBe(0);
    expect(result.stderr).toContain("App and WebDAV remain stopped");
    expect(fs.existsSync(path.join(directory, "app.running"))).toBe(false);
    expect(fs.existsSync(path.join(directory, "webdav.running"))).toBe(false);
    if (failure !== "compose up ")
      expect(commands()).not.toContain("compose up ");
  },
);

it("keeps the existing app serving when image preparation fails", () => {
  fs.writeFileSync(path.join(directory, "app.running"), "1");
  expect(start("build app").status).not.toBe(0);
  expect(fs.existsSync(path.join(directory, "app.running"))).toBe(true);
  expect(commands()).not.toContain("stop app webdav");
});

it("rejects invalid access configuration before stopping writers", () => {
  fs.writeFileSync(path.join(directory, "app.running"), "1");
  expect(start("validate-config").status).not.toBe(0);
  expect(commands()).toContain(
    "--entrypoint node app scripts/access.cjs validate-config",
  );
  expect(commands()).not.toContain("stop app webdav");
  expect(fs.existsSync(path.join(directory, "app.running"))).toBe(true);
});

it("captures private data before initialization without restarting writers", () => {
  const result = start("access.cjs initialize", "backup");
  expect(result.status).not.toBe(0);
  const backups = fs.readdirSync(path.join(directory, "backups"));
  expect(backups).toHaveLength(1);
  const archive = spawnSync(
    "tar",
    ["-xOf", path.join(directory, "backups", backups[0]!), "data/private.json"],
    { encoding: "utf8" },
  );
  expect(archive.status, archive.stderr).toBe(0);
  expect(archive.stdout).toBe("private-data");
  expect(commands()).not.toContain("compose start");
  expect(result.stderr).toContain("Pre-initialization backup:");
});

it("does not initialize when backup creation fails", () => {
  fs.writeFileSync(path.join(directory, "backups"), "occupied");
  const result = start("", "backup");
  expect(result.status).not.toBe(0);
  expect(commands()).not.toContain("access.cjs initialize");
  expect(result.stderr).toContain("App and WebDAV remain stopped");
});

function backup(args: string[], failure = "") {
  return spawnSync("bash", ["scripts/backup.sh", ...args], {
    cwd: directory,
    encoding: "utf8",
    env: {
      ...process.env,
      PATH: `${directory}/bin:${process.env.PATH}`,
      FAIL_COMMAND: failure,
    },
  });
}

it("standalone backup restarts only services that were originally running", () => {
  fs.writeFileSync(path.join(directory, "app.running"), "1");
  const result = backup([]);
  expect(result.status, result.stderr).toBe(0);
  expect(commands()).toContain("compose start app\n");
  expect(commands()).not.toContain("compose start app webdav");
});

it("refuses a stopped-mode backup while a writer is still running", () => {
  fs.writeFileSync(path.join(directory, "webdav.running"), "1");
  const result = backup(["--stopped"]);
  expect(result.status).not.toBe(0);
  expect(result.stderr).toContain("webdav is running");
  expect(commands()).not.toContain("compose stop");
  expect(commands()).not.toContain("compose start");
});

it.each([{ args: [] }, { args: ["--stopped"] }])(
  "aborts backup when Docker cannot inspect writers (%j)",
  ({ args }) => {
    const result = backup(args, "compose ps");
    expect(result.status).not.toBe(0);
    expect(commands()).not.toContain("compose stop");
    expect(commands()).not.toContain("compose start");
    expect(fs.readdirSync(path.join(directory, "backups"))).toEqual([]);
  },
);
